pub const async_waiter_reserve_granularity = 16;

/// Robustness limits so adversarial input throws a catchable error instead of
/// crashing the process (stack overflow / runaway loop).
///
/// `max_call_depth` is the *absolute* logical recursion ceiling — a backstop
/// against a runaway self-call, not the real limiter. On a platform with
/// registered stack bounds the effective limit is the native stack itself:
/// `stackGuard` throws as soon as the stack pointer is within `stack_redzone`
/// of the OS limit (`stack_scan.nearLimit`), which adapts to the actual stack
/// size and per-frame cost (much larger under ThreadSanitizer). Raising the
/// ceiling from the old 128 lets ordinary deep recursion *run* — to many
/// hundreds of frames on a normal stack — instead of throwing far below what
/// the native stack can hold. When bounds are unavailable the probe is blind,
/// so a conservative cap (`conservative_call_depth`) still prevents a crash.
pub const max_call_depth: u32 = 16384;
/// Fallback recursion cap used only when the native stack-pointer probe can't
/// protect the thread (`!stack_scan.boundsKnown()`), so an unsupported platform
/// can't overflow. Matches the old hard limit.
const conservative_call_depth: u32 = 128;
/// Default runaway guard for a host-entered interpreter. It is a safety valve
/// for an embedder that called `evaluate` and expects it to return, not a
/// semantic limit — see `Interpreter.step_budget` for why a spawned `Thread`
/// does not get one.
pub const max_steps: u64 = 500_000_000;

/// Below this logical call depth, a chain can't have consumed enough native
/// stack to matter, so the call guard skips the stack-pointer probe and the
/// hot shallow-call path stays a single depth compare (serial-perf gate).
const stack_check_floor: u32 = 32;
/// Native-stack headroom kept free below the thread's real OS stack limit. If a
/// deeper call would leave less than this, the guard throws `RangeError` rather
/// than let the tree-walker's native recursion fault the guard page. It must
/// cover the deepest the throw/unwind path itself reaches. Under ThreadSanitizer
/// frames inflate ~10×, so the redzone does too; a normal build keeps it small
/// so the reserve doesn't needlessly cap recursion depth.
const stack_redzone: usize = if (builtin.sanitize_thread) 1 << 20 else 1 << 18; // 1 MiB TSan / 256 KiB normal
const max_string_bytes: usize = 1 << 26;
const max_typed_array_bytes: usize = 1 << 30;
const max_temporal_instant_ns: i128 = 8_640_000_000_000_000_000_000;

/// Coerce a JS number to a length/index, clamping NaN/negative to 0 and huge
/// values to a cap (so `@intFromFloat` never panics; oversized allocations then
/// fail gracefully as OutOfMemory).
pub fn toLen(n: f64) usize {
    if (std.math.isNan(n) or n <= 0) return 0;
    if (n > 4294967295) return 4294967295;
    return @intFromFloat(@trunc(n));
}

fn toArrayLikeLen(n: f64) usize {
    if (std.math.isNan(n) or n <= 0) return 0;
    if (n > 9007199254740991.0) return 9007199254740991;
    return @intFromFloat(@trunc(n));
}

/// True for any ECMAScript WhiteSpace or LineTerminator code point — the exact
/// set `String.prototype.trim`/`trimStart`/`trimEnd` strip, and the StrWhiteSpace
/// that `parseInt`/`parseFloat`/`Number(str)` skip at the start of their argument.
pub fn isJsTrimCp(cp: u21) bool {
    return switch (cp) {
        0x0009, 0x000A, 0x000B, 0x000C, 0x000D, 0x0020 => true,
        0x00A0, 0x1680 => true,
        0x2000...0x200A => true,
        0x2028, 0x2029, 0x202F, 0x205F, 0x3000, 0xFEFF => true,
        else => false,
    };
}

/// Trim leading and/or trailing ECMAScript WhiteSpace+LineTerminator code points
/// from `s`. UTF-8 aware: a non-ASCII byte at a boundary is decoded so e.g. NBSP
/// (U+00A0) and the ideographic space (U+3000) are stripped, not just ASCII.
/// `jsTrim` for a fixed-width receiver — ASCII or a flat latin1 image. Every
/// trimmed code point above 0xFF is unrepresentable in either, so the set
/// reduces to seven bytes and no decoding is needed (0xA0 simply never occurs in
/// the ASCII case). Fixed width also lets the trailing scan walk backwards from
/// the end instead of forward over the whole string.
fn isJsTrimFlatByte(b: u8) bool {
    return switch (b) {
        0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x20, 0xA0 => true,
        else => false,
    };
}

fn jsTrimFlat(s: []const u8, trim_start_: bool, trim_end_: bool) []const u8 {
    var lo: usize = 0;
    var hi: usize = s.len;
    if (trim_start_) while (lo < hi and isJsTrimFlatByte(s[lo])) : (lo += 1) {};
    if (trim_end_) while (hi > lo and isJsTrimFlatByte(s[hi - 1])) : (hi -= 1) {};
    return s[lo..hi];
}

/// JavaScriptCore's wording for a null/undefined base. JSC appends the source
/// text of the offending expression — `null is not an object (evaluating
/// 'x.p')` — which needs spans the AST does not carry, so only the leading
/// clause is reproduced. Distinguishing null from undefined is the part callers
/// actually branch on, and it is what zig-js previously collapsed.
pub fn notAnObjectMessage(base: Value) []const u8 {
    return if (base.isNull()) "null is not an object" else "undefined is not an object";
}

fn jsTrim(s: []const u8, trim_start_: bool, trim_end_: bool) []const u8 {
    var lo: usize = 0;
    var hi: usize = s.len;
    if (trim_start_) {
        while (lo < hi) {
            const c = s[lo];
            const cp_len: usize = if (c < 0x80) 1 else (std.unicode.utf8ByteSequenceLength(c) catch break);
            if (lo + cp_len > hi) break;
            const cp: u21 = if (cp_len == 1) @as(u21, c) else (std.unicode.utf8Decode(s[lo .. lo + cp_len]) catch break);
            if (!isJsTrimCp(cp)) break;
            lo += cp_len;
        }
    }
    if (trim_end_) {
        var last_end: usize = lo;
        var i: usize = lo;
        while (i < hi) {
            const c = s[i];
            const cp_len: usize = if (c < 0x80) 1 else (std.unicode.utf8ByteSequenceLength(c) catch {
                last_end = hi;
                break;
            });
            if (i + cp_len > hi) {
                last_end = hi;
                break;
            }
            const cp: u21 = if (cp_len == 1) @as(u21, c) else (std.unicode.utf8Decode(s[i .. i + cp_len]) catch {
                last_end = i + cp_len;
                i += cp_len;
                continue;
            });
            i += cp_len;
            if (!isJsTrimCp(cp)) last_end = i;
        }
        hi = last_end;
    }
    return s[lo..hi];
}

fn localeIsTurkic(loc: []const u8) bool {
    return loc.len >= 2 and (std.mem.eql(u8, loc[0..2], "tr") or std.mem.eql(u8, loc[0..2], "az")) and
        (loc.len == 2 or loc[2] == '-');
}

fn localeIsLithuanian(loc: []const u8) bool {
    return loc.len >= 2 and std.mem.eql(u8, loc[0..2], "lt") and (loc.len == 2 or loc[2] == '-');
}

fn markLenAt(s: []const u8, i: usize, mark: []const u8) ?usize {
    if (i + mark.len <= s.len and std.mem.eql(u8, s[i .. i + mark.len], mark)) return mark.len;
    return null;
}

fn combiningAboveLen(s: []const u8, i: usize) ?usize {
    if (markLenAt(s, i, "\xcc\x80")) |n| return n; // U+0300 grave
    if (markLenAt(s, i, "\xcc\x81")) |n| return n; // U+0301 acute
    if (markLenAt(s, i, "\xcc\x83")) |n| return n; // U+0303 tilde
    if (markLenAt(s, i, "\xcc\x87")) |n| return n; // U+0307 dot above
    if (markLenAt(s, i, "\xf0\x9d\x86\x85")) |n| return n; // U+1D185 musical combining doit
    return null;
}

fn combiningBelowLen(s: []const u8, i: usize) ?usize {
    if (markLenAt(s, i, "\xcc\xa3")) |n| return n; // U+0323 dot below
    if (markLenAt(s, i, "\xcc\xa5")) |n| return n; // U+0325 ring below
    if (markLenAt(s, i, "\xcc\xa8")) |n| return n; // U+0328 ogonek
    if (markLenAt(s, i, "\xf0\x90\x87\xbd")) |n| return n; // U+101FD Phaistos combining oblique stroke
    return null;
}

fn combiningLen(s: []const u8, i: usize) ?usize {
    if (combiningAboveLen(s, i)) |n| return n;
    if (combiningBelowLen(s, i)) |n| return n;
    return null;
}

fn turkicUpper(self: *Interpreter, s: []const u8) EvalError![]const u8 {
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    var i: usize = 0;
    while (i < s.len) {
        if (s[i] == 'i') {
            try buf.appendSlice(self.arena, "\xc4\xb0");
            i += 1;
        } else if (i + 1 < s.len and s[i] == 0xc4 and s[i + 1] == 0xb1) {
            try buf.append(self.arena, 'I');
            i += 2;
        } else {
            try buf.append(self.arena, s[i]);
            i += 1;
        }
    }
    return unicode_case.toUpper(self.arena, try buf.toOwnedSlice(self.arena));
}

fn turkicLower(self: *Interpreter, s: []const u8) EvalError![]const u8 {
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    var i: usize = 0;
    while (i < s.len) {
        if (i + 1 < s.len and s[i] == 0xc4 and s[i + 1] == 0xb0) {
            try buf.append(self.arena, 'i');
            i += 2;
        } else if (s[i] == 'I') {
            var j = i + 1;
            var remove_dot = false;
            while (j < s.len) {
                if (markLenAt(s, j, "\xcc\x87") != null) {
                    remove_dot = true;
                    break;
                }
                if (combiningBelowLen(s, j)) |n| {
                    j += n;
                    continue;
                }
                break;
            }
            if (remove_dot) {
                try buf.append(self.arena, 'i');
                i += 1;
                while (i < s.len) {
                    if (i + 1 < s.len and s[i] == 0xcc and s[i + 1] == 0x87) {
                        i += 2;
                        break;
                    }
                    try buf.append(self.arena, s[i]);
                    i += 1;
                }
            } else {
                try buf.appendSlice(self.arena, "\xc4\xb1");
                i += 1;
            }
        } else {
            try buf.append(self.arena, s[i]);
            i += 1;
        }
    }
    return unicode_case.toLower(self.arena, try buf.toOwnedSlice(self.arena));
}

fn lithuanianLower(self: *Interpreter, s: []const u8) EvalError![]const u8 {
    const nfd = try unicode_normalize.normalize(self.arena, s, .nfd);
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    var i: usize = 0;
    while (i < nfd.len) {
        if (i + 2 <= nfd.len) {
            const two = nfd[i .. i + 2];
            if (std.mem.eql(u8, two, "\xc3\x8c")) { // Ì
                try buf.appendSlice(self.arena, "i\xcc\x87\xcc\x80");
                i += 2;
                continue;
            }
            if (std.mem.eql(u8, two, "\xc3\x8d")) { // Í
                try buf.appendSlice(self.arena, "i\xcc\x87\xcc\x81");
                i += 2;
                continue;
            }
            if (std.mem.eql(u8, two, "\xc4\xa8")) { // Ĩ
                try buf.appendSlice(self.arena, "i\xcc\x87\xcc\x83");
                i += 2;
                continue;
            }
        }
        var base_len: usize = if (nfd[i] < 0x80) 1 else 2;
        const base: ?[]const u8 = if (nfd[i] == 'I') blk: {
            if (markLenAt(nfd, i + 1, "\xcc\xa8")) |n| {
                base_len = 1 + n;
                break :blk "\xc4\xaf";
            }
            break :blk "i";
        } else if (nfd[i] == 'J')
            "j"
        else if (i + 2 <= nfd.len and std.mem.eql(u8, nfd[i .. i + 2], "\xc4\xae"))
            "\xc4\xaf"
        else
            null;
        if (base) |lower| {
            var j = i + base_len;
            var has_above = false;
            while (j < nfd.len) {
                if (combiningAboveLen(nfd, j)) |n| {
                    has_above = true;
                    j += n;
                    continue;
                }
                if (combiningBelowLen(nfd, j)) |n| {
                    j += n;
                    continue;
                }
                break;
            }
            try buf.appendSlice(self.arena, lower);
            if (has_above) try buf.appendSlice(self.arena, "\xcc\x87");
            i += base_len;
            continue;
        }
        if (nfd[i] < 0x80) {
            try buf.append(self.arena, if (nfd[i] >= 'A' and nfd[i] <= 'Z') nfd[i] + 32 else nfd[i]);
            i += 1;
        } else {
            const seq_len: usize = std.unicode.utf8ByteSequenceLength(nfd[i]) catch 1;
            const j = @min(i + seq_len, nfd.len);
            try buf.appendSlice(self.arena, try unicode_case.toLower(self.arena, nfd[i..j]));
            i = j;
        }
    }
    return buf.toOwnedSlice(self.arena);
}

fn softDottedLen(s: []const u8, i: usize) ?usize {
    const marks = [_][]const u8{
        "i",            "j",            "\xc4\xaf",     "\xc9\x89",     "\xc9\xa8",     "\xca\x9d",
        "\xca\xb2",     "\xcf\xb3",     "\xd1\x96",     "\xd1\x98",     "\xe1\xb5\xa2", "\xe1\xb6\x96",
        "\xe1\xb6\xa4", "\xe1\xb6\xa8", "\xe1\xb8\xad", "\xe1\xbb\x8b", "\xe2\x81\xb1", "\xe2\x85\x88",
        "\xe2\x85\x89", "\xe2\xb1\xbc",
    };
    for (marks) |m| if (markLenAt(s, i, m)) |n| return n;
    if (i + 4 <= s.len and s[i] == 0xf0 and s[i + 1] == 0x9d) return 4; // mathematical soft-dotted letters in the test262 list
    return null;
}

fn lithuanianUpper(self: *Interpreter, s: []const u8) EvalError![]const u8 {
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    var i: usize = 0;
    while (i < s.len) {
        if (softDottedLen(s, i)) |base_len| {
            try buf.appendSlice(self.arena, try unicode_case.toUpper(self.arena, s[i .. i + base_len]));
            i += base_len;
            while (i < s.len) {
                if (markLenAt(s, i, "\xcc\x87")) |n| {
                    i += n;
                    break;
                }
                if (combiningBelowLen(s, i)) |n| {
                    try buf.appendSlice(self.arena, s[i .. i + n]);
                    i += n;
                    continue;
                }
                break;
            }
            continue;
        }
        const seq_len: usize = if (s[i] < 0x80) 1 else (std.unicode.utf8ByteSequenceLength(s[i]) catch 1);
        const j = @min(i + seq_len, s.len);
        try buf.appendSlice(self.arena, try unicode_case.toUpper(self.arena, s[i..j]));
        i = j;
    }
    return buf.toOwnedSlice(self.arena);
}

/// `error.Throw` is the carrier for *any* JS exception: the thrown value lives
/// in `Interpreter.exception`. `error.OutOfMemory` is the only genuine host
/// failure. (ReferenceError/TypeError are no longer Zig errors — they are real,
/// catchable JS `Error` objects raised via `error.Throw`.)
pub const EvalError = error{ OutOfMemory, Throw, OptShortCircuit };

/// Context-owned source identity attached to a parsed statement. Protocol
/// adapters keep their own script registry; the evaluator only needs a stable
/// id and exact source coordinates at each statement boundary.
pub const DebugStatementLocation = struct {
    script_id: u64,
    location: parser_mod.SourceLocation,
    source_url: []const u8 = "",
    debugger_statement: bool = false,
};

pub const DebugScriptRegistration = struct {
    id: u64,
    start_line: usize,
};

const debug_location_cache_set_count = 16;
const debug_location_cache_way_count = 4;
const debug_location_cache_size = debug_location_cache_set_count * debug_location_cache_way_count;

const DebugLocationCacheEntry = struct {
    node: ?*const Node = null,
    location: ?DebugStatementLocation = null,
};

fn debugLocationCacheSetIndex(node: *const Node) usize {
    // Arena allocation gives adjacent nodes regular low address bits. Fold
    // higher bits before selecting a power-of-two set so one source construct
    // cannot evict every other hot statement merely because of its stride.
    var key = @intFromPtr(node) / @alignOf(Node);
    key ^= key >> 7;
    key ^= key >> 13;
    return key & (debug_location_cache_set_count - 1);
}

pub const DebugRegistrySnapshot = struct {
    location_cache_hits: u64 = 0,
    location_cache_misses: u64 = 0,
    lock_acquires: u64 = 0,
    lock_contentions: u64 = 0,
    lock_spins: u64 = 0,
};

/// Realm-owned, opt-in attribution for statement-location lookup. Interpreters
/// receive a null pointer in ordinary execution, so these atomics are paid only
/// by explicit benchmark/profile contexts.
pub const DebugRegistryStats = struct {
    location_cache_hits: std.atomic.Value(u64) = .init(0),
    location_cache_misses: std.atomic.Value(u64) = .init(0),
    lock_acquires: std.atomic.Value(u64) = .init(0),
    lock_contentions: std.atomic.Value(u64) = .init(0),
    lock_spins: std.atomic.Value(u64) = .init(0),

    pub fn snapshot(self: *const DebugRegistryStats) DebugRegistrySnapshot {
        return .{
            .location_cache_hits = @constCast(self).location_cache_hits.load(.acquire),
            .location_cache_misses = @constCast(self).location_cache_misses.load(.acquire),
            .lock_acquires = @constCast(self).lock_acquires.load(.acquire),
            .lock_contentions = @constCast(self).lock_contentions.load(.acquire),
            .lock_spins = @constCast(self).lock_spins.load(.acquire),
        };
    }
};

/// Reentrant lock for the Context-owned debugger registry. Inspector callbacks
/// may synchronously evaluate more source on the runtime thread, so a plain
/// mutex would deadlock while publishing the nested script. The owner/depth
/// bookkeeping is only touched by the owning thread; the atomic owner permits
/// a same-thread fast path without racing a peer that is releasing the lock.
pub const DebugRegistryLock = struct {
    mutex: std.atomic.Mutex = .unlocked,
    owner: std.atomic.Value(u64) = .init(0),
    depth: usize = 0,

    pub fn lock(self: *DebugRegistryLock) void {
        self.lockProfiled(null);
    }

    pub fn lockProfiled(self: *DebugRegistryLock, stats: ?*DebugRegistryStats) void {
        if (stats) |profile| _ = profile.lock_acquires.fetchAdd(1, .monotonic);
        const current: u64 = @intCast(std.Thread.getCurrentId());
        if (self.owner.load(.acquire) == current) {
            self.depth += 1;
            return;
        }
        var spins: usize = 0;
        while (!self.mutex.tryLock()) : (spins += 1) {
            if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
        }
        if (stats) |profile| if (spins != 0) {
            _ = profile.lock_contentions.fetchAdd(1, .monotonic);
            _ = profile.lock_spins.fetchAdd(@intCast(spins), .monotonic);
        };
        std.debug.assert(self.owner.load(.monotonic) == 0);
        self.depth = 1;
        self.owner.store(current, .release);
    }

    pub fn unlock(self: *DebugRegistryLock) void {
        const current: u64 = @intCast(std.Thread.getCurrentId());
        std.debug.assert(self.owner.load(.acquire) == current);
        std.debug.assert(self.depth > 0);
        self.depth -= 1;
        if (self.depth != 0) return;
        self.owner.store(0, .release);
        self.mutex.unlock();
    }
};

pub const DebugScriptHook = *const fn (
    ctx: *anyopaque,
    source: []const u8,
    url: []const u8,
    start_line: usize,
    statement_locations: []const parser_mod.StatementLocation,
) EvalError!DebugScriptRegistration;

pub const DebugStatementHook = *const fn (
    ctx: *anyopaque,
    interpreter: *Interpreter,
    location: DebugStatementLocation,
) EvalError!void;

/// Embedder-owned statement checkpoint. Unlike the debugger hook this does not
/// itself imply a pause; worker transports use it to marshal queued commands
/// onto the runtime thread before the debugger observes the same statement.
pub const HostStatementHook = *const fn (ctx: *anyopaque, interpreter: *Interpreter) void;

/// Runtime-owned cooperative sampling checkpoint. It runs only after the
/// current source location and always-on stack metadata have been published,
/// so consumers can copy the live stack without racing activation teardown.
/// Unlike the debugger hook it neither creates mutable scope mirrors nor
/// changes pause/exception semantics.
pub const ProfileStatementHook = *const fn (
    ctx: *anyopaque,
    interpreter: *Interpreter,
    location: DebugStatementLocation,
) void;

pub const DebugExceptionHook = *const fn (
    ctx: *anyopaque,
    interpreter: *Interpreter,
    exception: Value,
    location: ?DebugStatementLocation,
    uncaught: bool,
) EvalError!void;

/// Live JavaScript invocation metadata used by the synchronous inspector pause
/// callback. The frame points at the activation's real lexical environment and
/// values rather than a copied snapshot, so scope inspection observes exactly
/// what resumed execution will use. Frames live on the host/VM activation stack
/// and are valid only while the matching call is active.
pub const DebugCallFrame = struct {
    function_name: []const u8,
    environment: *Environment,
    this_value: Value,
    strict: bool,
    location: ?DebugStatementLocation = null,
    caller: ?*DebugCallFrame = null,
    environment_is_vm_activation: bool = false,
};

/// Always-on, allocation-free activation metadata used to snapshot Error
/// stacks. This is deliberately separate from DebugCallFrame: normal VM calls
/// must not allocate inspector Environment mirrors just to retain a trace.
pub const StackTraceCallFrame = struct {
    function_name: []const u8 = "",
    /// Stable runtime identity used by cooperative profilers to aggregate a
    /// function across changing sample positions. Zero is reserved for frames
    /// synthesized without a live function/global owner.
    function_identity: usize = 0,
    code_type: value.ErrorStackFrameCode = .function,
    is_async: bool = false,
    location: ?DebugStatementLocation = null,
    definition_location: ?DebugStatementLocation = null,
    caller: ?*StackTraceCallFrame = null,
};

/// A lexical scope with a parent chain. Function calls push a fresh scope whose
/// `parent` is the function's closure environment, which gives real closures.
/// Variable names are duplicated into `arena` on first definition so they
/// outlive the source buffer of any single evaluation.
/// A `using`/`await using` resource registered for disposal at scope exit:
/// its value and the (pre-resolved) `[Symbol.dispose]`/`[Symbol.asyncDispose]`
/// method. `method == undefined` is the async null/undefined no-op sentinel.
pub const Disposable = struct { value: Value, method: Value, is_async: bool, await_result: bool = false };

/// An identifier Reference captured before later observable evaluation. Raw
/// Environment/Object bases are activation-owned precise roots while live; the
/// `.static` case delegates to the compiler's frame/upvalue fallback, and
/// `.unresolvable` preserves that exact pre-side-effect resolution result.
pub const BindingReference = union(enum) {
    empty,
    static,
    environment: *Environment,
    with_object: *value.Object,
    global_object: *value.Object,
    unresolvable,
};

pub const CapturedBindingValue = struct {
    value: Value,
    /// Object Environment Record WithBaseObject; undefined for declarative,
    /// global-object, static, and unresolvable References.
    with_base: Value = Value.undef(),
};

/// A non-owning view of one ordinary VM activation's frame storage. A direct
/// eval Environment retains this view only when the compiler's immutable scope
/// plan names a live slot. It shares mapped-arguments cells and the frame's
/// escaped-slot lock, so there is exactly one binding value and one no-GIL
/// synchronization ruling rather than an Environment snapshot to reconcile.
pub const ActivationFrameView = struct {
    slots: []Value,
    mapped_arguments: ?*value.Object,
    mapped_parameter_indices: []const u32,
    escaped: *std.atomic.Value(bool),
    slot_lock: *std.atomic.Mutex,

    fn lockSlots(self: *const ActivationFrameView) bool {
        if (!bc.ic_seqlock_enabled.load(.monotonic) or !self.escaped.load(.monotonic)) return false;
        var spins: usize = 0;
        while (!self.slot_lock.tryLock()) : (spins += 1) {
            if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
        }
        return true;
    }

    fn unlockSlots(self: *const ActivationFrameView, held: bool) void {
        if (held) self.slot_lock.unlock();
    }

    fn mappedArgumentIndex(self: *const ActivationFrameView, slot: usize) ?usize {
        const object = self.mapped_arguments orelse return null;
        if (slot >= self.mapped_parameter_indices.len) return null;
        const raw_index = self.mapped_parameter_indices[slot];
        if (raw_index == std.math.maxInt(u32)) return null;
        const index: usize = @intCast(raw_index);
        const cold = object.coldState() orelse return null;
        if (index >= cold.arg_map_values.len) return null;
        return index;
    }

    pub fn read(self: *const ActivationFrameView, slot: usize) Value {
        std.debug.assert(slot < self.slots.len);
        if (self.mappedArgumentIndex(slot)) |index|
            return mappedParameterCellGet(self.mapped_arguments.?, index).?;
        const held = self.lockSlots();
        defer self.unlockSlots(held);
        return self.slots[slot];
    }

    pub fn write(self: *const ActivationFrameView, slot: usize, stored: Value) void {
        std.debug.assert(slot < self.slots.len);
        if (self.mappedArgumentIndex(slot)) |index| {
            std.debug.assert(mappedParameterCellSet(self.mapped_arguments.?, index, stored));
            return;
        }
        const held = self.lockSlots();
        self.slots[slot] = stored;
        self.unlockSlots(held);
    }

    pub fn markEscaped(self: *const ActivationFrameView) void {
        self.escaped.store(true, .release);
    }
};

/// One declarative scope's binding table over a live activation frame. The
/// compiler sorts `bindings` by name, giving lookups bounded logarithmic cost
/// without an attacker-controlled hash table or a per-eval binding copy.
pub const ActivationBindingsView = struct {
    frame: ActivationFrameView,
    bindings: []const bc.DirectEvalBinding,

    pub fn binding(self: *const ActivationBindingsView, name: []const u8) ?bc.DirectEvalBinding {
        var left: usize = 0;
        var right = self.bindings.len;
        while (left < right) {
            const middle = left + (right - left) / 2;
            const candidate = self.bindings[middle];
            switch (std.mem.order(u8, name, candidate.name)) {
                .lt => right = middle,
                .gt => left = middle + 1,
                .eq => return candidate,
            }
        }
        return null;
    }
};

pub const Environment = struct {
    vars: std.StringHashMapUnmanaged(Value) = .{},
    /// Root-realm identity, initialized before publication and immutable to
    /// mutators. The stopped collector rewrites it with the other owned edges;
    /// the writable globalThis binding is not an authority for realm selection.
    realm_global: ?*value.Object = null,
    /// Present only on lazily materialized ordinary-VM direct-eval records. The
    /// immutable name table resolves into the activation's real frame slots;
    /// `vars` remains available for genuinely new sloppy-eval declarations.
    activation: ?ActivationBindingsView = null,
    /// Original runtime Environment Record represented at this position in a
    /// direct-eval activation chain. The forwarding record owns only its new
    /// `parent` edge; every own-binding query/read/write/delete is performed on
    /// this exact target, preserving live binding and object-record identity
    /// without mutating the target's already-published parent link.
    direct_eval_forward_target: ?*Environment = null,
    /// Immutable identity of an activation-backed direct-eval record. Separate
    /// parameter and body records may expose identical names and slots, so cache
    /// validation must not infer record identity from their binding layout.
    direct_eval_scope_kind: ?bc.DirectEvalScopeKind = null,
    /// `using` resources declared in this scope, in declaration order (disposed
    /// in reverse when the scope exits).
    disposables: std.ArrayListUnmanaged(Disposable) = .empty,
    /// Pending error while a VM async-disposal step is suspended at an await.
    dispose_pending: ?Value = null,
    /// Names in `vars` declared `const` — assigning to them is a TypeError.
    consts: std.StringHashMapUnmanaged(void) = .{},
    /// Names in the GLOBAL (root) `vars` that are lexical declarations
    /// (`let`/`const`/`class`). A global lexical shadows a like-named global-object
    /// property (`let Array` reads `undefined`, not %Array%), so its read must NOT
    /// defer to the global object — unlike a global `var`, which shares storage
    /// with its own-property. Inferring lexical-ness from "the global object lacks
    /// an own property" is wrong when the name shadows a pre-existing builtin, so
    /// this set records it explicitly. Only populated on the root environment.
    lexicals: std.StringHashMapUnmanaged(void) = .{},
    /// Names that are *non-strict* immutable bindings — a named function
    /// expression's own name. Reassignment throws in strict code but is a silent
    /// no-op in sloppy code (unlike `const`, which always throws).
    fn_names: std.StringHashMapUnmanaged(void) = .{},
    /// Names that are *deletable* bindings — a sloppy direct eval's top-level
    /// `var`/function declarations create deletable (configurable) bindings in the
    /// surrounding variable environment (EvalDeclarationInstantiation step 16.b),
    /// unlike ordinary declarations. `delete x` removes such a binding and returns
    /// true; a subsequent reference is then unresolvable (ReferenceError).
    deletable: std.StringHashMapUnmanaged(void) = .{},
    /// Module *indirect bindings* (`import { x } from "m"`): `local` resolves
    /// live to `name` in another module's environment, so a mutation of the
    /// exporter's binding is visible here. Assigning to one is a TypeError.
    aliases: std.StringHashMapUnmanaged(Alias) = .{},
    arena: std.mem.Allocator,
    /// Optional allocator for binding-table buckets and duplicated binding
    /// names. Null keeps the legacy arena-owned path; GC contexts set this to
    /// the context backing allocator so an Environment finalizer can reclaim
    /// its side tables before context teardown.
    bindings_allocator: ?std.mem.Allocator = null,
    /// Internal accounting for GC-owned duplicated binding-name bytes.
    gc_name_bytes_live: ?*usize = null,
    parent: ?*Environment = null,
    /// True only when this Environment itself was allocated as a GC cell. The
    /// root realm Environment is embedded in Context and remains false. This is
    /// immutable after initialization, allowing precise Environment edges to
    /// skip broad heap-membership scans during tracing.
    gc_managed: bool = false,
    /// Stable `%Object.prototype%` for this realm. Only the root environment
    /// owns a value; object allocation walks to that root and caches the
    /// intrinsic there so lexical shadowing, global replacement, and temporary
    /// cross-realm entry cannot change ordinary-object prototype identity.
    object_proto_intrinsic: ?*value.Object = null,
    /// Set when a closure captures this environment (or a descendant, via
    /// `markCaptured` walking the parent chain at closure creation). A `for
    /// (let …)` loop uses it to decide whether each iteration needs a fresh
    /// per-iteration binding environment: the per-iteration copy is only
    /// observable through a closure that captured that iteration's binding, so an
    /// uncaptured loop env is reused across iterations instead of reallocated —
    /// removing the per-iteration GC-cell allocation from the common tight loop.
    /// Shared ancestors and direct-eval targets can be captured concurrently;
    /// acquire readers observe release publication of the escaped-frame state.
    captured: std.atomic.Value(bool) = .init(false),
    /// True for a function or the global scope (a *variable* environment); false
    /// for a block `{…}` scope. `var`/function declarations hoist to the nearest
    /// variable environment, while `let`/`const`/`class` bind in the block.
    fn_scope: bool = false,
    /// True while this declarative Environment belongs exclusively to one
    /// running function activation. The concurrent GC marker may inspect it,
    /// but only the owning mutator can read or write its bindings. Reads skip
    /// `binding_lock`; writes use the interpreter/collector entry handshake and
    /// fall back to the lock while concurrent tracing is active. Closure
    /// capture clears this flag before the Environment can be published to
    /// another mutator. Root and module environments never opt into this proof;
    /// nested scopes inherit it only from a still-private activation. Capture
    /// clears it with release ordering even for already-shared ancestors, whose
    /// binding lookups must never race with that same-value update.
    private_activation: std.atomic.Value(bool) = .init(false),
    /// True for the *function body* block — a real block env (so it can hold the
    /// body's top-level `let`/`const`) but treated like the variable scope for
    /// function-declaration hoisting and Annex B B.3.3 analysis: a function
    /// declared directly in the body is var-scoped, not block-scoped.
    fn_body: bool = false,
    /// True for the declarative environment that holds a *simple* (single
    /// BindingIdentifier) catch parameter. Annex B.3.5 lets a direct eval's `var`
    /// match such a binding without the lexical-conflict SyntaxError, so
    /// EvalDeclarationInstantiation skips this environment in its conflict walk.
    is_catch_param: bool = false,
    /// An object Environment Record for a `with (obj) {…}` block: identifier
    /// resolution at this chain position consults `obj`'s properties (honoring
    /// `Symbol.unscopables`). Because it sits in the lexical chain, a binding
    /// declared *inside* the `with` (innermost) shadows it, and it in turn
    /// shadows outer scopes — and a function defined inside the `with` captures
    /// it through its closure.
    with_object: ?*value.Object = null,
    /// Phase 7 / M3: serializes the binding storage a concurrent GC marker reads
    /// in `traceEnv` (`vars` values, `disposables`, `aliases`) against the
    /// mutator's binding writes (`put`/`assign`/`putAlias`, `using` registration).
    /// Like `Object.property_lock`: shared/captured writers and lookups take it.
    /// Uncaptured private activations may elide it under the collector handshake
    /// because only their owning mutator changes the tables. The uncontended
    /// shared path is a single atomic CAS.
    binding_lock: std.atomic.Mutex = .unlocked,
    /// Immutable publication ruling for this Environment. Context-embedded
    /// roots in single-owner realms are traced only at quiescent checkpoints
    /// and never need the mutex; roots exposed to peer mutators or a concurrent
    /// marker set this before bootstrap and retain it for their whole lifetime.
    binding_lock_required: bool = true,

    /// Binding locks are only needed when a context runs the GC marker
    /// concurrently (`concurrent_gc`) or multiple mutators in parallel
    /// (`parallel_gc`). This is process-wide and intentionally starts enabled:
    /// concurrent context creation can otherwise flip false→true between a
    /// lock helper's load and its paired unlock helper, making the unlock act on
    /// an unheld mutex. Private writes use a separate per-interpreter handshake;
    /// this flag remains the fail-safe policy for every actual lock pair.
    pub var binding_locks_enabled: std.atomic.Value(bool) = .init(true);

    fn bindingRecord(self: *const Environment) *const Environment {
        const target = self.direct_eval_forward_target orelse return self;
        std.debug.assert(self.activation == null);
        std.debug.assert(target.direct_eval_forward_target == null);
        return target;
    }

    fn mutableBindingRecord(self: *Environment) *Environment {
        return @constCast(self.bindingRecord());
    }

    fn activationBinding(self: *const Environment, name: []const u8) ?bc.DirectEvalBinding {
        if (self.activation) |*view| if (view.binding(name)) |binding| return binding;
        const target = self.direct_eval_forward_target orelse return null;
        return target.activationBinding(name);
    }

    pub fn hasOwnBinding(self: *const Environment, name: []const u8) bool {
        if (self.activationBinding(name) != null) return true;
        const record = @constCast(self.bindingRecord());
        const locked = record.lockBindingsForRead();
        defer record.unlockBindingsForRead(locked);
        return record.aliases.contains(name) or record.vars.contains(name);
    }

    pub fn lockBindings(self: *Environment) void {
        if (!self.binding_lock_required or !binding_locks_enabled.load(.acquire)) return;
        var spins: usize = 0;
        while (!self.binding_lock.tryLock()) : (spins += 1) {
            if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
        }
        jsthread.recordEnvLockAcquire(spins);
        gc_runtime.enterTraceSensitiveLock();
    }
    pub fn unlockBindings(self: *Environment) void {
        if (!self.binding_lock_required or !binding_locks_enabled.load(.acquire)) return;
        gc_runtime.leaveTraceSensitiveLock();
        self.binding_lock.unlock();
    }

    /// Acquire the binding lock for a table read unless this is an uncaptured,
    /// mutator-private activation. Returns whether the caller must unlock.
    pub fn lockBindingsForRead(self: *Environment) bool {
        if (!self.binding_lock_required) return false;
        if (self.private_activation.load(.acquire) and !self.captured.load(.acquire)) return false;
        self.lockBindings();
        jsthread.recordEnvReadLockAcquire(if (self.parent == null)
            .root
        else if (self.captured.load(.acquire))
            .captured
        else
            .other);
        return true;
    }

    pub fn unlockBindingsForRead(self: *Environment, locked: bool) void {
        if (locked) self.unlockBindings();
    }

    /// Enter a binding-table write. Uncaptured private activations use the
    /// active interpreter's marker handshake instead of the per-Environment
    /// mutex; every other Environment retains the ordinary lock. Returns true
    /// when the caller owns `binding_lock`, false when it owns the private-write
    /// guard. Allocation recovery treats both as trace-sensitive regions.
    pub fn lockBindingsForWrite(self: *Environment) bool {
        // Preserve the existing boolean guard contract for callers: `true`
        // takes the ordinary unlock branch, whose immutable policy check is a
        // no-op for this single-owner Environment.
        if (!self.binding_lock_required) return true;
        if (self.private_activation.load(.acquire) and !self.captured.load(.acquire) and
            gc_mod.tryEnterPrivateEnvironmentWrite())
        {
            gc_runtime.enterTraceSensitiveLock();
            jsthread.recordEnvPrivateWriteElision();
            return false;
        }
        self.lockBindings();
        jsthread.recordEnvWriteLockAcquire(if (self.private_activation.load(.acquire) and !self.captured.load(.acquire))
            .private
        else if (self.parent == null)
            .root
        else if (self.captured.load(.acquire))
            .captured
        else
            .other);
        return true;
    }

    pub fn unlockBindingsForWrite(self: *Environment, locked: bool) void {
        if (!self.binding_lock_required) return;
        if (locked) {
            self.unlockBindings();
        } else {
            gc_runtime.leaveTraceSensitiveLock();
            gc_mod.leavePrivateEnvironmentWrite();
        }
    }

    pub fn lockBindingsForTrace(self: *Environment) void {
        if (!self.binding_lock_required) return;
        self.lockBindings();
        jsthread.recordEnvTraceLockAcquire();
    }

    pub fn unlockBindingsForTrace(self: *Environment) void {
        if (!self.binding_lock_required) return;
        self.unlockBindings();
    }

    inline fn barrierStoredValue(self: *Environment, v: Value) void {
        if (self.gc_managed)
            gc_mod.barrierValueFromManaged(self, v)
        else
            // The realm root is embedded in Context, not in a GC cell. Passing
            // its address as an owner makes the tolerant barrier exhaust the
            // slab/index lookup on every root binding write. The ownerless path
            // retains the exact young target and shades it during incremental
            // marking, which is the required barrier for an external root.
            gc_mod.barrierValue(v);
    }

    inline fn barrierStoredEnvironment(self: *Environment, target: *Environment) void {
        if (!target.gc_managed) return;
        if (self.gc_managed) {
            if (!gc_mod.barrierExactManagedCellFrom(self, target))
                gc_mod.barrierCellFrom(self, target);
        } else {
            // Context-embedded roots are external precise roots rather than GC
            // cells; retain and shade a newly published managed module target.
            gc_mod.barrierCell(target);
        }
    }

    inline fn bindingsHaveSingleWriter(self: *const Environment) bool {
        return !self.binding_lock_required or (self.private_activation.load(.acquire) and !self.captured.load(.acquire));
    }

    /// Define (or overwrite) a binding in *this* scope (used by let/const).
    pub fn put(self: *Environment, name: []const u8, v: Value) EvalError!void {
        if (self.activation) |*view| if (view.binding(name)) |binding| {
            self.barrierStoredValue(v);
            view.frame.write(binding.slot, v);
            return;
        };
        if (self.direct_eval_forward_target) |target| return target.put(name, v);
        self.barrierStoredValue(v);
        if (self.bindingsHaveSingleWriter()) {
            // The owning mutator is the only structural writer. Snapshot before
            // allocating so a private activation retains one collector handshake
            // and an existing-value update never performs a fallible key copy.
            if (self.vars.contains(name)) {
                const locked = self.lockBindingsForWrite();
                defer self.unlockBindingsForWrite(locked);
                self.vars.getPtr(name).?.* = v;
                return;
            }
            var owned: ?[]u8 = try self.dupeBindingName(name);
            defer if (owned) |key| self.freeBindingName(key);
            const locked = self.lockBindingsForWrite();
            defer self.unlockBindingsForWrite(locked);
            try self.vars.ensureUnusedCapacity(self.bindingAllocator(), 1);
            self.vars.putAssumeCapacity(owned.?, v);
            owned = null;
            return;
        }

        var locked = self.lockBindingsForWrite();
        if (self.vars.getPtr(name)) |slot| {
            slot.* = v;
            self.unlockBindingsForWrite(locked);
            return;
        }
        self.unlockBindingsForWrite(locked);

        // The caller's name commonly borrows parser/source storage. Take
        // ownership outside the trace-sensitive Environment lock so heap-limit
        // recovery can collect an unreachable prior scope. Then recheck under
        // the lock: a no-GIL peer may have inserted the binding meanwhile.
        var owned: ?[]u8 = try self.dupeBindingName(name);
        defer if (owned) |key| self.freeBindingName(key);
        locked = self.lockBindingsForWrite();
        defer self.unlockBindingsForWrite(locked);
        if (self.vars.getPtr(name)) |slot| {
            slot.* = v;
            return;
        }
        try self.vars.ensureUnusedCapacity(self.bindingAllocator(), 1);
        self.vars.putAssumeCapacity(owned.?, v);
        owned = null;
    }

    fn putTaggedBinding(
        self: *Environment,
        tag: *std.StringHashMapUnmanaged(void),
        name: []const u8,
        v: Value,
    ) EvalError!void {
        while (true) {
            const single_writer = self.bindingsHaveSingleWriter();
            var locked = if (single_writer) false else self.lockBindingsForWrite();
            const needs_value_key = !self.vars.contains(name);
            const needs_tag_key = !tag.contains(name);
            if (!needs_value_key and !needs_tag_key) {
                if (single_writer) locked = self.lockBindingsForWrite();
                defer self.unlockBindingsForWrite(locked);
                self.vars.getPtr(name).?.* = v;
                return;
            }
            if (!single_writer) self.unlockBindingsForWrite(locked);

            // Allocate only the keys absent in the optimistic snapshot. The
            // ordinary lexical-declaration path already has its value binding
            // and must not require a second temporary copy under heap pressure.
            // A no-GIL DeleteBinding can invalidate that snapshot; retry outside
            // the lock if the final state needs a key we did not prepare.
            var value_key: ?[]u8 = null;
            defer if (value_key) |key| self.freeBindingName(key);
            if (needs_value_key) value_key = try self.dupeBindingName(name);
            var tag_key: ?[]u8 = null;
            defer if (tag_key) |key| self.freeBindingName(key);
            if (needs_tag_key) tag_key = try self.dupeBindingName(name);

            locked = self.lockBindingsForWrite();
            const value_slot = self.vars.getPtr(name);
            const has_tag = tag.contains(name);
            if ((value_slot == null and value_key == null) or (!has_tag and tag_key == null)) {
                self.unlockBindingsForWrite(locked);
                continue;
            }
            defer self.unlockBindingsForWrite(locked);

            // Capacity growth is the last fallible phase. It may retain an empty
            // allocation when the second table fails, but no binding or side-table
            // state becomes semantically visible until both reservations succeed.
            const a = self.bindingAllocator();
            if (value_slot == null) try self.vars.ensureUnusedCapacity(a, 1);
            if (!has_tag) try tag.ensureUnusedCapacity(a, 1);

            if (value_slot == null) {
                self.vars.putAssumeCapacity(value_key.?, v);
                value_key = null;
            } else {
                value_slot.?.* = v;
            }
            if (!has_tag) {
                tag.putAssumeCapacity(tag_key.?, {});
                tag_key = null;
            }
            return;
        }
    }

    /// Define a `const` binding in this scope (marks it immutable for `assign`).
    pub fn putConst(self: *Environment, name: []const u8, v: Value) EvalError!void {
        if (self.direct_eval_forward_target) |target| return target.putConst(name, v);
        self.barrierStoredValue(v);
        try self.putTaggedBinding(&self.consts, name, v);
    }

    fn markOwnedName(
        self: *Environment,
        set: *std.StringHashMapUnmanaged(void),
        name: []const u8,
    ) EvalError!void {
        const single_writer = self.bindingsHaveSingleWriter();
        var locked = if (single_writer) false else self.lockBindingsForWrite();
        if (set.contains(name)) {
            if (!single_writer) self.unlockBindingsForWrite(locked);
            return;
        }
        if (!single_writer) self.unlockBindingsForWrite(locked);

        var owned: ?[]u8 = try self.dupeBindingName(name);
        defer if (owned) |key| self.freeBindingName(key);
        locked = self.lockBindingsForWrite();
        defer self.unlockBindingsForWrite(locked);
        if (set.contains(name)) return;
        try set.ensureUnusedCapacity(self.bindingAllocator(), 1);
        set.putAssumeCapacity(owned.?, {});
        owned = null;
    }

    /// Record `name` as a global lexical declaration (see `lexicals`). The binding
    /// value itself is stored via the normal `put`/`putConst`; this only tags it so
    /// an identifier read resolves the declarative binding, not a shadowed
    /// global-object property.
    pub fn markLexical(self: *Environment, name: []const u8) EvalError!void {
        if (self.direct_eval_forward_target) |target| return target.markLexical(name);
        try self.markOwnedName(&self.lexicals, name);
    }

    /// Bind a named function expression's own name (immutable, non-strict).
    pub fn putFnName(self: *Environment, name: []const u8, v: Value) EvalError!void {
        if (self.direct_eval_forward_target) |target| return target.putFnName(name, v);
        self.barrierStoredValue(v);
        try self.putTaggedBinding(&self.fn_names, name, v);
    }

    /// Mark a binding in *this* scope as deletable (a sloppy eval-created var/fn).
    pub fn markDeletable(self: *Environment, name: []const u8) EvalError!void {
        if (self.direct_eval_forward_target) |target| return target.markDeletable(name);
        try self.markOwnedName(&self.deletable, name);
    }

    /// Remove a binding from *this* scope entirely (DeleteBinding for a deletable
    /// eval var). Drops it from `vars` and every side table so it no longer
    /// resolves. Returns whether a binding was present.
    pub fn removeVar(self: *Environment, name: []const u8) bool {
        if (self.direct_eval_forward_target) |target| return target.removeVar(name);
        const locked = self.lockBindingsForWrite();
        defer self.unlockBindingsForWrite(locked);
        const removed = if (self.vars.fetchRemove(name)) |entry| blk: {
            self.freeBindingName(entry.key);
            break :blk true;
        } else false;
        if (self.consts.fetchRemove(name)) |entry| self.freeBindingName(entry.key);
        if (self.fn_names.fetchRemove(name)) |entry| self.freeBindingName(entry.key);
        if (self.deletable.fetchRemove(name)) |entry| self.freeBindingName(entry.key);
        return removed;
    }

    /// Whether the nearest binding named `name` is a non-strict immutable
    /// (function-expression name) binding. Matches where `assign` would write.
    pub fn isFnName(self: *Environment, name: []const u8) bool {
        var env: ?*Environment = self;
        while (env) |e| {
            if (e.activationBinding(name) != null) return false;
            const record = e.mutableBindingRecord();
            const locked = record.lockBindingsForRead();
            if (record.vars.contains(name)) {
                const r = record.fn_names.contains(name);
                record.unlockBindingsForRead(locked);
                return r;
            }
            record.unlockBindingsForRead(locked);
            env = e.parent;
        }
        return false;
    }

    /// Whether the nearest binding named `name` is `const` (null if no binding).
    /// Matches where `assign` would write, so shadowing is handled correctly.
    pub fn isConst(self: *Environment, name: []const u8) ?bool {
        var env: ?*Environment = self;
        while (env) |e| {
            if (e.activationBinding(name)) |binding| return binding.immutable;
            const record = e.mutableBindingRecord();
            const locked = record.lockBindingsForRead();
            if (record.vars.contains(name)) {
                const r = record.consts.contains(name);
                record.unlockBindingsForRead(locked);
                return r;
            }
            record.unlockBindingsForRead(locked);
            env = e.parent;
        }
        return null;
    }

    /// Mark this environment and its ancestors as captured by a closure. A
    /// closure resolves free names through its whole lexical chain, so capturing
    /// it makes every ancestor binding reachable — including any enclosing
    /// `for (let …)` per-iteration env, which then must not be reused. Walks up
    /// only until an already-captured env (or the top): the first closure marks
    /// the chain, later ones short-circuit, so it stays cheap.
    pub fn markCaptured(self: *Environment) void {
        var e: ?*Environment = self;
        while (e) |env| : (e = env.parent) {
            if (env.direct_eval_forward_target) |target| target.markCaptured();
            if (env.captured.load(.acquire)) break;
            // Clear the single-mutator proof before publishing a closure. A
            // forwarding view may also reach an already-shared ancestor, so
            // even a same-value clear races with peer lookups unless atomic.
            env.private_activation.store(false, .release);
            if (env.activation) |*view| view.frame.markEscaped();
            env.captured.store(true, .release);
        }
    }

    /// The nearest enclosing variable environment (function or global), where
    /// `var`/function declarations live.
    pub fn varScope(self: *Environment) *Environment {
        var e = self;
        while (!e.bindingRecord().fn_scope) {
            e = e.parent orelse return e;
        }
        return e;
    }

    /// Assign to the nearest existing binding (used by `=`); if none exists,
    /// create it on the global (root) scope, matching sloppy-mode semantics.
    pub fn assign(self: *Environment, name: []const u8, v: Value) EvalError!void {
        var env: ?*Environment = self;
        while (env) |e| {
            if (e.activation) |*view| if (view.binding(name)) |binding| {
                e.barrierStoredValue(v);
                view.frame.write(binding.slot, v);
                return;
            };
            const record = e.mutableBindingRecord();
            // Hold `binding_lock` across BOTH the `getPtr` lookup and the value
            // write. Under no-GIL a peer thread's `put`/`getOrPut` on this scope
            // (e.g. globalDefine) can rehash `vars` concurrently, so an unlocked
            // lookup here races the grow — the systemic no-GIL Environment race
            // (Linux tsan-threadfuzz: globalDefine put vs assign getPtr). `ptr`
            // stays valid for the write because no rehash can occur under the
            // lock. A private activation instead owns the table exclusively and
            // uses the marker handshake until capture revokes that proof.
            const locked = record.lockBindingsForWrite();
            if (record.vars.getPtr(name)) |ptr| {
                record.barrierStoredValue(v);
                ptr.* = v;
                record.unlockBindingsForWrite(locked);
                return;
            }
            record.unlockBindingsForWrite(locked);
            env = e.parent;
        }
        var root = self;
        while (root.parent) |p| root = p;
        try root.put(name, v);
    }

    pub const ResolvedBindingState = enum {
        mutable,
        missing,
        tdz,
        immutable,
        function_name,
    };

    /// Classify one exact Declarative Environment Record without walking to a
    /// now-closer binding. Used by a previously captured Reference: PutValue
    /// must retain its original base even if intervening JavaScript mutates the
    /// surrounding environment chain before the store.
    pub fn resolvedBindingState(self: *Environment, name: []const u8, tdz_marker: ?*value.Object) ResolvedBindingState {
        if (self.activation) |*view| if (view.binding(name)) |binding| {
            const current = view.frame.read(binding.slot);
            if (tdz_marker) |marker|
                if (current.isObject() and current.asObj() == marker) return .tdz;
            return if (binding.immutable) .immutable else .mutable;
        };
        const record = self.mutableBindingRecord();
        const locked = record.lockBindingsForRead();
        defer record.unlockBindingsForRead(locked);
        if (record.aliases.contains(name)) return .immutable;
        const current = record.vars.get(name) orelse return .missing;
        if (tdz_marker) |marker|
            if (current.isObject() and current.asObj() == marker) return .tdz;
        if (record.consts.contains(name)) return .immutable;
        if (record.fn_names.contains(name)) return .function_name;
        return .mutable;
    }

    /// Store into this exact Environment Record. The caller has already applied
    /// TDZ/immutability checks and deliberately does not fall through to a
    /// different record if the binding disappeared after Reference creation.
    pub fn assignOwnResolved(self: *Environment, name: []const u8, v: Value) bool {
        if (self.activation) |*view| if (view.binding(name)) |binding| {
            self.barrierStoredValue(v);
            view.frame.write(binding.slot, v);
            return true;
        };
        const record = self.mutableBindingRecord();
        record.barrierStoredValue(v);
        const locked = record.lockBindingsForWrite();
        defer record.unlockBindingsForWrite(locked);
        const slot = record.vars.getPtr(name) orelse return false;
        slot.* = v;
        return true;
    }

    /// An indirect (module import) binding: `name` in module environment `env`.
    pub const Alias = struct { env: *Environment, name: []const u8 };

    /// Install an indirect binding `local` → `target.name` (a module import).
    pub fn putAlias(self: *Environment, local: []const u8, target: *Environment, name: []const u8) EvalError!void {
        if (self.direct_eval_forward_target) |forwarded| return forwarded.putAlias(local, target, name);
        self.barrierStoredEnvironment(target);
        // Both caller-provided names are owned before the Environment lock is
        // taken. Allocation recovery is prohibited inside that trace-sensitive
        // region, and a concurrent insert can make the local copy unnecessary.
        const optimistic_lock = self.lockBindingsForRead();
        const needs_local_key = !self.aliases.contains(local);
        self.unlockBindingsForRead(optimistic_lock);
        var local_key: ?[]u8 = if (needs_local_key) try self.dupeBindingName(local) else null;
        defer if (local_key) |key| self.freeBindingName(key);
        var target_key: ?[]u8 = try self.dupeBindingName(name);
        defer if (target_key) |key| self.freeBindingName(key);

        const locked = self.lockBindingsForWrite(); // traceEnv reads `aliases`; serialize the structural write
        defer self.unlockBindingsForWrite(locked);
        const existing = self.aliases.getPtr(local);
        // Alias bindings are module-instantiation state and are never deleted.
        // A peer may only have inserted one since the optimistic read, in which
        // case the unused local copy is released after unlocking.
        std.debug.assert(existing != null or local_key != null);
        if (existing == null) try self.aliases.ensureUnusedCapacity(self.bindingAllocator(), 1);

        const replacement = Alias{ .env = target, .name = target_key.? };
        target_key = null;
        if (existing) |slot| {
            const old_name = slot.name;
            slot.* = replacement;
            self.freeBindingName(old_name);
        } else {
            self.aliases.putAssumeCapacity(local_key.?, replacement);
            local_key = null;
        }
    }

    /// Whether `name` resolves (in the nearest scope that binds it) to a module
    /// import — an immutable indirect binding.
    pub fn isAlias(self: *Environment, name: []const u8) bool {
        var env: ?*Environment = self;
        while (env) |e| {
            if (e.activationBinding(name) != null) return false;
            const record = e.mutableBindingRecord();
            const locked = record.lockBindingsForRead();
            if (record.aliases.contains(name)) {
                record.unlockBindingsForRead(locked);
                return true;
            }
            if (record.vars.contains(name)) {
                record.unlockBindingsForRead(locked);
                return false;
            }
            record.unlockBindingsForRead(locked);
            env = e.parent;
        }
        return false;
    }

    /// Look up a binding, walking outward through enclosing scopes. A module
    /// import (`aliases`) resolves live in its exporting module's environment.
    pub fn get(self: *Environment, name: []const u8) ?Value {
        var env: ?*Environment = self;
        while (env) |e| {
            if (e.activation) |*view| if (view.binding(name)) |binding|
                return view.frame.read(binding.slot);
            const record = e.mutableBindingRecord();
            // Shared/captured scopes read under `binding_lock` so a concurrent
            // `put`/`putAlias` rehash cannot tear the read or free the table.
            // Uncaptured private activations have one mutator and may read
            // lock-free; their writes use the marker handshake above.
            const locked = record.lockBindingsForRead();
            if (record.aliases.count() != 0) {
                if (record.aliases.get(name)) |a| {
                    record.unlockBindingsForRead(locked);
                    return a.env.get(a.name);
                }
            }
            if (record.vars.get(name)) |v| {
                record.unlockBindingsForRead(locked);
                return v;
            }
            record.unlockBindingsForRead(locked);
            env = e.parent;
        }
        return null;
    }

    /// Look up a binding known to live in this exact declarative environment.
    /// Mapped-arguments parameter aliases use this: a parameter map never targets
    /// an outer scope or module alias, so the full parent-chain/alias walk only
    /// adds lock/hash churn on hot no-GIL readers.
    pub fn getLocal(self: *Environment, name: []const u8) ?Value {
        if (self.activation) |*view| if (view.binding(name)) |binding|
            return view.frame.read(binding.slot);
        const record = self.mutableBindingRecord();
        const locked = record.lockBindingsForRead();
        defer record.unlockBindingsForRead(locked);
        return record.vars.get(name);
    }

    /// GetBindingValue from this exact Declarative Environment Record without
    /// walking to a different record if the binding disappeared. Module import
    /// aliases remain live views of their target binding.
    pub fn getOwnResolved(self: *Environment, name: []const u8) ?Value {
        if (self.activation) |*view| if (view.binding(name)) |binding|
            return view.frame.read(binding.slot);
        const record = self.mutableBindingRecord();
        const locked = record.lockBindingsForRead();
        const alias = if (record.aliases.count() != 0) record.aliases.get(name) else null;
        const local = if (alias == null) record.vars.get(name) else null;
        record.unlockBindingsForRead(locked);
        if (alias) |target| return target.env.get(target.name);
        return local;
    }

    /// Assign a binding known to live in this exact declarative environment.
    /// Returns false if the binding is absent; callers that need sloppy global
    /// creation should use `assign` instead.
    pub fn assignLocal(self: *Environment, name: []const u8, v: Value) bool {
        if (self.activation) |*view| if (view.binding(name)) |binding| {
            self.barrierStoredValue(v);
            view.frame.write(binding.slot, v);
            return true;
        };
        const record = self.mutableBindingRecord();
        const locked = record.lockBindingsForWrite();
        defer record.unlockBindingsForWrite(locked);
        if (record.vars.getPtr(name)) |ptr| {
            record.barrierStoredValue(v);
            ptr.* = v;
            return true;
        }
        return false;
    }

    pub fn bindingAllocator(self: *const Environment) std.mem.Allocator {
        return self.bindings_allocator orelse self.arena;
    }

    fn dupeBindingName(self: *Environment, name: []const u8) EvalError![]u8 {
        const copy = try self.bindingAllocator().dupe(u8, name);
        if (self.bindings_allocator != null) {
            if (self.gc_name_bytes_live) |live| _ = @atomicRmw(usize, live, .Add, copy.len, .monotonic);
        }
        return copy;
    }

    fn deinitOwnedBindingStorage(self: *Environment) void {
        const a = self.bindings_allocator orelse return;

        var vit = self.vars.keyIterator();
        while (vit.next()) |key| self.freeBindingName(key.*);
        self.vars.deinit(a);
        self.vars = .{};

        var cit = self.consts.keyIterator();
        while (cit.next()) |key| self.freeBindingName(key.*);
        self.consts.deinit(a);
        self.consts = .{};

        var lit = self.lexicals.keyIterator();
        while (lit.next()) |key| self.freeBindingName(key.*);
        self.lexicals.deinit(a);
        self.lexicals = .{};

        var fit = self.fn_names.keyIterator();
        while (fit.next()) |key| self.freeBindingName(key.*);
        self.fn_names.deinit(a);
        self.fn_names = .{};

        var dit = self.deletable.keyIterator();
        while (dit.next()) |key| self.freeBindingName(key.*);
        self.deletable.deinit(a);
        self.deletable = .{};

        var ait = self.aliases.iterator();
        while (ait.next()) |entry| {
            self.freeBindingName(entry.key_ptr.*);
            self.freeBindingName(entry.value_ptr.name);
        }
        self.aliases.deinit(a);
        self.aliases = .{};

        self.disposables.deinit(a);
        self.disposables = .empty;
        self.dispose_pending = null;
    }

    /// Drop every allocator-owned side store before an uncaptured lexical
    /// environment is reused. The environment is still an active interpreter
    /// root here, so coordinate with a concurrent marker exactly like a binding
    /// write; the GC finalizer uses the unlocked companion after the cell is
    /// already known dead.
    pub fn resetForBlockReuse(self: *Environment) void {
        const locked = self.lockBindingsForWrite();
        defer self.unlockBindingsForWrite(locked);
        self.deinitOwnedBindingStorage();
        // A concurrent tracer reads the reusable cell under this same
        // Environment lock. Clear every mutable graph/ownership field before
        // publishing it in the interpreter cache.
        self.parent = null;
        self.object_proto_intrinsic = null;
        self.captured.store(false, .monotonic);
        self.fn_scope = false;
        self.private_activation.store(false, .monotonic);
        self.fn_body = false;
        self.is_catch_param = false;
        self.with_object = null;
        self.direct_eval_forward_target = null;
    }

    /// Clear a completed private activation while retaining its static binding
    /// layout for the next call of the same AST. Values are overwritten with
    /// `undefined` under the trace lock so the cache retains no user object
    /// graph. Dynamic eval bindings (`deletable`) and live aliases are excluded
    /// by releaseCallEnvironment; only bounded parameter/declaration spelling
    /// tables survive.
    pub fn resetForCallReuse(self: *Environment) void {
        const locked = self.lockBindingsForWrite();
        defer self.unlockBindingsForWrite(locked);
        var values = self.vars.valueIterator();
        while (values.next()) |slot| slot.* = Value.undef();
        if (self.bindings_allocator) |a| {
            self.disposables.deinit(a);
            self.disposables = .empty;
        } else {
            self.disposables.clearRetainingCapacity();
        }
        self.dispose_pending = null;
        self.parent = null;
        self.object_proto_intrinsic = null;
        self.captured.store(false, .monotonic);
        self.fn_scope = false;
        self.private_activation.store(false, .monotonic);
        self.fn_body = false;
        self.is_catch_param = false;
        self.with_object = null;
        self.direct_eval_forward_target = null;
    }

    pub fn finalizeOwnedBindingStorage(self: *Environment) void {
        self.deinitOwnedBindingStorage();
    }

    pub fn freeBindingName(self: *Environment, name: []const u8) void {
        if (self.bindings_allocator) |a| {
            a.free(name);
            if (self.gc_name_bytes_live) |live| {
                _ = @atomicRmw(usize, live, .Sub, name.len, .monotonic);
            }
        }
    }
};

test "Environment barriers distinguish embedded roots from managed owners" {
    const Provider = struct {
        calls: usize = 0,
        last_owner: ?*anyopaque = undefined,

        fn barrier(raw: *anyopaque, owner: ?*anyopaque, _: ?*anyopaque) void {
            const self: *@This() = @ptrCast(@alignCast(raw));
            self.calls += 1;
            self.last_owner = owner;
        }
    };

    var provider: Provider = .{};
    const previous = gc_runtime.setBarrier(&provider, Provider.barrier, null, null);
    defer _ = gc_runtime.setBarrier(previous[0], previous[1], previous[2], previous[3]);

    var child = value.Object{};
    var embedded = Environment{ .arena = std.testing.allocator };
    embedded.barrierStoredValue(Value.obj(&child));
    try std.testing.expectEqual(@as(usize, 1), provider.calls);
    try std.testing.expect(provider.last_owner == null);

    var managed = Environment{ .arena = std.testing.allocator, .gc_managed = true };
    managed.barrierStoredValue(Value.obj(&child));
    try std.testing.expectEqual(@as(usize, 2), provider.calls);
    try std.testing.expectEqual(@intFromPtr(&managed), @intFromPtr(provider.last_owner.?));
}

test "Environment direct eval forwarding preserves one live binding record" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();

    var original_parent = Environment{
        .arena = allocator,
        .binding_lock_required = false,
    };
    try original_parent.put("originalOnly", Value.num(1));
    var interleaved_parent = Environment{
        .arena = allocator,
        .binding_lock_required = false,
    };
    try interleaved_parent.put("interleavedOnly", Value.num(2));
    var target = Environment{
        .arena = allocator,
        .parent = &original_parent,
        .fn_scope = true,
        .binding_lock_required = false,
    };
    try target.put("mutable", Value.num(3));
    try target.putConst("immutable", Value.num(4));
    try target.putFnName("selfName", Value.num(5));
    try target.put("deletable", Value.num(6));
    try target.markDeletable("deletable");

    var forwarded = Environment{
        .arena = allocator,
        .parent = &interleaved_parent,
        .direct_eval_forward_target = &target,
        .binding_lock_required = false,
    };

    try std.testing.expectEqual(@as(?Value, Value.num(3)), forwarded.get("mutable"));
    try std.testing.expectEqual(@as(?Value, Value.num(2)), forwarded.get("interleavedOnly"));
    try std.testing.expectEqual(@as(?Value, null), forwarded.get("originalOnly"));
    try std.testing.expect(forwarded.hasOwnBinding("immutable"));
    try std.testing.expectEqual(@as(?bool, true), forwarded.isConst("immutable"));
    try std.testing.expect(forwarded.isFnName("selfName"));
    try std.testing.expectEqual(&forwarded, forwarded.varScope());

    try forwarded.assign("mutable", Value.num(7));
    try std.testing.expectEqual(@as(?Value, Value.num(7)), target.getLocal("mutable"));
    try target.put("late", Value.num(8));
    try std.testing.expectEqual(@as(?Value, Value.num(8)), forwarded.getLocal("late"));
    try forwarded.put("createdThroughForwarder", Value.num(9));
    try std.testing.expectEqual(@as(?Value, Value.num(9)), target.getLocal("createdThroughForwarder"));
    try std.testing.expect(forwarded.removeVar("deletable"));
    try std.testing.expectEqual(@as(?Value, null), target.getLocal("deletable"));
}

test "Environment direct eval forwarding preserves with binding references" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();
    const root_shape = try Shape.createRoot(allocator);
    var root = Environment{
        .arena = allocator,
        .fn_scope = true,
        .binding_lock_required = false,
    };
    var object = value.Object{};
    try object.setOwn(allocator, root_shape, "visible", Value.num(11));
    var target = Environment{
        .arena = allocator,
        .parent = &root,
        .with_object = &object,
        .binding_lock_required = false,
    };
    var forwarded = Environment{
        .arena = allocator,
        .parent = &root,
        .direct_eval_forward_target = &target,
        .binding_lock_required = false,
    };
    var machine = Interpreter{
        .arena = allocator,
        .env = &forwarded,
        .root_shape = root_shape,
    };

    const loaded = try machine.resolveBindingValue("visible", false);
    try std.testing.expectEqual(@as(f64, 11), loaded.value.asNum());
    try std.testing.expectEqual(&object, loaded.with_base.asObj());
    const reference = try machine.captureBindingReference("visible", null);
    try std.testing.expect(reference == .with_object);
    try std.testing.expectEqual(&object, reference.with_object);
    try machine.storeCapturedBindingReference(reference, "visible", Value.num(12));
    try std.testing.expectEqual(@as(f64, 12), object.getOwn("visible").?.asNum());
    try std.testing.expect(try machine.deleteIdentifier("visible", false, null));
    try std.testing.expectEqual(@as(?Value, null), object.getOwn("visible"));
}

test "Environment immutable lock ruling keeps only shared roots synchronized" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();

    jsthread.resetContentionStats();
    defer jsthread.disableContentionStats();
    var single_owner = Environment{
        .arena = arena.allocator(),
        .binding_lock_required = false,
    };
    try single_owner.put("value", Value.num(1));
    try std.testing.expectEqual(@as(?Value, Value.num(1)), single_owner.get("value"));
    try std.testing.expect(single_owner.assignLocal("value", Value.num(2)));
    try std.testing.expectEqual(@as(u64, 0), jsthread.contentionStats().env_lock_acquires);

    var shared = Environment{ .arena = arena.allocator() };
    try shared.put("value", Value.num(1));
    try std.testing.expectEqual(@as(?Value, Value.num(1)), shared.get("value"));
    // A shared insertion snapshots under one lock, allocates outside the
    // trace-sensitive region, then publishes under a second lock. The read is
    // the third acquisition; private/single-owner environments still write once.
    try std.testing.expectEqual(@as(u64, 3), jsthread.contentionStats().env_lock_acquires);
    try std.testing.expectEqual(@as(u64, 1), jsthread.contentionStats().env_read_lock_acquires);
    try std.testing.expectEqual(@as(u64, 2), jsthread.contentionStats().env_write_lock_acquires);
}

test "Environment capture publication synchronizes forwarding targets and peer reads" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();
    const lane_count = 4;
    const record_count = 256;
    var root = Environment{ .arena = allocator };
    const records = try allocator.alloc(Environment, record_count);
    for (records) |*record| {
        record.* = .{ .arena = allocator, .parent = &root };
        try record.put("value", Value.num(17));
    }
    var arrivals: std.atomic.Value(usize) = .init(0);
    var stop: std.atomic.Value(bool) = .init(false);
    var threads: [lane_count]std.Thread = undefined;
    var spawned: usize = 0;
    var results: [lane_count]bool = undefined;
    @memset(&results, true);
    defer {
        stop.store(true, .release);
        for (threads[0..spawned]) |thread| thread.join();
    }
    const Lane = struct {
        fn run(shared: []Environment, ready: *std.atomic.Value(usize), abort: *std.atomic.Value(bool), lane: usize, result: *bool) void {
            for (shared, 0..) |*record, index| {
                _ = ready.fetchAdd(1, .acq_rel);
                while (ready.load(.acquire) < (index + 1) * lane_count) {
                    if (abort.load(.acquire)) return;
                    std.atomic.spinLoopHint();
                }
                if (lane < 2) {
                    var forwarding = Environment{
                        .arena = record.arena,
                        .parent = record.parent,
                        .direct_eval_forward_target = record,
                    };
                    forwarding.markCaptured();
                    if (!forwarding.captured.load(.acquire) or !record.captured.load(.acquire)) result.* = false;
                } else {
                    for (0..8) |_| {
                        const got = record.get("value") orelse {
                            result.* = false;
                            abort.store(true, .release);
                            return;
                        };
                        if (!got.isNumber() or got.asNum() != 17) result.* = false;
                    }
                }
            }
        }
    };
    for (&threads, &results, 0..) |*thread, *result, lane| {
        thread.* = try std.Thread.spawn(.{}, Lane.run, .{ records, &arrivals, &stop, lane, result });
        spawned += 1;
    }
    for (threads) |thread| thread.join();
    spawned = 0;
    for (results) |result| try std.testing.expect(result);
    for (records) |*record| {
        try std.testing.expect(record.captured.load(.acquire));
        try std.testing.expect(!record.private_activation.load(.acquire));
    }
    try std.testing.expect(root.captured.load(.acquire));
}

test "Environment private activation reads elide locks until capture" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();

    var parent = Environment{
        .arena = arena.allocator(),
        .gc_managed = true,
        .fn_scope = true,
        .private_activation = .init(true),
    };
    try parent.put("outer", Value.num(11));
    var child = Environment{
        .arena = arena.allocator(),
        .parent = &parent,
        .gc_managed = true,
        .private_activation = .init(true),
    };
    try child.put("local", Value.num(7));

    jsthread.resetContentionStats();
    defer jsthread.disableContentionStats();
    try std.testing.expectEqual(@as(?Value, Value.num(7)), child.get("local"));
    try std.testing.expectEqual(@as(?Value, Value.num(11)), child.get("outer"));
    try std.testing.expectEqual(@as(u64, 0), jsthread.contentionStats().env_lock_acquires);

    child.markCaptured();
    try std.testing.expect(!child.private_activation.load(.acquire));
    try std.testing.expect(!parent.private_activation.load(.acquire));
    try std.testing.expectEqual(@as(?Value, Value.num(7)), child.get("local"));
    try std.testing.expectEqual(@as(?Value, Value.num(11)), child.get("outer"));
    const stats = jsthread.contentionStats();
    try std.testing.expectEqual(@as(u64, 3), stats.env_lock_acquires);
    try std.testing.expectEqual(@as(u64, 3), stats.env_read_lock_acquires);
    try std.testing.expectEqual(@as(u64, 1), stats.env_read_root_lock_acquires);
    try std.testing.expectEqual(@as(u64, 2), stats.env_read_captured_lock_acquires);
    try std.testing.expectEqual(@as(u64, 0), stats.env_read_other_lock_acquires);
}

test "Environment private activation writes use the collector handshake until capture" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();

    var root = Environment{ .arena = arena.allocator(), .fn_scope = true };
    var env = Environment{
        .arena = arena.allocator(),
        .parent = &root,
        .gc_managed = true,
        .fn_scope = true,
        .private_activation = .init(true),
    };
    var trace_active: std.atomic.Value(bool) = .init(false);
    var machine = Interpreter{
        .arena = arena.allocator(),
        .env = &env,
        .root_shape = undefined,
        .gc_environment_trace_active = &trace_active,
    };
    const previous = gc_mod.setActiveInterpreter(&machine);
    defer _ = gc_mod.setActiveInterpreter(previous);

    jsthread.resetContentionStats();
    defer jsthread.disableContentionStats();
    try env.put("value", Value.num(1));
    try std.testing.expectEqual(@as(u32, 0), machine.gc_private_environment_writes.load(.seq_cst));
    try std.testing.expect(!gc_runtime.inTraceSensitiveLock());
    var stats = jsthread.contentionStats();
    try std.testing.expectEqual(@as(u64, 0), stats.env_lock_acquires);
    try std.testing.expectEqual(@as(u64, 1), stats.env_write_private_elisions);

    trace_active.store(true, .seq_cst);
    try std.testing.expect(env.assignLocal("value", Value.num(2)));
    trace_active.store(false, .seq_cst);
    stats = jsthread.contentionStats();
    try std.testing.expectEqual(@as(u64, 1), stats.env_lock_acquires);
    try std.testing.expectEqual(@as(u64, 1), stats.env_write_private_lock_acquires);

    env.markCaptured();
    try std.testing.expect(env.assignLocal("value", Value.num(3)));
    stats = jsthread.contentionStats();
    try std.testing.expectEqual(@as(u64, 2), stats.env_lock_acquires);
    try std.testing.expectEqual(@as(u64, 1), stats.env_write_captured_lock_acquires);
    try std.testing.expectEqual(@as(u64, 1), stats.env_write_private_elisions);
}

/// The shared, mutable `this` binding of a derived constructor activation. A
/// derived ctor starts uninitialized and is bound exactly once by `super()`;
/// arrows defined lexically inside it share THIS cell (not the interpreter's
/// ambient this-state), so an arrow's `super()` initializes the enclosing ctor's
/// `this` even when the arrow is invoked from an unrelated dynamic context (e.g.
/// an iterator's `return()` running during the ctor's IteratorClose).
pub const ThisCell = struct {
    value_bits: std.atomic.Value(u64),
    /// 0 = uninitialized, 1 = a winning BindThisValue is publishing, 2 = bound.
    state: std.atomic.Value(u8),

    pub fn init(initial_value: Value, initialized: bool) ThisCell {
        return .{
            .value_bits = .init(initial_value.rawBits()),
            .state = .init(if (initialized) 2 else 0),
        };
    }

    pub fn isInitialized(self: *const ThisCell) bool {
        var state = self.state.load(.acquire);
        while (state == 1) : (state = self.state.load(.acquire)) std.atomic.spinLoopHint();
        return state == 2;
    }

    pub fn value(self: *const ThisCell) Value {
        while (self.state.load(.acquire) == 1) std.atomic.spinLoopHint();
        return Value.fromRawBits(self.value_bits.load(.acquire));
    }

    /// BindThisValue is exactly-once even when an escaped lexical arrow is
    /// invoked by concurrent no-GIL lanes after both superclass calls finish.
    pub fn bind(self: *ThisCell, bound_value: Value) bool {
        if (self.state.cmpxchgStrong(0, 1, .acq_rel, .acquire) != null) return false;
        self.value_bits.store(bound_value.rawBits(), .release);
        self.state.store(2, .release);
        return true;
    }
};

test "derived constructor this binding is published exactly once" {
    if (builtin.single_threaded) return error.SkipZigTest;

    const lane_count = 8;
    var cell = ThisCell.init(Value.undef(), false);
    var won: [lane_count]bool = @splat(false);
    const Worker = struct {
        fn run(shared: *ThisCell, result: *bool, lane: usize) void {
            result.* = shared.bind(Value.num(@floatFromInt(lane + 1)));
        }
    };
    var threads: [lane_count]std.Thread = undefined;
    for (&threads, 0..) |*thread, lane|
        thread.* = try std.Thread.spawn(.{}, Worker.run, .{ &cell, &won[lane], lane });
    for (&threads) |*thread| thread.join();

    var winners: usize = 0;
    var winner_value: f64 = 0;
    for (won, 0..) |did_win, lane| if (did_win) {
        winners += 1;
        winner_value = @floatFromInt(lane + 1);
    };
    try std.testing.expectEqual(@as(usize, 1), winners);
    try std.testing.expect(cell.isInitialized());
    try std.testing.expectEqual(winner_value, cell.value().asNum());
}

pub const ImportMetaSlot = struct {
    /// Module functions may be entered concurrently by shared-realm threads.
    /// The published pointer is therefore acquire/release, while `init_lock`
    /// serializes the first allocation so one declaring module has exactly one
    /// observable (and one allocated) import.meta object.
    obj: std.atomic.Value(?*value.Object) = .init(null),
    init_lock: std.atomic.Mutex = .unlocked,

    pub fn init(object: ?*value.Object) ImportMetaSlot {
        return .{ .obj = .init(object) };
    }

    pub fn load(self: *const ImportMetaSlot) ?*value.Object {
        return self.obj.load(.acquire);
    }

    pub fn publish(self: *ImportMetaSlot, object: *value.Object) void {
        self.obj.store(object, .release);
    }

    fn lockInitialization(self: *ImportMetaSlot) void {
        var spins: usize = 0;
        while (!self.init_lock.tryLock()) : (spins += 1) {
            if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
        }
    }
};

test "import.meta slot publishes one identity under concurrent first use" {
    const lane_count = 8;
    var slot = ImportMetaSlot{};
    var machines: [lane_count]Interpreter = undefined;
    var results: [lane_count]Value = undefined;
    var threads: [lane_count]std.Thread = undefined;
    var ready = std.atomic.Value(usize).init(0);
    var start = std.atomic.Value(bool).init(false);

    const Lane = struct {
        fn run(machine: *Interpreter, shared_slot: *ImportMetaSlot, ready_count: *std.atomic.Value(usize), start_flag: *std.atomic.Value(bool), result: *Value) void {
            machine.arena = std.testing.allocator;
            machine.gc = null;
            machine.import_meta_slot = shared_slot;
            machine.import_meta_obj = null;
            _ = ready_count.fetchAdd(1, .release);
            while (!start_flag.load(.acquire)) std.atomic.spinLoopHint();
            result.* = machine.importMetaValue() catch unreachable;
        }
    };

    for (&threads, &machines, &results) |*thread, *machine, *result|
        thread.* = try std.Thread.spawn(.{}, Lane.run, .{ machine, &slot, &ready, &start, result });
    while (ready.load(.acquire) != lane_count) std.atomic.spinLoopHint();
    start.store(true, .release);
    for (&threads) |*thread| thread.join();

    const published = slot.load() orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.destroy(published);
    for (results) |result| {
        try std.testing.expect(result.isObject());
        try std.testing.expectEqual(published, result.asObj());
    }
}

test "import.meta slot retries cleanly after allocation failure" {
    var slot = ImportMetaSlot{};
    var machine: Interpreter = undefined;
    var no_memory: [1]u8 = undefined;
    var fixed = std.heap.FixedBufferAllocator.init(&no_memory);
    machine.arena = fixed.allocator();
    machine.gc = null;
    machine.import_meta_slot = &slot;
    machine.import_meta_obj = null;

    try std.testing.expectError(error.OutOfMemory, machine.importMetaValue());
    try std.testing.expect(slot.load() == null);

    machine.arena = std.testing.allocator;
    const retried = try machine.importMetaValue();
    const published = slot.load() orelse return error.TestUnexpectedResult;
    defer std.testing.allocator.destroy(published);
    try std.testing.expectEqual(published, retried.asObj());
}

/// Resolve a function's realm global once, when its closure is created. The
/// ambient interpreter may currently be entered from another realm (notably
/// through that realm's `Function` constructor), so the owned environment
/// identity is authoritative. Minimal hosts can supply the explicit fallback.
pub fn functionRealmGlobal(env: *Environment, fallback: ?*value.Object) ?*value.Object {
    var current: ?*Environment = env;
    while (current) |scope| {
        if (scope.bindingRecord().realm_global) |global| return global;
        current = scope.parent;
    }
    if (fallback) |global| return global;
    if (env.get("globalThis")) |global| if (global.isObject()) return global.asObj();
    return null;
}

pub fn vmChunkAllowsInlineCalls(chunk: *const bc.Chunk) bool {
    for (chunk.code.items) |inst| switch (inst.op) {
        .tail_call, .tail_call_eval, .tail_call_eval_with_this, .tail_call_method, .tail_call_with_this, .tail_call_spread, .tail_call_with_this_spread => return false,
        else => {},
    };
    return true;
}

test "VM spread tail calls retain trampoline-owned activation replacement" {
    for ([_]bc.Op{ .tail_call_spread, .tail_call_with_this_spread }) |op| {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        var chunk = bc.Chunk.init(arena.allocator());
        _ = try chunk.emit(op, 0);
        try std.testing.expect(!vmChunkAllowsInlineCalls(&chunk));
    }

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var ordinary = bc.Chunk.init(arena.allocator());
    _ = try ordinary.emit(.call_spread, 0);
    try std.testing.expect(vmChunkAllowsInlineCalls(&ordinary));
}

/// Test-harness execution contract. `required` never counts a tree-walker
/// fallback as VM coverage; `tree_walker` suppresses bytecode for plain
/// synchronous functions while retaining generator/async suspend machinery.
pub const BytecodeExecutionMode = enum {
    automatic,
    tree_walker,
    required,
};

/// Stable runtime admission outcomes. These names are profiling schema: append
/// new reasons instead of renaming an existing one without a versioned migration.
pub const BytecodeAdmissionReason = enum(u8) {
    synthetic,
    program_compiled,
    program_debugger,
    program_source_policy,
    program_invalid_root,
    program_unsupported_lowering,
    plain_compiled,
    plain_policy_debugger,
    plain_policy_method,
    plain_policy_arguments,
    plain_policy_legacy_call_frame,
    plain_policy_dynamic_call,
    plain_policy_not_candidate,
    plain_rejected_generator_or_async,
    plain_rejected_function_scope_disposal,
    plain_rejected_block_nested_function_declaration,
    plain_rejected_lexical_shadowing,
    plain_rejected_temporal_dead_zone,
    plain_rejected_parameter_prologue,
    plain_rejected_unsupported_lowering,
    generator_compiled,
    generator_rejected_expression_body,
    generator_rejected_unsupported_lowering,
    async_compiled,
    async_rejected_async_generator,
    async_rejected_unsupported_lowering,
    template_plain_compiled,
    template_plain_fallback,
    template_generator_compiled,
    template_generator_fallback,
    template_async_compiled,
    template_async_fallback,
    program_policy_lexical_declaration,
    program_policy_catch,
    program_policy_switch,
    program_policy_label,
    program_policy_arguments_function,
    program_policy_legacy_caller,
    program_policy_legacy_arguments,
    program_policy_nested_function_declaration,
    template_plain_rejected_parameter_prologue,
    template_plain_rejected_unsupported_lowering,
    program_forced_tree_walker,
    plain_forced_tree_walker,
    plain_policy_class_constructor_semantics,
};

pub const bytecode_admission_reason_count = std.meta.fieldNames(BytecodeAdmissionReason).len;

pub const BytecodeAdmissionSnapshot = struct {
    counts: [bytecode_admission_reason_count]u64,

    pub fn count(self: *const BytecodeAdmissionSnapshot, reason: BytecodeAdmissionReason) u64 {
        return self.counts[@backingInt(reason)];
    }
};

/// Context-owned and safe for shared-realm no-GIL function creation. Recording
/// is monotonic profiling state and never changes an execution decision.
pub const BytecodeAdmissionInventory = struct {
    counts: [bytecode_admission_reason_count]std.atomic.Value(u64) = @splat(.init(0)),

    pub fn record(self: *BytecodeAdmissionInventory, reason: BytecodeAdmissionReason) void {
        _ = self.counts[@backingInt(reason)].fetchAdd(1, .monotonic);
    }

    pub fn snapshot(self: *const BytecodeAdmissionInventory) BytecodeAdmissionSnapshot {
        var result: BytecodeAdmissionSnapshot = undefined;
        for (&self.counts, 0..) |*count, index| result.counts[index] = count.load(.monotonic);
        return result;
    }
};

/// Opt-in execution attribution for benchmarks and causal profiles. These are
/// activation/dispatch counters rather than timings: ordinary contexts keep
/// the inventory pointer null so scored paths pay only the predictable null
/// check.
pub const ExecutionTierMetric = enum(u8) {
    tree_walker_entries,
    vm_entries,
    vm_dispatches,
    vm_quick_kernel_hits,
    baseline_entries,
    optimizer_entries,
    optimizer_osr_entries,
    deoptimizations,
    runtime_operation_calls,
    host_callbacks,
    wasm_dispatches,
    environment_allocations,
};

pub const execution_tier_metric_count = std.meta.fieldNames(ExecutionTierMetric).len;

pub const ExecutionTierSnapshot = struct {
    counts: [execution_tier_metric_count]u64,

    pub fn count(self: *const ExecutionTierSnapshot, metric: ExecutionTierMetric) u64 {
        return self.counts[@backingInt(metric)];
    }
};

pub const QuickBinaryMetric = enum(u8) {
    number_hits,
    number_misses,
    dequickenings,
};

pub const quick_binary_metric_count = std.meta.fieldNames(QuickBinaryMetric).len;

pub const QuickBinarySnapshot = struct {
    counts: [quick_binary_metric_count]u64,

    pub fn count(self: *const QuickBinarySnapshot, metric: QuickBinaryMetric) u64 {
        return self.counts[@backingInt(metric)];
    }
};

pub const TierTimingSnapshot = struct {
    baseline_attempts: u64 = 0,
    baseline_tier_ups: u64 = 0,
    baseline_tier_up_ns: u64 = 0,
    baseline_tier_up_ns_max: u64 = 0,
    baseline_failures: u64 = 0,
    baseline_failure_ns: u64 = 0,
    baseline_failure_ns_max: u64 = 0,
    optimizer_attempts: u64 = 0,
    optimizer_tier_ups: u64 = 0,
    optimizer_tier_up_ns: u64 = 0,
    optimizer_tier_up_ns_max: u64 = 0,
    optimizer_failures: u64 = 0,
    optimizer_failure_ns: u64 = 0,
    optimizer_failure_ns_max: u64 = 0,
    deoptimizations: u64 = 0,
    deoptimization_ns: u64 = 0,
    deoptimization_ns_max: u64 = 0,
};

/// Context-owned and race-safe for shared-realm attribution runs. Recording is
/// monotonic observational state and never changes an execution decision.
pub const ExecutionTierInventory = struct {
    counts: [execution_tier_metric_count]std.atomic.Value(u64) = @splat(.init(0)),
    quick_binary: [quick_binary_metric_count]std.atomic.Value(u64) = @splat(.init(0)),
    timing: AtomicTierTiming = .{},

    const AtomicTierTiming = struct {
        baseline_attempts: std.atomic.Value(u64) = .init(0),
        baseline_tier_ups: std.atomic.Value(u64) = .init(0),
        baseline_tier_up_ns: std.atomic.Value(u64) = .init(0),
        baseline_tier_up_ns_max: std.atomic.Value(u64) = .init(0),
        baseline_failures: std.atomic.Value(u64) = .init(0),
        baseline_failure_ns: std.atomic.Value(u64) = .init(0),
        baseline_failure_ns_max: std.atomic.Value(u64) = .init(0),
        optimizer_attempts: std.atomic.Value(u64) = .init(0),
        optimizer_tier_ups: std.atomic.Value(u64) = .init(0),
        optimizer_tier_up_ns: std.atomic.Value(u64) = .init(0),
        optimizer_tier_up_ns_max: std.atomic.Value(u64) = .init(0),
        optimizer_failures: std.atomic.Value(u64) = .init(0),
        optimizer_failure_ns: std.atomic.Value(u64) = .init(0),
        optimizer_failure_ns_max: std.atomic.Value(u64) = .init(0),
        deoptimizations: std.atomic.Value(u64) = .init(0),
        deoptimization_ns: std.atomic.Value(u64) = .init(0),
        deoptimization_ns_max: std.atomic.Value(u64) = .init(0),
    };

    fn recordMax(counter: *std.atomic.Value(u64), sample: u64) void {
        var observed = counter.load(.monotonic);
        while (sample > observed) {
            observed = counter.cmpxchgWeak(observed, sample, .monotonic, .monotonic) orelse break;
        }
    }

    pub fn record(self: *ExecutionTierInventory, metric: ExecutionTierMetric) void {
        _ = self.counts[@backingInt(metric)].fetchAdd(1, .monotonic);
    }

    pub fn recordMany(self: *ExecutionTierInventory, metric: ExecutionTierMetric, count: u64) void {
        _ = self.counts[@backingInt(metric)].fetchAdd(count, .monotonic);
    }

    pub fn recordQuickBinary(self: *ExecutionTierInventory, metric: QuickBinaryMetric) void {
        _ = self.quick_binary[@backingInt(metric)].fetchAdd(1, .monotonic);
    }

    pub fn recordBaselineTierUp(self: *ExecutionTierInventory, elapsed_ns: u64, succeeded: bool) void {
        _ = self.timing.baseline_attempts.fetchAdd(1, .monotonic);
        if (succeeded) {
            _ = self.timing.baseline_tier_ups.fetchAdd(1, .monotonic);
            _ = self.timing.baseline_tier_up_ns.fetchAdd(elapsed_ns, .monotonic);
            recordMax(&self.timing.baseline_tier_up_ns_max, elapsed_ns);
        } else {
            _ = self.timing.baseline_failures.fetchAdd(1, .monotonic);
            _ = self.timing.baseline_failure_ns.fetchAdd(elapsed_ns, .monotonic);
            recordMax(&self.timing.baseline_failure_ns_max, elapsed_ns);
        }
    }

    pub fn recordOptimizerTierUp(self: *ExecutionTierInventory, elapsed_ns: u64, succeeded: bool) void {
        _ = self.timing.optimizer_attempts.fetchAdd(1, .monotonic);
        if (succeeded) {
            _ = self.timing.optimizer_tier_ups.fetchAdd(1, .monotonic);
            _ = self.timing.optimizer_tier_up_ns.fetchAdd(elapsed_ns, .monotonic);
            recordMax(&self.timing.optimizer_tier_up_ns_max, elapsed_ns);
        } else {
            _ = self.timing.optimizer_failures.fetchAdd(1, .monotonic);
            _ = self.timing.optimizer_failure_ns.fetchAdd(elapsed_ns, .monotonic);
            recordMax(&self.timing.optimizer_failure_ns_max, elapsed_ns);
        }
    }

    pub fn recordDeoptimization(self: *ExecutionTierInventory, elapsed_ns: u64) void {
        self.record(.deoptimizations);
        _ = self.timing.deoptimizations.fetchAdd(1, .monotonic);
        _ = self.timing.deoptimization_ns.fetchAdd(elapsed_ns, .monotonic);
        recordMax(&self.timing.deoptimization_ns_max, elapsed_ns);
    }

    pub fn snapshot(self: *const ExecutionTierInventory) ExecutionTierSnapshot {
        var result: ExecutionTierSnapshot = undefined;
        for (&self.counts, 0..) |*count, index| result.counts[index] = count.load(.monotonic);
        return result;
    }

    pub fn quickBinarySnapshot(self: *const ExecutionTierInventory) QuickBinarySnapshot {
        var result: QuickBinarySnapshot = undefined;
        for (&self.quick_binary, 0..) |*count, index| result.counts[index] = count.load(.monotonic);
        return result;
    }

    pub fn timingSnapshot(self: *const ExecutionTierInventory) TierTimingSnapshot {
        var result: TierTimingSnapshot = .{};
        inline for (comptime std.meta.fieldNames(TierTimingSnapshot)) |name|
            @field(result, name) = @field(self.timing, name).load(.monotonic);
        return result;
    }
};

pub fn programRejectionAdmission(reason: Compiler.ProgramRejection) BytecodeAdmissionReason {
    return switch (reason) {
        .invalid_root => .program_invalid_root,
        .unsupported_lowering => .program_unsupported_lowering,
    };
}

fn plainRejectionAdmission(reason: Compiler.PlainFunctionRejection) BytecodeAdmissionReason {
    return switch (reason) {
        .generator_or_async => .plain_rejected_generator_or_async,
        .function_scope_disposal => .plain_rejected_function_scope_disposal,
        .block_nested_function_declaration => .plain_rejected_block_nested_function_declaration,
        .lexical_shadowing => .plain_rejected_lexical_shadowing,
        .temporal_dead_zone => .plain_rejected_temporal_dead_zone,
        .parameter_prologue => .plain_rejected_parameter_prologue,
        .unsupported_lowering => .plain_rejected_unsupported_lowering,
    };
}

fn generatorRejectionAdmission(reason: Compiler.GeneratorRejection) BytecodeAdmissionReason {
    return switch (reason) {
        .expression_body => .generator_rejected_expression_body,
        .unsupported_lowering => .generator_rejected_unsupported_lowering,
    };
}

fn asyncRejectionAdmission(reason: Compiler.AsyncRejection) BytecodeAdmissionReason {
    return switch (reason) {
        .async_generator => .async_rejected_async_generator,
        .unsupported_lowering => .async_rejected_unsupported_lowering,
    };
}

const TreeTailCall = struct {
    callee: Value,
    args: []const Value,
};

/// A JS-defined function value: parameter names, body AST, and the environment
/// captured at definition (the closure). Stored type-erased on `Object.jsFunction()`.
pub const Function = struct {
    params: []const ast.Param,
    body: *ast.Node,
    is_expr_body: bool,
    is_arrow: bool = false,
    /// Whether a call must materialize the `arguments` object (see
    /// `ast.FunctionNode.uses_arguments`). Defaults true so a closure built
    /// without a source-derived flag (e.g. VM templates) stays correct.
    uses_arguments: bool = true,
    /// A syntactic direct-eval call in this ordinary-function scope. It may
    /// resolve `arguments` dynamically even when the parsed body has no explicit
    /// reference. Frame-mode admission requires an exact activation binding
    /// plan and stays causally barred for incomplete environment contexts.
    uses_direct_eval: bool = false,
    closure: *Environment,
    /// The function's [[Realm]] global object, captured when the function is
    /// created. Sloppy `this` substitution and realm-sensitive operations must
    /// use this stable identity rather than repeatedly resolving the writable
    /// `globalThis` property through the closure environment.
    realm_global: ?*value.Object = null,
    name: []const u8 = "",
    /// Fixed source location captured when the function value is created.
    /// Sampling positions advance through the body independently.
    definition_location: ?DebugStatementLocation = null,
    /// Exact source text of the function definition, for `Function.prototype.
    /// toString`. Empty when the parser didn't capture it (then toString falls
    /// back to native-function syntax).
    source: []const u8 = "",
    /// Exact bytecode admission decision retained on the function for causal
    /// profiles. `.synthetic` is reserved for host/test-created Function cells.
    bytecode_admission_reason: BytecodeAdmissionReason = .synthetic,
    /// Tier contract active when this function's source was evaluated. A
    /// conformance runner may install automatic host helpers before evaluating
    /// required corpus code; later calls must preserve each function's own
    /// provenance rather than inherit the caller's current harness mode.
    bytecode_execution_mode: BytecodeExecutionMode = .automatic,
    /// Compiled body for the bytecode VM. Set by `makeFunction` (and the VM's
    /// `make_closure`) via `compilePlainFunction` when a plain function's body
    /// lowers to bytecode — see `plainFunctionPolicyRejection` — so tree-walk-
    /// created closures tier onto the VM too. Null when the body uses syntax the
    /// compiler does not lower yet, in which case the function is invoked via the
    /// tree-walker (`callFunction`). Generators/async use `gen_chunk`/`async_chunk`.
    chunk: ?*bc.Chunk = null,
    /// True when a plain VM chunk can execute through the bounded native-stack
    /// call fast path. Chunks containing a tail-call opcode must stay entirely
    /// under the heap activation driver because those opcodes yield a pending
    /// activation directly to that driver.
    vm_inline_calls_safe: bool = false,
    /// VM closure capture: the defining function's frame (type-erased `*vm.Frame`),
    /// for resolving upvalues. Null at the top level. The slot count to allocate
    /// for this function's own frame.
    frame: ?*anyopaque = null,
    local_count: u32 = 0,
    /// Class method support: the object on which this method/constructor lives
    /// (its [[HomeObject]]); `super.x` resolves on `home_object.protoAtomic()`.
    home_object: ?*value.Object = null,
    /// For a derived class constructor: the superclass object, called by `super(...)`.
    super_ctor: ?*value.Object = null,
    /// The derived constructor whose lexical environment an arrow shares. This
    /// keeps GetSuperConstructor live: `super()` reads that constructor object's
    /// current [[Prototype]] at call time instead of a frozen superclass pointer.
    derived_constructor: ?*value.Object = null,
    /// The declaring class evaluation's private-name map (`#x` → its unique storage
    /// key). A direct eval inside this function's body resolves the private names it
    /// references through this map (`getWithEval(){ return eval("this.#x") }`).
    /// Null for non-class functions; arrows inherit the enclosing one at call time.
    private_map: ?*const std.StringHashMapUnmanaged([]const u8) = null,
    /// Arrow functions capture `this` lexically at creation (like `home_object`
    /// and `super_ctor`); every call uses this captured value and ignores any
    /// provided `this` (a `.call`/`.apply`/`.bind` thisArg, or the receiver of a
    /// method/bare call). Only meaningful when `is_arrow` is set.
    arrow_this: Value = Value.undef(),
    /// Arrow functions also capture `new.target` lexically at creation: an arrow
    /// has no own new.target, so every call resolves it to the value that was in
    /// effect where the arrow was defined — F's new.target if defined inside a
    /// `new F()` activation, even when the arrow is called later. Only meaningful
    /// when `is_arrow` is set.
    arrow_new_target: Value = Value.undef(),
    /// A direct eval inside an arrow inherits whether `new.target` is
    /// syntactically allowed from the arrow's defining context. The captured
    /// value may be undefined, so this is separate from `arrow_new_target`.
    arrow_direct_eval_new_target_allowed: bool = false,
    // Whether this arrow is lexically inside a derived constructor — so `super()`
    // is legal in it (captured at creation; an arrow's super()-validity is
    // lexical, not the dynamic caller's, e.g. an arrow invoked by an iterator's
    // `return()` during the constructor's IteratorClose).
    arrow_in_derived_ctor: bool = false,
    /// For an arrow defined lexically inside a derived constructor: a pointer to
    /// that ctor activation's shared `this` cell, so the arrow's `super()` /
    /// `this` reads target the enclosing ctor's binding. Null for non-arrows and
    /// for arrows not inside a derived ctor. Captured at creation.
    this_cell: ?*ThisCell = null,
    /// Class constructors have [[FunctionKind]] "classConstructor": they cannot
    /// be called without [[Construct]], and derived constructors must initialize
    /// `this` through `super()` before completing normally.
    is_class_constructor: bool = false,
    is_derived_constructor: bool = false,
    // A synthesized default derived constructor (`constructor(...args){ super(...args) }`):
    // it forwards its arguments to the super constructor DIRECTLY, without the
    // observable @@iterator of a real spread.
    is_default_ctor: bool = false,
    /// True when this (arrow) function was created lexically inside a class field
    /// initializer / static block. The field-initializer eval restrictions
    /// (`new.target` ⇒ undefined; a direct eval may not reference `arguments` or
    /// call `super()`) are lexical, so an arrow defined there carries the context
    /// even when invoked later (`x = () => eval('arguments')`). Only meaningful for
    /// arrows; a non-arrow call always resets the field-initializer context.
    field_init_ctx: bool = false,
    /// A derived class constructor's instance field initializers, run when
    /// `super()` returns (not at the start of the body). Empty for a base class,
    /// whose field initializers are prepended to the body and run at its start.
    field_inits: []const *ast.Node = &.{},
    /// The private instance member names (fields/methods/accessors) this class's
    /// constructor brands each instance with: a base class at the start of the
    /// constructor, a derived class when `super()` returns.
    private_brand_names: []const []const u8 = &.{},
    /// `function*`: calling this returns a generator object instead of running
    /// the body. `gen_chunk` is the body compiled for the suspendable VM (null if
    /// the body falls outside the VM's lowered subset — then calling it throws).
    is_generator: bool = false,
    gen_chunk: ?*bc.Chunk = null,
    /// Back-pointer to the object wrapping this function, set at creation. Lets
    /// `makeGenerator` read the function's (lazily-materialized) `.prototype`
    /// property to use as the new generator instance's [[Prototype]].
    obj: ?*value.Object = null,
    /// `async function` / `async () => …` (and, with `is_generator`, an async
    /// generator). The Promise + microtask runtime is not yet implemented, so
    /// *calling* an async function throws; it parses and binds like any other
    /// function (a never-called async function is fully valid).
    is_async: bool = false,
    /// A plain async function's body compiled for the suspendable VM, where
    /// `await` is a suspend point driven by promise settlement (null if the body
    /// falls outside the VM's lowered subset → the tree-walker handles it).
    async_chunk: ?*bc.Chunk = null,
    /// Strict-mode function (see `ast.FunctionNode.is_strict`). Gates sloppy-only
    /// behaviors — currently `this`-substitution on a null/undefined receiver.
    is_strict: bool = false,
    /// Whether this function's statement tree can contain an Annex B B.3.3
    /// block-function candidate. Computed once at function creation; synthetic
    /// functions default conservative. A false value skips the otherwise
    /// invocation-local maps and parameter-name stack entirely.
    annex_b_possible: bool = true,
    /// A concise method (object/class method, get/set) — has no [[Construct]], so
    /// it is not a constructor (e.g. `%TypedArray%.from.call(method)` is a TypeError).
    is_method: bool = false,
    /// The module-local `import.meta` cell captured at function creation. Null in
    /// Script code, where `import.meta` is a syntax error.
    import_meta_slot: ?*ImportMetaSlot = null,
    /// The module path captured at function creation. Dynamic `import()` uses
    /// the lexical referrer, including after an async function resumes from an
    /// `await`, rather than the caller's ambient module.
    module_referrer: []const u8 = "",
    /// The `with`-scope chain captured at definition (object environment records
    /// enclosing the function). A function called from inside a `with` does NOT
    /// see the caller's `with` object — only the ones lexically enclosing its own
    /// definition — so the call restores this snapshot for the duration.
    with_stack: []*value.Object = &.{},
};

const LegacyCallFrame = struct {
    func_obj: *value.Object,
    arguments: ?Value = null,
    caller: ?*LegacyCallFrame = null,
    // For a non-strict function that does NOT reference `arguments`, the exotic
    // object is built lazily — only if the legacy `fn.arguments` property is ever
    // read (rare). These hold what `createArgumentsObject` needs; valid for the
    // call's duration (the frame is popped when the call returns).
    lazy_func: ?*Function = null,
    lazy_args: []const Value = &.{},
    lazy_env: ?*Environment = null,
};

/// Non-local control flow the tree-walker propagates up the statement list:
/// `ret` unwinds to the enclosing function, `brk`/`cont` to the enclosing loop.
const Signal = enum { none, ret, brk, cont };

/// Legacy static RegExp match state (Annex B 22.2.4.x). All slices are owned by
/// the interpreter arena; the empty string is the initial/no-match value.
const RegExpLegacy = struct {
    input: []const u8 = "",
    last_match: []const u8 = "",
    last_paren: []const u8 = "",
    left_context: []const u8 = "",
    right_context: []const u8 = "",
    groups: [9][]const u8 = .{ "", "", "", "", "", "", "", "", "" },
};

pub const InheritedPropertyObservation = struct {
    receiver_shape: ?*Shape,
    holder_shape: *Shape,
    slot: u32,
};

/// Tree-walking evaluator. Evaluating a program/block returns the completion
/// value of the last statement, which is what `JSEvaluateScript` hands back.
pub const Interpreter = struct {
    arena: std.mem.Allocator,
    /// Context-owned freeable backing for invocation-local indexes whose keys
    /// and results are owned elsewhere. Standalone interpreters fall back to
    /// their arena lifetime.
    scratch_allocator: ?std.mem.Allocator = null,
    env: *Environment,
    /// Context-owned registry for immutable native code. Null in standalone
    /// interpreter helpers and agent realms, which remain bytecode-only.
    jit_owner: ?*jit.Owner = null,
    /// Outermost `vm.run` holds one executable-owner lease; nested calls reuse
    /// it so hot native calls do not pay an atomic pair per invocation.
    jit_execution_depth: usize = 0,
    jit_execution_allowed: bool = false,
    /// Epoch token captured by the outer executable-owner lease. A native
    /// pointer is loaded and entered only while this remains the owner's
    /// current epoch; an invalidated outer execution stays bytecode-only.
    jit_execution_epoch: usize = 0,
    /// Parallel-realm heap mutations conservatively fire the Context's Class-A
    /// invalidation bridge once native code has published heap assumptions.
    jit_invalidation_ctx: ?*anyopaque = null,
    jit_invalidation_fn: ?*const fn (*anyopaque, *Interpreter, usize) void = null,
    /// Prefer a whole-activation baseline artifact over compiling the same
    /// managed loop into a slower generic optimizer region. Unit-test
    /// interpreters default this off so optimizer-specific tests exercise that
    /// tier; the production-policy test opts in explicitly.
    prefer_managed_baseline: bool = !builtin.is_test,
    /// Optional statement-boundary debugger hook. When installed by a Context,
    /// execution is deliberately kept on the tree walker so every tier observes
    /// the same source locations and pause semantics.
    debug_statement_ctx: ?*anyopaque = null,
    debug_statement_hook: ?DebugStatementHook = null,
    host_statement_ctx: ?*anyopaque = null,
    host_statement_hook: ?HostStatementHook = null,
    profile_statement_ctx: ?*anyopaque = null,
    profile_statement_hook: ?ProfileStatementHook = null,
    /// Realm-owned monotonic admission counts. Atomic because no-GIL workers
    /// can create functions concurrently in one Context.
    bytecode_admission_inventory: ?*BytecodeAdmissionInventory = null,
    /// Null unless a benchmark/profile explicitly requests attribution.
    execution_tier_inventory: ?*ExecutionTierInventory = null,
    /// Test-only differential switch. Production Contexts always leave
    /// instruction-local binary quickening enabled.
    bytecode_binary_quickening: bool = true,
    /// Test-only forced tier contract inherited from the Context. Production
    /// contexts always use `automatic`.
    bytecode_execution_mode: BytecodeExecutionMode = .automatic,
    debug_statement_locations: ?*std.AutoHashMapUnmanaged(*const Node, DebugStatementLocation) = null,
    /// Non-null only for a no-GIL shared realm. Script publication mutates one
    /// Context-owned registry while every interpreter reads it at statement
    /// boundaries, so those map operations need a lock independent of object
    /// and GC locks. Single-threaded/GIL contexts keep the null fast path.
    debug_registry_lock: ?*DebugRegistryLock = null,
    /// Realm-owned attribution sink, installed only when execution-tier
    /// profiling is explicitly enabled.
    debug_registry_stats: ?*DebugRegistryStats = null,
    /// Registered locations never change for an AST node. Copy them into this
    /// interpreter-local four-way cache after one synchronized registry lookup
    /// so hot loops in a shared realm do not contend on the registry at every
    /// ordinary statement boundary. Both positive and negative lookups are
    /// immutable once an AST is published, so non-statement nodes are cached as
    /// well. Total capacity remains fixed at 64 entries;
    /// adversarial source can cause bounded misses but cannot grow storage.
    debug_location_cache: [debug_location_cache_set_count][debug_location_cache_way_count]DebugLocationCacheEntry = @splat(@splat(.{})),
    debug_location_cache_next: [debug_location_cache_set_count]u8 = @splat(0),
    debug_location_cache_hits: usize = 0,
    debug_location_cache_misses: usize = 0,
    debug_script_ctx: ?*anyopaque = null,
    debug_script_hook: ?DebugScriptHook = null,
    debug_dynamic_url_override: ?[]const u8 = null,
    debug_dynamic_start_line: usize = 1,
    debug_exception_ctx: ?*anyopaque = null,
    debug_exception_hook: ?DebugExceptionHook = null,
    debug_current_location: ?DebugStatementLocation = null,
    debug_call_frame: ?*DebugCallFrame = null,
    stack_trace_call_frame: ?*StackTraceCallFrame = null,
    debug_top_level_location: ?DebugStatementLocation = null,
    debug_top_level_environment: ?*Environment = null,
    debug_top_level_strict: bool = false,
    debug_exception_origin_notified: bool = false,
    /// The Context-owned microtask queue (Promise reactions). Drained after the
    /// main script in `Context.evaluate` and inline by `await`.
    microtasks: ?*promise.MicrotaskQueue = null,
    /// Realm-owned process next-tick queue. It is deliberately distinct from
    /// PromiseJobs so host checkpoints can drain next ticks first, then
    /// microtasks, and loop when a microtask schedules another next tick.
    next_ticks: ?*promise.MicrotaskQueue = null,
    /// Realm-local HostPromiseRejectionTracker queue. Rejected promises remain
    /// rooted here until the explicit host notification checkpoint consumes or
    /// skips them after a later handler attachment.
    unhandled_rejections: ?*std.ArrayListUnmanaged(*promise.Promise) = null,
    /// Promises first handled after host notification. The explicit host
    /// checkpoint consumes this queue to emit one `rejectionHandled` event.
    handled_rejections: ?*std.ArrayListUnmanaged(*promise.Promise) = null,
    /// True under `parallel_js`: serialize content mutation of whichever
    /// microtask queue this interpreter is currently targeting. The lock lives
    /// on the queue itself so independent spawned-thread queues do not contend
    /// on a realm-wide lock.
    lock_microtasks: bool = false,
    /// Promise state needs a mutex only when a marker or peer mutator can read
    /// it concurrently. Serialized contexts still enter the trace-sensitive
    /// guard around mutations so allocator recovery cannot observe half-state.
    lock_promise_state: bool = false,
    /// When non-null (only under `parallel_js`), the Context's `realm_lock`,
    /// serializing this interpreter's mutation of the shared realm queues it can
    /// touch off-collector — currently `finalization_cleanup_jobs`, which the
    /// mid-script parallel collector reads under the same lock. Null on the
    /// GIL-serialized path.
    realm_lock: ?*std.atomic.Mutex = null,
    /// Serializes OrdinarySetPrototypeOf's cycle check with its graph update in
    /// no-GIL realms. The prototype relation spans multiple objects, so no
    /// single object's lock can make opposite-direction updates atomic.
    prototype_lock: ?*std.atomic.Mutex = null,
    /// Microtask currently popped from the queue and executing. It is no longer
    /// present in `microtasks`, so GC must trace it separately.
    current_microtask: ?promise.Microtask = null,
    /// Microtasks dequeued as a burst by `drainMicrotasks` but not yet run.
    /// They are no longer present in `microtasks`, so GC must trace them while
    /// callbacks run and may trigger collection.
    current_microtask_batch: []promise.Microtask = &.{},
    /// Run-loop `HoldJob`s currently popped from `Gil.tasks` for a bounded
    /// burst. They are no longer present in the realm task queue, so GC must
    /// trace them separately while callbacks/release promises can run JS and hit
    /// safepoints.
    current_hold_jobs: []const *anyopaque = &.{},
    /// The realm's SharedArrayBuffer storage references (Context-owned, like
    /// `microtasks`; agent realms own their own). Every SAB wrapper created in
    /// this realm tracks one reference here so the realm's teardown releases
    /// it — the arena itself runs no per-object destructors. Null only in
    /// hosts that never touch SABs (then wrappers leak their ref, harmlessly).
    sab_retains: ?*shared_buffer.RetainList = null,
    /// Outstanding `Atomics.waitAsync` promises of this realm (Context-owned,
    /// like `microtasks`). The list's address doubles as the realm's owner
    /// token in the waiter table; `settleAsyncWaiters` resolves entries as
    /// their tickets settle.
    async_waiters: ?*std.ArrayListUnmanaged(AsyncWaiterEntry) = null,
    /// Context-owned, unrefed AbortSignal timer lane. The core interpreter
    /// requests scheduling and polls at host checkpoints; only the owning
    /// Context knows native allocation, finalization, and generation state.
    abort_timeout_ctx: ?*anyopaque = null,
    abort_timeout_schedule: ?*const fn (?*anyopaque, *Interpreter, *value.Object, u64) EvalError!void = null,
    abort_timeout_poll: ?*const fn (?*anyopaque, *Interpreter) EvalError!void = null,
    polling_abort_timeouts: bool = false,
    /// Context-owned finalizer bridge for the independently ref-counted native
    /// FetchHeaders record. Standalone interpreter helpers leave this null;
    /// their arena lifetime deliberately owns the wrapper for the whole run.
    fetch_headers_attach_ctx: ?*anyopaque = null,
    fetch_headers_attach: ?*const fn (?*anyopaque, *value.Object, *fetch_headers.Record) EvalError!void = null,
    /// Context-owned public timer lane. Unlike AbortSignal's deliberately
    /// unrefed ABI record, these hooks implement refed shell event-loop work
    /// and key records by this interpreter's microtask queue (its event loop).
    timer_ctx: ?*anyopaque = null,
    timer_schedule: ?*const fn (?*anyopaque, *Interpreter, Value, []const Value, u64, bool) EvalError!u64 = null,
    timer_cancel: ?*const fn (?*anyopaque, *Interpreter, u64) void = null,
    timer_set_ref: ?*const fn (?*anyopaque, *Interpreter, u64, ?bool) bool = null,
    timer_refresh: ?*const fn (?*anyopaque, *Interpreter, u64) bool = null,
    timer_poll: ?*const fn (?*anyopaque, *Interpreter) EvalError!void = null,
    timer_keepalive: ?*const fn (?*anyopaque, *Interpreter) void = null,
    timer_abandon: ?*const fn (?*anyopaque, *Interpreter) void = null,
    polling_timers: bool = false,
    /// Context-owned FinalizationRegistry cleanup job queue. GC marks records
    /// ready and enqueues registries; this interpreter drains callbacks at host
    /// checkpoints, outside collection.
    finalization_cleanup_jobs: ?*std.ArrayListUnmanaged(*value.Object) = null,
    /// Cooperative termination (a worker's `terminate()`): when set and true,
    /// evaluation throws at the next step checkpoint in either engine (the
    /// tree-walker's `eval` and the VM's dispatch loop both poll it every
    /// 1024 steps).
    stop_flag: ?*const std.atomic.Value(bool) = null,
    /// `JSC::VMTraps::NeedWatchdogCheck` trap word (host-owned, c_api context
    /// group): when set, the next 1024-step checkpoint clears it and re-checks
    /// `watchdog_deadline_ns` on the executing thread — the executing-thread
    /// half of the watchdog, redundant with the host watchdog thread exactly
    /// like JSC's trap bit and `Watchdog` timer. Null = no trap plumbing.
    watchdog_check_flag: ?*std.atomic.Value(bool) = null,
    /// Armed monotonic-nanosecond execution deadline re-checked when the trap
    /// above is consumed. Zero means no time limit (`Watchdog::noTimeLimit`).
    watchdog_deadline_ns: ?*const std.atomic.Value(u64) = null,
    /// `NeedShellTimeoutCheck` is raised only after the shell timer expires.
    /// Consume it once at an execution checkpoint and publish the VM's normal
    /// termination-request word without conflating it with the watchdog bit.
    shell_timeout_check_flag: ?*std.atomic.Value(bool) = null,
    termination_request_flag: ?*std.atomic.Value(bool) = null,
    /// The Context's VM lock when `enable_threads` is on (Phase 6): the step
    /// checkpoints yield it when contended, and blocking operations release
    /// it while parked. Null = no threads, zero cost.
    gil: ?*gil_mod.Gil = null,
    /// Execution-mode selector: false for the shipping no-GIL default, true for
    /// the explicit `.gil = true` serialized fallback. Internal test options can
    /// exercise the same paths but do not expose this as a public API.
    use_thread_gil: bool = true,
    /// Phase 7: the precise-GC heap (type-erased `Context.gc`), or null for the
    /// arena engine. Cell allocation funnels through `gc_mod.allocObject` etc.,
    /// which use this when set. See docs/threads/P7-gc-design.md.
    gc: ?*anyopaque = null,
    /// Owning realm for host operations that use an Interpreter outside the
    /// Context evaluate entry point (for example Worker structured clone).
    /// Type-erased to keep the interpreter module independent of Context.
    gc_realm_context: ?*anyopaque = null,
    /// Per-mutator half of the Environment private-write/collector handshake.
    /// A private write increments before checking the Context trace flag; a
    /// collector publishes that flag before waiting for every active counter to
    /// drain. Sequential consistency closes the two-atomic entry race.
    gc_private_environment_writes: std.atomic.Value(u32) = .init(0),
    gc_environment_trace_active: ?*const std.atomic.Value(bool) = null,
    /// Backing allocator for GC-owned object side data. Null keeps the legacy
    /// arena ownership path; non-null means ArrayBuffer metadata/bytes must be
    /// released by the GC finalizer.
    gc_side_storage: ?std.mem.Allocator = null,
    /// Internal byte accounting for GC-owned non-shared ArrayBuffer slabs.
    gc_array_buffer_bytes_live: ?*usize = null,
    /// Internal entry accounting for GC-owned Promise reaction lists.
    gc_promise_reactions_live: ?*usize = null,
    /// Internal byte accounting for GC-owned Environment binding-name strings.
    gc_environment_name_bytes_live: ?*usize = null,
    /// Context-owned monotonic weak-state bit. Weak constructors set it before
    /// publishing state that requires ephemeron, weak-slot, or after-weak work.
    gc_weak_work: ?*std.atomic.Value(bool) = null,
    /// Context-owned pending collection request set by the JS shell `gc()`
    /// helper. M1 collection is precise and quiescent-only, so the request is
    /// serviced by `Context` at the next safe entry point.
    gc_requested: ?*std.atomic.Value(bool) = null,
    /// Context-owned moving-compaction request. Native optimizer safepoints
    /// use this as their cheap runtime gate without conflating compaction with
    /// the interpreter's exact 1024-step checkpoint semantics.
    gc_moving_requested: ?*std.atomic.Value(bool) = null,
    /// Optional Context callback used by microtask checkpoints to service a
    /// pending shell GC request after a job has unwound but before the next job
    /// runs. The callback owns the full safety policy: no active thread stacks,
    /// no untraced module graph, and no-op when GC is disabled.
    gc_checkpoint_ctx: ?*anyopaque = null,
    gc_checkpoint_fn: ?*const fn (ctx: *anyopaque) void = null,
    gc_recover_allocation_fn: ?*const fn (ctx: *anyopaque) bool = null,
    /// Set by the quota allocator when synchronous collection was refused
    /// inside a trace-sensitive lock. A catchable OOM services it only after
    /// unwinding that lock and while this interpreter's roots remain published.
    gc_deferred_allocation_recovery: ?*std.atomic.Value(bool) = null,
    /// Opaque owning `Context` for the WebAssembly JS API store (issue #141):
    /// wasm natives register and look up context-owned native wasm allocations
    /// through it. Null in isolated interpreter unit helpers — the wasm API
    /// then reports the store unavailable. Mirrors the type-erased
    /// `gc_checkpoint_ctx` back-pointer above.
    wasm_store_ctx: ?*anyopaque = null,
    /// Optional Context callback invoked at the engine step checkpoints
    /// (`(steps & 1023) == 0`) to run a guarded mid-script collection. Set only
    /// when the GC is on; null = zero cost. The callback owns the safety policy
    /// (no other running JS threads; conservative native-stack scan available).
    /// See `stack_scan.zig` and docs/threads/P7-gc-design.md.
    gc_safepoint_ctx: ?*anyopaque = null,
    gc_safepoint_fn: ?*const fn (ctx: *anyopaque, machine: *anyopaque) void = null,
    /// Realm-level exclusive-operation rendezvous. Unlike the ordinary
    /// 1024-step GC checkpoint, this is serviced only at a complete JavaScript
    /// statement (or an explicitly declared native-operation boundary), so an
    /// operation such as unshared WebAssembly.Memory growth cannot detach a
    /// buffer between `memory.buffer` and its consuming TypedArray constructor.
    mutator_stop_request: ?*const std.atomic.Value(u64) = null,
    mutator_stop_ctx: ?*anyopaque = null,
    mutator_stop_fn: ?*const fn (ctx: *anyopaque, machine: *anyopaque) void = null,
    mutator_stop_published_gen: std.atomic.Value(u64) = .init(0),
    /// True only while a specialized VM path services a checkpoint after
    /// materializing every live managed value into registered Exec/frame roots.
    /// The Context may then skip conservative native-stack scanning for that
    /// one private-mutator checkpoint; generic and parallel paths leave it false.
    gc_precise_safepoint: bool = false,
    /// Stronger than `gc_precise_safepoint`: true only when the suspended engine
    /// path can resume after every managed cell moves. Baseline checkpoints and
    /// optimizer loop safepoints own this declaration; specialized Zig quick
    /// paths may be precise for marking while retaining raw helper pointers, so
    /// they must leave it false.
    gc_moving_safepoint: bool = false,
    /// Root-publication generation this interpreter last published for, under the
    /// parallel mid-script collector (issue #1 M3). Written by this interpreter's
    /// own thread (at a safepoint or when parking), read by the collector to know
    /// every peer has published the current generation. Atomic for the cross-thread
    /// read; `0` until the first publish.
    gc_published_gen: std.atomic.Value(u64) = .init(0),
    /// Generator/async activation whose VM state is materialized in `gc_execs`
    /// at the current bytecode safepoint. Type-erased to keep interpreter.zig
    /// from importing vm.zig; the GC binding casts it back on the same thread.
    gc_active_generator: ?*anyopaque = null,
    /// True only while `gc_parked` was published from a checkpoint that also
    /// declared `gc_precise_safepoint` + `gc_moving_safepoint`. A cooperative
    /// moving collector requires this token from every peer; ordinary native
    /// waits remain parked for non-moving tracing but must fail closed for
    /// relocation because their raw stack words cannot be rewritten.
    gc_moving_parked: std.atomic.Value(bool) = .init(false),
    /// True while this interpreter's thread is blocked in native park code
    /// (Thread.join, Atomics.wait, contended Lock/Condition) with no GIL — it is
    /// not running JS, so its roots are frozen. The mid-script parallel collector
    /// then traces it *directly* (safe: frozen) instead of waiting for it to
    /// publish at a safepoint it won't reach. Set by the park sites, read by the
    /// collector. Atomic for the cross-thread read.
    gc_parked: std.atomic.Value(bool) = .init(false),
    /// Serializes the collector's *direct* read of this interpreter's frozen
    /// roots (operand stacks, frame slots, env) against the owner thread waking
    /// from a `gc_parked` wait and resuming mutation. The `gc_parked` flag alone
    /// is a TOCTOU: the collector can observe it `true`, then the owner clears it
    /// and runs — writing frame slots (`store_local`) and the operand stack while
    /// the collector still reads them (the data race behind the red TSan gate).
    /// The owner takes this lock to clear `gc_parked` before it resumes, and the
    /// collector takes it (re-checking `gc_parked` underneath) around the direct
    /// trace, so a parked peer cannot wake and mutate mid-read. Only ever
    /// contended under a parallel mid-script collection; uncontended (a single
    /// predicted `tryLock`) otherwise. See `gc.traceInterpreterRoots` callers.
    gc_root_lock: std.atomic.Mutex = .unlocked,
    /// Active VM `Exec` frames on this interpreter, innermost last. The VM
    /// operand stack is arena-backed (not a GC cell), so its live `Value`s are
    /// invisible to both the precise tracer and a conservative native-stack
    /// scan; registering each running `Exec` lets `gc.zig` trace them precisely
    /// during a mid-script collection. Populated only when the GC is on; the
    /// list itself is gpa-backed and freed on interpreter teardown.
    gc_execs: std.ArrayListUnmanaged(*vm.Exec) = .empty,
    /// Scoped descriptor for the currently executing JIT invocation. Precise
    /// collectors consult it only at a published native safepoint; the map is
    /// selected by the frame's current deopt index and validated before use.
    gc_native_roots: ?jit.ActiveNativeRoots = null,
    /// Active WebAssembly invocation roots. Descriptors live in the native
    /// invocation frames; registration is scoped to the call and the same
    /// safepoint/park rules that protect `gc_execs` protect these slices.
    gc_wasm_roots: std.ArrayListUnmanaged(*value.WasmExecutionRoots) = .empty,
    /// Tree-walker temporaries that must survive calls/checkpoints while they
    /// live only in Zig locals. VM values are covered by `gc_execs`; this stack
    /// covers interpreter paths such as iterator records/results in `for...of`.
    gc_temp_roots: std.ArrayListUnmanaged(Value) = .empty,
    /// Tree-walker identifier References retained across RHS, iterator, getter,
    /// coercion, or argument evaluation. Unlike VM references these do not live
    /// in a registered Exec, so their tagged Environment/Object bases need an
    /// explicit relocatable root stack.
    gc_binding_reference_roots: std.ArrayListUnmanaged(BindingReference) = .empty,
    /// Native Promise helpers retain raw Promise cells rather than their JS
    /// wrapper Values. Keep those pointer slots in a separate relocatable stack
    /// so a JIT safepoint reached through a handler/getter can compact the cell
    /// and the helper resumes from the rewritten address.
    gc_temp_promise_roots: std.ArrayListUnmanaged(*promise.Promise) = .empty,
    /// Default-initialized Object cells reserved by the fixed-shape allocation
    /// loop. A bounded per-interpreter tranche amortizes shared-heap publication
    /// across multiple step checkpoints; tracing this list keeps the unused
    /// suffix alive until later loop entries consume it.
    gc_object_reserve: std.ArrayListUnmanaged(*value.Object) = .empty,
    /// Number of currently running shared-realm Thread workers. Fixed-shape
    /// allocation uses a larger reserve as soon as a worker can overlap its
    /// creator, while creator-only execution stays on checkpoint-sized batches.
    parallel_worker_count: ?*std.atomic.Value(usize) = null,
    /// GC-owned lexical environments that are live for spec cleanup but no
    /// longer reachable through `self.env`'s parent chain, such as a `for` head
    /// environment that keeps `using` resources until loop exit.
    gc_env_roots: std.ArrayListUnmanaged(*Environment) = .empty,
    /// One fully-cleared, uncaptured block Environment retained by this
    /// interpreter. Fresh block identity is observable only through capture;
    /// keeping the empty cell here avoids repeating a GC-cell allocation while
    /// preserving distinct environments for every captured entry. The precise
    /// tracer and relocator treat this optional pointer as an ordinary root.
    reusable_block_env: ?*Environment = null,
    /// One fully-cleared, uncaptured function activation retained by this
    /// interpreter. A completed private activation has no observable identity;
    /// closures and mapped arguments mark it captured before either can escape,
    /// so only the unobservable common path enters this cache. Recursive calls
    /// still allocate distinct live environments. The precise tracer and
    /// relocator treat this optional pointer as an ordinary root.
    reusable_call_env: ?*Environment = null,
    /// AST identity whose static binding layout is retained in
    /// `reusable_call_env`. AST storage is arena-stable and non-moving; matching
    /// it avoids rooting another GC cell merely to identify the cache owner.
    reusable_call_body: ?*const Node = null,
    /// Context-owned serial used to mint per-class private-name storage keys.
    /// Null only in isolated interpreter unit helpers.
    private_name_serial: ?*std.atomic.Value(u64) = null,
    private_name_serial_local: u64 = 0,
    /// Per-interpreter stream for algorithmic-complexity hash seeds. It is
    /// seeded once from the engine's secure provider, so Map/Set construction
    /// and invocation-local native indexes do not request OS entropy per table.
    /// Interpreter ownership makes the stream race-free under shared-realm
    /// parallel execution.
    secure_hash_prng_seeded: bool = false,
    secure_hash_prng: std.Random.DefaultPrng = std.Random.DefaultPrng.init(0),
    /// Host-defined `[[CanBlock]]` policy for this VM. Spawned `$262.agent`
    /// threads override it through their threadlocal agent record.
    main_can_block: bool = true,
    /// The native-function object currently being invoked (set around each
    /// native call), so a native can reach its own `private_data` — used by
    /// Promise executor resolve/reject closures.
    active_native: ?*value.Object = null,
    /// The non-arrow JS function currently being invoked. `super()` needs this
    /// function object's current [[Prototype]] (GetSuperConstructor), which can
    /// be mutated after class definition.
    active_function: ?*value.Object = null,
    /// Active non-arrow JS calls for Annex B `Function.prototype.caller` and
    /// `.arguments`. Direct eval does not push a frame, so those lookups skip eval
    /// frames naturally.
    active_call_frame: ?*LegacyCallFrame = null,
    /// Context-owned buffer the global `print` appends to (the async harness's
    /// `$DONE` reports completion through `print`).
    print_buffer: ?*std.ArrayListUnmanaged(u8) = null,
    /// While binding a destructuring declaration, whether it's a `var` (leaves
    /// hoist to the variable scope) vs `let`/`const` (block-scoped).
    binding_hoisted: bool = false,
    /// While binding a declaration, whether it's `const` (so the bound names are
    /// marked immutable and later assignment throws a TypeError).
    binding_const: bool = false,
    /// One-shot flag: tag the next block env created (the function body) as
    /// `fn_body` (consumed by `evalBlockScope`).
    mark_fn_body: bool = false,
    /// Annex B B.3.3: names of block-nested function declarations in the current
    /// variable scope that are eligible for the legacy var-scoped binding. A
    /// block-level function declaration whose name is in this set also creates/
    /// updates a var-scoped binding when its block is evaluated; one absent from
    /// the set stays purely block-scoped (the "skip" cases). Null in strict code.
    annexb_legacy: ?*SecureStringMembership = null,
    /// The specific function-declaration nodes eligible for the legacy copy.
    /// Names are used to pre-create var bindings; nodes decide whether a
    /// particular same-named declaration updates that binding at runtime.
    annexb_legacy_nodes: ?*std.AutoHashMapUnmanaged(*const Node, void) = null,
    /// One-shot proof for the next function-body statement list. The function's
    /// static AST scan found no Annex B candidate, so evalStatements can skip
    /// building empty invocation-local maps. It is consumed before any nested
    /// eval or call can execute.
    skip_next_annex_b_scan: bool = false,
    /// The formal-parameter names of the current function activation (used by the
    /// Annex B B.3.3 eligibility analysis to exclude parameter-shadowing names).
    cur_func_params: []const ast.Param = &.{},
    cur_func_args_needed: bool = false,
    /// Sentinel object for a `let`/`const` binding in its temporal dead zone
    /// (hoisted into scope but not yet initialized). Reading it throws.
    tdz_marker: ?*value.Object = null,
    /// The context's global object — the value of `globalThis` and of top-level
    /// `this`. Global `var`/function bindings also surface as its properties, so
    /// `this.x`, `"x" in globalThis`, and reflection over the global all work.
    global_object: ?*value.Object = null,
    /// The Context's empty root shape — the origin of every object's shape
    /// transition chain (see shape.zig).
    root_shape: *Shape,
    /// Symbol objects indexed by their encoded property key (`sym_key`), so the
    /// original Symbol can be recovered from a stored key — used by
    /// Object.getOwnPropertySymbols and the Proxy traps (which must hand the
    /// Symbol, not its encoded string, to the handler). Populated whenever a
    /// Symbol is used as a property key (see `keyOf`).
    symbols: std.StringHashMapUnmanaged(*value.Object) = .{},
    /// Dynamic-import support (set by the module driver in context.zig). `cur_module`
    /// is the referrer path; `dyn_import`/`dyn_import_ctx` resolve+load+evaluate a
    /// specifier and write the module namespace into `out`, returning true on
    /// success (false leaves the failure in `self.exception`). Null in plain
    /// script evaluation (where `import(...)` rejects).
    cur_module: []const u8 = "",
    dyn_import_ctx: ?*anyopaque = null,
    dyn_import: ?DynamicImportHook = null,
    /// Deferred-evaluation trigger (set by the module driver): evaluates the
    /// `import defer` module identified by `module` (an opaque `*Context.Module`)
    /// the first time a binding of its deferred namespace is accessed. Idempotent
    /// (the module's own `evaluated` flag makes a re-trigger a no-op).
    defer_trigger_ctx: ?*anyopaque = null,
    defer_trigger: ?*const fn (ctx: *anyopaque, self: *Interpreter, module: *anyopaque) EvalError!void = null,
    /// The active module's `import.meta` cell. Functions capture this at creation
    /// so `import.meta` remains lexical when an exported function is called by a
    /// different module.
    import_meta_slot: ?*ImportMetaSlot = null,
    /// Script fallback for `import.meta` storage. Module code uses
    /// `import_meta_slot`; this keeps the existing root for non-module internals.
    import_meta_obj: ?*value.Object = null,
    /// Legacy static RegExp match state (Annex B): updated after a successful
    /// match, read by `RegExp.input`/`$_`/`lastMatch`/`$&`/`lastParen`/`$+`/
    /// `leftContext`/`$\``/`rightContext`/`$'`/`$1`..`$9`.
    re_legacy: RegExpLegacy = .{},
    /// Matching scratch is interpreter-local even when RegExp objects and their
    /// immutable compiled programs belong to a shared realm. This both avoids
    /// rebuilding the Thompson VM for every `exec` and prevents worker threads
    /// from sharing mutable matcher state.
    regex_matchers: std.AutoHashMapUnmanaged(*regex.Regex, regex.Regex.Matcher) = .empty,
    signal: Signal = .none,
    ret_value: Value = Value.undef(),
    /// The `this` binding for the currently-executing function (undefined at
    /// top level / in plain calls; the receiver in method calls; the new object
    /// in constructor calls).
    this_value: Value = Value.undef(),
    /// Whether the currently-executing code is strict mode (set from the
    /// program's directive prologue and each function's `is_strict`). Gates
    /// strict runtime errors: assignment to an undeclared binding or a
    /// non-writable/​non-extensible property throws instead of silently failing.
    strict: bool = false,
    /// The in-flight thrown value while `error.Throw` propagates. Read by
    /// `catch` and by the Context/C-API boundary.
    exception: Value = Value.undef(),
    /// Optional prebuilt JS exception for Context heap-limit failures. When set,
    /// allocation failures that happen while a JS handler is active can be
    /// reinterpreted as catchable `error.Throw` without allocating a fresh Error
    /// object while the allocator is already at its cap.
    out_of_memory_exception: Value = Value.undef(),
    /// Target label of a pending labeled `break`/`continue` (null = unlabeled).
    signal_label: ?[]const u8 = null,
    /// Consecutive labels enclosing the next labeled item. `labels_consumed`
    /// prevents a nested loop in the labeled iteration's body from inheriting
    /// them while keeping the slice stable for the outer loop's whole run.
    current_labels: std.ArrayListUnmanaged([]const u8) = .empty,
    labels_consumed: usize = 0,
    /// GetTemplateObject's per-realm cache: a tagged template's frozen strings
    /// object is built once per call site (keyed by the template AST node) and
    /// reused on every later evaluation, so `tag`...`` hands the tag the SAME
    /// object each time. A child realm re-parses its source, producing distinct
    /// nodes, so realms never share an entry.
    template_cache: std.AutoHashMapUnmanaged(*const anyopaque, Value) = .empty,
    /// A string literal is one immutable primitive per AST site, not a fresh
    /// allocation on every tree-walker visit. Besides avoiding needless churn,
    /// this lets parallel marking converge while another mutator loops over a
    /// literal. The cache is interpreter-local, arena-backed, and traced as an
    /// interpreter root while the activation is registered with the Context.
    string_literal_cache: std.AutoHashMapUnmanaged(*const Node, Value) = .empty,
    /// [[HomeObject]] of the executing method (for `super.x`) and the superclass
    /// constructor of the executing derived constructor (for `super(...)`).
    home_object: ?*value.Object = null,
    super_ctor: ?*value.Object = null,
    /// Scoped flag for a running derived class constructor. `super()` flips this
    /// from false to true; completion reads it to implement GetThisBinding.
    this_initialized: bool = true,
    /// The shared `this` cell of the derived constructor activation currently in
    /// scope (set on entry to a derived ctor, and inherited by its lexical arrows
    /// via their captured `Function.this_cell`). Null outside a derived ctor. The
    /// cell is the source of truth for the binding across nested calls: `super()`
    /// writes it, the ctor's completion reads it, and every call's epilogue
    /// re-syncs the ambient this-state from it (so an arrow's `super()` invoked
    /// during an intervening ordinary call still initializes the ctor's `this`).
    this_cell: ?*ThisCell = null,
    /// Whether the most recently completed statement list produced an EMPTY
    /// completion (only declarations / empty statements / empty blocks ran), so
    /// the eval/program completion value carries the last non-empty value forward
    /// (UpdateEmpty).
    completion_empty: bool = true,
    /// `new.target`: the constructor of the in-flight `new` call (undefined in a
    /// plain call). Inherited lexically by arrow functions.
    new_target: Value = Value.undef(),
    /// Set only while invoking a syntactic `eval(...)` call. The eval native
    /// uses this to distinguish direct eval from member/indirect eval.
    direct_eval_call: bool = false,
    /// One-shot ordinary-VM activation materializer. The eval native consumes
    /// it only after parsing and inherited early-error checks succeed, so syntax
    /// errors and non-string eval never allocate or publish activation records.
    /// It is cleared before eval code runs; a nested direct eval then naturally
    /// uses the freshly installed Environment chain rather than replaying the
    /// outer bytecode call site's plan.
    direct_eval_environment_hook: ?*const fn (*anyopaque, *Interpreter) EvalError!*Environment = null,
    direct_eval_environment_hook_ctx: ?*anyopaque = null,
    /// A strict tree-walked function return-position call that can reuse the
    /// current activation. Used only for cases the slot VM cannot safely lower
    /// (notably functions whose source contains syntactic `eval`).
    tree_tail_allowed: bool = false,
    tree_tail_call: ?TreeTailCall = null,
    /// Whether the current syntactic function body permits a direct eval to
    /// contain `new.target`. Ordinary functions/methods do; arrows, scripts,
    /// modules, class fields, and indirect eval do not introduce that context.
    direct_eval_new_target_allowed: bool = false,
    /// A derived constructor's instance field initializers, awaiting the `super()`
    /// that runs them. Set when entering the constructor; consumed (and cleared)
    /// by the SuperCall once `this` is initialized.
    pending_field_inits: []const *ast.Node = &.{},
    /// A derived constructor's private brand names, awaiting the `super()` that
    /// brands `this` with them.
    pending_brand_names: []const []const u8 = &.{},
    /// True while a class field initializer (or static block) is executing, so a
    /// direct eval inside it inherits the field-initializer early errors:
    /// `super()` and `arguments` are forbidden (`super.prop` stays legal).
    in_field_initializer: bool = false,
    /// True while a non-arrow function's parameter default expressions are being
    /// evaluated (the parameter scope, which has an `arguments` binding). A direct
    /// eval there may not declare `arguments` — an early error.
    in_param_expr: bool = false,
    /// True while *any* function's parameter default Initializer is being
    /// evaluated (including arrows, unlike `in_param_expr`). A function with
    /// parameter expressions keeps its parameters in an environment distinct from
    /// the body's var environment, so a direct eval in a default that declares a
    /// `var` shadowing a parameter name is a SyntaxError. Reset to false when
    /// entering any function body so a nested call's eval doesn't inherit it.
    in_param_default: bool = false,
    /// True while executing the body of a derived class constructor (extends a
    /// value OR `extends null`), where a `super()` call is syntactically valid.
    /// Arrows and direct eval inherit it (a `super()` reachable through them is
    /// still bound to the enclosing derived constructor); a non-arrow function
    /// resets it. Distinguishes the SyntaxError of `super()` in a disallowed
    /// context (global eval, a method, a base constructor) from the runtime
    /// TypeError of `super()` in an `extends null` constructor.
    in_derived_ctor: bool = false,
    in_default_ctor: bool = false, // executing a synthesized default derived constructor
    /// The private-name map of the class whose method/constructor/static element is
    /// currently executing (see Function.private_map). A direct eval uses it to
    /// rewrite the private names in the eval'd code to the right storage keys.
    current_private_map: ?*const std.StringHashMapUnmanaged([]const u8) = null,
    /// True while executing eval'd code: EvalDeclarationInstantiation creates
    /// new global var/function bindings as *deletable* (configurable), unlike a
    /// script's GlobalDeclarationInstantiation (D = false). Saved/restored
    /// around the eval body.
    eval_decl_deletable: bool = false,
    /// Active `with` scope objects (innermost last); bare identifiers consult
    /// these before the lexical environment.
    with_stack: std.ArrayListUnmanaged(*value.Object) = .empty,
    /// Robustness counters: function call depth and total evaluation steps.
    depth: u32 = 0,
    steps: u64 = 0,
    /// Runaway-guard ceiling for `steps`, per interpreter.
    ///
    /// A step count is only a meaningful runaway proxy for work whose duration
    /// this interpreter controls. A spawned `Thread` spinning on
    /// `Atomics.load(flag)` until a peer signals it accumulates steps at a rate
    /// set by *another* thread, so a lifetime cap there fails a correct program
    /// for running too long — and raising the constant only moves the failure.
    /// Thread lifetime is already bounded by join, termination, and the
    /// wall-clock watchdog, which are the right instruments. `threadMain`
    /// therefore lifts the ceiling for spawned threads and the host entry keeps
    /// it.
    step_budget: u64 = max_steps,
    /// VM call trampoline (see `vm.runDriver`): true while an explicit
    /// activation-stack driver is running, so the `.call` family pushes a new
    /// JS-chunk activation instead of recursing natively — lifting deep JS→JS
    /// recursion off the OS stack. False under `execLoop` (top-level program and
    /// generator/async bodies keep native calls). `pending_activation` carries
    /// the built callee activation from the `.call` opcode up to the driver
    /// (typed `?*vm.Activation`, held opaque to avoid a module cycle).
    driver_active: bool = false,
    pending_activation: ?*anyopaque = null,
    pending_tail_call: bool = false,
    /// Reusable, non-escaped VM call activations. The concrete node type lives
    /// in vm.zig; this stays opaque to avoid an interpreter↔VM module cycle.
    /// Activations whose frames were captured by a closure are never pooled.
    vm_activation_free: ?*anyopaque = null,
    /// Diagnostic counter used by focused VM tests and performance profiles.
    /// It counts backing activation allocations, not calls; a bounded value for
    /// repeated shallow recursion proves that the free list is doing real work.
    vm_activation_allocations: usize = 0,
    /// Bounded native-stack VM call depth. Ordinary shallow calls avoid a
    /// driver round-trip; once the bound is reached, a nested heap activation
    /// driver handles the remainder of the chain. Both fields are interpreter-
    /// local, including in shared-realm worker lanes.
    vm_inline_call_depth: u8 = 0,
    vm_inline_calls_disabled: bool = false,

    /// Bytes in the explicit Promise/next-tick root frontier at a precise
    /// safepoint. Nursery scheduling uses this to amortize a root scan against
    /// at least the same amount of young allocation; a multi-million-job burst
    /// must not retrace its whole tail for every fixed-size nursery refill.
    pub fn preciseJobRootBytes(self: *const Interpreter) usize {
        var jobs = self.current_microtask_batch.len +| @intFromBool(self.current_microtask != null);
        if (self.microtasks) |queue| jobs +|= queue.pendingLen();
        if (self.next_ticks) |queue| jobs +|= queue.pendingLen();
        return jobs *| @sizeOf(promise.Microtask);
    }

    /// Guard a function call against native-stack exhaustion: throw a catchable
    /// `RangeError` when either the logical call-depth limit or the real OS
    /// stack (probed via `stack_scan.nearLimit`) would be exceeded by recursing
    /// one level deeper. The stack probe only runs once a call chain is already
    /// deep (`stack_check_floor`), so the common shallow-call hot path stays a
    /// single compare. The probe matters for large-frame builds (ThreadSanitizer,
    /// deep host callbacks) where the fixed depth limit would otherwise let the
    /// tree-walker's native recursion overflow first — on whichever thread is
    /// recursing, so a deep-recursing peer throws instead of crashing the
    /// process. Each spawned `Thread` registered its stack bounds on entry
    /// (`stack_scan.enter` → `registerThreadBounds`).
    pub inline fn stackGuard(self: *Interpreter) EvalError!void {
        // Shallow-call hot path: a single compare, identical to the old guard.
        // Only once a chain is already deep do we pay the logical-limit check
        // plus the native stack-pointer probe (the latter matters for
        // large-frame builds — TSan, deep host callbacks — where the native
        // stack can overflow before `max_call_depth`).
        if (self.depth < stack_check_floor) return;
        if (self.depth >= max_call_depth or stack_scan.nearLimit(stack_redzone))
            return self.throwUncatchableError("RangeError", "Maximum call stack size exceeded");
        // If the native stack-pointer probe can't see this thread's bounds, it
        // can't catch a real overflow — fall back to the conservative depth cap
        // so an unsupported platform can't run off the end of the stack.
        if (!stack_scan.boundsKnown() and self.depth >= conservative_call_depth)
            return self.throwUncatchableError("RangeError", "Maximum call stack size exceeded");
    }

    // ---- exception helpers ------------------------------------------------

    /// Fire a Class-A stop for a shape-changing named-property mutation of
    /// `obj`, unless no published artifact speculates on its shape (#457).
    /// `obj` must be passed
    /// *before* the store: adding a property transitions the object to a new
    /// shape, while the assumption any optimized code guards on is the one it
    /// still has here. A shapeless receiver uses the optimizer's explicit
    /// empty-receiver token; only a null `obj` keeps the conservative stop.
    pub fn invalidateJitHeapFactsFor(self: *Interpreter, obj: ?*const value.Object) void {
        const owner = self.jit_owner orelse return;
        if (!owner.hasPublishedArtifacts()) return;
        const shape_token = if (obj) |o| token: {
            // Shape transitions publish under `property_lock`. The watchpoint
            // pre-check runs before this mutator's store, but another shared
            // mutator may be transitioning the same object concurrently; read
            // the exact pre-store shape under that same lock rather than racing
            // the writer or consulting a torn/stale pointer.
            o.lockProperties();
            defer o.unlockProperties();
            break :token if (o.shape) |shape|
                @intFromPtr(shape)
            else
                jit.NativePropertyCache.empty_receiver_shape_token;
        } else 0;
        if (!owner.shapeMayInvalidate(shape_token)) return;
        if (self.jit_invalidation_fn) |invalidate|
            invalidate(self.jit_invalidation_ctx.?, self, shape_token);
    }

    /// Mutation site with no object in hand: always conservative.
    pub fn invalidateJitHeapFacts(self: *Interpreter) void {
        self.invalidateJitHeapFactsFor(null);
    }

    pub fn setProp(self: *Interpreter, obj: *value.Object, key: []const u8, v: Value) EvalError!void {
        // Existing data-property writes preserve the receiver's immutable
        // shape/slot pair. Optimized own and inherited reads guard that live
        // shape and load the slot value on every execution, so a value update
        // invalidates no heap fact. Keep Class-A for an absent key: that path
        // transitions the receiver and remains the compile/link watchpoint
        // boundary until #471's per-artifact transition policy replaces it.
        const owner = self.jit_owner;
        if (owner == null or !owner.?.hasPublishedArtifacts()) {
            try obj.setOwn(self.arena, self.root_shape, key, v);
            return;
        }
        if (obj.getOwn(key) == null) self.invalidateJitHeapFactsFor(obj);
        try obj.setOwn(self.arena, self.root_shape, key, v);
    }

    /// Object-literal data initialization is CreateDataProperty: it defines an
    /// own data property even when an earlier duplicate literal entry made the
    /// same key an accessor.
    pub fn defineLiteralDataProp(self: *Interpreter, obj: *value.Object, key: []const u8, v: Value) EvalError!void {
        switch (try obj.defineLiteralDataOwn(self.arena, self.root_shape, key, v)) {
            .absent, .removed_continue, .deleted => {},
            .blocked => return self.throwError("TypeError", "Cannot redefine non-configurable accessor"),
        }
    }

    fn defineOwnDataProp(self: *Interpreter, obj: *value.Object, key: []const u8, v: Value, attr: value.PropAttr) EvalError!void {
        switch (try obj.deleteAccessorOwnPreserveOrder(self.arena, key)) {
            .absent, .removed_continue, .deleted => {},
            .blocked => return self.throwError("TypeError", "Cannot redefine non-configurable accessor"),
        }
        try obj.setOwn(self.arena, self.root_shape, key, v);
        try obj.setAttr(self.arena, key, attr);
    }

    /// Bind `name` in the current scope; at global scope (no enclosing
    /// function), also surface it as an own property of the global object —
    /// global `var`/function declarations are own properties of `globalThis`
    /// ({ writable, enumerable, !configurable }), so `hasOwnProperty(globalThis,
    /// name)` and reflection see them (the test262 async harness relies on this).
    pub fn globalDefine(self: *Interpreter, name: []const u8, v: Value) EvalError!void {
        const vs = self.env.varScope(); // `var`/function declarations hoist here
        const existed_local = vs.hasOwnBinding(name);
        try vs.put(name, v);
        if (vs.parent == null) {
            if (self.global_object) |g| {
                const existed = g.getOwn(name) != null;
                // CanDeclareGlobalVar: a new global var binding requires the global
                // object to be extensible (an existing property may be reused).
                if (!existed and !g.isExtensible())
                    return self.throwError("TypeError", "cannot declare global variable (global object is not extensible)");
                try self.setProp(g, name, v);
                // EvalDeclarationInstantiation makes new global bindings deletable
                // (configurable); a script's GlobalDeclarationInstantiation does not.
                if (!existed) try g.setAttr(self.arena, name, .{ .writable = true, .enumerable = true, .configurable = self.eval_decl_deletable });
            }
        } else if (!existed_local and self.eval_decl_deletable) {
            // A sloppy direct eval's top-level var/function in a *function* variable
            // environment is a fresh deletable binding (no global object backs it).
            try vs.markDeletable(name);
        }
    }

    /// Create a `var`-style binding if declaration instantiation needs one,
    /// without reinitializing an existing global object binding. In the spec, a
    /// Global Environment Record's object binding continues to read/write the
    /// property; in this interpreter, leaving `vars` empty for an existing
    /// global property lets identifier resolution fall through to that property.
    fn createVarBinding(self: *Interpreter, name: []const u8) EvalError!void {
        const vs = self.env.varScope();
        if (vs.hasOwnBinding(name)) return; // param / hoisted function / earlier var
        if (vs.parent == null) {
            if (self.global_object) |g| {
                if (objectHasOwn(g, name)) return;
                if (!g.isExtensible())
                    return self.throwError("TypeError", "cannot declare global variable (global object is not extensible)");
                try vs.put(name, Value.undef());
                try self.setProp(g, name, Value.undef());
                try g.setAttr(self.arena, name, .{ .writable = true, .enumerable = true, .configurable = self.eval_decl_deletable });
                return;
            }
        }
        try vs.put(name, Value.undef());
        if (vs.parent != null and self.eval_decl_deletable)
            try vs.markDeletable(name);
    }

    /// A top-level function declaration (script GlobalDeclarationInstantiation or
    /// eval EvalDeclarationInstantiation). Implements CanDeclareGlobalFunction +
    /// CreateGlobalFunctionBinding: a new/configurable target takes a fresh
    /// `{ writable, enumerable, configurable: D }` descriptor (D = deletable for
    /// eval); a non-configurable existing property must already be a writable,
    /// enumerable data property or the declaration is a TypeError.
    /// CanDeclareGlobalFunction: whether a global function binding `name` may be
    /// (re)declared on the global object `g`.
    fn canDeclareGlobalFunction(g: *value.Object, name: []const u8) bool {
        if (g.getOwn(name) != null or g.getAccessor(name) != null) {
            const a = g.getAttr(name);
            if (a.configurable) return true;
            // A non-configurable existing property is only redefinable as a
            // function if it is a writable, enumerable data property.
            if (g.getAccessor(name) != null or !a.writable or !a.enumerable) return false;
            return true;
        }
        return g.isExtensible();
    }

    /// EvalDeclarationInstantiation does all the CanDeclareGlobalFunction /
    /// CanDeclareGlobalVar checks *before* declaring anything, so a conflict
    /// throws without leaving earlier declarations behind. Run that pre-check when
    /// a (sloppy) eval's variable environment is the global object.
    fn checkGlobalEvalDeclarable(self: *Interpreter, stmts: []const *Node) EvalError!void {
        if (self.env.varScope().parent != null) return; // not declaring to global
        const g = self.global_object orelse return;
        for (stmts) |s| if (s.* == .func_decl) {
            const nm = s.func_decl.name;
            if (nm.len != 0 and !canDeclareGlobalFunction(g, nm))
                return self.throwError("TypeError", "cannot declare global function (existing property is not configurable)");
        };
        if (!g.isExtensible()) {
            var vars: std.ArrayListUnmanaged([]const u8) = .empty;
            try self.collectEvalVarNames(stmts, &vars);
            for (vars.items) |nm| {
                if (g.getOwn(nm) == null and !self.env.varScope().hasOwnBinding(nm))
                    return self.throwError("TypeError", "cannot declare global variable (global object is not extensible)");
            }
        }
    }

    /// EvalDeclarationInstantiation lexical-conflict early error (19.2.1.3 step 5,
    /// sloppy direct eval). Walk the lexical environments from the eval's scope up
    /// to — but not including — the variable environment; a `var` the eval would
    /// introduce that collides with an intervening lexical binding (`let`/`const`/
    /// `class`, a block-scoped function) is a SyntaxError: `let x; eval('var x')`.
    ///
    /// In our model var/function declarations hoist past block and function-body
    /// environments to the nearest `fn_scope`, so those intervening environments
    /// hold only lexical bindings — any name match there is a genuine conflict.
    /// `with` (object) environments use Annex B alternate semantics (var hoists
    /// over them) and are skipped. At the global variable environment, a global
    /// lexical (in the root bindings but not an own global property) still conflicts.
    fn checkEvalLexicalConflicts(self: *Interpreter, stmts: []*Node) EvalError!void {
        var vars: std.ArrayListUnmanaged([]const u8) = .empty;
        try self.collectEvalVarNames(stmts, &vars);
        if (vars.items.len == 0) return;
        const var_env = self.env.varScope();
        // A direct eval inside a parameter default: the parameter environment is
        // distinct from the body's variable environment, so a `var` shadowing a
        // parameter name is a SyntaxError. The parameters live in `var_env` (the
        // parameter scope); `arguments` has its own separate restriction.
        if (self.in_param_default) {
            for (vars.items) |n|
                if (!eq(n, "arguments") and paramsBindName(self.cur_func_params, n))
                    return self.throwError("SyntaxError", "eval cannot var-declare a parameter name in a parameter default");
        }
        var env: *Environment = self.env;
        while (env != var_env) {
            // A simple catch parameter is exempt (Annex B.3.5: a direct eval's
            // `var` may match it); other declarative records are checked.
            const record = env.bindingRecord();
            if (record.with_object == null and !record.is_catch_param) {
                for (vars.items) |n|
                    if (env.hasOwnBinding(n))
                        return self.throwError("SyntaxError", "var declaration in eval conflicts with a lexical binding");
            }
            env = env.parent orelse break;
        }
        if (var_env.parent == null) {
            // Global variable environment: a global lexical lives in the root
            // bindings without a matching own property on the global object.
            const g = self.global_object orelse return;
            for (vars.items) |n|
                if (var_env.hasOwnBinding(n) and !objectHasOwn(g, n))
                    return self.throwError("SyntaxError", "var declaration in eval conflicts with a global lexical binding");
        }
    }

    /// GlobalDeclarationInstantiation early errors (16.1.7 steps 3–12). Run at the
    /// top of a Script's GlobalDeclarationInstantiation, *before* any binding is
    /// created, so a conflict throws SyntaxError without leaving partial state.
    ///
    /// In our model a global `var`/function binding lives in BOTH the root
    /// environment's `vars` and as an own property of the global object, while a
    /// global lexical (`let`/`const`/`class`) lives ONLY in the root `vars`. That
    /// lets us reconstruct the global environment record's predicates:
    ///   HasLexicalDeclaration(n) := root.vars has n AND global has no own n
    ///   HasVarDeclaration(n)     := root.vars has n AND global has own n
    ///   HasRestrictedGlobalProperty(n) := global has own non-configurable n
    fn checkGlobalDeclConflicts(self: *Interpreter, stmts: []*Node) EvalError!void {
        if (self.env.parent != null) return; // only a Script's global scope
        const g = self.global_object orelse return;
        const root = self.env;

        // lexNames: the script's top-level LexicallyDeclaredNames (let/const/class).
        // Each must not collide with an existing var or lexical binding, nor name a
        // restricted (non-configurable) global property.
        var lex_names: std.ArrayListUnmanaged([]const u8) = .empty;
        try self.collectTopLexNames(stmts, &lex_names);
        for (lex_names.items) |n| {
            // HasLexicalDeclaration(n): in root `vars` but not an own global
            // property (a global `var`/function lives in both).
            if (root.hasOwnBinding(n) and !objectHasOwn(g, n))
                return self.throwError("SyntaxError", "redeclaration of global lexical binding");
            // HasRestrictedGlobalProperty(n): an own non-configurable property.
            // (A `var` introduced by non-strict direct eval is configurable, so it
            // is NOT restricted — a later `let` may legally shadow it.)
            if (objectHasOwn(g, n) and !g.getAttr(n).configurable)
                return self.throwError("SyntaxError", "cannot declare restricted global property");
        }

        // declaredVarNames: the script's VarDeclaredNames (nested `var` + top-level
        // function declarations). None may collide with an existing lexical binding.
        var vars: std.ArrayListUnmanaged([]const u8) = .empty;
        try self.collectEvalVarNames(stmts, &vars);
        for (stmts) |s| if (s.* == .func_decl and s.func_decl.name.len > 0)
            try vars.append(self.arena, s.func_decl.name);
        for (vars.items) |n| {
            // HasLexicalDeclaration(n): in root `vars` but not an own global property.
            if (root.hasOwnBinding(n) and !objectHasOwn(g, n))
                return self.throwError("SyntaxError", "var declaration conflicts with global lexical binding");
        }
    }

    /// The top-level (statement-list-level) lexical names of a program: `let`/
    /// `const`/`class` declarations, including those wrapped in a `decl_group` or
    /// `export`. Block-nested lexicals are not part of LexicallyDeclaredNames.
    fn collectTopLexNames(self: *Interpreter, stmts: []const *Node, out: *std.ArrayListUnmanaged([]const u8)) EvalError!void {
        for (stmts) |s| try self.collectTopLexNamesNode(s, out);
    }

    fn collectTopLexNamesNode(self: *Interpreter, node: *Node, out: *std.ArrayListUnmanaged([]const u8)) EvalError!void {
        switch (node.*) {
            .var_decl => |d| if (d.kind != .@"var" and d.name.len > 0) try out.append(self.arena, d.name),
            .destructure_decl => |d| if (d.kind != .@"var") try self.evalPatternVarNames(d.pattern, out),
            .class_expr => |c| if (c.name.len > 0) try out.append(self.arena, c.name),
            .decl_group => |g| for (g) |d2| try self.collectTopLexNamesNode(d2, out),
            .export_decl => |e| if (e.declaration) |d| try self.collectTopLexNamesNode(d, out),
            else => {},
        }
    }

    /// Collect top-level + block-nested `var` names of an eval program (does not
    /// cross function boundaries).
    fn collectEvalVarNames(self: *Interpreter, stmts: []const *Node, out: *std.ArrayListUnmanaged([]const u8)) EvalError!void {
        for (stmts) |s| try self.collectEvalVarNamesNode(s, out);
    }

    fn collectEvalVarNamesNode(self: *Interpreter, node: *Node, out: *std.ArrayListUnmanaged([]const u8)) EvalError!void {
        switch (node.*) {
            .var_decl => |d| if (d.kind == .@"var" and d.name.len > 0) try out.append(self.arena, d.name),
            .destructure_decl => |d| if (d.kind == .@"var") try self.evalPatternVarNames(d.pattern, out),
            .decl_group => |g| for (g) |d2| try self.collectEvalVarNamesNode(d2, out),
            .block => |b| for (b) |s| try self.collectEvalVarNamesNode(s, out),
            .if_stmt => |i| {
                try self.collectEvalVarNamesNode(i.consequent, out);
                if (i.alternate) |a| try self.collectEvalVarNamesNode(a, out);
            },
            .while_stmt => |w| try self.collectEvalVarNamesNode(w.body, out),
            .do_while_stmt => |w| try self.collectEvalVarNamesNode(w.body, out),
            .for_stmt => |f| {
                if (f.init) |ini| try self.collectEvalVarNamesNode(ini, out);
                try self.collectEvalVarNamesNode(f.body, out);
            },
            .for_in => |f| {
                if (f.decl_kind) |k| if (k == .@"var") try self.evalPatternVarNames(f.target, out);
                try self.collectEvalVarNamesNode(f.body, out);
            },
            .labeled_stmt => |l| try self.collectEvalVarNamesNode(l.body, out),
            .try_stmt => |t| {
                try self.collectEvalVarNamesNode(t.block, out);
                if (t.catch_block) |c| try self.collectEvalVarNamesNode(c, out);
                if (t.finally_block) |fb| try self.collectEvalVarNamesNode(fb, out);
            },
            .switch_stmt => |sw| for (sw.cases) |cs| for (cs.body) |s| try self.collectEvalVarNamesNode(s, out),
            else => {},
        }
    }

    fn evalPatternVarNames(self: *Interpreter, node: *Node, out: *std.ArrayListUnmanaged([]const u8)) EvalError!void {
        switch (node.*) {
            .identifier => |n| try out.append(self.arena, n),
            .obj_pattern => |p| {
                for (p.props) |prop| try self.evalPatternVarNames(prop.target, out);
                if (p.rest) |r| if (r.* == .identifier) try out.append(self.arena, r.identifier);
            },
            .arr_pattern => |p| {
                for (p.elems) |elem| if (elem.target) |t| try self.evalPatternVarNames(t, out);
                if (p.rest) |r| try self.evalPatternVarNames(r, out);
            },
            else => {},
        }
    }

    pub fn globalDefineFunc(self: *Interpreter, name: []const u8, v: Value) EvalError!void {
        const vs = self.env.varScope();
        if (vs.parent != null or self.global_object == null) {
            const existed = vs.hasOwnBinding(name);
            try vs.put(name, v);
            // A sloppy direct eval's top-level function declaration in a function
            // variable env is a deletable binding, like its `var` siblings.
            if (!existed and vs.parent != null and self.eval_decl_deletable) try vs.markDeletable(name);
            return;
        }
        const g = self.global_object.?;
        if (g.getOwn(name) != null or g.getAccessor(name) != null) {
            const a = g.getAttr(name);
            if (!a.configurable) {
                // CanDeclareGlobalFunction: a non-configurable property is only
                // redefinable if it is a writable, enumerable *data* property.
                if (g.getAccessor(name) != null or !a.writable or !a.enumerable)
                    return self.throwError("TypeError", "cannot declare global function (existing property is not configurable)");
                try vs.put(name, v);
                try self.setProp(g, name, v); // keep the existing attributes
                return;
            }
        } else if (!g.isExtensible()) {
            return self.throwError("TypeError", "cannot declare global function (global object is not extensible)");
        }
        try vs.put(name, v);
        try self.defineOwnDataProp(g, name, v, .{ .writable = true, .enumerable = true, .configurable = self.eval_decl_deletable });
    }

    /// Create the global var binding for an Annex B B.3.3 legacy block-level
    /// function. Per CreateGlobalVarBinding(F, D), the new property's
    /// deletability D follows the surrounding instantiation: a Script's
    /// GlobalDeclarationInstantiation uses D = false (non-configurable, like an
    /// ordinary global `var`), whereas a direct eval's EvalDeclarationInstantiation
    /// uses D = true. An already-existing property keeps its attributes.
    fn globalDefineDeletable(self: *Interpreter, name: []const u8, v: Value) EvalError!void {
        const vs = self.env.varScope();
        try vs.put(name, v);
        if (vs.parent == null) {
            if (self.global_object) |g| {
                const existed = g.getOwn(name) != null;
                try self.setProp(g, name, v);
                if (!existed) try g.setAttr(self.arena, name, .{ .writable = true, .enumerable = true, .configurable = self.eval_decl_deletable });
            }
        }
    }

    /// The TDZ sentinel as a Value.
    fn tdzVal(self: *Interpreter) Value {
        return Value.obj(self.tdz_marker.?);
    }

    /// Whether `v` is the TDZ sentinel (an uninitialized let/const binding).
    pub fn isTdz(self: *Interpreter, v: Value) bool {
        return v.isObject() and self.tdz_marker != null and v.asObj() == self.tdz_marker.?;
    }

    /// PrivateFieldAdd / PrivateMethodOrAccessorAdd: branding an object that
    /// already carries the private name `name` is a TypeError — reachable when the
    /// same object undergoes instance-element initialization twice (a base that
    /// `return`s an already-constructed instance, so a later `new` re-installs the
    /// derived class's private members on it).
    fn addPrivateBrandChecked(self: *Interpreter, o: *value.Object, name: []const u8) EvalError!void {
        // PrivateFieldAdd / PrivateMethodOrAccessorAdd step 1: a private member
        // cannot be added to a non-extensible object.
        if (!o.isExtensible())
            return self.throwError("TypeError", "Cannot add a private member to a non-extensible object");
        if (o.hasPrivateBrand(name))
            return self.throwError("TypeError", "Cannot initialize a private member twice on the same object");
        try o.addPrivateBrand(self.arena, name);
    }

    pub fn addPrivateMethodOrAccessorChecked(self: *Interpreter, o: *value.Object, home: ?*value.Object, name: []const u8) EvalError!void {
        try self.addPrivateBrandChecked(o, name);
        const h = home orelse return;
        if (h.getAccessor(name)) |acc| {
            try o.setAccessor(self.arena, name, acc.get, acc.set);
            try o.setAttr(self.arena, name, .{ .enumerable = false, .configurable = false });
        } else if (h.getOwn(name)) |v| {
            try o.setOwn(self.arena, self.root_shape, name, v);
            try o.setAttr(self.arena, name, .{ .writable = false, .enumerable = false, .configurable = false });
        }
    }

    pub fn initializePrivateClassField(self: *Interpreter, o: *value.Object, name: []const u8, field_value: Value) EvalError!void {
        try self.addPrivateBrandChecked(o, name);
        try o.setOwn(self.arena, self.root_shape, name, field_value);
        try o.setAttr(self.arena, name, .{ .writable = true, .enumerable = false, .configurable = false });
    }

    pub fn initializePublicClassField(self: *Interpreter, receiver: Value, key: []const u8, field_value: Value) EvalError!void {
        if (!receiver.isObject()) return self.throwError("TypeError", "Class field receiver is not an object");
        const o = receiver.asObj();
        if (o.proxyHandler() != null or o.proxy_revoked or isModuleNs(o)) {
            const desc = (try self.newObject()).asObj();
            try self.setProp(desc, "value", field_value);
            try self.setProp(desc, "writable", Value.boolVal(true));
            try self.setProp(desc, "enumerable", Value.boolVal(true));
            try self.setProp(desc, "configurable", Value.boolVal(true));
            try builtins.defineOne(self, o, key, desc);
            return;
        }
        if (!objectHasOwn(o, key) and !o.isExtensible())
            return self.throwError("TypeError", "Cannot define class field on a non-extensible object");
        try self.setProp(o, key, field_value);
    }

    /// Pre-bind every identifier in a destructuring pattern to the TDZ sentinel.
    fn tdzBindPattern(self: *Interpreter, target: *Node, tdz: Value) void {
        switch (target.*) {
            .identifier => |name| self.env.put(name, tdz) catch {},
            .obj_pattern => |p| {
                for (p.props) |pr| self.tdzBindPattern(pr.target, tdz);
                if (p.rest) |r| if (r.* == .identifier) self.env.put(r.identifier, tdz) catch {}; // a binding object rest is a name
            },
            .arr_pattern => |p| {
                for (p.elems) |e| if (e.target) |t| self.tdzBindPattern(t, tdz);
                if (p.rest) |r| self.tdzBindPattern(r, tdz);
            },
            else => {},
        }
    }

    fn checkRestrictedGlobalLexical(self: *Interpreter, name: []const u8) EvalError!void {
        if (self.env.parent != null) return;
        if (!eq(name, "undefined") and !eq(name, "NaN") and !eq(name, "Infinity")) return;
        const g = self.global_object orelse return;
        if (objectHasOwn(g, name) and !g.getAttr(name).configurable)
            return self.throwError("SyntaxError", "Cannot declare restricted global property");
    }

    fn checkRestrictedGlobalLexicalPattern(self: *Interpreter, target: *Node) EvalError!void {
        switch (target.*) {
            .identifier => |name| try self.checkRestrictedGlobalLexical(name),
            .obj_pattern => |p| {
                for (p.props) |pr| try self.checkRestrictedGlobalLexicalPattern(pr.target);
                if (p.rest) |r| if (r.* == .identifier) try self.checkRestrictedGlobalLexical(r.identifier);
            },
            .arr_pattern => |p| {
                for (p.elems) |e| if (e.target) |t| try self.checkRestrictedGlobalLexicalPattern(t);
                if (p.rest) |r| try self.checkRestrictedGlobalLexicalPattern(r);
            },
            else => {},
        }
    }

    /// An own data property of the global object, used as the fallback for a
    /// bare global reference (`this.x = 1` at top level → bare `x`).
    fn currentGlobalObject(self: *Interpreter) ?*value.Object {
        return functionRealmGlobal(self.env, self.global_object);
    }

    /// A bare global reference's value: a proper [[Get]] on the global object —
    /// invoking an accessor's getter — when `name` is an own property (data or
    /// accessor), else null (the name is unresolved). Mirrors the tree-walker's
    /// identifier global fallback so the VM's `load_var` resolves global
    /// accessor properties, not just data ones.
    pub fn globalProp(self: *Interpreter, name: []const u8) EvalError!?Value {
        const g = self.currentGlobalObject() orelse return null;
        if (try self.hasPropertyResult(g, name))
            return try self.getPropertyWithReceiver(Value.obj(g), name, Value.obj(g));
        return null;
    }

    /// Whether the global object has a binding `name` (own or inherited),
    /// without invoking a getter — the existence test behind strict
    /// "assignment to an undeclared global" and `typeof <unresolved>`.
    pub fn globalHasBinding(self: *Interpreter, name: []const u8) EvalError!bool {
        const g = self.currentGlobalObject() orelse return false;
        return try self.hasPropertyResult(g, name);
    }

    pub fn isDirectEvalCallee(self: *Interpreter, callee: Value) bool {
        if (!callee.isObject()) return false;
        const intrinsic = rootEnv(self.env).get("\x00evalIntrinsic") orelse return false;
        return intrinsic.isObject() and intrinsic.asObj() == callee.asObj();
    }

    fn globalBindingObject(self: *Interpreter, name: []const u8) ?*value.Object {
        const g = self.currentGlobalObject() orelse return null;
        var env: ?*Environment = self.env;
        while (env) |e| {
            if (e.activationBinding(name) != null) return null;
            const record = e.mutableBindingRecord();
            // Read `vars` under the binding lock: a peer thread's put/getOrPut on
            // this scope can rehash it concurrently (no-GIL Environment race,
            // Linux tsan-threadfuzz: globalDefine put vs this contains). Only a
            // proven-private activation may elide this read lock.
            const locked = record.lockBindingsForRead();
            const has = record.vars.contains(name);
            record.unlockBindingsForRead(locked);
            if (has)
                return if (e.parent == null and objectHasOwn(g, name)) g else null;
            env = e.parent;
        }
        return null;
    }

    /// ToObject(v): an ordinary object is returned as-is, a primitive is boxed
    /// into the matching wrapper (whose prototype is that constructor's
    /// `.prototype`), and null/undefined throw a TypeError. BigInt/Symbol are
    /// represented as object-tagged primitives internally, so they still need
    /// fresh wrappers here.
    pub fn toObject(self: *Interpreter, v: Value) EvalError!*value.Object {
        if (v.isObject() and !v.asObj().is_symbol and !v.asObj().is_bigint and
            v.asObj().getterSetterCellData() == null) return v.asObj();
        if (v.isObject() and v.asObj().getterSetterCellData() != null)
            return self.throwError("TypeError", "Cannot convert an internal accessor cell to an object");
        if (v.isNull() or v.isUndefined())
            return self.throwError("TypeError", "Cannot convert undefined or null to object");
        const ctor_name: []const u8 = switch (v.kind()) {
            .string => "String",
            .number => "Number",
            .boolean => "Boolean",
            .object => if (v.asObj().is_symbol) "Symbol" else if (v.asObj().is_bigint) "BigInt" else unreachable,
            else => unreachable,
        };
        const o = try gc_mod.allocObj(self.arena);
        o.* = .{};
        try o.setBoxedPrimitive(self.arena, v);
        if (self.env.get(ctor_name)) |ctor| {
            if (ctor.isObject()) o.setProtoAtomic(try self.protoObject(ctor.asObj()));
        }
        return o;
    }

    /// ToObject for property references whose base is a primitive.
    fn boxPrimitiveBase(self: *Interpreter, v: Value) EvalError!*value.Object {
        return self.toObject(v);
    }

    /// Resolve and immediately GetValue an identifier through the lexical
    /// environment chain. Unlike a captured assignment Reference, an immediate
    /// read needs only one binding-table probe. A `with` record additionally
    /// carries its exact WithBaseObject for call/tag evaluation.
    fn lookupIdentValue(self: *Interpreter, name: []const u8) EvalError!?CapturedBindingValue {
        // Read each scope's binding tables under its `binding_lock` (via the
        // flag-gated `lockBindings`, like `Environment.get`): a peer thread may
        // be mutating `vars`/`aliases` through `Environment.put` (which locks),
        // so an unlocked `.get` here races the grow — the systemic no-GIL
        // Environment race the Linux-TSan corpus gate surfaced (it hit even
        // smoke.js: main defines a global while a worker resolves one). Binding
        // locks intentionally start enabled process-wide: concurrent context
        // creation can otherwise flip the flag between a helper's lock load and
        // its paired unlock load. If this becomes a proven hot-path bottleneck,
        // replace the gate with an acquisition token rather than reintroducing
        // false→true transitions.
        var env: ?*Environment = self.env;
        while (env) |e| {
            if (e.activation) |*activation| if (activation.binding(name)) |binding|
                return .{ .value = activation.frame.read(binding.slot) };
            const record = e.mutableBindingRecord();
            const locked = record.lockBindingsForRead();
            // Skip the `aliases` hash (which would still hash `name`) when the map
            // is empty — the common case for ordinary scopes (aliases exist only for
            // `arguments`/`with`/eval-mapped bindings). Halves the per-identifier
            // hashing on the hot resolution path.
            const alias = if (record.aliases.count() != 0) record.aliases.get(name) else null;
            const found_var: ?Value = if (alias == null) record.vars.get(name) else null;
            // `consts` membership must be read under the SAME `binding_lock` as
            // `vars`/`aliases`: a peer thread's `putConst` writes `consts` while
            // holding that lock, so reading it after `unlockBindings` is the same
            // no-GIL Environment data race (Linux-TSan `tsan-parallel-js`). Only
            // meaningful for a resolved global binding, so guard on that first.
            // A global `var`/function shares storage with its own-property on the
            // global object, so its read reflects the current property value; a
            // global lexical (`let`/`const`/`class`) is a distinct declarative
            // binding and shadows any like-named global property. `consts`/`lexicals`
            // are read under the SAME `binding_lock` as `vars` (no-GIL race).
            const global_shadowable = found_var != null and e.parent == null and
                !record.consts.contains(name) and !record.lexicals.contains(name);
            record.unlockBindingsForRead(locked);
            if (alias) |a| return .{ .value = a.env.get(a.name) orelse return null };
            if (found_var) |v| {
                if (global_shadowable) {
                    const g = self.currentGlobalObject() orelse return .{ .value = v };
                    if (objectHasOwn(g, name)) return .{ .value = try self.getProperty(Value.obj(g), name) };
                }
                return .{ .value = v };
            }
            if (record.with_object != null) {
                // HasBinding and GetBindingValue can execute Proxy traps and
                // @@unscopables accessors that move the heap. Root the owning
                // Environment so the object, selected receiver, and next link
                // are always refreshed from relocated storage.
                const environment_root = try self.pushTempEnvRoot(e);
                defer self.restoreTempEnvRoots(environment_root);
                const rooted_environment = self.tempEnvRoot(environment_root, e);
                const with_object = rooted_environment.mutableBindingRecord().with_object.?;
                if (try self.withHasBinding(with_object, name)) {
                    const refreshed_environment = self.tempEnvRoot(environment_root, e);
                    const object_fallback = Value.obj(refreshed_environment.mutableBindingRecord().with_object.?);
                    const object_root = try self.pushTempRoot(object_fallback);
                    defer self.restoreTempRoots(object_root);
                    // Object Environment Record GetBindingValue does its OWN
                    // HasProperty(N) before Get(N) — distinct from the HasBinding
                    // check above — so a proxy env observes a second `has`. If the
                    // binding vanished in between (e.g. a `@@unscopables` getter
                    // deleted it), GetBindingValue with S=true throws a
                    // ReferenceError; a sloppy reference reads undefined.
                    if (!try self.hasPropertyResult(self.tempRoot(object_root, object_fallback).asObj(), name)) {
                        if (self.strict) return self.throwError("ReferenceError", name);
                        return .{ .value = Value.undef() };
                    }
                    const result = try self.getProperty(self.tempRoot(object_root, object_fallback), name);
                    return .{
                        .value = result,
                        .with_base = self.tempRoot(object_root, object_fallback),
                    };
                }
                env = self.tempEnvRoot(environment_root, e).parent;
                continue;
            }
            env = e.parent;
        }
        return null;
    }

    /// Value-only compatibility wrapper for callers that do not need a
    /// WithBaseObject. Global-object-only properties remain the caller's
    /// fallback, matching the historical lookup contract.
    pub fn lookupIdent(self: *Interpreter, name: []const u8) EvalError!?Value {
        return if (try self.lookupIdentValue(name)) |resolved| resolved.value else null;
    }

    /// Resolve an identifier *for assignment*: a `with` object that provides the
    /// binding takes the write (returns true); otherwise the caller assigns to
    /// the lexical/global binding. Stops at the first scope (binding or `with`)
    /// that owns `name`.
    /// The declarative environment that currently holds `name` (a `var`/`let`/
    /// `const` binding), searching outward from `start`. Used to capture an
    /// assignment's target binding BEFORE its right-hand side runs, so a direct
    /// eval in the RHS that introduces a closer binding can't retarget the write
    /// (PutValue uses the initially-created Reference). Returns null when no
    /// declarative binding exists (the target is a `with`/global/new binding).
    fn bindingEnvOf(start: *Environment, name: []const u8) ?*Environment {
        var env: ?*Environment = start;
        while (env) |e| {
            if (e.activationBinding(name) != null) return e;
            const record = e.mutableBindingRecord();
            // Existence check under the binding lock (same no-GIL race class as
            // lookupIdent); the `getPtr` result is not escaped, only its
            // presence, so nothing dangles after unlock.
            const locked = record.lockBindingsForRead();
            const owns = record.vars.getPtr(name) != null or record.aliases.get(name) != null;
            record.unlockBindingsForRead(locked);
            if (owns) return e;
            env = e.parent;
        }
        return null;
    }

    pub fn assignWithObject(self: *Interpreter, name: []const u8) EvalError!?*value.Object {
        var env: ?*Environment = self.env;
        while (env) |e| {
            if (e.activationBinding(name) != null) return null;
            const record = e.mutableBindingRecord();
            const locked = record.lockBindingsForRead();
            const owned = record.aliases.get(name) != null or record.vars.get(name) != null;
            record.unlockBindingsForRead(locked);
            if (owned) return null; // a real binding owns it
            if (record.with_object) |wo| {
                if (try self.withHasBinding(wo, name)) return wo;
            }
            env = e.parent;
        }
        return null;
    }

    /// Resolve an identifier Reference now and retain its exact base for a later
    /// PutValue. A bounded walk stops immediately before a statically resolved
    /// frame/upvalue binding; a full walk additionally distinguishes a global
    /// object binding from an unresolvable reference. `withHasBinding` runs only
    /// here, so iterator/property/default side effects cannot repeat or retarget
    /// the observable `has`/`@@unscopables` lookup.
    pub fn captureBindingReference(self: *Interpreter, name: []const u8, environment_limit: ?u32) EvalError!BindingReference {
        var remaining = environment_limit;
        var env: ?*Environment = self.env;
        while (env) |e| {
            if (remaining) |count| {
                if (count == 0) return .static;
                remaining = count - 1;
            }
            if (e.activationBinding(name) != null) return .{ .environment = e };
            const record = e.mutableBindingRecord();
            const locked = record.lockBindingsForRead();
            const owns_alias = record.aliases.contains(name);
            const owns_var = record.vars.contains(name);
            const owns = owns_alias or owns_var;
            const root_object_candidate = owns_var and !owns_alias and e.parent == null and
                !record.lexicals.contains(name) and !record.consts.contains(name);
            record.unlockBindingsForRead(locked);
            if (owns) {
                if (root_object_candidate) if (self.currentGlobalObject()) |global|
                    if (objectHasOwn(global, name)) return .{ .global_object = global };
                return .{ .environment = e };
            }
            if (record.with_object) |object| {
                // HasBinding can execute Proxy traps and @@unscopables getters,
                // either of which may force a moving collection. Root the
                // Environment Record that owns the object so both the selected
                // base and the next outward link are read from relocated storage.
                const environment_root = try self.pushTempEnvRoot(e);
                defer self.restoreTempEnvRoots(environment_root);
                if (try self.withHasBinding(object, name)) {
                    const rooted_environment = self.tempEnvRoot(environment_root, e);
                    return .{ .with_object = rooted_environment.mutableBindingRecord().with_object.? };
                }
                env = self.tempEnvRoot(environment_root, e).parent;
                continue;
            }
            env = e.parent;
        }
        if (environment_limit != null) return .static;
        if (try self.globalHasBinding(name))
            return .{ .global_object = self.currentGlobalObject().? };
        return .unresolvable;
    }

    /// Delete an IdentifierReference after resolving its Environment Record.
    /// Frame-mode bytecode supplies a bounded search: activation-local
    /// declarative/`with` records may shadow a known slot, but environments
    /// lexically behind that non-deletable frame/upvalue binding must not.
    /// Null searches the complete name-backed Environment chain.
    pub fn deleteIdentifier(self: *Interpreter, name: []const u8, strict: bool, environment_limit: ?u32) EvalError!bool {
        var remaining = environment_limit;
        var env: ?*Environment = self.env;
        while (env) |e| {
            if (remaining) |count| {
                if (count == 0) return false;
                remaining = count - 1;
            }

            if (e.activationBinding(name) != null) {
                if (strict) return self.throwError("TypeError", "Cannot delete binding");
                return false;
            }

            const record = e.mutableBindingRecord();
            const locked = record.lockBindingsForRead();
            const owns = record.vars.contains(name) or record.aliases.get(name) != null;
            const deletable = owns and record.deletable.contains(name);
            const is_global = e.parent == null;
            record.unlockBindingsForRead(locked);
            if (owns) {
                // A sloppy eval-created binding is removed from the declaring
                // Environment. Global variable bindings instead mirror their
                // configurable state on the global object's own property.
                if (deletable) {
                    _ = e.removeVar(name);
                    return true;
                }
                if (is_global) {
                    if (self.global_object) |global| {
                        if (objectHasOwn(global, name)) {
                            const deleted = try self.deleteOwn(global, name);
                            if (deleted) _ = e.removeVar(name);
                            if (!deleted and strict) return self.throwError("TypeError", "Cannot delete property");
                            return deleted;
                        }
                    }
                }
                if (strict) return self.throwError("TypeError", "Cannot delete binding");
                return false;
            }
            if (record.with_object) |object| {
                if (try self.withHasBinding(object, name)) {
                    const deleted = try self.deleteOwn(object, name);
                    if (!deleted and strict) return self.throwError("TypeError", "Cannot delete property");
                    return deleted;
                }
            }
            env = e.parent;
        }

        // A bounded search reaching the chain tail still falls back to the
        // statically known non-deletable slot rather than an unresolvable name.
        if (environment_limit != null) return false;
        if (self.global_object) |global| {
            if (objectHasOwn(global, name)) {
                const deleted = try self.deleteOwn(global, name);
                if (!deleted and strict) return self.throwError("TypeError", "Cannot delete property");
                return deleted;
            }
        }
        return true;
    }

    /// Whether a `with` binding object provides a binding for `name`: it has the
    /// property AND `name` is not listed truthy in the object's
    /// `[Symbol.unscopables]` (which hides selected names from `with` scope).
    pub fn withHasBinding(self: *Interpreter, o: *value.Object, name: []const u8) EvalError!bool {
        // Both HasProperty and the two Gets below are observable. A Proxy trap
        // or accessor may force moving GC, so never carry an unrooted raw object
        // pointer from one operation to the next.
        const object_fallback = Value.obj(o);
        const object_root = try self.pushTempRoot(object_fallback);
        defer self.restoreTempRoots(object_root);
        if (!try self.hasPropertyResult(self.tempRoot(object_root, object_fallback).asObj(), name)) return false;
        const unsc_key = self.wellKnownSymbolKey("unscopables") orelse return true;
        const unsc = try self.getProperty(self.tempRoot(object_root, object_fallback), unsc_key);
        const unsc_root = try self.pushTempRoot(unsc);
        defer self.restoreTempRoots(unsc_root);
        const rooted_unsc = self.tempRoot(unsc_root, unsc);
        if (rooted_unsc.isObject()) {
            if ((try self.getProperty(rooted_unsc, name)).toBoolean()) return false;
        }
        return true;
    }

    /// Build an `Error`-family instance with `name`/`message` properties.
    /// Register a `using`/`await using` resource on the current scope. Validates
    /// it has a [Symbol.dispose] / [Symbol.asyncDispose] method (null/undefined is
    /// a permitted no-op resource).
    pub fn addDisposable(self: *Interpreter, val: Value, is_async: bool) EvalError!void {
        if (val.isNull() or val.isUndefined()) {
            if (!is_async) return;
            const locked = self.env.lockBindingsForWrite(); // traceEnv reads disposables; serialize the append
            defer self.env.unlockBindingsForWrite(locked);
            try self.env.disposables.append(self.env.bindingAllocator(), .{ .value = Value.undef(), .method = Value.undef(), .is_async = true, .await_result = true });
            return;
        }
        if (!val.isObject()) return self.throwError("TypeError", "a 'using' declaration value must be an object or null/undefined");
        var method: Value = Value.undef();
        var await_result = false;
        if (is_async) {
            if (self.wellKnownSymbolKey("asyncDispose")) |k| method = try self.getProperty(val, k);
            await_result = !(method.isUndefined() or method.isNull());
            if (method.isUndefined() or method.isNull()) {
                if (self.wellKnownSymbolKey("dispose")) |k| method = try self.getProperty(val, k);
            }
        } else if (self.wellKnownSymbolKey("dispose")) |k| {
            method = try self.getProperty(val, k);
        }
        if (!method.isCallable()) return self.throwError("TypeError", "a 'using' declaration value must have a [Symbol.dispose] method");
        self.env.barrierStoredValue(val);
        self.env.barrierStoredValue(method);
        const locked = self.env.lockBindingsForWrite(); // traceEnv reads disposables; serialize the append
        defer self.env.unlockBindingsForWrite(locked);
        try self.env.disposables.append(self.env.bindingAllocator(), .{ .value = val, .method = method, .is_async = is_async, .await_result = await_result });
    }

    /// Dispose a scope's `using` resources in reverse declaration order, threading
    /// `body_err` (the scope body's thrown value, if any). A disposal error
    /// becomes the pending completion, wrapping any earlier one in a
    /// SuppressedError. Returns the value to re-throw, or null on clean exit.
    pub fn disposeScope(self: *Interpreter, env: *Environment, body_err: ?Value) EvalError!?Value {
        var pending = body_err orelse env.dispose_pending;
        env.dispose_pending = null;
        var i = env.disposables.items.len;
        while (i > 0) {
            i -= 1;
            const d = env.disposables.items[i];
            var dispose_err: ?Value = null;
            if (d.method.isUndefined()) {
                if (d.is_async) {
                    const tick = try promiseResolveAfterTick(self, Value.undef());
                    _ = self.awaitValue(tick) catch |e| {
                        if (e != error.Throw) return e;
                        dispose_err = self.exception;
                        self.exception = Value.undef();
                    };
                }
            } else if (self.callValueWithThis(d.method, &.{}, d.value)) |rv| {
                if (d.is_async) {
                    _ = self.awaitValue(rv) catch |e| {
                        if (e != error.Throw) return e;
                        dispose_err = self.exception;
                        self.exception = Value.undef();
                    };
                }
            } else |e| {
                if (e != error.Throw) return e;
                dispose_err = self.exception;
                self.exception = Value.undef();
            }
            if (dispose_err) |this_err| {
                pending = if (pending) |prev|
                    (self.makeErrorWithArgs("SuppressedError", &.{ this_err, prev }) catch this_err)
                else
                    this_err;
            }
        }
        if (env.bindings_allocator != null) {
            env.disposables.deinit(env.bindingAllocator());
            env.disposables = .empty;
        } else {
            env.disposables.clearRetainingCapacity();
        }
        return pending;
    }

    pub fn disposeScopeAsyncStep(self: *Interpreter, env: *Environment) EvalError!?Value {
        var pending: ?Value = env.dispose_pending;
        env.dispose_pending = null;
        while (env.disposables.items.len > 0) {
            const idx = env.disposables.items.len - 1;
            const d = env.disposables.items[idx];
            env.disposables.shrinkRetainingCapacity(idx);
            var dispose_err: ?Value = null;
            if (d.method.isUndefined()) {
                if (d.is_async and d.await_result) return Value.undef();
            } else if (self.callValueWithThis(d.method, &.{}, d.value)) |rv| {
                if (d.is_async and d.await_result) return rv;
            } else |e| {
                if (e != error.Throw) return e;
                dispose_err = self.exception;
                self.exception = Value.undef();
            }
            if (dispose_err) |this_err| {
                pending = if (pending) |prev|
                    (self.makeErrorWithArgs("SuppressedError", &.{ this_err, prev }) catch this_err)
                else
                    this_err;
            }
            env.dispose_pending = pending;
        }
        clear: {
            if (env.bindings_allocator != null) {
                env.disposables.deinit(env.bindingAllocator());
                env.disposables = .empty;
                break :clear;
            }
            env.disposables.clearRetainingCapacity();
        }
        if (pending) |err| {
            env.dispose_pending = null;
            self.exception = err;
            return error.Throw;
        }
        return null;
    }

    pub fn initEnvironment(self: *Interpreter, env: *Environment, parent: ?*Environment, fn_scope: bool) void {
        env.* = .{
            .arena = self.arena,
            .bindings_allocator = self.gc_side_storage,
            .gc_name_bytes_live = self.gc_environment_name_bytes_live,
            .parent = parent,
            .gc_managed = gc_mod.allocationsAreManaged(),
            .fn_scope = fn_scope,
            .private_activation = .init(if (parent) |p| p.private_activation.load(.acquire) and !p.captured.load(.acquire) else false),
        };
    }

    fn acquireBlockEnvironment(self: *Interpreter, parent: *Environment) EvalError!*Environment {
        if (self.reusable_block_env) |env| {
            // Unlike a fresh nursery cell, the cache can be observed by a
            // concurrent marker and can already be tenured. Preserve its mutex,
            // reinitialize the empty payload under that mutex, and barrier the
            // newly installed parent edge. The cache pointer remains published
            // until evalBlockScope installs this cell as the active environment,
            // so a concurrent root snapshot can never miss it between owners.
            env.lockBindings();
            defer env.unlockBindings();
            env.arena = self.arena;
            env.bindings_allocator = self.gc_side_storage;
            env.gc_name_bytes_live = self.gc_environment_name_bytes_live;
            env.parent = parent;
            // Cell ownership is fixed by allocEnv. In particular, a concurrent
            // marker can read this bit through a different Environment edge,
            // so even a same-value rewrite here would be an engine-state race.
            std.debug.assert(env.gc_managed == (self.gc_side_storage != null));
            env.fn_scope = false;
            env.private_activation.store(parent.private_activation.load(.acquire) and !parent.captured.load(.acquire), .monotonic);
            // The cached cell can have survived long enough to tenure. Reusing
            // it under a young lexical parent creates a new managed edge, unlike
            // initialization of a freshly allocated nursery environment.
            if (env.gc_managed and parent.gc_managed)
                if (!gc_mod.barrierExactManagedCellFrom(env, parent))
                    gc_mod.barrierCellFrom(env, parent);
            return env;
        }
        const env = try gc_mod.allocEnv(self.arena);
        self.initEnvironment(env, parent, false);
        return env;
    }

    fn acquireCallEnvironment(self: *Interpreter, func: *Function) EvalError!*Environment {
        if (self.reusable_call_env) |env| {
            // Different functions can have different static binding layouts.
            // Reclaim the retained side tables before reusing the cell for a
            // different AST; identical bodies keep their bounded layout and
            // overwrite values without allocator traffic.
            if (self.reusable_call_body != func.body) {
                env.resetForBlockReuse();
                self.reusable_call_body = null;
            }
            // Keep the cache pointer published until callPlain installs this as
            // the active environment. A concurrent marker can therefore never
            // miss the cell between its two interpreter-owned roots.
            env.lockBindings();
            defer env.unlockBindings();
            env.arena = self.arena;
            env.bindings_allocator = self.gc_side_storage;
            env.gc_name_bytes_live = self.gc_environment_name_bytes_live;
            env.parent = func.closure;
            // Reuse changes graph edges and activation state, never the cell's
            // allocation-time ownership ruling. Keep this a read-only invariant
            // for concurrent parent-edge tracing.
            std.debug.assert(env.gc_managed == (self.gc_side_storage != null));
            env.fn_scope = true;
            env.private_activation.store(true, .monotonic);
            // A cached activation can be tenured while its new closure parent
            // is young. Publish that managed edge exactly before execution.
            if (env.gc_managed and func.closure.gc_managed)
                if (!gc_mod.barrierExactManagedCellFrom(env, func.closure))
                    gc_mod.barrierCellFrom(env, func.closure);
            return env;
        }
        const env = try gc_mod.allocEnv(self.arena);
        self.initEnvironment(env, func.closure, true);
        env.private_activation.store(true, .monotonic);
        return env;
    }

    fn releaseBlockEnvironment(self: *Interpreter, env: *Environment) void {
        // Arena environments cannot release their side storage, function-body
        // environments retain special declaration-instantiation state, and a
        // captured environment has observable identity. All three keep their
        // existing one-shot lifetime.
        if (env.bindings_allocator == null or env.fn_body or env.captured.load(.acquire) or
            env.disposables.items.len != 0 or env.dispose_pending != null)
            return;
        env.resetForBlockReuse();
        // Nested block exit can find the slot occupied by an already-cleared
        // inner environment. Reclaim this environment's side storage anyway and
        // let its empty cell die; one retained cell is sufficient.
        if (self.reusable_block_env == null) self.reusable_block_env = env;
    }

    fn releaseCallEnvironment(self: *Interpreter, env: *Environment, func: *Function) void {
        // A closure or mapped arguments object makes activation identity and
        // bindings observable. Allocation failures can leave a partial table;
        // callPlain deliberately invokes this helper only for normal completion.
        if (env.bindings_allocator == null or env.captured.load(.acquire) or env.aliases.count() != 0 or
            env.deletable.count() != 0 or
            env.disposables.items.len != 0 or env.dispose_pending != null)
            return;
        env.resetForCallReuse();
        if (self.reusable_call_env == null) {
            self.reusable_call_env = env;
            self.reusable_call_body = func.body;
        }
    }

    /// Evaluate a `{…}` block in its own lexical scope, disposing any `using`
    /// resources declared in it when it exits (normally or abruptly).
    /// Whether a block statement list binds anything at its OWN scope and so needs
    /// its own declarative environment. Only `let`/`const`/`class`, block-scoped
    /// function declarations, and `using` resources bind here; `var` hoists to the
    /// variable scope, and nested constructs (if / loops / switch / try / with /
    /// inner blocks) establish their own scopes. Conservative by construction: the
    /// allowlist holds only statements that provably do not bind here, so any
    /// unrecognized or declaration statement returns `true` (allocate an env, the
    /// original behavior) — a mistake can only cost an allocation, never misroute a
    /// binding.
    fn blockNeedsOwnScope(stmts: []const *Node) bool {
        for (stmts) |s| switch (s.*) {
            .expr_stmt, .if_stmt, .while_stmt, .do_while_stmt, .for_stmt, .for_in, .switch_stmt, .return_stmt, .throw_stmt, .break_stmt, .continue_stmt, .block, .try_stmt, .with_stmt => {},
            .var_decl => |d| if (d.kind != .@"var" or d.dispose != 0) return true, // let/const/using bind here; plain var hoists out
            .destructure_decl => |d| if (d.kind != .@"var") return true,
            else => return true, // func_decl, class (a lexical var_decl), decl_group, labeled (maybe a function), import/export, …
        };
        return false;
    }

    fn evalBlockScope(self: *Interpreter, stmts: []*Node) EvalError!Value {
        // A label on a block (`L: { … }`) labels the BLOCK, not a loop nested inside
        // it — so consume the pending label here, keeping it from being adopted by an
        // inner loop (`L: { do { break L; } while (true); … }` must break the block).
        // The matching break is consumed at the `.labeled_stmt` level.
        _ = self.takeLabels();
        // A block that binds nothing at its own scope needs no environment — run its
        // statements in the current scope, skipping the per-entry GC-cell allocation
        // (common in hot loop bodies like `{ acc += x; }`). A function body needs
        // a distinct `fn_body` environment only when it owns lexical declarations;
        // its call environment is already the variable-scope marker otherwise.
        if (!blockNeedsOwnScope(stmts)) {
            // A binding-free function body can execute directly in its call
            // environment. That environment is already the variable scope, so
            // evalStatements still performs function-top hoisting and Annex B
            // analysis for nested constructs without allocating an empty body
            // cell on every invocation.
            if (self.mark_fn_body) self.mark_fn_body = false;
            return self.evalStatements(stmts);
        }
        const block_env = try self.acquireBlockEnvironment(self.env);
        if (self.mark_fn_body) {
            block_env.fn_body = true;
            self.mark_fn_body = false;
        }
        const saved_env = self.env;
        self.env = block_env;
        if (self.reusable_block_env == block_env) self.reusable_block_env = null;
        defer self.env = saved_env;
        const result = self.evalStatements(stmts);
        if (block_env.disposables.items.len == 0) {
            if (result) |val| {
                self.releaseBlockEnvironment(block_env);
                return val;
            } else |err| {
                // A JavaScript throw has a fully-instantiated environment and
                // its escaping value/closures have already marked capture.
                // Allocator failures can interrupt a binding insertion, so leave
                // those environments to the GC finalizer instead of recycling a
                // possibly partial table.
                if (err == error.Throw) self.releaseBlockEnvironment(block_env);
                return err;
            }
        }
        var body_err: ?Value = null;
        const val: Value = result catch |e| blk: {
            if (e != error.Throw) return e;
            body_err = self.exception;
            break :blk Value.undef();
        };
        if (try self.disposeScope(block_env, body_err)) |err| {
            self.exception = err;
            self.releaseBlockEnvironment(block_env);
            return error.Throw;
        }
        self.releaseBlockEnvironment(block_env);
        return val;
    }

    fn labeledFunctionDeclNode(node: *Node) ?*Node {
        return @import("annex_b.zig").functionDeclaration(node);
    }

    fn labeledStatementTargetsIteration(node: *const Node) bool {
        return switch (node.*) {
            .while_stmt, .do_while_stmt, .for_stmt, .for_in => true,
            .labeled_stmt => |statement| labeledStatementTargetsIteration(statement.body),
            else => false,
        };
    }

    fn hoistStatementFunctionDecl(self: *Interpreter, stmt: *Node, at_fn_top: bool) EvalError!bool {
        const fn_node = switch (stmt.*) {
            .func_decl => stmt,
            .labeled_stmt => labeledFunctionDeclNode(stmt) orelse return false,
            else => return false,
        };
        const fnode = fn_node.func_decl;
        const fnv = try self.makeFunction(fnode, self.env);
        if (at_fn_top) {
            try self.globalDefineFunc(fnode.name, fnv);
        } else {
            try self.env.put(fnode.name, fnv);
        }
        return true;
    }

    fn evalHoistedFunctionDecl(self: *Interpreter, stmt: *Node) EvalError!bool {
        const fn_node = switch (stmt.*) {
            .func_decl => stmt,
            .labeled_stmt => labeledFunctionDeclNode(stmt) orelse return false,
            else => return false,
        };
        if (self.annexb_legacy_nodes) |set| {
            if (set.contains(fn_node)) {
                const name = fn_node.func_decl.name;
                const fnv = self.env.get(name) orelse Value.undef();
                try self.globalDefineDeletable(name, fnv);
            }
        }
        return true;
    }

    pub fn makeErrorWithProto(self: *Interpreter, name: []const u8, message: []const u8, proto: ?*value.Object) EvalError!Value {
        const obj = try gc_mod.allocObj(self.arena);
        obj.* = .{ .behavior = .{ .is_error = true } };
        try obj.setErrorName(self.arena, name);
        try self.captureErrorStack(obj);
        // Link to `<name>.prototype` so `name` (and `toString`) are inherited and
        // `instanceof` / `Object.getPrototypeOf` see a real chain.
        if (proto) |p| {
            obj.setProtoAtomic(p);
        } else if (self.env.get(name)) |ctor_v| {
            if (ctor_v.isObject()) {
                if (ctor_v.asObj().getOwn("prototype")) |proto_v| {
                    if (proto_v.isObject()) obj.setProtoAtomic(proto_v.asObj());
                }
            }
        }
        // `message` is an own property only when one was supplied (else inherited,
        // = "" from the prototype); `name` is always inherited from the prototype.
        if (message.len > 0) {
            try self.setProp(obj, "message", try Value.strAlloc(self.arena, message));
            try obj.setAttr(self.arena, "message", .{ .enumerable = false, .configurable = true, .writable = true });
        }
        return Value.obj(obj);
    }

    pub fn errorStackFrameFromCallFrame(frame: *const StackTraceCallFrame, index: usize) value.ErrorStackFrame {
        const location = frame.location;
        const line: i32 = if (location) |loc|
            std.math.cast(i32, loc.location.line -| 1) orelse std.math.maxInt(i32)
        else
            -1;
        const column: i32 = if (location) |loc|
            std.math.cast(i32, loc.location.column -| 1) orelse std.math.maxInt(i32)
        else
            -1;
        const line_start: i32 = if (location) |loc| blk: {
            const start = loc.location.byte_offset -| (loc.location.column -| 1);
            break :blk std.math.cast(i32, start) orelse -1;
        } else -1;
        return .{
            .function_name = frame.function_name,
            .source_url = if (location) |loc| loc.source_url else "",
            .script_id = if (location) |loc| loc.script_id else 0,
            .line_zero_based = line,
            .column_zero_based = column,
            .line_start_byte = line_start,
            .code_type = frame.code_type,
            .is_async = frame.is_async,
            .jsc_stack_frame_index = std.math.cast(i32, index) orelse std.math.maxInt(i32),
        };
    }

    fn appendErrorStackFrame(self: *Interpreter, frames: *std.ArrayListUnmanaged(value.ErrorStackFrame), frame: *const StackTraceCallFrame) EvalError!void {
        try frames.append(self.arena, errorStackFrameFromCallFrame(frame, frames.items.len));
    }

    /// Realm-local limit used by private async-stack reconstruction. The
    /// writable `Error.stackTraceLimit` convention defaults to ten frames;
    /// non-finite/non-positive values disable collection and very large values
    /// are bounded by the structured-frame ABI's u8-sized practical limit.
    pub fn selectedStackTraceLimit(self: *Interpreter) usize {
        const ctor = self.env.get("Error") orelse return 10;
        if (!ctor.isObject()) return 10;
        const configured = ctor.asObj().getOwn("stackTraceLimit") orelse return 10;
        if (!configured.isNumber()) return 0;
        const number = configured.asNum();
        if (!std.math.isFinite(number) or number <= 0) return 0;
        const bounded = @min(number, @as(f64, @floatFromInt(std.math.maxInt(u8))));
        return @intFromFloat(@floor(bounded));
    }

    fn captureErrorStack(self: *Interpreter, obj: *value.Object) EvalError!void {
        var frames: std.ArrayListUnmanaged(value.ErrorStackFrame) = .empty;
        var current = self.stack_trace_call_frame;
        while (current) |frame| : (current = frame.caller) {
            try self.appendErrorStackFrame(&frames, frame);
            if (frames.items.len == std.math.maxInt(u8)) break;
        }
        if (frames.items.len == 0) {
            var global_frame = StackTraceCallFrame{
                .code_type = if (self.cur_module.len > 0) .module else .global,
                .location = self.debug_current_location,
            };
            try self.appendErrorStackFrame(&frames, &global_frame);
        }
        try obj.setErrorStackFrames(self.arena, try frames.toOwnedSlice(self.arena));
    }

    pub fn makeError(self: *Interpreter, name: []const u8, message: []const u8) EvalError!Value {
        return self.makeErrorWithProto(name, message, null);
    }

    /// Build a DOMException whose `name` is `name` (e.g. "DataCloneError"),
    /// `code` derives from it, and `message` is the (possibly empty) detail. It
    /// is error-like (`is_error`) and chains through %DOMException.prototype% to
    /// %Error.prototype%; `name`/`message`/`code` are read by the prototype
    /// accessors from cold error metadata and the hidden `\x00dommsg` slot.
    pub fn makeDOMException(self: *Interpreter, name: []const u8, message: []const u8) EvalError!Value {
        const obj = try gc_mod.allocObj(self.arena);
        obj.* = .{ .behavior = .{ .is_error = true } };
        try obj.setErrorName(self.arena, try self.arena.dupe(u8, name));
        try self.captureErrorStack(obj);
        if (self.env.get("DOMException")) |ctor_v| if (ctor_v.isObject()) {
            if (ctor_v.asObj().getOwn("prototype")) |p| if (p.isObject()) obj.setProtoAtomic(p.asObj());
        };
        if (message.len > 0)
            try obj.setOwn(self.arena, self.root_shape, "\x00dommsg", try Value.strAlloc(self.arena, message));
        return Value.obj(obj);
    }

    pub fn throwDOMException(self: *Interpreter, name: []const u8, message: []const u8) EvalError {
        self.exception = try self.makeDOMException(name, message);
        try self.notifyDebuggerException(false);
        return error.Throw;
    }

    /// Raise a JS exception of the given error class. Always returns
    /// `error.Throw` (or `error.OutOfMemory` if the error object can't be built).
    pub fn throwError(self: *Interpreter, name: []const u8, message: []const u8) EvalError {
        self.exception = try self.makeError(name, message);
        try self.notifyDebuggerException(false);
        return error.Throw;
    }

    fn throwMissingRequiredChunk(self: *Interpreter, func: *const Function, kind: []const u8) EvalError {
        const function_name = if (func.name.len == 0) "<anonymous>" else func.name;
        const message = try std.fmt.allocPrint(self.arena, "required bytecode {s} function '{s}' has no compiled chunk ({s})", .{
            kind,
            function_name,
            @tagName(func.bytecode_admission_reason),
        });
        return self.throwError("InternalError", message);
    }

    /// Raise an engine-originated exception that WebAssembly `try_table` must
    /// not catch when it crosses a JavaScript callback frame (stack exhaustion
    /// and WebAssembly traps are specified to bypass Wasm handlers).
    pub fn throwUncatchableError(self: *Interpreter, name: []const u8, message: []const u8) EvalError {
        self.exception = try self.makeError(name, message);
        self.exception.asObj().markWasmUncatchableException();
        try self.notifyDebuggerException(false);
        return error.Throw;
    }

    /// Like `throwError`, but the error object's [[Prototype]] is given
    /// explicitly instead of being recovered from the realm's `<name>` binding.
    /// Used by the WebAssembly error classes, whose constructors live on the
    /// WebAssembly namespace rather than as global bindings (issue #141).
    pub fn throwErrorWithProto(self: *Interpreter, name: []const u8, message: []const u8, proto: *value.Object) EvalError {
        self.exception = try self.makeErrorWithProto(name, message, proto);
        try self.notifyDebuggerException(false);
        return error.Throw;
    }

    pub fn notifyDebuggerException(self: *Interpreter, uncaught: bool) EvalError!void {
        if (self.debug_exception_hook) |hook| {
            if (!uncaught) self.debug_exception_origin_notified = true;
            try hook(self.debug_exception_ctx.?, self, self.exception, self.debug_current_location, uncaught);
        }
    }

    pub fn catchableOutOfMemory(self: *Interpreter, err: EvalError) EvalError {
        if (err == error.OutOfMemory and !self.out_of_memory_exception.isUndefined()) {
            self.serviceDeferredAllocationRecovery();
            self.exception = self.out_of_memory_exception;
            return error.Throw;
        }
        return err;
    }

    fn serviceDeferredAllocationRecovery(self: *Interpreter) void {
        const pending = self.gc_deferred_allocation_recovery orelse return;
        if (!pending.load(.acquire)) return;
        const recover = self.gc_recover_allocation_fn orelse return;
        const ctx = self.gc_checkpoint_ctx orelse return;
        if (recover(ctx)) pending.store(false, .release);
    }

    /// Raise a SyntaxError for parser failures with a best-effort source
    /// location. `context` names the embedding operation ("eval", "Function",
    /// etc.); source-bearing APIs can layer richer filenames on top separately.
    pub fn throwParserSyntaxErrorAt(self: *Interpreter, context: []const u8, loc: parser_mod.SourceLocation, err: anyerror) EvalError {
        const message = std.fmt.allocPrint(self.arena, "{s}: {s} at {d}:{d}", .{
            context,
            @errorName(err),
            loc.line,
            loc.column,
        }) catch return error.OutOfMemory;
        self.exception = try self.makeError("SyntaxError", message);
        const obj = self.exception.asObj();
        try obj.setOwn(self.arena, self.root_shape, "line", Value.num(@floatFromInt(loc.line)));
        try obj.setAttr(self.arena, "line", .{ .writable = true, .enumerable = false, .configurable = true });
        try obj.setOwn(self.arena, self.root_shape, "column", Value.num(@floatFromInt(loc.column)));
        try obj.setAttr(self.arena, "column", .{ .writable = true, .enumerable = false, .configurable = true });
        try obj.setOwn(self.arena, self.root_shape, "byteOffset", Value.num(@floatFromInt(loc.byte_offset)));
        try obj.setAttr(self.arena, "byteOffset", .{ .writable = true, .enumerable = false, .configurable = true });
        try self.notifyDebuggerException(false);
        return error.Throw;
    }

    pub fn throwParserSyntaxError(self: *Interpreter, context: []const u8, source: []const u8, parser: ?*const Parser, err: anyerror) EvalError {
        const loc = if (parser) |p| p.errorLocation() else parser_mod.sourceLocationAt(source, 0);
        return self.throwParserSyntaxErrorAt(context, loc, err);
    }

    pub fn throwParserSyntaxErrorInRealm(self: *Interpreter, realm: *Environment, context: []const u8, source: []const u8, parser: ?*const Parser, err: anyerror) EvalError {
        const saved_env = self.env;
        self.env = realm;
        defer self.env = saved_env;
        return self.throwParserSyntaxError(context, source, parser, err);
    }

    pub fn throwParserSyntaxErrorAtInRealm(self: *Interpreter, realm: *Environment, context: []const u8, loc: parser_mod.SourceLocation, err: anyerror) EvalError {
        const saved_env = self.env;
        self.env = realm;
        defer self.env = saved_env;
        return self.throwParserSyntaxErrorAt(context, loc, err);
    }

    /// Consume VM trap bits that require work on the executing thread. This is
    /// shared by the tree walker, bytecode VM, quickened regions, and native
    /// checkpoint islands so a tier change cannot delay or lose a host trap.
    pub fn serviceVmTraps(self: *Interpreter) EvalError!void {
        if (self.shell_timeout_check_flag) |flag| if (flag.swap(false, .acq_rel)) {
            if (self.termination_request_flag) |requested| requested.store(true, .release);
            return self.throwError("Error", "worker terminated");
        };
        if (self.watchdog_check_flag) |flag| if (flag.swap(false, .acq_rel)) {
            // JSC `VMTraps::NeedWatchdogCheck`: re-check the armed execution
            // time limit on the executing thread. A future/disarmed deadline
            // consumes the trap without disturbing evaluation.
            if (self.watchdog_deadline_ns) |deadline_ptr| {
                const deadline = deadline_ptr.load(.acquire);
                if (deadline != 0) {
                    const now: u64 = @intCast(@max(std.Io.Timestamp.now(agent.engineIo(), .awake).nanoseconds, 0));
                    if (now >= deadline) {
                        if (self.termination_request_flag) |requested| requested.store(true, .release);
                        return self.throwError("Error", "worker terminated");
                    }
                }
            }
        };
    }

    /// Every AST node evaluation crosses the same debugger, budget, trap, GIL,
    /// and GC checkpoint boundary. Specialized Reference evaluators must call
    /// this before bypassing `eval`; otherwise a tier-local fast path can delay
    /// host progress or lose the cooperative scheduling point the AST carries.
    fn beginNodeEvaluation(self: *Interpreter, node: *const Node) EvalError!void {
        try self.serviceDebugStatement(node);
        self.steps += 1;
        if (self.steps > self.step_budget) return self.throwError("RangeError", "evaluation step budget exceeded");
        if ((self.steps & 1023) == 0) {
            if (self.stop_flag) |sf| if (sf.load(.monotonic))
                return self.throwError("Error", "worker terminated");
            try self.serviceVmTraps();
            if (self.use_thread_gil) if (self.gil) |g| g.yieldIfContended();
            // Mid-script GC: the tree-walker holds live `Value`s only as native
            // Zig locals/registers, which the conservative native-stack scan
            // covers; run a guarded collection. No-op when the GC is off.
            if (self.gc_safepoint_fn != null) self.serviceGcSafepoint();
        }
    }

    pub fn eval(self: *Interpreter, node: *const Node) EvalError!Value {
        try self.beginNodeEvaluation(node);
        return switch (node.*) {
            .number => |n| Value.num(n),
            .bigint_lit => |b| if (b.text) |s| try self.makeBigIntText(s) else try self.makeBigInt(b.value),
            .string => |s| blk: {
                if (self.string_literal_cache.get(node)) |cached| break :blk cached;
                const literal = try Value.strAlloc(self.arena, s);
                try self.string_literal_cache.put(self.arena, node, literal);
                break :blk literal;
            },
            .boolean => |b| Value.boolVal(b),
            .null_lit => Value.nul(),
            .undefined_lit => Value.undef(),
            .elision => Value.undef(), // only meaningful inside an array literal
            // GetThisBinding: in a derived constructor, `this` is in its TDZ until
            // `super()` initializes it — reading it (e.g. `super(this.x)`) is a
            // ReferenceError. `this_initialized` is true everywhere else (base
            // ctors, methods, ordinary functions), so this only fires before super().
            .this_expr => if (self.this_cell) |c| blk: {
                if (!c.isInitialized()) return self.throwError("ReferenceError", "Must call super constructor before using 'this'");
                break :blk c.value();
            } else if (self.this_initialized) self.this_value else return self.throwError("ReferenceError", "Must call super constructor before using 'this'"),
            // A class field initializer / static block is run as a method-like
            // function (it is [[Call]]ed, never [[Construct]]ed), so `new.target`
            // inside it — including inside a direct `eval` in it — is undefined.
            // `callPlain` clears `in_field_initializer` for any non-arrow call, so a
            // `new X()` made from a field initializer still sees its own new.target.
            .new_target_expr => if (self.in_field_initializer) Value.undef() else self.new_target,
            .identifier => |name| blk: {
                const resolved = try self.resolveBindingValue(name, false);
                break :blk resolved.value;
            },

            .unary => |u| try self.evalUnary(u.op, u.operand),
            .delete_expr => |target| blk: {
                // `delete super.x` / `delete super[expr]` is always a ReferenceError
                // (the reference is a SuperReference). SuperProperty creation does
                // GetThisBinding first — a derived constructor before `super()` has
                // uninitialized `this`, a ReferenceError thrown BEFORE the key is
                // evaluated — then evaluates the computed key (for its side effects,
                // but without ToPropertyKey), and finally delete rejects the
                // SuperReference. So `delete super[{toString(){throw}}]` yields the
                // ReferenceError, not the toString error.
                if (target.* == .super_member) {
                    if (!self.this_initialized) return self.throwError("ReferenceError", "Must call super constructor before using 'this'");
                    if (target.super_member.computed) |c| _ = try self.eval(c);
                    return self.throwError("ReferenceError", "Cannot delete a super property");
                }
                // `delete obj.prop` / `delete obj[expr]`: remove an own property
                // (honoring [[Configurable]]). `delete <non-reference>` is true.
                if (target.* == .optional_chain and target.optional_chain.* == .member)
                    break :blk try self.deleteMemberExpression(target.optional_chain.member);
                if (target.* == .member) {
                    break :blk try self.deleteMemberExpression(target.member);
                }
                // `delete <name>` inside a `with` deletes from the binding object
                // (an object environment record); elsewhere a bare-name delete
                // resolves the reference's base. A property of the global object
                // (a built-in like `JSON`, a global `var`/`function`, or a sloppy
                // implicit global) deletes per [[Configurable]] — so configurable
                // built-ins go, non-configurable global vars stay (false). A name
                // bound only in a declarative record (`let`/`const`, or a
                // function-local) is not deletable → false.
                if (target.* == .identifier)
                    break :blk Value.boolVal(try self.deleteIdentifier(target.identifier, self.strict, null));
                // Any other operand (a CallExpression, literal, parenthesized
                // expression, …) is not a Reference: evaluate it for its side
                // effects, then `delete` is simply true.
                _ = try self.eval(target);
                break :blk Value.boolVal(true);
            },
            .update => |u| try self.evalUpdate(u.inc, u.prefix, u.target),
            .binary => |b| try self.evalBinary(b.op, b.left, b.right),
            .logical => |l| try self.evalLogical(l.op, l.left, l.right),
            .sequence => |s| blk: {
                _ = try self.eval(s.first);
                break :blk try self.eval(s.second);
            },

            .assign => |a| blk: {
                // A PUBLIC class field initializer desugars to `this.<name> =
                // <field_init_value>`, but DefineField is CreateDataPropertyOrThrow,
                // not [[Set]]: it defines an own data property (shadowing any
                // same-named accessor up the prototype chain) and throws on a
                // non-extensible receiver. The anonymous RHS is named with the
                // field name.
                if (a.value.* == .field_init_value and a.target.* == .member) {
                    const m = a.target.member;
                    const obj = try self.eval(m.object);
                    // Computed public class fields are resolved once at class
                    // definition time, then baked into this desugared member node
                    // as an already-encoded storage key. Reusing memberKey would
                    // double-escape NUL-led string keys and turn Symbol storage
                    // keys into public strings.
                    const key = if (m.computed == null and m.property.len > 0 and m.property[0] == 0)
                        m.property
                    else
                        try self.memberKey(m.property, m.computed);
                    const v = try self.eval(a.value);
                    try self.maybeNameAnon(v, a.value.field_init_value, key);
                    try self.initializePublicClassField(obj, key, v);
                    break :blk v;
                }
                if (a.target.* == .call) {
                    _ = try self.eval(a.target);
                    return self.throwError("ReferenceError", "invalid assignment target");
                }
                // `base[key] = value`: the LeftHandSide is evaluated before the RHS,
                // but RequireObjectCoercible(base) and ToPropertyKey(key) are deferred
                // to PutValue — so the spec order is base, key expression, RHS, THEN
                // the null/undefined check and ToPropertyKey. assignTo would run the
                // RHS first (its caller already evaluated it), tripping a key
                // `toString` / the base check before the RHS.
                if (a.target.* == .member) {
                    const m = a.target.member;
                    if (m.computed) |ce| {
                        const recv = try self.eval(m.object);
                        const kv = try self.eval(ce);
                        const v = try self.eval(a.value);
                        if (recv.isNull() or recv.isUndefined())
                            return self.throwError("TypeError", notAnObjectMessage(recv));
                        if (fastNumericIndex(kv)) |idx| {
                            if (try self.setFastArrayNumericIndex(recv, idx, v)) break :blk v;
                            var fast_key_buf: [24]u8 = undefined;
                            const key = std.fmt.bufPrint(&fast_key_buf, "{d}", .{idx}) catch unreachable;
                            try self.setMember(recv, key, v);
                        } else {
                            try self.setMember(recv, try self.keyOf(kv), v);
                        }
                        break :blk v;
                    } else {
                        // `obj.name = rhs`: evaluate the object (the MemberExpression)
                        // BEFORE the RHS, per spec order (PutValue runs after both).
                        // assignTo's member arm does the same [[Set]] — via setMember,
                        // so private/getter-setter/primitive semantics are unchanged —
                        // but only after the caller already evaluated the RHS.
                        const recv = try self.eval(m.object);
                        const v = try self.eval(a.value);
                        try self.setMember(recv, m.property, v);
                        break :blk v;
                    }
                }
                // `super[key] = value`: the SuperReference is created before the
                // RHS, so GetThisBinding/GetSuperBase and the computed expression
                // run first. ToPropertyKey(key) is part of PutValue, so it remains
                // after the RHS.
                if (a.target.* == .super_member) {
                    const m = a.target.super_member;
                    const home = self.home_object orelse return self.throwError("SyntaxError", "'super' outside a method");
                    if (!self.this_initialized) return self.throwError("ReferenceError", "Must call super constructor before using 'this'");
                    const key_val: ?Value = if (m.computed) |ce| try self.eval(ce) else null;
                    const parent = home.protoAtomic();
                    const v = try self.eval(a.value);
                    const parent_obj = parent orelse return self.throwError("TypeError", "Cannot set property of null (super)");
                    const key = if (key_val) |kv| try self.keyOf(kv) else m.property;
                    if (!try self.setMemberResult(Value.obj(parent_obj), key, v, self.this_value)) {
                        if (self.strict) return self.throwError("TypeError", "Cannot set property");
                    }
                    break :blk v;
                }
                // Resolve an identifier Reference before the RHS and retain its
                // exact base. This covers strict unresolvable references and
                // `with` Object Environment Records without a second HasBinding.
                const binding_reference: ?BindingReference = if (a.target.* == .identifier)
                    try self.captureBindingReference(a.target.identifier, null)
                else
                    null;
                const binding_reference_root: ?usize = if (binding_reference) |reference|
                    try self.pushTempBindingReferenceRoot(reference)
                else
                    null;
                defer if (binding_reference_root) |mark| self.restoreTempBindingReferenceRoots(mark);
                const v = try self.eval(a.value);
                // NamedEvaluation: `f = function(){}` names the function "f"
                // (only a bare, *unparenthesized* identifier target — a
                // parenthesized `(f) =` is not an IdentifierRef).
                if (a.target.* == .identifier and !a.target_parenthesized) try self.maybeNameAnon(v, a.value, a.target.identifier);
                if (binding_reference) |reference|
                    try self.storeCapturedBindingReference(
                        self.tempBindingReferenceRoot(binding_reference_root.?, reference),
                        a.target.identifier,
                        v,
                    )
                else
                    try self.assignTo(a.target, v);
                break :blk v;
            },

            // Compound assignment `target op= value`: resolve the LeftHandSide
            // reference ONCE, GetValue, then PutValue on the SAME reference.
            .op_assign => |oa| blk: {
                switch (oa.target.*) {
                    .identifier => |name| {
                        const reference = try self.captureBindingReference(name, null);
                        const reference_root = try self.pushTempBindingReferenceRoot(reference);
                        defer self.restoreTempBindingReferenceRoots(reference_root);
                        const old = (try self.loadCapturedBindingReference(
                            self.tempBindingReferenceRoot(reference_root, reference),
                            name,
                            false,
                        )).value;
                        const old_root = try self.pushTempRoot(old);
                        defer self.restoreTempRoots(old_root);
                        const rhs = try self.eval(oa.value);
                        const new = try self.applyBinary(oa.op, self.tempRoot(old_root, old), rhs);
                        try self.storeCapturedBindingReference(
                            self.tempBindingReferenceRoot(reference_root, reference),
                            name,
                            new,
                        );
                        break :blk new;
                    },
                    .member => |m| {
                        // The base (and a computed key expression) evaluate exactly
                        // once. Mirror a member read's order: the key expression is
                        // evaluated, then the null/undefined base is rejected BEFORE
                        // ToPropertyKey (so `null[obj.toString]` throws without
                        // calling toString), then the property key is formed.
                        const obj = try self.eval(m.object);
                        var fast_key_buf: [24]u8 = undefined;
                        const key: []const u8 = if (m.computed) |ce| blk2: {
                            const kv = try self.eval(ce);
                            if (m.optional and (obj.isNull() or obj.isUndefined())) break :blk Value.undef();
                            if (obj.isNull() or obj.isUndefined())
                                return self.throwError("TypeError", notAnObjectMessage(obj));
                            if (fastNumericIndex(kv)) |idx|
                                break :blk2 std.fmt.bufPrint(&fast_key_buf, "{d}", .{idx}) catch unreachable;
                            break :blk2 try self.keyOf(kv);
                        } else m.property;
                        const old = try self.getProperty(obj, key);
                        const rhs = try self.eval(oa.value);
                        const new = try self.applyBinary(oa.op, old, rhs);
                        try self.setMember(obj, key, new);
                        break :blk new;
                    },
                    .super_member => |m| {
                        // Logical assignment carries one SuperReference through
                        // GetValue, the short-circuit decision, and PutValue. A
                        // getter/RHS may mutate the method home's prototype, but
                        // the eventual write still targets this captured base.
                        const home = self.home_object orelse return self.throwError("SyntaxError", "'super' outside a method");
                        if (!self.this_initialized) return self.throwError("ReferenceError", "Must call super constructor before using 'this'");
                        const key_val: ?Value = if (m.computed) |ce| try self.eval(ce) else null;
                        const parent = home.protoAtomic() orelse return self.throwError("TypeError", "Cannot read property of null (super)");
                        const key = if (key_val) |kv| try self.keyOf(kv) else m.property;
                        const old = try self.getPropertyWithReceiver(Value.obj(parent), key, self.this_value);
                        const rhs = try self.eval(oa.value);
                        const new = try self.applyBinary(oa.op, old, rhs);
                        if (!try self.setMemberResult(Value.obj(parent), key, new, self.this_value)) {
                            if (self.strict) return self.throwError("TypeError", "Cannot set property");
                        }
                        break :blk new;
                    },
                    else => {
                        if (oa.target.* == .call) {
                            _ = try self.eval(oa.target);
                            return self.throwError("ReferenceError", "invalid assignment target");
                        }
                        // super.x etc.: the base is stable, so read + assignTo are safe.
                        const old = try self.eval(oa.target);
                        const rhs = try self.eval(oa.value);
                        const new = try self.applyBinary(oa.op, old, rhs);
                        try self.assignTo(oa.target, new);
                        break :blk new;
                    },
                }
            },

            .logical_assign => |la| blk: {
                // The LeftHandSide reference is resolved ONCE; the short-circuit
                // predicate then decides whether the RHS runs and the store
                // happens (so `obj[f()] &&= g()` evaluates `f()` once and skips
                // `g()` when the held value is falsy/truthy/non-nullish).
                switch (la.target.*) {
                    .identifier => |name| {
                        const reference = try self.captureBindingReference(name, null);
                        const reference_root = try self.pushTempBindingReferenceRoot(reference);
                        defer self.restoreTempBindingReferenceRoots(reference_root);
                        const old = (try self.loadCapturedBindingReference(
                            self.tempBindingReferenceRoot(reference_root, reference),
                            name,
                            false,
                        )).value;
                        const short = switch (la.op) {
                            .@"and" => !old.toBoolean(),
                            .@"or" => old.toBoolean(),
                            .nullish => !(old.isNull() or old.isUndefined()),
                        };
                        if (short) break :blk old;
                        const rhs = try self.eval(la.value);
                        try self.storeCapturedBindingReference(
                            self.tempBindingReferenceRoot(reference_root, reference),
                            name,
                            rhs,
                        );
                        break :blk rhs;
                    },
                    .member => |m| {
                        const obj = try self.eval(m.object);
                        var fast_key_buf: [24]u8 = undefined;
                        const key: []const u8 = if (m.computed) |ce| blk2: {
                            const kv = try self.eval(ce);
                            if (obj.isNull() or obj.isUndefined())
                                return self.throwError("TypeError", notAnObjectMessage(obj));
                            if (fastNumericIndex(kv)) |idx|
                                break :blk2 std.fmt.bufPrint(&fast_key_buf, "{d}", .{idx}) catch unreachable;
                            break :blk2 try self.keyOf(kv);
                        } else m.property;
                        const old = try self.getProperty(obj, key);
                        const short = switch (la.op) {
                            .@"and" => !old.toBoolean(),
                            .@"or" => old.toBoolean(),
                            .nullish => !(old.isNull() or old.isUndefined()),
                        };
                        if (short) break :blk old;
                        const rhs = try self.eval(la.value);
                        try self.setMember(obj, key, rhs);
                        break :blk rhs;
                    },
                    .super_member => |m| {
                        const home = self.home_object orelse return self.throwError("SyntaxError", "'super' outside a method");
                        if (!self.this_initialized) return self.throwError("ReferenceError", "Must call super constructor before using 'this'");
                        const key_val: ?Value = if (m.computed) |ce| try self.eval(ce) else null;
                        const parent = home.protoAtomic() orelse return self.throwError("TypeError", "Cannot read property of null (super)");
                        const key = if (key_val) |kv| try self.keyOf(kv) else m.property;
                        const old = try self.getPropertyWithReceiver(Value.obj(parent), key, self.this_value);
                        const short = switch (la.op) {
                            .@"and" => !old.toBoolean(),
                            .@"or" => old.toBoolean(),
                            .nullish => !(old.isNull() or old.isUndefined()),
                        };
                        if (short) break :blk old;
                        const rhs = try self.eval(la.value);
                        if (!try self.setMemberResult(Value.obj(parent), key, rhs, self.this_value)) {
                            if (self.strict) return self.throwError("TypeError", "Cannot set property");
                        }
                        break :blk rhs;
                    },
                    else => {
                        const old = try self.eval(la.target);
                        const short = switch (la.op) {
                            .@"and" => !old.toBoolean(),
                            .@"or" => old.toBoolean(),
                            .nullish => !(old.isNull() or old.isUndefined()),
                        };
                        if (short) break :blk old;
                        const rhs = try self.eval(la.value);
                        try self.assignTo(la.target, rhs);
                        break :blk rhs;
                    },
                }
            },

            .function => |fnode| blk: {
                // A *named* function expression binds its own name as an
                // immutable binding in a fresh scope enclosing the body, so the
                // body can refer to itself (recursion) and can't rebind the name.
                if (fnode.has_name_binding and !fnode.is_arrow) {
                    const fenv = try gc_mod.allocEnv(self.arena);
                    self.initEnvironment(fenv, self.env, false);
                    const fv = try self.makeFunction(fnode, fenv);
                    try fenv.putFnName(fnode.name, fv);
                    break :blk fv;
                }
                break :blk try self.makeFunction(fnode, self.env);
            },
            .class_expr => |c| try self.evalClass(c.name, c.inferred_name, c.superclass, c.members, c.source),

            // `yield` only executes inside a compiled generator body (on the
            // suspendable VM). Reaching it in the tree-walker means a generator
            // body fell outside the VM's lowered subset — report it clearly
            // rather than producing a wrong value.
            .yield_expr => return self.throwError("SyntaxError", "yield is only supported in VM-compiled generator bodies"),

            .await_expr => |a| try self.evalAwait(a.argument),

            .import_meta => try self.importMetaValue(),
            .import_call => |ic| try self.evalImportCall(ic.specifier, ic.options, ic.phase),

            .super_call => |sc| blk: {
                // `super()` is a SyntaxError outside a derived constructor — the
                // case the parser can't catch is eval'd code (`eval("super()")` in
                // global code, a method, or an arrow not enclosed by a derived
                // constructor). When it IS a derived constructor, a null super
                // constructor is `class … extends null`: GetSuperConstructor yields
                // %Function.prototype%, not a constructor → a runtime TypeError.
                if (!self.in_derived_ctor) return self.throwError("SyntaxError", "'super' keyword unexpected here");
                // GetSuperConstructor (the live [[Prototype]]) is read here, but its
                // IsConstructor check is DEFERRED until after ArgumentListEvaluation:
                // `super(sideEffect())` must evaluate the arguments even when the
                // super constructor turns out not to be a constructor. The live proto
                // is sourced dynamically: the active constructor's [[Prototype]] via
                // `active_function` when available (spec GetActiveFunction), else the
                // per-call `super_ctor` (set from the ctor's live proto on entry).
                const sup_opt: ?*value.Object = blk2: {
                    if (self.active_function) |fn_obj| if (fn_obj.jsFunction()) |erased| {
                        const active: *Function = @ptrCast(@alignCast(erased));
                        if (active.is_derived_constructor) break :blk2 self.effectiveProto(fn_obj);
                        if (active.derived_constructor) |owner| break :blk2 self.effectiveProto(owner);
                    };
                    break :blk2 self.super_ctor;
                };
                // A synthesized default derived constructor forwards its arguments
                // to the super constructor DIRECTLY — its `super(...args)` does not
                // run a user-observable spread, so a hijacked Array.prototype
                // @@iterator is never invoked. (`args` is its rest-parameter array.)
                const args = if (self.in_default_ctor) dblk: {
                    const av = self.env.get("args") orelse Value.undef();
                    break :dblk if (av.isObject() and av.asObj().is_array) try av.asObj().internalElementsSnapshot(self.arena) else &[_]Value{};
                } else try self.evalArgs(sc);
                // IsConstructor(superConstructor) AFTER the arguments are evaluated.
                const sup = sup_opt orelse return self.throwError("TypeError", "Super constructor null is not a constructor");
                if (!isConstructorValue(Value.obj(sup))) return self.throwError("TypeError", "Super constructor is not a constructor");
                // Construct the superclass with the most-derived class as NewTarget,
                // so the produced object's prototype is the derived class's.
                const sup_ret = try self.constructNT(Value.obj(sup), args, self.new_target);
                // BindThisValue: `super()` initializes `this` exactly once — a
                // second call (after the construct's side effects) is a ReferenceError.
                if (self.this_cell) |c| {
                    if (!c.bind(sup_ret)) return self.throwError("ReferenceError", "Super constructor may only be called once");
                } else if (self.this_initialized) return self.throwError("ReferenceError", "Super constructor may only be called once");
                // The object the super constructor produces (a built-in exotic from
                // `extends Map/Array/...`, or an object a JS base explicitly returns)
                // *becomes* the `this` binding — its prototype was already set from
                // new_target. Rebind `this` to it (the eagerly-allocated placeholder
                // is discarded); the field initializers / private brands below target it.
                self.this_value = sup_ret;
                self.this_initialized = true;
                // InitializeInstanceElements: a derived class brands `this` with
                // its private names and runs its field initializers now, once
                // `super()` has returned and `this` exists. Clear the pending sets
                // so they apply exactly once.
                const bns = self.pending_brand_names;
                self.pending_brand_names = &.{};
                if (self.this_value.isObject())
                    for (bns) |bn| try self.addPrivateMethodOrAccessorChecked(self.this_value.asObj(), self.home_object, bn);
                const fis = self.pending_field_inits;
                self.pending_field_inits = &.{};
                for (fis) |fi| _ = try self.eval(fi);
                // SuperCall evaluates to the new `this` (BindThisValue's result),
                // so `value = super()` observes the bound object.
                break :blk self.this_value;
            },
            .super_member => |m| blk: {
                const home = self.home_object orelse return self.throwError("SyntaxError", "'super' outside a method");
                // GetThisBinding (SuperProperty step 2) precedes evaluating the
                // property key (step 3): in a derived constructor before `super()`,
                // `super[expr]` / `super.x` is a ReferenceError and `expr` never runs.
                if (!self.this_initialized) return self.throwError("ReferenceError", "Must call super constructor before using 'this'");
                const key_val: ?Value = if (m.computed) |ce| try self.eval(ce) else null;
                // Computed SuperProperty evaluates the key expression before
                // MakeSuperPropertyReference checks the current super base, but
                // ToPropertyKey is deferred until GetValue below.
                const parent = home.protoAtomic() orelse return self.throwError("TypeError", "Cannot read property of null (super)");
                const key = if (key_val) |kv| try self.keyOf(kv) else m.property;
                break :blk try self.getPropertyWithReceiver(Value.obj(parent), key, self.this_value);
            },

            .call => |c| try self.evalCall(c.callee, c.args, c.optional),
            .tagged_template => |t| try self.evalTaggedTemplate(node, t.tag, t.exprs),
            .new_expr => |n| try self.evalNew(n.callee, n.args),
            .member => |m| blk: {
                const obj = try self.eval(m.object);
                if (m.optional and (obj.isNull() or obj.isUndefined())) return error.OptShortCircuit;
                if (m.computed) |ce| {
                    // Spec order: GetValue of the key expression first (its side
                    // effects run), THEN the null/undefined base check, THEN
                    // ToPropertyKey — so `base[prop()]` with a throwing `prop()`
                    // surfaces that throw, while `null[obj]` is a TypeError before
                    // the key's `toString` is ever called.
                    const kv = try self.eval(ce);
                    if (obj.isNull() or obj.isUndefined())
                        return self.throwError("TypeError", notAnObjectMessage(obj));
                    var fast_key_buf: [24]u8 = undefined;
                    const key = if (fastNumericIndex(kv)) |idx|
                        std.fmt.bufPrint(&fast_key_buf, "{d}", .{idx}) catch unreachable
                    else
                        try self.keyOf(kv);
                    break :blk try self.getProperty(obj, key);
                }
                break :blk try self.getProperty(obj, m.property);
            },
            .optional_chain => |inner| self.eval(inner) catch |e|
                if (e == error.OptShortCircuit) Value.undef() else return e,
            .field_init_value => |inner| blk: {
                // Evaluate a class instance field initializer with the
                // field-initializer context active, so a direct eval inside it
                // inherits the `super()`/`arguments` early errors.
                const saved_fi = self.in_field_initializer;
                self.in_field_initializer = true;
                defer self.in_field_initializer = saved_fi;
                break :blk try self.eval(inner);
            },
            .private_field_def => |d| blk: {
                // PrivateFieldAdd: brand `this` with this field's name (in
                // declaration order) as an own, writable, non-enumerable,
                // non-configurable property. Per DefineField, the initializer is
                // evaluated FIRST and PrivateFieldAdd (the brand + the
                // extensibility check + the store) happens AFTER — so a field
                // whose initializer seals `this` (`#g = (preventExtensions(this),
                // …)`) makes its own add throw, and a field cannot reference itself.
                const fv = try self.eval(d.value);
                // An anonymous initializer takes the field's source name (`#x`,
                // the part of the storage key before the NUL marker).
                const raw_init = if (d.value.* == .field_init_value) d.value.field_init_value else d.value;
                try self.maybeNameAnon(fv, raw_init, std.mem.sliceTo(d.name, 0));
                if (self.this_value.isObject())
                    try self.initializePrivateClassField(self.this_value.asObj(), d.name, fv);
                break :blk Value.undef();
            },
            .object_lit => |props| try self.evalObjectLit(props),
            .array_lit => |elems| try self.evalArrayLit(elems),
            .regex_literal => |r| try self.makeRegex(r.pattern, r.flags),
            // Spreads are consumed by array/argument evaluation, never on their own.
            .spread => return self.throwError("SyntaxError", "unexpected spread element"),
            // Patterns are binding targets, not expressions.
            .obj_pattern, .arr_pattern => return self.throwError("SyntaxError", "unexpected destructuring pattern"),

            .conditional => |c| if ((try self.eval(c.cond)).toBoolean())
                try self.eval(c.consequent)
            else
                try self.eval(c.alternate),

            .var_decl => |d| blk: {
                // ResolveBinding happens BEFORE the Initializer is evaluated:
                // for a `var x = init` whose name a `with` object provides,
                // capture that target object first, so a side effect in the
                // initializer (e.g. `delete obj.x`) can't retarget the write.
                const binding_reference: ?BindingReference = if (d.kind == .@"var" and d.init != null)
                    try self.captureBindingReference(d.name, null)
                else
                    null;
                const binding_reference_root = try self.pushOptionalBindingReferenceRoot(binding_reference);
                defer if (binding_reference_root) |mark| self.restoreTempBindingReferenceRoots(mark);
                var v: Value = Value.undef();
                if (d.init) |init_node| {
                    v = try self.eval(init_node);
                    try self.maybeNameAnon(v, init_node, d.name); // `var f = function(){}` ⇒ name "f"
                }
                // `var` hoists to the variable scope (and mirrors onto the global
                // object); `let`/`const` bind in the current (possibly block) scope.
                if (d.kind == .@"var") {
                    // A `var x = init` inside a `with` whose object provides `x`
                    // assigns the initializer to that object (ResolveBinding walks
                    // the object Environment Record), leaving the hoisted var
                    // binding untouched — exactly like a bare `x = init`. Without
                    // an initializer, or when no `with` shadows the name, the var
                    // scope binding takes the value as before.
                    if (d.init != null) {
                        if (self.tempOptionalBindingReferenceRoot(binding_reference_root, binding_reference)) |reference|
                            try self.storeCapturedBindingReference(reference, d.name, v)
                        else
                            try self.globalDefine(d.name, v);
                    }
                    // A bare `var x;` (no initializer) is a runtime no-op: the
                    // binding already exists from declaration instantiation
                    // (hoistVarNames runs at the var scope before the body). Calling
                    // globalDefine here would clobber a prior value (`var x=5; var x;`
                    // ⇒ 5, not undefined) and resurrect a binding a preceding
                    // `delete` removed (a sloppy eval's deletable var).
                } else if (d.kind == .@"const") {
                    try self.checkRestrictedGlobalLexical(d.name);
                    try self.env.putConst(d.name, v);
                } else {
                    try self.checkRestrictedGlobalLexical(d.name);
                    try self.env.put(d.name, v);
                }
                // A `using`/`await using` binding registers its resource for
                // disposal when the enclosing scope exits.
                if (d.dispose != 0) try self.addDisposable(v, d.dispose == 2);
                break :blk Value.undef();
            },

            .func_decl => |fnode| blk: {
                // Reached only for a function declaration that is the *bare* body
                // of an `if`/loop/label (a function in a statement list is hoisted
                // by `evalStatements`, not evaluated here). Annex B B.3.3 treats it
                // as block-scoped: it creates the legacy var binding only when the
                // name is eligible; otherwise the binding is purely local (and dies
                // with the statement, so nothing leaks to the enclosing scope).
                const block_env = try gc_mod.allocEnv(self.arena);
                self.initEnvironment(block_env, self.env, false);
                const saved_env = self.env;
                self.env = block_env;
                defer self.env = saved_env;
                const fnv = try self.makeFunction(fnode, block_env);
                try block_env.put(fnode.name, fnv);
                if (self.annexb_legacy_nodes) |set| {
                    if (set.contains(node)) try self.globalDefineDeletable(fnode.name, fnv);
                }
                break :blk Value.undef();
            },

            // Module declarations. Import bindings are wired during linking
            // (`Context.linkModule`), so an `import` is a runtime no-op. An
            // `export` evaluates its inner declaration/expression so the local
            // bindings exist; the module's export map (built at link time) reads
            // those bindings live from the module environment.
            .import_decl => Value.undef(),
            .export_decl => |e| blk: {
                if (e.declaration) |d| break :blk try self.eval(d);
                if (e.default_expr) |dx| {
                    const v = switch (dx.*) {
                        // `export default function/class` — a named or anonymous
                        // declaration whose value binds to the synthetic "*default*"
                        // (and its own name, when present, for self-reference).
                        .func_decl => |fnode| try self.makeFunction(fnode, self.env),
                        .function => |fnode| if (fnode.is_default_export_decl) try self.makeFunction(fnode, self.env) else try self.eval(dx),
                        .class_expr => |c| try self.evalClass(
                            c.name,
                            if (c.name.len > 0 or c.inferred_name.len > 0) c.inferred_name else "default",
                            c.superclass,
                            c.members,
                            c.source,
                        ),
                        else => try self.eval(dx),
                    };
                    if (e.default_name.len > 0) {
                        try self.env.put(e.default_name, v);
                    } else if (v.isObject()) {
                        // `export default function(){}` / `class{}` / arrow / other
                        // anonymous AssignmentExpression: NamedEvaluation names it
                        // "default".
                        try self.maybeNameAnon(v, dx, "default");
                    }
                    try self.env.put("*default*", v);
                    break :blk Value.undef();
                }
                break :blk Value.undef(); // `export { … }` / `export * …`: no runtime effect
            },

            .destructure_decl => |d| blk: {
                const v = try self.eval(d.init);
                const saved = self.binding_hoisted;
                const saved_c = self.binding_const;
                self.binding_hoisted = (d.kind == .@"var");
                self.binding_const = (d.kind == .@"const");
                defer self.binding_hoisted = saved;
                defer self.binding_const = saved_c;
                try self.bindPattern(d.pattern, v, true);
                break :blk Value.undef();
            },

            .return_stmt => |maybe| blk: {
                if (maybe) |e| {
                    if (self.tree_tail_allowed) {
                        if (try self.prepareTreeTailCall(e)) |v| {
                            self.ret_value = v;
                            self.signal = .ret;
                            break :blk v;
                        }
                    }
                }
                const v: Value = if (maybe) |e| try self.eval(e) else Value.undef();
                self.ret_value = v;
                self.signal = .ret;
                break :blk v;
            },

            .throw_stmt => |e| {
                self.exception = try self.eval(e);
                try self.notifyDebuggerException(false);
                return error.Throw;
            },

            .try_stmt => |t| try self.evalTry(t),

            .break_stmt => |label| blk: {
                self.signal = .brk;
                self.signal_label = label;
                break :blk Value.undef();
            },
            .continue_stmt => |label| blk: {
                self.signal = .cont;
                self.signal_label = label;
                break :blk Value.undef();
            },
            .labeled_stmt => |l| blk: {
                const saved_labels_len = self.current_labels.items.len;
                const saved_labels_consumed = self.labels_consumed;
                if (labeledStatementTargetsIteration(l.body)) try self.current_labels.append(self.arena, l.label);
                defer {
                    self.current_labels.items.len = saved_labels_len;
                    self.labels_consumed = saved_labels_consumed;
                }
                const result = try self.eval(l.body);
                // A labeled break that reached here (e.g. on a labeled block) is consumed.
                if (self.signal == .brk and labelEq(self.signal_label, l.label)) {
                    self.signal = .none;
                    self.signal_label = null;
                }
                break :blk result;
            },

            .expr_stmt => |e| try self.eval(e),
            .debugger_stmt => Value.undef(),

            // A `{…}` block is its own lexical scope: `let`/`const`/`class` and
            // block function declarations live here, `var` hoists past it; any
            // `using` resources are disposed when it exits.
            .block => |stmts| try self.evalBlockScope(stmts),
            // A multi-declarator group runs in the current scope (no new block).
            .decl_group => |stmts| try self.evalStatements(stmts),
            .program => |stmts| blk: {
                // GlobalDeclarationInstantiation early errors run once per Script,
                // here at the program root — NOT inside evalStatements, which is
                // re-entered for `decl_group`s (`let a, b`) in the same scope.
                try self.checkGlobalDeclConflicts(stmts);
                break :blk try self.evalStatements(stmts);
            },

            .if_stmt => |s| if ((try self.eval(s.cond)).toBoolean())
                try self.eval(s.consequent)
            else if (s.alternate) |alt|
                try self.eval(alt)
            else
                Value.undef(),

            .with_stmt => |w| blk: {
                // The binding object is ToObject(expr): a primitive is boxed,
                // null/undefined throw — only those throw, not every non-object.
                const obj = try self.toObject(try self.eval(w.obj));
                // Push an object Environment Record onto the lexical chain. A
                // function defined in the body captures it via its closure, and a
                // binding declared inside the body shadows it — both fall out of
                // the chain position automatically.
                const wenv = try gc_mod.allocEnv(self.arena);
                self.initEnvironment(wenv, self.env, false);
                wenv.with_object = obj;
                const saved_env = self.env;
                self.env = wenv;
                defer self.env = saved_env;
                break :blk try self.eval(w.body);
            },
            .while_stmt => |s| try self.evalWhile(s.cond, s.body),
            .do_while_stmt => |s| blk: {
                const my_labels = self.takeLabels();
                var last: Value = Value.undef();
                while (true) {
                    last = try self.eval(s.body);
                    if (self.loopSignal(my_labels)) |stop| if (stop) break;
                    if (!(try self.eval(s.cond)).toBoolean()) break;
                }
                break :blk last;
            },
            .for_stmt => |f| try self.evalFor(f.init, f.cond, f.update, f.body),
            .switch_stmt => |s| try self.evalSwitch(s.disc, s.cases),
            .for_in => |f| try self.evalForInOf(f.decl_kind, f.target, f.var_init, f.iterable, f.body, f.is_of, f.is_await, f.dispose),
        };
    }

    pub fn lockDebugRegistry(self: *Interpreter) void {
        if (self.debug_registry_lock) |registry| registry.lockProfiled(self.debug_registry_stats);
    }

    pub fn unlockDebugRegistry(self: *Interpreter) void {
        if (self.debug_registry_lock) |registry| registry.unlock();
    }

    pub fn debugStatementLocation(self: *Interpreter, node: *const Node) ?DebugStatementLocation {
        const set_index = debugLocationCacheSetIndex(node);
        const set = &self.debug_location_cache[set_index];
        var first_empty: ?usize = null;
        for (set, 0..) |*cached, way| {
            if (cached.node == node) {
                if (builtin.is_test) self.debug_location_cache_hits += 1;
                if (self.debug_registry_stats) |stats| _ = stats.location_cache_hits.fetchAdd(1, .monotonic);
                return cached.location;
            }
            if (cached.node == null and first_empty == null) first_empty = way;
        }

        const locations = self.debug_statement_locations orelse return null;
        if (self.debug_registry_stats) |stats| _ = stats.location_cache_misses.fetchAdd(1, .monotonic);
        const location = blk: {
            self.lockDebugRegistry();
            defer self.unlockDebugRegistry();
            break :blk locations.get(node);
        };
        const replacement = first_empty orelse self.debug_location_cache_next[set_index];
        set[replacement] = .{ .node = node, .location = location };
        self.debug_location_cache_next[set_index] = @intCast((replacement + 1) % debug_location_cache_way_count);
        if (builtin.is_test) self.debug_location_cache_misses += 1;
        return location;
    }

    pub fn serviceDebugStatement(self: *Interpreter, node: *const Node) EvalError!void {
        // The parser registry contains only parseStatement roots. Avoid letting
        // guaranteed-negative expression/Program probes evict real statements
        // from the bounded interpreter-local debugger cache.
        const location = if (parser_mod.canPublishStatementLocation(node))
            self.debugStatementLocation(node)
        else
            null;
        if (location != null) self.serviceMutatorStopSafepoint();
        if (self.host_statement_hook) |hook| hook(self.host_statement_ctx.?, self);
        if (location) |statement_location| {
            self.debug_current_location = statement_location;
            if (self.stack_trace_call_frame) |frame| frame.location = statement_location;
            if (self.debug_statement_hook) |hook| {
                if (self.debug_call_frame) |frame| {
                    if (!frame.environment_is_vm_activation) frame.environment = self.env;
                    frame.this_value = self.this_value;
                    frame.location = statement_location;
                } else {
                    self.debug_top_level_location = statement_location;
                    self.debug_top_level_environment = self.env;
                    self.debug_top_level_strict = self.strict;
                }
                try hook(self.debug_statement_ctx.?, self, statement_location);
            }
            if (self.profile_statement_hook) |hook|
                hook(self.profile_statement_ctx.?, self, statement_location);
        }
    }

    pub fn registerParsedDebugScript(self: *Interpreter, source: []const u8, url: []const u8, start_line: usize, parser: *const Parser) EvalError!void {
        const hook = self.debug_script_hook orelse return;
        _ = try hook(
            self.debug_script_ctx.?,
            source,
            url,
            start_line,
            parser.statement_locations.items,
        );
    }

    pub fn registerParsedDynamicDebugScript(self: *Interpreter, source: []const u8, fallback_url: []const u8, start_line: usize, parser: *const Parser) EvalError!void {
        return self.registerParsedDebugScript(
            source,
            self.debug_dynamic_url_override orelse dynamicDebugSourceUrl(source, fallback_url),
            if (self.debug_dynamic_url_override != null) self.debug_dynamic_start_line else start_line,
            parser,
        );
    }

    /// Evaluate debugger-authored source in a paused frame's live lexical
    /// environment. The caller preserves/restores the pending exception because
    /// exception pauses may already have one; this helper isolates evaluator
    /// control state and suppresses recursive debugger stops while the command
    /// itself runs.
    pub fn evaluateForDebugger(self: *Interpreter, source: []const u8, environment: *Environment, this_value: Value, strict: bool) EvalError!Value {
        // Functions/classes created by the command retain AST slices into the
        // parser input after this call returns. Match Context evaluation's
        // ownership boundary instead of borrowing the debugger transport buffer.
        const owned_source = try self.arena.dupe(u8, source);
        var lex_diagnostic: ?parser_mod.SourceLocation = null;
        var parser = Parser.initWithScratchDiagnostic(self.arena, self.scratch_allocator orelse self.arena, owned_source, &lex_diagnostic) catch |err|
            return self.throwParserSyntaxErrorAt("debugger evaluation", lex_diagnostic orelse parser_mod.sourceLocationAt(owned_source, 0), err);
        parser.useRealmHashKeys(self.root_shape);
        parser.strict = strict;
        const program = parser.parseProgram() catch |err| return self.throwParserSyntaxError("debugger evaluation", owned_source, &parser, err);

        const saved_env = self.env;
        const saved_this = self.this_value;
        const saved_strict = self.strict;
        const saved_signal = self.signal;
        const saved_signal_label = self.signal_label;
        const saved_ret = self.ret_value;
        const saved_statement_hook = self.debug_statement_hook;
        const saved_exception_hook = self.debug_exception_hook;
        self.env = environment;
        self.this_value = this_value;
        self.strict = strict;
        self.signal = .none;
        self.signal_label = null;
        self.ret_value = Value.undef();
        self.debug_statement_hook = null;
        self.debug_exception_hook = null;
        defer {
            self.env = saved_env;
            self.this_value = saved_this;
            self.strict = saved_strict;
            self.signal = saved_signal;
            self.signal_label = saved_signal_label;
            self.ret_value = saved_ret;
            self.debug_statement_hook = saved_statement_hook;
            self.debug_exception_hook = saved_exception_hook;
        }
        if (program.* == .program) try self.hoistVarNames(program.program);
        return self.eval(program);
    }

    /// `for-of` (values of arrays/strings) and `for-in` (own keys of objects /
    /// indices of arrays). Each iteration binds the loop variable then runs the
    /// body, honoring break/continue/return.
    fn evalForInOf(self: *Interpreter, decl_kind: ?ast.DeclKind, target: *Node, var_init: ?*Node, iterable: *Node, body: *Node, is_of: bool, is_await: bool, dispose: u8) EvalError!Value {
        const my_labels = self.takeLabels();
        // A `let`/`const` loop binding gets a fresh declarative environment per
        // iteration, so a closure created in the head or body captures *that*
        // iteration's binding (`var` is function-scoped, so it doesn't).
        const lexical = decl_kind != null and decl_kind.? != .@"var";
        const outer_env = self.env;
        if (var_init) |ini| {
            const init_value = try self.eval(ini);
            try self.bindLoopTarget(decl_kind, target, init_value);
        }
        // Head evaluation: per spec the loop bindings are declared (in their TDZ)
        // in a fresh environment while the iterable expression runs, so a closure
        // captured there sees them uninitialized (`typeof x` throws).
        var iter: Value = undefined;
        if (lexical and self.tdz_marker != null) {
            const head_env = try gc_mod.allocEnv(self.arena);
            self.initEnvironment(head_env, outer_env, false);
            self.env = head_env;
            self.tdzBindPattern(target, self.tdzVal());
            iter = self.eval(iterable) catch |e| {
                self.env = outer_env;
                return e;
            };
            self.env = outer_env;
        } else {
            iter = try self.eval(iterable);
        }
        var last: Value = Value.undef();
        if (is_of) {
            // Generic iterator protocol: obtain the iterator (generators are
            // their own; arrays/strings get an index cursor; a user object's
            // `[Symbol.iterator]()` is honored), then pull `.next()` until done.
            // `for await`: the async iterator (Symbol.asyncIterator, else a sync
            // iterator) and each `next()` result is awaited.
            const sync_record: ?IteratorRecord = if (is_await) null else try self.getIteratorRecord(iter);
            const iter_obj = if (sync_record) |record| record.iterator else try self.asyncIteratorOf(iter);
            const iter_root = try self.pushTempRoot(iter_obj);
            defer self.restoreTempRoots(iter_root);
            // GetIterator reads the iterator's `next` method exactly ONCE (it
            // becomes the Iterator Record's [[NextMethod]]); IteratorNext reuses
            // it. A `next` accessor must therefore not be re-read per iteration.
            const next_method = if (sync_record) |record| record.next_method else try self.getProperty(iter_obj, "next");
            const next_root = try self.pushTempRoot(next_method);
            defer self.restoreTempRoots(next_root);
            var ienv: IterEnvState = .{};
            const iter_env_mark = self.gc_env_roots.items.len;
            defer self.gc_env_roots.shrinkRetainingCapacity(iter_env_mark);
            while (true) {
                const res0 = try self.callValueWithThis(next_method, &.{}, iter_obj);
                const res0_root = try self.pushTempRoot(res0);
                defer self.restoreTempRoots(res0_root);
                const res = if (is_await) try self.awaitValue(res0) else res0;
                const res_root = try self.pushTempRoot(res);
                defer self.restoreTempRoots(res_root);
                // IteratorNext: the result of `next()` must be an Object (a Symbol
                // or BigInt is object-tagged here but is not an Object per Type()).
                if (!builtins.isRealObject(res)) return self.throwError("TypeError", "iterator result is not an object");
                if ((try self.getProperty(res, "done")).toBoolean()) break; // exhausted — no close
                const saved_env = self.env;
                defer self.env = saved_env;
                // The per-iteration env also holds a `for (using x of …)` resource,
                // disposed (DisposeResources) at the END of each iteration — so a
                // `using` loop (`dispose != 0`) must get a fresh env each iteration
                // (no reuse); otherwise the env is reused in place while uncaptured.
                var iter_env: ?*Environment = null;
                if (lexical) {
                    const e = try self.iterBindingEnv(&ienv, saved_env, dispose == 0);
                    self.env = e;
                    iter_env = e;
                }
                // Binding/assigning the loop target is also an abrupt-completion
                // close site: if PutValue or a destructuring assignment throws
                // (e.g. a setter on `for (x.attr of it)`), IteratorClose runs
                // before the error propagates. (IteratorValue itself — the
                // `.value` get — does NOT close, so it stays outside the catch.)
                const next_value = try self.getProperty(res, "value");
                self.bindLoopTarget(decl_kind, target, next_value) catch |e| {
                    if (is_await) self.asyncIteratorCloseKeepingThrow(iter_obj) else self.iteratorCloseKeepingThrow(iter_obj);
                    return e;
                };
                // `for (using/await using x of …)`: register the bound resource for
                // disposal at the end of this iteration.
                if (dispose != 0) self.addDisposable(next_value, dispose == 2) catch |e| {
                    if (is_await) self.asyncIteratorCloseKeepingThrow(iter_obj) else self.iteratorCloseKeepingThrow(iter_obj);
                    return e;
                };
                // A throw in the body closes the iterator before propagating. On a
                // throw completion any error from IteratorClose is discarded AND the
                // original thrown value is preserved (iteratorClose can overwrite
                // `self.exception` via a throwing `return`/get-method).
                last = self.eval(body) catch |e| {
                    if (e == error.Throw) if (iter_env) |ie| if (ie.disposables.items.len > 0) {
                        const body_err = self.exception;
                        if (self.disposeScope(ie, body_err) catch null) |de| self.exception = de;
                    };
                    if (is_await) self.asyncIteratorCloseKeepingThrow(iter_obj) else self.iteratorCloseKeepingThrow(iter_obj);
                    return e;
                };
                // DisposeResources at the end of a normal iteration; a disposal error
                // is a throw completion that also closes the iterator.
                if (iter_env) |ie| if (ie.disposables.items.len > 0) {
                    if (try self.disposeScope(ie, null)) |de| {
                        self.exception = de;
                        if (is_await) self.asyncIteratorCloseKeepingThrow(iter_obj) else self.iteratorCloseKeepingThrow(iter_obj);
                        return error.Throw;
                    }
                };
                // `break`/`return` (an abrupt loop exit) also closes the iterator.
                // Unlike the throw case above, this is a normal/return completion,
                // so an error from IteratorClose (a non-callable `return`, or a
                // `return()` that yields a non-object) PROPAGATES rather than being
                // swallowed.
                if (self.loopSignal(my_labels)) |stop| if (stop) {
                    const ss = self.signal;
                    const sr = self.ret_value;
                    self.signal = .none;
                    if (is_await) try self.asyncIteratorClose(iter_obj) else try self.iteratorClose(iter_obj);
                    self.signal = ss;
                    self.ret_value = sr;
                    break;
                };
            }
        } else {
            // for-in: enumerate keys (skip null/undefined per spec, ToObject any
            // other primitive — e.g. a string's character indices).
            switch (iter.kind()) {
                .undefined, .null => {}, // iterating null/undefined is a no-op
                else => {
                    const o = try self.toObject(iter);
                    var ienv: IterEnvState = .{};
                    const iter_env_mark = self.gc_env_roots.items.len;
                    defer self.gc_env_roots.shrinkRetainingCapacity(iter_env_mark);
                    // EnumerateObjectProperties: own + inherited enumerable string
                    // keys with prototype-chain shadowing (see forInKeyList).
                    for (try self.forInKeyList(o)) |k| {
                        // A property deleted (or made non-enumerable) before it is
                        // reached must not be visited: the key list is a snapshot,
                        // so re-check the property still exists on the chain.
                        if (!try self.hasPropertyResult(o, k)) continue;
                        const saved_env = self.env;
                        defer self.env = saved_env;
                        // for-in has no per-iteration `using` resource, so the
                        // binding env is always reusable while uncaptured.
                        if (lexical) self.env = try self.iterBindingEnv(&ienv, saved_env, true);
                        try self.bindLoopTarget(decl_kind, target, try Value.strAlloc(self.arena, value.decodeStringKey(k)));
                        last = try self.eval(body);
                        if (self.loopSignal(my_labels)) |stop| if (stop) break;
                    }
                },
            }
        }
        return last;
    }

    /// EnumerateObjectProperties: the ordered string keys visited by `for-in`,
    /// walking the prototype chain. A key is emitted once (the first time it is
    /// seen on the chain); a shadowing own property — enumerable or not —
    /// suppresses any same-named property further up. Array dense element indices
    /// (skipping holes) are own enumerable keys outside the shape. Symbol/private
    /// keys are excluded.
    pub fn forInKeyList(self: *Interpreter, start: *value.Object) EvalError![]const []const u8 {
        var out: std.ArrayListUnmanaged([]const u8) = .empty;
        const scratch = self.scratch_allocator orelse self.arena;
        var visited: SecureStringMembership = .{};
        defer visited.deinit(scratch);
        var cur: ?*value.Object = start;
        while (cur) |o| {
            // A String wrapper's own enumerable character indices "0".."len-1".
            if (o.boxedPrimitive()) |p| if (p.isString()) {
                const plen = utf16LenOfValue(p);
                var i: usize = 0;
                while (i < plen) : (i += 1) {
                    const key = try std.fmt.allocPrint(self.arena, "{d}", .{i});
                    if (try visited.getOrPutSecure(self, scratch, key)) continue;
                    try out.append(self.arena, key);
                }
            };
            const dense_len = o.elementsLen();
            if (o.is_array or dense_len != 0) {
                var i: usize = 0;
                while (i < dense_len) : (i += 1) {
                    if (!o.denseElementPresent(i)) continue;
                    const key = try std.fmt.allocPrint(self.arena, "{d}", .{i});
                    // Accessor at this index comes from ownKeys below.
                    if (o.getAccessor(key) != null) continue;
                    if (try visited.getOrPutSecure(self, scratch, key)) continue;
                    if (o.getAttr(key).enumerable) try out.append(self.arena, key);
                }
            }
            // A TypedArray's integer-indexed elements are own enumerable keys
            // (outside the shape); enumerate the current length (which a resizable
            // backing buffer may have shrunk or grown).
            if (o.typedArray()) |ta| {
                var i: usize = 0;
                const len = ta.currentLength() orelse 0;
                while (i < len) : (i += 1) {
                    const key = try std.fmt.allocPrint(self.arena, "{d}", .{i});
                    if (try visited.getOrPutSecure(self, scratch, key)) continue;
                    try out.append(self.arena, key);
                }
            }
            const own_keys = if (o.proxyHandler() != null or o.proxy_revoked or o.moduleNs() != null)
                try self.objectOwnKeysList(o)
            else
                try o.ownKeysWithScratch(self.arena, self.scratch_allocator orelse self.arena);
            for (own_keys) |k| {
                if (value.isRealSymbolKey(k) or value.isHiddenInternalKey(k) or value.isPrivateKey(k)) continue;
                if (try visited.getOrPutSecure(self, scratch, k)) continue;
                const enumerable = if (moduleNsOf(o) != null) blk: {
                    const desc = try moduleNsDesc(self, o, k);
                    break :blk desc.isObject() and if (desc.asObj().getOwn("enumerable")) |e| e.toBoolean() else false;
                } else if (o.proxyHandler() != null or o.proxy_revoked) blk: {
                    const desc = try builtins.objectGetOwnPropertyDescriptor(@ptrCast(self), Value.undef(), &.{ Value.obj(o), try self.keyToValue(k) });
                    break :blk desc.isObject() and if (desc.asObj().getOwn("enumerable")) |e| e.toBoolean() else false;
                } else o.getAttr(k).enumerable;
                if (enumerable) try out.append(self.arena, k);
            }
            cur = o.protoAtomic();
        }
        return out.items;
    }

    /// JavaScriptCore's `JSObjectCopyPropertyNames` snapshot: enumerable string
    /// names from the object and its prototype chain, with first occurrence
    /// winning. Unlike language `for-in`, host `getPropertyNames` callback keys
    /// participate through the host-class own-key bridge.
    pub fn cApiPropertyNameSnapshot(self: *Interpreter, start: *value.Object) EvalError![]const []const u8 {
        var out: std.ArrayListUnmanaged([]const u8) = .empty;
        const scratch = self.scratch_allocator orelse self.arena;
        var visited: SecureStringMembership = .{};
        defer visited.deinit(scratch);
        var cur: ?*value.Object = start;
        while (cur) |object| {
            for (try self.objectOwnKeysList(object)) |key| {
                if (value.isRealSymbolKey(key) or value.isHiddenInternalKey(key) or value.isPrivateKey(key)) continue;
                if (try visited.getOrPutSecure(self, scratch, key)) continue;
                const enumerable = if (moduleNsOf(object) != null) blk: {
                    const desc = try moduleNsDesc(self, object, key);
                    break :blk desc.isObject() and if (desc.asObj().getOwn("enumerable")) |entry| entry.toBoolean() else false;
                } else if (object.proxyHandler() != null or object.proxy_revoked) blk: {
                    const desc = try builtins.objectGetOwnPropertyDescriptor(@ptrCast(self), Value.undef(), &.{ Value.obj(object), try self.keyToValue(key) });
                    break :blk desc.isObject() and if (desc.asObj().getOwn("enumerable")) |entry| entry.toBoolean() else false;
                } else try self.enumerableOwnPropertyResult(object, key);
                if (enumerable) try out.append(self.arena, key);
            }
            cur = object.protoAtomic();
        }
        return out.items;
    }

    pub const ForInPreparation = struct {
        target: Value,
        keys: Value,
    };

    /// Prepare the VM's private for-in operand-stack state. The target is boxed
    /// exactly once per ForIn/OfHeadEvaluation and the fresh dense key array is
    /// never exposed to JavaScript or driven through the iterator protocol.
    pub fn prepareForIn(self: *Interpreter, v: Value) EvalError!ForInPreparation {
        const arr = (try self.newArray()).asObj();
        // ForIn/OfHeadEvaluation: undefined/null enumerate nothing; any other
        // value is ToObject'd first (so a primitive string yields its indices).
        if (v.isUndefined() or v.isNull()) return .{ .target = v, .keys = Value.obj(arr) };
        const target = try self.toObject(v);
        for (try self.forInKeyList(target)) |k|
            try arr.appendElement(self.arena, try Value.strAlloc(self.arena, value.decodeStringKey(k)));
        return .{ .target = Value.obj(target), .keys = Value.obj(arr) };
    }

    /// Bind one iteration's value to the loop target: a declaration declares
    /// (identifier or destructuring pattern), an assignment form assigns to an
    /// existing identifier / member / pattern.
    fn bindLoopTarget(self: *Interpreter, decl_kind: ?ast.DeclKind, target: *Node, v: Value) EvalError!void {
        if (decl_kind) |k| {
            if (k == .@"var") return self.assignTo(target, v);
            const saved = self.binding_const;
            self.binding_const = (k == .@"const");
            defer self.binding_const = saved;
            try self.bindPattern(target, v, true);
        } else try self.assignTo(target, v);
    }

    /// `switch`: evaluate the discriminant, find the first strictly-equal `case`
    /// (or `default`), then run from there with fall-through until a `break`.
    fn evalSwitch(self: *Interpreter, disc_node: *Node, cases: []ast.SwitchCase) EvalError!Value {
        // The discriminant evaluates in the enclosing scope; the whole CaseBlock
        // is then one lexical (declarative) environment, so a `let`/`const`/class
        // in any case is block-scoped to the switch (and case-test expressions
        // evaluate within it).
        const disc = try self.eval(disc_node);
        // The CaseBlock is its own lexical environment only if some case declares a
        // block-scoped binding (let/const/class/function/using). When none does,
        // the cases run in the enclosing scope with no per-switch env allocation
        // (the hoisting/TDZ instantiation below would be a no-op anyway).
        var switch_needs_env = false;
        for (cases) |c| if (blockNeedsOwnScope(c.body)) {
            switch_needs_env = true;
            break;
        };
        const saved_env = self.env;
        defer self.env = saved_env;
        var block_env: ?*Environment = null;
        if (switch_needs_env) {
            const be = try gc_mod.allocEnv(self.arena);
            self.initEnvironment(be, self.env, false);
            self.env = be;
            block_env = be;
            // Instantiate the CaseBlock's lexical declarations (across all cases):
            // function declarations are block-scoped (with the Annex B B.3.3 legacy
            // copy), and let/const/class get the temporal-dead-zone sentinel.
            for (cases) |c| for (c.body) |s| switch (s.*) {
                .func_decl, .labeled_stmt => _ = try self.hoistStatementFunctionDecl(s, false),
                else => {},
            };
            if (self.tdz_marker) |_| {
                const tdz = self.tdzVal();
                for (cases) |c| for (c.body) |s| switch (s.*) {
                    .var_decl => |d| if (d.kind != .@"var") try self.env.put(d.name, tdz),
                    .decl_group => |g| for (g) |gs| switch (gs.*) {
                        .var_decl => |d| if (d.kind != .@"var") try self.env.put(d.name, tdz),
                        else => {},
                    },
                    .destructure_decl => |d| if (d.kind != .@"var") self.tdzBindPattern(d.pattern, tdz),
                    .class_expr => |c2| if (c2.name.len > 0) try self.env.put(c2.name, tdz),
                    else => {},
                };
            }
        }
        var start: ?usize = null;
        for (cases, 0..) |c, i| {
            if (c.@"test") |t| {
                if (value.strictEquals(disc, try self.eval(t))) {
                    start = i;
                    break;
                }
            }
        }
        if (start == null) {
            for (cases, 0..) |c, i| {
                if (c.@"test" == null) {
                    start = i;
                    break;
                }
            }
        }
        var last: Value = Value.undef();
        if (start) |si| {
            var i = si;
            outer: while (i < cases.len) : (i += 1) {
                for (cases[i].body) |stmt| {
                    if (try self.evalHoistedFunctionDecl(stmt)) continue; // lexical function was hoisted above; Annex B update runs now
                    const r = try self.eval(stmt);
                    if (self.signal != .none) {
                        // UpdateEmpty: a raw break/continue is empty (keep `last`);
                        // a compound statement carries its own folded value.
                        if (!abruptCompletionEmpty(stmt)) last = r;
                        break :outer;
                    }
                    // UpdateEmpty: an empty statement completion (declarations,
                    // empty statement/block) does not replace the case block's value.
                    if (!self.stmtCompletionEmpty(stmt)) last = r;
                }
            }
            // An unlabeled `break` exits the switch; a labeled one targets an
            // enclosing loop and must keep propagating.
            if (self.signal == .brk and self.signal_label == null) self.signal = .none;
        }
        if (block_env) |be| if (be.disposables.items.len != 0) {
            if (try self.disposeScope(be, null)) |err| {
                self.exception = err;
                return error.Throw;
            }
        };
        // CaseBlockEvaluation returns NormalCompletion(undefined) when no case
        // statement produced a value — a concrete value, never an empty completion.
        self.completion_empty = false;
        return last;
    }

    fn evalWhile(self: *Interpreter, cond: *Node, body: *Node) EvalError!Value {
        const my_labels = self.takeLabels();
        var last: Value = Value.undef();
        while ((try self.eval(cond)).toBoolean()) {
            last = try self.eval(body);
            if (self.loopSignal(my_labels)) |stop| if (stop) break;
        }
        return last;
    }

    fn evalFor(self: *Interpreter, init_node: ?*Node, cond: ?*Node, update: ?*Node, body: *Node) EvalError!Value {
        const my_labels = self.takeLabels();
        // Collect the lexical (`let`/`const`) binding names declared in the init,
        // if any. They get a fresh, value-copied environment each iteration so a
        // closure created in the body captures that iteration's binding.
        var names: std.ArrayListUnmanaged([]const u8) = .empty;
        if (init_node) |ini| collectForLexNames(ini, &names, self.arena);
        const lexical = names.items.len > 0;

        const outer = self.env;
        const env_root_mark = self.gc_env_roots.items.len;
        var loop_env_rooted = false;
        defer if (loop_env_rooted) self.gc_env_roots.shrinkRetainingCapacity(env_root_mark);
        defer if (lexical) {
            self.env = outer;
        };
        // The for-head's lexical environment, which holds any `using`/`await using`
        // resource declared in the init — disposed at the END of the ForStatement.
        var loop_env: ?*Environment = null;
        if (init_node) |ini| {
            if (lexical) {
                // The loop's lexical declaration lives in its own environment.
                const le = try gc_mod.allocEnv(self.arena);
                self.initEnvironment(le, outer, false);
                self.env = le;
                loop_env = le;
                // ForDeclarationBindingInstantiation creates every head binding
                // before evaluating any initializer. Reads and assignments from
                // an initializer therefore observe the new binding's TDZ rather
                // than a same-named outer binding.
                if (self.tdz_marker != null) try self.predeclareForLexicals(ini);
            }
            // A later initializer in the head can throw after an earlier `using`
            // resource was registered (`for (using a = x, b = throws(); …)`); the
            // already-acquired resources are disposed before the error propagates.
            _ = self.eval(ini) catch |e| {
                if (e == error.Throw) if (loop_env) |le| if (le.disposables.items.len > 0) {
                    const body_err = self.exception;
                    if (self.disposeScope(le, body_err) catch null) |de| self.exception = de;
                };
                return e;
            };
        }
        // CreatePerIterationEnvironment (initial copy, before the first test).
        // As with later iterations, the copy is observable only when initializer
        // evaluation captured the head environment. Reuse an uncaptured head in
        // place instead of allocating a redundant second environment before its
        // condition.
        if (lexical and self.env.captured.load(.acquire)) self.env = try self.perIterEnv(outer, names.items, self.env);
        if (loop_env) |le| {
            if (le.disposables.items.len == 0) {
                loop_env = null;
            } else {
                try self.gc_env_roots.append(self.arena, le);
                loop_env_rooted = true;
            }
        }

        const last = self.runForBody(cond, update, body, my_labels, lexical, outer, names.items) catch |e| {
            // DisposeResources runs on an abrupt completion too, threading the error.
            if (loop_env) |le| if (le.disposables.items.len > 0 and e == error.Throw) {
                const body_err = self.exception;
                if (try self.disposeScope(le, body_err)) |err| self.exception = err;
            };
            return e;
        };
        if (loop_env) |le| if (le.disposables.items.len > 0) {
            if (try self.disposeScope(le, null)) |err| {
                self.exception = err;
                return error.Throw;
            }
        };
        return last;
    }

    /// The `for` loop's iteration, factored out so `evalFor` can run DisposeResources
    /// for a for-head `using` on both normal and abrupt completion.
    fn runForBody(self: *Interpreter, cond: ?*Node, update: ?*Node, body: *Node, my_labels: []const []const u8, lexical: bool, outer: *Environment, names: []const []const u8) EvalError!Value {
        var last: Value = Value.undef();
        while (true) {
            if (cond) |c| {
                if (!(try self.eval(c)).toBoolean()) break;
            }
            last = try self.eval(body);
            if (self.loopSignal(my_labels)) |stop| if (stop) break;
            // CreatePerIterationEnvironment: per spec each iteration gets a fresh
            // copy of the loop bindings, so a closure created this iteration
            // captures *this* iteration's value. That copy is only observable
            // through such a closure — so when nothing captured this iteration's
            // env (`captured` unset), reuse it in place and let the update mutate
            // it, skipping a GC-cell allocation per iteration (the tight-loop
            // fast path). If it was captured, allocate the fresh copy so the
            // captured binding keeps its value.
            if (lexical and self.env.captured.load(.acquire)) self.env = try self.perIterEnv(outer, names, self.env);
            if (update) |u| _ = try self.eval(u);
        }
        return last;
    }

    /// A fresh per-iteration environment for a `for (let …; …; …)` loop: a child
    /// of `outer` holding each lexical binding, value-copied from `prev`.
    fn perIterEnv(self: *Interpreter, outer: *Environment, names: []const []const u8, prev: *Environment) EvalError!*Environment {
        const e = try gc_mod.allocEnv(self.arena);
        self.initEnvironment(e, outer, false);
        for (names) |n| {
            const v = prev.get(n) orelse Value.undef();
            // Preserve const-ness across the per-iteration copy so a `const`
            // loop binding stays immutable — `for (const i = 0; …; i++)` is a
            // TypeError at the update, not a silent reassignment.
            if (prev.isConst(n)) |is_const| {
                if (is_const) try e.putConst(n, v) else try e.put(n, v);
            } else try e.put(n, v);
        }
        return e;
    }

    /// Per-iteration binding-env state for a `for-of`/`for-in` loop, threaded
    /// across iterations by `iterBindingEnv`.
    const IterEnvState = struct {
        /// The env being reused in place (rooted once in `gc_env_roots`), or null.
        reuse: ?*Environment = null,
        /// Once any iteration's env is captured we stop reusing for the rest of the
        /// loop, so a captured binding is never re-bound and its closure keeps that
        /// iteration's value.
        disabled: bool = false,
    };

    /// Choose this iteration's per-iteration binding environment for a
    /// `for-of`/`for-in` loop. Reuses the same env in place while nothing captures
    /// it (the fast path — no GC-cell allocation per iteration, as the target is
    /// re-bound via `put`/`putConst` which overwrites the value and preserves
    /// const-ness), and roots it once in `gc_env_roots` so it survives a
    /// collection between iterations (unlike `for(;;)`, these loops restore
    /// `self.env` to the outer scope each iteration, so the reused env would
    /// otherwise be unrooted). Falls back to a fresh child of `outer` once the
    /// reuse env is captured, or when reuse is disallowed (`allow_reuse` false —
    /// a per-iteration `using` resource must get its own env to dispose).
    fn iterBindingEnv(self: *Interpreter, state: *IterEnvState, outer: *Environment, allow_reuse: bool) EvalError!*Environment {
        if (state.reuse) |r| {
            if (!r.captured.load(.acquire)) return r; // reuse in place — no allocation
            state.reuse = null; // captured: abandon it (kept alive by its closure) and stop reusing
            state.disabled = true;
        }
        const e = try gc_mod.allocEnv(self.arena);
        self.initEnvironment(e, outer, false);
        if (allow_reuse and !state.disabled) {
            state.reuse = e;
            try self.gc_env_roots.append(self.arena, e); // root across iterations (shrunk at loop exit)
        }
        return e;
    }

    /// Collect the names bound by a `for` loop's lexical (`let`/`const`) init.
    /// Returns nothing for a `var`/expression init (no per-iteration scope).
    fn collectForLexNames(node: *Node, out: *std.ArrayListUnmanaged([]const u8), arena: std.mem.Allocator) void {
        switch (node.*) {
            .var_decl => |d| if (d.kind != .@"var") {
                out.append(arena, d.name) catch {};
            },
            .destructure_decl => |d| if (d.kind != .@"var") {
                collectPatternNames(d.pattern, out, arena);
            },
            .decl_group => |group| for (group) |n| collectForLexNames(n, out, arena),
            else => {},
        }
    }

    fn predeclareForLexicals(self: *Interpreter, node: *Node) EvalError!void {
        switch (node.*) {
            .var_decl => |decl| if (decl.kind != .@"var") {
                if (decl.kind == .@"const")
                    try self.env.putConst(decl.name, self.tdzVal())
                else
                    try self.env.put(decl.name, self.tdzVal());
            },
            .destructure_decl => |decl| if (decl.kind != .@"var") {
                try self.predeclareForLexicalPattern(decl.pattern, decl.kind == .@"const");
            },
            .decl_group => |group| for (group) |decl| try self.predeclareForLexicals(decl),
            else => {},
        }
    }

    fn predeclareForLexicalPattern(self: *Interpreter, target: *Node, immutable: bool) EvalError!void {
        switch (target.*) {
            .identifier => |name| {
                if (immutable)
                    try self.env.putConst(name, self.tdzVal())
                else
                    try self.env.put(name, self.tdzVal());
            },
            .obj_pattern => |pattern| {
                for (pattern.props) |property| try self.predeclareForLexicalPattern(property.target, immutable);
                if (pattern.rest) |rest| try self.predeclareForLexicalPattern(rest, immutable);
            },
            .arr_pattern => |pattern| {
                for (pattern.elems) |element| if (element.target) |element_target|
                    try self.predeclareForLexicalPattern(element_target, immutable);
                if (pattern.rest) |rest| try self.predeclareForLexicalPattern(rest, immutable);
            },
            else => {},
        }
    }

    /// Append every identifier bound by a destructuring pattern.
    fn collectPatternNames(target: *Node, out: *std.ArrayListUnmanaged([]const u8), arena: std.mem.Allocator) void {
        switch (target.*) {
            .identifier => |name| out.append(arena, name) catch {},
            .obj_pattern => |p| {
                for (p.props) |pr| collectPatternNames(pr.target, out, arena);
                if (p.rest) |r| if (r.* == .identifier) out.append(arena, r.identifier) catch {};
            },
            .arr_pattern => |p| {
                for (p.elems) |e| if (e.target) |t| collectPatternNames(t, out, arena);
                if (p.rest) |r| collectPatternNames(r, out, arena);
            },
            else => {},
        }
    }

    /// Consume all consecutive labels of the enclosing labeled item. The labels
    /// remain backed by `current_labels` until their statements return, while
    /// `labels_consumed` prevents loops nested in the body from inheriting them.
    fn takeLabels(self: *Interpreter) []const []const u8 {
        const labels = self.current_labels.items[self.labels_consumed..];
        self.labels_consumed = self.current_labels.items.len;
        return labels;
    }

    /// Inspect the control-flow signal at a loop boundary, given the loop's own
    /// labels (`my_labels`). Returns null (nothing pending), true (break this
    /// loop), or false (continue). A labeled break/continue aimed at an *outer*
    /// loop breaks this loop but leaves the signal set to keep propagating.
    fn loopSignal(self: *Interpreter, my_labels: []const []const u8) ?bool {
        switch (self.signal) {
            .none => return null,
            .ret => return true, // leave set; the function unwinds
            .brk => {
                if (self.signal_label == null or labelIn(self.signal_label.?, my_labels)) {
                    self.signal = .none;
                    self.signal_label = null;
                    return true;
                }
                return true; // labeled break for an outer loop: exit, keep signal
            },
            .cont => {
                if (self.signal_label == null or labelIn(self.signal_label.?, my_labels)) {
                    self.signal = .none;
                    self.signal_label = null;
                    return false;
                }
                return true; // labeled continue for an outer loop: exit, keep signal
            },
        }
    }

    fn evalUpdate(self: *Interpreter, inc: bool, prefix: bool, target: *Node) EvalError!Value {
        if (target.* == .identifier) {
            const name = target.identifier;
            const reference = try self.captureBindingReference(name, null);
            const reference_root = try self.pushTempBindingReferenceRoot(reference);
            defer self.restoreTempBindingReferenceRoots(reference_root);
            var old = (try self.loadCapturedBindingReference(
                self.tempBindingReferenceRoot(reference_root, reference),
                name,
                false,
            )).value;
            if (old.isObject() and !old.asObj().is_bigint and !old.asObj().is_symbol)
                old = try self.toPrimitive(old, .number);
            if (old.isObject() and old.asObj().is_bigint) {
                const updated = try self.makeBigInt(if (inc) old.asObj().bigIntValue() +% 1 else old.asObj().bigIntValue() -% 1);
                try self.storeCapturedBindingReference(
                    self.tempBindingReferenceRoot(reference_root, reference),
                    name,
                    updated,
                );
                return if (prefix) updated else old;
            }
            const old_number = old.toNumber();
            const updated = Value.num(if (inc) old_number + 1 else old_number - 1);
            try self.storeCapturedBindingReference(
                self.tempBindingReferenceRoot(reference_root, reference),
                name,
                updated,
            );
            return if (prefix) updated else Value.num(old_number);
        }
        // A member update evaluates its Reference once: both a side-effecting
        // base in `base().name++` and a computed key are captured for the later
        // PutValue rather than re-evaluated after ToNumeric.
        if (target.* == .member and !target.member.optional) {
            const member = target.member;
            const recv = try self.eval(member.object);
            const key = if (member.computed) |computed| key: {
                // Evaluate the key expression (GetValue) but reject a nullish
                // base before observable ToPropertyKey coercion.
                const key_val = try self.eval(computed);
                if (recv.isNull() or recv.isUndefined())
                    return self.throwError("TypeError", "Cannot read properties of null or undefined");
                break :key try self.keyOf(key_val);
            } else member.property;
            var ov = try self.getProperty(recv, key);
            if (ov.isObject() and !ov.asObj().is_bigint and !ov.asObj().is_symbol)
                ov = try self.toPrimitive(ov, .number);
            if (ov.isObject() and ov.asObj().is_bigint) {
                const b = ov.asObj().bigIntValue();
                const up = try self.makeBigInt(if (inc) b +% 1 else b -% 1);
                try self.setMember(recv, key, up);
                return if (prefix) up else ov;
            }
            const o = ov.toNumber();
            const up = if (inc) o + 1 else o - 1;
            try self.setMember(recv, key, Value.num(up));
            return Value.num(if (prefix) up else o);
        }
        if (target.* == .super_member) {
            const m = target.super_member;
            const home = self.home_object orelse return self.throwError("SyntaxError", "'super' outside a method");
            if (!self.this_initialized) return self.throwError("ReferenceError", "Must call super constructor before using 'this'");
            const key_val: ?Value = if (m.computed) |ce| try self.eval(ce) else null;
            const parent = home.protoAtomic() orelse return self.throwError("TypeError", "Cannot read property of null (super)");
            const key = if (key_val) |kv| try self.keyOf(kv) else m.property;
            var ov = try self.getPropertyWithReceiver(Value.obj(parent), key, self.this_value);
            if (ov.isObject() and !ov.asObj().is_bigint and !ov.asObj().is_symbol)
                ov = try self.toPrimitive(ov, .number);
            if (ov.isObject() and ov.asObj().is_bigint) {
                const b = ov.asObj().bigIntValue();
                const up = try self.makeBigInt(if (inc) b +% 1 else b -% 1);
                if (!try self.setMemberResult(Value.obj(parent), key, up, self.this_value)) {
                    if (self.strict) return self.throwError("TypeError", "Cannot set property");
                }
                return if (prefix) up else ov;
            }
            const o = ov.toNumber();
            const up = if (inc) o + 1 else o - 1;
            if (!try self.setMemberResult(Value.obj(parent), key, Value.num(up), self.this_value)) {
                if (self.strict) return self.throwError("TypeError", "Cannot set property");
            }
            return Value.num(if (prefix) up else o);
        }
        if (target.* == .call) {
            _ = try self.eval(target);
            return self.throwError("ReferenceError", "invalid assignment target");
        }
        var old_val = try self.eval(target);
        // ToNumeric: an object operand coerces via ToPrimitive(number); a BigInt
        // is incremented/decremented by 1n (not the Number 1), and the result
        // stays a BigInt.
        if (old_val.isObject() and !old_val.asObj().is_bigint and !old_val.asObj().is_symbol)
            old_val = try self.toPrimitive(old_val, .number);
        if (old_val.isObject() and old_val.asObj().is_bigint) {
            const b = old_val.asObj().bigIntValue();
            const updated = try self.makeBigInt(if (inc) b +% 1 else b -% 1);
            try self.assignTo(target, updated);
            return if (prefix) updated else old_val;
        }
        const old = old_val.toNumber();
        const updated = if (inc) old + 1 else old - 1;
        try self.assignTo(target, Value.num(updated));
        return Value.num(if (prefix) updated else old);
    }

    /// Pre-declare every `var`-scoped name in `stmts` as `undefined` (hoisting),
    /// so a forward reference reads `undefined` instead of throwing a
    /// ReferenceError. Recurses through nested control-flow statements but stops
    /// at function boundaries (their vars belong to their own scope); existing
    /// bindings (parameters, hoisted functions, earlier vars) are left untouched.
    pub fn hoistVarNames(self: *Interpreter, stmts: []*Node) EvalError!void {
        for (stmts) |s| try self.hoistVarsIn(s);
    }

    fn hoistVarsIn(self: *Interpreter, node: *Node) EvalError!void {
        switch (node.*) {
            .var_decl => |d| if (d.kind == .@"var") try self.hoistOneVar(d.name),
            .destructure_decl => |d| if (d.kind == .@"var") try self.hoistPatternVars(d.pattern),
            .decl_group => |g| for (g) |gs| try self.hoistVarsIn(gs),
            .export_decl => |e| if (e.declaration) |d| try self.hoistVarsIn(d),
            .block => |b| for (b) |bs| try self.hoistVarsIn(bs),
            .if_stmt => |i| {
                try self.hoistVarsIn(i.consequent);
                if (i.alternate) |alt| try self.hoistVarsIn(alt);
            },
            .while_stmt => |w| try self.hoistVarsIn(w.body),
            .do_while_stmt => |w| try self.hoistVarsIn(w.body),
            .with_stmt => |w| try self.hoistVarsIn(w.body),
            .for_stmt => |f| {
                if (f.init) |ini| try self.hoistVarsIn(ini);
                try self.hoistVarsIn(f.body);
            },
            .for_in => |f| {
                if (f.decl_kind) |k| if (k == .@"var") try self.hoistPatternVars(f.target);
                try self.hoistVarsIn(f.body);
            },
            .try_stmt => |t| {
                try self.hoistVarsIn(t.block);
                if (t.catch_block) |c| try self.hoistVarsIn(c);
                if (t.finally_block) |fb| try self.hoistVarsIn(fb);
            },
            .switch_stmt => |sw| for (sw.cases) |c| for (c.body) |cs| try self.hoistVarsIn(cs),
            .labeled_stmt => |l| try self.hoistVarsIn(l.body),
            else => {}, // function decls/exprs and expressions hoist nothing here
        }
    }

    fn hoistOneVar(self: *Interpreter, name: []const u8) EvalError!void {
        try self.createVarBinding(name);
    }

    fn hoistPatternVars(self: *Interpreter, pat: *Node) EvalError!void {
        switch (pat.*) {
            .identifier => |name| try self.hoistOneVar(name),
            .obj_pattern => |p| {
                for (p.props) |prop| try self.hoistPatternVars(prop.target);
                if (p.rest) |r| try self.hoistPatternVars(r);
            },
            .arr_pattern => |p| {
                for (p.elems) |elem| if (elem.target) |target| try self.hoistPatternVars(target);
                if (p.rest) |r| try self.hoistPatternVars(r);
            },
            else => {},
        }
    }

    // ---- Annex B B.3.3 block-level function legacy-binding analysis -----------

    fn annexbListMayNeedScan(stmts: []const *Node, depth: u32) bool {
        if (depth >= 1) for (stmts) |s| switch (s.*) {
            .func_decl => |f| if (!f.is_generator and !f.is_async) return true,
            .labeled_stmt => if (labeledFunctionDeclNode(s) != null) return true,
            else => {},
        };
        for (stmts) |s| if (annexbStmtMayNeedScan(s, depth)) return true;
        return false;
    }

    fn annexbBranchMayNeedScan(node: *const Node, depth: u32) bool {
        return switch (node.*) {
            .block => |b| annexbListMayNeedScan(b, depth + 1),
            .func_decl => |f| !f.is_generator and !f.is_async,
            else => annexbStmtMayNeedScan(node, depth),
        };
    }

    /// Allocation-free structural pre-scan for the exact statement forms the
    /// Annex B collector traverses. Nested function bodies are intentionally not
    /// entered: each invocation owns its own cached decision.
    fn annexbStmtMayNeedScan(s: *const Node, depth: u32) bool {
        return switch (s.*) {
            .block => |b| annexbListMayNeedScan(b, depth + 1),
            .if_stmt => |i| annexbBranchMayNeedScan(i.consequent, depth) or
                (i.alternate != null and annexbBranchMayNeedScan(i.alternate.?, depth)),
            .while_stmt => |w| annexbBranchMayNeedScan(w.body, depth),
            .do_while_stmt => |w| annexbBranchMayNeedScan(w.body, depth),
            .with_stmt => |w| annexbBranchMayNeedScan(w.body, depth),
            .for_stmt => |f| annexbBranchMayNeedScan(f.body, depth),
            .for_in => |f| annexbBranchMayNeedScan(f.body, depth),
            .labeled_stmt => |l| annexbBranchMayNeedScan(l.body, depth),
            .switch_stmt => |sw| blk: {
                for (sw.cases) |c| for (c.body) |cs| switch (cs.*) {
                    .func_decl => |f| if (!f.is_generator and !f.is_async) break :blk true,
                    .labeled_stmt => if (labeledFunctionDeclNode(cs) != null) break :blk true,
                    else => {},
                };
                for (sw.cases) |c| for (c.body) |cs|
                    if (annexbStmtMayNeedScan(cs, depth + 1)) break :blk true;
                break :blk false;
            },
            .try_stmt => |t| annexbBranchMayNeedScan(t.block, depth) or
                (t.catch_block != null and annexbBranchMayNeedScan(t.catch_block.?, depth)) or
                (t.finally_block != null and annexbBranchMayNeedScan(t.finally_block.?, depth)),
            else => false,
        };
    }

    fn collectAnnexBLegacy(self: *Interpreter, stmts: []*Node, depth: u32, out: *SecureStringMembership, nodes: *std.AutoHashMapUnmanaged(*const Node, void)) EvalError!void {
        const Collector = struct {
            interpreter: *Interpreter,
            names: *SecureStringMembership,
            nodes: *std.AutoHashMapUnmanaged(*const Node, void),

            pub fn add(collector: *@This(), node: *const Node, name: []const u8) EvalError!void {
                const machine = collector.interpreter;
                const scratch = machine.scratch_allocator orelse machine.arena;
                _ = try collector.names.getOrPutSecure(machine, scratch, name);
                try collector.nodes.put(scratch, node, {});
            }
        };
        var collector = Collector{ .interpreter = self, .names = out, .nodes = nodes };
        try @import("annex_b.zig").collect(
            EvalError,
            self.scratch_allocator orelse self.arena,
            stmts,
            depth,
            if (self.eval_decl_deletable) &.{} else self.cur_func_params,
            !self.eval_decl_deletable and self.cur_func_args_needed,
            &collector,
        );
    }

    pub fn evalStatements(self: *Interpreter, stmts: []*Node) EvalError!Value {
        // A function-declaration directly in the variable scope (function body /
        // script / eval top level) is var-scoped; one inside a nested block is
        // block-scoped, with an additional legacy var binding under Annex B B.3.3.
        const at_fn_top = self.env.fn_body or self.env == self.env.varScope();
        const skip_annex_b_scan = self.skip_next_annex_b_scan;
        self.skip_next_annex_b_scan = false;
        // Annex B B.3.3: at the variable scope, work out which block-nested
        // function names get a legacy var binding, and pre-create those bindings
        // as `undefined`. Sloppy code only (strict block functions stay purely
        // block-scoped). The set stays live for nested blocks via `annexb_legacy`.
        var annexb_set: SecureStringMembership = .{};
        var annexb_nodes: std.AutoHashMapUnmanaged(*const Node, void) = .empty;
        const saved_annexb = self.annexb_legacy;
        const saved_annexb_nodes = self.annexb_legacy_nodes;
        const annexb_scratch = self.scratch_allocator orelse self.arena;
        defer {
            self.annexb_legacy = saved_annexb;
            self.annexb_legacy_nodes = saved_annexb_nodes;
            annexb_set.deinit(annexb_scratch);
            annexb_nodes.deinit(annexb_scratch);
        }
        if (at_fn_top and !self.strict and !skip_annex_b_scan) {
            try self.collectAnnexBLegacy(stmts, 0, &annexb_set, &annexb_nodes);
            self.annexb_legacy = &annexb_set;
            self.annexb_legacy_nodes = &annexb_nodes;
            const vs = self.env.varScope();
            var it = annexb_set.keyIterator();
            while (it.next()) |k| {
                if (!vs.hasOwnBinding(k.*)) try self.createVarBinding(k.*);
            }
        }
        // Hoist function declarations to the top of the scope so forward
        // references work (`bar(); function bar() {}`). Each is bound exactly
        // once here; the main loop then skips them, preserving function identity
        // (`var g = bar; function bar() {}` ⇒ `g === bar`).
        for (stmts) |s| switch (s.*) {
            .func_decl, .labeled_stmt => _ = try self.hoistStatementFunctionDecl(s, at_fn_top),
            // `export function f(){}` / direct `export default function f(){}`
            // hoist just like bare function declarations. Parenthesized
            // `export default (function(){})` is an expression and must wait for
            // source-order evaluation.
            .export_decl => |e| {
                if (e.declaration) |d| {
                    if (d.* == .func_decl) try self.globalDefine(d.func_decl.name, try self.makeFunction(d.func_decl, self.env));
                } else if (e.default_expr) |dx| {
                    const fv: ?Value = switch (dx.*) {
                        .function => |f| if (f.is_default_export_decl) try self.makeFunction(f, self.env) else null,
                        else => null,
                    };
                    if (fv) |v| {
                        if (e.default_name.len > 0) try self.globalDefine(e.default_name, v) else try self.maybeNameAnon(v, dx, "default");
                        try self.env.put("*default*", v);
                    }
                }
            },
            else => {},
        };
        // `var` hoisting: once per function/script var-scope, pre-declare every
        // `var` name (in nested control-flow too) as `undefined`. Runs after the
        // function-declaration hoist above (declare-if-absent, so it never
        // clobbers a hoisted function or parameter).
        if (self.env == self.env.varScope()) try self.hoistVarNames(stmts);
        for (stmts) |s| switch (s.*) {
            .var_decl => |d| if (d.kind != .@"var") try self.checkRestrictedGlobalLexical(d.name),
            .decl_group => |group| for (group) |gs| switch (gs.*) {
                .var_decl => |d| if (d.kind != .@"var") try self.checkRestrictedGlobalLexical(d.name),
                else => {},
            },
            .destructure_decl => |d| if (d.kind != .@"var") try self.checkRestrictedGlobalLexicalPattern(d.pattern),
            .class_expr => |c| if (c.name.len > 0) try self.checkRestrictedGlobalLexical(c.name),
            else => {},
        };
        // Temporal dead zone: `let`/`const` (and `class`) declarations are
        // hoisted into this scope as uninitialized bindings; reading one before
        // its declaration runs throws a ReferenceError.
        if (self.tdz_marker) |_| {
            const tdz = self.tdzVal();
            // At the global scope, record each lexical name so its read resolves to
            // the declarative binding rather than a like-named global-object
            // property (`let Array` reads undefined, not %Array%).
            const mark_global = self.env.parent == null;
            for (stmts) |s| switch (s.*) {
                .var_decl => |d| if (d.kind != .@"var") {
                    try self.env.put(d.name, tdz);
                    if (mark_global) try self.env.markLexical(d.name);
                },
                .decl_group => |group| for (group) |gs| switch (gs.*) {
                    .var_decl => |d| if (d.kind != .@"var") {
                        try self.env.put(d.name, tdz);
                        if (mark_global) try self.env.markLexical(d.name);
                    },
                    else => {},
                },
                .destructure_decl => |d| if (d.kind != .@"var") self.tdzBindPattern(d.pattern, tdz),
                .class_expr => |c| if (c.name.len > 0) {
                    try self.env.put(c.name, tdz);
                    if (mark_global) try self.env.markLexical(c.name);
                },
                else => {},
            };
        }
        var last: Value = Value.undef();
        var seen_value = false; // any non-empty completion accumulated yet
        for (stmts) |s| {
            if (try self.evalHoistedFunctionDecl(s)) continue; // lexical function was hoisted above; Annex B update runs now
            // An exported function declaration was hoisted above too (preserving
            // its identity); skip it so it isn't rebuilt with a fresh identity.
            if (s.* == .export_decl) {
                const e = s.export_decl;
                if (e.declaration) |d| {
                    if (d.* == .func_decl) continue;
                } else if (e.default_expr) |dx| {
                    if (dx.* == .function and dx.function.is_default_export_decl) continue;
                }
            }
            const r = try self.eval(s);
            // An abrupt completion (break/continue/return) unwinds to the caller.
            // UpdateEmpty: a raw break/continue carries an EMPTY value, so the
            // list's accumulated value (`last`) flows through; anything else
            // (return, or a compound statement that already folded its nested
            // value) carries its own value.
            if (self.signal != .none) {
                if (!abruptCompletionEmpty(s)) last = r;
                return last;
            }
            // UpdateEmpty: a declaration / empty statement / empty block does not
            // replace the statement list's value.
            if (!self.stmtCompletionEmpty(s)) {
                last = r;
                seen_value = true;
            }
        }
        self.completion_empty = !seen_value;
        return last;
    }

    /// Whether statement `s` produces an EMPTY completion (so it doesn't update
    /// the enclosing list's completion value). Declarations and empty statements
    /// are empty; a `{ … }` block defers to the brand its own list set.
    /// Whether an ABRUPT completion produced by `s` carries an EMPTY value (so
    /// UpdateEmpty lets the enclosing list's accumulated value flow through). A
    /// raw `break`/`continue` has an empty completion value; `return` carries its
    /// argument, and a compound statement already folded its own nested value in.
    fn abruptCompletionEmpty(s: *Node) bool {
        return switch (s.*) {
            .break_stmt, .continue_stmt => true,
            else => false,
        };
    }

    fn stmtCompletionEmpty(self: *Interpreter, s: *Node) bool {
        return switch (s.*) {
            .var_decl, .decl_group, .destructure_decl, .debugger_stmt => true,
            .class_expr => true, // a class *declaration* statement
            .block => self.completion_empty,
            else => false,
        };
    }

    pub fn recordBytecodeAdmission(self: *Interpreter, reason: BytecodeAdmissionReason) void {
        if (self.bytecode_admission_inventory) |inventory| inventory.record(reason);
    }

    pub fn recordExecutionTier(self: *Interpreter, metric: ExecutionTierMetric) void {
        if (self.execution_tier_inventory) |inventory| inventory.record(metric);
    }

    pub fn recordQuickBinary(self: *Interpreter, metric: QuickBinaryMetric) void {
        if (self.execution_tier_inventory) |inventory| inventory.recordQuickBinary(metric);
    }

    pub fn makeFunction(self: *Interpreter, fnode: *const ast.FunctionNode, closure: *Environment) EvalError!Value {
        // The closure keeps `closure` (and its whole ancestor chain) reachable, so
        // an enclosing `for (let …)` loop must give each iteration its own binding
        // env rather than reusing one. Record that here (see `Environment.captured`).
        closure.markCaptured();
        const func = try gc_mod.allocFunction(self.arena);
        func.* = .{
            .params = fnode.params,
            .body = fnode.body,
            .is_expr_body = fnode.is_expr_body,
            .is_arrow = fnode.is_arrow,
            .uses_arguments = fnode.uses_arguments,
            .uses_direct_eval = fnode.uses_direct_eval,
            .closure = closure,
            .realm_global = functionRealmGlobal(closure, self.global_object),
            .name = fnode.name,
            .definition_location = self.debug_current_location,
            .source = fnode.source,
            .bytecode_execution_mode = self.bytecode_execution_mode,
            .is_generator = fnode.is_generator,
            .is_async = fnode.is_async,
            .is_strict = fnode.is_strict,
            .annex_b_possible = !fnode.is_strict and switch (fnode.body.*) {
                .block => |stmts| annexbListMayNeedScan(stmts, 0),
                else => false,
            },
            .is_method = fnode.is_method,
            .import_meta_slot = self.import_meta_slot,
            .module_referrer = self.cur_module,
        };
        // A `with` block's object Environment Record is part of the lexical chain
        // (`Environment.with_object`), so a function defined inside a `with`
        // captures it automatically through its `closure` — no separate capture.
        // Arrows capture `super` (home object + super constructor) lexically from
        // the enclosing method, just as they capture `this`/`new.target`. A
        // non-arrow gets its home object later (e.g. when installed as a method).
        if (fnode.is_arrow) {
            func.home_object = self.home_object;
            func.super_ctor = self.super_ctor;
            func.arrow_this = self.this_value; // captured lexically; used on every call
            func.arrow_new_target = self.new_target; // new.target is lexical for arrows too
            func.arrow_direct_eval_new_target_allowed = self.direct_eval_new_target_allowed;
            func.arrow_in_derived_ctor = self.in_derived_ctor; // super()-legality is lexical
            func.this_cell = self.this_cell; // share the enclosing derived ctor's `this` binding
            func.field_init_ctx = self.in_field_initializer; // field-init eval restrictions are lexical
            if (self.active_function) |active_object| if (active_object.jsFunction()) |erased| {
                const active: *Function = @ptrCast(@alignCast(erased));
                func.derived_constructor = if (active.is_derived_constructor) active_object else active.derived_constructor;
                func.field_inits = active.field_inits;
                func.private_brand_names = active.private_brand_names;
            };
        }
        // Compile a generator body up front for the suspendable VM. Bodies
        // outside the VM's lowered subset leave `gen_chunk` null, so calling the
        // generator throws a clear TypeError rather than running incorrectly.
        var admission_reason: BytecodeAdmissionReason = undefined;
        var admission_deferred = false;
        if (fnode.is_generator) {
            switch (try Compiler.admitGenerator(self.arena, fnode, true)) {
                .compiled => |chunk| {
                    func.gen_chunk = chunk;
                    admission_reason = .generator_compiled;
                },
                .rejected => |reason| admission_reason = generatorRejectionAdmission(reason),
            }
        } else if (fnode.is_async) {
            // A plain async function compiles to a suspendable body (await is a
            // suspend point); null on unsupported syntax → tree-walk fallback.
            switch (try Compiler.admitAsync(self.arena, fnode, true)) {
                .compiled => |chunk| {
                    func.async_chunk = chunk;
                    admission_reason = .async_compiled;
                },
                .rejected => |reason| admission_reason = asyncRejectionAdmission(reason),
            }
        } else if (fnode.defer_plain_bytecode_compilation) {
            admission_reason = .synthetic;
            admission_deferred = true;
        } else {
            admission_reason = try self.installPlainFunctionBytecode(func, fnode);
        }
        func.bytecode_admission_reason = admission_reason;
        if (!admission_deferred) self.recordBytecodeAdmission(admission_reason);
        // A function object's [[Prototype]] is the kind-specific function
        // prototype intrinsic: %GeneratorFunction.prototype% for `function*`,
        // %AsyncFunction.prototype% for `async function`,
        // %AsyncGeneratorFunction.prototype% for `async function*`, else
        // %Function.prototype%. So `Object.getPrototypeOf(function*(){}).
        // constructor === GeneratorFunction`, etc.
        const fproto: ?*value.Object = blk: {
            const tag: ?[]const u8 = if (fnode.is_generator and fnode.is_async)
                "\x00AsyncGenFuncProto"
            else if (fnode.is_generator)
                "\x00GenFuncProto"
            else if (fnode.is_async)
                "\x00AsyncFuncProto"
            else
                null;
            if (tag) |t| if (self.env.get(t)) |v| if (v.isObject()) break :blk v.asObj();
            break :blk self.functionProto();
        };
        const obj = try gc_mod.allocObj(self.arena);
        obj.* = .{ .proto = fproto };
        try obj.setJsFunction(self.arena, @ptrCast(func));
        func.obj = obj;
        try installFunctionProps(self.arena, self.root_shape, obj, fnode.params, func.name);
        return Value.obj(obj);
    }

    fn installPlainFunctionBytecode(self: *Interpreter, func: *Function, fnode: *const ast.FunctionNode) EvalError!BytecodeAdmissionReason {
        if (self.bytecode_execution_mode == .tree_walker) return .plain_forced_tree_walker;
        if (self.debug_statement_hook != null) return .plain_policy_debugger;
        // `required` is a coverage contract, not an automatic tier-selection
        // hint. Dynamic eval is parsed and instantiated at runtime, so its
        // nested functions cannot arrive as program FnTemplates; compile every
        // lowerable function here even when it is too cold/simple for automatic
        // admission. Genuine compiler barriers remain causal rejections below.
        if (self.bytecode_execution_mode != .required)
            if (plainFunctionPolicyRejection(fnode)) |reason| return reason;
        return switch (try Compiler.admitPlainFunction(self.arena, fnode)) {
            .compiled => |code| blk: {
                func.chunk = code.chunk;
                func.local_count = code.local_count;
                func.vm_inline_calls_safe = vmChunkAllowsInlineCalls(code.chunk);
                break :blk .plain_compiled;
            },
            .rejected => |reason| plainRejectionAdmission(reason),
        };
    }

    fn sourceMayHaveTailCall(source: []const u8) bool {
        return std.mem.indexOf(u8, source, "return") != null and std.mem.indexOfScalar(u8, source, '(') != null;
    }

    fn sourceMayObserveLegacyCallFrame(source: []const u8) bool {
        return std.mem.indexOf(u8, source, "caller") != null or
            std.mem.indexOf(u8, source, ".arguments") != null;
    }

    fn sourceIdentifierByte(c: u8) bool {
        return std.ascii.isAlphanumeric(c) or c == '_' or c == '$';
    }

    fn sourceBodyMayCallOtherThan(source: []const u8, allowed_name: []const u8, second_allowed_name: []const u8) bool {
        // A traditional function's own parameter list is not a body call. The
        // old whole-source scan therefore rejected every sloppy function before
        // the named-property and self-recursion exceptions below could apply.
        // Starting after the opening brace, distinguish control/grouping
        // parentheses from call syntax. This remains deliberately conservative:
        // a computed/parenthesized callee or any non-self identifier call keeps
        // the body on the tree-walker for legacy caller/arguments observability.
        const body_start = if (std.mem.indexOfScalar(u8, source, '{')) |brace|
            brace + 1
        else
            0;
        var search = body_start;
        while (std.mem.indexOfScalarPos(u8, source, search, '(')) |paren| {
            var end = paren;
            while (end > body_start and std.ascii.isWhitespace(source[end - 1])) end -= 1;
            if (end == body_start) {
                search = paren + 1;
                continue;
            }
            const preceding = source[end - 1];
            if (preceding == ')' or preceding == ']' or preceding == '.') return true;
            // A comment can separate an identifier callee from `(`, and a
            // non-ASCII byte can be part of an identifier. The source-level
            // classifier intentionally rejects both ambiguous forms rather
            // than admitting a real call by mistake.
            if (preceding == '/' or preceding >= 0x80) return true;
            if (!sourceIdentifierByte(preceding)) {
                search = paren + 1;
                continue;
            }
            var start = end - 1;
            while (start > body_start and sourceIdentifierByte(source[start - 1])) start -= 1;
            const token = source[start..end];
            const control = std.mem.eql(u8, token, "if") or
                std.mem.eql(u8, token, "for") or
                std.mem.eql(u8, token, "while") or
                std.mem.eql(u8, token, "switch") or
                std.mem.eql(u8, token, "catch") or
                std.mem.eql(u8, token, "with");
            const allowed = (allowed_name.len != 0 and std.mem.eql(u8, token, allowed_name)) or
                (second_allowed_name.len != 0 and std.mem.eql(u8, token, second_allowed_name));
            if (!control and !allowed) return true;
            search = paren + 1;
        }
        return false;
    }

    fn sourceHasNamedSelfCall(source: []const u8, name: []const u8) bool {
        if (name.len == 0) return false;
        var search: usize = 0;
        var call_count: usize = 0;
        while (std.mem.indexOfPos(u8, source, search, name)) |at| {
            const after = at + name.len;
            if (after < source.len and source[after] == '(') {
                call_count += 1;
                if (call_count >= 2) return true;
            }
            search = after;
        }
        return false;
    }

    /// Whether a plain function should compile to a bytecode chunk and run on the
    /// VM instead of the tree-walker. Besides tail calls and recursion, named
    /// property functions enter the VM so their observed shapes can reach the
    /// optimizing tier. Unsupported bodies still fall back during compilation.
    /// Generators and async functions retain their dedicated paths. Ordinary
    /// arguments owners use compiler-assigned frame slots; sloppy simple
    /// parameters additionally use object-owned mapped cells. Methods use the
    /// same admission now that activations carry their exact home object and
    /// super constructor.
    fn plainFunctionPolicyRejection(fnode: *const ast.FunctionNode) ?BytecodeAdmissionReason {
        // Arrows created on the tree-walker retain the barrier: standalone
        // admission has no defining frame from which to resolve their inherited
        // arguments binding. Arrows nested in compiled owners are lowered with
        // that parent FnScope by Compiler.compileFunction instead.
        if (fnode.is_arrow and fnode.uses_arguments) return .plain_policy_arguments;
        // Sloppy caller/callee reflection observes the interpreter's dynamic
        // call-frame chain, not merely the arguments exotic. Keep this more
        // specific boundary ahead of mapped-arguments admission.
        if (!fnode.is_strict and sourceMayObserveLegacyCallFrame(fnode.source))
            return .plain_policy_legacy_call_frame;
        if (fnode.uses_arguments) return null;
        if (fnode.requires_tree_walk_class_constructor) return .plain_policy_class_constructor_semantics;
        if (fnode.is_derived_class_constructor) return null;
        if (fnode.class_instance_initializers.len != 0) return null;
        if (fnode.is_strict) return if (fnode.uses_direct_eval or sourceMayHaveTailCall(fnode.source) or std.mem.indexOfScalar(u8, fnode.source, '.') != null)
            null
        else
            .plain_policy_not_candidate;
        const named_self_recursion = sourceHasNamedSelfCall(fnode.source, fnode.name);
        // The compiler/runtime direct-eval admission is itself fail-closed on
        // incomplete activation contexts. Exempt only the syntactic eval callee
        // from the legacy dynamic-call policy; any additional call still keeps
        // a sloppy function on the tree walker.
        if (sourceBodyMayCallOtherThan(
            fnode.source,
            if (named_self_recursion) fnode.name else "",
            if (fnode.uses_direct_eval) "eval" else "",
        ))
            return .plain_policy_dynamic_call;
        if (!named_self_recursion and !fnode.uses_direct_eval and
            std.mem.indexOfScalar(u8, fnode.source, '.') == null and
            std.mem.indexOfScalar(u8, fnode.source, '[') == null)
            return .plain_policy_not_candidate;
        return null;
    }

    pub fn funcOf(v: Value) ?*Function {
        if (v.isObject()) {
            if (v.asObj().jsFunction()) |e| return @ptrCast(@alignCast(e));
        }
        return null;
    }

    fn legacyCallerArgumentsAllowed(f: *const Function) bool {
        return !f.is_strict and !f.is_arrow and !f.is_generator and !f.is_async and !f.is_method and !f.is_class_constructor;
    }

    fn legacyCallFrameFor(self: *Interpreter, obj: *value.Object) ?*LegacyCallFrame {
        var frame = self.active_call_frame;
        while (frame) |fr| : (frame = fr.caller) {
            if (fr.func_obj == obj) return fr;
        }
        return null;
    }

    fn legacyCallerValue(frame: *LegacyCallFrame) Value {
        if (frame.caller) |caller_frame| {
            if (funcOf(Value.obj(caller_frame.func_obj))) |caller_func| {
                if (legacyCallerArgumentsAllowed(caller_func)) return Value.obj(caller_frame.func_obj);
            }
        }
        return Value.nul();
    }

    pub fn jsFunctionHasOwnPrototypeSlot(o: *value.Object) bool {
        const erased = o.jsFunction() orelse return false;
        const f: *Function = @ptrCast(@alignCast(erased));
        // Ordinary functions expose a constructor `.prototype`. Generator and
        // async-generator functions, including concise methods, expose one for
        // the yielded iterator prototype. Arrows, non-generator concise methods,
        // accessors, and plain async functions do not.
        return !f.is_arrow and (f.is_generator or (!f.is_method and !f.is_async));
    }

    /// Force a function's lazily-created `.prototype` into being a real own
    /// property (with its correct non-enumerable attributes and, for an ordinary
    /// function, its `constructor` back-link). Mirrors the lazy install in
    /// `getProperty`, so reflection over the function — `Reflect.ownKeys`,
    /// `Object.getOwnPropertyNames` — sees the property that a bare access would
    /// materialize. No-op for arrows/methods/plain-async (no prototype slot) and
    /// for a function whose prototype already exists.
    pub fn materializeFunctionPrototype(self: *Interpreter, o: *value.Object) EvalError!void {
        if (o.jsFunction() == null or !jsFunctionHasOwnPrototypeSlot(o)) return;
        if (o.getOwn("prototype") != null or o.getAccessor("prototype") != null) return;
        const f = funcOf(Value.obj(o)) orelse return;
        if (f.is_generator) {
            _ = try self.genProtoObject(o, f.is_async);
            return;
        }
        if (!f.is_arrow) {
            const proto = try self.protoObject(o);
            try o.setAttr(self.arena, "prototype", .{ .writable = true, .enumerable = false, .configurable = false });
            try self.setProp(proto, "constructor", Value.obj(o));
            try proto.setAttr(self.arena, "constructor", .{ .writable = true, .enumerable = false, .configurable = true });
        }
    }

    /// `Function.prototype.toString`. A user function returns its exact captured
    /// source; a native, bound, or not-yet-captured function returns the spec's
    /// NativeFunction syntax `function NAME() { [native code] }`.
    fn functionToString(self: *Interpreter, o: *value.Object) EvalError!Value {
        if (funcOf(Value.obj(o))) |func| {
            if (func.source.len > 0) return try Value.strAlloc(self.arena, func.source);
        }
        // Bound function exotics have a public `.name` like "bound f", but their
        // NativeFunction source form is anonymous (`function () { [native code] }`).
        // The source form consumes semantic StringData, never its physical cell
        // image, so a flat Latin-1 name must cross the canonical byte boundary.
        const raw_name: []const u8 = if (o.boundFunction() != null)
            ""
        else if (o.getOwn("name")) |n|
            (if (n.isString()) try n.asWtf8(self.arena) else "")
        else
            "";
        const nm: []const u8 = if (raw_name.len > 0 and raw_name[0] == 0) "" else raw_name;
        return try Value.strOwned(self.arena, try std.mem.concat(self.arena, u8, &.{ "function ", nm, "() { [native code] }" }));
    }

    /// True if `node` is an *anonymous* function/class definition — the
    /// syntactic predicate `IsAnonymousFunctionDefinition` that drives
    /// NamedEvaluation (`var f = function(){}` ⇒ `f.name === "f"`).
    fn isAnonFnDef(node: *Node) bool {
        return switch (node.*) {
            .function => |f| f.name.len == 0,
            // `export default function(){}` parses the body as a `func_decl`; an
            // anonymous one is named "default" by NamedEvaluation.
            .func_decl => |f| f.name.len == 0,
            .class_expr => |c| c.name.len == 0,
            else => false,
        };
    }

    /// NamedEvaluation: when an anonymous function/class produced by `init_node`
    /// is bound to the name `name` (a declaration, assignment, property, or
    /// destructuring default), give the still-unnamed function that name. The
    /// `name` own property is { writable:false, enumerable:false,
    /// configurable:true }, like every function name.
    /// Name an accessor function `"get name"` / `"set name"` (a non-writable,
    /// non-enumerable, configurable own `name` property), overriding the
    /// parser-assigned bare name.
    fn nameAccessor(self: *Interpreter, fnv: Value, prefix: []const u8, name_str: []const u8) EvalError!void {
        if (!fnv.isObject() or !fnv.asObj().isCallableObject()) return;
        const nm = try std.fmt.allocPrint(self.arena, "{s} {s}", .{ prefix, name_str });
        try fnv.asObj().setOwn(self.arena, self.root_shape, "name", try Value.strAlloc(self.arena, nm));
        try fnv.asObj().setAttr(self.arena, "name", .{ .writable = false, .enumerable = false, .configurable = true });
        if (funcOf(fnv)) |f| f.name = nm;
    }

    /// The function-name string a property key contributes (PropertyName's name):
    /// a string key as-is, a symbol as `[description]` (or `""` when undescribed),
    /// else ToString. Used to name concise methods/accessors from their key.
    fn keyDisplayName(self: *Interpreter, kv: Value) EvalError![]const u8 {
        if (kv.isObject() and kv.asObj().is_symbol)
            return if (kv.asObj().symbolDescription()) |d| try std.fmt.allocPrint(self.arena, "[{s}]", .{d}) else "";
        if (kv.isString()) return kv.asWtf8(self.arena);
        return self.toStringWtf8(kv);
    }

    pub fn maybeNameAnon(self: *Interpreter, val: Value, init_node: *Node, name: []const u8) EvalError!void {
        if (!isAnonFnDef(init_node)) return;
        try self.nameAnonValue(val, name);
    }

    /// The naming step of NamedEvaluation, without the syntactic isAnonFnDef gate.
    /// The VM's `name_anon` opcode is emitted by the compiler only for a bare
    /// anonymous function/class value, so the gate is applied at compile time;
    /// `maybeNameAnon` above applies it for the tree-walker.
    pub fn nameAnonValue(self: *Interpreter, val: Value, name: []const u8) EvalError!void {
        if (name.len == 0) return;
        if (!val.isObject() or !val.asObj().isCallableObject()) return;
        const o = val.asObj();
        if (o.getOwn("name")) |c| {
            // Already has a meaningful own `name`: a non-empty string, or — for a
            // class with an explicit `static name(){}`/field — a non-string value.
            // Only an empty-string placeholder (a freshly-built anonymous class)
            // is overridable.
            if (!c.isString() or c.asStr().len != 0) return;
        }
        try o.setOwn(self.arena, self.root_shape, "name", try Value.strAlloc(self.arena, name));
        try o.setAttr(self.arena, "name", .{ .writable = false, .enumerable = false, .configurable = true });
        if (funcOf(val)) |f| f.name = name; // keep Function.name in sync
    }

    fn nextPrivateStorageKey(self: *Interpreter, name: []const u8) ![]const u8 {
        const id = if (self.private_name_serial) |serial|
            try mintUniqueAtomicSerial(u64, serial)
        else
            try mintUniqueLocalSerial(u64, &self.private_name_serial_local);
        return std.fmt.allocPrint(self.arena, "{s}\x00{d}", .{ name, id });
    }

    fn remapPrivateName(map: *std.StringHashMapUnmanaged([]const u8), name: []const u8) []const u8 {
        if (!value.isRawPrivateName(name)) return name;
        return map.get(name) orelse name;
    }

    fn rewritePrivateNamesInFunction(self: *Interpreter, f: *ast.FunctionNode, map: *std.StringHashMapUnmanaged([]const u8)) EvalError!void {
        for (f.params) |p| {
            if (p.default) |d| try self.rewritePrivateNamesInNode(d, map);
            if (p.pattern) |pat| try self.rewritePrivateNamesInNode(pat, map);
        }
        try self.rewritePrivateNamesInNode(f.body, map);
    }

    fn rewritePrivateNamesInNode(self: *Interpreter, node: *Node, map: *std.StringHashMapUnmanaged([]const u8)) EvalError!void {
        switch (node.*) {
            .identifier => |name| node.* = .{ .identifier = remapPrivateName(map, name) },
            .unary => |u| try self.rewritePrivateNamesInNode(u.operand, map),
            .delete_expr => |n| try self.rewritePrivateNamesInNode(n, map),
            .update => |u| try self.rewritePrivateNamesInNode(u.target, map),
            .binary => |b| {
                try self.rewritePrivateNamesInNode(b.left, map);
                try self.rewritePrivateNamesInNode(b.right, map);
            },
            .logical => |l| {
                try self.rewritePrivateNamesInNode(l.left, map);
                try self.rewritePrivateNamesInNode(l.right, map);
            },
            .sequence => |s| {
                try self.rewritePrivateNamesInNode(s.first, map);
                try self.rewritePrivateNamesInNode(s.second, map);
            },
            .assign => |a| {
                try self.rewritePrivateNamesInNode(a.target, map);
                try self.rewritePrivateNamesInNode(a.value, map);
            },
            .op_assign => |oa| {
                try self.rewritePrivateNamesInNode(oa.target, map);
                try self.rewritePrivateNamesInNode(oa.value, map);
            },
            .logical_assign => |la| {
                try self.rewritePrivateNamesInNode(la.target, map);
                try self.rewritePrivateNamesInNode(la.value, map);
            },
            .conditional => |c| {
                try self.rewritePrivateNamesInNode(c.cond, map);
                try self.rewritePrivateNamesInNode(c.consequent, map);
                try self.rewritePrivateNamesInNode(c.alternate, map);
            },
            .function => |f| try self.rewritePrivateNamesInFunction(f, map),
            .yield_expr => |y| if (y.argument) |a| try self.rewritePrivateNamesInNode(a, map),
            .await_expr => |a| try self.rewritePrivateNamesInNode(a.argument, map),
            .class_expr => |c| {
                if (c.superclass) |sc| try self.rewritePrivateNamesInNode(sc, map);
                var nested_map: std.StringHashMapUnmanaged([]const u8) = .empty;
                defer nested_map.deinit(self.arena);
                var it = map.iterator();
                while (it.next()) |entry| try nested_map.put(self.arena, entry.key_ptr.*, entry.value_ptr.*);
                for (c.members) |m| {
                    if (m.key_expr == null and value.isRawPrivateName(m.key)) _ = nested_map.remove(m.key);
                }
                for (c.members) |m| {
                    if (m.key_expr) |key_expr| try self.rewritePrivateNamesInNode(key_expr, map);
                    if (m.field_init) |init| try self.rewritePrivateNamesInNode(init, &nested_map);
                    if (m.func) |func| try self.rewritePrivateNamesInNode(func, &nested_map);
                    if (m.static_block) |block| try self.rewritePrivateNamesInNode(block, &nested_map);
                }
            },
            .super_call => |args| for (args) |arg_node| try self.rewritePrivateNamesInNode(arg_node, map),
            .super_member => |sm| {
                if (sm.computed) |c| {
                    try self.rewritePrivateNamesInNode(c, map);
                } else {
                    node.* = .{ .super_member = .{ .property = remapPrivateName(map, sm.property), .computed = null } };
                }
            },
            .call => |c| {
                try self.rewritePrivateNamesInNode(c.callee, map);
                for (c.args) |arg_node| try self.rewritePrivateNamesInNode(arg_node, map);
            },
            .new_expr => |n| {
                try self.rewritePrivateNamesInNode(n.callee, map);
                for (n.args) |arg_node| try self.rewritePrivateNamesInNode(arg_node, map);
            },
            .tagged_template => |t| {
                try self.rewritePrivateNamesInNode(t.tag, map);
                for (t.exprs) |expr| try self.rewritePrivateNamesInNode(expr, map);
            },
            .member => |m| {
                try self.rewritePrivateNamesInNode(m.object, map);
                if (m.computed) |c| {
                    try self.rewritePrivateNamesInNode(c, map);
                } else {
                    node.* = .{ .member = .{ .object = m.object, .property = remapPrivateName(map, m.property), .computed = null, .optional = m.optional } };
                }
            },
            .optional_chain => |n| try self.rewritePrivateNamesInNode(n, map),
            .field_init_value => |n| try self.rewritePrivateNamesInNode(n, map),
            .private_field_def => |d| try self.rewritePrivateNamesInNode(d.value, map),
            .object_lit => |props| for (props) |p| {
                if (p.key_expr) |ke| try self.rewritePrivateNamesInNode(ke, map);
                try self.rewritePrivateNamesInNode(p.value, map);
            },
            .array_lit => |items| for (items) |item| try self.rewritePrivateNamesInNode(item, map),
            .spread => |n| try self.rewritePrivateNamesInNode(n, map),
            .obj_pattern => |pat| {
                for (pat.props) |p| {
                    if (p.key_expr) |ke| try self.rewritePrivateNamesInNode(ke, map);
                    try self.rewritePrivateNamesInNode(p.target, map);
                    if (p.default) |d| try self.rewritePrivateNamesInNode(d, map);
                }
                // `({...this.#x} = …)`: the rest target may reference a private name.
                if (pat.rest) |r| try self.rewritePrivateNamesInNode(r, map);
            },
            .arr_pattern => |pat| {
                for (pat.elems) |el| {
                    if (el.target) |t| try self.rewritePrivateNamesInNode(t, map);
                    if (el.default) |d| try self.rewritePrivateNamesInNode(d, map);
                }
                if (pat.rest) |r| try self.rewritePrivateNamesInNode(r, map);
            },
            .var_decl => |vd| if (vd.init) |init| try self.rewritePrivateNamesInNode(init, map),
            .destructure_decl => |dd| {
                try self.rewritePrivateNamesInNode(dd.pattern, map);
                try self.rewritePrivateNamesInNode(dd.init, map);
            },
            .func_decl => |f| try self.rewritePrivateNamesInFunction(f, map),
            .return_stmt => |maybe| if (maybe) |r| try self.rewritePrivateNamesInNode(r, map),
            .throw_stmt => |n| try self.rewritePrivateNamesInNode(n, map),
            .try_stmt => |t| {
                try self.rewritePrivateNamesInNode(t.block, map);
                if (t.catch_param) |p| try self.rewritePrivateNamesInNode(p, map);
                if (t.catch_block) |b| try self.rewritePrivateNamesInNode(b, map);
                if (t.finally_block) |f| try self.rewritePrivateNamesInNode(f, map);
            },
            .labeled_stmt => |l| try self.rewritePrivateNamesInNode(l.body, map),
            .expr_stmt => |n| try self.rewritePrivateNamesInNode(n, map),
            .block, .decl_group, .program => |stmts| for (stmts) |stmt| try self.rewritePrivateNamesInNode(stmt, map),
            .if_stmt => |i| {
                try self.rewritePrivateNamesInNode(i.cond, map);
                try self.rewritePrivateNamesInNode(i.consequent, map);
                if (i.alternate) |a| try self.rewritePrivateNamesInNode(a, map);
            },
            .while_stmt => |w| {
                try self.rewritePrivateNamesInNode(w.cond, map);
                try self.rewritePrivateNamesInNode(w.body, map);
            },
            .do_while_stmt => |d| {
                try self.rewritePrivateNamesInNode(d.body, map);
                try self.rewritePrivateNamesInNode(d.cond, map);
            },
            .for_stmt => |f| {
                if (f.init) |n| try self.rewritePrivateNamesInNode(n, map);
                if (f.cond) |n| try self.rewritePrivateNamesInNode(n, map);
                if (f.update) |n| try self.rewritePrivateNamesInNode(n, map);
                try self.rewritePrivateNamesInNode(f.body, map);
            },
            .for_in => |f| {
                try self.rewritePrivateNamesInNode(f.target, map);
                if (f.var_init) |ini| try self.rewritePrivateNamesInNode(ini, map);
                try self.rewritePrivateNamesInNode(f.iterable, map);
                try self.rewritePrivateNamesInNode(f.body, map);
            },
            .switch_stmt => |s| {
                try self.rewritePrivateNamesInNode(s.disc, map);
                for (s.cases) |case| {
                    if (case.@"test") |t| try self.rewritePrivateNamesInNode(t, map);
                    for (case.body) |stmt| try self.rewritePrivateNamesInNode(stmt, map);
                }
            },
            .with_stmt => |w| {
                try self.rewritePrivateNamesInNode(w.obj, map);
                try self.rewritePrivateNamesInNode(w.body, map);
            },
            .export_decl => |e| {
                if (e.declaration) |d| try self.rewritePrivateNamesInNode(d, map);
            },
            .import_call => |ic| {
                try self.rewritePrivateNamesInNode(ic.specifier, map);
                if (ic.options) |o| try self.rewritePrivateNamesInNode(o, map);
            },
            .number, .bigint_lit, .string, .boolean, .null_lit, .undefined_lit, .elision, .this_expr, .new_target_expr, .regex_literal, .break_stmt, .continue_stmt, .debugger_stmt, .import_decl, .import_meta => {},
        }
    }

    // ---- AST deep copy (for per-evaluation private-name rewriting) -------------
    // A class with private names is rewritten in place (`#x` → a unique storage
    // key). Two evaluations of the SAME class source (`classfactory()`) must get
    // DISTINCT keys, so each evaluation first deep-copies its member ASTs and
    // rewrites the copy — leaving the runtime (which reads the rewritten keys
    // directly, and works for nested classes / async / the VM) unchanged.

    fn deepCopyNodes(self: *Interpreter, nodes: []const *Node) EvalError![]*Node {
        const out = try self.arena.alloc(*Node, nodes.len);
        for (nodes, 0..) |n, i| out[i] = try self.deepCopyNode(n);
        return out;
    }

    fn deepCopyOpt(self: *Interpreter, n: ?*Node) EvalError!?*Node {
        return if (n) |x| try self.deepCopyNode(x) else null;
    }

    fn deepCopyFunction(self: *Interpreter, f: *const ast.FunctionNode) EvalError!*ast.FunctionNode {
        const nf = try self.arena.create(ast.FunctionNode);
        nf.* = f.*; // scalars + flags
        const params = try self.arena.alloc(ast.Param, f.params.len);
        for (f.params, 0..) |p, i| params[i] = .{
            .name = p.name,
            .default = try self.deepCopyOpt(p.default),
            .is_rest = p.is_rest,
            .pattern = try self.deepCopyOpt(p.pattern),
        };
        nf.params = params;
        nf.body = try self.deepCopyNode(f.body);
        return nf;
    }

    fn deepCopyClassMembers(self: *Interpreter, members: []const ast.ClassMember) EvalError![]ast.ClassMember {
        const out = try self.arena.alloc(ast.ClassMember, members.len);
        for (members, 0..) |m, i| {
            out[i] = m; // scalars (key, flags, accessor/auto-accessor)
            out[i].key_expr = try self.deepCopyOpt(m.key_expr);
            out[i].func = try self.deepCopyOpt(m.func);
            out[i].field_init = try self.deepCopyOpt(m.field_init);
            out[i].static_block = try self.deepCopyOpt(m.static_block);
        }
        return out;
    }

    /// Deep-copy an AST subtree (string/number leaves share their immutable
    /// payloads; every node gets a fresh allocation so a later rewrite mutates
    /// only this copy). Exhaustive — the compiler flags any unhandled variant.
    fn deepCopyNode(self: *Interpreter, node: *const Node) EvalError!*Node {
        const n = try self.arena.create(Node);
        n.* = switch (node.*) {
            .number, .bigint_lit, .string, .boolean, .null_lit, .undefined_lit, .elision, .this_expr, .new_target_expr, .regex_literal, .identifier, .break_stmt, .continue_stmt, .import_decl, .import_meta => node.*,
            .unary => |u| .{ .unary = .{ .op = u.op, .operand = try self.deepCopyNode(u.operand) } },
            .delete_expr => |x| .{ .delete_expr = try self.deepCopyNode(x) },
            .update => |u| .{ .update = .{ .inc = u.inc, .prefix = u.prefix, .target = try self.deepCopyNode(u.target) } },
            .binary => |b| .{ .binary = .{ .op = b.op, .left = try self.deepCopyNode(b.left), .right = try self.deepCopyNode(b.right) } },
            .logical => |l| .{ .logical = .{ .op = l.op, .left = try self.deepCopyNode(l.left), .right = try self.deepCopyNode(l.right) } },
            .sequence => |s| .{ .sequence = .{ .first = try self.deepCopyNode(s.first), .second = try self.deepCopyNode(s.second) } },
            .assign => |a| .{ .assign = .{ .target = try self.deepCopyNode(a.target), .value = try self.deepCopyNode(a.value) } },
            .op_assign => |a| .{ .op_assign = .{ .target = try self.deepCopyNode(a.target), .op = a.op, .value = try self.deepCopyNode(a.value) } },
            .logical_assign => |a| .{ .logical_assign = .{ .target = try self.deepCopyNode(a.target), .op = a.op, .value = try self.deepCopyNode(a.value) } },
            .conditional => |c| .{ .conditional = .{ .cond = try self.deepCopyNode(c.cond), .consequent = try self.deepCopyNode(c.consequent), .alternate = try self.deepCopyNode(c.alternate) } },
            .function => |f| .{ .function = try self.deepCopyFunction(f) },
            .yield_expr => |y| .{ .yield_expr = .{ .argument = try self.deepCopyOpt(y.argument), .delegate = y.delegate } },
            .await_expr => |a| .{ .await_expr = .{ .argument = try self.deepCopyNode(a.argument) } },
            .class_expr => |c| .{ .class_expr = .{ .name = c.name, .inferred_name = c.inferred_name, .superclass = try self.deepCopyOpt(c.superclass), .members = try self.deepCopyClassMembers(c.members), .source = c.source } },
            .super_call => |args| .{ .super_call = try self.deepCopyNodes(args) },
            .super_member => |sm| .{ .super_member = .{ .property = sm.property, .computed = try self.deepCopyOpt(sm.computed) } },
            .call => |c| .{ .call = .{ .callee = try self.deepCopyNode(c.callee), .args = try self.deepCopyNodes(c.args), .optional = c.optional } },
            .new_expr => |x| .{ .new_expr = .{ .callee = try self.deepCopyNode(x.callee), .args = try self.deepCopyNodes(x.args) } },
            .tagged_template => |t| .{ .tagged_template = .{ .tag = try self.deepCopyNode(t.tag), .cooked = t.cooked, .raw = t.raw, .exprs = try self.deepCopyNodes(t.exprs) } },
            .member => |m| .{ .member = .{ .object = try self.deepCopyNode(m.object), .property = m.property, .computed = try self.deepCopyOpt(m.computed), .optional = m.optional } },
            .optional_chain => |x| .{ .optional_chain = try self.deepCopyNode(x) },
            .field_init_value => |x| .{ .field_init_value = try self.deepCopyNode(x) },
            .private_field_def => |d| .{ .private_field_def = .{ .name = d.name, .value = try self.deepCopyNode(d.value) } },
            .object_lit => |props| blk: {
                const out = try self.arena.alloc(ast.Property, props.len);
                for (props, 0..) |p, i| out[i] = .{ .key = p.key, .key_expr = try self.deepCopyOpt(p.key_expr), .value = try self.deepCopyNode(p.value), .accessor = p.accessor, .is_spread = p.is_spread, .proto_setter = p.proto_setter };
                break :blk .{ .object_lit = out };
            },
            .array_lit => |items| .{ .array_lit = try self.deepCopyNodes(items) },
            .spread => |x| .{ .spread = try self.deepCopyNode(x) },
            .obj_pattern => |pat| blk: {
                const props = try self.arena.alloc(ast.ObjPatProp, pat.props.len);
                for (pat.props, 0..) |p, i| props[i] = .{ .key = p.key, .key_expr = try self.deepCopyOpt(p.key_expr), .target = try self.deepCopyNode(p.target), .default = try self.deepCopyOpt(p.default) };
                break :blk .{ .obj_pattern = .{ .props = props, .rest = try self.deepCopyOpt(pat.rest) } };
            },
            .arr_pattern => |pat| blk: {
                const elems = try self.arena.alloc(ast.ArrPatElem, pat.elems.len);
                for (pat.elems, 0..) |el, i| elems[i] = .{ .target = try self.deepCopyOpt(el.target), .default = try self.deepCopyOpt(el.default) };
                break :blk .{ .arr_pattern = .{ .elems = elems, .rest = try self.deepCopyOpt(pat.rest) } };
            },
            .var_decl => |vd| .{ .var_decl = .{ .kind = vd.kind, .name = vd.name, .init = try self.deepCopyOpt(vd.init), .dispose = vd.dispose } },
            .destructure_decl => |dd| .{ .destructure_decl = .{ .kind = dd.kind, .pattern = try self.deepCopyNode(dd.pattern), .init = try self.deepCopyNode(dd.init) } },
            .func_decl => |f| .{ .func_decl = try self.deepCopyFunction(f) },
            .return_stmt => |x| .{ .return_stmt = try self.deepCopyOpt(x) },
            .throw_stmt => |x| .{ .throw_stmt = try self.deepCopyNode(x) },
            .try_stmt => |t| blk: {
                const nt = try self.arena.create(ast.TryNode);
                nt.* = .{ .block = try self.deepCopyNode(t.block), .catch_param = try self.deepCopyOpt(t.catch_param), .catch_block = try self.deepCopyOpt(t.catch_block), .finally_block = try self.deepCopyOpt(t.finally_block) };
                break :blk .{ .try_stmt = nt };
            },
            .labeled_stmt => |l| .{ .labeled_stmt = .{ .label = l.label, .body = try self.deepCopyNode(l.body) } },
            .expr_stmt => |x| .{ .expr_stmt = try self.deepCopyNode(x) },
            .block => |stmts| .{ .block = try self.deepCopyNodes(stmts) },
            .debugger_stmt => .debugger_stmt,
            .decl_group => |stmts| .{ .decl_group = try self.deepCopyNodes(stmts) },
            .if_stmt => |i| .{ .if_stmt = .{ .cond = try self.deepCopyNode(i.cond), .consequent = try self.deepCopyNode(i.consequent), .alternate = try self.deepCopyOpt(i.alternate) } },
            .while_stmt => |w| .{ .while_stmt = .{ .cond = try self.deepCopyNode(w.cond), .body = try self.deepCopyNode(w.body) } },
            .do_while_stmt => |d| .{ .do_while_stmt = .{ .body = try self.deepCopyNode(d.body), .cond = try self.deepCopyNode(d.cond) } },
            .for_stmt => |f| .{ .for_stmt = .{ .init = try self.deepCopyOpt(f.init), .cond = try self.deepCopyOpt(f.cond), .update = try self.deepCopyOpt(f.update), .body = try self.deepCopyNode(f.body) } },
            .for_in => |f| .{ .for_in = .{ .decl_kind = f.decl_kind, .target = try self.deepCopyNode(f.target), .var_init = try self.deepCopyOpt(f.var_init), .iterable = try self.deepCopyNode(f.iterable), .body = try self.deepCopyNode(f.body), .is_of = f.is_of, .is_await = f.is_await, .dispose = f.dispose } },
            .switch_stmt => |s| blk: {
                const cases = try self.arena.alloc(ast.SwitchCase, s.cases.len);
                for (s.cases, 0..) |c, i| cases[i] = .{ .@"test" = try self.deepCopyOpt(c.@"test"), .body = try self.deepCopyNodes(c.body) };
                break :blk .{ .switch_stmt = .{ .disc = try self.deepCopyNode(s.disc), .cases = cases } };
            },
            .with_stmt => |w| .{ .with_stmt = .{ .obj = try self.deepCopyNode(w.obj), .body = try self.deepCopyNode(w.body) } },
            .export_decl => node.*, // exports never appear inside a class body
            .import_call => |ic| .{ .import_call = .{ .specifier = try self.deepCopyNode(ic.specifier), .options = try self.deepCopyOpt(ic.options), .phase = ic.phase } },
            .program => |stmts| .{ .program = try self.deepCopyNodes(stmts) },
        };
        return n;
    }

    /// Rewrite this class's private names (`#x` → a unique storage key) in member
    /// keys and bodies, and return the raw→storage map (persisted in the arena) so
    /// the class's functions can resolve private names a direct eval references.
    /// Returns null when the class declares no private names.
    fn rewriteClassPrivateNames(self: *Interpreter, members: []ast.ClassMember) EvalError!?*const std.StringHashMapUnmanaged([]const u8) {
        const map = try self.arena.create(std.StringHashMapUnmanaged([]const u8));
        map.* = .empty;
        for (members) |m| {
            if (m.key_expr != null or !value.isRawPrivateName(m.key) or map.contains(m.key)) continue;
            try map.put(self.arena, m.key, try self.nextPrivateStorageKey(m.key));
        }
        if (map.count() == 0) return null;
        for (members) |*m| {
            m.key = remapPrivateName(map, m.key);
            // A computed key (`[expr]`) may itself reference a private name —
            // `[self.#f]` — so rewrite it too, else the raw `#f` is mistaken for a
            // public property at runtime.
            if (m.key_expr) |ke| try self.rewritePrivateNamesInNode(ke, map);
            if (m.field_init) |init| try self.rewritePrivateNamesInNode(init, map);
            if (m.func) |func| try self.rewritePrivateNamesInNode(func, map);
            if (m.static_block) |block| try self.rewritePrivateNamesInNode(block, map);
        }
        return map;
    }

    /// Evaluate a `class` to a constructor function value: methods go on its
    /// `.prototype`, static members on the class object itself, and instance
    /// fields are desugared into the constructor (`this.f = init`). With
    /// `extends`, the prototypes are linked and methods get a home object so
    /// `super.x` / `super(...)` resolve. (Accessors are still deferred.)
    fn evalClass(self: *Interpreter, name: []const u8, inferred_name: []const u8, superclass: ?*Node, members: []ast.ClassMember, source: []const u8) EvalError!Value {
        return self.evalClassWithComputedKeys(name, inferred_name, superclass, members, source, null);
    }

    pub const PreparedClassHeritage = struct {
        constructor: Value,
        prototype: Value,
    };

    /// ClassDefinitionEvaluation's heritage validation. Keep this separate from
    /// class construction so resumable bytecode can perform the observable
    /// `prototype` lookup before computed element names, then retain both precise
    /// Values on its activation stack across a yield/await.
    pub fn prepareClassHeritage(self: *Interpreter, superclass: Value) EvalError!PreparedClassHeritage {
        if (superclass.isNull()) return .{ .constructor = Value.nul(), .prototype = Value.nul() };
        if (!isConstructorValue(superclass))
            return self.throwError("TypeError", "class extends value is not a constructor");

        const prototype = try self.getProperty(superclass, "prototype");
        if (prototype.isObject() and !prototype.asObj().is_symbol and !prototype.asObj().is_bigint)
            return .{ .constructor = superclass, .prototype = prototype };
        if (prototype.isNull())
            return .{ .constructor = superclass, .prototype = Value.nul() };
        return self.throwError("TypeError", "class heritage's 'prototype' is not an object or null");
    }

    pub fn evalClassWithComputedKeys(self: *Interpreter, name: []const u8, inferred_name: []const u8, superclass: ?*Node, members: []ast.ClassMember, source: []const u8, computed_keys: ?[]const Value) EvalError!Value {
        // A class with ClassHeritage is a *derived* class even when the heritage
        // is `null` (`class C extends null`): the constructor is a derived
        // constructor (its `this` is uninitialized until a — here impossible —
        // `super()`), its prototype's [[Prototype]] is null, and its constructor's
        // [[Prototype]] is %Function.prototype% (the makeFunction default).
        const derived = superclass != null;
        // The class name is a binding in a scope that wraps the WHOLE class,
        // including the heritage expression — where the name is in TDZ, so
        // `class x extends x {}` is a ReferenceError. Create that scope before
        // evaluating heritage; buildClass installs the actual (const) binding once
        // the constructor exists.
        const outer_env = self.env;
        const class_env = try gc_mod.allocEnv(self.arena);
        self.initEnvironment(class_env, outer_env, false);
        self.env = class_env;
        defer self.env = outer_env;
        const saved_strict = self.strict;
        self.strict = true;
        defer self.strict = saved_strict;
        if (name.len > 0) try class_env.put(name, self.tdzVal());
        const prepared = if (superclass) |sc| try self.prepareClassHeritage(try self.eval(sc)) else null;
        return self.buildClass(
            name,
            inferred_name,
            members,
            if (prepared) |heritage| if (heritage.constructor.isNull()) null else heritage.constructor.asObj() else null,
            if (prepared) |heritage| if (heritage.prototype.isNull()) null else heritage.prototype.asObj() else null,
            source,
            derived,
            class_env,
            computed_keys,
        );
    }

    /// Finish a bytecode-lowered class after the compiler has already entered its
    /// lexical Environment, evaluated/validated heritage, and evaluated computed
    /// names. No observable lookup is repeated here.
    pub fn evalClassWithPreparedHeritage(
        self: *Interpreter,
        name: []const u8,
        inferred_name: []const u8,
        members: []ast.ClassMember,
        source: []const u8,
        heritage: ?PreparedClassHeritage,
        computed_keys: []const Value,
    ) EvalError!Value {
        const saved_strict = self.strict;
        self.strict = true;
        defer self.strict = saved_strict;
        return self.buildClass(
            name,
            inferred_name,
            members,
            if (heritage) |prepared| if (prepared.constructor.isNull()) null else prepared.constructor.asObj() else null,
            if (heritage) |prepared| if (prepared.prototype.isNull()) null else prepared.prototype.asObj() else null,
            source,
            heritage != null,
            self.env,
            computed_keys,
        );
    }

    fn buildClass(self: *Interpreter, name: []const u8, inferred_name: []const u8, members_arg: []ast.ClassMember, super_obj: ?*value.Object, super_proto: ?*value.Object, source: []const u8, derived: bool, class_env: *Environment, computed_keys: ?[]const Value) EvalError!Value {
        // A class with private names is rewritten (`#x` → a unique storage key) in
        // place. Deep-copy the member ASTs first so EACH evaluation rewrites its
        // own copy — two evaluations of the same class source then have distinct
        // private names (the `classfactory()` / multiple-evaluations tests).
        var has_private = false;
        for (members_arg) |m| {
            if (m.key_expr == null and value.isRawPrivateName(m.key)) {
                has_private = true;
                break;
            }
        }
        const members = if (has_private) try self.deepCopyClassMembers(members_arg) else members_arg;
        const private_map = try self.rewriteClassPrivateNames(members);
        // Execute the class's static elements / field initializers with this
        // class's private map active, so a direct eval in them resolves the
        // class's private names.
        const saved_pm = self.current_private_map;
        self.current_private_map = private_map;
        defer self.current_private_map = saved_pm;

        // `class_env` (created by evalClass or entered by class bytecode, and
        // already current) wraps the class body. The class name is bound there
        // once the constructor exists, so methods, static initializers, and
        // instance-field initializers can refer to it (`static x = C.m()`).

        // Instance field initializers, prepended to the constructor body.
        var field_inits: std.ArrayListUnmanaged(*Node) = .empty;
        const auto_storage_keys = try self.arena.alloc([]const u8, members.len);
        for (members, 0..) |m, i| {
            auto_storage_keys[i] = if (m.is_auto_accessor)
                try self.nextPrivateStorageKey("#<auto-accessor>")
            else
                "";
        }
        // The desugared `this.<name> = init` member node of each PUBLIC instance
        // field with a computed name, by member index. A computed field name is
        // evaluated ONCE (at class definition, in source order); the member loop
        // below bakes that key into the node so it is not re-evaluated for every
        // instance.
        const field_member_nodes = try self.arena.alloc(?*Node, members.len);
        @memset(field_member_nodes, null);
        for (members, 0..) |m, i| {
            if (!m.is_field or m.is_static) continue;
            const this_node = try self.arena.create(Node);
            this_node.* = .this_expr;
            const member_node = try self.arena.create(Node);
            member_node.* = .{ .member = .{ .object = this_node, .property = m.key, .computed = m.key_expr } };
            if (m.key_expr != null) field_member_nodes[i] = member_node;
            const raw_value = m.field_init orelse blk: {
                const u = try self.arena.create(Node);
                u.* = .undefined_lit;
                break :blk u;
            };
            // Wrap the initializer so a direct eval inside it sees the
            // field-initializer context (no `super()` / `arguments`).
            // Even a field without an explicit initializer performs DefineField
            // with `undefined`; retain the wrapper so it cannot fall through to
            // ordinary assignment semantics (notably for Symbol keys and an
            // inherited setter).
            const value_node = try self.arena.create(Node);
            value_node.* = .{ .field_init_value = raw_value };
            const stmt = try self.arena.create(Node);
            // A private field is *defined* (PrivateFieldAdd) on `this`, not
            // assigned via PrivateSet; a public field is an ordinary assignment.
            if (m.is_auto_accessor) {
                stmt.* = .{ .private_field_def = .{ .name = auto_storage_keys[i], .value = value_node } };
            } else if (m.key_expr == null and value.isPrivateKey(m.key)) {
                stmt.* = .{ .private_field_def = .{ .name = m.key, .value = value_node } };
            } else {
                const assign_node = try self.arena.create(Node);
                assign_node.* = .{ .assign = .{ .target = member_node, .value = value_node } };
                stmt.* = .{ .expr_stmt = assign_node };
            }
            try field_inits.append(self.arena, stmt);
        }

        // Constructor: explicit (augmented with field inits) or default. For a
        // derived class with no explicit constructor, synthesize
        // `constructor(...args) { super(...args); }`.
        var ctor_node: ?*const ast.FunctionNode = null;
        for (members) |m| {
            if (m.is_ctor) ctor_node = m.func.?.function;
        }
        var default_params: []const ast.Param = &.{};
        var default_super: []*Node = &.{};
        if (ctor_node == null and derived) {
            const args_id = try self.arena.create(Node);
            args_id.* = .{ .identifier = "args" };
            const spread_node = try self.arena.create(Node);
            spread_node.* = .{ .spread = args_id };
            const super_args = try self.arena.dupe(*Node, &.{spread_node});
            const super_node = try self.arena.create(Node);
            super_node.* = .{ .super_call = super_args };
            const stmt = try self.arena.create(Node);
            stmt.* = .{ .expr_stmt = super_node };
            default_super = try self.arena.dupe(*Node, &.{stmt});
            default_params = try self.arena.dupe(ast.Param, &.{.{ .name = "args", .is_rest = true }});
        }
        const orig: []*Node = if (ctor_node) |cf| cf.body.block else default_super;
        // Instance elements are not ordinary constructor-body statements. A base
        // class initializes them before parameter default evaluation; a derived
        // class initializes them when `super()` returns.
        const body_stmts = orig;
        const body = try self.arena.create(Node);
        body.* = .{ .block = body_stmts };
        const fnode = try self.arena.create(ast.FunctionNode);
        const display_name = if (inferred_name.len > 0) inferred_name else name;
        fnode.* = .{
            .name = display_name,
            .params = if (ctor_node) |cf| cf.params else default_params,
            .body = body,
            .source = source,
            .is_expr_body = false,
            // Preserve the parser's exact conservative ruling. FunctionNode's
            // default is true for hand-built nodes, which otherwise forces an
            // unused arguments exotic and blocks bytecode for every class
            // constructor synthesized here.
            .uses_arguments = if (ctor_node) |cf| cf.uses_arguments else false,
            .uses_direct_eval = if (ctor_node) |cf| cf.uses_direct_eval else false,
            .requires_tree_walk_class_constructor = false,
            .class_instance_initializers = field_inits.items,
            .is_derived_class_constructor = derived,
            .is_default_class_constructor = derived and ctor_node == null,
            .defer_plain_bytecode_compilation = field_inits.items.len != 0,
            // All class code is strict, so the constructor is a strict function
            // (e.g. its `.caller`/`.arguments` hit the %ThrowTypeError% poison pill
            // rather than the legacy sloppy `null`).
            .is_strict = true,
        };
        const class_val = try self.makeFunction(fnode, self.env);
        const class_obj = class_val.asObj();
        const proto = try self.protoObject(class_obj);
        // A class's `prototype` is non-writable, non-enumerable, non-configurable.
        try class_obj.setAttr(self.arena, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
        // The `constructor` back-link is created BEFORE the class element methods,
        // so a same-named element — e.g. a *computed* `['constructor']() {}`, which
        // is an ordinary method, not the class constructor — overrides it.
        try self.setProp(proto, "constructor", class_val);
        try proto.setAttr(self.arena, "constructor", .{ .writable = true, .enumerable = false, .configurable = true });

        // Link the prototype chains for inheritance.
        if (super_obj) |so| {
            proto.setProtoAtomic(super_proto);
            class_obj.setProtoAtomic(so); // static methods inherit
        } else if (derived) {
            // `extends null`: the prototype object's [[Prototype]] is null; the
            // constructor's [[Prototype]] stays %Function.prototype%.
            proto.setProtoAtomic(null);
        }
        // The constructor's home object is the prototype; super(...) targets the superclass.
        if (funcOf(class_val)) |cf| {
            cf.home_object = proto;
            cf.super_ctor = super_obj;
            cf.private_map = private_map; // a direct eval in a field initializer resolves private names
            cf.is_class_constructor = true;
            cf.is_derived_constructor = derived;
            cf.is_default_ctor = derived and ctor_node == null;
            cf.derived_constructor = if (derived) class_obj else null;
            cf.field_inits = field_inits.items;
            // Private brands. Methods/accessors are added all at once before field
            // initializers run, so they brand the instance up front; *fields* are
            // added in declaration order, so each field brands the instance at its
            // own initializer (`private_field_def`) — a field referenced before its
            // declaration must still throw. Static members brand the class object.
            var brand_names: std.ArrayListUnmanaged([]const u8) = .empty;
            for (members) |m| {
                if (m.key_expr != null or m.static_block != null or m.key.len == 0 or m.key[0] != '#') continue;
                if (m.is_field) continue; // fields brand at their initializer
                if (m.is_static) {
                    try class_obj.addPrivateBrand(self.arena, m.key);
                } else {
                    // A `get #x` / `set #x` pair shares one private name, so the
                    // instance is branded with it only once.
                    var dup = false;
                    for (brand_names.items) |bn| if (eq(bn, m.key)) {
                        dup = true;
                        break;
                    };
                    if (!dup) try brand_names.append(self.arena, m.key);
                }
            }
            cf.private_brand_names = brand_names.items;
        }

        // ClassDefinitionEvaluation splits into two source-order passes. Pass 1
        // (this loop) is step 28: evaluate EVERY computed element name and define
        // methods/accessors; field names are evaluated here but their initializers
        // are deferred. Static field names/displaynames are stashed for pass 2.
        const static_keys = try self.arena.alloc([]const u8, members.len);
        const static_names = try self.arena.alloc([]const u8, members.len);
        var computed_i: usize = 0;
        for (members, 0..) |m, i| {
            // A `static { ... }` block has no name to evaluate; it runs in pass 2
            // (step 34), interleaved with static-field initializers in source order.
            if (m.static_block != null) continue;
            const kv: ?Value = if (m.key_expr) |ke| blk: {
                if (computed_keys) |keys| {
                    if (computed_i >= keys.len)
                        return self.throwError("TypeError", "missing computed class name");
                    const key = try self.toPropertyKeyValue(keys[computed_i]);
                    computed_i += 1;
                    break :blk key;
                }
                break :blk try self.toPropertyKeyValue(try self.eval(ke));
            } else null;
            const key = if (kv) |k| try self.keyOf(k) else try value.encodeStringKey(self.arena, m.key);
            // The name an anonymous field/method initializer takes from this key.
            // A private name (`#x`) was rewritten to the `#x\x00<serial>` storage
            // key, but its function name is the source form `#x` (the part before
            // the NUL marker).
            const name_str = if (kv) |k|
                try self.keyDisplayName(k)
            else if (value.isPrivateKey(m.key))
                std.mem.sliceTo(m.key, 0)
            else
                m.key;
            // A public instance field's computed NAME was just evaluated here,
            // once and in source order. Bake the resulting key into its desugared
            // per-instance initializer so the name expression does not re-run for
            // every `new` (and its side effects happen exactly once).
            if (kv != null and m.is_field and !m.is_static) {
                if (field_member_nodes[i]) |mn| {
                    // `key` may be a slice owned by a temporary StringCell. The
                    // initializer AST and its deferred bytecode chunk outlive
                    // that cell and are not relocation slots, so retain an
                    // arena-owned encoded key before a moving collection can
                    // invalidate the borrowed bytes.
                    mn.member.property = try self.arena.dupe(u8, key);
                    mn.member.computed = null;
                }
            }
            // A static class element may not have the key "prototype" — the
            // constructor's `prototype` is a reserved, non-configurable own
            // property. The non-computed form is a parse SyntaxError; a computed
            // key resolving to "prototype" is a runtime TypeError.
            if (m.is_static and !m.is_ctor and !value.isPrivateKey(key) and eq(key, "prototype"))
                return self.throwError("TypeError", "Classes may not have a static property named 'prototype'");
            if (m.is_field) {
                if (m.is_auto_accessor) {
                    const home = if (m.is_static) class_obj else proto;
                    try self.defineAutoAccessor(home, key, auto_storage_keys[i], name_str);
                    try home.setAttr(self.arena, key, .{ .writable = false, .enumerable = false, .configurable = true });
                }
                // A static field's name is now resolved; its initializer (DefineField)
                // is deferred to pass 2 so every element's name is evaluated first.
                if (m.is_static) {
                    static_keys[i] = key;
                    static_names[i] = name_str;
                }
                continue;
            }
            if (m.is_ctor) continue;
            const fv = try self.eval(m.func.?);
            const home = if (m.is_static) class_obj else proto;
            if (funcOf(fv)) |mf| {
                mf.home_object = home;
                mf.super_ctor = super_obj;
                mf.private_map = private_map; // a direct eval in this method resolves the class's private names
            }
            switch (m.accessor) {
                .none => {
                    // Name a computed/symbol-keyed method ("[desc]"); a plain
                    // `m(){}` already carries its parser-assigned name.
                    try self.maybeNameAnon(fv, m.func.?, name_str);
                    if (!value.isPrivateKey(key)) switch (try home.deleteAccessorOwnPreserveOrder(self.arena, key)) {
                        .absent, .deleted, .removed_continue => {},
                        .blocked => return self.throwError("TypeError", "Cannot redefine class element"),
                    };
                    try self.setProp(home, key, fv);
                },
                .get => {
                    try self.nameAccessor(fv, "get", name_str);
                    if (!value.isPrivateKey(key) and !(try home.deleteNamedDataOwnPreserveOrder(self.arena, self.root_shape, key)))
                        return self.throwError("TypeError", "Cannot redefine class element");
                    try self.defineAccessor(home, key, fv, null);
                },
                .set => {
                    try self.nameAccessor(fv, "set", name_str);
                    if (!value.isPrivateKey(key) and !(try home.deleteNamedDataOwnPreserveOrder(self.arena, self.root_shape, key)))
                        return self.throwError("TypeError", "Cannot redefine class element");
                    try self.defineAccessor(home, key, null, fv);
                },
            }
            // Class methods/accessors are non-enumerable (writable + configurable),
            // unlike object-literal properties.
            try home.setAttr(self.arena, key, .{ .writable = !(value.isPrivateKey(key) and m.accessor == .none), .enumerable = false, .configurable = true });
        }
        if (computed_keys) |keys| if (computed_i != keys.len)
            return self.throwError("TypeError", "too many computed class names");

        // The constructor object must exist before computed names run, but its
        // bytecode must see the one-time keys baked above. Complete admission
        // exactly once now; no tree-walker callback or per-instance key work is
        // introduced by this deferred compilation point.
        if (fnode.defer_plain_bytecode_compilation) if (funcOf(class_val)) |cf| {
            const reason = try self.installPlainFunctionBytecode(cf, fnode);
            cf.bytecode_admission_reason = reason;
            self.recordBytecodeAdmission(reason);
        };

        // Computed element names run while the inner class binding is still in
        // TDZ. Once names/methods are installed, initialize the immutable
        // binding so static elements and later method bodies can reference it.
        if (name.len > 0) try class_env.putConst(name, class_val);

        // Pass 2 (step 34): run the static elements — `static { }` blocks and
        // static-field initializers — in source order, now that EVERY computed
        // name (including later instance/static field names) has been evaluated.
        // `this`/home is the class object so `super` and arrows resolve correctly.
        for (members, 0..) |m, i| {
            if (m.static_block) |block| {
                const saved_this = self.this_value;
                const saved_home = self.home_object;
                const saved_env = self.env;
                self.this_value = class_val;
                self.home_object = class_obj;
                // A `static {}` block is its own function-like scope: it gets a
                // fresh variable environment so its `var` declarations stay local
                // (each block, and the outer scope, are independent).
                const block_env = try gc_mod.allocEnv(self.arena);
                self.initEnvironment(block_env, class_env, true);
                self.env = block_env;
                if (block.* == .block) try self.hoistVarNames(block.block);
                _ = self.eval(block) catch |e| {
                    self.this_value = saved_this;
                    self.home_object = saved_home;
                    self.env = saved_env;
                    return e;
                };
                self.this_value = saved_this;
                self.home_object = saved_home;
                self.env = saved_env;
                continue;
            }
            if (!m.is_field or !m.is_static) continue;
            const key = static_keys[i];
            const name_str = static_names[i];
            const saved_this = self.this_value;
            const saved_home = self.home_object;
            const saved_fi = self.in_field_initializer;
            self.this_value = class_val;
            self.home_object = class_obj;
            self.in_field_initializer = true;
            // DefineField order: evaluate the initializer FIRST, then
            // PrivateFieldAdd (brand + extensibility check) — so a static private
            // field whose initializer seals the class object makes its own add throw.
            const fv2 = if (m.field_init) |init_node| self.eval(init_node) catch |e| {
                self.this_value = saved_this;
                self.home_object = saved_home;
                self.in_field_initializer = saved_fi;
                return e;
            } else Value.undef();
            self.this_value = saved_this;
            self.home_object = saved_home;
            self.in_field_initializer = saved_fi;
            if (m.field_init) |fi| try self.maybeNameAnon(fv2, fi, name_str);
            if (m.is_auto_accessor) {
                const storage_key = auto_storage_keys[i];
                try self.addPrivateBrandChecked(class_obj, storage_key);
                try class_obj.setOwn(self.arena, self.root_shape, storage_key, fv2);
                try class_obj.setAttr(self.arena, storage_key, .{ .writable = true, .enumerable = false, .configurable = false });
            } else {
                if (value.isPrivateKey(key)) try self.addPrivateBrandChecked(class_obj, key);
                try self.setProp(class_obj, key, fv2);
            }
        }
        return class_val;
    }

    fn evalArgs(self: *Interpreter, arg_nodes: []*Node) EvalError![]Value {
        // Fast path: no spreads → fixed-size slice.
        var has_spread = false;
        for (arg_nodes) |an| {
            if (an.* == .spread) has_spread = true;
        }
        if (!has_spread) {
            const args = try self.arena.alloc(Value, arg_nodes.len);
            for (arg_nodes, 0..) |an, i| args[i] = try self.eval(an);
            return args;
        }
        var list: std.ArrayListUnmanaged(Value) = .empty;
        for (arg_nodes) |an| {
            if (an.* == .spread) {
                try self.spreadInto(&list, try self.eval(an.spread));
            } else {
                try list.append(self.arena, try self.eval(an));
            }
        }
        return list.items;
    }

    /// Expand an iterable into `list` for `...spread`. The full iterator protocol
    /// is required even for packed arrays: `%ArrayIteratorPrototype%.next` is an
    /// observable mutable property, so a direct element-copy shortcut would skip
    /// both its lookup and calls.
    pub fn spreadInto(self: *Interpreter, list: *std.ArrayListUnmanaged(Value), v: Value) EvalError!void {
        // A nullish spread argument reports the spread-specific message rather
        // than the generic nullish-base one; both tiers route through here.
        if (v.isUndefined() or v.isNull())
            return self.throwError("TypeError", "Spread syntax requires ...iterable not be null or undefined");
        const record = try self.getIteratorRecord(v); // throws TypeError if not iterable
        const iter_obj = record.iterator;
        const iter_root = try self.pushTempRoot(iter_obj);
        defer self.restoreTempRoots(iter_root);
        // GetIterator reads the `next` method exactly ONCE and reuses it for every
        // step; re-reading it per step (a `get next()` accessor, or a mutated slot)
        // is observable and non-conformant.
        const next_method = record.next_method;
        const next_root = try self.pushTempRoot(next_method);
        defer self.restoreTempRoots(next_root);
        while (true) {
            const res = try self.callValueWithThis(next_method, &.{}, iter_obj);
            if (!builtins.isRealObject(res)) return self.throwError("TypeError", "iterator result is not an object");
            if ((try self.getProperty(res, "done")).toBoolean()) break;
            try list.append(self.arena, try self.getProperty(res, "value"));
        }
    }

    fn deleteMemberExpression(self: *Interpreter, m: anytype) EvalError!Value {
        const obj = self.eval(m.object) catch |e|
            if (e == error.OptShortCircuit) return Value.boolVal(true) else return e;
        // Optional property access decides before evaluating a computed key.
        // Ordinary access evaluates that expression once, but [[Delete]] checks
        // the base before ToPropertyKey (observable for object-valued keys).
        if (m.optional and (obj.isNull() or obj.isUndefined())) return Value.boolVal(true);
        const computed_key: ?Value = if (m.computed) |ce| try self.eval(ce) else null;
        const key = if (computed_key) |raw| DeletePropertyKey{ .computed = raw } else DeletePropertyKey{ .named = try value.encodeStringKey(self.arena, m.property) };
        return Value.boolVal(try self.deletePropertyValue(obj, key, self.strict));
    }

    const DeletePropertyKey = union(enum) {
        named: []const u8,
        computed: Value,

        fn resolve(self: @This(), interpreter: *Interpreter) EvalError![]const u8 {
            return switch (self) {
                .named => |name| name,
                .computed => |raw| interpreter.keyOf(raw),
            };
        }
    };

    /// Apply DeletePropertyOrThrow/[[Delete]] to an already-evaluated property
    /// reference. Computed-key evaluation belongs to the caller; ToPropertyKey
    /// deliberately stays here, after RequireObjectCoercible, matching ECMA-262
    /// Delete Operator Evaluation and preserving proxy/Symbol behavior.
    pub fn deleteNamedProperty(self: *Interpreter, obj: Value, key: []const u8, strict: bool) EvalError!bool {
        return self.deletePropertyValue(obj, .{ .named = key }, strict);
    }

    pub fn deleteComputedProperty(self: *Interpreter, obj: Value, key: Value, strict: bool) EvalError!bool {
        return self.deletePropertyValue(obj, .{ .computed = key }, strict);
    }

    fn deletePropertyValue(self: *Interpreter, obj: Value, key_ref: DeletePropertyKey, strict: bool) EvalError!bool {
        if (obj.isNull() or obj.isUndefined())
            return self.throwError("TypeError", "Cannot convert undefined or null to object");
        if (!obj.isObject()) {
            // ToObject succeeds for every remaining primitive. Its ordinary
            // [[Delete]] still receives a PropertyKey even when the wrapper has
            // no own properties, so object-key coercion remains observable for
            // Number/Boolean as well as String values.
            const key = try key_ref.resolve(self);
            if (obj.isString()) {
                if (std.mem.eql(u8, key, "length")) {
                    if (strict) return self.throwError("TypeError", "Cannot delete property");
                    return false;
                }
                if (arrayIndex(key)) |i| if (i < utf16LenOfValue(obj)) {
                    if (strict) return self.throwError("TypeError", "Cannot delete property");
                    return false;
                };
            }
            return true;
        }
        const key = try key_ref.resolve(self);
        const ok = try self.deleteOwn(obj.asObj(), key);
        // Strict mode: a failed delete (a non-configurable property) is a
        // TypeError rather than a `false` result.
        if (!ok and strict) return self.throwError("TypeError", "Cannot delete property");
        return ok;
    }

    fn evalCall(self: *Interpreter, callee_node: *Node, arg_nodes: []*Node, optional: bool) EvalError!Value {
        if (callee_node.* == .optional_chain and callee_node.optional_chain.* == .member) {
            const m = callee_node.optional_chain.member;
            const recv_opt: ?Value = self.eval(m.object) catch |err|
                if (err == error.OptShortCircuit) null else return err;
            if (recv_opt == null or (m.optional and (recv_opt.?.isNull() or recv_opt.?.isUndefined()))) {
                // Parentheses terminate the inner chain. Its absent Reference is
                // the ordinary value undefined: an outer optional call skips its
                // arguments, while an ordinary call evaluates them and then
                // throws for calling undefined. Do not leak OptShortCircuit past
                // the wrapper or accidentally retain the pre-short-circuit base.
                if (optional) return error.OptShortCircuit;
                return self.callValueWithThis(Value.undef(), try self.evalArgs(arg_nodes), Value.undef());
            }
            const recv = recv_opt.?;
            const key = try self.memberKey(m.property, m.computed);
            if (optional) {
                const method = try self.getProperty(recv, key);
                if (method.isNull() or method.isUndefined()) return error.OptShortCircuit;
                return self.callValueWithThis(method, try self.evalArgs(arg_nodes), recv);
            }
            // Evaluate the MemberExpression's Get before its Arguments. Keep the
            // resolved value so an accessor/proxy is observed exactly once.
            const method = try self.getProperty(recv, key);
            const args = try self.evalArgs(arg_nodes);
            return self.callResolvedMethod(recv, key, method, args);
        }
        // Method call `obj.m(...)`: evaluate the receiver once so it can both
        // resolve the method and bind `this`. Array/string builtins (push,
        // pop, ...) that aren't own properties are dispatched here too.
        if (callee_node.* == .member) {
            const m = callee_node.member;
            const recv = try self.eval(m.object);
            if (m.optional and (recv.isNull() or recv.isUndefined())) return error.OptShortCircuit;
            // Evaluate a computed key's EXPRESSION now, but defer ToPropertyKey (its
            // toString/valueOf) until after RequireObjectCoercible — a nullish
            // receiver throws before the key's toString runs, matching the read path
            // and the deferred-ToPropertyKey spec (`null[{toString(){…}}]()`).
            const kv: ?Value = if (m.computed) |ce| try self.eval(ce) else null;
            // Evaluating the callee MemberExpression does RequireObjectCoercible on
            // the base, so a nullish receiver throws BEFORE the arguments are
            // evaluated — `o.bar.gar(foo())` must not run `foo()` when `o.bar` is
            // undefined.
            if (recv.isNull() or recv.isUndefined())
                return self.throwError("TypeError", notAnObjectMessage(recv));
            const key = if (kv) |k| try self.keyOf(k) else m.property;
            // `recv.m?.(...)`: short-circuit if the method itself is nullish.
            if (optional) {
                const method = try self.getProperty(recv, key);
                if (method.isNull() or method.isUndefined()) return error.OptShortCircuit;
                return self.callValueWithThis(method, try self.evalArgs(arg_nodes), recv);
            }
            // Evaluate the MemberExpression's Get before its Arguments (ECMA-262
            // EvaluateCall), then retain that exact reference through argument
            // expansion. Re-reading here would duplicate getters/proxy traps.
            const method = try self.getProperty(recv, key);
            const args = try self.evalArgs(arg_nodes);
            return self.callResolvedMethod(recv, key, method, args);
        }
        // `super.m(args)`: look the method up on the home object's prototype,
        // but invoke it with the current `this`.
        if (callee_node.* == .super_member) {
            const sm = callee_node.super_member;
            const home = self.home_object orelse return self.throwError("SyntaxError", "'super' outside a method");
            // GetThisBinding precedes the key/lookup (see the super read path): a
            // derived-ctor `super.m()` before `super()` is a ReferenceError.
            if (!self.this_initialized) return self.throwError("ReferenceError", "Must call super constructor before using 'this'");
            const key_val: ?Value = if (sm.computed) |ce| try self.eval(ce) else null;
            const parent = home.protoAtomic() orelse
                return self.throwError("TypeError", "no superclass method");
            const key = if (key_val) |kv| try self.keyOf(kv) else sm.property;
            const method = try self.getProperty(Value.obj(parent), key);
            const args = try self.evalArgs(arg_nodes);
            return self.callValueWithThis(method, args, self.this_value);
        }
        // A bare identifier carries its exact WithBaseObject out of the same
        // ResolveBinding/GetValue operation. Root both Values across argument
        // evaluation so a callback-triggered moving collection cannot stale the
        // selected callee or receiver.
        const resolved: CapturedBindingValue = if (callee_node.* == .identifier) resolved: {
            try self.beginNodeEvaluation(callee_node);
            break :resolved try self.resolveBindingValue(callee_node.identifier, false);
        } else .{ .value = try self.eval(callee_node) };
        const callee_root = try self.pushTempRoot(resolved.value);
        defer self.restoreTempRoots(callee_root);
        const with_base_root = try self.pushTempRoot(resolved.with_base);
        defer self.restoreTempRoots(with_base_root);
        const callee = self.tempRoot(callee_root, resolved.value);
        if (optional and (callee.isNull() or callee.isUndefined())) return error.OptShortCircuit;
        const args = try self.evalArgs(arg_nodes);
        const rooted_callee = self.tempRoot(callee_root, resolved.value);
        const rooted_with_base = self.tempRoot(with_base_root, resolved.with_base);
        const saved_direct_eval = self.direct_eval_call;
        // A direct eval requires the callee to be THIS realm's %eval% intrinsic.
        // A syntactic `eval(...)` whose binding resolves to another realm's eval
        // (or a reassigned `eval`) is an *indirect* eval — it runs as global code
        // in that eval's own realm, not in the caller's scope.
        const eval_named = !optional and callee_node.* == .identifier and std.mem.eql(u8, callee_node.identifier, "eval");
        self.direct_eval_call = eval_named and self.isDirectEvalCallee(rooted_callee);
        defer self.direct_eval_call = saved_direct_eval;
        return self.callValueWithThis(rooted_callee, args, rooted_with_base);
    }

    fn prepareTreeTailCall(self: *Interpreter, node: *Node) EvalError!?Value {
        if (node.* != .call) return null;
        const c = node.call;
        if (c.optional or c.callee.* != .identifier) return null;
        const eval_named = std.mem.eql(u8, c.callee.identifier, "eval");
        if (!eval_named) return null;
        // Tree-tail reuse does not currently carry an explicit receiver. Leave
        // any active `with` call to the ordinary path before running observable
        // HasBinding, so it resolves exactly once with the correct base.
        var environment: ?*Environment = self.env;
        while (environment) |current| : (environment = current.parent)
            if (current.with_object != null) return null;
        try self.beginNodeEvaluation(c.callee);
        const callee = (try self.resolveBindingValue(c.callee.identifier, false)).value;
        if (self.isDirectEvalCallee(callee)) return null;
        const args = try self.evalArgs(c.args);
        self.tree_tail_call = .{ .callee = callee, .args = args };
        return Value.undef();
    }

    /// `tag`a${x}b`` → `tag(strings, x)` where `strings` is the frozen cooked
    /// array carrying a frozen `raw` array. The tag's `this` is the member
    /// receiver for `obj.tag`...`` (e.g. `String.raw`...``), else undefined.
    /// GetTemplateObject: the frozen "strings" object for a tagged-template call
    /// site, cached by AST node so the tag receives the SAME object on every
    /// evaluation — and the SAME object whether the site runs on the tree-walker
    /// or the bytecode VM (both key `template_cache` on the node pointer).
    pub fn getTemplateObject(self: *Interpreter, site: *const Node) EvalError!*value.Object {
        if (self.template_cache.get(@ptrCast(site))) |cached| return cached.asObj();
        const t = site.tagged_template;
        const s = (try self.newArray()).asObj();
        for (t.cooked) |c| try s.appendElement(self.arena, if (c) |cv| try Value.strAlloc(self.arena, cv) else Value.undef());
        const raw_arr = (try self.newArray()).asObj();
        for (t.raw) |c| try raw_arr.appendElement(self.arena, try Value.strAlloc(self.arena, c));
        try freezeTemplateArray(self, raw_arr);
        try s.setOwn(self.arena, self.root_shape, "raw", Value.obj(raw_arr));
        try s.setAttr(self.arena, "raw", .{ .writable = false, .enumerable = false, .configurable = false });
        try freezeTemplateArray(self, s);
        try self.template_cache.put(self.arena, @ptrCast(site), Value.obj(s));
        return s;
    }

    fn evalTaggedTemplate(self: *Interpreter, site: *const Node, tag_node: *Node, expr_nodes: []*Node) EvalError!Value {
        // TaggedTemplate evaluates the tag Reference and GetValue before
        // GetTemplateObject or any substitution. Capture the receiver now so a
        // member/super tag cannot be re-resolved after observable expressions.
        var callee: Value = undefined;
        var receiver: ?Value = null;
        switch (tag_node.*) {
            .member => |m| {
                const recv = try self.eval(m.object);
                const key_value: ?Value = if (m.computed) |key| try self.eval(key) else null;
                if (recv.isNull() or recv.isUndefined()) {
                    if (m.optional) return error.OptShortCircuit;
                    return self.throwError("TypeError", notAnObjectMessage(recv));
                }
                const key = if (key_value) |key_primitive| try self.keyOf(key_primitive) else m.property;
                callee = try self.getProperty(recv, key);
                receiver = recv;
            },
            .super_member => |m| {
                const home = self.home_object orelse return self.throwError("SyntaxError", "'super' outside a method");
                if (!self.this_initialized)
                    return self.throwError("ReferenceError", "Must call super constructor before using 'this'");
                const key_value: ?Value = if (m.computed) |key| try self.eval(key) else null;
                const parent = home.protoAtomic() orelse
                    return self.throwError("TypeError", "Cannot read property of null (super)");
                const key = if (key_value) |key_primitive| try self.keyOf(key_primitive) else m.property;
                callee = try self.getPropertyWithReceiver(Value.obj(parent), key, self.this_value);
                receiver = self.this_value;
            },
            .identifier => |name| {
                try self.beginNodeEvaluation(tag_node);
                const resolved = try self.resolveBindingValue(name, false);
                callee = resolved.value;
                if (resolved.with_base.isObject()) receiver = resolved.with_base;
            },
            else => callee = try self.eval(tag_node),
        }

        const callee_root = try self.pushTempRoot(callee);
        defer self.restoreTempRoots(callee_root);
        const receiver_fallback = receiver orelse Value.undef();
        const receiver_root = try self.pushTempRoot(receiver_fallback);
        defer self.restoreTempRoots(receiver_root);
        const strings = try self.getTemplateObject(site);
        var args: std.ArrayListUnmanaged(Value) = .empty;
        try args.append(self.arena, Value.obj(strings));
        for (expr_nodes) |en| try args.append(self.arena, try self.eval(en));
        return if (receiver != null)
            self.callValueWithThis(
                self.tempRoot(callee_root, callee),
                args.items,
                self.tempRoot(receiver_root, receiver_fallback),
            )
        else
            self.callValue(self.tempRoot(callee_root, callee), args.items);
    }

    fn freezeTemplateArray(self: *Interpreter, obj: *value.Object) EvalError!void {
        var i: usize = 0;
        while (i < obj.elementsLen()) : (i += 1) {
            const key = try std.fmt.allocPrint(self.arena, "{d}", .{i});
            try obj.setAttr(self.arena, key, .{ .writable = false, .enumerable = true, .configurable = false });
        }
        try obj.setAttr(self.arena, "length", .{ .writable = false, .enumerable = false, .configurable = false });
        obj.setExtensible(false);
    }

    /// Invoke a callable value with `this = undefined`.
    pub fn callValue(self: *Interpreter, callee: Value, args: []const Value) EvalError!Value {
        return self.callValueWithThis(callee, args, Value.undef());
    }

    /// Invoke a callable value with an explicit `this`. Zig-native builtins run
    /// directly; JS functions push a call scope over their closure; builtin
    /// error constructors fabricate an error instance.
    pub fn callValueWithThis(self: *Interpreter, callee: Value, args: []const Value, this_val: Value) EvalError!Value {
        if (!callee.isObject()) return self.throwError("TypeError", "value is not a function");
        const obj = callee.asObj();
        if (obj.proxyHandler() != null or obj.proxy_revoked) {
            const target = obj.proxyTarget() orelse return self.throwError("TypeError", "Cannot perform 'apply' on a proxy that has been revoked");
            // A Proxy has a [[Call]] method only if its target is callable; if not,
            // calling it is a TypeError BEFORE the apply trap runs (9.5.12).
            if (!obj.behavior.proxy_callable) return self.throwError("TypeError", "value is not a function");
            if (try self.proxyTrap(obj, "apply")) |trap| {
                const arr = try self.newArray();
                for (args) |a| try arr.asObj().appendElement(self.arena, a);
                return self.callValueWithThis(trap, &.{ Value.obj(target), this_val, arr }, Value.obj(obj.proxyHandler().?));
            }
            return self.callValueWithThis(Value.obj(target), args, this_val);
        }
        if (obj.boundFunction()) |erased| {
            const bf: *BoundFn = @ptrCast(@alignCast(erased));
            return self.callValueWithThis(bf.target, try self.concatArgs(bf.args, args), bf.this);
        }
        if (obj.errorCtor()) |name| return self.makeErrorWithArgs(name, args);
        if (obj.hostClassHooks()) |hooks| if (hooks.call) |call| {
            if (hooks.is_callable == null or hooks.is_callable.?(obj)) {
                try self.stackGuard();
                self.depth += 1;
                defer self.depth -= 1;
                self.recordExecutionTier(.host_callbacks);
                return call(@ptrCast(self), obj, this_val, args);
            }
        };
        if (obj.native) |nf| {
            try self.stackGuard();
            self.depth += 1;
            defer self.depth -= 1;
            // Expose the callee object to the native (it isn't a parameter), so
            // closures-over-data like Promise resolve/reject can find their slot.
            const saved_native = self.active_native;
            self.active_native = obj;
            defer self.active_native = saved_native;
            if (obj.hostCallback() != null) self.recordExecutionTier(.host_callbacks);
            // A plain [[Call]] has new.target = undefined; without this reset a
            // native that guards construction (e.g. `Symbol`, `BigInt`) called from
            // inside a constructor would see the enclosing ctor's new.target and
            // wrongly reject the call as `new Symbol()`. A DIRECT eval is the sole
            // exception: it runs its code in the caller's context, so `new.target`
            // inside `eval(...)` inherits the caller's (an indirect eval still gets
            // undefined via the general reset).
            const saved_nt = self.new_target;
            if (!self.direct_eval_call) self.new_target = Value.undef();
            defer self.new_target = saved_nt;
            return nf(@ptrCast(self), this_val, args);
        }
        if (obj.jsFunction()) |erased| {
            const func: *Function = @ptrCast(@alignCast(erased));
            return self.callFunction(func, args, this_val);
        }
        return self.throwError("TypeError", "value is not a function");
    }

    /// A bound function: target + the `this`/leading args fixed by `fn.bind`.
    pub const BoundFn = struct { target: Value, this: Value, args: []const Value };

    /// `fn.bind(this, ...bound)`: a new callable that prepends `bound` to its args.
    /// CreateListFromArrayLike: the argument list for `Function.prototype.apply`
    /// (and Reflect.apply). `undefined`/`null` → empty; a non-object throws; an
    /// object is read by `length` (ToLength) and indices 0..length via [[Get]],
    /// so a real array-like (e.g. `arguments`) works, not only a dense array.
    fn argListFromArrayLike(self: *Interpreter, v: Value) EvalError![]const Value {
        if (v.isUndefined() or v.isNull()) return &.{};
        if (!builtins.isRealObject(v)) return self.throwError("TypeError", "CreateListFromArrayLike called on non-object");
        const o = v.asObj();
        const len = toLen((try self.toPrimitive(try self.getProperty(v, "length"), .number)).toNumber());
        if (len > (1 << 24)) return self.throwError("RangeError", "argument list too large");
        // Dense fast path for a plain array with no accessors.
        if (o.is_array) {
            if (try o.packedDenseElementsSnapshot(self.arena)) |items| {
                if (len <= items.len) return items[0..len];
            }
        }
        const buf = try self.arena.alloc(Value, len);
        for (buf, 0..) |*slot, i| slot.* = try self.getProperty(v, try std.fmt.allocPrint(self.arena, "{d}", .{i}));
        return buf;
    }

    fn createBound(self: *Interpreter, target: *value.Object, this: Value, bound_args: []const Value) EvalError!*value.Object {
        const bf = try gc_mod.allocBoundFn(self.arena);
        bf.* = .{ .target = Value.obj(target), .this = this, .args = try self.arena.dupe(Value, bound_args) };
        const obj = try gc_mod.allocObj(self.arena);
        const target_proto = if (target.proxyHandler() != null or target.proxy_revoked) blk: {
            const p = try self.proxyGetProto(target);
            break :blk if (p.isObject()) p.asObj() else null;
        } else self.effectiveProto(target);
        obj.* = .{ .proto = target_proto };
        try obj.setBoundFunction(self.arena, @ptrCast(bf));
        obj.setProtoExplicitNull(target_proto == null);
        return obj;
    }

    fn installBoundMetadata(self: *Interpreter, obj: *value.Object, bound_len: f64, bound_name: Value) EvalError!void {
        const ro_attr: value.PropAttr = .{ .writable = false, .enumerable = false, .configurable = true };
        try obj.setOwn(self.arena, self.root_shape, "length", Value.num(bound_len));
        try obj.setAttr(self.arena, "length", ro_attr);
        try obj.setOwn(self.arena, self.root_shape, "name", bound_name);
        try obj.setAttr(self.arena, "name", ro_attr);
    }

    fn makeBoundExact(self: *Interpreter, target: *value.Object, this: Value, bound_args: []const Value, bound_len: f64, bound_name: Value) EvalError!Value {
        const obj = try self.createBound(target, this, bound_args);
        try self.installBoundMetadata(obj, bound_len, bound_name);
        return Value.obj(obj);
    }

    fn makeBound(self: *Interpreter, target: *value.Object, this: Value, bound_args: []const Value) EvalError!Value {
        // BoundFunctionCreate precedes the observable target length/name reads
        // in Function.prototype.bind. Keep that ordering exact for proxies.
        const obj = try self.createBound(target, this, bound_args);
        // Per spec: a bound function's `length` is max(0, target.length - args)
        // and its `name` is "bound " + target.name. Both are
        // { writable: false, enumerable: false, configurable: true }.
        const bound_len: f64 = if (try self.objectProtoHasOwn(target, "length")) blk: {
            const tgt_len_v = try self.getProperty(Value.obj(target), "length");
            if (!tgt_len_v.isNumber()) break :blk 0;
            const len_int = if (std.math.isNan(tgt_len_v.asNum())) @as(f64, 0) else @trunc(tgt_len_v.asNum());
            const bound_count: f64 = @floatFromInt(bound_args.len);
            break :blk if (len_int <= bound_count) 0 else len_int - bound_count;
        } else 0;
        const ro_attr: value.PropAttr = .{ .writable = false, .enumerable = false, .configurable = true };
        // SetFunctionLength precedes Get(target, "name"). Besides the proxy
        // access order, preserve the failure boundary: an OOM while publishing
        // length must not run a user-defined name getter.
        try obj.setOwn(self.arena, self.root_shape, "length", Value.num(bound_len));
        try obj.setAttr(self.arena, "length", ro_attr);
        const tgt_name = try self.getProperty(Value.obj(target), "name");
        // SetFunctionName prefixes the target's String value, not the backing
        // bytes used by a particular StringCell representation.
        const base_name = if (tgt_name.isString()) try tgt_name.asWtf8(self.arena) else "";
        var scratch = std.heap.ArenaAllocator.init(self.scratch_allocator orelse gc_mod.temporaryAllocator(self.arena));
        defer scratch.deinit();
        const bound_name = try std.fmt.allocPrint(scratch.allocator(), "bound {s}", .{base_name});
        try obj.setOwn(self.arena, self.root_shape, "name", try Value.strAlloc(self.arena, bound_name));
        try obj.setAttr(self.arena, "name", ro_attr);
        return Value.obj(obj);
    }

    /// Concatenate bound args with call args (for invoking a bound function).
    fn concatArgs(self: *Interpreter, a: []const Value, b: []const Value) EvalError![]const Value {
        if (a.len == 0) return b;
        if (b.len == 0) return a;
        const out = try self.arena.alloc(Value, a.len + b.len);
        @memcpy(out[0..a.len], a);
        @memcpy(out[a.len..], b);
        return out;
    }

    pub fn makeErrorWithArgs(self: *Interpreter, name: []const u8, args: []const Value) EvalError!Value {
        return self.makeErrorWithArgsNT(name, args, Value.undef());
    }

    fn makeErrorWithArgsNT(self: *Interpreter, name: []const u8, args: []const Value, new_target: Value) EvalError!Value {
        // AggregateError(errors, message, options) shifts message/options by one
        // and carries an own `errors` array built from the first (iterable) arg.
        const aggregate = std.mem.eql(u8, name, "AggregateError");
        const suppressed = std.mem.eql(u8, name, "SuppressedError");
        const msg_i: usize = if (aggregate) 1 else if (suppressed) 2 else 0;
        const opt_i: usize = if (aggregate) 2 else if (suppressed) 3 else 1;

        const ctor_realm_array_proto = if (aggregate and new_target.isObject())
            try self.functionRealmIntrinsicProto(new_target.asObj(), "Array")
        else
            null;
        const proto = if (new_target.isObject()) try self.ctorRealmIntrinsicProto(new_target.asObj(), name) else null;

        // The message is ToString'd (via ToPrimitive(string), so an object's
        // toString/valueOf runs); a Symbol message throws a TypeError.
        const has_msg = args.len > msg_i and !args[msg_i].isUndefined();
        const msg = if (has_msg) blk: {
            const prim = try self.toPrimitive(args[msg_i], .string);
            if (prim.isObject() and prim.asObj().is_symbol)
                return self.throwError("TypeError", "Cannot convert a Symbol value to a string");
            break :blk if (prim.isString()) try prim.asWtf8(self.arena) else try prim.toString(self.arena);
        } else "";
        const err = try self.makeErrorWithProto(name, msg, proto);
        if (has_msg and msg.len == 0) {
            try self.setProp(err.asObj(), "message", Value.str(""));
            try err.asObj().setAttr(self.arena, "message", .{ .enumerable = false, .configurable = true, .writable = true });
        }

        if (aggregate) {
            // `errors` is a fresh Array built from the (iterable) first argument.
            const errs = try self.iterableToArray(if (args.len > 0) args[0] else Value.undef(), ctor_realm_array_proto);
            try self.setProp(err.asObj(), "errors", errs);
            try err.asObj().setAttr(self.arena, "errors", .{ .enumerable = false, .configurable = true, .writable = true });
        }

        if (suppressed) {
            // SuppressedError(error, suppressed, message): the first two arguments
            // become non-enumerable own `error` / `suppressed` properties.
            try self.setProp(err.asObj(), "error", if (args.len > 0) args[0] else Value.undef());
            try err.asObj().setAttr(self.arena, "error", .{ .enumerable = false, .configurable = true, .writable = true });
            try self.setProp(err.asObj(), "suppressed", if (args.len > 1) args[1] else Value.undef());
            try err.asObj().setAttr(self.arena, "suppressed", .{ .enumerable = false, .configurable = true, .writable = true });
        }

        // ES2022 `cause` option: `new Error(msg, { cause })` installs a
        // non-enumerable `cause` own property when the options object HAS one —
        // a real HasProperty (walks the prototype chain and fires a Proxy `has`
        // trap), then [[Get]] reads the value.
        if (args.len > opt_i and args[opt_i].isObject()) {
            if (try self.inOperator(Value.str("cause"), args[opt_i])) {
                const cause = try self.getProperty(args[opt_i], "cause");
                try self.setProp(err.asObj(), "cause", cause);
                try err.asObj().setAttr(self.arena, "cause", .{ .enumerable = false, .configurable = true, .writable = true });
            }
        }
        return err;
    }

    fn iterableToArray(self: *Interpreter, v: Value, proto: ?*value.Object) EvalError!Value {
        const arr = try self.newArrayWithProto(proto);
        const record = try self.getIteratorRecord(v);
        const iter_root = try self.pushTempRoot(record.iterator);
        defer self.restoreTempRoots(iter_root);
        const next_root = try self.pushTempRoot(record.next_method);
        defer self.restoreTempRoots(next_root);
        while (true) {
            const result = try self.callValueWithThis(record.next_method, &.{}, record.iterator);
            if (!builtins.isRealObject(result)) return self.throwError("TypeError", "iterator result is not an object");
            if ((try self.getProperty(result, "done")).toBoolean()) break;
            try arr.asObj().appendElement(self.arena, try self.getProperty(result, "value"));
        }
        return arr;
    }

    fn callFunction(self: *Interpreter, func: *Function, args: []const Value, this_val: Value) EvalError!Value {
        return self.callFunctionNT(func, args, this_val, Value.undef());
    }

    /// `callFunction` with an explicit `new.target` (set by `construct`; a plain
    /// call passes undefined). Arrow functions inherit the enclosing new.target.
    fn callFunctionNT(self: *Interpreter, func: *Function, args: []const Value, this_val: Value, new_target: Value) EvalError!Value {
        const saved_bytecode_execution_mode = self.bytecode_execution_mode;
        self.bytecode_execution_mode = func.bytecode_execution_mode;
        defer self.bytecode_execution_mode = saved_bytecode_execution_mode;
        // Under `parallel_js` the concurrent parallel marker does NOT conservatively
        // scan a running peer's native stack, so `func` — reachable only through this
        // thread's stack while the call is in flight — can be swept mid-call and its
        // GC cell reused by a peer's `makeFunction`, a use-after-free that surfaces
        // as a torn read of `func.is_class_constructor` back in `callPlain`. Publish
        // the callee's wrapping object (which marks the `Function` through
        // `Object.jsFunction()`) as a precise root for the call's duration.
        // `lock_microtasks` is true iff `parallel_js` (which the parallel marker requires), so the
        // single-threaded hot path pays nothing.
        const callee_rooted = self.lock_microtasks and func.obj != null;
        const callee_root_mark = if (callee_rooted) mark: {
            const m = try self.pushTempRoot(Value.obj(func.obj.?));
            // Shade the callee now: a concurrent mark may begin before this root is
            // republished at the next safepoint, and the marker would otherwise miss
            // it (idempotent, a no-op when no mark is active).
            gc_mod.barrierValue(Value.obj(func.obj.?));
            break :mark m;
        } else 0;
        defer if (callee_rooted) self.restoreTempRoots(callee_root_mark);
        // An async (non-generator) function runs its body synchronously and wraps
        // the completion in a Promise: a normal return resolves it, a throw
        // rejects it. `await` inside drives the microtask queue inline until the
        // awaited promise settles (the synchronous-settling model). Async
        // generators still need the suspendable VM, so they fall through.
        if (func.is_async and !func.is_generator) {
            // A body the VM could lower runs as a suspendable activation driven
            // by promise settlement (spec-correct await ordering). Otherwise fall
            // back to the synchronous-settling tree-walk model below.
            if (func.async_chunk) |_| return vm.runAsync(self, func, args, this_val);
            if (func.bytecode_execution_mode == .required)
                return self.throwMissingRequiredChunk(func, "async");
            const result = try promise.newPromise(self);
            const rp: *promise.Promise = @ptrCast(@alignCast(result.promiseData().?));
            if (self.callPlain(func, args, this_val, new_target)) |rv| {
                try promise.resolve(self, rp, rv);
            } else |err| {
                if (err == error.Throw) {
                    const reason = self.exception;
                    self.exception = Value.undef();
                    try promise.reject(self, rp, reason);
                } else return err;
            }
            return Value.obj(result);
        }
        // A VM-lowered plain function MUST run on the VM regardless of how it was
        // *entered*: its body resolves captured variables as frame upvalues
        // (`load_upval`), which only the VM's activation frames provide — the
        // tree-walker's `callPlain` resolves names through the lexical
        // `Environment` chain, where a frame-local upvalue does not exist. When
        // such a closure is invoked from a tree-walker/native entry (e.g. a spawned
        // `Thread`'s `callValueWithThis`, a TypedArray `@@species` constructor, or
        // any host call that lands here while the top-level ran on the VM),
        // tree-walking the body raises a spurious `ReferenceError`. `vm.callValue`
        // and the VM's construct opcode already dispatch chunk functions to the
        // VM; mirror that here so interpreter/native calls and constructor entries
        // thread the same activation frame and explicit `new.target`.
        if (new_target.isUndefined() and func.is_class_constructor)
            return throwClassConstructorCallError(self, func);
        if (!func.is_generator and !func.is_async) {
            if (func.chunk) |fchunk| return vm.runFunction(self, func, fchunk, args, this_val, new_target);
            if (func.bytecode_execution_mode == .required)
                return self.throwMissingRequiredChunk(func, "plain");
        }
        var cur_func = func;
        var cur_args = args;
        var cur_this = this_val;
        var cur_new_target = new_target;
        while (true) {
            const rv = try self.callPlain(cur_func, cur_args, cur_this, cur_new_target);
            const tail = self.tree_tail_call orelse return rv;
            self.tree_tail_call = null;
            if (!tail.callee.isObject()) return self.callValue(tail.callee, tail.args);
            const obj = tail.callee.asObj();
            const erased = obj.jsFunction() orelse return self.callValue(tail.callee, tail.args);
            const next_func: *Function = @ptrCast(@alignCast(erased));
            if (next_func.is_generator or next_func.is_async or next_func.is_class_constructor)
                return self.callValue(tail.callee, tail.args);
            if (next_func.chunk) |fchunk| return vm.runFunction(self, next_func, fchunk, tail.args, Value.undef(), Value.undef());
            if (next_func.bytecode_execution_mode == .required)
                return self.throwMissingRequiredChunk(next_func, "plain");
            cur_func = next_func;
            cur_args = tail.args;
            cur_this = Value.undef();
            cur_new_target = Value.undef();
        }
    }

    /// The body of a plain (sync) function call: scope setup, param binding, and
    /// evaluation. Async functions route through `callFunctionNT`, which wraps
    /// this in a Promise.
    fn callPlain(self: *Interpreter, func: *Function, args: []const Value, this_val: Value, new_target: Value) EvalError!Value {
        // Calling a `function*` builds a generator object (its body runs lazily,
        // on the suspendable VM, via `.next()`). Async generators can't yet run
        // their body (need yield+await suspension), but per spec their parameters
        // still bind eagerly on the call — so a computed-key/default side effect
        // (e.g. `async function*({ [thrower()]: x }) {}`) must propagate before we
        // give up. We fall through to the normal scope-setup + bindParams path and
        // return an inert async-generator stub once binding succeeds.
        if (func.is_generator and !func.is_async) return vm.makeGenerator(self, func, args, this_val);
        // An async generator whose body the VM lowered runs as a real async
        // generator; an unlowerable body falls through to the inert stub below.
        if (func.is_generator and func.is_async and func.gen_chunk != null)
            return vm.makeAsyncGenerator(self, func, args, this_val);
        self.recordExecutionTier(.tree_walker_entries);
        try self.stackGuard();
        self.depth += 1;
        defer self.depth -= 1;

        const call_env = try self.acquireCallEnvironment(func);
        // On normal completion the activation is fully instantiated and safe to
        // clear. Any error can interrupt a binding insertion, so preserve that
        // cell for the GC finalizer rather than caching a potentially partial
        // table; caught JavaScript throws complete normally at this boundary.
        var call_failed = false;
        defer if (!call_failed) self.releaseCallEnvironment(call_env, func);
        errdefer call_failed = true;

        const saved_env = self.env;
        const saved_signal = self.signal;
        const saved_ret = self.ret_value;
        const saved_this = self.this_value;
        const saved_home = self.home_object;
        const saved_super = self.super_ctor;
        const saved_nt = self.new_target;
        const saved_strict = self.strict;
        const saved_global = self.global_object;
        const saved_import_meta_slot = self.import_meta_slot;
        const saved_import_meta_obj = self.import_meta_obj;
        const saved_cur_module = self.cur_module;
        const saved_this_initialized = self.this_initialized;
        const saved_this_cell = self.this_cell;
        const saved_active_function = self.active_function;
        const saved_eval_nt = self.direct_eval_new_target_allowed;
        const saved_fi = self.in_field_initializer;
        const saved_pe = self.in_param_expr;
        const saved_pd = self.in_param_default;
        self.in_param_default = false; // a function body is not a parameter default
        const saved_params = self.cur_func_params;
        const saved_args_needed = self.cur_func_args_needed;
        self.cur_func_params = func.params;
        self.cur_func_args_needed = func.uses_arguments or func.uses_direct_eval;
        const saved_edd = self.eval_decl_deletable;
        self.eval_decl_deletable = false; // a function's own vars aren't eval-deletable, even if called from eval
        const saved_idc = self.in_derived_ctor;
        const saved_dfc = self.in_default_ctor;
        const saved_pm = self.current_private_map;
        const saved_call_frame = self.active_call_frame;
        const saved_debug_call_frame = self.debug_call_frame;
        const saved_stack_trace_call_frame = self.stack_trace_call_frame;
        const saved_tree_tail_allowed = self.tree_tail_allowed;
        var call_frame: LegacyCallFrame = undefined;
        var debug_call_frame = DebugCallFrame{
            .function_name = func.name,
            .environment = call_env,
            .this_value = this_val,
            .strict = func.is_strict,
            .caller = saved_debug_call_frame,
        };
        var stack_trace_call_frame = StackTraceCallFrame{
            .function_name = func.name,
            .function_identity = @intFromPtr(func),
            .definition_location = func.definition_location,
            .code_type = if (!new_target.isUndefined() or func.is_class_constructor) .constructor else .function,
            .is_async = func.is_async,
            .caller = saved_stack_trace_call_frame,
        };
        self.stack_trace_call_frame = &stack_trace_call_frame;
        if (self.debug_statement_hook != null or self.host_statement_hook != null) self.debug_call_frame = &debug_call_frame;
        if (!func.is_arrow) self.current_private_map = func.private_map; // arrows inherit the enclosing class's map
        if (!func.is_arrow) {
            self.active_function = func.obj;
            if (func.obj) |fo| {
                call_frame = .{ .func_obj = fo, .caller = saved_call_frame };
                self.active_call_frame = &call_frame;
            }
        }
        const saved_pfi = self.pending_field_inits;
        const saved_pbn = self.pending_brand_names;
        // A derived constructor's field initializers + private brands wait for its
        // SuperCall.
        self.pending_field_inits = func.field_inits;
        self.pending_brand_names = if (func.is_derived_constructor or (func.is_arrow and func.arrow_in_derived_ctor))
            func.private_brand_names
        else
            &.{};
        self.env = call_env;
        if (self.reusable_call_env == call_env) {
            self.reusable_call_env = null;
            self.reusable_call_body = null;
        }
        self.signal = .none;
        self.strict = func.is_strict;
        self.tree_tail_allowed = func.is_strict and new_target.isUndefined() and
            std.mem.indexOf(u8, func.source, "eval") != null;
        self.tree_tail_call = null;
        self.import_meta_slot = func.import_meta_slot;
        self.import_meta_obj = if (func.import_meta_slot) |slot| slot.load() else null;
        self.cur_module = func.module_referrer;
        if (func.realm_global) |global| {
            self.global_object = global;
        } else if (self.env.get("globalThis")) |gt| {
            if (gt.isObject()) self.global_object = gt.asObj();
        }
        // Sloppy-mode this-substitution: null/undefined become the callee
        // realm's global object; primitive receivers are boxed in the callee
        // realm. Strict functions keep the original value, and arrows inherit
        // `this` lexically.
        self.this_value = if (func.is_arrow)
            // Arrows ignore the provided `this` and use the lexically captured one.
            func.arrow_this
        else if (!func.is_strict) blk: {
            if (this_val.isNull() or this_val.isUndefined()) {
                if (func.realm_global) |global| break :blk Value.obj(global);
                if (self.env.get("globalThis")) |gt| if (gt.isObject()) break :blk gt;
                break :blk if (self.global_object) |g| Value.obj(g) else this_val;
            }
            if (!this_val.isObject() or this_val.asObj().is_symbol or this_val.asObj().is_bigint)
                break :blk Value.obj(try self.toObject(this_val));
            break :blk this_val;
        } else this_val;
        self.home_object = func.home_object;
        // GetSuperConstructor reads the running constructor's CURRENT [[Prototype]]
        // dynamically (e.g. after `Object.setPrototypeOf(C, …)`), not a value frozen
        // at class definition. For a class constructor that's `func.obj`'s live
        // proto (normally == the captured heritage); arrows keep their lexically
        // captured super constructor.
        self.super_ctor = if (!func.is_arrow and func.is_class_constructor)
            (if (func.obj) |fo| fo.protoAtomic() else func.super_ctor)
        else
            func.super_ctor;
        self.new_target = if (func.is_arrow) func.arrow_new_target else new_target; // arrows capture lexically at creation
        self.direct_eval_new_target_allowed = if (func.is_arrow) func.arrow_direct_eval_new_target_allowed else true;
        // A non-arrow function call is a fresh context that is not a field
        // initializer; an arrow carries the field-initializer context LEXICALLY from
        // where it was defined (so `field = () => eval('arguments')` keeps the
        // restriction even when invoked later, after the field has been built).
        self.in_field_initializer = func.is_arrow and func.field_init_ctx;
        // Arrows inherit the enclosing super()-call legality; a non-arrow function
        // establishes it (only a derived constructor permits `super()`).
        // `super()`-legality is lexical: an arrow uses the value captured where it
        // was defined (so it stays legal even when invoked from a non-constructor
        // context, e.g. an iterator's `return()`); a non-arrow establishes it.
        self.in_derived_ctor = if (func.is_arrow) func.arrow_in_derived_ctor else func.is_derived_constructor;
        if (!func.is_arrow) self.in_default_ctor = func.is_default_ctor;
        // An arrow has no own `this` binding: it inherits the enclosing function's
        // this-initialization state (a non-arrow establishes it — only a derived
        // constructor starts uninitialized).
        if (!func.is_arrow) self.this_initialized = !func.is_derived_constructor;
        // The `this` binding is a shared cell so an arrow's `super()` reaches the
        // enclosing derived ctor's binding across intervening calls. A derived ctor
        // opens a fresh cell; an arrow adopts its captured one (the enclosing ctor's)
        // and reads the live binding through it; every other call clears it.
        if (func.is_arrow) {
            self.this_cell = func.this_cell;
            if (func.this_cell) |c| {
                self.this_value = c.value();
                self.this_initialized = c.isInitialized();
            }
        } else if (func.is_derived_constructor) {
            const cell = try self.arena.create(ThisCell);
            cell.* = ThisCell.init(self.this_value, false);
            self.this_cell = cell;
        } else {
            self.this_cell = null;
        }
        defer {
            self.env = saved_env;
            self.signal = saved_signal;
            self.ret_value = saved_ret;
            self.home_object = saved_home;
            self.super_ctor = saved_super;
            self.new_target = saved_nt;
            self.strict = saved_strict;
            self.global_object = saved_global;
            self.import_meta_slot = saved_import_meta_slot;
            self.import_meta_obj = saved_import_meta_obj;
            self.cur_module = saved_cur_module;
            self.this_value = saved_this;
            self.this_initialized = saved_this_initialized;
            self.this_cell = saved_this_cell;
            self.active_function = saved_active_function;
            self.active_call_frame = saved_call_frame;
            self.debug_call_frame = saved_debug_call_frame;
            self.stack_trace_call_frame = saved_stack_trace_call_frame;
            self.tree_tail_allowed = saved_tree_tail_allowed;
            // Re-sync the ambient this-state from the (restored) enclosing derived
            // ctor's shared cell: a `super()` that ran during this call — possibly
            // via an arrow invoked from an unrelated context — initialized the
            // cell, and that binding must remain visible to the enclosing ctor.
            if (self.this_cell) |c| if (c.isInitialized()) {
                self.this_value = c.value();
                self.this_initialized = true;
            };
            self.direct_eval_new_target_allowed = saved_eval_nt;
            self.in_field_initializer = saved_fi;
            self.in_param_expr = saved_pe;
            self.in_param_default = saved_pd;
            self.cur_func_params = saved_params;
            self.cur_func_args_needed = saved_args_needed;
            self.eval_decl_deletable = saved_edd;
            self.in_derived_ctor = saved_idc;
            self.in_default_ctor = saved_dfc;
            self.current_private_map = saved_pm;
            self.pending_field_inits = saved_pfi;
            self.pending_brand_names = saved_pbn;
        }
        if (func.is_class_constructor and new_target.isUndefined())
            return throwClassConstructorCallError(self, func);

        // Non-arrow functions get an `arguments` array-like over the call args —
        // but only if the body could reference it. An explicit reference or a
        // direct eval can observe the binding; otherwise skip building the
        // exotic object (and its element copy + parameter map) entirely. The
        // later `body_env.vars.contains("arguments")` copy degrades gracefully
        // when the binding is absent.
        if (!func.is_arrow and (func.uses_arguments or func.uses_direct_eval)) {
            // The body references `arguments`: build eagerly and bind it.
            const args_obj = try self.createArgumentsObject(func, args, call_env);
            if (self.active_call_frame) |fr| {
                if (func.obj != null and fr.func_obj == func.obj.?) fr.arguments = args_obj;
            }
            try call_env.put("arguments", args_obj);
        } else if (!func.is_arrow and legacyCallerArgumentsAllowed(func)) {
            // Non-strict function that does NOT name `arguments`: the exotic object
            // is observable ONLY through the legacy `fn.arguments` property, which
            // is rarely read. Defer the alloc + element copy + parameter map to
            // that read (see `.arguments` getter) so the common non-strict call —
            // e.g. a hot sort comparator — pays nothing per call.
            if (self.active_call_frame) |fr| {
                if (func.obj != null and fr.func_obj == func.obj.?) {
                    fr.lazy_func = func;
                    fr.lazy_args = args;
                    fr.lazy_env = call_env;
                }
            }
        }
        // A base class initializes its instance elements before parameter
        // default evaluation. A derived class waits until `super()` returns.
        if (func.is_class_constructor and !func.is_derived_constructor and self.this_value.isObject()) {
            for (func.private_brand_names) |bn| try self.addPrivateMethodOrAccessorChecked(self.this_value.asObj(), func.home_object, bn);
            for (func.field_inits) |fi| _ = try self.eval(fi);
        }

        // Bind parameters in `call_env` (so a default can reference earlier
        // params). A non-arrow parameter scope owns `arguments`, so a direct eval
        // in a default expression may not redeclare it (checked in evalFn).
        try self.bindParams2(func.params, args, func.is_arrow);

        // Async generator: params have now bound (propagating any side-effect
        // throws). We can't run the body yet, so hand back an inert object
        // standing in for the async-generator instance — the sync `*-err` dstr
        // tests only check the binding throw; the body-running tests are
        // async-flagged and skipped.
        if (func.is_async and func.is_generator) return self.newObject();

        if (func.is_expr_body) return self.eval(func.body);
        // FunctionDeclarationInstantiation: when the formals contain a parameter
        // expression (a default Initializer), the body runs in a SEPARATE variable
        // environment, so a closure created in the parameter list cannot see the
        // body's `var`/function declarations (and vice-versa). A body `var` that
        // names a parameter inherits the parameter's bound value.
        var has_param_expr = false;
        for (func.params) |p| if (p.default != null) {
            has_param_expr = true;
            break;
        };
        if (func.body.* == .block) {
            if (has_param_expr) {
                const body_env = try gc_mod.allocEnv(self.arena);
                self.initEnvironment(body_env, call_env, true);
                self.env = body_env;
                try self.hoistVarNames(func.body.block);
                if (body_env.vars.contains("arguments")) {
                    if (call_env.get("arguments")) |av| try body_env.put("arguments", av);
                }
                for (func.params) |p| {
                    if (p.pattern == null and !p.is_rest and body_env.vars.contains(p.name)) {
                        if (call_env.get(p.name)) |pv| try body_env.put(p.name, pv);
                    }
                }
            } else {
                // Hoist the body's `var`s into the (shared) function scope.
                try self.hoistVarNames(func.body.block);
            }
        }
        // Tag the body block as the function-body scope for Annex B B.3.3.
        // This activation's parameter names have been installed since before
        // BindingInitialization so parameter-phase eval sees the same identity.
        const saved_skip_annex_b_scan = self.skip_next_annex_b_scan;
        defer self.skip_next_annex_b_scan = saved_skip_annex_b_scan;
        self.skip_next_annex_b_scan = !func.annex_b_possible;
        self.mark_fn_body = true;
        _ = try self.eval(func.body);
        self.mark_fn_body = false;
        if (func.is_class_constructor and func.is_derived_constructor) {
            if (self.signal == .ret) {
                if (self.ret_value.isObject() and !self.ret_value.asObj().is_symbol and !self.ret_value.asObj().is_bigint) return self.ret_value;
                if (!self.ret_value.isUndefined()) {
                    self.env = saved_env;
                    self.global_object = saved_global;
                    return self.throwError("TypeError", "Derived constructors may only return object or undefined");
                }
            }
            // GetThisBinding reads the shared cell: `super()` may have run during
            // an intervening call (e.g. an iterator `return()` handler invoking a
            // `() => super()` arrow as the abrupt `return` was processed), so the
            // cell — not the ambient flag — is authoritative.
            const inited = if (self.this_cell) |c| c.isInitialized() else self.this_initialized;
            if (!inited) {
                self.env = saved_env;
                self.global_object = saved_global;
                return self.throwError("ReferenceError", "Must call super constructor before using 'this'");
            }
            // The bound `this` (the object `super()` produced) is what `new`
            // yields — not the discarded eager placeholder.
            return if (self.this_cell) |c| c.value() else self.this_value;
        }
        return if (self.signal == .ret) self.ret_value else Value.undef();
    }

    /// Bind a function's parameters to `args` in the current environment
    /// (`self.env`): a rest param (`...r`) collects the remaining args into an
    /// array; an absent/undefined arg falls back to the param's default; a
    /// destructuring pattern is bound via `bindPattern`. Shared by ordinary
    /// calls and generators (which bind into the generator's own environment).
    pub fn bindParams(self: *Interpreter, params: []const ast.Param, args: []const Value) EvalError!void {
        return self.bindParams2(params, args, false);
    }

    /// Whether any parameter binds the name `arguments` (a simple param, a rest
    /// param, or a name inside a destructuring pattern).
    fn paramsBindArguments(params: []const ast.Param) bool {
        for (params) |p| {
            if (p.pattern) |pat| {
                if (patternBindsName(pat, "arguments")) return true;
            } else if (std.mem.eql(u8, p.name, "arguments")) return true;
        }
        return false;
    }

    fn paramsBindName(params: []const ast.Param, name: []const u8) bool {
        for (params) |parameter| {
            if (parameter.pattern) |pattern| {
                if (patternBindsName(pattern, name)) return true;
            } else if (std.mem.eql(u8, parameter.name, name)) return true;
        }
        return false;
    }

    fn patternBindsName(node: *Node, name: []const u8) bool {
        switch (node.*) {
            .identifier => |n| return std.mem.eql(u8, n, name),
            .obj_pattern => |p| {
                for (p.props) |prop| if (patternBindsName(prop.target, name)) return true;
                if (p.rest) |r| if (r.* == .identifier and std.mem.eql(u8, r.identifier, name)) return true;
            },
            .arr_pattern => |p| {
                for (p.elems) |elem| if (elem.target) |t| {
                    if (patternBindsName(t, name)) return true;
                };
                if (p.rest) |r| if (patternBindsName(r, name)) return true;
            },
            else => {},
        }
        return false;
    }

    const ArgumentsMapTarget = union(enum) {
        environment: *Environment,
        frame: struct {
            slot_values: []const Value,
            mapped_parameter_indices: []const u32,
        },
    };

    pub fn createArgumentsObject(self: *Interpreter, func: *Function, args: []const Value, call_env: *Environment) EvalError!Value {
        return self.createArgumentsObjectWithMap(func, args, .{ .environment = call_env });
    }

    /// Create the sloppy simple-parameter arguments object used by a VM frame.
    /// Its mapped parameter cells belong to the object rather than pointing at
    /// recyclable activation storage; dedicated mapped-local bytecodes share
    /// those cells while the frame is live or captured.
    pub fn createFrameArgumentsObject(
        self: *Interpreter,
        func: *Function,
        args: []const Value,
        slot_values: []const Value,
        mapped_parameter_indices: []const u32,
    ) EvalError!Value {
        return self.createArgumentsObjectWithMap(func, args, .{ .frame = .{
            .slot_values = slot_values,
            .mapped_parameter_indices = mapped_parameter_indices,
        } });
    }

    fn createArgumentsObjectWithMap(self: *Interpreter, func: *Function, args: []const Value, map_target: ArgumentsMapTarget) EvalError!Value {
        const args_obj = try self.newArray();
        args_obj.asObj().is_arguments = true;
        // The arguments exotic object's [[Prototype]] is %Object.prototype%
        // (not Array.prototype): it has no inherited array methods, and
        // `arguments.toString()` is Object.prototype.toString -> "[object
        // Arguments]". Index storage and for-of still use the `is_array` path.
        if (self.objectProto()) |op| args_obj.asObj().proto = op;
        // It does have an own @@iterator = %Array.prototype.values% (so
        // `arguments[Symbol.iterator]()` yields an Array Iterator).
        if (self.arrayProtoObj()) |ap| if (self.symbolIteratorKey()) |ik| {
            if (ap.getOwn(ik)) |it| {
                try args_obj.asObj().setOwn(self.arena, self.root_shape, ik, it);
                try args_obj.asObj().setAttr(self.arena, ik, .{ .writable = true, .enumerable = false, .configurable = true });
            }
        };
        try args_obj.asObj().setOwn(self.arena, self.root_shape, "length", Value.num(@floatFromInt(args.len)));
        try args_obj.asObj().setAttr(self.arena, "length", .{ .writable = true, .enumerable = false, .configurable = true });
        for (args) |av| try args_obj.asObj().appendElement(self.arena, av);

        // Strict mode's `arguments.callee` is a poison-pill accessor whose get
        // and set are both `%ThrowTypeError%`. Non-simple sloppy formals also
        // use an unmapped arguments object with the poison pill.
        var non_simple_params = false;
        for (func.params) |p| {
            if (p.default != null or p.is_rest or p.pattern != null) {
                non_simple_params = true;
                break;
            }
        }
        if (func.is_strict or non_simple_params) {
            if (self.throwTypeError()) |tte| {
                try args_obj.asObj().setAccessor(self.arena, "callee", Value.obj(tte), Value.obj(tte));
                try args_obj.asObj().setAttr(self.arena, "callee", .{ .enumerable = false, .configurable = false });
            }
        } else if (func.obj) |fo| {
            // A mapped (sloppy, simple-parameter) arguments object's `callee` is
            // an own data property = the callee function itself.
            try args_obj.asObj().setOwn(self.arena, self.root_shape, "callee", Value.obj(fo));
            try args_obj.asObj().setAttr(self.arena, "callee", .{ .writable = true, .enumerable = false, .configurable = true });
        }

        // Mapped arguments [[ParameterMap]]: in sloppy mode with simple
        // parameters, each in-range index aliases its parameter binding.
        if (!func.is_strict and !non_simple_params and func.params.len > 0) {
            const n = @min(args.len, func.params.len);
            const cold = try args_obj.asObj().ensureCold(self.arena);
            switch (map_target) {
                .environment => |call_env| {
                    const names_allocator = try args_obj.asObj().argMapNamesAllocator(self.arena);
                    const names = try names_allocator.alloc([]const u8, n);
                    errdefer names_allocator.free(names);
                    const severed_allocator = try args_obj.asObj().argMapSeveredAllocator(self.arena);
                    const severed = try severed_allocator.alloc(std.atomic.Value(bool), n);
                    errdefer severed_allocator.free(severed);
                    for (names, 0..) |*nm, i| nm.* = func.params[i].name;
                    for (severed) |*flag| flag.* = .init(false);
                    // A duplicated parameter name maps only its last index.
                    for (names, 0..) |nm, i| {
                        var j = i + 1;
                        while (j < n) : (j += 1) if (std.mem.eql(u8, nm, names[j])) {
                            names[i] = "";
                            break;
                        };
                    }
                    // A mapped arguments object may outlive the call and
                    // continues to alias Environment-backed parameters.
                    call_env.markCaptured();
                    cold.arg_map_env = @ptrCast(call_env);
                    cold.arg_map_names = names;
                    cold.arg_map_severed = severed;
                },
                .frame => |frame| {
                    if (frame.mapped_parameter_indices.len > frame.slot_values.len)
                        return self.throwError("InternalError", "invalid mapped arguments frame layout");
                    const values_allocator = try args_obj.asObj().argMapValuesAllocator(self.arena);
                    const values = try values_allocator.alloc(std.atomic.Value(u64), n);
                    errdefer values_allocator.free(values);
                    const severed_allocator = try args_obj.asObj().argMapSeveredAllocator(self.arena);
                    const severed = try severed_allocator.alloc(std.atomic.Value(bool), n);
                    errdefer severed_allocator.free(severed);
                    for (values) |*cell| cell.* = .init(Value.undef().bits);
                    for (severed) |*flag| flag.* = .init(true);
                    for (frame.mapped_parameter_indices, 0..) |argument_index, slot| {
                        if (argument_index >= n) continue;
                        values[argument_index].store(frame.slot_values[slot].bits, .monotonic);
                        severed[argument_index].store(false, .monotonic);
                    }
                    cold.arg_map_values = values;
                    cold.arg_map_severed = severed;
                },
            }
        }
        return args_obj;
    }

    pub fn bindParams2(self: *Interpreter, params: []const ast.Param, args: []const Value, is_arrow: bool) EvalError!void {
        // The parameter scope binds `arguments` when this is a non-arrow function
        // (the arguments object) or when a parameter is named `arguments`; in
        // either case a direct eval in a default may not declare `arguments`.
        const param_scope_has_arguments = !is_arrow or paramsBindArguments(params);
        // FunctionDeclarationInstantiation creates every binding in a
        // non-simple parameter list before IteratorBindingInitialization begins.
        // The bindings are initialized strictly left-to-right, so a default,
        // computed key, iterator hook, or direct eval that reaches a later
        // parameter observes its live TDZ rather than an outer/global name.
        // Non-simple lists cannot contain duplicate bound names (an early error),
        // so each predeclaration owns one exact parameter binding.
        var non_simple = false;
        for (params) |parameter| {
            if (parameter.default != null or parameter.is_rest or parameter.pattern != null) {
                non_simple = true;
                break;
            }
        }
        if (non_simple and self.tdz_marker != null) {
            for (params) |parameter| {
                if (parameter.pattern) |pattern|
                    try self.predeclareForLexicalPattern(pattern, false)
                else
                    try self.env.put(parameter.name, self.tdzVal());
            }
        }
        for (params, 0..) |p, i| {
            if (p.is_rest) {
                const rest = try self.newArray();
                var j = i;
                while (j < args.len) : (j += 1) try rest.asObj().appendElement(self.arena, args[j]);
                if (p.pattern) |pat| try self.bindPattern(pat, rest, true) else try self.env.put(p.name, rest);
                break;
            }
            var v: Value = if (i < args.len) args[i] else Value.undef();
            if (v.isUndefined()) {
                if (p.default) |d| {
                    // The default runs in the parameter scope; a non-arrow's owns
                    // `arguments`, so a direct eval there can't declare it. The
                    // `in_param_default` flag (all functions) marks that a direct
                    // eval here may not `var`-declare a parameter name.
                    const saved_pe = self.in_param_expr;
                    const saved_pd = self.in_param_default;
                    self.in_param_expr = param_scope_has_arguments;
                    self.in_param_default = true;
                    v = self.eval(d) catch |e| {
                        self.in_param_expr = saved_pe;
                        self.in_param_default = saved_pd;
                        return e;
                    };
                    self.in_param_expr = saved_pe;
                    self.in_param_default = saved_pd;
                    if (p.pattern == null) try self.maybeNameAnon(v, d, p.name); // `function f(x = () => {})` ⇒ name "x"
                }
            }
            if (p.pattern) |pat| try self.bindPattern(pat, v, true) else try self.env.put(p.name, v);
        }
    }

    /// `new Callee(args)`: builtin error constructors mint an error instance;
    /// JS functions get a fresh `this` object (tagged with a constructor
    /// reference for `instanceof`) and may override it by explicitly returning
    /// an object.
    fn evalNew(self: *Interpreter, callee_node: *Node, arg_nodes: []*Node) EvalError!Value {
        const callee = try self.eval(callee_node);
        const args = try self.evalArgs(arg_nodes);
        return self.construct(callee, args);
    }

    /// Construct an instance from `callee` with already-evaluated `args`. Shared
    /// by the `new` operator and the C-API `JSObjectCallAsConstructor`.
    /// Copy a built-in super constructor's result (`src`, a fresh exotic object)
    /// onto the derived instance (`dst`) in place, so the instance gains the
    /// internal slots — [[SetData]]/[[MapData]]/array elements/[[PromiseState]]/
    /// wrapper [[…Data]]/etc. — plus any maintained own properties (e.g. a Set's
    /// `size`). `dst`'s prototype (its derived `.prototype`) is preserved; `dst`
    /// is otherwise pristine (a derived constructor cannot touch `this` before
    /// `super()` returns). `src` is discarded, so transfer ownership of any
    /// GC-owned backing stores to `dst`; otherwise both cells would finalize the
    /// same slots/elements/accessor storage.
    fn adoptInternalSlots(dst: *value.Object, src: *value.Object) void {
        const keep_proto = dst.protoAtomic();
        dst.* = src.*;
        dst.setProtoAtomic(keep_proto);
        src.* = .{};
    }

    pub fn construct(self: *Interpreter, callee: Value, args: []const Value) EvalError!Value {
        return self.constructNT(callee, args, callee);
    }

    /// [[Construct]] with an explicit NewTarget (Reflect.construct / subclassing):
    /// `new_target` drives the new instance's prototype and the `new.target` seen
    /// by the constructor; `callee` is the function actually invoked.
    pub fn constructNT(self: *Interpreter, callee: Value, args: []const Value, new_target: Value) EvalError!Value {
        if (!callee.isObject()) return self.throwError("TypeError", "value is not a constructor");
        const obj = callee.asObj();
        if (obj.proxyHandler() != null or obj.proxy_revoked) {
            const target = obj.proxyTarget() orelse return self.throwError("TypeError", "Cannot perform 'construct' on a proxy that has been revoked");
            // A Proxy has a [[Construct]] method only if its target is a
            // constructor; if not, `new proxy()` is a TypeError before the
            // construct trap runs (9.5.13).
            if (!isConstructorValue(Value.obj(target))) return self.throwError("TypeError", "value is not a constructor");
            if (try self.proxyTrap(obj, "construct")) |trap| {
                const arr = try self.newArray();
                for (args) |a| try arr.asObj().appendElement(self.arena, a);
                const res = try self.callValueWithThis(trap, &.{ Value.obj(target), arr, new_target }, Value.obj(obj.proxyHandler().?));
                // The [[Construct]] trap must return an Object (9.5.14 step 9).
                if (!res.isObject() or res.asObj().is_symbol or res.asObj().is_bigint)
                    return self.throwError("TypeError", "proxy 'construct' trap must return an object");
                return res;
            }
            return self.constructNT(Value.obj(target), args, new_target);
        }
        if (obj.boundFunction()) |erased| {
            // `new (fn.bind(...))(...)`: construct the target with bound args
            // prepended (the bound `this` is ignored by `new`, per spec).
            const bf: *BoundFn = @ptrCast(@alignCast(erased));
            const nt = if (std.meta.eql(new_target, callee)) bf.target else new_target;
            return self.constructNT(bf.target, try self.concatArgs(bf.args, args), nt);
        }
        if (obj.errorCtor()) |name| return self.makeErrorWithArgsNT(name, args, new_target);
        if (obj.hostClassHooks()) |hooks| if (hooks.construct) |construct_callback| {
            if (hooks.is_constructor != null and hooks.is_constructor.?(obj)) {
                self.recordExecutionTier(.host_callbacks);
                return construct_callback(@ptrCast(self), obj, args);
            }
        };
        if (obj.native) |nf| {
            // Most built-ins aren't constructors; only flagged ones are `new`-able.
            if (!obj.native_ctor) return self.throwError("TypeError", "value is not a constructor");
            // Signal [[Construct]] to the native via `new_target` (restored after),
            // so e.g. `new Number(x)` boxes a wrapper object while `Number(x)`
            // returns a primitive.
            const saved_nt = self.new_target;
            self.new_target = new_target;
            defer self.new_target = saved_nt;
            const saved_native = self.active_native;
            self.active_native = obj;
            defer self.active_native = saved_native;
            return nf(@ptrCast(self), Value.undef(), args); // native ctor (Array, Map, RegExp, ...)
        }
        if (obj.jsFunction()) |erased| {
            const func: *Function = @ptrCast(@alignCast(erased));
            // Arrow / async / generator functions and concise methods / accessors
            // are not constructors (a class constructor is not flagged is_method).
            if (func.is_arrow or func.is_async or func.is_generator or func.is_method)
                return self.throwError("TypeError", "value is not a constructor");
            // OrdinaryCreateFromConstructor: the instance proto comes from NewTarget.
            const inst = try gc_mod.allocObj(self.arena);
            inst.* = .{ .proto = if (new_target.isObject()) try self.ctorRealmIntrinsicProto(new_target.asObj(), "Object") else try self.protoObject(obj) };
            try inst.setCtorRef(self.arena, obj);
            const this_val = Value.obj(inst);
            const ret = try self.callFunctionNT(func, args, this_val, new_target);
            return if (ret.isObject()) ret else this_val;
        }
        return self.throwError("TypeError", "value is not a constructor");
    }

    // ---- objects, arrays, members -----------------------------------------

    fn memberKey(self: *Interpreter, static: []const u8, computed: ?*Node) EvalError![]const u8 {
        if (computed) |ce| return self.keyOf(try self.eval(ce));
        return value.encodeStringKey(self.arena, static);
    }

    fn fastNumericIndex(v: Value) ?usize {
        if (!v.isNumber()) return null;
        const n = v.asNum();
        if (std.math.isNan(n) or std.math.isInf(n) or @trunc(n) != n or n < 0 or n >= 4294967295)
            return null;
        return @intFromFloat(n);
    }

    fn arrayProtoChainCleanForIndexedSet(self: *Interpreter, o: *value.Object) bool {
        var cur = self.effectiveProto(o);
        while (cur) |c| {
            if (c.proxyHandler() != null or c.proxy_revoked or c.typedArray() != null or c.has_indexed_property.load(.monotonic))
                return false;
            if (c.indexed_own_seen.load(.acquire)) return false;
            cur = self.effectiveProto(c);
        }
        return true;
    }

    pub fn arrayProtoChainCleanForDenseAppend(self: *Interpreter, o: *value.Object) bool {
        var cur = self.effectiveProto(o);
        while (cur) |c| {
            if (c.proxyHandler() != null or c.proxy_revoked or c.typedArray() != null or c.has_indexed_property.load(.monotonic))
                return false;
            if (c.indexed_own_seen.load(.acquire)) return false;
            cur = self.effectiveProto(c);
        }
        return true;
    }

    /// Pure eligibility gate for the private JSArray contiguous-vector bridge.
    /// The vector snapshot performs the final hole/length/backing checks.
    pub fn canExposeContiguousArray(self: *Interpreter, o: *value.Object) bool {
        if (!o.is_array or o.is_arguments or o.forced_array_storage or
            o.proxyHandler() != null or o.proxy_revoked or o.typedArray() != null or
            o.accessorsMap() != null or o.attrsMap() != null or
            o.has_indexed_property.load(.monotonic)) return false;
        return self.arrayProtoChainCleanForIndexedSet(o);
    }

    /// VM call-site fast path for the intrinsic `Array.prototype.push`. The
    /// callee identity check means an own/prototype override has already won
    /// during ordinary property lookup. Only packed, extensible real arrays
    /// whose indexed writes cannot observe a descriptor or prototype hook are
    /// mutated here; every generic/observable case returns null for normal
    /// native dispatch.
    pub fn isIntrinsicArrayPush(callee: Value) bool {
        if (!callee.isObject()) return false;
        const native = callee.asObj().native orelse return false;
        return native == arrayProtoMethod("push");
    }

    pub fn tryFastArrayPush(self: *Interpreter, callee: Value, this: Value, args: []const Value) EvalError!?Value {
        if (!isIntrinsicArrayPush(callee)) return null;
        if (!this.isObject()) return null;
        const o = this.asObj();
        try self.checkRestricted(o);
        if (!o.is_array or o.is_arguments or o.proxyHandler() != null or o.proxy_revoked or
            o.accessorsMap() != null or o.attrsMap() != null or
            o.has_indexed_property.load(.monotonic) or !o.isExtensible() or
            !self.arrayProtoChainCleanForDenseAppend(o)) return null;
        const new_len = try o.appendPackedDenseElements(self.arena, args) orelse return null;
        return Value.num(@floatFromInt(new_len));
    }

    fn arrayProtoMayAffectIndexedHas(self: *Interpreter, o: *value.Object) bool {
        var cur = self.effectiveProto(o);
        while (cur) |c| {
            if (c.proxyHandler() != null or c.proxy_revoked or c.typedArray() != null or c.has_indexed_property.load(.monotonic))
                return true;
            if (c.indexed_own_seen.load(.acquire)) return true;
            cur = self.effectiveProto(c);
        }
        return false;
    }

    fn setFastArrayNumericIndex(self: *Interpreter, recv: Value, index: usize, v: Value) EvalError!bool {
        if (!recv.isObject()) return false;
        const o = recv.asObj();
        try self.checkRestricted(o);
        if (!o.is_array or o.is_arguments or o.accessorsMap() != null or o.attrsMap() != null or
            o.has_indexed_property.load(.monotonic) or !o.isExtensible() or !self.arrayProtoChainCleanForIndexedSet(o))
            return false;
        const dense_cap: usize = 1 << 24;
        return try o.setOrGrowDenseElement(self.arena, index, v, dense_cap);
    }

    /// ToPropertyKey: a Symbol key uses its unique internal encoding (so
    /// symbol-keyed properties don't collide with string keys and stay out of
    /// string enumeration); other keys coerce to string.
    /// ToString(v): the spec abstract operation — `ToString(ToPrimitive(v,
    /// string))` for an object (running its `toString`/`valueOf`, propagating any
    /// throw), and a TypeError for a Symbol. Unlike `Value.toString` (a Zig-level
    /// rendering), this observes user methods and rejects Symbols.
    pub fn toStringV(self: *Interpreter, v: Value) EvalError![]const u8 {
        if (v.isObject() and v.asObj().is_symbol)
            return self.throwError("TypeError", "Cannot convert a Symbol value to a string");
        if (v.isObject()) {
            const prim = try self.toPrimitive(v, .string);
            if (prim.isObject() and prim.asObj().is_symbol)
                return self.throwError("TypeError", "Cannot convert a Symbol value to a string");
            return prim.toString(self.arena);
        }
        return v.toString(self.arena);
    }

    /// Like `toStringV`, but retain the resulting string Value so a
    /// representation-aware consumer can stream code units without copying an
    /// existing string through an encoded byte slice and a new StringCell.
    pub fn toStringValue(self: *Interpreter, v: Value) EvalError!Value {
        if (v.isObject() and v.asObj().is_symbol)
            return self.throwError("TypeError", "Cannot convert a Symbol value to a string");
        if (v.isObject()) {
            const prim = try self.toPrimitive(v, .string);
            if (prim.isObject() and prim.asObj().is_symbol)
                return self.throwError("TypeError", "Cannot convert a Symbol value to a string");
            if (prim.isString()) return prim;
            return Value.strAlloc(self.arena, try prim.toString(self.arena));
        }
        if (v.isString()) return v;
        return Value.strAlloc(self.arena, try v.toString(self.arena));
    }

    /// Like `toStringV`, but a string result is returned as canonical WTF-8 via
    /// `Value.asWtf8` (re-encoding a flat-latin1 cell). Use this — not
    /// `toStringV` — at every site that feeds the coerced string into WTF-8
    /// decoding/slicing logic, so a flat-stored receiver is seen as WTF-8. A
    /// number/boolean/etc. renders to ASCII, for which `asWtf8`/`toString` agree.
    pub fn toStringWtf8(self: *Interpreter, v: Value) EvalError![]const u8 {
        if (v.isObject() and v.asObj().is_symbol)
            return self.throwError("TypeError", "Cannot convert a Symbol value to a string");
        if (v.isObject()) {
            const prim = try self.toPrimitive(v, .string);
            if (prim.isObject() and prim.asObj().is_symbol)
                return self.throwError("TypeError", "Cannot convert a Symbol value to a string");
            if (prim.isString()) return prim.asWtf8(self.arena);
            return prim.toString(self.arena);
        }
        if (v.isString()) return v.asWtf8(self.arena);
        return v.toString(self.arena);
    }

    /// ToNumber(v): runs `[Symbol.toPrimitive]`/`valueOf`/`toString` for an
    /// object (propagating throws), and a TypeError for a Symbol.
    pub fn toNumberV(self: *Interpreter, v: Value) EvalError!f64 {
        if (v.isObject() and v.asObj().is_symbol)
            return self.throwError("TypeError", "Cannot convert a Symbol value to a number");
        if (v.isObject() and v.asObj().is_bigint)
            return self.throwError("TypeError", "Cannot convert a BigInt value to a number");
        if (v.isObject()) {
            const prim = try self.toPrimitive(v, .number);
            if (prim.isObject() and prim.asObj().is_symbol)
                return self.throwError("TypeError", "Cannot convert a Symbol value to a number");
            if (prim.isObject() and prim.asObj().is_bigint)
                return self.throwError("TypeError", "Cannot convert a BigInt value to a number");
            return prim.toNumber();
        }
        return v.toNumber();
    }

    /// ArraySetLength's numeric path: ToUint32(value), then ToNumber(value)
    /// again, so observable coercions run in spec order before descriptor checks.
    pub fn arrayLengthFromValue(self: *Interpreter, v: Value) EvalError!u32 {
        const uint_n = try self.toNumberV(v);
        const new_len = Value.uint32FromF64(uint_n);
        const number_len = try self.toNumberV(v);
        if (@as(f64, @floatFromInt(new_len)) != number_len)
            return self.throwError("RangeError", "Invalid array length");
        return new_len;
    }

    /// Apply the deletion half of ArraySetLength after writability/coercion
    /// checks. Returns false when a non-configurable element blocks the shrink.
    pub fn setArrayLength(self: *Interpreter, o: *value.Object, requested_len: usize) EvalError!bool {
        if (!o.is_arguments and o.attrsMap() == null and o.accessorsMap() == null and !o.has_indexed_property.load(.monotonic)) {
            try o.truncateDenseElementsAndSetLength(self.arena, requested_len);
            return true;
        }

        const old_len = o.arrayLength();
        var new_len = requested_len;
        var blocked = false;

        if (requested_len < old_len) {
            const DeleteEntry = struct {
                idx: usize,
                key: []const u8,
            };
            var entries: std.ArrayListUnmanaged(DeleteEntry) = .empty;
            for (try self.objectOwnKeysList(o)) |k| {
                if (arrayElementIndex(k)) |idx| {
                    if (idx >= requested_len and idx < old_len)
                        try entries.append(self.arena, .{ .idx = idx, .key = k });
                }
            }
            std.mem.sort(DeleteEntry, entries.items, {}, struct {
                fn lt(_: void, a: DeleteEntry, b: DeleteEntry) bool {
                    return a.idx > b.idx;
                }
            }.lt);

            for (entries.items) |entry| {
                if (!objectHasOwn(o, entry.key)) continue;
                if (!o.getAttr(entry.key).configurable) {
                    new_len = entry.idx + 1;
                    blocked = true;
                    break;
                }
                _ = try self.deleteOwn(o, entry.key);
            }
        }

        try o.truncateDenseElementsAndSetLength(self.arena, new_len);
        return !blocked;
    }

    /// ToPropertyKey as a primitive Value: ToPrimitive(key, string) keeping a
    /// Symbol as-is. Unlike `keyOf` it returns the primitive (not a storage
    /// string), so a caller can derive BOTH a storage key and a display name
    /// from a single — possibly side-effecting — coercion. (Computing them with
    /// two `keyOf`/`keyDisplayName` calls would run `valueOf`/`@@toPrimitive`
    /// twice and, when the result is a Symbol, throw in the ToString half.)
    pub fn toPropertyKeyValue(self: *Interpreter, k: Value) EvalError!Value {
        const primitive = if (k.isObject() and !k.asObj().is_symbol)
            try self.toPrimitive(k, .string)
        else
            k;
        if (primitive.isObject() and primitive.asObj().is_symbol) return primitive;
        if (primitive.isString()) return try Value.strAlloc(self.arena, try primitive.asWtf8(self.arena));
        return try Value.strAlloc(self.arena, try primitive.toString(self.arena));
    }

    pub fn keyOf(self: *Interpreter, k: Value) EvalError![]const u8 {
        if (k.isObject() and k.asObj().is_symbol) return self.registerSymbol(k.asObj());
        // ToPropertyKey: an object key is first ToPrimitive(key, string) — running
        // its `[Symbol.toPrimitive]`/`toString`/`valueOf` (a TypeError if none
        // yields a primitive) — and a resulting Symbol keeps its key.
        if (k.isObject()) {
            const prim = try self.toPrimitive(k, .string);
            if (prim.isObject() and prim.asObj().is_symbol) return self.registerSymbol(prim.asObj());
            // Property keys are canonical WTF-8 (compared by bytes, read by JSON /
            // enumeration), so re-encode a flat-latin1 string key.
            if (prim.isString()) return value.encodeStringKey(self.arena, try prim.asWtf8(self.arena));
            return value.encodeStringKey(self.arena, try prim.toString(self.arena));
        }
        if (k.isString()) return value.encodeStringKey(self.arena, try k.asWtf8(self.arena));
        return value.encodeStringKey(self.arena, try k.toString(self.arena));
    }

    /// Index a Symbol by its encoded `sym_key` so it can later be recovered (by
    /// getOwnPropertySymbols / proxy traps), then return that key.
    fn registerSymbol(self: *Interpreter, sym: *value.Object) []const u8 {
        self.symbols.put(self.arena, sym.symbolKey(), sym) catch {};
        if (self.symbolIdentityRegistry()) |symbol_registry| {
            const storage_key = self.symbolRegistryStorageKey(sym.symbolKey()) catch return sym.symbolKey();
            symbol_registry.setOwn(self.arena, self.root_shape, storage_key, Value.obj(sym)) catch {};
        }
        return sym.symbolKey();
    }

    fn symbolRegistryStorageKey(self: *Interpreter, key: []const u8) EvalError![]const u8 {
        return std.fmt.allocPrint(self.arena, "\x00r{s}", .{key});
    }

    fn symbolIdentityRegistry(self: *Interpreter) ?*value.Object {
        const symbol_namespace = self.env.get("Symbol") orelse return null;
        if (!symbol_namespace.isObject()) return null;
        if (symbol_namespace.asObj().getOwn("\x00registry")) |shared| {
            if (shared.isObject()) return shared.asObj();
        }
        return symbol_namespace.asObj();
    }

    /// Allocate a fresh plain object. The single creation point so later tiers
    /// (object shapes) have one seam to hook.
    pub fn newObject(self: *Interpreter) EvalError!Value {
        const obj = try gc_mod.allocObject(self.gc, self.arena);
        // An ordinary object's [[Prototype]] is %Object.prototype%. Callers that
        // need a null-proto object (`Object.create(null)`, dictionary holders)
        // overwrite `obj.protoAtomic()` right after this returns.
        // `allocObject` has already default-initialized every field; assign only
        // the prototype instead of zeroing the large Object payload a second
        // time on the dominant allocation path.
        obj.proto = self.objectProto();
        return Value.obj(obj);
    }

    /// The `.prototype` object of a constructor, creating it on first use (every
    /// function/class has one; instances proto to it).
    /// GetPrototypeFromConstructor(ctor, %Intl.<service>.prototype%): the
    /// constructor's own `prototype` when it is an object, else the intrinsic
    /// prototype of the constructor's *realm* (recovered from a JS function's
    /// closure root environment), so cross-realm `Reflect.construct` derives the
    /// proto from the NewTarget's realm. Falls back to the current realm.
    pub fn ctorRealmProto(self: *Interpreter, ctor: *value.Object, service: []const u8) EvalError!*value.Object {
        const p = try self.getProperty(Value.obj(ctor), "prototype");
        if (p.isObject() and !p.asObj().is_symbol) return p.asObj();
        if (try self.functionRealmIntlProto(ctor, service)) |proto| return proto;
        return try self.protoObject(ctor);
    }

    fn envIntlServiceProto(env: *Environment, service: []const u8) ?*value.Object {
        if (env.get("globalThis")) |gt| {
            if (gt.isObject()) {
                if (gt.asObj().getOwn("Intl")) |intl| {
                    if (intl.isObject()) {
                        if (intl.asObj().getOwn(service)) |svc_v| {
                            if (svc_v.isObject()) {
                                if (svc_v.asObj().getOwn("prototype")) |proto_v| {
                                    if (proto_v.isObject()) return proto_v.asObj();
                                }
                            }
                        }
                    }
                }
            }
        }
        if (env.get("Intl")) |intl| {
            if (intl.isObject()) {
                if (intl.asObj().getOwn(service)) |svc_v| {
                    if (svc_v.isObject()) {
                        if (svc_v.asObj().getOwn("prototype")) |proto_v| {
                            if (proto_v.isObject()) return proto_v.asObj();
                        }
                    }
                }
            }
        }
        return null;
    }

    fn envIntrinsicProto(env: *Environment, intrinsic: []const u8) ?*value.Object {
        if (env.get("globalThis")) |gt| {
            if (gt.isObject()) {
                if (gt.asObj().getOwn(intrinsic)) |ctor_v| {
                    if (ctor_v.isObject()) {
                        if (ctor_v.asObj().getOwn("prototype")) |proto_v| {
                            if (proto_v.isObject()) return proto_v.asObj();
                        }
                    }
                }
            }
        }
        if (env.get(intrinsic)) |ctor_v| {
            if (ctor_v.isObject()) {
                if (ctor_v.asObj().getOwn("prototype")) |proto_v| {
                    if (proto_v.isObject()) return proto_v.asObj();
                }
            }
        }
        return null;
    }

    fn envIntrinsicObject(env: *Environment, intrinsic: []const u8) ?*value.Object {
        if (env.get(intrinsic)) |v| {
            if (v.isObject()) return v.asObj();
        }
        return null;
    }

    fn functionRealmIntrinsicProto(self: *Interpreter, ctor: *value.Object, intrinsic: []const u8) EvalError!?*value.Object {
        if (ctor.proxyHandler() != null or ctor.proxy_revoked) {
            const target = ctor.proxyTarget() orelse return self.throwError("TypeError", "Cannot get function realm from a revoked proxy");
            return try self.functionRealmIntrinsicProto(target, intrinsic);
        }
        if ((ctor.native_ctor or ctor.errorCtor() != null) and ctor.private_data != null) {
            const env: *Environment = @ptrCast(@alignCast(ctor.private_data.?));
            if (envIntrinsicProto(env, intrinsic)) |proto| return proto;
        }
        if (ctor.jsFunction()) |jf| {
            const fnp: *Function = @ptrCast(@alignCast(jf));
            var env: ?*Environment = fnp.closure;
            while (env) |e| {
                if (envIntrinsicProto(e, intrinsic)) |proto| return proto;
                if (e.parent == null) break;
                env = e.parent;
            }
        }
        if (ctor.boundFunction()) |erased| {
            const bf: *BoundFn = @ptrCast(@alignCast(erased));
            if (bf.target.isObject()) return try self.functionRealmIntrinsicProto(bf.target.asObj(), intrinsic);
        }
        return null;
    }

    fn functionRealmIntlProto(self: *Interpreter, ctor: *value.Object, service: []const u8) EvalError!?*value.Object {
        if (ctor.proxyHandler() != null or ctor.proxy_revoked) {
            const target = ctor.proxyTarget() orelse return self.throwError("TypeError", "Cannot get function realm from a revoked proxy");
            return try self.functionRealmIntlProto(target, service);
        }
        if ((ctor.native_ctor or ctor.errorCtor() != null) and ctor.private_data != null) {
            const env: *Environment = @ptrCast(@alignCast(ctor.private_data.?));
            if (envIntlServiceProto(env, service)) |proto| return proto;
        }
        if (ctor.jsFunction()) |jf| {
            const fnp: *Function = @ptrCast(@alignCast(jf));
            var env: ?*Environment = fnp.closure;
            while (env) |e| {
                if (envIntlServiceProto(e, service)) |proto| return proto;
                if (e.parent == null) break;
                env = e.parent;
            }
        }
        if (ctor.boundFunction()) |erased| {
            const bf: *BoundFn = @ptrCast(@alignCast(erased));
            if (bf.target.isObject()) return try self.functionRealmIntlProto(bf.target.asObj(), service);
        }
        return null;
    }

    fn functionRealmIntrinsicObject(self: *Interpreter, ctor: *value.Object, intrinsic: []const u8) EvalError!?*value.Object {
        if (ctor.proxyHandler() != null or ctor.proxy_revoked) {
            const target = ctor.proxyTarget() orelse return self.throwError("TypeError", "Cannot get function realm from a revoked proxy");
            return try self.functionRealmIntrinsicObject(target, intrinsic);
        }
        if ((ctor.native_ctor or ctor.errorCtor() != null) and ctor.private_data != null) {
            const env: *Environment = @ptrCast(@alignCast(ctor.private_data.?));
            if (envIntrinsicObject(env, intrinsic)) |obj| return obj;
        }
        if (ctor.jsFunction()) |jf| {
            const fnp: *Function = @ptrCast(@alignCast(jf));
            var env: ?*Environment = fnp.closure;
            while (env) |e| {
                if (envIntrinsicObject(e, intrinsic)) |obj| return obj;
                if (e.parent == null) break;
                env = e.parent;
            }
        }
        if (ctor.boundFunction()) |erased| {
            const bf: *BoundFn = @ptrCast(@alignCast(erased));
            if (bf.target.isObject()) return try self.functionRealmIntrinsicObject(bf.target.asObj(), intrinsic);
        }
        return null;
    }

    /// GetPrototypeFromConstructor for global intrinsics such as
    /// `%AggregateError.prototype%`: own `newTarget.prototype` wins; otherwise
    /// use the NewTarget realm's intrinsic prototype when that realm is known.
    pub fn ctorRealmIntrinsicProto(self: *Interpreter, ctor: *value.Object, intrinsic: []const u8) EvalError!*value.Object {
        const p = try self.getProperty(Value.obj(ctor), "prototype");
        if (p.isObject() and !p.asObj().is_symbol) return self.preparePrototypeUse(p.asObj());
        if (try self.functionRealmIntrinsicProto(ctor, intrinsic)) |proto| return proto;
        if (envIntrinsicProto(self.env, intrinsic)) |proto| return proto;
        return try self.protoObject(ctor);
    }

    /// GetPrototypeFromConstructor(newTarget, %ctor_name.prototype%): read
    /// `newTarget.prototype` via [[Get]] (a getter runs and may throw); if the
    /// result isn't an object, fall back to the named intrinsic's prototype.
    /// Returns null when there is no new.target (the caller keeps its default).
    fn protoFromCtor(self: *Interpreter, ctor_name: []const u8) EvalError!?*value.Object {
        if (!self.new_target.isObject()) return null;
        // GetPrototypeFromConstructor: new.target.prototype, or — when that is not
        // an Object — the *new.target's realm's* named intrinsic prototype.
        return try self.ctorRealmIntrinsicProto(self.new_target.asObj(), ctor_name);
    }

    pub fn protoObject(self: *Interpreter, ctor: *value.Object) EvalError!*value.Object {
        if (ctor.getOwn("prototype")) |p| {
            if (p.isObject()) return self.preparePrototypeUse(p.asObj());
        }
        // Lazy install is a check-then-act over shared object storage: with the
        // GIL dropped, two threads `new`-ing (or reading `.prototype` of) the same
        // not-yet-materialized constructor could both miss above and install
        // *distinct* prototypes, breaking `F.prototype === F.prototype`. Take the
        // realm lazy-init lock and RE-CHECK (double-checked locking), so exactly
        // one thread installs and the others observe it. No-op when threads are
        // off (gil == null), so the single-thread path is unchanged.
        if (self.gil) |g| {
            g.lockLazyInit();
            defer g.unlockLazyInit();
            if (ctor.getOwn("prototype")) |p| {
                if (p.isObject()) return self.preparePrototypeUse(p.asObj());
            }
            return try self.installProtoObject(ctor);
        }
        return try self.installProtoObject(ctor);
    }

    fn preparePrototypeUse(self: *Interpreter, proto: *value.Object) *value.Object {
        _ = self;
        if (proto.elementsLen() != 0) proto.indexed_own_seen.store(true, .release);
        return proto;
    }

    fn installProtoObject(self: *Interpreter, ctor: *value.Object) EvalError!*value.Object {
        const proto = (try self.newObject()).asObj();
        try self.setProp(ctor, "prototype", Value.obj(proto));
        // `F.prototype.constructor === F` (writable, non-enumerable,
        // configurable), so an instance's `.constructor` resolves through the
        // prototype chain to F — not the `Object` fallback. Matches the lazy
        // materialization in `getProperty`.
        try self.setProp(proto, "constructor", Value.obj(ctor));
        try proto.setAttr(self.arena, "constructor", .{ .writable = true, .enumerable = false, .configurable = true });
        return proto;
    }

    /// Lazily materialize a generator function's `.prototype` (no `constructor`
    /// back-link; its [[Prototype]] is %(Async)GeneratorPrototype%). Same
    /// check-then-act race as `protoObject`, so it shares the double-checked
    /// realm lazy-init lock.
    pub fn genProtoObject(self: *Interpreter, o: *value.Object, is_async: bool) EvalError!*value.Object {
        if (o.getOwn("prototype")) |p| {
            if (p.isObject()) return p.asObj();
        }
        if (self.gil) |g| {
            g.lockLazyInit();
            defer g.unlockLazyInit();
            if (o.getOwn("prototype")) |p| {
                if (p.isObject()) return p.asObj();
            }
            return try self.installGenProto(o, is_async);
        }
        return try self.installGenProto(o, is_async);
    }

    fn installGenProto(self: *Interpreter, o: *value.Object, is_async: bool) EvalError!*value.Object {
        const tag = if (is_async) "\x00AsyncGenProto" else "\x00GenProto";
        const proto = try gc_mod.allocObj(self.arena);
        const gen_proto = (try self.functionRealmIntrinsicObject(o, tag)) orelse
            if (Interpreter.envIntrinsicObject(self.env, tag)) |gp| gp else null;
        proto.* = .{ .proto = gen_proto };
        try o.setOwn(self.arena, self.root_shape, "prototype", Value.obj(proto));
        try o.setAttr(self.arena, "prototype", .{ .writable = true, .enumerable = false, .configurable = false });
        return proto;
    }

    pub fn pollAbortSignalTimeouts(self: *Interpreter) EvalError!void {
        const poll = self.abort_timeout_poll orelse return;
        if (self.polling_abort_timeouts) return;
        self.polling_abort_timeouts = true;
        defer self.polling_abort_timeouts = false;
        try poll(self.abort_timeout_ctx, self);
    }

    pub fn pollTimers(self: *Interpreter) EvalError!void {
        const poll = self.timer_poll orelse return;
        if (self.polling_timers) return;
        self.polling_timers = true;
        defer self.polling_timers = false;
        try poll(self.timer_ctx, self);
    }

    pub fn keepaliveTimers(self: *Interpreter) void {
        const keepalive = self.timer_keepalive orelse return;
        keepalive(self.timer_ctx, self);
    }

    pub fn abandonTimers(self: *Interpreter) void {
        const abandon = self.timer_abandon orelse return;
        abandon(self.timer_ctx, self);
    }

    /// Run one complete host checkpoint: finish the current task's next ticks
    /// and Promise jobs before selecting timer tasks. Timer callbacks may queue
    /// another microtask checkpoint, which the Context scheduler drains between
    /// timer records rather than batching multiple tasks together.
    pub fn drainMicrotasks(self: *Interpreter) EvalError!void {
        if (self.microtasks != null or self.next_ticks != null) {
            var batch: std.ArrayListUnmanaged(promise.Microtask) = .empty;
            defer batch.deinit(self.arena);
            while (true) {
                if (self.next_ticks) |queue| try self.drainJobQueue(queue, &batch);
                if (self.microtasks) |queue| try self.drainJobQueue(queue, &batch);
                const more_next_ticks = if (self.next_ticks) |queue| self.jobQueueHasPending(queue) else false;
                if (!more_next_ticks) break;
            }
        }
        try self.pollAbortSignalTimeouts();
        try self.pollTimers();
    }

    /// Move each pending burst out under its queue lock, then execute unlocked.
    /// Jobs enqueued reentrantly form the next FIFO burst. On an abrupt failure,
    /// untouched jobs are restored ahead of newly queued work.
    fn drainJobQueue(
        self: *Interpreter,
        queue: *promise.MicrotaskQueue,
        batch: *std.ArrayListUnmanaged(promise.Microtask),
    ) EvalError!void {
        while (try self.jobQueueDequeueBatch(queue, batch)) {
            var i: usize = 0;
            while (i < batch.items.len) : (i += 1) {
                const job = batch.items[i];
                self.current_microtask_batch = batch.items[i + 1 ..];
                self.current_microtask = job;
                promise.runJob(self, &self.current_microtask.?) catch |err| {
                    if (job.kind == .next_tick and err == error.Throw) {
                        const thrown = self.exception;
                        self.exception = Value.undef();
                        const handled = handleProcessUncaughtException(self, thrown, false) catch |dispatch_err| {
                            self.lockJobQueue(queue);
                            queue.prependSlice(self.arena, batch.items[i + 1 ..]) catch {};
                            self.unlockJobQueue(queue);
                            self.current_microtask = null;
                            self.current_microtask_batch = &.{};
                            return dispatch_err;
                        };
                        if (handled) {
                            self.current_microtask = null;
                            self.serviceRequestedGcCheckpoint();
                            continue;
                        }
                        self.exception = thrown;
                    }
                    self.lockJobQueue(queue);
                    queue.prependSlice(self.arena, batch.items[i + 1 ..]) catch {};
                    self.unlockJobQueue(queue);
                    self.current_microtask = null;
                    self.current_microtask_batch = &.{};
                    return err;
                };
                self.current_microtask = null;
                self.serviceRequestedGcCheckpoint();
            }
            self.current_microtask_batch = &.{};
            batch.clearRetainingCapacity();
        }
    }

    /// Atomically pop the next microtask (front of the queue), or null if empty.
    /// Holds the current microtask queue lock only across the queue mutation — never across the
    /// job's execution — so it stays a brief leaf-lock that can't deadlock with
    /// the GIL or any per-structure lock.
    fn microtaskDequeue(self: *Interpreter) ?promise.Microtask {
        const q = self.microtasks orelse return null;
        self.lockMicrotasks();
        defer self.unlockMicrotasks();
        return q.pop();
    }

    /// Atomically move all currently pending microtasks into `batch`. Running
    /// the copied burst outside the queue lock avoids serializing independent
    /// jobs on a lock while preserving per-queue FIFO: tasks enqueued by the
    /// burst (or by a peer) remain in the queue and are drained by a later burst.
    fn jobQueueDequeueBatch(
        self: *Interpreter,
        queue: *promise.MicrotaskQueue,
        batch: *std.ArrayListUnmanaged(promise.Microtask),
    ) EvalError!bool {
        self.lockJobQueue(queue);
        defer self.unlockJobQueue(queue);
        const pending = queue.pendingItems();
        if (pending.len == 0) {
            queue.clearRetainingCapacity();
            return false;
        }
        if (batch.capacity - batch.items.len < pending.len) promise_profile.recordMicrotaskBatchGrow();
        try batch.appendSlice(self.arena, pending);
        promise_profile.recordMicrotaskPops(pending.len);
        queue.clearRetainingCapacity();
        return true;
    }

    fn jobQueueHasPending(self: *Interpreter, queue: *promise.MicrotaskQueue) bool {
        self.lockJobQueue(queue);
        defer self.unlockJobQueue(queue);
        return !queue.isEmpty();
    }

    pub fn lockJobQueue(self: *Interpreter, queue: *promise.MicrotaskQueue) void {
        if (self.lock_microtasks) queue.acquire();
    }

    pub fn unlockJobQueue(self: *Interpreter, queue: *promise.MicrotaskQueue) void {
        if (self.lock_microtasks) queue.release();
    }

    /// Spin-acquire the current microtask queue's lock (only engaged under
    /// `parallel_js`; a single bool check otherwise). The critical section is a
    /// single queue append/pop/length check, never JS.
    pub fn lockMicrotasks(self: *Interpreter) void {
        if (!self.lock_microtasks) return;
        const q = self.microtasks orelse return;
        q.acquire();
    }

    pub fn unlockMicrotasks(self: *Interpreter) void {
        if (!self.lock_microtasks) return;
        if (self.microtasks) |q| q.release();
    }

    pub fn lockRealm(self: *Interpreter) void {
        const m = self.realm_lock orelse return;
        var spins: usize = 0;
        while (!m.tryLock()) : (spins += 1) {
            if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
        }
        // The parallel tracer takes this same realm lock for async waiters and
        // other persistent roots. Do not recover allocation while holding it.
        gc_runtime.enterTraceSensitiveLock();
    }

    pub fn unlockRealm(self: *Interpreter) void {
        if (self.realm_lock) |m| {
            gc_runtime.leaveTraceSensitiveLock();
            m.unlock();
        }
    }

    fn lockPrototypeGraph(self: *Interpreter) void {
        const m = self.prototype_lock orelse return;
        var spins: usize = 0;
        while (!m.tryLock()) : (spins += 1) {
            if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
        }
        gc_runtime.enterTraceSensitiveLock();
    }

    fn unlockPrototypeGraph(self: *Interpreter) void {
        if (self.prototype_lock) |m| {
            gc_runtime.leaveTraceSensitiveLock();
            m.unlock();
        }
    }

    fn asyncWaiterCount(self: *Interpreter, listp: *std.ArrayListUnmanaged(AsyncWaiterEntry)) usize {
        self.lockRealm();
        defer self.unlockRealm();
        return listp.items.len;
    }

    fn appendAsyncWaiter(self: *Interpreter, entry: AsyncWaiterEntry) !void {
        const listp = self.async_waiters orelse return error.OutOfMemory;
        self.lockRealm();
        defer self.unlockRealm();
        const spare = listp.capacity - listp.items.len;
        if (spare == 0) {
            try listp.ensureTotalCapacity(self.arena, listp.items.len + async_waiter_reserve_granularity);
        }
        listp.appendAssumeCapacity(entry);
    }

    fn takeAsyncWaiter(self: *Interpreter, listp: *std.ArrayListUnmanaged(AsyncWaiterEntry), id: u64) ?AsyncWaiterEntry {
        self.lockRealm();
        defer self.unlockRealm();
        var i: usize = 0;
        while (i < listp.items.len) : (i += 1) {
            if (listp.items[i].id == id) return listp.swapRemove(i);
        }
        return null;
    }

    fn clearAsyncWaiters(self: *Interpreter, listp: *std.ArrayListUnmanaged(AsyncWaiterEntry)) void {
        self.lockRealm();
        defer self.unlockRealm();
        listp.clearRetainingCapacity();
    }

    fn serviceRequestedGcCheckpoint(self: *Interpreter) void {
        const requested = self.gc_requested orelse return;
        if (!requested.load(.monotonic)) return;
        const f = self.gc_checkpoint_fn orelse return;
        const ctx = self.gc_checkpoint_ctx orelse return;
        f(ctx);
    }

    /// Register a running VM `Exec` as a precise GC root for the duration of its
    /// instruction loop. No-op when the GC is off (the common path), so the VM
    /// pays only a null check. The list is arena-backed; symmetric `popExecRoot`
    /// keeps it bounded by the live call-nesting depth.
    pub fn pushExecRoot(self: *Interpreter, exec: *vm.Exec) void {
        if (self.gc == null) return;
        self.gc_execs.append(self.arena, exec) catch {};
    }

    pub fn popExecRoot(self: *Interpreter, exec: *vm.Exec) void {
        if (self.gc == null) return;
        var i = self.gc_execs.items.len;
        while (i > 0) {
            i -= 1;
            if (self.gc_execs.items[i] == exec) {
                _ = self.gc_execs.orderedRemove(i);
                return;
            }
        }
    }

    pub fn pushWasmRoots(self: *Interpreter, roots: *value.WasmExecutionRoots) error{OutOfMemory}!void {
        if (self.gc == null) return;
        try self.gc_wasm_roots.append(self.arena, roots);
    }

    pub fn popWasmRoots(self: *Interpreter, roots: *value.WasmExecutionRoots) void {
        if (self.gc == null) return;
        var i = self.gc_wasm_roots.items.len;
        while (i > 0) {
            i -= 1;
            if (self.gc_wasm_roots.items[i] == roots) {
                _ = self.gc_wasm_roots.orderedRemove(i);
                return;
            }
        }
    }

    pub fn pushTempRoot(self: *Interpreter, v: Value) EvalError!usize {
        if (self.gc == null) return 0;
        const mark = self.gc_temp_roots.items.len;
        try self.gc_temp_roots.append(self.arena, v);
        return mark;
    }

    pub fn restoreTempRoots(self: *Interpreter, mark: usize) void {
        if (self.gc == null) return;
        self.gc_temp_roots.shrinkRetainingCapacity(mark);
    }

    pub fn setTempRoot(self: *Interpreter, mark: usize, v: Value) void {
        if (self.gc == null) return;
        std.debug.assert(mark < self.gc_temp_roots.items.len);
        self.gc_temp_roots.items[mark] = v;
    }

    pub fn tempRoot(self: *Interpreter, mark: usize, fallback: Value) Value {
        if (self.gc == null) return fallback;
        return self.gc_temp_roots.items[mark];
    }

    pub fn pushTempEnvRoot(self: *Interpreter, environment: *Environment) EvalError!usize {
        if (self.gc == null) return 0;
        const mark = self.gc_env_roots.items.len;
        try self.gc_env_roots.append(self.arena, environment);
        return mark;
    }

    pub fn restoreTempEnvRoots(self: *Interpreter, mark: usize) void {
        if (self.gc == null) return;
        self.gc_env_roots.shrinkRetainingCapacity(mark);
    }

    pub fn setTempEnvRoot(self: *Interpreter, mark: usize, environment: *Environment) void {
        if (self.gc == null) return;
        std.debug.assert(mark < self.gc_env_roots.items.len);
        self.gc_env_roots.items[mark] = environment;
    }

    pub fn tempEnvRoot(self: *Interpreter, mark: usize, fallback: *Environment) *Environment {
        if (self.gc == null) return fallback;
        return self.gc_env_roots.items[mark];
    }

    fn pushTempBindingReferenceRoot(self: *Interpreter, reference: BindingReference) EvalError!usize {
        if (self.gc == null) return 0;
        const mark = self.gc_binding_reference_roots.items.len;
        try self.gc_binding_reference_roots.append(self.arena, reference);
        return mark;
    }

    fn restoreTempBindingReferenceRoots(self: *Interpreter, mark: usize) void {
        if (self.gc == null) return;
        self.gc_binding_reference_roots.shrinkRetainingCapacity(mark);
    }

    fn tempBindingReferenceRoot(self: *Interpreter, mark: usize, fallback: BindingReference) BindingReference {
        if (self.gc == null) return fallback;
        return self.gc_binding_reference_roots.items[mark];
    }

    fn pushOptionalBindingReferenceRoot(self: *Interpreter, reference: ?BindingReference) EvalError!?usize {
        return if (reference) |resolved| try self.pushTempBindingReferenceRoot(resolved) else null;
    }

    fn tempOptionalBindingReferenceRoot(
        self: *Interpreter,
        mark: ?usize,
        fallback: ?BindingReference,
    ) ?BindingReference {
        const reference = fallback orelse return null;
        return self.tempBindingReferenceRoot(mark.?, reference);
    }

    test "Interpreter publishes into a reserved completion root without allocating" {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        var gc_sentinel: u8 = 0;
        var machine = Interpreter{
            .arena = arena.allocator(),
            .env = undefined,
            .root_shape = undefined,
            .gc = &gc_sentinel,
        };
        const mark = try machine.pushTempRoot(Value.undef());
        defer machine.restoreTempRoots(mark);

        var no_memory: [0]u8 = .{};
        var exhausted = std.heap.FixedBufferAllocator.init(&no_memory);
        machine.arena = exhausted.allocator();
        machine.setTempRoot(mark, Value.num(42));
        try std.testing.expectEqual(@as(f64, 42), machine.tempRoot(mark, Value.undef()).asNum());
    }

    pub fn pushTempPromiseRoot(self: *Interpreter, p: *promise.Promise) EvalError!usize {
        if (self.gc == null) return 0;
        const mark = self.gc_temp_promise_roots.items.len;
        try self.gc_temp_promise_roots.append(self.arena, p);
        return mark;
    }

    pub fn tempPromiseRoot(self: *Interpreter, mark: usize, fallback: *promise.Promise) *promise.Promise {
        if (self.gc == null) return fallback;
        return self.gc_temp_promise_roots.items[mark];
    }

    pub fn restoreTempPromiseRoots(self: *Interpreter, mark: usize) void {
        if (self.gc == null) return;
        self.gc_temp_promise_roots.shrinkRetainingCapacity(mark);
    }

    /// Run a guarded mid-script collection at a step checkpoint. The Context
    /// callback owns the safety policy (GC on, no other running JS threads,
    /// conservative native-stack scan available); a no-op otherwise.
    pub fn serviceGcSafepoint(self: *Interpreter) void {
        const f = self.gc_safepoint_fn orelse return;
        const ctx = self.gc_safepoint_ctx orelse return;
        f(ctx, self);
    }

    /// Join a realm-exclusive operation only from a boundary that contains no
    /// partially evaluated JavaScript expression. The request load is the hot
    /// no-op; the callback is entered only while another mutator owns a stop.
    pub fn serviceMutatorStopSafepoint(self: *Interpreter) void {
        const request = self.mutator_stop_request orelse return;
        if (request.load(.acquire) == 0) return;
        const f = self.mutator_stop_fn orelse return;
        const ctx = self.mutator_stop_ctx orelse return;
        f(ctx, self);
    }

    /// Pin this interpreter's frozen-root state for a collector's direct read, or
    /// (from the owner thread) hold it across the `gc_parked` clear on wake. See
    /// `gc_root_lock`. A spin lock: the critical sections are short (the owner's
    /// is a single store; the collector's is one root trace of a stalled peer).
    pub fn lockGcRoots(self: *Interpreter) void {
        var spins: usize = 0;
        while (!self.gc_root_lock.tryLock()) : (spins += 1) {
            if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
        }
    }
    pub fn unlockGcRoots(self: *Interpreter) void {
        self.gc_root_lock.unlock();
    }

    /// Host cleanup jobs for FinalizationRegistry. Collection appends registries
    /// with ready records; host checkpoints deliver them through each registry's
    /// constructor callback.
    pub fn drainFinalizationCleanupJobs(self: *Interpreter) EvalError!void {
        const q = self.finalization_cleanup_jobs orelse return;
        var i: usize = 0;
        while (true) {
            // `q` is the shared realm queue: the mid-script parallel collector
            // reads it (and `queueFinalizationRegistryCleanup` appends to it)
            // under `realm_lock`, so every access to its slice header here must
            // take the same lock. Read one registry per turn under the lock, then
            // run its callback UNLOCKED — the callback executes JS that can queue
            // more jobs (re-entering this drain) or trigger a collection. The
            // check-and-clear is atomic under the lock so no append is lost.
            self.lockRealm();
            if (i >= q.items.len) {
                q.clearRetainingCapacity();
                self.unlockRealm();
                return;
            }
            const registry = q.items[i];
            i += 1;
            self.unlockRealm();
            if (!registry.behavior.is_finalization_registry) continue;
            const cb = registry.finalizationCallback();
            if (!cb.isCallable()) continue;
            // Pop each ready record (registry-internal lock); run its callback unlocked.
            while (registry.finRecordTakeReady()) |record| {
                if (self.callValue(cb, &.{record.held})) |_| {} else |err| {
                    if (err == error.Throw) {
                        self.exception = Value.undef();
                    } else return err;
                }
            }
        }
    }

    /// Event-loop tail for `Atomics.waitAsync`: while this realm has
    /// outstanding async waiters, block until tickets settle (a notify, the
    /// deadline, or group teardown), resolve their promises, and drain the
    /// reactions — repeating until none remain or none can ever settle
    /// (infinite deadline with no live agent to notify; those promises are
    /// abandoned pending, the host's prerogative). Called after the main
    /// microtask drain in Context.evaluate/evaluateModule and agent realms.
    pub fn settleAsyncWaiters(self: *Interpreter) void {
        const park_with_gil = self.use_thread_gil and self.gil != null;
        if (self.gil) |g| {
            // Quiescence loop: pumped tasks queue microtasks which can queue
            // further tasks — keep going until both are empty.
            while (true) {
                jsthread.pumpTasks(self);
                jsthread.pollPropAsync(self);
                self.drainMicrotasks() catch {};
                // A peer thread settling an asyncJoin/propAsync can `enqueue`
                // (locked append) into this shared realm queue concurrently, so
                // read its length under the same queue lock.
                self.lockMicrotasks();
                const q_empty = if (self.microtasks) |q| q.isEmpty() else true;
                self.unlockMicrotasks();
                const tasks_empty = g.tasks_queued.load(.acquire) == 0;
                if (q_empty and tasks_empty) {
                    if (jsthread.nextPropAsyncDeadline(self)) |deadline| {
                        const now = std.Io.Timestamp.now(agent.engineIo(), .awake).nanoseconds;
                        if (deadline > now) {
                            if (park_with_gil) g.release();
                            std.Io.sleep(agent.engineIo(), .fromNanoseconds(@intCast(deadline - now)), .awake) catch {};
                            if (park_with_gil) g.acquire();
                        }
                        continue;
                    }
                    break;
                }
            }
        }
        const listp = self.async_waiters orelse return;
        if (self.asyncWaiterCount(listp) == 0) return;
        const owner: *const anyopaque = @ptrCast(listp);
        var buf: [16]agent.Settled = undefined;
        while (self.asyncWaiterCount(listp) > 0) {
            // harvestAsync blocks; under a GIL the notifier needs the VM lock.
            if (park_with_gil) self.gil.?.release();
            const n = agent.harvestAsync(owner, &buf);
            if (park_with_gil) self.gil.?.acquire();
            if (n == 0) break;
            for (buf[0..n]) |s| {
                if (self.takeAsyncWaiter(listp, s.id)) |e| {
                    if (promise.promiseOf(e.promise)) |pp| {
                        const outcome: Value = if (s.outcome == .ok) Value.str("ok") else Value.str("timed-out");
                        promise.resolve(self, pp, outcome) catch {};
                    }
                }
            }
            self.drainMicrotasks() catch {};
        }
        agent.abandonAsync(owner);
        self.clearAsyncWaiters(listp);
    }

    fn evalAwait(self: *Interpreter, arg_node: *Node) EvalError!Value {
        return self.awaitValueSpec(try self.eval(arg_node));
    }

    /// `import.meta` — the surrounding module's meta-object (an ordinary
    /// extensible object with a null [[Prototype]]), created once and cached.
    pub fn importMetaValue(self: *Interpreter) EvalError!Value {
        if (self.import_meta_slot) |slot| {
            if (slot.load()) |o| {
                self.import_meta_obj = o;
                return Value.obj(o);
            }
            slot.lockInitialization();
            defer slot.init_lock.unlock();
            if (slot.load()) |o| {
                self.import_meta_obj = o;
                return Value.obj(o);
            }
            const o = try gc_mod.allocObj(self.arena);
            o.* = .{ .proto = null };
            slot.publish(o);
            self.import_meta_obj = o;
            return Value.obj(o);
        }
        if (self.import_meta_obj) |o| return Value.obj(o);
        const o = try gc_mod.allocObj(self.arena);
        o.* = .{ .proto = null };
        self.import_meta_obj = o;
        return Value.obj(o);
    }

    /// `import(specifier [, options])` — returns a promise for the module
    /// namespace. Abrupt evaluation of the specifier/options expressions throws
    /// synchronously; later coercion/validation failures reject the promise.
    fn evalImportCall(self: *Interpreter, spec_node: *Node, options_node: ?*Node, phase: []const u8) EvalError!Value {
        const specv = try self.eval(spec_node);
        const optionsv: Value = if (options_node) |on| try self.eval(on) else Value.undef();

        return self.finishImportCall(specv, optionsv, phase);
    }

    const DynamicImportJob = struct {
        hook: DynamicImportHook,
        hook_ctx: *anyopaque,
        referrer: []const u8,
        specifier: []const u8,
        phase: []const u8,
        module_type: []const u8,
        promise: *promise.Promise,
    };

    fn dynamicImportJobFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
        _ = this;
        _ = args;
        const self: *Interpreter = @ptrCast(@alignCast(ctx));
        const fnobj = self.active_native orelse return Value.undef();
        const data: *DynamicImportJob = @ptrCast(@alignCast(fnobj.private_data.?));
        var out: Value = Value.undef();
        switch (data.hook(data.hook_ctx, self, data.referrer, data.specifier, data.phase, data.module_type, &out, data.promise)) {
            .success => try promise.resolve(self, data.promise, out),
            .pending => {},
            .failure => try promise.reject(self, data.promise, self.exception),
        }
        return Value.undef();
    }

    /// Finish `import(specifier [, options])` after the argument expressions have
    /// already evaluated. Shared by the tree-walker and the bytecode VM so a
    /// `yield` inside a generator argument suspends before the import promise is
    /// created, while later coercion/validation failures still reject it.
    pub fn finishImportCall(self: *Interpreter, specv: Value, optionsv: Value, phase: []const u8) EvalError!Value {
        const pobj = try promise.newPromise(self);
        const p = promise.promiseOf(Value.obj(pobj)).?;
        const spec = self.toStringV(specv) catch {
            try promise.reject(self, p, self.exception);
            return Value.obj(pobj);
        };
        // EvaluateImportCall steps 10-11: validate the options/import-attributes
        // argument. A non-undefined options that is not an Object, a non-Object
        // `with`, or a non-String attribute value all reject with a TypeError.
        // (Attributes are otherwise ignored — every module is the host's source.)
        const module_type = self.validateImportOptions(optionsv) catch {
            try promise.reject(self, p, self.exception);
            return Value.obj(pobj);
        };
        // Resolve+load the module from the PromiseJobs queue. Argument
        // evaluation/coercion above is immediate, but the module graph itself
        // cannot preempt the currently evaluating module.
        if (self.dyn_import) |f| {
            const data = try self.arena.create(DynamicImportJob);
            data.* = .{
                .hook = f,
                .hook_ctx = self.dyn_import_ctx.?,
                .referrer = self.cur_module,
                .specifier = spec,
                .phase = phase,
                .module_type = module_type,
                .promise = p,
            };
            const job = try gc_mod.allocObj(self.arena);
            job.* = .{ .native = dynamicImportJobFn, .private_data = @ptrCast(data) };
            try installNativeProps(self.arena, self.root_shape, job, "", 1);
            const tick_obj = try promise.newPromise(self);
            const tick = promise.promiseOf(Value.obj(tick_obj)).?;
            _ = try promise.then(self, tick, Value.obj(job), Value.undef());
            try promise.resolve(self, tick, Value.undef());
        } else {
            const err = try self.makeError("TypeError", "dynamic import is not available in this context");
            try promise.reject(self, p, err);
        }
        return Value.obj(pobj);
    }

    /// Validate the second argument of `import(specifier, options)` per
    /// EvaluateImportCall: options (when present) must be an Object; its `with`
    /// attribute (when present) must be an Object whose every own enumerable
    /// value is a String. Throws a TypeError otherwise. Returns the `type`
    /// attribute value when present.
    fn validateImportOptions(self: *Interpreter, options: Value) EvalError![]const u8 {
        if (options.isUndefined()) return "";
        if (!options.isObject() or options.asObj().is_symbol or options.asObj().is_bigint)
            return self.throwError("TypeError", "import() options must be an object");
        const attrs = try self.getProperty(options, "with");
        if (attrs.isUndefined()) return "";
        if (!attrs.isObject() or attrs.asObj().is_symbol or attrs.asObj().is_bigint)
            return self.throwError("TypeError", "import() 'with' attributes must be an object");
        var module_type: []const u8 = "";
        const attrs_obj = attrs.asObj();
        const keys = try self.objectOwnKeysList(attrs_obj);
        for (keys) |k| {
            if (value.isSymbolKey(k)) continue;
            if (!try self.objectProtoPropertyIsEnumerable(attrs_obj, k)) continue;
            const v = try self.getProperty(attrs, k);
            if (!v.isString()) return self.throwError("TypeError", "import attribute values must be strings");
            if (std.mem.eql(u8, k, "type")) module_type = v.asStr();
        }
        return module_type;
    }

    /// `await v` on an already-evaluated value (synchronous-settling): perform
    /// Await's `PromiseResolve(%Promise%, v)` step, then drive the microtask
    /// queue until the promise settles and return its value (or throw its
    /// rejection). The PromiseResolve step is observable for promises through a
    /// `.constructor` lookup and assimilates thenables exactly once.
    pub fn awaitValue(self: *Interpreter, v: Value) EvalError!Value {
        const wrapped = try promiseResolveValue(self, v);
        const p = promise.promiseOf(wrapped).?;
        return self.awaitPromiseSettledValue(p);
    }

    fn runOneMicrotask(self: *Interpreter) EvalError!bool {
        if (self.microtaskDequeue()) |job| {
            self.current_microtask = job;
            promise.runJob(self, &self.current_microtask.?) catch |err| {
                self.current_microtask = null;
                return err;
            };
            self.current_microtask = null;
            return true;
        }
        return false;
    }

    /// Spec-facing `await`: Await always resumes through the PromiseJobs queue,
    /// even when the wrapped value is already fulfilled. Run one queued job before
    /// observing the wrapped promise's state, then use the legacy settling loop
    /// for pending promises.
    pub fn awaitValueSpec(self: *Interpreter, v: Value) EvalError!Value {
        const wrapped = try promiseResolveValue(self, v);
        const p = promise.promiseOf(wrapped).?;
        _ = try self.runOneMicrotask();
        return self.awaitPromiseSettledValue(p);
    }

    fn awaitPromiseSettledValue(self: *Interpreter, p: *promise.Promise) EvalError!Value {
        while (promise.snapshot(p).state == .pending) {
            if (try self.runOneMicrotask()) {
                continue;
            }
            if (self.microtasks == null) break;
            // Threads mode: another thread can settle this shared promise
            // (asyncJoin, cross-thread resolve, asyncHold task delivery). In
            // serialized mode the current interpreter owns the context GIL and
            // must hand it over while waiting. Under `parallel_js`, the GIL
            // object still exists for bookkeeping but this interpreter does not
            // hold it, so yielding is enough after pumping realm tasks.
            if (self.gil) |g| {
                jsthread.pumpTasks(self);
                jsthread.pollPropAsync(self); // expire property waitAsync deadlines
                if (self.use_thread_gil) {
                    g.release();
                    std.Thread.yield() catch {};
                    g.acquire();
                } else {
                    std.Thread.yield() catch {};
                }
                continue;
            }
            if (self.async_waiters) |waiters| {
                if (self.asyncWaiterCount(waiters) > 0) {
                    self.settleAsyncWaiters();
                    continue;
                }
            }
            break; // nothing left to settle it
        }
        const done = promise.snapshot(p);
        return switch (done.state) {
            .fulfilled => done.value,
            .rejected => blk: {
                self.exception = done.value;
                break :blk error.Throw;
            },
            .pending => Value.undef(), // never settled synchronously
        };
    }

    /// A BigInt primitive value with the given `i128` magnitude.
    pub fn makeBigInt(self: *Interpreter, v: i128) EvalError!Value {
        const o = try gc_mod.allocObj(self.arena);
        o.* = .{ .is_bigint = true };
        try o.setPrimitiveState(self.arena, .{ .bigint = .{ .value = v } });
        try self.finishBigInt(o);
        return Value.obj(o);
    }

    /// Create a fresh Symbol primitive linked to this realm's live
    /// Symbol.prototype. The description storage must already outlive the
    /// returned value (callers normally duplicate it into the realm arena).
    pub fn makeSymbol(self: *Interpreter, description: ?[]const u8) EvalError!Value {
        const symbol = try makeSymbolObj(self.arena, self.root_shape, description, symbolProto(self));
        _ = self.registerSymbol(symbol.asObj());
        return symbol;
    }

    pub fn makeBigIntText(self: *Interpreter, s: []const u8) EvalError!Value {
        if (std.fmt.parseInt(i128, s, 10)) |v| return self.makeBigInt(v) else |_| {}
        const o = try gc_mod.allocObj(self.arena);
        o.* = .{ .is_bigint = true };
        try o.setPrimitiveState(self.arena, .{ .bigint = .{ .text = .init(s) } });
        try self.finishBigInt(o);
        return Value.obj(o);
    }

    pub fn makeBigIntFromNumber(self: *Interpreter, n: f64) EvalError!Value {
        var managed = try std.math.big.int.Managed.init(self.arena);
        const limb_bits = @bitSizeOf(std.math.big.Limb);
        try managed.ensureCapacity((1076 + limb_bits - 1) / limb_bits);
        var mutable = managed.toMutable();
        _ = mutable.setFloat(n, .trunc);
        managed.setMetadata(mutable.positive, mutable.len);
        return makeBigIntFromManaged(self, &managed);
    }

    fn finishBigInt(self: *Interpreter, o: *value.Object) EvalError!void {
        if (self.env.get("BigInt")) |c| {
            if (c.isObject()) o.setProtoAtomic(try self.protoObject(c.asObj()));
        }
    }

    /// ToBigInt(v): a boolean/number(integer)/string/BigInt converts; a
    /// non-integer Number is a RangeError; null/undefined/Symbol a TypeError.
    /// ToBigInt(v) (`number_ok = false`) or the `BigInt(v)` constructor's
    /// NumberToBigInt (`number_ok = true`). The only difference is a Number
    /// argument: ToBigInt rejects it (TypeError), while the constructor converts
    /// an integral Number to the matching BigInt.
    pub fn toBigIntValue(self: *Interpreter, v: Value) EvalError!Value {
        return self.toBigIntValueImpl(v, false);
    }

    pub fn toBigIntValueImpl(self: *Interpreter, v: Value, number_ok: bool) EvalError!Value {
        switch (v.kind()) {
            .object => {
                const o = v.asObj();
                if (o.is_bigint) return v;
                if (o.is_symbol) return self.throwError("TypeError", "Cannot convert a Symbol value to a BigInt");
                const p = try self.toPrimitive(v, .number);
                if (p.isObject() and !p.asObj().is_bigint and !p.asObj().is_symbol) return self.throwError("TypeError", "Cannot convert object to a BigInt");
                return self.toBigIntValueImpl(p, number_ok);
            },
            .boolean => return self.makeBigInt(if (v.asBool()) 1 else 0),
            .number => {
                const n = v.asNum();
                if (!number_ok) return self.throwError("TypeError", "Cannot convert a Number to a BigInt; use BigInt()");
                if (std.math.isNan(n) or std.math.isInf(n) or @trunc(n) != n)
                    return self.throwError("RangeError", "The number is not a safe integer");
                const i128_limit = std.math.pow(f64, 2.0, 127.0);
                if (n >= i128_limit or n < -i128_limit) return self.makeBigIntFromNumber(n);
                return self.makeBigInt(@intFromFloat(n));
            },
            .string => {
                const s = try v.asWtf8(self.arena);
                return self.makeBigIntText((try canonicalStringToBigInt(self.arena, s)) orelse
                    return self.throwError("SyntaxError", "Cannot convert string to a BigInt"));
            },
            .null, .undefined => return self.throwError("TypeError", "Cannot convert undefined or null to a BigInt"),
        }
    }

    /// Box a primitive into a wrapper object (`new Number/String/Boolean`). Its
    /// prototype is the in-flight constructor's `.prototype`, so methods,
    /// `instanceof`, and `[object Number|String|Boolean]` all resolve correctly.
    pub fn makeWrapper(self: *Interpreter, p: Value) EvalError!Value {
        const o = try gc_mod.allocObj(self.arena);
        o.* = .{};
        try o.setBoxedPrimitive(self.arena, p);
        if (self.new_target.isObject()) {
            const intrinsic: []const u8 = switch (p.kind()) {
                .string => "String",
                .number => "Number",
                .boolean => "Boolean",
                else => "Object",
            };
            o.setProtoAtomic(try self.ctorRealmIntrinsicProto(self.new_target.asObj(), intrinsic));
        }
        return Value.obj(o);
    }

    /// Create an instance for `new ctor(...)`: a fresh object whose prototype is
    /// the constructor's `.prototype`.
    pub fn newInstance(self: *Interpreter, ctor: *value.Object) EvalError!Value {
        const obj = try gc_mod.allocObj(self.arena);
        obj.* = .{ .proto = try self.protoObject(ctor) };
        try obj.setCtorRef(self.arena, ctor);
        return Value.obj(obj);
    }

    /// Allocate a fresh array object.
    pub fn newArray(self: *Interpreter) EvalError!Value {
        return self.newArrayWithProto(null);
    }

    fn newArrayWithProto(self: *Interpreter, proto: ?*value.Object) EvalError!Value {
        const obj = try gc_mod.allocObj(self.arena);
        obj.* = .{ .is_array = true, .proto = proto orelse self.arrayProto() };
        return Value.obj(obj);
    }

    fn newArrayInRealm(self: *Interpreter, env: *Environment) EvalError!Value {
        const obj = try gc_mod.allocObj(self.arena);
        const proto: ?*value.Object = blk: {
            const av = env.get("Array") orelse break :blk null;
            if (!av.isObject()) break :blk null;
            const p = av.asObj().getOwn("prototype") orelse break :blk null;
            break :blk if (p.isObject()) p.asObj() else null;
        };
        obj.* = .{ .is_array = true, .proto = proto };
        return Value.obj(obj);
    }

    /// ArrayCreate(length): allocate a fresh array with a logical length.
    pub fn newArrayWithLength(self: *Interpreter, len: usize) EvalError!Value {
        if (len > 4294967295) return self.throwError("RangeError", "Invalid array length");
        const arr = try self.newArray();
        try arr.asObj().extendArrayLengthFloor(self.arena, len);
        return arr;
    }

    /// JSC's private JSArray::putDirectIndex boundary: define/replace an own
    /// indexed value without running prototype setters. Dense nearby writes
    /// preserve holes; distant writes use sparse own storage and advance length.
    pub fn putArrayDirectIndex(self: *Interpreter, array: *value.Object, index: u32, out: Value) EvalError!void {
        if (!array.is_array) return;
        const i: usize = index;
        const dense_cap: usize = 1 << 24;
        const dense_len = array.elementsLen();
        if (i < dense_cap and i <= dense_len + 1024) {
            _ = try array.growDenseElement(self.arena, i, out);
            return;
        }
        if (index < std.math.maxInt(u32))
            try array.extendArrayLengthFloor(self.arena, i + 1);
        var key_storage: [32]u8 = undefined;
        const key = borrowedIndexKey(&key_storage, index);
        try self.setProp(array, key, out);
    }

    pub fn pushArrayDirect(self: *Interpreter, array: *value.Object, out: Value) EvalError!void {
        if (!array.is_array) return;
        const len = array.arrayLength();
        if (len >= std.math.maxInt(u32))
            return self.throwError("RangeError", "Invalid array length");
        try self.putArrayDirectIndex(array, @intCast(len), out);
    }

    pub fn getDirectIndex(self: *Interpreter, object: *value.Object, index: u32) EvalError!?Value {
        _ = self;
        if (object.denseElement(index)) |direct| return direct;
        var key_storage: [32]u8 = undefined;
        const key = borrowedIndexKey(&key_storage, index);
        return object.getOwn(key);
    }

    fn newArrayWithLengthInRealm(self: *Interpreter, env: *Environment, len: usize) EvalError!Value {
        if (len > 4294967295) return self.throwError("RangeError", "Invalid array length");
        const arr = try self.newArrayInRealm(env);
        try arr.asObj().extendArrayLengthFloor(self.arena, len);
        return arr;
    }

    /// `Array.prototype`, resolved from the live `Array` binding, so array
    /// instances inherit from it (inherited index access, `in`, iteration over
    /// inherited indices). Null only before globals are installed.
    fn arrayProto(self: *Interpreter) ?*value.Object {
        const av = self.env.get("Array") orelse return null;
        if (!av.isObject()) return null;
        const p = av.asObj().getOwn("prototype") orelse return null;
        return if (p.isObject()) p.asObj() else null;
    }

    /// `%Object.prototype%`, the [[Prototype]] of an ordinary plain object.
    /// Resolve it once from the realm during bootstrap/first use, then retain
    /// the intrinsic identity even if user code shadows or replaces the global
    /// `Object` binding. Null only during the early bootstrap window before
    /// `Object` is installed; those intrinsics wire their prototypes explicitly.
    pub fn objectProto(self: *Interpreter) ?*value.Object {
        var realm = self.env;
        while (realm.parent) |parent| realm = parent;
        const read_locked = realm.lockBindingsForRead();
        if (realm.object_proto_intrinsic) |cached| {
            realm.unlockBindingsForRead(read_locked);
            return cached;
        }
        realm.unlockBindingsForRead(read_locked);

        const ov = realm.get("Object") orelse return null;
        if (!ov.isObject()) return null;
        const p = ov.asObj().getOwn("prototype") orelse return null;
        if (!p.isObject()) return null;
        const intrinsic = p.asObj();
        gc_mod.barrierCellFrom(realm, @ptrCast(intrinsic));
        const write_locked = realm.lockBindingsForWrite();
        if (realm.object_proto_intrinsic == null) realm.object_proto_intrinsic = intrinsic;
        const cached = realm.object_proto_intrinsic;
        realm.unlockBindingsForWrite(write_locked);
        return cached;
    }

    /// The shared `%ThrowTypeError%` intrinsic, stashed as the get/set of
    /// `Function.prototype.caller` during setup — reused by the strict
    /// `arguments.callee` and `arguments.caller` poison-pill accessors.
    pub fn throwTypeError(self: *Interpreter) ?*value.Object {
        if (self.env.get("\x00ThrowTypeError")) |v| {
            if (v.isObject()) return v.asObj();
        }
        const fp = self.functionProto() orelse return null;
        const acc = fp.getAccessor("caller") orelse return null;
        if (acc.get) |g| if (g.isObject()) return g.asObj();
        return null;
    }

    /// `Function.prototype`, the [[Prototype]] of every function object — so
    /// `fn instanceof Function`, `Object.getPrototypeOf(fn)`, and inherited
    /// `call`/`apply`/`bind`/`toString` all resolve through the chain.
    pub fn functionProto(self: *Interpreter) ?*value.Object {
        const fv = self.env.get("Function") orelse return null;
        if (!fv.isObject()) return null;
        const p = fv.asObj().getOwn("prototype") orelse return null;
        return if (p.isObject()) p.asObj() else null;
    }

    /// `{ ...src }` CopyDataProperties: copy `src`'s own enumerable properties /
    /// array elements into `target` (a string spreads its chars by index).
    /// Shared by the tree-walker object literal and the VM `init_spread` op.
    pub fn spreadDataProps(self: *Interpreter, target: Value, src: Value) EvalError!void {
        switch (src.kind()) {
            .object => {
                const so = src.asObj();
                // A Proxy source must go through [[OwnPropertyKeys]] then, per key,
                // [[GetOwnProperty]] — invoking the `ownKeys` and
                // `getOwnPropertyDescriptor` traps in order (and reading only
                // enumerable keys via Get) rather than its empty raw key set.
                if (so.proxyHandler() != null or so.proxy_revoked) {
                    for (try self.objectOwnKeysList(so)) |k| {
                        if (value.isPrivateKey(k)) continue;
                        const desc = try builtins.objectGetOwnPropertyDescriptor(self, Value.undef(), &.{ src, try self.keyToValue(k) });
                        if (!(desc.isObject() and (try self.getProperty(desc, "enumerable")).toBoolean())) continue;
                        try self.setMember(target, k, try self.getProperty(src, k));
                    }
                    return;
                }
                if (so.is_array) {
                    for (try self.objectOwnKeysList(so)) |k| {
                        if (value.isPrivateKey(k)) continue;
                        const desc = try builtins.objectGetOwnPropertyDescriptor(self, Value.undef(), &.{ src, try self.keyToValue(k) });
                        if (!(desc.isObject() and (try self.getProperty(desc, "enumerable")).toBoolean())) continue;
                        try self.setMember(target, k, try self.getProperty(src, k));
                    }
                    return;
                }
                // [[OwnPropertyKeys]] (not just `ownKeys`): integer-indexed dense
                // elements live outside the shape's key order, so a `{ ...src }`
                // where `src.0` was set via `src[0]=…` would otherwise drop it.
                for (try self.objectOwnKeysList(so)) |k| {
                    if (value.isPrivateKey(k)) continue;
                    if (!so.getAttr(k).enumerable) continue;
                    try self.setMember(target, k, try self.getProperty(src, k));
                }
            },
            .string => {
                var code_units = StringCodeUnitIterator.initValue(src);
                var i: usize = 0;
                while (code_units.next()) |cu| : (i += 1)
                    try self.setMember(target, try std.fmt.allocPrint(self.arena, "{d}", .{i}), try self.stringValueFromCodeUnit(cu.unit));
            },
            else => {}, // null/undefined/number/boolean spread → no own enumerable props
        }
    }

    /// Install an object-literal getter/setter (the VM `init_getter`/`init_setter`
    /// ops). Mirrors the `.get`/`.set` arms of `evalObjectLit`.
    pub fn vmInitAccessor(self: *Interpreter, obj: Value, key: Value, fn_val: Value, is_get: bool) EvalError!void {
        const k = try self.keyOf(key);
        const name = try self.keyDisplayName(key);
        if (funcOf(fn_val)) |f| f.home_object = obj.asObj();
        try self.nameAccessor(fn_val, if (is_get) "get" else "set", name);
        if (is_get)
            try self.defineAccessor(obj.asObj(), k, fn_val, null)
        else
            try self.defineAccessor(obj.asObj(), k, null, fn_val);
    }

    fn evalObjectLit(self: *Interpreter, props: []ast.Property) EvalError!Value {
        const v = try self.newObject();
        for (props) |p| {
            if (p.is_spread) {
                const src = try self.eval(p.value);
                try self.spreadDataProps(v, src);
                continue;
            }
            // ToPropertyKey ONCE (its valueOf/@@toPrimitive runs a single time);
            // keyOf and keyDisplayName then read the resulting primitive without
            // re-coercing.
            const kv: ?Value = if (p.key_expr) |ke| try self.toPropertyKeyValue(try self.eval(ke)) else null;
            const key = if (kv) |k| try self.keyOf(k) else try value.encodeStringKey(self.arena, p.key);
            // The name a method/accessor takes from this key (a symbol shows as
            // `[description]`, not its internal key).
            const name_str = if (kv) |k| try self.keyDisplayName(k) else p.key;
            switch (p.accessor) {
                .none => {
                    const pv = try self.eval(p.value);
                    if (p.proto_setter) { // only the `__proto__: value` colon form
                        // Only an Object or null sets [[Prototype]]; any other
                        // value (incl. a Symbol/BigInt, which are object-tagged) is
                        // discarded without creating an own `__proto__` property.
                        if (builtins.isRealObject(pv)) v.asObj().proto = pv.asObj();
                        if (pv.isNull()) v.asObj().proto = null;
                        continue;
                    }
                    // A concise method's [[HomeObject]] is the object being built,
                    // so `super` inside it resolves on the object's prototype.
                    if (p.value.* == .function and p.value.function.is_method)
                        if (funcOf(pv)) |f| {
                            f.home_object = v.asObj();
                        };
                    try self.maybeNameAnon(pv, p.value, name_str); // `{ x: function(){} }` ⇒ name "x"
                    try self.defineLiteralDataProp(v.asObj(), key, pv);
                },
                .get => {
                    const gv = try self.eval(p.value);
                    if (funcOf(gv)) |f| f.home_object = v.asObj();
                    try self.nameAccessor(gv, "get", name_str);
                    try self.defineAccessor(v.asObj(), key, gv, null);
                },
                .set => {
                    const sv = try self.eval(p.value);
                    if (funcOf(sv)) |f| f.home_object = v.asObj();
                    try self.nameAccessor(sv, "set", name_str);
                    try self.defineAccessor(v.asObj(), key, null, sv);
                },
            }
        }
        return v;
    }

    /// Build a `RegExp` instance with `source`/`flags`/`lastIndex` and the
    /// `global`/`ignoreCase`/`multiline` booleans. Matching (test/exec) is
    /// dispatched in `regexMethod`, backed by zig-regex.
    pub fn regexpPrototypeFromNewTarget(self: *Interpreter) EvalError!?*value.Object {
        if (self.new_target.isObject()) {
            const p = try self.getProperty(self.new_target, "prototype");
            if (p.isObject() and !p.asObj().is_symbol and !p.asObj().is_bigint) return p.asObj();
        }
        return null;
    }

    fn makeRegexWithConstructorTarget(self: *Interpreter, pattern: []const u8, flags: []const u8, constructor_target: ?*value.Object) EvalError!Value {
        try self.validateRegExpFlags(flags);
        const o = (try self.newObject()).asObj();
        o.behavior.is_regex = true;
        // An empty pattern's [[OriginalSource]] is "(?:)" (so `//`, `new RegExp()`,
        // `new RegExp("")` all match the empty string and report that source).
        const source = if (pattern.len == 0) "(?:)" else pattern;
        // source / flags live in internal slots; `lastIndex` is the one real own
        // data property (writable). source/flags/global/… resolve via the
        // RegExp.prototype accessor getters.
        const regex_state = try o.ensureRegexState(self.arena);
        regex_state.source = try self.arena.dupe(u8, source);
        regex_state.flags = try self.arena.dupe(u8, flags);
        try self.setProp(o, "lastIndex", Value.num(0));
        try o.setAttr(self.arena, "lastIndex", .{ .writable = true, .enumerable = false, .configurable = false });
        if (constructor_target) |target| {
            // GetPrototypeFromConstructor: new.target.prototype, or new.target's
            // realm's %RegExp.prototype% when that is not an Object.
            o.setProtoAtomic(try self.ctorRealmIntrinsicProto(target, "RegExp"));
        } else if (self.env.get("RegExp")) |c| {
            if (c.isObject()) o.setProtoAtomic(try self.protoObject(c.asObj()));
        }
        // Eagerly compile to validate the pattern — RegExp construction reports a
        // SyntaxError for an invalid pattern (the compiled form is discarded;
        // methods recompile on demand).
        _ = try self.compileRegex(o);
        return Value.obj(o);
    }

    /// RegExpCreate and a RegularExpressionLiteral always allocate from the
    /// current realm's intrinsic. An enclosing constructor's `new.target` is
    /// unrelated and must not become the literal/internal RegExp prototype.
    pub fn makeRegex(self: *Interpreter, pattern: []const u8, flags: []const u8) EvalError!Value {
        return self.makeRegexWithConstructorTarget(pattern, flags, null);
    }

    /// RegExp constructor allocation uses its actual `new.target` when invoked
    /// with `new`; a plain call falls back to the current realm intrinsic.
    pub fn makeRegexFromConstructor(self: *Interpreter, pattern: []const u8, flags: []const u8) EvalError!Value {
        return self.makeRegexWithConstructorTarget(
            pattern,
            flags,
            if (self.new_target.isObject()) self.new_target.asObj() else null,
        );
    }

    fn validateRegExpFlags(self: *Interpreter, flags: []const u8) EvalError!void {
        // Each flag must be one of `dgimsuvy` with no duplicates. `u` and `v` are
        // mutually exclusive.
        var seen = std.mem.zeroes([128]bool);
        for (flags) |f| {
            if (f >= 128 or std.mem.indexOfScalar(u8, "dgimsuvy", f) == null or seen[f])
                return self.throwError("SyntaxError", "Invalid regular expression flags");
            seen[f] = true;
        }
        if (seen['u'] and seen['v']) return self.throwError("SyntaxError", "Invalid regular expression flags");
    }

    fn setRegExpLastIndexValue(self: *Interpreter, o: *value.Object, v: Value) EvalError!void {
        if (o.getOwn("lastIndex") != null and !o.getAttr("lastIndex").writable)
            return self.throwError("TypeError", "Cannot assign to read only property 'lastIndex'");
        try self.setProp(o, "lastIndex", v);
    }

    fn setRegExpLastIndex(self: *Interpreter, o: *value.Object, n: f64) EvalError!void {
        try self.setRegExpLastIndexValue(o, Value.num(n));
    }

    fn compileRegex(self: *Interpreter, o: *value.Object) EvalError!*regex.Regex {
        if (o.regexCompiled()) |cached| return @ptrCast(@alignCast(cached));
        const raw_src = o.regexSource();
        const flags = o.regexFlags();
        const unicode = std.mem.indexOfScalar(u8, flags, 'u') != null or std.mem.indexOfScalar(u8, flags, 'v') != null;
        const scratch = self.scratch_allocator orelse self.arena;
        const normalized = if (unicode)
            regexp_compat.NormalizedPattern.borrowed(raw_src)
        else
            try regexp_compat.normalizeAnnexBClassRanges(scratch, raw_src);
        defer normalized.deinit(scratch);
        const compat_src = normalized.bytes;
        const src = if (unicode) compat_src else try self.regexpSearchInput(compat_src, false);
        const cf = regex.common.CompileFlags{
            .case_insensitive = std.mem.indexOfScalar(u8, flags, 'i') != null,
            .multiline = std.mem.indexOfScalar(u8, flags, 'm') != null,
            // `s` (dotAll): `.` also matches line terminators.
            .dot_all = std.mem.indexOfScalar(u8, flags, 's') != null,
            // `u`/`v` (unicode): pattern is interpreted as Unicode code points
            // (enables `\u{...}` and code-point-aware classes in the engine).
            .unicode = unicode,
            .unicode_sets = std.mem.indexOfScalar(u8, flags, 'v') != null,
            .ecmascript = true,
        };
        const compiled = try self.arena.create(regex.Regex);
        compiled.* = regex.Regex.compileWithFlags(self.arena, src, cf) catch
            return self.throwError("SyntaxError", "invalid regular expression");
        const regex_state = try o.ensureRegexState(self.arena);
        regex_state.compiled = @ptrCast(compiled);
        return compiled;
    }

    fn regexMatcher(self: *Interpreter, re: *regex.Regex) EvalError!*regex.Regex.Matcher {
        const entry = try self.regex_matchers.getOrPut(self.arena, re);
        if (!entry.found_existing) entry.value_ptr.* = re.matcher();
        return entry.value_ptr;
    }

    /// Whether `o` is the `%RegExp.prototype%` intrinsic (which the source/flags
    /// accessors special-case: they return "(?:)" / "" / undefined rather than
    /// throwing).
    fn isRegExpProto(self: *Interpreter, o: *value.Object) bool {
        if (self.env.get("RegExp")) |c| if (c.isObject()) {
            if (c.asObj().getOwn("prototype")) |p| if (p.isObject()) return p.asObj() == o;
        };
        return false;
    }

    fn regexMethod(self: *Interpreter, o: *value.Object, name: []const u8, args: []const Value) EvalError!?Value {
        if (eq(name, "test")) {
            return Value.boolVal(try self.regexpTestBuiltin(o, arg0(args)));
        }
        if (eq(name, "compile")) {
            if (regExpAccessorData(self)) |data| {
                if (o.protoAtomic() != data.proto)
                    return throwErrorInRealm(self, data.realm, "TypeError", "RegExp.prototype.compile called on an incompatible RegExp");
            }
            var pattern: []const u8 = "";
            var flags: []const u8 = "";
            const pattern_v = if (args.len > 0) args[0] else Value.undef();
            const flags_v = if (args.len > 1) args[1] else Value.undef();
            if (pattern_v.isObject() and pattern_v.asObj().behavior.is_regex) {
                if (!flags_v.isUndefined()) return self.throwError("TypeError", "flags supplied with a RegExp pattern");
                pattern = pattern_v.asObj().regexSource();
                flags = pattern_v.asObj().regexFlags();
            } else {
                if (!pattern_v.isUndefined()) pattern = try self.toStringWtf8(pattern_v);
                if (!flags_v.isUndefined()) flags = try self.toStringWtf8(flags_v);
            }
            try self.validateRegExpFlags(flags);
            const source = if (pattern.len == 0) "(?:)" else pattern;
            const old_source = o.regexSource();
            const old_flags = o.regexFlags();
            const old_compiled = o.regexCompiled();
            const regex_state = try o.ensureRegexState(self.arena);
            regex_state.source = try self.arena.dupe(u8, source);
            regex_state.flags = try self.arena.dupe(u8, flags);
            regex_state.compiled = null;
            _ = self.compileRegex(o) catch |err| {
                regex_state.source = old_source;
                regex_state.flags = old_flags;
                regex_state.compiled = old_compiled;
                return err;
            };
            try self.setRegExpLastIndex(o, 0);
            return Value.obj(o);
        }
        if (eq(name, "exec")) {
            const src = arg0(args);
            // The regex engine scans `input` as WTF-8, so a flat-latin1 subject
            // cell must be re-encoded (not read as its raw 1-byte-per-unit image).
            const input = try self.toStringWtf8(src);
            // ASCII input ⇒ byte offset == UTF-16 index, so the conversions below
            // are O(1) and this exec-in-a-loop stays O(n) overall (see isAscii).
            // The flag is cached on the source string's cell; a coerced non-string
            // has no cell, so fall back to the O(n) walk (false).
            const ascii = src.isString() and src.strIsAscii();
            // RegExpBuiltinExec always reads/coerces `lastIndex`; it only uses it
            // as the search start for global/sticky regexps.
            const li = toLen(try self.toNumberV(try self.getProperty(Value.obj(o), "lastIndex")));
            const flags = o.regexFlags();
            const global = std.mem.indexOfScalar(u8, flags, 'g') != null;
            const sticky = std.mem.indexOfScalar(u8, flags, 'y') != null;
            const unicode = std.mem.indexOfScalar(u8, flags, 'u') != null or std.mem.indexOfScalar(u8, flags, 'v') != null;
            // ASCII has no astral chars, so regexpSearchInput would rescan O(n)
            // only to return `input` unchanged — skip it so exec-in-a-loop is O(n).
            const search_input = if (ascii) input else try self.regexpSearchInput(input, unicode);
            const start_units = if (global or sticky) li else 0;
            if (start_units > utf16LenOfStringA(input, ascii)) {
                if (global or sticky) try self.setRegExpLastIndex(o, 0);
                return Value.nul();
            }
            const start = byteOffsetForUtf16IndexA(search_input, start_units, ascii);
            const re = try self.compileRegex(o);
            const matcher = try self.regexMatcher(re);
            const found = regex.Regex.Matcher.findFrom(matcher, search_input, start) catch null;
            if (found) |match| {
                var m = match;
                defer m.deinit(self.arena);
                // Sticky matches must begin exactly at lastIndex.
                if (sticky and m.start != start) {
                    try self.setRegExpLastIndex(o, 0);
                    return Value.nul();
                }
                const mstart = m.start;
                const mend = m.end;
                if (global or sticky) try self.setRegExpLastIndex(o, @floatFromInt(utf16IndexForByteOffsetA(search_input, mend, ascii)));
                // Borrowed legacy slices + reuse of the source string cell avoid an
                // O(n) input/context copy per call, so exec-in-a-loop stays O(n)
                // (search_input is arena/cell lifetime — same as the fast path).
                recordRegexpLegacyBorrowed(self, search_input, mstart, mend, m.captures);
                const arr = try self.newArray();
                try arr.asObj().appendElement(self.arena, try Value.strAlloc(self.arena, try self.stringSliceFromSearchSpan(input, search_input, mstart, mend)));
                for (0..m.captures.len) |i| try arr.asObj().appendElement(self.arena, try self.captureValSpan(m, i, input, search_input));
                try self.setProp(arr.asObj(), "index", Value.num(@floatFromInt(utf16IndexForByteOffsetA(search_input, mstart, ascii))));
                try self.setProp(arr.asObj(), "input", if (src.isString()) src else try Value.strAlloc(self.arena, input));
                const groups = try self.regexGroupsSpan(re, m, input, search_input);
                try self.setProp(arr.asObj(), "groups", if (groups) |g| Value.obj(g) else Value.undef());
                // The `d` (hasIndices) flag adds a parallel match-indices array.
                if (std.mem.indexOfScalar(u8, flags, 'd') != null)
                    try self.setProp(arr.asObj(), "indices", Value.obj(try self.makeIndicesArray(re, m, search_input, 0)));
                return arr;
            }
            if (global or sticky) try self.setRegExpLastIndex(o, 0);
            return Value.nul();
        }
        if (eq(name, "toString")) {
            return try self.regexpToString(Value.obj(o));
        }
        return null;
    }

    pub fn regexpTestBuiltin(self: *Interpreter, o: *value.Object, input_arg: Value) EvalError!bool {
        const input = try self.toStringWtf8(input_arg);
        const ascii = input_arg.isString() and input_arg.strIsAscii();
        const li = toLen(try self.toNumberV(try self.getProperty(Value.obj(o), "lastIndex")));
        const flags = o.regexFlags();
        const global = std.mem.indexOfScalar(u8, flags, 'g') != null;
        const sticky = std.mem.indexOfScalar(u8, flags, 'y') != null;
        const unicode = std.mem.indexOfScalar(u8, flags, 'u') != null or std.mem.indexOfScalar(u8, flags, 'v') != null;
        // ASCII has no astral chars, so regexpSearchInput would rescan O(n) only to
        // return `input` unchanged — skip it so test-in-a-loop is O(n).
        const search_input = if (ascii) input else try self.regexpSearchInput(input, unicode);
        const start_units = if (global or sticky) li else 0;
        if (start_units > utf16LenOfStringA(input, ascii)) {
            if (global or sticky) try self.setRegExpLastIndex(o, 0);
            return false;
        }
        const start = byteOffsetForUtf16IndexA(search_input, start_units, ascii);
        const re = try self.compileRegex(o);
        const matcher = try self.regexMatcher(re);
        const found = regex.Regex.Matcher.findFrom(matcher, search_input, start) catch null;
        if (found) |match| {
            var m = match;
            defer m.deinit(self.arena);
            if (sticky and m.start != start) {
                try self.setRegExpLastIndex(o, 0);
                return false;
            }
            if (global or sticky) try self.setRegExpLastIndex(o, @floatFromInt(utf16IndexForByteOffsetA(search_input, m.end, ascii)));
            // Borrowed legacy slices avoid an O(n) copy per call → test-in-a-loop
            // is O(n) (search_input is arena/cell lifetime, same as the fast path).
            recordRegexpLegacyBorrowed(self, search_input, m.start, m.end, m.captures);
            return true;
        }
        if (global or sticky) try self.setRegExpLastIndex(o, 0);
        return false;
    }

    /// RegExpExec(R, S): use a callable `exec` method when present, validate its
    /// result, otherwise fall back to the built-in matcher only for true RegExp
    /// instances.
    fn regexpExecGeneric(self: *Interpreter, rx: Value, s: []const u8) EvalError!Value {
        if (!rx.isObject()) return self.throwError("TypeError", "RegExpExec receiver must be an object");
        const exec = try self.getProperty(rx, "exec");
        if (exec.isCallable()) {
            const result = try self.callValueWithThis(exec, &.{try Value.strAlloc(self.arena, s)}, rx);
            if (result.isNull() or (result.isObject() and !result.asObj().is_symbol and !result.asObj().is_bigint)) return result;
            return self.throwError("TypeError", "RegExp exec result must be an object or null");
        }
        if (rx.asObj().behavior.is_regex) return (try self.regexMethod(rx.asObj(), "exec", &.{try Value.strAlloc(self.arena, s)})).?;
        return self.throwError("TypeError", "RegExp exec property is not callable");
    }

    fn setRegExpLikeLastIndex(self: *Interpreter, rx: Value, n: f64) EvalError!void {
        try self.setRegExpLikeLastIndexValue(rx, Value.num(n));
    }

    fn setRegExpLikeLastIndexValue(self: *Interpreter, rx: Value, v: Value) EvalError!void {
        if (rx.isObject() and rx.asObj().behavior.is_regex) return self.setRegExpLastIndexValue(rx.asObj(), v);
        if (rx.isObject()) {
            const was_strict = self.strict;
            self.strict = true;
            defer self.strict = was_strict;
            return self.setMember(rx, "lastIndex", v);
        }
        return self.throwError("TypeError", "RegExp receiver must be an object");
    }

    fn regexpSameValue(a: Value, b: Value) bool {
        if (a.isNumber() and b.isNumber()) {
            const x = a.asNum();
            const y = b.asNum();
            if (std.math.isNan(x) and std.math.isNan(y)) return true;
            if (x == 0 and y == 0) return (1.0 / x) == (1.0 / y);
            return x == y;
        }
        return value.strictEquals(a, b);
    }

    fn jsStringSeqLen(s: []const u8, i: usize) usize {
        if (wtf8SurrogateAt(s, i) != null) return 3;
        return utf8SeqLen(s, i);
    }

    fn utf16LenOfSeq(s: []const u8, i: usize) usize {
        if (wtf8SurrogateAt(s, i) != null) return 1;
        return if (utf8SeqLen(s, i) == 4) @as(usize, 2) else 1;
    }

    pub fn utf16LenOfString(s: []const u8) usize {
        var units: usize = 0;
        var i: usize = 0;
        while (i < s.len) {
            units += utf16LenOfSeq(s, i);
            i += jsStringSeqLen(s, i);
        }
        return units;
    }

    /// UTF-16 length of a string `Value`, representation-aware, allocation free,
    /// and O(1) for ordinary engine strings through StringCell's construction-
    /// time cache. Only oversized embedding inputs beyond the cache's explicit
    /// sentinel use the exact WTF-8 walk. Use this for `.length` and index-bound
    /// checks, including `hasProperty`/`objectHasOwn` where allocation is
    /// forbidden. Caller has checked `isString()`.
    pub fn utf16LenOfValue(v: Value) usize {
        std.debug.assert(v.isString());
        return v.asStringCell().utf16Len();
    }

    pub fn jsStringIs8Bit(s: []const u8) bool {
        var i: usize = 0;
        while (i < s.len) {
            if (wtf8SurrogateAt(s, i) != null) return false;
            const sequence_len = utf8SeqLen(s, i);
            const codepoint = std.unicode.utf8Decode(s[i .. i + sequence_len]) catch return false;
            if (codepoint > 0xff) return false;
            i += sequence_len;
        }
        return true;
    }

    fn utf16IndexFromByteOffset(s: []const u8, offset: usize) usize {
        var units: usize = 0;
        var i: usize = 0;
        while (i < s.len and i < offset) {
            units += utf16LenOfSeq(s, i);
            i += jsStringSeqLen(s, i);
        }
        return units;
    }

    const StringCodeUnit = strcell.Utf16CodeUnit;

    const StringCodeUnitIterator = struct {
        inner: strcell.Utf16CodeUnitIterator,

        fn initValue(v: Value) StringCodeUnitIterator {
            std.debug.assert(v.isString());
            return .{ .inner = .init(v.asStr(), v.strIsFlatLatin1()) };
        }

        fn initWtf8(bytes: []const u8) StringCodeUnitIterator {
            return .{ .inner = .init(bytes, false) };
        }

        fn next(self: *StringCodeUnitIterator) ?StringCodeUnit {
            return self.inner.next();
        }
    };

    fn stringCodeUnitAt(s: []const u8, index: usize) ?StringCodeUnit {
        var iter = StringCodeUnitIterator.initWtf8(s);
        var units: usize = 0;
        while (iter.next()) |cu| : (units += 1) if (units == index) return cu;
        return null;
    }

    /// ECMA string indices address UTF-16 code units. A cached ASCII cell is
    /// already a one-byte-per-unit image, so indexed reads must not restart a
    /// WTF-8 scan at byte zero and turn a sequential reader into O(n^2) work.
    fn stringCodeUnitAtA(s: []const u8, index: usize, ascii: bool) ?StringCodeUnit {
        if (ascii) {
            if (index >= s.len) return null;
            return .{ .unit = s[index] };
        }
        return stringCodeUnitAt(s, index);
    }

    fn stringFromCodeUnit(self: *Interpreter, unit: u16) EvalError![]const u8 {
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        if (unit >= 0xD800 and unit <= 0xDFFF) {
            try appendWtf8CodeUnit(&buf, self.arena, unit);
        } else {
            var tmp: [3]u8 = undefined;
            const n = std.unicode.utf8Encode(@intCast(unit), &tmp) catch 1;
            if (n == 1 and unit > 0x7F) {
                try appendWtf8CodeUnit(&buf, self.arena, unit);
            } else {
                try buf.appendSlice(self.arena, tmp[0..n]);
            }
        }
        return buf.toOwnedSlice(self.arena);
    }

    fn stringValueFromCodeUnit(self: *Interpreter, unit: u16) EvalError!Value {
        return try Value.strAlloc(self.arena, try self.stringFromCodeUnit(unit));
    }

    /// Build `prefix + middle + suffix` with ASCII affixes directly in the
    /// StringCell's final physical representation. This avoids a flat-latin1
    /// conversion scratch allocation before the already-required result cell.
    /// Trim a fixed-width receiver — ASCII or a flat latin1 image — with the
    /// byte scan in `jsTrimFlat`, and build the result without a conversion pass:
    /// an ASCII range is already canonical WTF-8, and a flat range goes to
    /// `createCellWithAsciiAffixes` as a flat middle between empty affixes, so it
    /// is neither re-encoded on the way in nor re-flattened on the way out.
    /// Returns the receiver's own cell when nothing is trimmed, since the string
    /// is immutable.
    fn trimmedFixedWidthValue(
        self: *Interpreter,
        s: []const u8,
        s_cell: ?*const StringCell,
        s_flat: bool,
        trim_start_: bool,
        trim_end_: bool,
    ) EvalError!Value {
        const trimmed = jsTrimFlat(s, trim_start_, trim_end_);
        if (trimmed.len == 0) return Value.str("");
        if (trimmed.len == s.len) return try self.stringReceiverValue(s, s_cell);
        if (!s_flat) return try Value.strAlloc(self.arena, trimmed);
        return Value.strCell(try strcell.createCellWithAsciiAffixes(self.arena, "", trimmed, true, ""));
    }

    fn stringValueWithAsciiAffixes(self: *Interpreter, prefix: []const u8, middle: Value, suffix: []const u8) EvalError!Value {
        std.debug.assert(middle.isString());
        const canonical_len = try strcell.asciiAffixedCanonicalLength(prefix, middle.asStr(), middle.strIsFlatLatin1(), suffix);
        if (canonical_len > max_string_bytes) return self.throwError("RangeError", "Invalid string length");
        return Value.strCell(try strcell.createCellWithAsciiAffixes(
            self.arena,
            prefix,
            middle.asStr(),
            middle.strIsFlatLatin1(),
            suffix,
        ));
    }

    /// Read one UTF-16 code unit without confusing the StringCell's physical
    /// representation for its ECMAScript index space. Flat latin1 and ASCII
    /// canonical WTF-8 are one raw byte per unit and stay O(1); every other
    /// cell takes the exact representation-aware path.
    pub fn stringIndexValueOf(self: *Interpreter, v: Value, index: usize) EvalError!?Value {
        std.debug.assert(v.isString());
        const unit = try v.asStringCell().codeUnitAt(gc_mod.temporaryAllocator(self.arena), index) orelse return null;
        return try self.stringValueFromCodeUnit(unit.unit);
    }

    fn ensureStringAppend(self: *Interpreter, buf: *const std.ArrayListUnmanaged(u8), add_len: usize) EvalError!void {
        if (add_len > max_string_bytes or buf.items.len > max_string_bytes - add_len)
            return self.throwError("RangeError", "Invalid string length");
    }

    fn appendStringByte(self: *Interpreter, buf: *std.ArrayListUnmanaged(u8), byte: u8) EvalError!void {
        try self.ensureStringAppend(buf, 1);
        try buf.append(self.arena, byte);
    }

    fn appendStringSlice(self: *Interpreter, buf: *std.ArrayListUnmanaged(u8), bytes: []const u8) EvalError!void {
        try self.ensureStringAppend(buf, bytes.len);
        try buf.appendSlice(self.arena, bytes);
    }

    fn appendStringUtf16Prefix(self: *Interpreter, buf: *std.ArrayListUnmanaged(u8), s: []const u8, units: usize) EvalError!void {
        var copied: usize = 0;
        var i: usize = 0;
        while (i < s.len and copied < units) {
            const seq_len = jsStringSeqLen(s, i);
            const seq_units = utf16LenOfSeq(s, i);
            if (copied + seq_units <= units) {
                try buf.appendSlice(self.arena, s[i .. i + seq_len]);
                copied += seq_units;
            } else {
                const cu = stringCodeUnitAt(s, copied) orelse return;
                try buf.appendSlice(self.arena, try self.stringFromCodeUnit(cu.unit));
                copied += 1;
            }
            i += seq_len;
        }
    }

    /// `stringSliceUtf16` for a receiver that may be a flat latin1 image, where a
    /// code-unit range IS a byte range. Only the extracted range is re-encoded to
    /// WTF-8, so slicing does not cost a pass over the whole receiver.
    fn stringSliceUtf16A(self: *Interpreter, s: []const u8, start: usize, end: usize, flat: bool) EvalError![]const u8 {
        if (!flat) return self.stringSliceUtf16(s, start, end);
        const lo = @min(start, s.len);
        const hi = @min(end, s.len);
        if (lo >= hi) return "";
        return strcell.latin1FlatToWtf8(self.arena, s[lo..hi]);
    }

    fn stringSliceUtf16(self: *Interpreter, s: []const u8, start: usize, end: usize) EvalError![]const u8 {
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        var units: usize = 0;
        var i: usize = 0;
        while (i < s.len and units < end) {
            const seq_len = jsStringSeqLen(s, i);
            const seq_units = utf16LenOfSeq(s, i);
            const seq_start = units;
            const seq_end = units + seq_units;
            if (seq_end <= start) {
                units = seq_end;
                i += seq_len;
                continue;
            }
            if (start <= seq_start and seq_end <= end) {
                try buf.appendSlice(self.arena, s[i .. i + seq_len]);
            } else {
                var u = @max(start, seq_start);
                while (u < @min(end, seq_end)) : (u += 1) {
                    const cu = stringCodeUnitAt(s, u) orelse break;
                    try buf.appendSlice(self.arena, try self.stringFromCodeUnit(cu.unit));
                }
            }
            units = seq_end;
            i += seq_len;
        }
        return buf.toOwnedSlice(self.arena);
    }

    /// Return at most `max_units` UTF-16 code units from canonical WTF-8.
    /// A boundary between an astral scalar's surrogate pair must materialize
    /// the exact lone high surrogate; every complete-sequence boundary can
    /// borrow the existing immutable prefix.
    pub fn stringPrefixUtf16(self: *Interpreter, s: []const u8, max_units: usize) EvalError![]const u8 {
        if (max_units == 0) return s[0..0];
        var units: usize = 0;
        var i: usize = 0;
        while (i < s.len) {
            const seq_len = jsStringSeqLen(s, i);
            const seq_units = utf16LenOfSeq(s, i);
            if (seq_units > max_units - units)
                return self.stringSliceUtf16(s, 0, max_units);
            units += seq_units;
            i += seq_len;
            if (units == max_units) return s[0..i];
        }
        return s;
    }

    fn stringLengthForAccess(s: []const u8, ascii: bool, cell: ?*const StringCell) usize {
        return if (cell) |string_cell| string_cell.utf16Len() else utf16LenOfStringA(s, ascii);
    }

    fn stringCodeUnitAtAccess(
        self: *Interpreter,
        s: []const u8,
        index: usize,
        ascii: bool,
        cell: ?*const StringCell,
    ) EvalError!?StringCodeUnit {
        if (cell) |string_cell| {
            const unit = try string_cell.codeUnitAt(gc_mod.temporaryAllocator(self.arena), index) orelse return null;
            return .{ .unit = unit.unit, .astral = unit.astral };
        }
        return stringCodeUnitAtA(s, index, ascii);
    }

    fn stringPosition(self: *Interpreter, s: []const u8, v: Value, ascii: bool, cell: ?*const StringCell) EvalError!?usize {
        const n = try self.toNumberV(v);
        const pos = if (std.math.isNan(n)) @as(f64, 0) else @trunc(n);
        if (pos < 0 or pos >= @as(f64, @floatFromInt(stringLengthForAccess(s, ascii, cell)))) return null;
        return @intFromFloat(pos);
    }

    fn stringClampPosition(self: *Interpreter, s: []const u8, v: Value, default_pos: usize, ascii: bool, cell: ?*const StringCell) EvalError!usize {
        if (v.isUndefined()) return default_pos;
        const n = try self.toNumberV(v);
        if (std.math.isNan(n) or n <= 0) return 0;
        const len = stringLengthForAccess(s, ascii, cell);
        if (n >= @as(f64, @floatFromInt(len))) return len;
        return @intFromFloat(@trunc(n));
    }

    fn byteOffsetForUtf16Index(s: []const u8, index: usize) usize {
        var units: usize = 0;
        var i: usize = 0;
        while (i < s.len) {
            if (index <= units) return i;
            const seq_len = jsStringSeqLen(s, i);
            const seq_units = utf16LenOfSeq(s, i);
            if (index < units + seq_units) return i + seq_len;
            units += seq_units;
            i += seq_len;
        }
        return s.len;
    }

    fn utf16IndexForByteOffset(s: []const u8, byte_offset: usize) usize {
        var units: usize = 0;
        var i: usize = 0;
        const target = @min(byte_offset, s.len);
        while (i < s.len and i < target) {
            units += utf16LenOfSeq(s, i);
            i += jsStringSeqLen(s, i);
        }
        return units;
    }

    // ---- ASCII fast paths (flat-string model, phase 1) --------------------
    // When a string is known ASCII (cached `StringCell.isAscii()`), its WTF-8
    // bytes are already a flat 1-byte-per-unit image, so byte offset == UTF-16
    // index and these conversions are O(1) instead of walking the string. The
    // `ascii` flag is threaded from the source cell at the hot call sites
    // (regexp exec/match/replace/split, indexOf/lastIndexOf); everything else
    // keeps the exact O(n) WTF-8 walk.

    fn byteOffsetForUtf16IndexA(s: []const u8, index: usize, ascii: bool) usize {
        if (ascii) return @min(index, s.len);
        return byteOffsetForUtf16Index(s, index);
    }

    fn utf16IndexForByteOffsetA(s: []const u8, byte_offset: usize, ascii: bool) usize {
        if (ascii) return @min(byte_offset, s.len);
        return utf16IndexForByteOffset(s, byte_offset);
    }

    fn utf16LenOfStringA(s: []const u8, ascii: bool) usize {
        if (ascii) return s.len;
        return utf16LenOfString(s);
    }

    fn stringBytesAreAscii(s: []const u8) bool {
        for (s) |byte| if (byte >= 0x80) return false;
        return true;
    }

    const Utf16KmpPattern = struct {
        scratch: std.mem.Allocator,
        units: []u16,
        prefix: []u32,

        fn init(scratch: std.mem.Allocator, needle: []const u8, needle_len: usize) EvalError!Utf16KmpPattern {
            std.debug.assert(needle_len > 0);
            if (needle_len > std.math.maxInt(u32)) return error.OutOfMemory;
            const units = try scratch.alloc(u16, needle_len);
            errdefer scratch.free(units);
            var needle_it = StringCodeUnitIterator.initWtf8(needle);
            for (units) |*unit| unit.* = needle_it.next().?.unit;

            // Ordinary constructed strings are capped at `max_string_bytes`
            // (2^26); the explicit guard above also covers larger external
            // strings. A u32 prefix bounds freeable KMP scratch to six bytes
            // per needle code unit instead of a native usize pair.
            const prefix = try scratch.alloc(u32, needle_len);
            errdefer scratch.free(prefix);
            prefix[0] = 0;
            var prefix_len: usize = 0;
            var prefix_index: usize = 1;
            while (prefix_index < needle_len) : (prefix_index += 1) {
                while (prefix_len > 0 and units[prefix_index] != units[prefix_len])
                    prefix_len = @intCast(prefix[prefix_len - 1]);
                if (units[prefix_index] == units[prefix_len]) prefix_len += 1;
                prefix[prefix_index] = @intCast(prefix_len);
            }
            return .{ .scratch = scratch, .units = units, .prefix = prefix };
        }

        fn deinit(self: *Utf16KmpPattern) void {
            self.scratch.free(self.prefix);
            self.scratch.free(self.units);
        }

        fn accepts(self: *const Utf16KmpPattern, matched: *usize, unit: u16) bool {
            while (matched.* > 0 and unit != self.units[matched.*])
                matched.* = @intCast(self.prefix[matched.* - 1]);
            if (unit == self.units[matched.*]) matched.* += 1;
            if (matched.* != self.units.len) return false;
            // Retain the longest suffix-prefix so a last-index scan recognizes
            // overlapping matches (for example, "aaaa" / "aaa").
            matched.* = @intCast(self.prefix[self.units.len - 1]);
            return true;
        }
    };

    /// ECMA-262 StringIndexOf over the engine's WTF-8 storage. The common
    /// ASCII representation is already one byte per UTF-16 code unit. Other
    /// strings stream their abstract code units through KMP so astral halves
    /// and lone surrogates remain observable without repeated rescans.
    /// `needle`'s flat latin1 image, for searching a flat latin1 haystack with
    /// plain byte operations. Null when the needle carries a code unit above
    /// 0xFF, which therefore cannot occur in such a haystack at all. An ASCII
    /// needle is already its own flat image, so the common case copies nothing.
    fn flatLatin1Needle(self: *Interpreter, needle: []const u8) EvalError!?[]const u8 {
        if (stringBytesAreAscii(needle)) return needle;
        if (!jsStringIs8Bit(needle)) return null;
        return try strcell.wtf8ToLatin1Flat(self.arena, needle);
    }

    fn stringIndexOfUtf16(self: *Interpreter, haystack: []const u8, needle: []const u8, start: usize, haystack_len: usize, haystack_ascii: bool, haystack_flat: bool) EvalError!?usize {
        if (start > haystack_len) return null;
        if (needle.len == 0) return start;
        // A flat latin1 haystack is one byte per code unit, so — once the needle
        // is in the same representation — this is the same byte search the ASCII
        // path runs, and the match offset is already the code-unit index.
        if (haystack_flat) {
            const flat_needle = (try self.flatLatin1Needle(needle)) orelse return null;
            if (flat_needle.len == 0) return start;
            return std.mem.indexOfPos(u8, haystack, @min(start, haystack.len), flat_needle);
        }
        const needle_ascii = stringBytesAreAscii(needle);
        if (haystack_ascii) {
            if (!needle_ascii) return null;
            return std.mem.indexOfPos(u8, haystack, @min(start, haystack.len), needle);
        }

        const needle_len = utf16LenOfString(needle);
        if (needle_len == 0) return start;
        if (needle_len > haystack_len - start) return null;
        const scratch = self.scratch_allocator orelse self.arena;
        var pattern = try Utf16KmpPattern.init(scratch, needle, needle_len);
        defer pattern.deinit();

        var haystack_it = StringCodeUnitIterator.initWtf8(haystack);
        var index: usize = 0;
        while (index < start) : (index += 1) _ = haystack_it.next() orelse return null;
        var matched: usize = 0;
        while (haystack_it.next()) |code_unit| {
            index += 1;
            if (pattern.accepts(&matched, code_unit.unit)) return index - needle_len;
        }
        return null;
    }

    /// Greatest UTF-16 match start at or before `limit`. Scanning only through
    /// `max_start + needle_len` observes every admissible candidate exactly
    /// once, including overlaps, without a reverse/random-access decode.
    fn stringLastIndexOfUtf16(self: *Interpreter, haystack: []const u8, needle: []const u8, limit: usize, haystack_len: usize, haystack_ascii: bool, haystack_flat: bool) EvalError!?usize {
        if (limit > haystack_len) return null;
        if (needle.len == 0) return limit;
        if (haystack_flat) {
            const flat_needle = (try self.flatLatin1Needle(needle)) orelse return null;
            if (flat_needle.len == 0) return limit;
            if (flat_needle.len > haystack.len) return null;
            const max_start = @min(limit, haystack.len - flat_needle.len);
            return std.mem.lastIndexOf(u8, haystack[0 .. max_start + flat_needle.len], flat_needle);
        }
        const needle_ascii = stringBytesAreAscii(needle);
        if (haystack_ascii) {
            if (!needle_ascii or needle.len > haystack.len) return null;
            const max_start = @min(limit, haystack.len - needle.len);
            return std.mem.lastIndexOf(u8, haystack[0 .. max_start + needle.len], needle);
        }

        const needle_len = utf16LenOfString(needle);
        if (needle_len == 0) return limit;
        if (needle_len > haystack_len) return null;
        const max_start = @min(limit, haystack_len - needle_len);
        const scan_units = max_start + needle_len;
        const scratch = self.scratch_allocator orelse self.arena;
        var pattern = try Utf16KmpPattern.init(scratch, needle, needle_len);
        defer pattern.deinit();

        var haystack_it = StringCodeUnitIterator.initWtf8(haystack);
        var index: usize = 0;
        var matched: usize = 0;
        var last: ?usize = null;
        while (index < scan_units) {
            const unit = (haystack_it.next() orelse break).unit;
            index += 1;
            if (pattern.accepts(&matched, unit)) last = index - needle_len;
        }
        return last;
    }

    /// All non-overlapping StringIndexOf results, in ascending UTF-16 order.
    /// ECMA-262 replaceAll collects this list before invoking any replacer, and
    /// split consumes the same sequence. `max_matches` lets split stop once its
    /// result limit makes later matches unobservable.
    fn stringMatchPositionsUtf16(
        self: *Interpreter,
        haystack: []const u8,
        needle: []const u8,
        haystack_len: usize,
        haystack_ascii: bool,
        max_matches: ?usize,
    ) EvalError!std.ArrayListUnmanaged(u32) {
        const scratch = self.scratch_allocator orelse self.arena;
        var positions: std.ArrayListUnmanaged(u32) = .empty;
        errdefer positions.deinit(scratch);
        const limit = max_matches orelse std.math.maxInt(usize);
        if (limit == 0) return positions;

        if (needle.len == 0) {
            // Constructed strings are capped far below u32; fail closed for an
            // oversized external slice instead of overflowing compact scratch.
            if (haystack_len >= std.math.maxInt(u32)) return error.OutOfMemory;
            const count = @min(haystack_len + 1, limit);
            try positions.ensureTotalCapacity(scratch, count);
            for (0..count) |position| positions.appendAssumeCapacity(@intCast(position));
            return positions;
        }

        const needle_ascii = stringBytesAreAscii(needle);
        if (haystack_ascii) {
            if (!needle_ascii or needle.len > haystack.len) return positions;
            var from: usize = 0;
            while (positions.items.len < limit) {
                const position = std.mem.indexOfPos(u8, haystack, from, needle) orelse break;
                if (position > std.math.maxInt(u32)) return error.OutOfMemory;
                try positions.append(scratch, @intCast(position));
                from = position + needle.len;
            }
            return positions;
        }

        const needle_len = utf16LenOfString(needle);
        if (needle_len == 0 or needle_len > haystack_len) return positions;
        var pattern = try Utf16KmpPattern.init(scratch, needle, needle_len);
        defer pattern.deinit();

        var haystack_it = StringCodeUnitIterator.initWtf8(haystack);
        var index: usize = 0;
        var matched: usize = 0;
        while (haystack_it.next()) |code_unit| {
            index += 1;
            if (!pattern.accepts(&matched, code_unit.unit)) continue;
            const position = index - needle_len;
            if (position > std.math.maxInt(u32)) return error.OutOfMemory;
            try positions.append(scratch, @intCast(position));
            if (positions.items.len == limit) break;
            // replaceAll/split resume after the complete match, so overlapping
            // candidates are not admissible even though indexOf/lastIndexOf do
            // retain the KMP suffix-prefix state.
            matched = 0;
        }
        return positions;
    }

    /// Private-ABI contains operation. Unlike String.prototype.includes this
    /// has no position argument, but it shares the exact, bounded matcher and
    /// must surface scratch-allocation failure to the embedding exception path.
    pub fn stringIncludesUtf16(self: *Interpreter, haystack: []const u8, needle: []const u8) EvalError!bool {
        const haystack_ascii = stringBytesAreAscii(haystack);
        const haystack_len = utf16LenOfStringA(haystack, haystack_ascii);
        return (try self.stringIndexOfUtf16(haystack, needle, 0, haystack_len, haystack_ascii, false)) != null;
    }

    /// Compare `needle` with the UTF-16 substring beginning at `start` without
    /// materializing that substring. This differs from converting `start` to a
    /// byte offset: the index may designate the low half of an astral scalar.
    /// `needle_flat` says `needle` has already been converted to the haystack's
    /// flat latin1 representation by the caller (which owns the allocator), so
    /// both sides are one byte per code unit and `start` is a byte offset.
    fn stringCodeUnitsEqualAt(haystack: []const u8, needle: []const u8, start: usize, haystack_ascii: bool, needle_flat: bool) bool {
        if (needle.len == 0) return true;
        if (needle_flat) {
            if (start > haystack.len) return false;
            return std.mem.startsWith(u8, haystack[start..], needle);
        }
        const needle_ascii = stringBytesAreAscii(needle);
        if (haystack_ascii) {
            if (!needle_ascii or start > haystack.len) return false;
            return std.mem.startsWith(u8, haystack[start..], needle);
        }

        var haystack_it = StringCodeUnitIterator.initWtf8(haystack);
        var skipped: usize = 0;
        while (skipped < start) : (skipped += 1) _ = haystack_it.next() orelse return false;
        var needle_it = StringCodeUnitIterator.initWtf8(needle);
        while (needle_it.next()) |expected| {
            const actual = haystack_it.next() orelse return false;
            if (actual.unit != expected.unit) return false;
        }
        return true;
    }

    fn appendWtf8CodeUnit(buf: *std.ArrayListUnmanaged(u8), a: std.mem.Allocator, cu: u16) !void {
        try buf.append(a, @intCast(0xE0 | (cu >> 12)));
        try buf.append(a, @intCast(0x80 | ((cu >> 6) & 0x3F)));
        try buf.append(a, @intCast(0x80 | (cu & 0x3F)));
    }

    /// A forward-only (byte, UTF-16-unit) position for one string. A global regex
    /// scan queries monotonically increasing positions, so threading one cursor
    /// makes the whole scan's UTF-16↔byte conversions O(n) instead of O(n^2). A
    /// backward query resets to the start (still correct, just no speedup).
    const RxCursor = struct {
        byte: usize = 0,
        units: usize = 0,
        /// True when the scanned string is ASCII: byte offset == UTF-16 index,
        /// so both conversions are identity and never walk (see `RxCursor` doc).
        ascii: bool = false,
        fn byteForUtf16(self: *RxCursor, s: []const u8, index: usize) usize {
            if (self.ascii) return @min(index, s.len);
            if (index < self.units) {
                self.byte = 0;
                self.units = 0;
            }
            var i = self.byte;
            var u = self.units;
            while (i < s.len) {
                if (index <= u) break;
                const su = utf16LenOfSeq(s, i);
                if (index < u + su) {
                    self.byte = i;
                    self.units = u;
                    return i + jsStringSeqLen(s, i);
                }
                u += su;
                i += jsStringSeqLen(s, i);
            }
            self.byte = i;
            self.units = u;
            return i;
        }
        fn utf16ForByte(self: *RxCursor, s: []const u8, byte: usize) usize {
            if (self.ascii) return @min(byte, s.len);
            const target = @min(byte, s.len);
            if (target < self.byte) {
                self.byte = 0;
                self.units = 0;
            }
            var i = self.byte;
            var u = self.units;
            while (i < s.len and i < target) {
                u += utf16LenOfSeq(s, i);
                i += jsStringSeqLen(s, i);
            }
            self.byte = i;
            self.units = u;
            return u;
        }
    };

    /// True when `rx` is a plain built-in RegExp whose `exec` is the original
    /// (not overridden by a subclass). Only then may an internal global loop take
    /// the fast `regexBuiltinExecWith` path instead of RegExpExec via the property.
    fn regexpHasBuiltinExec(self: *Interpreter, rx: Value) bool {
        if (!rx.isObject() or !rx.asObj().behavior.is_regex) return false;
        const exec = self.getProperty(rx, "exec") catch return false;
        if (!exec.isObject()) return false;
        const builtin_exec = rootEnv(self.env).get("\x00RegExpBuiltinExec") orelse return false;
        return builtin_exec.isObject() and exec.asObj() == builtin_exec.asObj();
    }

    /// RegExpBuiltinExec with the per-call O(n) setup hoisted out: `search_input`
    /// and `input_u16_len` are precomputed once by the caller, and the UTF-16↔byte
    /// conversions resume from the shared `cursor`. Identical result to the
    /// property-`exec` path; used by the internal global loops.
    fn regexBuiltinExecWith(self: *Interpreter, o: *value.Object, input: []const u8, input_value: Value, search_input: []const u8, flags: []const u8, input_u16_len: usize, cursor: *RxCursor) EvalError!Value {
        const li = toLen(try self.toNumberV(try self.getProperty(Value.obj(o), "lastIndex")));
        const live_flags = o.regexFlags();
        const cached_unicode = std.mem.indexOfScalar(u8, flags, 'u') != null or std.mem.indexOfScalar(u8, flags, 'v') != null;
        const live_unicode = std.mem.indexOfScalar(u8, live_flags, 'u') != null or std.mem.indexOfScalar(u8, live_flags, 'v') != null;
        if (live_unicode != cached_unicode) return (try self.regexMethod(o, "exec", &.{input_value})).?;
        const global = std.mem.indexOfScalar(u8, live_flags, 'g') != null;
        const sticky = std.mem.indexOfScalar(u8, live_flags, 'y') != null;
        const start_units = if (global or sticky) li else 0;
        if (start_units > input_u16_len) {
            if (global or sticky) try self.setRegExpLastIndex(o, 0);
            return Value.nul();
        }
        const start = cursor.byteForUtf16(search_input, start_units);
        const re = try self.compileRegex(o);
        const matcher = try self.regexMatcher(re);
        const found = regex.Regex.Matcher.findFrom(matcher, search_input, start) catch null;
        if (found) |match| {
            var m = match;
            defer m.deinit(self.arena);
            if (sticky and m.start != start) {
                try self.setRegExpLastIndex(o, 0);
                return Value.nul();
            }
            const mstart = m.start;
            const mend = m.end;
            const mstart_units = cursor.utf16ForByte(search_input, mstart);
            const mend_units = cursor.utf16ForByte(search_input, mend);
            if (global or sticky) try self.setRegExpLastIndex(o, @floatFromInt(mend_units));
            recordRegexpLegacyBorrowed(self, search_input, mstart, mend, m.captures);
            const arr = try self.newArray();
            try arr.asObj().appendElement(self.arena, try Value.strAlloc(self.arena, try self.stringSliceFromSearchSpan(input, search_input, mstart, mend)));
            for (0..m.captures.len) |i| try arr.asObj().appendElement(self.arena, try self.captureValSpan(m, i, input, search_input));
            try self.setProp(arr.asObj(), "index", Value.num(@floatFromInt(mstart_units)));
            try self.setProp(arr.asObj(), "input", input_value); // shared cell (no per-match re-copy)
            const groups = try self.regexGroupsSpan(re, m, input, search_input);
            try self.setProp(arr.asObj(), "groups", if (groups) |g| Value.obj(g) else Value.undef());
            if (std.mem.indexOfScalar(u8, live_flags, 'd') != null)
                try self.setProp(arr.asObj(), "indices", Value.obj(try self.makeIndicesArray(re, m, search_input, 0)));
            return arr;
        }
        if (global or sticky) try self.setRegExpLastIndex(o, 0);
        return Value.nul();
    }

    fn regexpSearchInput(self: *Interpreter, input: []const u8, unicode: bool) ![]const u8 {
        return regexpSearchInputAlloc(self.arena, input, unicode);
    }

    fn stringSliceFromSearchSpan(self: *Interpreter, input: []const u8, search_input: []const u8, start: usize, end: usize) EvalError![]const u8 {
        // Common case: no astral chars, so `search_input` IS `input` and the match
        // byte span is exactly the substring — a direct byte slice (O(match len)).
        if (search_input.ptr == input.ptr) return input[start..end];
        const start_units = utf16IndexForByteOffset(search_input, start);
        const end_units = utf16IndexForByteOffset(search_input, end);
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        try appendUtf16Slice(&buf, self.arena, input, start_units, end_units);
        return try buf.toOwnedSlice(self.arena);
    }

    fn appendUtf16Slice(buf: *std.ArrayListUnmanaged(u8), a: std.mem.Allocator, s: []const u8, start: usize, end: usize) !void {
        try appendUtf16SliceImpl(buf, a, s, 0, 0, start, end);
    }

    /// `appendUtf16Slice` resuming from `cursor` (a whole-sequence boundary). One
    /// cursor threaded through the increasing slices of `regexpReplace`'s output
    /// makes that loop O(n) instead of O(n^2).
    fn appendUtf16SliceFrom(buf: *std.ArrayListUnmanaged(u8), a: std.mem.Allocator, s: []const u8, cursor: *RxCursor, start: usize, end: usize) !void {
        if (start < cursor.units) {
            cursor.byte = 0;
            cursor.units = 0;
        }
        while (cursor.byte < s.len) {
            const su = utf16LenOfSeq(s, cursor.byte);
            if (cursor.units + su > start) break;
            cursor.units += su;
            cursor.byte += jsStringSeqLen(s, cursor.byte);
        }
        try appendUtf16SliceImpl(buf, a, s, cursor.byte, cursor.units, start, end);
    }

    fn appendUtf16SliceImpl(buf: *std.ArrayListUnmanaged(u8), a: std.mem.Allocator, s: []const u8, from_byte: usize, from_units: usize, start: usize, end: usize) !void {
        if (start >= end) return;
        var units: usize = from_units;
        var i: usize = from_byte;
        while (i < s.len and units < end) {
            const seq_len = jsStringSeqLen(s, i);
            const seq_units = utf16LenOfSeq(s, i);
            if (units + seq_units <= start) {
                units += seq_units;
                i += seq_len;
                continue;
            }
            if (seq_units == 2 and seq_len == 4) {
                const cp = std.unicode.utf8Decode(s[i .. i + seq_len]) catch 0;
                if (cp > 0xFFFF) {
                    const u = cp - 0x10000;
                    const high: u16 = @intCast(0xD800 + (u >> 10));
                    const low: u16 = @intCast(0xDC00 + (u & 0x3FF));
                    const include_high = start <= units and units < end;
                    const include_low = start <= units + 1 and units + 1 < end;
                    if (include_high and include_low) {
                        try buf.appendSlice(a, s[i .. i + seq_len]);
                    } else {
                        if (include_high) try appendWtf8CodeUnit(buf, a, high);
                        if (include_low) try appendWtf8CodeUnit(buf, a, low);
                    }
                    units += seq_units;
                    i += seq_len;
                    continue;
                }
            }
            if (units >= start and units < end) try buf.appendSlice(a, s[i .. i + seq_len]);
            units += seq_units;
            i += seq_len;
        }
    }

    fn advanceStringIndex(s: []const u8, index: usize, unicode: bool) usize {
        if (!unicode) return index + 1;
        var units: usize = 0;
        var b: usize = 0;
        while (b < s.len) {
            const seq_len = jsStringSeqLen(s, b);
            const seq_units = utf16LenOfSeq(s, b);
            if (index == units) {
                if (seq_units == 2) return index + 2;
                const first = wtf8SurrogateAt(s, b);
                if (first != null and first.? >= 0xD800 and first.? <= 0xDBFF) {
                    const next = b + seq_len;
                    if (wtf8SurrogateAt(s, next)) |second| {
                        if (second >= 0xDC00 and second <= 0xDFFF) return index + 2;
                    }
                }
                return index + 1;
            }
            if (index < units + seq_units) return index + 1;
            units += seq_units;
            b += seq_len;
        }
        return index + 1;
    }

    fn isRegExpObjectValue(v: Value) bool {
        return v.isObject() and !v.asObj().is_symbol and !v.asObj().is_bigint;
    }

    /// RegExp.prototype[@@matchAll]: build a lazy %RegExpStringIterator% over a
    /// species-constructed matcher (so a subclass's exec/lastIndex drive iteration).
    fn regexpMatchAll(self: *Interpreter, this: Value, s: []const u8) EvalError!Value {
        if (!this.isObject()) return self.throwError("TypeError", "RegExp.prototype[Symbol.matchAll] called on a non-object");
        const default_ctor = self.env.get("RegExp") orelse return self.throwError("TypeError", "RegExp is not defined");
        const c = try self.speciesConstructor(this, default_ctor);
        const flags = try self.toStringWtf8(try self.getProperty(this, "flags"));
        const matcher = try self.construct(c, &.{ this, try Value.strAlloc(self.arena, flags) });
        const last_index = toLen(try self.toNumberV(try self.getProperty(this, "lastIndex")));
        try self.setRegExpLikeLastIndex(matcher, @floatFromInt(last_index));
        const global = std.mem.indexOfScalar(u8, flags, 'g') != null;
        const unicode = std.mem.indexOfScalar(u8, flags, 'u') != null or std.mem.indexOfScalar(u8, flags, 'v') != null;
        return self.createRegExpStringIterator(matcher, s, global, unicode);
    }

    fn createRegExpStringIterator(self: *Interpreter, matcher: Value, s: []const u8, global: bool, unicode: bool) EvalError!Value {
        const it = try gc_mod.allocObj(self.arena);
        it.* = .{};
        if (self.env.get("\x00ReStrIterProto")) |p| {
            if (p.isObject()) it.setProtoAtomic(p.asObj());
        }
        try self.setProp(it, "__re", matcher);
        try self.setProp(it, "__str", try Value.strOwned(self.arena, try self.arena.dupe(u8, s)));
        try self.setProp(it, "__g", Value.boolVal(global));
        try self.setProp(it, "__u", Value.boolVal(unicode));
        try self.setProp(it, "__done", Value.boolVal(false));
        return Value.obj(it);
    }

    fn regexpMatch(self: *Interpreter, rx: Value, s: []const u8) EvalError!Value {
        if (!isRegExpObjectValue(rx)) return self.throwError("TypeError", "RegExp.prototype[Symbol.match] called on a non-object");
        const flags = try self.toStringWtf8(try self.getProperty(rx, "flags"));
        const global = std.mem.indexOfScalar(u8, flags, 'g') != null;
        if (!global) return try self.regexpExecGeneric(rx, s);
        const full_unicode = std.mem.indexOfScalar(u8, flags, 'u') != null or std.mem.indexOfScalar(u8, flags, 'v') != null;

        // Fast path for a plain built-in RegExp: precompute the search input and
        // its length ONCE and share a conversion cursor, so the whole scan is O(n)
        // instead of O(n^2) (each RegExpExec otherwise re-scans/re-allocates).
        const fast = self.regexpHasBuiltinExec(rx);
        const search_input = if (fast) try self.regexpSearchInput(s, full_unicode) else "";
        const input_value = if (fast) try Value.strAlloc(self.arena, s) else Value.undef();
        const input_ascii = fast and input_value.strIsAscii();
        const input_u16 = if (fast) utf16LenOfStringA(s, input_ascii) else 0;
        var cursor: RxCursor = .{ .ascii = input_ascii };

        try self.setRegExpLikeLastIndex(rx, 0);
        const arr = try self.newArray();
        while (true) {
            const result = if (fast)
                try self.regexBuiltinExecWith(rx.asObj(), s, input_value, search_input, flags, input_u16, &cursor)
            else
                try self.regexpExecGeneric(rx, s);
            if (result.isNull()) return if (arr.asObj().elementsLen() == 0) Value.nul() else arr;

            const match_v = try self.getProperty(result, "0");
            const match_s = try self.toStringWtf8(match_v);
            try arr.asObj().appendElement(self.arena, try Value.strOwned(self.arena, try self.arena.dupe(u8, match_s)));

            if (match_s.len == 0) {
                const li = toLen(try self.toNumberV(try self.getProperty(rx, "lastIndex")));
                try self.setRegExpLikeLastIndex(rx, @floatFromInt(advanceStringIndex(s, li, full_unicode)));
            }
        }
    }

    fn regexpSearch(self: *Interpreter, rx: Value, s: []const u8) EvalError!Value {
        if (!isRegExpObjectValue(rx)) return self.throwError("TypeError", "RegExp.prototype[Symbol.search] called on a non-object");
        const previous_last_index = try self.getProperty(rx, "lastIndex");
        if (!regexpSameValue(previous_last_index, Value.num(0))) try self.setRegExpLikeLastIndex(rx, 0);
        const result = try self.regexpExecGeneric(rx, s);
        const current_last_index = try self.getProperty(rx, "lastIndex");
        if (!regexpSameValue(current_last_index, previous_last_index)) try self.setRegExpLikeLastIndexValue(rx, previous_last_index);
        if (result.isNull()) return Value.num(-1);
        const index = try self.toNumberV(try self.getProperty(result, "index"));
        return Value.num(@floatFromInt(toLen(index)));
    }

    fn regexpReplace(self: *Interpreter, rx: Value, s: []const u8, replace_value: Value) EvalError!Value {
        if (!isRegExpObjectValue(rx)) return self.throwError("TypeError", "RegExp.prototype[Symbol.replace] called on a non-object");
        const functional_replace = replace_value.isCallable();
        const replace_string = if (functional_replace) "" else try self.toStringWtf8(replace_value);
        const flags = try self.toStringWtf8(try self.getProperty(rx, "flags"));
        const global = std.mem.indexOfScalar(u8, flags, 'g') != null;
        const full_unicode = global and (std.mem.indexOfScalar(u8, flags, 'u') != null or std.mem.indexOfScalar(u8, flags, 'v') != null);

        if (global) try self.setRegExpLikeLastIndex(rx, 0);

        // Fast path for a plain built-in RegExp: hoist the per-exec O(n) setup out
        // of the match-collection loop (see regexBuiltinExecWith), so it is O(n).
        const fast = self.regexpHasBuiltinExec(rx);
        const unicode = std.mem.indexOfScalar(u8, flags, 'u') != null or std.mem.indexOfScalar(u8, flags, 'v') != null;
        const search_input = if (fast) try self.regexpSearchInput(s, unicode) else "";
        const input_value = if (fast) try Value.strAlloc(self.arena, s) else Value.undef();
        const input_ascii = fast and input_value.strIsAscii();
        const input_u16 = if (fast) utf16LenOfStringA(s, input_ascii) else 0;
        var cursor: RxCursor = .{ .ascii = input_ascii };

        var results: std.ArrayListUnmanaged(Value) = .empty;
        while (true) {
            const result = if (fast)
                try self.regexBuiltinExecWith(rx.asObj(), s, input_value, search_input, flags, input_u16, &cursor)
            else
                try self.regexpExecGeneric(rx, s);
            if (result.isNull()) break;
            try results.append(self.arena, result);
            if (!global) break;

            const match = try self.toStringV(try self.getProperty(result, "0"));
            if (match.len == 0) {
                const li = toArrayLikeLen(try self.toNumberV(try self.getProperty(rx, "lastIndex")));
                try self.setRegExpLikeLastIndex(rx, @floatFromInt(advanceStringIndex(s, li, full_unicode)));
            }
        }

        const string_len = utf16LenOfStringA(s, input_ascii);
        var accumulated: usize = 0;
        var out: std.ArrayListUnmanaged(u8) = .empty;
        // Matches are in increasing position order, so one cursor keeps the
        // per-match output slices O(n) overall.
        var out_cursor: RxCursor = .{ .ascii = input_ascii };
        for (results.items) |result| {
            const length = toLen(try self.toNumberV(try self.getProperty(result, "length")));
            const captures_len = if (length == 0) 0 else length - 1;
            const matched = try self.toStringWtf8(try self.getProperty(result, "0"));
            const position = @min(toLen(try self.toNumberV(try self.getProperty(result, "index"))), string_len);

            var captures: std.ArrayListUnmanaged(Value) = .empty;
            var i: usize = 1;
            while (i <= captures_len) : (i += 1) {
                const key = try std.fmt.allocPrint(self.arena, "{d}", .{i});
                const capture = try self.getProperty(result, key);
                if (capture.isUndefined()) {
                    try captures.append(self.arena, Value.undef());
                } else {
                    try captures.append(self.arena, try Value.strAlloc(self.arena, try self.toStringWtf8(capture)));
                }
            }
            const named_captures = try self.getProperty(result, "groups");

            var replacement: []const u8 = "";
            if (functional_replace) {
                var call_args: std.ArrayListUnmanaged(Value) = .empty;
                try call_args.append(self.arena, try Value.strAlloc(self.arena, matched));
                try call_args.appendSlice(self.arena, captures.items);
                try call_args.append(self.arena, Value.num(@floatFromInt(position)));
                try call_args.append(self.arena, try Value.strAlloc(self.arena, s));
                if (!named_captures.isUndefined()) try call_args.append(self.arena, named_captures);
                replacement = try self.toStringWtf8(try self.callValue(replace_value, call_args.items));
            } else {
                const substitution_groups: Value = if (named_captures.isUndefined())
                    Value.undef()
                else
                    Value.obj(try self.toObject(named_captures));
                var repl_buf: std.ArrayListUnmanaged(u8) = .empty;
                try self.getSubstitutionValues(&repl_buf, replace_string, matched, s, position, captures.items, substitution_groups);
                replacement = try repl_buf.toOwnedSlice(self.arena);
            }

            if (position >= accumulated) {
                try appendUtf16SliceFrom(&out, self.arena, s, &out_cursor, accumulated, position);
                try self.appendStringSlice(&out, replacement);
                accumulated = @min(position + utf16LenOfString(matched), string_len);
            }
        }
        try appendUtf16SliceFrom(&out, self.arena, s, &out_cursor, accumulated, string_len);
        return try Value.strOwned(self.arena, try out.toOwnedSlice(self.arena));
    }

    fn appendSplitSegment(self: *Interpreter, out: *std.ArrayListUnmanaged(Value), s: []const u8, cursor: *RxCursor, start: usize, end: usize) EvalError!void {
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        try appendUtf16SliceFrom(&buf, self.arena, s, cursor, start, end);
        try out.append(self.arena, try Value.strOwned(self.arena, try buf.toOwnedSlice(self.arena)));
    }

    fn regexpSplit(self: *Interpreter, rx: Value, s: []const u8, limit_value: Value) EvalError!Value {
        if (!isRegExpObjectValue(rx)) return self.throwError("TypeError", "RegExp.prototype[Symbol.split] called on a non-object");
        const result = try self.newArray();
        const out = try result.asObj().ensureElementsList(self.arena);

        const default_ctor = self.env.get("RegExp") orelse Value.undef();
        const ctor = try self.speciesConstructor(rx, default_ctor);
        const flags = try self.toStringWtf8(try self.getProperty(rx, "flags"));
        const full_unicode = std.mem.indexOfScalar(u8, flags, 'u') != null or std.mem.indexOfScalar(u8, flags, 'v') != null;
        const splitter_flags = if (std.mem.indexOfScalar(u8, flags, 'y') != null) flags else try std.mem.concat(self.arena, u8, &.{ flags, "y" });
        const splitter = try self.construct(ctor, &.{ rx, try Value.strAlloc(self.arena, splitter_flags) });
        const lim: usize = if (limit_value.isUndefined()) std.math.maxInt(u32) else value.Value.uint32FromF64(try self.toNumberV(limit_value));
        if (lim == 0) return result;

        const size = utf16LenOfString(s);
        if (size == 0) {
            const z = try self.regexpExecGeneric(splitter, s);
            if (z.isNull()) try out.append(self.arena, try Value.strAlloc(self.arena, s));
            return result;
        }

        // Fast path for a plain built-in splitter: precompute once, share cursors
        // (one for exec conversions, one for the output segment slices) → O(n).
        const fast = self.regexpHasBuiltinExec(splitter);
        const search_input = if (fast) try self.regexpSearchInput(s, full_unicode) else "";
        const input_value = if (fast) try Value.strAlloc(self.arena, s) else Value.undef();
        const input_ascii = fast and input_value.strIsAscii();
        const input_u16 = if (fast) size else 0;
        var exec_cursor: RxCursor = .{ .ascii = input_ascii };
        var seg_cursor: RxCursor = .{ .ascii = input_ascii };

        var p: usize = 0;
        var q: usize = 0;
        while (q < size) {
            try self.setRegExpLikeLastIndex(splitter, @floatFromInt(q));
            const z = if (fast)
                try self.regexBuiltinExecWith(splitter.asObj(), s, input_value, search_input, splitter_flags, input_u16, &exec_cursor)
            else
                try self.regexpExecGeneric(splitter, s);
            if (z.isNull()) {
                q = advanceStringIndex(s, q, full_unicode);
                continue;
            }

            const e = @min(toLen(try self.toNumberV(try self.getProperty(splitter, "lastIndex"))), size);
            if (e == p) {
                q = advanceStringIndex(s, q, full_unicode);
                continue;
            }

            try self.appendSplitSegment(out, s, &seg_cursor, p, q);
            if (out.items.len >= lim) return result;

            const length = toLen(try self.toNumberV(try self.getProperty(z, "length")));
            var i: usize = 1;
            while (i < length) : (i += 1) {
                const key = try std.fmt.allocPrint(self.arena, "{d}", .{i});
                try out.append(self.arena, try self.getProperty(z, key));
                if (out.items.len >= lim) return result;
            }

            p = e;
            q = p;
        }
        try self.appendSplitSegment(out, s, &seg_cursor, p, size);
        return result;
    }

    fn regexpToString(self: *Interpreter, this: Value) EvalError!Value {
        if (!this.isObject()) return self.throwError("TypeError", "RegExp.prototype.toString called on a non-object");
        if (self.isRegExpProto(this.asObj())) return Value.str("/(?:)/");
        const src = try self.toStringWtf8(try self.getProperty(this, "source"));
        const flags = try self.toStringWtf8(try self.getProperty(this, "flags"));
        return try Value.strOwned(self.arena, try std.mem.concat(self.arena, u8, &.{ "/", src, "/", flags }));
    }

    const ms_per_day: i64 = 86400000;

    /// Build a `Date` whose time is `t` ms since the Unix epoch.
    pub fn makeDate(self: *Interpreter, t: f64) EvalError!Value {
        // TimeClip(t): a non-finite or out-of-±8.64e15 time is NaN, otherwise the
        // integer part (toward zero), with -0 normalized to +0.
        const clipped = if (std.math.isNan(t) or @abs(t) > 8.64e15) std.math.nan(f64) else blk: {
            const tr = @trunc(t);
            break :blk if (tr == 0) 0 else tr;
        };
        return self.makeDateWithRawNumber(clipped);
    }

    /// Build a DateInstance around an already-computed internal time value.
    /// Private JSC consumers use this lower boundary and intentionally bypass
    /// the ECMAScript Date-constructor TimeClip performed by `makeDate`.
    pub fn makeDateWithRawNumber(self: *Interpreter, t: f64) EvalError!Value {
        const o = (try self.newObject()).asObj();
        o.behavior.is_date = true;
        // Proto from the in-flight constructor's new.target (`new Date`, or a
        // `class extends Date` subclass), else %Date.prototype% — so
        // `Date.prototype.isPrototypeOf(d)` and `d.constructor` resolve. Date
        // methods still dispatch via the `is_date` branch in builtinMethod.
        if (self.new_target.isObject()) {
            o.setProtoAtomic(try self.ctorRealmIntrinsicProto(self.new_target.asObj(), "Date"));
        } else if (self.env.get("Date")) |ctor| {
            if (ctor.isObject()) {
                if (ctor.asObj().getOwn("prototype")) |p| {
                    if (p.isObject()) o.setProtoAtomic(p.asObj());
                }
            }
        }
        try o.initDateMs(self.arena, t);
        return Value.obj(o);
    }

    /// Civil date (year, month 1-12, day 1-31) from days since the epoch
    /// (Howard Hinnant's algorithm).
    fn civilFromDays(z0: i64) struct { y: i64, m: i64, d: i64 } {
        const z = z0 + 719468;
        const era = @divTrunc(if (z >= 0) z else z - 146096, 146097);
        const doe = z - era * 146097;
        const yoe = @divFloor(doe - @divFloor(doe, 1460) + @divFloor(doe, 36524) - @divFloor(doe, 146096), 365);
        const y = yoe + era * 400;
        const doy = doe - (365 * yoe + @divFloor(yoe, 4) - @divFloor(yoe, 100));
        const mp = @divFloor(5 * doy + 2, 153);
        const d = doy - @divFloor(153 * mp + 2, 5) + 1;
        const m = if (mp < 10) mp + 3 else mp - 9;
        return .{ .y = y + @as(i64, if (m <= 2) 1 else 0), .m = m, .d = d };
    }

    /// Clamp a signed component to a non-negative integer for `{d}` formatting
    /// (negative years/fields are out of this engine's rendered range).
    fn dnz(x: i64) u64 {
        return if (x < 0) 0 else @intCast(x);
    }

    /// Days since the epoch for a civil date (inverse of `civilFromDays`).
    fn daysFromCivil(y0: i64, m: i64, d: i64) i64 {
        const y = y0 - @as(i64, if (m <= 2) 1 else 0);
        const era = @divTrunc(if (y >= 0) y else y - 399, 400);
        const yoe = y - era * 400;
        const mp = if (m > 2) m - 3 else m + 9;
        const doy = @divFloor(153 * mp + 2, 5) + d - 1;
        const doe = yoe * 365 + @divFloor(yoe, 4) - @divFloor(yoe, 100) + doy;
        return era * 146097 + doe - 719468;
    }

    const day_names = [_][]const u8{ "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat" };
    const month_names = [_][]const u8{ "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
    const DateParts = struct { y: i64, mo: i64, d: i64, h: i64, mi: i64, s: i64, ms: i64, wday: i64 };

    /// Decompose a finite epoch-ms time into broken-down (UTC) components.
    fn dateDecompose(t: f64) DateParts {
        const ti: i64 = @intFromFloat(t);
        const days = @divFloor(ti, ms_per_day);
        const tod = @mod(ti, ms_per_day);
        const c = civilFromDays(days);
        return .{
            .y = c.y,
            .mo = c.m - 1,
            .d = c.d,
            .h = @divFloor(tod, 3600000),
            .mi = @mod(@divFloor(tod, 60000), 60),
            .s = @mod(@divFloor(tod, 1000), 60),
            .ms = @mod(tod, 1000),
            .wday = @mod(days + 4, 7),
        };
    }

    /// Render the implementation's existing Date year spelling into bounded
    /// caller storage. A clipped Date is limited to six digits, but leave room
    /// for the full i64 domain so private raw-Date embeddings cannot overflow
    /// this helper before their existing decomposition boundary.
    fn writeDateYear(y: i64, out: *[32]u8) []const u8 {
        return if (y < 0)
            std.fmt.bufPrint(out, "-{d:0>4}", .{@as(u64, @intCast(-y))}) catch unreachable
        else
            std.fmt.bufPrint(out, "{d:0>4}", .{@as(u64, @intCast(y))}) catch unreachable;
    }

    /// Format through the active precise realm's backing allocator so its
    /// managed StringCell factory can take the final bytes directly;
    /// standalone interpreters keep arena ownership.
    fn dateStringResultAllocator(self: *Interpreter) std.mem.Allocator {
        return gc_mod.temporaryAllocator(self.arena);
    }

    fn dateTimeClip(t: f64) f64 {
        if (!std.math.isFinite(t) or @abs(t) > 8.64e15) return std.math.nan(f64);
        const tr = @trunc(t);
        return if (tr == 0) 0 else tr;
    }

    /// Recompose broken-down components into an epoch-ms time, set it on `o`, and
    /// return it — the shared back half of every `Date.prototype.set*`. Out-of-range
    /// fields roll over (e.g. `setHours(0,0,0,-1)`); a non-finite or absurd field, or
    /// a result past the ±8.64e15 ms range (TimeClip), yields NaN.
    fn dateCommit(self: *Interpreter, o: *value.Object, y: f64, mo: f64, d: f64, h: f64, mi: f64, s: f64, ms: f64) EvalError!Value {
        _ = self; // [[DateValue]] now lives in the `date_ms` field, no property write
        const nan = std.math.nan(f64);
        var tf: f64 = nan;
        const fields = [_]f64{ y, mo, d, h, mi, s, ms };
        var ok = true;
        for (fields) |f| {
            if (!std.math.isFinite(f) or @abs(f) > 1e9) ok = false;
        }
        if (ok) {
            var yi: i64 = @intFromFloat(@trunc(y));
            var moi: i64 = @intFromFloat(@trunc(mo));
            yi += @divFloor(moi, 12);
            moi = @mod(moi, 12);
            const days = daysFromCivil(yi, moi + 1, @intFromFloat(@trunc(d)));
            const tod = @as(i64, @intFromFloat(@trunc(h))) * 3600000 + @as(i64, @intFromFloat(@trunc(mi))) * 60000 +
                @as(i64, @intFromFloat(@trunc(s))) * 1000 + @as(i64, @intFromFloat(@trunc(ms)));
            tf = @as(f64, @floatFromInt(days)) * @as(f64, @floatFromInt(ms_per_day)) + @as(f64, @floatFromInt(tod));
            if (@abs(tf) > 8.64e15) tf = nan;
        }
        o.setDateMs(tf);
        return Value.num(tf);
    }

    /// `Date.prototype` methods (UTC-based; v1 ignores local timezone, so
    /// get*/getUTC* coincide). Time is the internal-slot field `date_ms`.
    fn dateMethod(self: *Interpreter, o: *value.Object, name: []const u8, args: []const Value) EvalError!?Value {
        const t = o.dateMs();
        const nan = std.math.nan(f64);
        if (eq(name, "getTime") or eq(name, "valueOf")) return Value.num(t);
        // toLocale{,Date,Time}String(locales, options) === new Intl.DateTimeFormat
        // (locales, options).format(this), with the method's required/defaults.
        if (eq(name, "toLocaleString") or eq(name, "toLocaleDateString") or eq(name, "toLocaleTimeString")) {
            if (std.math.isNan(t)) return Value.str("Invalid Date");
            const required: DtfRequired = if (eq(name, "toLocaleDateString")) .date else if (eq(name, "toLocaleTimeString")) .time else .any;
            const defaults: DtfDefaults = if (eq(name, "toLocaleDateString")) .date else if (eq(name, "toLocaleTimeString")) .time else .all;
            const dtf = (try self.newObject()).asObj();
            const locs = try canonicalizeLocaleList(self, if (args.len > 0) args[0] else Value.undef());
            const loc = localeListFirstOr(locs, "en");
            const r = try dtfProcessOptionsKind(self, if (args.len > 1) args[1] else Value.undef(), required, defaults);
            try dtfStoreOptions(self, dtf, loc, r, false);
            return try intlDateTimeFormatFn(@ptrCast(self), Value.obj(dtf), &.{Value.num(t)});
        }
        if (eq(name, "setTime")) {
            var nt = try self.toNumberV(arg0(args));
            if (@abs(nt) > 8.64e15) nt = nan;
            o.setDateMs(nt);
            return Value.num(nt);
        }

        // ---- setters ----------------------------------------------------------
        if (std.mem.startsWith(u8, name, "set")) {
            const fy = eq(name, "setFullYear") or eq(name, "setUTCFullYear");
            const sy = eq(name, "setYear"); // Annex B B.2.4.2 (revives like setFullYear)
            const setter_arity: usize = if (fy) 3 else if (sy) 1 else if (eq(name, "setMonth") or eq(name, "setUTCMonth")) 2 else if (eq(name, "setDate") or eq(name, "setUTCDate")) 1 else if (eq(name, "setHours") or eq(name, "setUTCHours")) 4 else if (eq(name, "setMinutes") or eq(name, "setUTCMinutes")) 3 else if (eq(name, "setSeconds") or eq(name, "setUTCSeconds")) 2 else if (eq(name, "setMilliseconds") or eq(name, "setUTCMilliseconds")) 1 else 0;
            if (setter_arity == 0) return null;
            // Each setter converts only the arguments named by its ECMA-262
            // algorithm. Extra arguments are unobservable. Keep the at-most-four
            // converted values in native storage: the DateValue was captured in
            // `t` above, and in-arity values still convert once, left-to-right,
            // before any store, including when the date is invalid.
            var converted: [4]Value = @splat(Value.undef());
            const converted_len = @min(args.len, setter_arity);
            for (args[0..converted_len], 0..) |av, idx|
                converted[idx] = Value.num(try self.toNumberV(av));
            const a = converted[0..converted_len];
            // Non-fullyear setters on an invalid date stay invalid (arguments were
            // still coerced above); setFullYear revives it from a zero base.
            if (std.math.isNan(t) and !fy and !sy) return Value.num(nan);
            const c = dateDecompose(if (std.math.isNan(t)) 0 else t);
            var y: f64 = @floatFromInt(c.y);
            var mo: f64 = @floatFromInt(c.mo);
            var d: f64 = @floatFromInt(c.d);
            var h: f64 = @floatFromInt(c.h);
            var mi: f64 = @floatFromInt(c.mi);
            var s: f64 = @floatFromInt(c.s);
            var ms: f64 = @floatFromInt(c.ms);
            if (fy) {
                y = arg0(a).toNumber();
                if (a.len > 1) mo = a[1].toNumber();
                if (a.len > 2) d = a[2].toNumber();
                return try self.dateCommit(o, y, mo, d, h, mi, s, ms);
            }
            if (sy) {
                const yv = arg0(a).toNumber();
                if (std.math.isNan(yv)) {
                    o.setDateMs(nan);
                    return Value.num(nan);
                }
                const yi = @trunc(yv);
                y = if (yi >= 0 and yi <= 99) 1900 + yi else yv;
                return try self.dateCommit(o, y, mo, d, h, mi, s, ms);
            }
            if (eq(name, "setMonth") or eq(name, "setUTCMonth")) {
                mo = arg0(a).toNumber();
                if (a.len > 1) d = a[1].toNumber();
                return try self.dateCommit(o, y, mo, d, h, mi, s, ms);
            }
            if (eq(name, "setDate") or eq(name, "setUTCDate")) {
                d = arg0(a).toNumber();
                return try self.dateCommit(o, y, mo, d, h, mi, s, ms);
            }
            if (eq(name, "setHours") or eq(name, "setUTCHours")) {
                h = arg0(a).toNumber();
                if (a.len > 1) mi = a[1].toNumber();
                if (a.len > 2) s = a[2].toNumber();
                if (a.len > 3) ms = a[3].toNumber();
                return try self.dateCommit(o, y, mo, d, h, mi, s, ms);
            }
            if (eq(name, "setMinutes") or eq(name, "setUTCMinutes")) {
                mi = arg0(a).toNumber();
                if (a.len > 1) s = a[1].toNumber();
                if (a.len > 2) ms = a[2].toNumber();
                return try self.dateCommit(o, y, mo, d, h, mi, s, ms);
            }
            if (eq(name, "setSeconds") or eq(name, "setUTCSeconds")) {
                s = arg0(a).toNumber();
                if (a.len > 1) ms = a[1].toNumber();
                return try self.dateCommit(o, y, mo, d, h, mi, s, ms);
            }
            if (eq(name, "setMilliseconds") or eq(name, "setUTCMilliseconds")) {
                ms = arg0(a).toNumber();
                return try self.dateCommit(o, y, mo, d, h, mi, s, ms);
            }
        }

        // ---- string conversions ----------------------------------------------
        if (eq(name, "toISOString")) {
            if (!std.math.isFinite(t) or @abs(t) > 8.64e15) return self.throwError("RangeError", "Invalid time value");
            return try self.dateISOStringValue(t);
        }
        if (eq(name, "toJSON")) {
            // The Date-receiver fast path (the generic `dateToJSONFn` native
            // handles a borrowed/non-Date `this`): a non-finite time is null.
            if (!std.math.isFinite(t) or @abs(t) > 8.64e15) return Value.nul();
            return try self.dateISOStringValue(t);
        }
        if (eq(name, "toUTCString") or eq(name, "toGMTString")) {
            if (std.math.isNan(t)) return Value.str("Invalid Date");
            const c = dateDecompose(t);
            var year_buffer: [32]u8 = undefined;
            const year = writeDateYear(c.y, &year_buffer);
            const allocator = self.dateStringResultAllocator();
            return try Value.strOwned(allocator, try std.fmt.allocPrint(allocator, "{s}, {d:0>2} {s} {s} {d:0>2}:{d:0>2}:{d:0>2} GMT", .{
                day_names[@intCast(c.wday)], dnz(c.d), month_names[@intCast(c.mo)], year, dnz(c.h), dnz(c.mi), dnz(c.s),
            }));
        }
        if (eq(name, "toDateString") or eq(name, "toString") or eq(name, "toTimeString")) {
            if (std.math.isNan(t)) return Value.str("Invalid Date");
            const c = dateDecompose(t);
            var year_buffer: [32]u8 = undefined;
            const year = writeDateYear(c.y, &year_buffer);
            const allocator = self.dateStringResultAllocator();
            // ECMA-262 Date string methods first obtain the complete result and
            // return that one String value. Format only the selected method's
            // fields and transfer the exact final buffer into its StringCell.
            if (eq(name, "toDateString"))
                return try Value.strOwned(allocator, try std.fmt.allocPrint(allocator, "{s} {s} {d:0>2} {s}", .{
                    day_names[@intCast(c.wday)], month_names[@intCast(c.mo)], dnz(c.d), year,
                }));
            if (eq(name, "toTimeString"))
                return try Value.strOwned(allocator, try std.fmt.allocPrint(allocator, "{d:0>2}:{d:0>2}:{d:0>2} GMT+0000 (Coordinated Universal Time)", .{
                    dnz(c.h), dnz(c.mi), dnz(c.s),
                }));
            return try Value.strOwned(allocator, try std.fmt.allocPrint(allocator, "{s} {s} {d:0>2} {s} {d:0>2}:{d:0>2}:{d:0>2} GMT+0000 (Coordinated Universal Time)", .{
                day_names[@intCast(c.wday)], month_names[@intCast(c.mo)], dnz(c.d), year, dnz(c.h), dnz(c.mi), dnz(c.s),
            }));
        }

        // ---- getters ----------------------------------------------------------
        if (std.math.isNan(t)) return Value.num(nan);
        const ti: i64 = @intFromFloat(t);
        const days = @divFloor(ti, ms_per_day);
        const tod = @mod(ti, ms_per_day);
        const c = civilFromDays(days);
        if (eq(name, "getFullYear") or eq(name, "getUTCFullYear")) return Value.num(@floatFromInt(c.y));
        if (eq(name, "getYear")) return Value.num(@floatFromInt(c.y - 1900)); // Annex B B.2.4.1
        if (eq(name, "getMonth") or eq(name, "getUTCMonth")) return Value.num(@floatFromInt(c.m - 1));
        if (eq(name, "getDate") or eq(name, "getUTCDate")) return Value.num(@floatFromInt(c.d));
        if (eq(name, "getDay") or eq(name, "getUTCDay")) return Value.num(@floatFromInt(@mod(days + 4, 7)));
        if (eq(name, "getHours") or eq(name, "getUTCHours")) return Value.num(@floatFromInt(@divFloor(tod, 3600000)));
        if (eq(name, "getMinutes") or eq(name, "getUTCMinutes")) return Value.num(@floatFromInt(@mod(@divFloor(tod, 60000), 60)));
        if (eq(name, "getSeconds") or eq(name, "getUTCSeconds")) return Value.num(@floatFromInt(@mod(@divFloor(tod, 1000), 60)));
        if (eq(name, "getMilliseconds") or eq(name, "getUTCMilliseconds")) return Value.num(@floatFromInt(@mod(tod, 1000)));
        if (eq(name, "getTimezoneOffset")) return Value.num(0);
        return null;
    }

    /// Write exact ECMAScript UTC ISO text into a caller-owned 28-byte buffer.
    /// Ordinary years use 24 bytes and extended years use 27; no terminator is
    /// written. Invalid Date time values leave the caller buffer untouched.
    pub fn writeDateISOString(t: f64, out: *[28]u8) ?usize {
        if (!std.math.isFinite(t) or @abs(t) > 8.64e15) return null;
        const c = dateDecompose(t);
        var buffer: [28]u8 = undefined;
        const rendered = if (c.y >= 0 and c.y <= 9999)
            std.fmt.bufPrint(&buffer, "{d:0>4}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}.{d:0>3}Z", .{
                dnz(c.y), dnz(c.mo + 1), dnz(c.d), dnz(c.h), dnz(c.mi), dnz(c.s), dnz(c.ms),
            }) catch return null
        else if (c.y < 0)
            std.fmt.bufPrint(&buffer, "-{d:0>6}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}.{d:0>3}Z", .{
                @as(u64, @intCast(-c.y)), dnz(c.mo + 1), dnz(c.d), dnz(c.h), dnz(c.mi), dnz(c.s), dnz(c.ms),
            }) catch return null
        else
            std.fmt.bufPrint(&buffer, "+{d:0>6}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}.{d:0>3}Z", .{
                @as(u64, @intCast(c.y)), dnz(c.mo + 1), dnz(c.d), dnz(c.h), dnz(c.mi), dnz(c.s), dnz(c.ms),
            }) catch return null;
        @memcpy(out[0..rendered.len], rendered);
        return rendered.len;
    }

    /// Turn the stack-rendered ISO image into one owned runtime string. The
    /// caller has already applied the toISOString/toJSON invalid-time rule.
    fn dateISOStringValue(self: *Interpreter, t: f64) EvalError!Value {
        var buffer: [28]u8 = undefined;
        const len = writeDateISOString(t, &buffer) orelse unreachable;
        const allocator = self.dateStringResultAllocator();
        return Value.strOwned(allocator, try allocator.dupe(u8, buffer[0..len]));
    }

    /// Compute a Date's epoch-ms from constructor arguments.
    pub fn dateTimeFromArgs(args: []const Value) f64 {
        if (args.len == 0) return 0; // (a real clock isn't wired; epoch is deterministic)
        if (args.len == 1) return dateTimeClip(args[0].toNumber());
        const nan = std.math.nan(f64);
        const fields = [_]f64{
            args[0].toNumber(),
            args[1].toNumber(),
            if (args.len > 2) args[2].toNumber() else 1,
            if (args.len > 3) args[3].toNumber() else 0,
            if (args.len > 4) args[4].toNumber() else 0,
            if (args.len > 5) args[5].toNumber() else 0,
            if (args.len > 6) args[6].toNumber() else 0,
        };
        for (fields) |f| if (!std.math.isFinite(f)) return nan;
        const y_f = @trunc(fields[0]);
        const mo_f = @trunc(fields[1]);
        const d_f = @trunc(fields[2]);
        const h = @trunc(fields[3]);
        const mi = @trunc(fields[4]);
        const s = @trunc(fields[5]);
        const millis = @trunc(fields[6]);
        if (@abs(y_f) > 1_000_000 or @abs(mo_f) > 12_000_000) return nan;
        var y: i64 = @intFromFloat(y_f);
        var mo: i64 = @intFromFloat(mo_f);
        y += @divFloor(mo, 12);
        mo = @mod(mo, 12);
        const month_start: f64 = @floatFromInt(daysFromCivil(y, mo + 1, 1));
        const day = month_start + d_f - 1;
        const time = ((h * 3_600_000 + mi * 60_000) + s * 1000) + millis;
        return dateTimeClip(day * @as(f64, @floatFromInt(ms_per_day)) + time);
    }

    /// Build a `Map`, optionally populated from an iterable of `[k,v]` pairs.
    /// Whether `start`'s [[Prototype]] chain reaches the named constructor's
    /// `.prototype` — used to tell a WeakMap/WeakSet (whose chain includes
    /// %WeakMap.prototype%/%WeakSet.prototype%) from a Map/Set, including
    /// subclasses, since both kinds share the `is_map`/`is_set` storage.
    fn protoReachesCtorProto(self: *Interpreter, ctor_name: []const u8, start: ?*value.Object) bool {
        const cv = self.env.get(ctor_name) orelse return false;
        if (!cv.isObject()) return false;
        const wp = cv.asObj().getOwn("prototype") orelse return false;
        if (!wp.isObject()) return false;
        var cur = start;
        while (cur) |c| : (cur = c.protoAtomic()) {
            if (c == wp.asObj()) return true;
        }
        return false;
    }

    pub fn makeMap(self: *Interpreter, init_v: Value) EvalError!Value {
        return self.makeMapWithIntrinsic(init_v, "Map");
    }

    /// Issue one unpredictable seed for an attacker-controlled native hash
    /// table. Builtins with invocation-local side indexes share this stream so
    /// they inherit the same fail-closed entropy boundary as Map/Set storage.
    pub fn newSecureHashSeed(self: *Interpreter) EvalError!u64 {
        if (!self.secure_hash_prng_seeded) {
            var bytes: [8]u8 = undefined;
            // Hash tables on attacker-controlled content are an algorithmic-
            // complexity boundary. Fail if the host cannot supply entropy; a
            // predictable clock/thread fallback silently restores adversarial
            // placement.
            agent.engineIo().randomSecure(&bytes) catch return error.OutOfMemory;
            const seed = std.mem.readInt(u64, &bytes, .little);
            self.secure_hash_prng = std.Random.DefaultPrng.init(seed);
            self.secure_hash_prng_seeded = true;
        }
        return self.secure_hash_prng.random().int(u64);
    }

    pub fn prepareStrongCollection(self: *Interpreter, o: *value.Object) EvalError!void {
        if (o.collHashSeed() != null) return;
        _ = try o.ensureStrongCollectionState(self.arena, try self.newSecureHashSeed());
    }

    pub fn prepareWeakCollection(self: *Interpreter, o: *value.Object) EvalError!void {
        if (o.collHashSeed() != null) return;
        _ = try o.ensureWeakCollectionState(self.arena, try self.newSecureHashSeed());
    }

    fn noteWeakWork(self: *Interpreter) void {
        if (self.gc_weak_work) |flag| flag.store(true, .release);
    }

    pub fn makeWeakMap(self: *Interpreter, init_v: Value) EvalError!Value {
        return self.makeMapWithIntrinsic(init_v, "WeakMap");
    }

    fn makeMapWithIntrinsic(self: *Interpreter, init_v: Value, intrinsic: []const u8) EvalError!Value {
        const o = (try self.newObject()).asObj();
        o.is_map = true;
        if (self.new_target.isObject()) {
            o.setProtoAtomic(try self.ctorRealmIntrinsicProto(self.new_target.asObj(), intrinsic));
        } else if (self.env.get("Map")) |ctor| {
            if (ctor.isObject()) {
                if (ctor.asObj().getOwn("prototype")) |p| {
                    if (p.isObject()) o.setProtoAtomic(p.asObj());
                }
            }
        }
        o.is_weak = self.protoReachesCtorProto("WeakMap", o.protoAtomic());
        if (o.is_weak) {
            self.noteWeakWork();
        } else {
            // A strong collection always owns its seeded index state. Failing
            // construction is preferable to later publishing an index that
            // omits entries inserted during an earlier sidecar OOM.
            try self.prepareStrongCollection(o);
        }
        try self.addEntriesFromIterable(o, init_v, false);
        return Value.obj(o);
    }

    /// Build a `Set`, optionally populated from an iterable of values.
    pub fn makeSet(self: *Interpreter, init_v: Value) EvalError!Value {
        return self.makeSetWithIntrinsic(init_v, "Set");
    }

    pub fn makeWeakSet(self: *Interpreter, init_v: Value) EvalError!Value {
        return self.makeSetWithIntrinsic(init_v, "WeakSet");
    }

    fn makeSetWithIntrinsic(self: *Interpreter, init_v: Value, intrinsic: []const u8) EvalError!Value {
        const o = (try self.newObject()).asObj();
        o.is_set = true;
        // Proto from the in-flight constructor (`new Set`/`new WeakSet`), so a
        // WeakSet doesn't inherit Set.prototype; internal results default to Set.
        if (self.new_target.isObject()) {
            o.setProtoAtomic(try self.ctorRealmIntrinsicProto(self.new_target.asObj(), intrinsic));
        } else if (self.env.get("Set")) |ctor| {
            if (ctor.isObject()) {
                if (ctor.asObj().getOwn("prototype")) |p| {
                    if (p.isObject()) o.setProtoAtomic(p.asObj());
                }
            }
        }
        o.is_weak = self.protoReachesCtorProto("WeakSet", o.protoAtomic());
        if (o.is_weak) {
            self.noteWeakWork();
        } else {
            try self.prepareStrongCollection(o);
        }
        try self.addEntriesFromIterable(o, init_v, true);
        return Value.obj(o);
    }

    /// Map's AddEntriesFromIterable and the Set constructor's add loop: drain
    /// `iterable` through its iterator protocol, invoking the instance's own
    /// `set`/`add` (so a user override and the WeakMap/WeakSet variants are
    /// honored). A non-callable adder, a non-iterable argument, or — for a Map —
    /// a non-object entry is a TypeError; any abrupt completion mid-iteration
    /// closes the iterator (preserving the original exception) before propagating.
    fn addEntriesFromIterable(self: *Interpreter, o: *value.Object, iterable: Value, is_set: bool) EvalError!void {
        if (iterable.isUndefined() or iterable.isNull()) return;
        const adder = try self.getProperty(Value.obj(o), if (is_set) "add" else "set");
        if (!adder.isCallable())
            return self.throwError("TypeError", if (is_set) "Set add method is not callable" else "Map set method is not callable");
        const iter = try self.iteratorOf(iterable);
        while (true) {
            const r = try self.callMethod(iter, "next", &.{});
            if (!builtins.isRealObject(r)) return self.throwError("TypeError", "iterator.next() did not return an object");
            if ((try self.getProperty(r, "done")).toBoolean()) break;
            const item = try self.getProperty(r, "value");
            self.addOneEntry(o, adder, item, is_set) catch |e| {
                // IteratorClose, keeping the original abrupt completion's value.
                const saved = self.exception;
                self.iteratorClose(iter) catch {};
                self.exception = saved;
                return e;
            };
        }
    }

    /// Add one drained iterator value to the collection via `adder` (bound to
    /// `o`). For a Map the value must be an entry object `{0: key, 1: value}`.
    fn addOneEntry(self: *Interpreter, o: *value.Object, adder: Value, item: Value, is_set: bool) EvalError!void {
        const self_v = Value.obj(o);
        if (is_set) {
            _ = try self.callValueWithThis(adder, &.{item}, self_v);
            return;
        }
        if (!builtins.isRealObject(item)) return self.throwError("TypeError", "Iterator value is not an entry object");
        const k = try self.getProperty(item, "0");
        const v = try self.getProperty(item, "1");
        _ = try self.callValueWithThis(adder, &.{ k, v }, self_v);
    }

    fn mapMethod(self: *Interpreter, o: *value.Object, name: []const u8, args: []const Value) EvalError!?Value {
        const self_v = Value.obj(o);
        const key = canonicalCollectionKey(arg0(args));
        // A WeakMap key (`set`/`getOrInsert`/`getOrInsertComputed`) must be a
        // value that can be held weakly — an object or a (non-registered) symbol;
        // a primitive throws before any insertion or callback runs.
        if (o.is_weak and (eq(name, "set") or eq(name, "getOrInsert") or eq(name, "getOrInsertComputed"))) {
            if (!canBeHeldWeakly(arg0(args)))
                return self.throwError("TypeError", "Invalid value used as WeakMap key");
        }
        if (o.is_weak) {
            const key_obj = weakKeyPtr(key);
            // weak_entries access goes through the elements_lock'd helpers so a
            // concurrent GC marker reading them never races an append/remove.
            if (eq(name, "set")) {
                try self.prepareWeakCollection(o);
                try o.weakEntrySet(self.arena, key_obj, arg(args, 1));
                return self_v;
            }
            if (eq(name, "get")) {
                return o.weakEntryGet(key_obj) orelse Value.undef();
            }
            if (eq(name, "has")) {
                return Value.boolVal(o.weakEntryHas(key_obj));
            }
            if (eq(name, "delete")) {
                return Value.boolVal(o.weakEntryDelete(key_obj));
            }
            if (eq(name, "getOrInsert") or eq(name, "getOrInsertComputed")) {
                const cb = if (eq(name, "getOrInsertComputed")) cb: {
                    const candidate = arg(args, 1);
                    if (!candidate.isCallable()) return self.throwError("TypeError", "Map.prototype.getOrInsertComputed: callback is not a function");
                    break :cb candidate;
                } else Value.undef();
                if (o.weakEntryGet(key_obj)) |existing| return existing;
                // The callback runs with no lock held (it may re-enter the map);
                // the upsert then keeps existing-entry-wins semantics.
                const v = if (eq(name, "getOrInsertComputed")) try self.callValue(cb, &.{key}) else arg(args, 1);
                try self.prepareWeakCollection(o);
                try o.weakEntrySet(self.arena, key_obj, v);
                return v;
            }
            return null;
        }
        if (eq(name, "set")) {
            const val = arg(args, 1);
            const pair = (try self.newArray()).asObj();
            try pair.appendElement(self.arena, key);
            try pair.appendElement(self.arena, val);
            const elements_locked_1 = o.lockElements();
            defer o.unlockElements(elements_locked_1);
            if (mapFindPos(o, key, self.arena)) |pos| {
                _ = liveMapEntry(o.elementsItems()[pos]).?.setElementAt(1, val);
                return self_v;
            }
            gc_mod.barrierCellFrom(o, @ptrCast(pair)); // new entry hidden behind the live map
            const elements = try o.ensureElementsList(self.arena);
            const pos: u32 = @intCast(elements.items.len);
            const serial = try o.collPrepareInsert(self.arena);
            try elements.append(o.elementsAllocator(self.arena), Value.obj(pair));
            o.collCommitInsert(serial);
            if (!o.collUnindexed()) if (o.collHashSeed()) |seed| {
                const hkey = hashKey(seed, key);
                if (!o.collIndexPut(self.arena, hkey, pos)) o.collDisableIndex(self.arena);
            };
            return self_v;
        }
        if (eq(name, "get")) {
            const elements_locked_2 = o.lockElements();
            defer o.unlockElements(elements_locked_2);
            if (mapFindPos(o, key, self.arena)) |pos| return mapEntryValue(liveMapEntry(o.elementsItems()[pos]).?);
            return Value.undef();
        }
        if (eq(name, "has")) {
            const elements_locked_3 = o.lockElements();
            defer o.unlockElements(elements_locked_3);
            return Value.boolVal(mapFindPos(o, key, self.arena) != null);
        }
        if (eq(name, "delete")) {
            const elements_locked_4 = o.lockElements();
            defer o.unlockElements(elements_locked_4);
            if (mapFindPos(o, key, self.arena)) |pos| {
                liveMapEntry(o.elementsItems()[pos]).?.clearElementsRetainingCapacity();
                o.collRecordDelete();
                if (!o.collUnindexed()) if (o.collHashSeed()) |seed|
                    o.collIndexRemove(hashKey(seed, key), @intCast(pos));
                maybeCompactStrongCollection(o, self.arena);
                return Value.boolVal(true);
            }
            return Value.boolVal(false);
        }
        if (eq(name, "clear")) {
            o.clearStrongCollection(self.arena);
            return Value.undef();
        }
        if (eq(name, "forEach")) {
            const cb = arg0(args);
            if (!cb.isCallable()) return self.throwError("TypeError", "Map.prototype.forEach callback is not callable");
            var next_serial: u64 = 0;
            var next_pos: usize = 0;
            var layout_generation: ?u64 = null;
            while (true) {
                var found = false;
                var entry_key: Value = Value.undef();
                var entry_value: Value = Value.undef();
                const elements_locked_5 = o.lockElements();
                var pos = o.collCursorStart(next_serial, next_pos, layout_generation);
                layout_generation = o.collLayoutGeneration();
                while (pos < o.elementsItems().len) : (pos += 1) {
                    const serial = o.collSerialAt(pos);
                    next_serial = serial + 1;
                    next_pos = pos + 1;
                    const entry = liveMapEntry(o.elementsItems()[pos]) orelse continue;
                    entry_key = entry.elementAt(0) orelse Value.undef();
                    entry_value = mapEntryValue(entry);
                    found = true;
                    break;
                }
                o.unlockElements(elements_locked_5);
                if (!found) break;
                _ = try self.callValueWithThis(cb, &.{ entry_value, entry_key, self_v }, arg(args, 1));
            }
            return Value.undef();
        }
        // Upsert proposal: return the existing value for `key`, else insert and
        // return a default (`getOrInsert`) or a computed value (`getOrInsertComputed`).
        if (eq(name, "getOrInsert") or eq(name, "getOrInsertComputed")) {
            const cb = if (eq(name, "getOrInsertComputed")) cb: {
                const candidate = arg(args, 1);
                if (!candidate.isCallable()) return self.throwError("TypeError", "Map.prototype.getOrInsertComputed: callback is not a function");
                break :cb candidate;
            } else Value.undef();
            {
                const elements_locked_6 = o.lockElements();
                defer o.unlockElements(elements_locked_6);
                if (mapFindPos(o, key, self.arena)) |pos| return mapEntryValue(liveMapEntry(o.elementsItems()[pos]).?);
            }
            const v = if (eq(name, "getOrInsertComputed")) blk: {
                break :blk try self.callValue(cb, &.{key});
            } else arg(args, 1);
            _ = try self.mapMethod(o, "set", &.{ key, v });
            return v;
        }
        if (eq(name, "keys") or eq(name, "values") or eq(name, "entries"))
            return try self.makeCursorIteratorWithKind(self_v, collectionIterKind(name));
        return null;
    }

    /// Private embedding boundary for native Map cells. These helpers bypass
    /// mutable userland Map.prototype methods and operate on [[MapData]] through
    /// the same internal implementation as the builtins.
    pub fn createNativeMap(self: *Interpreter) EvalError!Value {
        return self.makeMap(Value.undef());
    }

    pub fn nativeMapGet(self: *Interpreter, map: *value.Object, key: Value) EvalError!Value {
        return (try self.mapMethod(map, "get", &.{key})) orelse Value.undef();
    }

    pub fn nativeMapHas(self: *Interpreter, map: *value.Object, key: Value) EvalError!bool {
        return ((try self.mapMethod(map, "has", &.{key})) orelse Value.boolVal(false)).toBoolean();
    }

    pub fn nativeMapRemove(self: *Interpreter, map: *value.Object, key: Value) EvalError!bool {
        return ((try self.mapMethod(map, "delete", &.{key})) orelse Value.boolVal(false)).toBoolean();
    }

    pub fn nativeMapSet(self: *Interpreter, map: *value.Object, key: Value, stored_value: Value) EvalError!void {
        _ = (try self.mapMethod(map, "set", &.{ key, stored_value })) orelse Value.undef();
    }

    pub fn nativeMapClear(self: *Interpreter, map: *value.Object) EvalError!void {
        _ = (try self.mapMethod(map, "clear", &.{})) orelse Value.undef();
    }

    pub fn nativeMapSize(_: *Interpreter, map: *value.Object) usize {
        return liveMapEntryCount(map);
    }

    pub fn nativeSetSize(_: *Interpreter, set: *value.Object) usize {
        return liveSetEntryCount(set);
    }

    pub fn nativeSetAdd(self: *Interpreter, set: *value.Object, key: Value) EvalError!void {
        _ = (try self.setMethod(set, "add", &.{key})) orelse Value.undef();
    }

    fn setMethod(self: *Interpreter, o: *value.Object, name: []const u8, args: []const Value) EvalError!?Value {
        const self_v = Value.obj(o);
        // A WeakSet value must be holdable weakly (object or non-registered
        // symbol); a primitive throws before insertion.
        if (o.is_weak and eq(name, "add") and !canBeHeldWeakly(arg0(args)))
            return self.throwError("TypeError", "Invalid value used in WeakSet");
        const key = canonicalCollectionKey(arg0(args));
        if (o.is_weak) {
            const key_obj = weakKeyPtr(key);
            // elements_lock'd helpers — race-free against a concurrent GC marker.
            if (eq(name, "add")) {
                try self.prepareWeakCollection(o);
                try o.weakEntryAdd(self.arena, key_obj);
                return self_v;
            }
            if (eq(name, "has")) {
                return Value.boolVal(o.weakEntryHas(key_obj));
            }
            if (eq(name, "delete")) {
                return Value.boolVal(o.weakEntryDelete(key_obj));
            }
            return null;
        }
        if (eq(name, "add")) {
            const elements_locked_7 = o.lockElements();
            defer o.unlockElements(elements_locked_7);
            if (setFindPos(o, key, self.arena) != null) return self_v;
            gc_mod.barrierValueFrom(o, key); // new key hidden behind the live set
            const elements = try o.ensureElementsList(self.arena);
            const pos: u32 = @intCast(elements.items.len);
            const serial = try o.collPrepareInsert(self.arena);
            try elements.append(o.elementsAllocator(self.arena), key);
            o.collCommitInsert(serial);
            if (!o.collUnindexed()) if (o.collHashSeed()) |seed| {
                const hkey = hashKey(seed, key);
                if (!o.collIndexPut(self.arena, hkey, pos)) o.collDisableIndex(self.arena);
            };
            return self_v;
        }
        if (eq(name, "has")) {
            const elements_locked_8 = o.lockElements();
            defer o.unlockElements(elements_locked_8);
            return Value.boolVal(setFindPos(o, key, self.arena) != null);
        }
        if (eq(name, "delete")) {
            const tomb = try gc_mod.allocObj(self.arena);
            tomb.* = .{ .behavior = .{ .is_set_deleted = true } };
            const elements_locked_9 = o.lockElements();
            defer o.unlockElements(elements_locked_9);
            if (setFindPos(o, key, self.arena)) |pos| {
                o.elementsItems()[pos] = Value.obj(tomb);
                o.collRecordDelete();
                if (!o.collUnindexed()) if (o.collHashSeed()) |seed|
                    o.collIndexRemove(hashKey(seed, key), @intCast(pos));
                maybeCompactStrongCollection(o, self.arena);
                return Value.boolVal(true);
            }
            return Value.boolVal(false);
        }
        if (eq(name, "clear")) {
            o.clearStrongCollection(self.arena);
            return Value.undef();
        }
        if (eq(name, "forEach")) {
            const cb = arg0(args);
            if (!cb.isCallable()) return self.throwError("TypeError", "Set.prototype.forEach callback is not callable");
            var next_serial: u64 = 0;
            var next_pos: usize = 0;
            var layout_generation: ?u64 = null;
            while (true) {
                var live_entry: ?Value = null;
                const elements_locked_10 = o.lockElements();
                var pos = o.collCursorStart(next_serial, next_pos, layout_generation);
                layout_generation = o.collLayoutGeneration();
                while (pos < o.elementsItems().len) : (pos += 1) {
                    const serial = o.collSerialAt(pos);
                    next_serial = serial + 1;
                    next_pos = pos + 1;
                    live_entry = liveSetEntry(o.elementsItems()[pos]) orelse continue;
                    break;
                }
                o.unlockElements(elements_locked_10);
                if (live_entry == null) break;
                _ = try self.callValueWithThis(cb, &.{ live_entry.?, live_entry.?, self_v }, arg(args, 1));
            }
            return Value.undef();
        }
        // ES2024 set-operation methods. They take a set-like argument (the
        // set-record protocol: `size`, `has`, `keys`) and either return a new
        // Set (union/intersection/difference/symmetricDifference) or a boolean.
        const is_setop = eq(name, "union") or eq(name, "intersection") or eq(name, "difference") or
            eq(name, "symmetricDifference") or eq(name, "isSubsetOf") or eq(name, "isSupersetOf") or
            eq(name, "isDisjointFrom");
        if (is_setop) {
            const rec = try self.getSetRecord(arg0(args));
            if (eq(name, "union")) {
                var other_iter: Value = Value.undef();
                var other_next: Value = Value.undef();
                const other_keys = if (rec.is_set) try self.collectSetKeys(rec) else blk: {
                    other_iter = try self.callValueWithThis(rec.keys, &.{}, Value.obj(rec.obj));
                    if (!builtins.isRealObject(other_iter)) return self.throwError("TypeError", "iterator.next() did not return an object");
                    other_next = try self.getProperty(other_iter, "next");
                    break :blk &[_]Value{};
                };
                const result = (try self.makeSet(Value.undef())).asObj();
                for (try self.collectLiveSetEntries(o)) |entry| {
                    _ = try self.setMethod(result, "add", &.{entry});
                }
                if (rec.is_set) {
                    for (other_keys) |k| _ = try self.setMethod(result, "add", &.{k});
                } else {
                    while (true) {
                        const r = try self.callValueWithThis(other_next, &.{}, other_iter);
                        if (!builtins.isRealObject(r)) return self.throwError("TypeError", "iterator.next() did not return an object");
                        if ((try self.getProperty(r, "done")).toBoolean()) break;
                        _ = try self.setMethod(result, "add", &.{try self.getProperty(r, "value")});
                    }
                }
                return Value.obj(result);
            }
            const this_size: f64 = @floatFromInt(liveSetEntryCount(o));
            if (eq(name, "intersection")) {
                const result = (try self.makeSet(Value.undef())).asObj();
                if (this_size <= rec.size) {
                    // Smaller `this`: walk this, probe the other set's `has`.
                    var i: usize = 0;
                    while (i < o.elementsLen()) : (i += 1) {
                        const entry = liveSetEntryAt(o, i) orelse continue;
                        if (try self.recordHas(rec, entry)) _ = try self.setMethod(result, "add", &.{entry});
                    }
                } else {
                    // Smaller other: walk the other set's keys, keep those in this.
                    if (rec.is_set) {
                        for (try self.collectSetKeys(rec)) |k| {
                            if (setContains(o, k)) _ = try self.setMethod(result, "add", &.{k});
                        }
                    } else {
                        const iter = try self.callValueWithThis(rec.keys, &.{}, Value.obj(rec.obj));
                        const next_m = try self.getProperty(iter, "next");
                        while (true) {
                            const r = try self.callValueWithThis(next_m, &.{}, iter);
                            if (!builtins.isRealObject(r)) return self.throwError("TypeError", "iterator.next() did not return an object");
                            if ((try self.getProperty(r, "done")).toBoolean()) break;
                            const k = try self.getProperty(r, "value");
                            if (setContains(o, k)) _ = try self.setMethod(result, "add", &.{k});
                        }
                    }
                }
                return Value.obj(result);
            }
            if (eq(name, "difference")) {
                // result starts as a copy of this; the smaller operand drives the walk.
                const result = (try self.makeSet(Value.undef())).asObj();
                for (try self.collectLiveSetEntries(o)) |entry| {
                    _ = try self.setMethod(result, "add", &.{entry});
                }
                if (this_size <= rec.size) {
                    var i: usize = 0;
                    while (i < result.elementsLen()) : (i += 1) {
                        const entry = liveSetEntryAt(result, i) orelse continue;
                        if (try self.recordHas(rec, entry)) _ = try self.setMethod(result, "delete", &.{entry});
                    }
                } else {
                    for (try self.collectSetKeys(rec)) |k| {
                        _ = try self.setMethod(result, "delete", &.{k});
                    }
                }
                return Value.obj(result);
            }
            if (eq(name, "symmetricDifference")) {
                var other_iter: Value = Value.undef();
                var other_next: Value = Value.undef();
                const other_keys = if (rec.is_set) try self.collectSetKeys(rec) else blk: {
                    other_iter = try self.callValueWithThis(rec.keys, &.{}, Value.obj(rec.obj));
                    if (!builtins.isRealObject(other_iter)) return self.throwError("TypeError", "iterator.next() did not return an object");
                    other_next = try self.getProperty(other_iter, "next");
                    break :blk &[_]Value{};
                };
                const result = (try self.makeSet(Value.undef())).asObj();
                for (try self.collectLiveSetEntries(o)) |entry| {
                    _ = try self.setMethod(result, "add", &.{entry});
                }
                if (rec.is_set) {
                    for (other_keys) |k| {
                        if (setContains(o, k))
                            _ = try self.setMethod(result, "delete", &.{k})
                        else if (!setContains(result, k))
                            _ = try self.setMethod(result, "add", &.{k});
                    }
                } else {
                    while (true) {
                        const r = try self.callValueWithThis(other_next, &.{}, other_iter);
                        if (!builtins.isRealObject(r)) return self.throwError("TypeError", "iterator.next() did not return an object");
                        if ((try self.getProperty(r, "done")).toBoolean()) break;
                        const k = try self.getProperty(r, "value");
                        if (setContains(o, k))
                            _ = try self.setMethod(result, "delete", &.{k})
                        else if (!setContains(result, k))
                            _ = try self.setMethod(result, "add", &.{k});
                    }
                }
                return Value.obj(result);
            }
            if (eq(name, "isSubsetOf")) {
                // A larger `this` cannot be a subset (and must not probe `has`).
                if (this_size > rec.size) return Value.boolVal(false);
                // Iterate the LIVE [[SetData]] by index: `rec.has` may mutate `this`
                // (e.g. delete a trailing element), and a removed slot must be
                // skipped rather than re-probed from a stale snapshot.
                var i: usize = 0;
                while (i < o.elementsLen()) : (i += 1) {
                    const entry = liveSetEntryAt(o, i) orelse continue;
                    if (!(try self.recordHas(rec, entry)))
                        return Value.boolVal(false);
                }
                return Value.boolVal(true);
            }
            if (eq(name, "isSupersetOf")) {
                // A smaller `this` cannot be a superset (and must not iterate keys).
                if (this_size < rec.size) return Value.boolVal(false);
                // Stop (closing the iterator) at the first other-key absent from this.
                return Value.boolVal(!(try self.setKeysAny(rec, o, false)));
            }
            if (eq(name, "isDisjointFrom")) {
                if (this_size <= rec.size) {
                    var i: usize = 0;
                    while (i < o.elementsLen()) : (i += 1) {
                        const entry = liveSetEntryAt(o, i) orelse continue;
                        if (try self.recordHas(rec, entry)) return Value.boolVal(false);
                    }
                    return Value.boolVal(true);
                }
                // Stop (closing the iterator) at the first other-key present in this.
                return Value.boolVal(!(try self.setKeysAny(rec, o, true)));
            }
        }
        if (eq(name, "keys") or eq(name, "values") or eq(name, "entries"))
            return try self.makeCursorIteratorWithKind(self_v, collectionIterKind(name));
        return null;
    }

    const SetRecord = struct { obj: *value.Object, has: Value, keys: Value, size: f64, is_set: bool };

    /// GetSetRecord: a set-like argument must be an object with a numeric `size`
    /// and callable `has`/`keys`. A native Set is recognized directly (its
    /// `has`/`keys` are dispatched, not stored properties), so it's served from
    /// its own elements rather than the protocol.
    fn getSetRecord(self: *Interpreter, v: Value) EvalError!SetRecord {
        if (!v.isObject()) return self.throwError("TypeError", "argument is not an object");
        // GetSetRecord: rawSize = Get(obj,"size"); numSize = ToNumber(rawSize)
        // (a Symbol/BigInt size throws a TypeError); NaN throws; intSize < 0 is a
        // RangeError. ToNumber runs before `has`/`keys` are read.
        const size = try self.toNumberV(try self.getProperty(v, "size"));
        if (std.math.isNan(size)) return self.throwError("TypeError", "set-like 'size' is NaN");
        if (@trunc(size) < 0) return self.throwError("RangeError", "set-like 'size' is negative"); // intSize = ToIntegerOrInfinity
        if (v.asObj().is_set) return .{ .obj = v.asObj(), .has = Value.undef(), .keys = Value.undef(), .size = size, .is_set = true };
        const has = try self.getProperty(v, "has");
        if (!has.isCallable()) return self.throwError("TypeError", "set-like 'has' is not callable");
        const keys = try self.getProperty(v, "keys");
        if (!keys.isCallable()) return self.throwError("TypeError", "set-like 'keys' is not callable");
        return .{ .obj = v.asObj(), .has = has, .keys = keys, .size = size, .is_set = false };
    }

    /// Lazily walk `rec`'s keys (GetIteratorDirect — `next` captured once),
    /// stopping as soon as `setContains(o, key) == want`. On an early stop the
    /// key iterator is closed (IteratorClose) and `true` is returned; if the keys
    /// are exhausted without a match, `false` (no close — the iterator finished).
    fn setKeysAny(self: *Interpreter, rec: SetRecord, o: *value.Object, want: bool) EvalError!bool {
        if (rec.is_set) {
            for (try self.collectSetKeys(rec)) |entry| if (setContains(o, entry) == want) return true;
            return false;
        }
        const iter = try self.callValueWithThis(rec.keys, &.{}, Value.obj(rec.obj));
        const next_m = try self.getProperty(iter, "next");
        while (true) {
            const r = try self.callValueWithThis(next_m, &.{}, iter);
            if (!r.isObject()) return self.throwError("TypeError", "iterator.next() did not return an object");
            if ((try self.getProperty(r, "done")).toBoolean()) return false;
            const k = try self.getProperty(r, "value");
            if (setContains(o, k) == want) {
                try self.iteratorClose(iter);
                return true;
            }
        }
    }

    /// SetDataHas: whether the native Set `o` contains `elem` (SameValueZero) —
    /// used by the set operations when they iterate the *other* operand.
    fn setContains(o: *value.Object, elem: Value) bool {
        const elements_locked_11 = o.lockElements();
        defer o.unlockElements(elements_locked_11);
        for (o.elementsItems()) |e| {
            const entry = liveSetEntry(e) orelse continue;
            if (value.sameValueZero(entry, elem)) return true;
        }
        return false;
    }

    /// Whether the set-like contains `elem` (a native Set scans its elements; a
    /// set-like calls its `has`).
    fn recordHas(self: *Interpreter, rec: SetRecord, elem: Value) EvalError!bool {
        if (rec.is_set) {
            const elements_locked_12 = rec.obj.lockElements();
            defer rec.obj.unlockElements(elements_locked_12);
            for (rec.obj.elementsItems()) |e| {
                const entry = liveSetEntry(e) orelse continue;
                if (value.sameValueZero(entry, elem)) return true;
            }
            return false;
        }
        return (try self.callValueWithThis(rec.has, &.{elem}, Value.obj(rec.obj))).toBoolean();
    }

    /// The set-like's elements (a native Set's `elements`, else its `keys()`).
    fn collectSetKeys(self: *Interpreter, rec: SetRecord) EvalError![]Value {
        if (rec.is_set) {
            return self.collectLiveSetEntries(rec.obj);
        }
        const iter = try self.callValueWithThis(rec.keys, &.{}, Value.obj(rec.obj));
        // GetIteratorDirect: capture `next` ONCE, then call it each step (the
        // spec does not re-read the `next` property on every iteration).
        const next_method = try self.getProperty(iter, "next");
        var list: std.ArrayListUnmanaged(Value) = .empty;
        while (true) {
            const r = try self.callValueWithThis(next_method, &.{}, iter);
            if (!r.isObject()) return self.throwError("TypeError", "iterator.next() did not return an object");
            if ((try self.getProperty(r, "done")).toBoolean()) break;
            try list.append(self.arena, try self.getProperty(r, "value"));
        }
        return list.items;
    }

    /// Snapshot a native Set's live [[SetData]] entries under its element lock.
    /// The returned slice is used before running user code or mutating other
    /// collections, so callers never hold `elements_lock` across re-entrant JS.
    fn collectLiveSetEntries(self: *Interpreter, o: *value.Object) EvalError![]Value {
        var list: std.ArrayListUnmanaged(Value) = .empty;
        const elements_locked_13 = o.lockElements();
        defer o.unlockElements(elements_locked_13);
        for (o.elementsItems()) |e| {
            const entry = liveSetEntry(e) orelse continue;
            try list.append(self.arena, entry);
        }
        return list.items;
    }

    fn evalArrayLit(self: *Interpreter, elems: []*Node) EvalError!Value {
        const v = try self.newArray();
        for (elems) |en| {
            if (en.* == .spread) {
                try self.spreadInto(try v.asObj().ensureElementsList(self.arena), try self.eval(en.spread));
            } else if (en.* == .elision) {
                // A hole: a slot that reads as absent (skipped by iteration).
                try v.asObj().appendArrayHole(self.arena);
            } else {
                try v.asObj().appendElement(self.arena, try self.eval(en));
            }
        }
        return v;
    }

    /// `index`-as-string -> array element index, or null if not an integer.
    pub fn arrayIndex(key: []const u8) ?usize {
        if (key.len == 0) return null;
        // Array indices are CANONICAL numeric strings only: a leading zero
        // ("01", "00", "007") is an ordinary string key, distinct from "1"/"0"/
        // "7", so it must NOT alias to an element slot (CanonicalNumericIndexString).
        if (key.len > 1 and key[0] == '0') return null;
        for (key) |c| if (!std.ascii.isDigit(c)) return null;
        return std.fmt.parseInt(usize, key, 10) catch null;
    }

    fn arrayElementIndex(key: []const u8) ?usize {
        const i = arrayIndex(key) orelse return null;
        return if (i < 4294967295) i else null;
    }

    // ---- Proxy ------------------------------------------------------------

    /// Fetch trap `name` from a proxy's handler. Returns null when the trap is
    /// absent/undefined (the caller forwards to the target). Throws if the proxy
    /// is revoked or the trap isn't callable.
    fn proxyTrap(self: *Interpreter, o: *value.Object, name: []const u8) EvalError!?Value {
        if (o.proxy_revoked or o.proxyHandler() == null)
            return self.throwError("TypeError", "Cannot perform 'get' on a proxy that has been revoked");
        const trap = try self.getProperty(Value.obj(o.proxyHandler().?), name);
        if (trap.isUndefined() or trap.isNull()) return null;
        if (!trap.isCallable()) return self.throwError("TypeError", "proxy trap is not a function");
        return trap;
    }

    /// A property key as a JS value for passing to a trap. (String keys only for
    /// now; symbol-keyed trap arguments aren't reconstructed yet.)
    pub fn keyToValue(self: *Interpreter, key: []const u8) EvalError!Value {
        // A symbol-encoded key recovers the original Symbol (registered in
        // `keyOf` when it was used as a property key); other keys are strings.
        if (value.isRealSymbolKey(key)) {
            if (self.symbols.get(key)) |sym| return Value.obj(sym);
            // Context embedding calls create short-lived Interpreter values.
            // Recover Symbols used by a previous call from a reflection-hidden
            // registry on the realm-rooted Symbol intrinsic.
            if (self.symbolIdentityRegistry()) |symbol_registry| {
                const storage_key = try self.symbolRegistryStorageKey(key);
                if (symbol_registry.getOwn(storage_key)) |registered| {
                    if (registered.isObject() and registered.asObj().is_symbol) {
                        self.symbols.put(self.arena, key, registered.asObj()) catch {};
                        return registered;
                    }
                }
            }
            // Fallback: a well-known symbol (Symbol.iterator / toStringTag / …)
            // whose key wasn't registered via `keyOf` this evaluation — find the
            // canonical Symbol object on the global `Symbol` so identity holds
            // (e.g. getOwnPropertySymbols/Reflect.ownKeys surfacing @@toStringTag).
            if (self.env.get("Symbol")) |symv| if (symv.isObject()) {
                const ks = symv.asObj().ownKeysWithScratch(self.arena, self.scratch_allocator orelse self.arena) catch &.{};
                for (ks) |k| {
                    const v = symv.asObj().getOwn(k) orelse continue;
                    if (v.isObject() and v.asObj().is_symbol and std.mem.eql(u8, v.asObj().symbolKey(), key)) {
                        self.symbols.put(self.arena, key, v.asObj()) catch {};
                        return Value.obj(v.asObj());
                    }
                }
            };
        }
        return try Value.strAlloc(self.arena, value.decodeStringKey(key));
    }

    /// Guard against unbounded proxy→target→proxy forwarding (which recurses
    /// without a JS call frame, so the normal call-depth limit wouldn't catch it).
    fn proxyDepth(self: *Interpreter) EvalError!void {
        try self.stackGuard();
    }

    /// [[GetPrototypeOf]] of an (unwrapped) prototype value for a target object,
    /// honoring a target that is itself a Proxy.
    fn ordinaryProtoValue(self: *Interpreter, o: *value.Object) EvalError!Value {
        if (o.proxyHandler() != null or o.proxy_revoked) return self.proxyGetProto(o);
        return if (self.effectiveProto(o)) |p| Value.obj(p) else Value.nul();
    }

    fn sameProtoValue(proto: ?*value.Object, v: Value) bool {
        return (proto == null and v.isNull()) or (proto != null and v.isObject() and proto.? == v.asObj());
    }

    fn ordinarySetPrototypeOf(self: *Interpreter, o: *value.Object, new_proto: ?*value.Object) EvalError!bool {
        self.lockPrototypeGraph();
        defer self.unlockPrototypeGraph();
        const current = try self.ordinaryProtoValue(o);
        if (sameProtoValue(new_proto, current)) return true;
        if (self.objectProto()) |op| {
            if (o == op) return false;
        }
        if (!o.isExtensible()) return false;
        var cur = new_proto;
        while (cur) |c| {
            if (c == o) return false;
            // OrdinarySetPrototypeOf only continues the cycle walk through
            // ordinary objects. A Proxy in the candidate prototype chain is
            // exotic; reaching it stops the walk rather than invoking its
            // [[GetPrototypeOf]] trap.
            if (c.proxyHandler() != null or c.proxy_revoked) break;
            cur = self.effectiveProto(c);
        }
        if (new_proto) |np| _ = self.preparePrototypeUse(np);
        o.setPrototypeStateAtomic(new_proto);
        return true;
    }

    /// [[SetPrototypeOf]] honoring Proxy targets and Proxy invariants.
    pub fn setPrototypeOfObject(self: *Interpreter, o: *value.Object, new_proto: ?*value.Object) EvalError!bool {
        try self.checkRestricted(o);
        if (o.proxyHandler() != null or o.proxy_revoked) return self.proxySetProto(o, new_proto);
        return self.ordinarySetPrototypeOf(o, new_proto);
    }

    /// Public embedding funnel for [[GetPrototypeOf]], including Proxy traps
    /// and the engine's implicit Function.prototype fallback.
    pub fn getPrototypeOfObject(self: *Interpreter, o: *value.Object) EvalError!Value {
        try self.checkRestricted(o);
        return self.ordinaryProtoValue(o);
    }

    /// [[GetPrototypeOf]] for a Proxy (9.5.1): invoke the trap, require an Object
    /// or null result, and enforce the non-extensible-target invariant.
    pub fn proxyGetProto(self: *Interpreter, o: *value.Object) EvalError!Value {
        try self.proxyDepth();
        const target = o.proxyTarget() orelse return self.throwError("TypeError", "Cannot perform 'getPrototypeOf' on a proxy that has been revoked");
        const trap = (try self.proxyTrap(o, "getPrototypeOf")) orelse return self.ordinaryProtoValue(target);
        const res = try self.callValueWithThis(trap, &.{Value.obj(target)}, Value.obj(o.proxyHandler().?));
        if (!res.isNull() and (!res.isObject() or res.asObj().is_symbol or res.asObj().is_bigint))
            return self.throwError("TypeError", "proxy 'getPrototypeOf' trap must return an object or null");
        if (!try self.ordinaryIsExtensible(target)) {
            const tp = try self.ordinaryProtoValue(target);
            const same = (res.isNull() and tp.isNull()) or (res.isObject() and tp.isObject() and res.asObj() == tp.asObj());
            if (!same) return self.throwError("TypeError", "proxy 'getPrototypeOf' trap result must match the prototype of a non-extensible target");
        }
        return res;
    }

    /// [[IsExtensible]] honoring a Proxy target.
    fn ordinaryIsExtensible(self: *Interpreter, o: *value.Object) EvalError!bool {
        if (o.proxyHandler() != null or o.proxy_revoked) return self.proxyIsExtensible(o);
        if (o.moduleNs() != null) return false; // a module namespace is never extensible
        return o.isExtensible();
    }

    /// [[IsExtensible]] for a Proxy (9.5.3): the boolean trap result must equal
    /// the target's own extensibility.
    pub fn proxyIsExtensible(self: *Interpreter, o: *value.Object) EvalError!bool {
        try self.proxyDepth();
        const target = o.proxyTarget() orelse return self.throwError("TypeError", "Cannot perform 'isExtensible' on a proxy that has been revoked");
        const trap = (try self.proxyTrap(o, "isExtensible")) orelse return self.ordinaryIsExtensible(target);
        const res = (try self.callValueWithThis(trap, &.{Value.obj(target)}, Value.obj(o.proxyHandler().?))).toBoolean();
        if (res != try self.ordinaryIsExtensible(target))
            return self.throwError("TypeError", "proxy 'isExtensible' trap result must match the target's extensibility");
        return res;
    }

    /// [[PreventExtensions]] for a Proxy (9.5.4): a truthy trap result requires
    /// the target to already be non-extensible.
    pub fn proxyPreventExt(self: *Interpreter, o: *value.Object) EvalError!bool {
        try self.proxyDepth();
        const target = o.proxyTarget() orelse return self.throwError("TypeError", "Cannot perform 'preventExtensions' on a proxy that has been revoked");
        const trap = (try self.proxyTrap(o, "preventExtensions")) orelse {
            if (target.proxyHandler() != null) return self.proxyPreventExt(target);
            target.setExtensible(false);
            return true;
        };
        const res = (try self.callValueWithThis(trap, &.{Value.obj(target)}, Value.obj(o.proxyHandler().?))).toBoolean();
        if (res and try self.ordinaryIsExtensible(target))
            return self.throwError("TypeError", "proxy 'preventExtensions' cannot report success while the target is extensible");
        return res;
    }

    /// [[SetPrototypeOf]] for a Proxy: forward when the trap is absent, otherwise
    /// coerce the trap result and enforce the non-extensible target invariant.
    pub fn proxySetProto(self: *Interpreter, o: *value.Object, new_proto: ?*value.Object) EvalError!bool {
        try self.proxyDepth();
        const target = o.proxyTarget() orelse return self.throwError("TypeError", "Cannot perform 'setPrototypeOf' on a proxy that has been revoked");
        const proto_v: Value = if (new_proto) |p| Value.obj(p) else Value.nul();
        const trap = (try self.proxyTrap(o, "setPrototypeOf")) orelse return self.setPrototypeOfObject(target, new_proto);
        const ok = (try self.callValueWithThis(trap, &.{ Value.obj(target), proto_v }, Value.obj(o.proxyHandler().?))).toBoolean();
        if (!ok) return false;
        if (try self.ordinaryIsExtensible(target)) return true;
        const target_proto = try self.ordinaryProtoValue(target);
        if (!sameProtoValue(new_proto, target_proto))
            return self.throwError("TypeError", "proxy 'setPrototypeOf' cannot report success with a different prototype on a non-extensible target");
        return true;
    }

    fn proxyGet(self: *Interpreter, o: *value.Object, key: []const u8, receiver: Value) EvalError!Value {
        try self.proxyDepth();
        self.depth += 1;
        defer self.depth -= 1;
        const target = o.proxyTarget() orelse return self.throwError("TypeError", "Cannot perform 'get' on a proxy that has been revoked");
        if (try self.proxyTrap(o, "get")) |trap| {
            const res = try self.callValueWithThis(trap, &.{ Value.obj(target), try self.keyToValue(key), receiver }, Value.obj(o.proxyHandler().?));
            // [[Get]] invariant (9.5.8): a non-configurable non-writable data
            // property must report its value; a non-configurable accessor with
            // no getter must report undefined.
            if (target.proxyHandler() == null and !target.proxy_revoked and objectHasOwn(target, key) and !target.getAttr(key).configurable) {
                if (target.getAccessor(key)) |acc| {
                    if ((acc.get == null or acc.get.?.isUndefined()) and !res.isUndefined())
                        return self.throwError("TypeError", "proxy 'get' must report undefined for a non-configurable accessor with no getter");
                } else if (!target.getAttr(key).writable) {
                    if (target.getOwn(key)) |tv| if (!value.sameValue(res, tv))
                        return self.throwError("TypeError", "proxy 'get' must report the target value for a non-configurable non-writable property");
                }
            }
            return res;
        }
        return self.getPropertyWithReceiver(Value.obj(target), key, receiver);
    }

    fn proxySet(self: *Interpreter, o: *value.Object, key: []const u8, v: Value, receiver: Value) EvalError!bool {
        try self.proxyDepth();
        self.depth += 1;
        defer self.depth -= 1;
        const target = o.proxyTarget() orelse return self.throwError("TypeError", "Cannot perform 'set' on a proxy that has been revoked");
        if (try self.proxyTrap(o, "set")) |trap| {
            const ok = (try self.callValueWithThis(trap, &.{ Value.obj(target), try self.keyToValue(key), v, receiver }, Value.obj(o.proxyHandler().?))).toBoolean();
            // [[Set]] invariant (9.5.9): a successful set can't disagree with a
            // non-configurable non-writable data property, nor target a
            // non-configurable accessor that has no setter.
            if (ok and target.proxyHandler() == null and !target.proxy_revoked and objectHasOwn(target, key) and !target.getAttr(key).configurable) {
                if (target.getAccessor(key)) |acc| {
                    if (acc.set == null or acc.set.?.isUndefined()) return self.throwError("TypeError", "proxy 'set' cannot succeed for a non-configurable accessor with no setter");
                } else if (!target.getAttr(key).writable) {
                    if (target.getOwn(key)) |tv| if (!value.sameValue(v, tv))
                        return self.throwError("TypeError", "proxy 'set' cannot change a non-configurable non-writable property");
                }
            }
            return ok;
        }
        return self.setMemberResult(Value.obj(target), key, v, receiver);
    }

    fn proxyHas(self: *Interpreter, o: *value.Object, key: []const u8) EvalError!bool {
        try self.proxyDepth();
        self.depth += 1;
        defer self.depth -= 1;
        const target = o.proxyTarget() orelse return self.throwError("TypeError", "Cannot perform 'has' on a proxy that has been revoked");
        if (try self.proxyTrap(o, "has")) |trap| {
            const b = (try self.callValueWithThis(trap, &.{ Value.obj(target), try self.keyToValue(key) }, Value.obj(o.proxyHandler().?))).toBoolean();
            // [[HasProperty]] invariant (9.5.7): can't hide a non-configurable
            // own property, nor an own property of a non-extensible target.
            if (!b and target.proxyHandler() == null and !target.proxy_revoked and objectHasOwn(target, key)) {
                if (!target.getAttr(key).configurable) return self.throwError("TypeError", "proxy 'has' cannot report a non-configurable own property as absent");
                if (!try self.ordinaryIsExtensible(target)) return self.throwError("TypeError", "proxy 'has' cannot report an own property of a non-extensible target as absent");
            }
            return b;
        }
        return self.hasPropertyResult(target, key);
    }

    fn proxyDelete(self: *Interpreter, o: *value.Object, key: []const u8) EvalError!bool {
        try self.proxyDepth();
        self.depth += 1;
        defer self.depth -= 1;
        const target = o.proxyTarget() orelse return self.throwError("TypeError", "Cannot perform 'deleteProperty' on a proxy that has been revoked");
        if (try self.proxyTrap(o, "deleteProperty")) |trap| {
            const b = (try self.callValueWithThis(trap, &.{ Value.obj(target), try self.keyToValue(key) }, Value.obj(o.proxyHandler().?))).toBoolean();
            // [[Delete]] invariant (9.5.10): can't report deleting a
            // non-configurable property, nor any property of a non-extensible target.
            if (b and target.proxyHandler() == null and !target.proxy_revoked and objectHasOwn(target, key)) {
                if (!target.getAttr(key).configurable) return self.throwError("TypeError", "proxy 'deleteProperty' cannot delete a non-configurable property");
                if (!try self.ordinaryIsExtensible(target)) return self.throwError("TypeError", "proxy 'deleteProperty' cannot delete a property of a non-extensible target");
            }
            return b;
        }
        return self.deleteOwn(target, key);
    }

    /// `ownKeys` trap → an array of keys (string values). Falls back to the
    /// target's own string keys.
    /// An object's [[OwnPropertyKeys]] as encoded key strings — proxy-aware, and
    /// including an array's dense element indices and `length` (which live
    /// outside the shape).
    pub fn objectOwnKeysList(self: *Interpreter, t: *value.Object) EvalError![]const []const u8 {
        if (t.proxyHandler() != null or t.proxy_revoked) return self.proxyOwnKeys(t);
        const scratch = self.scratch_allocator orelse self.arena;
        const appendReflectable = struct {
            fn f(arena: std.mem.Allocator, list: *std.ArrayListUnmanaged([]const u8), k: []const u8) !void {
                if (value.isPrivateKey(k)) return;
                if (value.isHiddenInternalKey(k)) return;
                try list.append(arena, k);
            }
        }.f;
        if (moduleNsOf(t)) |ns| {
            try triggerDeferModule(self, ns); // `import defer`: [[OwnPropertyKeys]] evaluates first
            // Sorted string export names first, then the @@toStringTag symbol key.
            var list: std.ArrayListUnmanaged([]const u8) = .empty;
            try list.appendSlice(self.arena, ns.names);
            try list.append(self.arena, ns.tag_key);
            return list.items;
        }
        if (t.boxedPrimitive()) |p| {
            if (p.isString()) {
                // String exotic [[OwnPropertyKeys]]: the char-index keys merged with
                // any user integer-index keys (all ascending), then "length", then
                // other string keys in insertion order, then symbols.
                var indices: std.ArrayListUnmanaged([]const u8) = .empty;
                var seen: std.AutoHashMapUnmanaged(usize, void) = .empty;
                defer seen.deinit(scratch);
                for (0..utf16LenOfValue(p)) |i| {
                    try indices.append(self.arena, try std.fmt.allocPrint(self.arena, "{d}", .{i}));
                    try seen.put(scratch, i, {});
                }
                for (try t.denseElementIndices(self.arena)) |dense_i| {
                    const entry = try seen.getOrPut(scratch, dense_i);
                    if (entry.found_existing) continue;
                    try indices.append(self.arena, try std.fmt.allocPrint(self.arena, "{d}", .{dense_i}));
                }
                var strings: std.ArrayListUnmanaged([]const u8) = .empty;
                var symbols: std.ArrayListUnmanaged([]const u8) = .empty;
                for (try t.ownKeysWithScratch(self.arena, scratch)) |k| {
                    if (std.mem.eql(u8, k, "length") or value.isPrivateKey(k) or value.isHiddenInternalKey(k)) continue;
                    if (value.isRealSymbolKey(k)) {
                        try symbols.append(self.arena, k);
                    } else if (value.canonicalIndex(k)) |idx| {
                        const entry = try seen.getOrPut(scratch, idx);
                        if (!entry.found_existing) try indices.append(self.arena, k);
                    } else try strings.append(self.arena, k);
                }
                std.mem.sort([]const u8, indices.items, {}, struct {
                    fn lt(_: void, x: []const u8, y: []const u8) bool {
                        return value.canonicalIndex(x).? < value.canonicalIndex(y).?;
                    }
                }.lt);
                var list: std.ArrayListUnmanaged([]const u8) = .empty;
                try list.appendSlice(self.arena, indices.items);
                try list.append(self.arena, "length");
                try list.appendSlice(self.arena, strings.items);
                try list.appendSlice(self.arena, symbols.items);
                return list.items;
            }
        }
        if (t.typedArray()) |ta| {
            // Integer-Indexed Exotic [[OwnPropertyKeys]]: the in-bounds element
            // indices (ascending) first, then any ordinary own string/symbol keys.
            var list: std.ArrayListUnmanaged([]const u8) = .empty;
            var i: usize = 0;
            const cur = ta.currentLength() orelse 0;
            while (i < cur) : (i += 1) try list.append(self.arena, try std.fmt.allocPrint(self.arena, "{d}", .{i}));
            for (try t.ownKeysWithScratch(self.arena, scratch)) |k| try appendReflectable(self.arena, &list, k);
            return list.items;
        }
        if (t.is_array) {
            // OrdinaryOwnPropertyKeys order: integer indices ascending (merging the
            // dense element store with any sparse/accessor index in the shape),
            // then string keys in creation order — "length" exists from
            // construction so it precedes any user-added string key — then symbols.
            var indices: std.ArrayListUnmanaged([]const u8) = .empty;
            var seen: std.AutoHashMapUnmanaged(usize, void) = .empty;
            defer seen.deinit(scratch);
            for (try t.denseElementIndices(self.arena)) |i| {
                try indices.append(self.arena, try std.fmt.allocPrint(self.arena, "{d}", .{i}));
                try seen.put(scratch, i, {});
            }
            var strings: std.ArrayListUnmanaged([]const u8) = .empty;
            var symbols: std.ArrayListUnmanaged([]const u8) = .empty;
            for (try t.ownKeysWithScratch(self.arena, scratch)) |k| {
                if (value.isPrivateKey(k) or value.isHiddenInternalKey(k)) continue;
                if (value.isRealSymbolKey(k)) {
                    try symbols.append(self.arena, k);
                } else if (value.canonicalIndex(k)) |idx| {
                    const entry = try seen.getOrPut(scratch, idx);
                    if (!entry.found_existing) try indices.append(self.arena, k);
                } else {
                    try strings.append(self.arena, k);
                }
            }
            std.mem.sort([]const u8, indices.items, {}, struct {
                fn lt(_: void, x: []const u8, y: []const u8) bool {
                    return value.canonicalIndex(x).? < value.canonicalIndex(y).?;
                }
            }.lt);
            var list: std.ArrayListUnmanaged([]const u8) = .empty;
            try list.appendSlice(self.arena, indices.items);
            try list.append(self.arena, "length");
            try list.appendSlice(self.arena, strings.items);
            try list.appendSlice(self.arena, symbols.items);
            return list.items;
        }
        // A function's `.prototype` own property is materialized lazily; force it
        // into being so it appears as a real own key here (its non-enumerable
        // attrs keep it out of Object.keys/JSON). It is repositioned after `name`
        // below — the spec creates it at that position, but the lazy install
        // appends it at the tail.
        const fn_has_proto = t.jsFunction() != null and Interpreter.jsFunctionHasOwnPrototypeSlot(t);
        if (fn_has_proto) try self.materializeFunctionPrototype(t);
        var indices: std.ArrayListUnmanaged([]const u8) = .empty;
        var seen: std.AutoHashMapUnmanaged(usize, void) = .empty;
        defer seen.deinit(scratch);
        for (try t.denseElementIndices(self.arena)) |dense_i| {
            try indices.append(self.arena, try std.fmt.allocPrint(self.arena, "{d}", .{dense_i}));
            try seen.put(scratch, dense_i, {});
        }
        var strings: std.ArrayListUnmanaged([]const u8) = .empty;
        var symbols: std.ArrayListUnmanaged([]const u8) = .empty;
        // Ordinary own-key storage is already unique. Allocate membership only
        // if a host hook contributes a string key that can overlap it.
        var seen_strings: ?SecureStringMembership = null;
        defer if (seen_strings) |*membership| membership.deinit(scratch);
        if (t.hostClassHooks()) |hooks| if (hooks.own_keys) |own_keys| {
            self.recordExecutionTier(.host_callbacks);
            for (try own_keys(@ptrCast(self), t)) |k| {
                if (value.isPrivateKey(k) or value.isHiddenInternalKey(k)) continue;
                if (value.isRealSymbolKey(k)) {
                    try symbols.append(self.arena, k);
                } else if (value.canonicalIndex(k)) |idx| {
                    const entry = try seen.getOrPut(scratch, idx);
                    if (!entry.found_existing) try indices.append(self.arena, k);
                } else {
                    if (seen_strings == null) seen_strings = .{};
                    if (!try seen_strings.?.getOrPutSecure(self, scratch, k)) try strings.append(self.arena, k);
                }
            }
        };
        for (try t.ownKeysWithScratch(self.arena, scratch)) |k| {
            if (value.isPrivateKey(k) or value.isHiddenInternalKey(k)) continue;
            if (value.isRealSymbolKey(k)) {
                try symbols.append(self.arena, k);
            } else if (value.canonicalIndex(k)) |idx| {
                const entry = try seen.getOrPut(scratch, idx);
                if (!entry.found_existing) try indices.append(self.arena, k);
            } else {
                if (seen_strings) |*membership| {
                    if (!try membership.getOrPutSecure(self, scratch, k)) try strings.append(self.arena, k);
                } else try strings.append(self.arena, k);
            }
        }
        std.mem.sort([]const u8, indices.items, {}, struct {
            fn lt(_: void, x: []const u8, y: []const u8) bool {
                return value.canonicalIndex(x).? < value.canonicalIndex(y).?;
            }
        }.lt);
        // Move a function's `prototype` to directly follow `name` (spec creation
        // order), rather than wherever the lazy install appended it.
        if (fn_has_proto) {
            var reordered: std.ArrayListUnmanaged([]const u8) = .empty;
            var placed = false;
            for (strings.items) |s| {
                if (std.mem.eql(u8, s, "prototype")) continue;
                try reordered.append(self.arena, s);
                if (std.mem.eql(u8, s, "name")) {
                    try reordered.append(self.arena, "prototype");
                    placed = true;
                }
            }
            if (!placed) try reordered.append(self.arena, "prototype");
            strings = reordered;
        }
        var list: std.ArrayListUnmanaged([]const u8) = .empty;
        try list.appendSlice(self.arena, indices.items);
        try list.appendSlice(self.arena, strings.items);
        try list.appendSlice(self.arena, symbols.items);
        return list.items;
    }

    const SecureStringHashContext = struct {
        seed: u64,

        pub fn hash(context: @This(), key: []const u8) u64 {
            return std.hash.Wyhash.hash(context.seed, key);
        }

        pub fn eql(_: @This(), left: []const u8, right: []const u8) bool {
            return std.mem.eql(u8, left, right);
        }
    };

    const SecureStringIndex = std.HashMapUnmanaged(
        []const u8,
        void,
        SecureStringHashContext,
        std.hash_map.default_max_load_percentage,
    );

    const SecureStringMembership = struct {
        index: SecureStringIndex = .empty,
        context: ?SecureStringHashContext = null,

        fn deinit(membership: *@This(), allocator: std.mem.Allocator) void {
            membership.index.deinit(allocator);
        }

        fn putWithContext(
            membership: *@This(),
            allocator: std.mem.Allocator,
            key: []const u8,
            context: SecureStringHashContext,
        ) std.mem.Allocator.Error!bool {
            if (membership.context) |installed| {
                std.debug.assert(installed.seed == context.seed);
                return (try membership.index.getOrPutContext(allocator, key, installed)).found_existing;
            }
            const entry = try membership.index.getOrPutContext(allocator, key, context);
            // A failed first allocation leaves no published seed or partially
            // initialized membership index for any enumeration caller.
            membership.context = context;
            return entry.found_existing;
        }

        fn getOrPutSecure(
            membership: *@This(),
            interpreter: *Interpreter,
            allocator: std.mem.Allocator,
            key: []const u8,
        ) EvalError!bool {
            const context = membership.context orelse SecureStringHashContext{ .seed = try interpreter.newSecureHashSeed() };
            return membership.putWithContext(allocator, key, context);
        }

        fn remove(membership: *@This(), key: []const u8) bool {
            const context = membership.context orelse return false;
            return membership.index.removeContext(key, context);
        }

        fn count(membership: *const @This()) usize {
            return membership.index.count();
        }

        fn keyIterator(membership: *const @This()) SecureStringIndex.KeyIterator {
            return membership.index.keyIterator();
        }
    };

    pub fn proxyOwnKeys(self: *Interpreter, o: *value.Object) EvalError![]const []const u8 {
        try self.proxyDepth();
        self.depth += 1;
        defer self.depth -= 1;
        const scratch = self.scratch_allocator orelse self.arena;
        const target = o.proxyTarget() orelse return self.throwError("TypeError", "Cannot perform 'ownKeys' on a proxy that has been revoked");
        if (try self.proxyTrap(o, "ownKeys")) |trap| {
            const res = try self.callValueWithThis(trap, &.{Value.obj(target)}, Value.obj(o.proxyHandler().?));
            if (!res.isObject()) return self.throwError("TypeError", "ownKeys trap must return an object");
            // CreateListFromArrayLike(types: String, Symbol): every element must
            // be a String or Symbol.
            const len = toLen(try self.toNumberV(try self.getProperty(res, "length")));
            var list: std.ArrayListUnmanaged([]const u8) = .empty;
            var i: usize = 0;
            while (i < len) : (i += 1) {
                const k = try self.getProperty(res, try std.fmt.allocPrint(self.arena, "{d}", .{i}));
                if (!k.isString() and !(k.isObject() and k.asObj().is_symbol))
                    return self.throwError("TypeError", "ownKeys trap result includes a non-String, non-Symbol key");
                try list.append(self.arena, try self.keyOf(k));
            }
            // [[OwnPropertyKeys]] invariants: no duplicates; every
            // non-configurable target key must be present; for a non-extensible
            // target the result must be exactly the target's keys.
            var seen: SecureStringMembership = .{};
            defer seen.deinit(scratch);
            for (list.items) |k| {
                if (try seen.getOrPutSecure(self, scratch, k))
                    return self.throwError("TypeError", "ownKeys trap result contains duplicate keys");
            }
            const extensible = target.isExtensible();
            const tkeys = try self.objectOwnKeysList(target);
            var has_nonconfig = false;
            for (tkeys) |tk| {
                if (objectHasOwn(target, tk) and !target.getAttr(tk).configurable) has_nonconfig = true;
            }
            if (!extensible or has_nonconfig) {
                // Every non-configurable target key must appear.
                for (tkeys) |tk| {
                    if (!objectHasOwn(target, tk) or target.getAttr(tk).configurable) continue;
                    if (!seen.remove(tk)) return self.throwError("TypeError", "ownKeys trap omitted a non-configurable key");
                }
                if (!extensible) {
                    // Non-extensible: the remaining (configurable) target keys must
                    // also appear, and nothing extra may be present.
                    for (tkeys) |tk| {
                        if (!objectHasOwn(target, tk) or !target.getAttr(tk).configurable) continue;
                        if (!seen.remove(tk)) return self.throwError("TypeError", "ownKeys trap omitted a key on a non-extensible target");
                    }
                    if (seen.count() != 0) return self.throwError("TypeError", "ownKeys trap added a key absent from a non-extensible target");
                }
            }
            return list.items;
        }
        return self.objectOwnKeysList(target);
    }

    /// `Thread.restrict` enforcement: every essential-internal-method funnel
    /// calls this (get/set/has/delete/define/ownKeys/proto/extensibility).
    pub fn checkRestricted(self: *Interpreter, o: *value.Object) EvalError!void {
        const owner = o.restrictionOwner();
        if (owner != 0 and owner != @as(u64, @intCast(std.Thread.getCurrentId())))
            return self.throwError("ConcurrentAccessError", "object is restricted to another thread");
    }

    pub fn getProperty(self: *Interpreter, recv: Value, key: []const u8) EvalError!Value {
        if (recv.isObject()) try self.checkRestricted(recv.asObj());
        return self.getPropertyWithReceiverFound(recv, key, recv, null, null);
    }

    pub fn getPropertyObserved(
        self: *Interpreter,
        recv: Value,
        key: []const u8,
        observation: *?InheritedPropertyObservation,
    ) EvalError!Value {
        observation.* = null;
        if (recv.isObject()) try self.checkRestricted(recv.asObj());
        return self.getPropertyWithReceiverFound(recv, key, recv, null, observation);
    }

    /// PrivateGet (`this.#x` read). Resolves the PrivateElement on the receiver's
    /// chain: a field/method returns its value; an accessor invokes its getter, or
    /// is a TypeError if it has only a setter; an object that was never branded
    /// with the name is a TypeError ("did not declare it"). Private fields are own
    /// properties of an instance; methods/accessors live on the home object.
    fn privateGet(self: *Interpreter, recv: Value, key: []const u8) EvalError!Value {
        // Brand check: the receiver must carry this private name (it is a proper
        // instance of the declaring class evaluation, and — for a derived `this` —
        // `super()` has already returned).
        if (!recv.isObject() or !recv.asObj().hasPrivateBrand(key))
            return self.throwError("TypeError", "Cannot read private member from an object whose class did not declare it");
        var cur: ?*value.Object = recv.asObj();
        while (cur) |c| {
            if (c.getAccessor(key)) |acc| {
                if (acc.get) |g| if (!g.isUndefined()) return self.callValueWithThis(g, &.{}, recv);
                return self.throwError("TypeError", "Cannot read private member: accessor has no getter");
            }
            if (c.getOwn(key)) |v| return v; // private field (own) or method (on home)
            // A private method lives on the declaring class's prototype; when the
            // instance is a Proxy (a base that `return`ed `new Proxy(this, …)`), the
            // method is reached through the proxy's target chain, not the proxy's
            // own [[Prototype]]. (Private access never invokes proxy traps.)
            cur = if (c.proxyHandler() != null) (c.proxyTarget() orelse c.protoAtomic()) else c.protoAtomic();
        }
        return Value.undef(); // branded but value not yet present (TDZ-like); rare
    }

    /// PrivateSet (`this.#x = v`). Resolves the PrivateElement: a field is written;
    /// a method is non-writable (TypeError); an accessor invokes its setter, or is
    /// a TypeError if it has only a getter; an unbranded object is a TypeError.
    fn privateSet(self: *Interpreter, recv: Value, key: []const u8, v: Value) EvalError!void {
        if (!recv.isObject() or !recv.asObj().hasPrivateBrand(key))
            return self.throwError("TypeError", "Cannot write private member to an object whose class did not declare it");
        const o = recv.asObj();
        var cur: ?*value.Object = o;
        while (cur) |c| {
            if (c.getAccessor(key)) |acc| {
                if (acc.set) |s| if (!s.isUndefined()) {
                    _ = try self.callValueWithThis(s, &.{v}, recv);
                    return;
                };
                return self.throwError("TypeError", "Cannot write private member: accessor has no setter");
            }
            if (c.getOwn(key)) |_| {
                // A private field is an own, writable property of the instance; an
                // inherited (home-object) private data element is a method, which
                // is read-only.
                if (c == o and c.getAttr(key).writable) {
                    try o.setOwn(self.arena, self.root_shape, key, v);
                    return;
                }
                return self.throwError("TypeError", "Cannot write private method");
            }
            // See privateGet: reach a Proxy instance's private accessor (on the
            // declaring class's prototype) through the proxy's target chain.
            cur = if (c.proxyHandler() != null) (c.proxyTarget() orelse c.protoAtomic()) else c.protoAtomic();
        }
        // Branded, but the field's own slot has not been materialized yet (a field
        // written before its own initializer ran, e.g. `#a = (this.#b = 1)`).
        // Define it now.
        try o.setOwn(self.arena, self.root_shape, key, v);
        try o.setAttr(self.arena, key, .{ .writable = true, .enumerable = false, .configurable = false });
    }

    /// Ordinary [[Get]] with the receiver kept separate from the object where
    /// lookup starts. Reflect.get and Proxy forwarding rely on this when an
    /// inherited accessor observes `this`.
    pub fn getPropertyWithReceiver(self: *Interpreter, recv: Value, key: []const u8, receiver: Value) EvalError!Value {
        return self.getPropertyWithReceiverFound(recv, key, receiver, null, null);
    }

    /// Ordinary [[Get]] while retaining the PropertySlot-style distinction
    /// between an absent property and a present property whose value is
    /// `undefined`.  This must be one lookup: probing with [[HasProperty]] first
    /// would add an observable `has` trap before a Proxy's `get` trap.
    pub fn getPropertyIfExists(self: *Interpreter, recv: Value, key: []const u8) EvalError!?Value {
        var found = true;
        const result = try self.getPropertyWithReceiverFound(recv, key, recv, &found, null);
        return if (found) result else null;
    }

    /// `GetOwnProperty` followed by PropertySlot value resolution.  A Proxy is
    /// queried exactly once through its `getOwnPropertyDescriptor` trap; an own
    /// accessor is then invoked with `receiver` as `this`.  Null means absent,
    /// while a present property may legitimately return `undefined`.
    pub fn getOwnPropertyValue(
        self: *Interpreter,
        object: *value.Object,
        key: []const u8,
        receiver: Value,
    ) EvalError!?Value {
        const descriptor = try builtins.objectGetOwnPropertyDescriptor(
            @ptrCast(self),
            Value.undef(),
            &.{ Value.obj(object), try self.keyToValue(key) },
        );
        if (!descriptor.isObject()) return null;
        const desc = descriptor.asObj();
        if (desc.getOwn("value")) |result| return result;
        const getter = desc.getOwn("get") orelse Value.undef();
        if (getter.isUndefined()) return Value.undef();
        return try self.callValueWithThis(getter, &.{}, receiver);
    }

    fn getPropertyWithReceiverFound(
        self: *Interpreter,
        recv: Value,
        key: []const u8,
        receiver: Value,
        found: ?*bool,
        inherited_observation: ?*?InheritedPropertyObservation,
    ) EvalError!Value {
        if (found) |slot| slot.* = true;
        // PrivateGet is not OrdinaryGet: it resolves the PrivateElement directly
        // (a setter-only accessor read is a TypeError; an absent brand is a
        // TypeError, never `undefined`).
        if (value.isPrivateKey(key)) return self.privateGet(recv, key);
        switch (recv.kind()) {
            .object => {
                const o = recv.asObj();
                if (o.is_symbol or o.is_bigint) return self.getPrimitiveMember(recv, key);
                if (o.proxyHandler() != null or o.proxy_revoked) return self.proxyGet(o, key, receiver);
                if (moduleNsOf(o)) |ns| {
                    try triggerDeferIfString(self, ns, key); // `import defer`: a string [[Get]] evaluates first
                    if (!moduleNsHas(ns, key)) {
                        if (found) |slot| slot.* = false;
                    }
                    return moduleNsGet(self, ns, key);
                }
                // Annex B legacy `caller`/`arguments`: sloppy ordinary functions
                // expose their active caller/arguments state. Newer function kinds
                // (methods, arrows, classes, async/generator functions, bound
                // functions, built-ins) fall through to %ThrowTypeError%.
                if ((std.mem.eql(u8, key, "caller") or std.mem.eql(u8, key, "arguments")) and o.boundFunction() == null and o.getOwn(key) == null) {
                    if (funcOf(recv)) |f| {
                        if (legacyCallerArgumentsAllowed(f)) {
                            const frame = self.legacyCallFrameFor(o) orelse return Value.nul();
                            if (std.mem.eql(u8, key, "caller")) return legacyCallerValue(frame);
                            if (frame.arguments) |a| return a;
                            // Legacy-only case: build the exotic object on demand
                            // (deferred from the call) and cache it for repeat reads.
                            if (frame.lazy_func) |lf| {
                                const obj = try self.createArgumentsObject(lf, frame.lazy_args, frame.lazy_env.?);
                                frame.arguments = obj;
                                return obj;
                            }
                            return Value.nul();
                        }
                    }
                }
                // A (non-arrow) function's `.prototype` is an own data property,
                // materialized lazily on first access — every [[Construct]]-able
                // function has one, with a `constructor` back-reference. Without
                // this a plain `Test262Error.prototype.toString = …` (and any
                // `f.prototype.x = …`) read undefined and threw.
                if (std.mem.eql(u8, key, "prototype") and o.jsFunction() != null and Interpreter.jsFunctionHasOwnPrototypeSlot(o) and o.getOwn("prototype") == null and o.getAccessor("prototype") == null) {
                    if (funcOf(recv)) |f| {
                        // A generator function's `.prototype` is a fresh object whose
                        // [[Prototype]] is %GeneratorPrototype% and which has NO
                        // `constructor` back-link; it is the [[Prototype]] of every
                        // instance the generator produces.
                        if (f.is_generator) {
                            return Value.obj(try self.genProtoObject(o, f.is_async));
                        }
                        if (!f.is_arrow) {
                            const proto = try self.protoObject(o);
                            // `Ctor.prototype` is { writable, !enumerable, !configurable };
                            // its `constructor` back-link is { writable, !enumerable, configurable }.
                            try o.setAttr(self.arena, "prototype", .{ .writable = true, .enumerable = false, .configurable = false });
                            try self.setProp(proto, "constructor", recv);
                            try proto.setAttr(self.arena, "constructor", .{ .writable = true, .enumerable = false, .configurable = true });
                            return Value.obj(proto);
                        }
                    }
                }
                if (o.arrayBuffer()) |ab| {
                    if (std.mem.eql(u8, key, "byteLength") and o.getOwn(key) == null and o.getAccessor(key) == null)
                        return Value.num(@floatFromInt(if (ab.isDetached()) 0 else ab.bytes().len));
                }
                if (o.typedArray()) |ta| {
                    const cur = ta.currentLength(); // null when detached / out of bounds
                    if (std.mem.eql(u8, key, "length") and o.getOwn(key) == null and o.getAccessor(key) == null) return Value.num(@floatFromInt(cur orelse 0));
                    if (std.mem.eql(u8, key, "byteLength") and o.getOwn(key) == null and o.getAccessor(key) == null) return Value.num(@floatFromInt((cur orelse 0) * ta.kind.byteSize()));
                    if (std.mem.eql(u8, key, "byteOffset") and o.getOwn(key) == null and o.getAccessor(key) == null) return Value.num(@floatFromInt(if (cur == null) 0 else ta.byte_offset));
                    if (std.mem.eql(u8, key, "buffer") and o.getOwn(key) == null and o.getAccessor(key) == null) return Value.obj(ta.buffer);
                    if (std.mem.eql(u8, key, "BYTES_PER_ELEMENT") and o.getOwn(key) == null and o.getAccessor(key) == null) return Value.num(@floatFromInt(ta.kind.byteSize()));
                    if (arrayIndex(key)) |i| {
                        if (i >= (cur orelse 0)) {
                            if (found) |slot| slot.* = false;
                            return Value.undef();
                        }
                        if (ta.kind.isBigInt()) return self.makeBigInt(value.taReadBig(ta, i));
                        return value.taRead(ta, i);
                    }
                    // A canonical numeric key that isn't a plain in-range index
                    // ("-0", "-1", "1.5", out-of-bounds, …) reads as undefined and
                    // never consults the prototype (Integer-Indexed [[Get]]).
                    if (canonicalNumericIndexString(key) != null) {
                        if (found) |slot| slot.* = false;
                        return Value.undef();
                    }
                    // other keys (methods, constructor, @@toStringTag) fall through.
                }
                if (o.is_array) {
                    // An arguments object's `length` is an ordinary own data
                    // property (deletable / redefinable), not the Array exotic
                    // length — once deleted it is simply absent (fall through to
                    // the prototype lookup), with no element-count fallback.
                    if (o.is_arguments) {
                        if (std.mem.eql(u8, key, "length")) {
                            if (o.getOwn("length")) |l| return l;
                        }
                    } else if (std.mem.eql(u8, key, "length"))
                        return Value.num(@floatFromInt(o.arrayLength()));
                    // An accessor defined on an index (via defineProperty) wins
                    // over the dense element store, so the getter is invoked.
                    if (arrayElementIndex(key)) |i| {
                        // A mapped arguments index reads its parameter binding.
                        if (argMapGet(o, i)) |mapped| return mapped;
                        // A present (non-hole) dense element with no index accessor
                        // is returned directly; a hole falls through to the proto
                        // chain so an inherited index (e.g. `Array.prototype[0]`) is
                        // seen, and an accessor likewise wins over the store.
                        if (o.getAccessor(key) == null) {
                            if (o.denseElement(i)) |v| return v;
                        }
                        // else fall through: hole, accessor, or a sparse named property.
                    }
                }
                if (!o.is_array) {
                    if (arrayElementIndex(key)) |i| {
                        if (o.getOwn(key) == null and o.getAccessor(key) == null) {
                            if (o.denseElement(i)) |v| return v;
                        }
                    }
                }
                // A String-wrapper object exposes `length` and indexed chars as
                // own integer-keyed properties (`new String("ab").length === 2`,
                // `[0] === "a"`).
                if (o.boxedPrimitive()) |p| {
                    if (p.isString()) {
                        if (std.mem.eql(u8, key, "length")) return Value.num(@floatFromInt(utf16LenOfValue(p)));
                        if (arrayIndex(key)) |i| {
                            if (try self.stringIndexValueOf(p, i)) |v| return v;
                        }
                    }
                }
                // Accessor or data, then walk the prototype chain (a native/bound
                // function with no explicit prototype inherits from
                // %Function.prototype% — so `fn.constructor`, `fn.call` as a
                // value, etc. resolve).
                var cur: ?*value.Object = o;
                var prototype_depth: usize = 0;
                while (cur) |c| {
                    if (c.proxyHandler() != null or c.proxy_revoked)
                        return self.proxyGet(c, key, receiver);
                    // A module namespace reached through the prototype chain (its
                    // exports live in the ModuleNs, not as own properties): a
                    // string [[Get]] triggers a deferred module's evaluation, then
                    // reads the export (its [[Prototype]] is null, so it ends here).
                    if (moduleNsOf(c)) |ns| {
                        try triggerDeferIfString(self, ns, key);
                        if (!moduleNsHas(ns, key)) {
                            if (found) |slot| slot.* = false;
                        }
                        return moduleNsGet(self, ns, key);
                    }
                    if (c.is_array and std.mem.eql(u8, key, "length")) {
                        // arguments `length` is an ordinary own property (absent
                        // once deleted); a real Array's is the exotic length.
                        if (c.is_arguments) {
                            if (c.getOwn("length")) |l| return l;
                        } else return Value.num(@floatFromInt(c.arrayLength())); // locked length read (grow-vs-read)
                    }
                    const named_own = c.namedOwnPropertySnapshot(key);
                    if (named_own == .accessor) {
                        const acc = named_own.accessor;
                        // An explicit `get: undefined` is stored as the undefined
                        // value but means "no getter".
                        if (acc.get) |g| {
                            if (!g.isUndefined()) return self.callValueWithThis(g, &.{}, receiver);
                        }
                        return Value.undef(); // accessor with no getter
                    }
                    if (c.is_array) {
                        if (arrayElementIndex(key)) |i| {
                            // A mapped arguments index reads its parameter binding.
                            if (argMapGet(c, i)) |mapped| return mapped;
                            // Locked dense read (no-GIL grow-vs-read class): a peer
                            // append/realloc must not race this len/bounds/element read.
                            if (c.getAccessor(key) == null) if (c.denseElement(i)) |v| return v;
                        }
                    } else if (arrayElementIndex(key)) |i| {
                        if (c.getOwn(key) == null and c.getAccessor(key) == null) if (c.denseElement(i)) |v| return v;
                    }
                    if (c.boxedPrimitive()) |p| {
                        if (p.isString()) {
                            if (std.mem.eql(u8, key, "length")) return Value.num(@floatFromInt(utf16LenOfValue(p)));
                            if (arrayIndex(key)) |i| {
                                if (try self.stringIndexValueOf(p, i)) |v| return v;
                            }
                        }
                    }
                    if (named_own == .data) {
                        const own = named_own.data;
                        if (prototype_depth == 1) if (inherited_observation) |observation| {
                            observation.* = .{
                                .receiver_shape = o.shapeSnapshot(),
                                .holder_shape = own.shape,
                                .slot = own.slot,
                            };
                        };
                        return own.value;
                    }
                    if (c.hostClassHooks()) |hooks| if (hooks.get) |get| {
                        self.recordExecutionTier(.host_callbacks);
                        switch (try get(@ptrCast(self), c, key)) {
                            .unhandled => {},
                            .value => |v| return v,
                        }
                    };
                    cur = self.effectiveProto(c);
                    prototype_depth += 1;
                }
                // On the global object, an absent own property falls back to the
                // global lexical bindings, so `globalThis.Math`, `this.parseInt`,
                // etc. resolve to the installed globals.
                if (self.global_object != null and o == self.global_object.?) {
                    if (rootEnv(self.env).get(key)) |v| return v;
                }
                // Accessing a private member the object doesn't carry is a brand
                // violation — a TypeError, not `undefined`.
                if (value.isPrivateKey(key)) return self.throwError("TypeError", "Cannot read private member from an object whose class did not declare it");
                // Legacy intrinsic gaps may still use a kind constructor fallback,
                // but an explicit null prototype must terminate lookup exactly.
                if (std.mem.eql(u8, key, "constructor") and !o.protoExplicitNull()) {
                    if (self.constructorOf(recv)) |ctor| return ctor;
                }
                if (found) |slot| slot.* = false;
                return Value.undef();
            },
            .string, .number, .boolean => return self.getPrimitiveMember(recv, key),
            .undefined, .null => return self.throwError("TypeError", notAnObjectMessage(recv)),
        }
    }

    /// [[Get]] on a primitive base: ToObject(base) for lookup, with the original
    /// primitive as the receiver passed to inherited accessors/proxy traps.
    fn getPrimitiveMember(self: *Interpreter, recv: Value, key: []const u8) EvalError!Value {
        if (recv.isString()) {
            if (std.mem.eql(u8, key, "length")) return Value.num(@floatFromInt(utf16LenOfValue(recv)));
            if (arrayIndex(key)) |i| {
                if (try self.stringIndexValueOf(recv, i)) |v| return v;
                return Value.undef();
            }
        }
        const boxed = try self.boxPrimitiveBase(recv);
        var cur: ?*value.Object = boxed;
        while (cur) |c| {
            if (c.proxyHandler() != null or c.proxy_revoked)
                return self.proxyGet(c, key, recv);
            if (c.getAccessor(key)) |acc| {
                if (acc.get) |g| {
                    if (!g.isUndefined()) return self.callValueWithThis(g, &.{}, recv);
                }
                return Value.undef();
            }
            if (c.getOwn(key)) |v| return v;
            cur = self.effectiveProto(c);
        }
        if (std.mem.eql(u8, key, "constructor")) {
            if (self.constructorOf(recv)) |ctor| return ctor;
        }
        return Value.undef();
    }

    /// The global constructor for a value's kind (`[].constructor === Array`).
    /// A fallback used when the prototype chain doesn't supply `constructor`
    /// (instance prototypes aren't wired yet).
    fn constructorOf(self: *Interpreter, recv: Value) ?Value {
        const name: []const u8 = switch (recv.kind()) {
            .string => "String",
            .number => "Number",
            .boolean => "Boolean",
            .object => blk: {
                const o = recv.asObj();
                break :blk if (o.is_array) "Array" else if (o.behavior.is_regex) "RegExp" else if (o.is_symbol) "Symbol" else if (o.behavior.is_error) (if (o.errorName().len > 0) o.errorName() else "Error") else if (o.is_map) "Map" else if (o.is_set) "Set" else if (o.behavior.is_date) "Date" else if (o.boxedPrimitive()) |p| (switch (p.kind()) {
                    .number => "Number",
                    .string => "String",
                    .boolean => "Boolean",
                    else => "Object",
                }) else if (o.isCallableObject()) "Function" else "Object";
            },
            else => return null,
        };
        return self.env.get(name);
    }

    // ---- destructuring ----------------------------------------------------

    /// Bind a value to a destructuring target. `declare` selects whether leaf
    /// identifiers are declared in the current scope (`let {a}=…`) or assigned
    /// to an existing binding / member (`({a}=…)` and parameter binding uses
    /// declare).
    /// VM entry for `bind_pattern`: destructure `val` into `target` with the
    /// given mode (0 var, 1 let, 2 const, 3 assignment), reusing `bindPattern`.
    pub fn bindPatternVM(self: *Interpreter, target: *Node, val: Value, mode: u32) EvalError!void {
        const saved_const = self.binding_const;
        const saved_hoist = self.binding_hoisted;
        self.binding_const = (mode == 2);
        self.binding_hoisted = false;
        defer {
            self.binding_const = saved_const;
            self.binding_hoisted = saved_hoist;
        }
        try self.bindPattern(target, val, mode != 3);
    }

    fn bindPattern(self: *Interpreter, target: *Node, val: Value, declare: bool) EvalError!void {
        switch (target.*) {
            .identifier => |name| if (declare)
                (if (self.binding_hoisted)
                    try self.globalDefine(name, val)
                else if (self.binding_const)
                    try self.env.putConst(name, val)
                else
                    try self.env.put(name, val))
            else
                // Assignment-form target: route through `assignTo` so const/TDZ/
                // strict/with checks apply (e.g. `[c] = …` with const `c`).
                try self.assignTo(target, val),
            .member => |m| { // assignment destructuring into obj.prop / arr[i]
                const recv = try self.eval(m.object);
                const key = try self.memberKey(m.property, m.computed);
                try self.setMember(recv, key, val);
            },
            .super_member => try self.assignTo(target, val),
            .obj_pattern => |p| try self.destructureObject(p.props, p.rest, val, declare),
            .arr_pattern => |p| try self.destructureArray(p.elems, p.rest, val, declare),
            else => return self.throwError("SyntaxError", "invalid destructuring target"),
        }
    }

    fn capturePatternIdentifierReference(self: *Interpreter, target: ?*Node, declare: bool) EvalError!?BindingReference {
        const node = target orelse return null;
        if (node.* != .identifier) return null;
        // Lexical BindingInitialization targets the freshly instantiated record
        // directly. Assignment and hoisted `var` patterns instead perform
        // ResolveBinding at each leaf's specified evaluation point.
        if (declare and !self.binding_hoisted) return null;
        return try self.captureBindingReference(node.identifier, null);
    }

    fn bindPatternWithReference(
        self: *Interpreter,
        target: *Node,
        val: Value,
        declare: bool,
        reference: ?BindingReference,
    ) EvalError!void {
        if (reference) |resolved|
            return self.storeCapturedBindingReference(resolved, target.identifier, val);
        return self.bindPattern(target, val, declare);
    }

    fn setSuperMemberResolved(self: *Interpreter, property: []const u8, computed: ?*Node, computed_key: Value, v: Value) EvalError!void {
        const home = self.home_object orelse return self.throwError("SyntaxError", "'super' outside a method");
        if (!self.this_initialized) return self.throwError("ReferenceError", "Must call super constructor before using 'this'");
        const parent = home.protoAtomic() orelse return self.throwError("TypeError", "Cannot set property of null (super)");
        const key = if (computed != null) try self.keyOf(computed_key) else try value.encodeStringKey(self.arena, property);
        if (!try self.setMemberResult(Value.obj(parent), key, v, self.this_value)) {
            if (self.strict) return self.throwError("TypeError", "Cannot set property");
        }
    }

    /// JavaScriptCore reports the first statically-known key of an object
    /// binding pattern and omits it when there is none (a computed first key, an
    /// empty pattern, or rest-only). Both execution tiers share this wording.
    pub fn throwDestructureError(self: *Interpreter, key: ?[]const u8) EvalError {
        const name = key orelse
            return self.throwError("TypeError", "Cannot destructure null or undefined value");
        return self.throwError("TypeError", try std.fmt.allocPrint(
            self.arena,
            "Cannot destructure property '{s}' from null or undefined value",
            .{name},
        ));
    }

    fn destructureObject(self: *Interpreter, props: []ast.ObjPatProp, rest: ?*Node, val: Value, declare: bool) EvalError!void {
        if (val.isUndefined() or val.isNull())
            return self.throwDestructureError(if (props.len != 0 and props[0].key_expr == null) props[0].key else null);
        var consumed: std.ArrayListUnmanaged([]const u8) = .empty;
        for (props) |prop| {
            const key = if (prop.key_expr) |ke| try self.keyOf(try self.eval(ke)) else try value.encodeStringKey(self.arena, prop.key);
            try consumed.append(self.arena, key);
            // KeyedDestructuringAssignmentEvaluation: when the target is a plain
            // member reference (assignment form), its reference (base, then the key
            // EXPRESSION) is evaluated BEFORE GetV(value, key) — and ToPropertyKey of
            // the target's computed key is deferred to PutValue, after GetV.
            const member_assign = !declare and (prop.target.* == .member or prop.target.* == .super_member);
            var m_base: Value = undefined;
            var m_keyval: Value = undefined;
            if (member_assign) {
                switch (prop.target.*) {
                    .member => |m| {
                        m_base = try self.eval(m.object);
                        if (m.computed) |ce| m_keyval = try self.eval(ce);
                    },
                    .super_member => |m| {
                        if (m.computed) |ce| m_keyval = try self.eval(ce);
                    },
                    else => unreachable,
                }
            }
            // KeyedBindingInitialization/AssignmentEvaluation resolves a plain
            // identifier target before GetV(value, P). Retain that exact base,
            // not merely the observable `with` lookup, across getters/defaults.
            const binding_reference = try self.capturePatternIdentifierReference(prop.target, declare);
            const binding_reference_root = try self.pushOptionalBindingReferenceRoot(binding_reference);
            defer if (binding_reference_root) |mark| self.restoreTempBindingReferenceRoots(mark);
            var v = try self.getProperty(val, key);
            if (v.isUndefined()) {
                if (prop.default) |d| {
                    v = try self.eval(d);
                    if (prop.target.* == .identifier) try self.maybeNameAnon(v, d, prop.target.identifier);
                }
            }
            if (member_assign) {
                switch (prop.target.*) {
                    .member => |m| {
                        const tkey = if (m.computed != null) try self.keyOf(m_keyval) else m.property;
                        try self.setMember(m_base, tkey, v);
                    },
                    .super_member => |m| try self.setSuperMemberResolved(m.property, m.computed, m_keyval, v),
                    else => unreachable,
                }
            } else {
                try self.bindPatternWithReference(
                    prop.target,
                    v,
                    declare,
                    self.tempOptionalBindingReferenceRoot(binding_reference_root, binding_reference),
                );
            }
        }
        if (rest) |rest_target| {
            // RestDestructuringAssignmentEvaluation creates the target Reference
            // before CopyDataProperties. Keep its base, raw computed key, and
            // super base stable while source getters run; ToPropertyKey and the
            // final PutValue deliberately remain after the copy.
            var rest_recv: Value = Value.undef();
            var rest_member: ?struct { property: []const u8, computed: bool, keyval: Value } = null;
            var rest_super: ?struct { base: Value, property: []const u8, computed: bool, keyval: Value } = null;
            const rest_binding_reference = try self.capturePatternIdentifierReference(rest_target, declare);
            const rest_binding_reference_root = try self.pushOptionalBindingReferenceRoot(rest_binding_reference);
            defer if (rest_binding_reference_root) |mark| self.restoreTempBindingReferenceRoots(mark);
            if (!declare) switch (rest_target.*) {
                .member => |member| {
                    rest_recv = try self.eval(member.object);
                    const keyval = if (member.computed) |key| try self.eval(key) else Value.undef();
                    rest_member = .{ .property = member.property, .computed = member.computed != null, .keyval = keyval };
                },
                .super_member => |member| {
                    _ = self.home_object orelse return self.throwError("SyntaxError", "'super' outside a method");
                    if (!self.this_initialized) return self.throwError("ReferenceError", "Must call super constructor before using 'this'");
                    const keyval = if (member.computed) |key| try self.eval(key) else Value.undef();
                    // The key expression may collect and relocate the home
                    // object. Re-read the interpreter-owned root before the
                    // spec's subsequent GetSuperBase step.
                    const home = self.home_object orelse return self.throwError("SyntaxError", "'super' outside a method");
                    rest_super = .{
                        .base = if (home.protoAtomic()) |base| Value.obj(base) else Value.nul(),
                        .property = member.property,
                        .computed = member.computed != null,
                        .keyval = keyval,
                    };
                },
                else => {},
            };
            const rest_obj = try self.copyObjectRest(val, consumed.items);
            // A declaration binds the rest name; an assignment writes through the
            // target reference — which may be a member (`({...obj.y} = …)`), so it
            // runs a setter / honors a const binding like any other assignment.
            if (declare) {
                try self.bindPatternWithReference(
                    rest_target,
                    rest_obj,
                    true,
                    self.tempOptionalBindingReferenceRoot(rest_binding_reference_root, rest_binding_reference),
                );
            } else if (rest_member) |member| {
                // PutValue checks the captured base before coercing the raw
                // computed key. A nullish base therefore throws without running
                // a user-defined toString after CopyDataProperties completes.
                if (rest_recv.isNull() or rest_recv.isUndefined())
                    return self.throwError("TypeError", notAnObjectMessage(rest_recv));
                const key = if (member.computed) try self.keyOf(member.keyval) else member.property;
                try self.setMember(rest_recv, key, rest_obj);
            } else if (rest_super) |super_ref| {
                if (!super_ref.base.isObject()) return self.throwError("TypeError", "Cannot set property of null (super)");
                const key = if (super_ref.computed) try self.keyOf(super_ref.keyval) else super_ref.property;
                if (!try self.setMemberResult(super_ref.base, key, rest_obj, self.this_value)) {
                    if (self.strict) return self.throwError("TypeError", "Cannot set property");
                }
            } else {
                try self.bindPatternWithReference(
                    rest_target,
                    rest_obj,
                    false,
                    self.tempOptionalBindingReferenceRoot(rest_binding_reference_root, rest_binding_reference),
                );
            }
        }
    }

    /// CopyDataProperties for object binding-rest. Excluded keys have already
    /// undergone ToPropertyKey, so this helper performs no user-visible coercion.
    fn copyObjectRest(self: *Interpreter, val: Value, excluded: []const []const u8) EvalError!Value {
        if (val.isUndefined() or val.isNull())
            return self.throwDestructureError(null);
        const rest_obj = try self.newObject();
        if (val.isObject()) {
            // Object rest copies only enumerable own properties, in
            // [[OwnPropertyKeys]] order. That includes dense array indexes and
            // symbol keys, not just named shape slots.
            const vo = val.asObj();
            const keys = try self.objectOwnKeysList(vo);
            outer: for (keys) |k| {
                if (value.isPrivateKey(k)) continue;
                for (excluded) |excluded_key| {
                    if (std.mem.eql(u8, excluded_key, k)) continue :outer;
                }
                const desc = try builtins.objectGetOwnPropertyDescriptor(self, Value.undef(), &.{ val, try self.keyToValue(k) });
                if (!(desc.isObject() and (try self.getProperty(desc, "enumerable")).toBoolean())) continue;
                // Copy via [[Get]] so an accessor's getter runs (and a data
                // property's value is read), landing as a plain data prop.
                try self.setProp(rest_obj.asObj(), k, try self.getProperty(val, k));
            }
        } else if (val.isString()) {
            // ToObject(string): a String exotic object whose own *enumerable*
            // properties are its UTF-16 index chars (`{...r} = "foo"` ⇒
            // r = {0:"f",1:"o",2:"o"}; `length` is non-enumerable). Other
            // primitives (number/boolean/symbol/bigint) have no own enumerable
            // properties, so their rest object is correctly empty.
            var code_units = StringCodeUnitIterator.initValue(val);
            var i: usize = 0;
            outer_str: while (code_units.next()) |cu| : (i += 1) {
                const k = try std.fmt.allocPrint(self.arena, "{d}", .{i});
                for (excluded) |excluded_key| {
                    if (std.mem.eql(u8, excluded_key, k)) continue :outer_str;
                }
                try self.setProp(rest_obj.asObj(), k, try self.stringValueFromCodeUnit(cu.unit));
            }
        }
        return rest_obj;
    }

    pub fn objectRestVM(self: *Interpreter, val: Value, excluded_values: []const Value) EvalError!Value {
        var excluded: std.ArrayListUnmanaged([]const u8) = .empty;
        for (excluded_values) |key| try excluded.append(self.arena, try self.keyOf(key));
        return self.copyObjectRest(val, excluded.items);
    }

    fn destructureArray(self: *Interpreter, elems: []ast.ArrPatElem, rest: ?*Node, val: Value, declare: bool) EvalError!void {
        if (val.isUndefined() or val.isNull())
            return self.throwError("TypeError", notAnObjectMessage(val));

        // ArrayBindingPattern/AssignmentPattern always uses GetIterator, even for
        // packed arrays: both @@iterator and the returned iterator's `next` are
        // observable mutable properties.
        const record = try self.getIteratorRecord(val);
        const iter_obj = record.iterator;
        const iter_root = try self.pushTempRoot(iter_obj);
        defer self.restoreTempRoots(iter_root);
        const next_method = record.next_method;
        const next_root = try self.pushTempRoot(next_method);
        defer self.restoreTempRoots(next_root);
        var done = false;
        // IteratorClose on an abrupt completion: if any element step (target
        // reference, default expression, assignment, or pattern) throws while the
        // iterator is still open, close it (the original throw wins). A throw from
        // IteratorStep/IteratorValue itself marks the iterator done (no close).
        errdefer if (!done) self.iteratorCloseKeepingThrow(iter_obj);
        for (elems) |elem| {
            // Assignment destructuring evaluates a member target's Reference
            // (its object, then the computed key EXPRESSION) BEFORE IteratorStep, so
            // a throw there closes the still-open iterator without ever calling
            // `next()`. ToPropertyKey of the computed key is deferred to PutValue.
            var member_recv: Value = Value.undef();
            var member_keyval: Value = Value.undef();
            var member_kind: enum { none, member, super_member } = .none;
            const binding_reference = try self.capturePatternIdentifierReference(elem.target, declare);
            const binding_reference_root = try self.pushOptionalBindingReferenceRoot(binding_reference);
            defer if (binding_reference_root) |mark| self.restoreTempBindingReferenceRoots(mark);
            if (!declare) if (elem.target) |t| switch (t.*) {
                .member => |m| {
                    member_kind = .member;
                    member_recv = try self.eval(m.object);
                    if (m.computed) |ce| member_keyval = try self.eval(ce);
                },
                .super_member => |m| {
                    member_kind = .super_member;
                    if (m.computed) |ce| member_keyval = try self.eval(ce);
                },
                else => {},
            };
            var v: Value = Value.undef();
            if (!done) {
                const res = self.callValueWithThis(next_method, &.{}, iter_obj) catch |e| {
                    done = true;
                    return e;
                };
                if (!res.isObject() or res.asObj().is_symbol or res.asObj().is_bigint) {
                    done = true;
                    return self.throwError("TypeError", "iterator result is not an object");
                }
                const is_done = (self.getProperty(res, "done") catch |e| {
                    done = true;
                    return e;
                }).toBoolean();
                if (is_done) done = true else v = self.getProperty(res, "value") catch |e| {
                    done = true;
                    return e;
                };
            }
            if (elem.target) |t| {
                if (v.isUndefined()) {
                    if (elem.default) |d| {
                        v = try self.eval(d);
                        if (t.* == .identifier) try self.maybeNameAnon(v, d, t.identifier);
                    }
                }
                switch (member_kind) {
                    .member => {
                        const m = t.member;
                        const tkey = if (m.computed != null) try self.keyOf(member_keyval) else m.property;
                        try self.setMember(member_recv, tkey, v);
                    },
                    .super_member => {
                        const m = t.super_member;
                        try self.setSuperMemberResolved(m.property, m.computed, member_keyval, v);
                    },
                    .none => try self.bindPatternWithReference(
                        t,
                        v,
                        declare,
                        self.tempOptionalBindingReferenceRoot(binding_reference_root, binding_reference),
                    ),
                }
            }
        }
        if (rest) |rest_target| {
            // Like an element, a member rest target's Reference is evaluated BEFORE
            // the iterator is drained (a throw here closes it, having stepped only
            // for the preceding elements).
            var rest_recv: Value = Value.undef();
            var rest_key: ?[]const u8 = null;
            var rest_super: ?struct { property: []const u8, computed: ?*Node, keyval: Value } = null;
            const binding_reference = try self.capturePatternIdentifierReference(rest_target, declare);
            const binding_reference_root = try self.pushOptionalBindingReferenceRoot(binding_reference);
            defer if (binding_reference_root) |mark| self.restoreTempBindingReferenceRoots(mark);
            if (!declare) switch (rest_target.*) {
                .member => |m| {
                    rest_recv = try self.eval(m.object);
                    rest_key = try self.memberKey(m.property, m.computed);
                },
                .super_member => |m| {
                    var keyval: Value = Value.undef();
                    if (m.computed) |ce| keyval = try self.eval(ce);
                    rest_super = .{ .property = m.property, .computed = m.computed, .keyval = keyval };
                },
                else => {},
            };
            const rest_arr = try self.newArray();
            while (!done) {
                const res = self.callValueWithThis(next_method, &.{}, iter_obj) catch |e| {
                    done = true;
                    return e;
                };
                if (!res.isObject() or res.asObj().is_symbol or res.asObj().is_bigint) {
                    done = true;
                    return self.throwError("TypeError", "iterator result is not an object");
                }
                if ((self.getProperty(res, "done") catch |e| {
                    done = true;
                    return e;
                }).toBoolean()) {
                    done = true;
                    break;
                }
                try rest_arr.asObj().appendElement(self.arena, try self.getProperty(res, "value"));
            }
            if (rest_key) |k|
                try self.setMember(rest_recv, k, rest_arr)
            else if (rest_super) |s|
                try self.setSuperMemberResolved(s.property, s.computed, s.keyval, rest_arr)
            else
                try self.bindPatternWithReference(
                    rest_target,
                    rest_arr,
                    declare,
                    self.tempOptionalBindingReferenceRoot(binding_reference_root, binding_reference),
                ); // iterator already exhausted
            return;
        }
        // IteratorClose: if destructuring finished before the iterator was
        // exhausted, call its `return()` to let it clean up. This is a NORMAL
        // completion close — its own throw must propagate — so disarm the abrupt
        // errdefer first (set `done`) to avoid a double close.
        const needs_close = !done;
        done = true;
        if (needs_close) try self.iteratorClose(iter_obj);
    }

    /// IteratorClose: invoke `iterator.return()` if present (generators are
    /// closed through their dispatched `return`). The result is discarded; a
    /// throw propagates (normal-completion close).
    pub fn iteratorClose(self: *Interpreter, iter: Value) EvalError!void {
        if (iter.isObject() and iter.asObj().generator() != null) {
            const r = try self.callMethod(iter, "return", &.{});
            if (!r.isObject()) return self.throwError("TypeError", "iterator 'return' did not return an object");
            return;
        }
        // GetMethod(iterator, "return"): absent (undefined/null) → no close; a
        // present-but-non-callable `return` is a TypeError. A normal-completion
        // close also requires `return()` to return an object.
        const ret = try self.getProperty(iter, "return");
        if (ret.isUndefined() or ret.isNull()) return;
        if (!ret.isCallable()) return self.throwError("TypeError", "iterator 'return' is not a function");
        const r = try self.callValueWithThis(ret, &.{}, iter);
        if (!r.isObject()) return self.throwError("TypeError", "iterator 'return' did not return an object");
    }

    /// IteratorClose with an existing throw completion: close `iter`, but keep the
    /// pending exception (a throw from `return()` is discarded — the original
    /// completion wins). Used when an iterator-helper callback throws.
    pub fn iteratorCloseKeepingThrow(self: *Interpreter, iter: Value) void {
        const saved = self.exception;
        self.iteratorClose(iter) catch {};
        self.exception = saved;
    }

    /// AsyncIteratorClose: invoke and await `iterator.return()` if present. Used
    /// by `for await` for normal/break/return completions, where close errors
    /// replace the original completion.
    fn asyncIteratorClose(self: *Interpreter, iter: Value) EvalError!void {
        const ret = try self.getProperty(iter, "return");
        if (ret.isUndefined() or ret.isNull()) return;
        if (!ret.isCallable()) return self.throwError("TypeError", "async iterator 'return' is not a function");
        const r = try self.awaitValue(try self.callValueWithThis(ret, &.{}, iter));
        if (!builtins.isRealObject(r)) return self.throwError("TypeError", "async iterator 'return' did not return an object");
    }

    /// AsyncIteratorClose over an existing throw completion: suppress any close
    /// failure (including return lookup, call, await rejection, or result-shape
    /// error) and restore the original thrown value.
    fn asyncIteratorCloseKeepingThrow(self: *Interpreter, iter: Value) void {
        const saved = self.exception;
        self.asyncIteratorClose(iter) catch {};
        self.exception = saved;
    }

    /// Close every iterator in `list` in reverse list order while preserving the
    /// in-flight throw completion (its value in `self.exception`): any error a
    /// `return()` raises is discarded. Mirrors IteratorCloseAll over a Throw
    /// completion for the `Iterator.zip` setup phase.
    pub fn closeListKeepingThrow(self: *Interpreter, list: []const Value) void {
        const saved = self.exception;
        var i: usize = list.len;
        while (i > 0) {
            i -= 1;
            self.iteratorClose(list[i]) catch {};
            self.exception = saved;
        }
    }

    /// Element `i` of an array/string for array destructuring (undefined if out
    /// of range). Non-iterable values raise a TypeError.
    fn elementAt(self: *Interpreter, val: Value, i: usize) EvalError!Value {
        switch (val.kind()) {
            .object => {
                const o = val.asObj();
                if (!o.is_array) return self.throwError("TypeError", "value is not iterable");
                // Array destructuring consumes the array iterator: indices below
                // the logical length read through [[Get]], so holes, sparse tails,
                // inherited index properties, and accessors are observable.
                if (i >= o.arrayLength()) return Value.undef();
                return self.arrIndexGet(o, i);
            },
            .string => {
                const s = val.asStr();
                if (i >= s.len) return Value.undef();
                return try Value.strOwned(self.arena, try self.arena.dupe(u8, s[i .. i + 1]));
            },
            else => return self.throwError("TypeError", "value is not iterable"),
        }
    }

    fn iterableLen(val: Value) usize {
        return switch (val.kind()) {
            .object => if (val.asObj().is_array) val.asObj().arrayLength() else 0,
            .string => val.asStr().len,
            else => 0,
        };
    }

    /// Assign to a named variable with the same immutability checks `assignTo`
    /// applies, for the bytecode VM's `store_var` (which would otherwise bypass
    /// them): a `const` reassignment throws; a function-expression name throws in
    /// strict code and is a no-op in sloppy code.
    pub fn assignVarVM(self: *Interpreter, name: []const u8, v: Value) EvalError!void {
        // A `with` object that provides this name takes the write (its
        // SetMutableBinding: HasProperty re-check, then Set) — the VM store path
        // must consult it just like the tree-walker's assignTo, or the write
        // wrongly falls through to a fresh global.
        if (try self.assignWithObject(name)) |o| {
            const still = try self.hasPropertyResult(o, name); // SetMutableBinding step 2
            if (!still and self.strict) return self.throwError("ReferenceError", name);
            return self.setMember(Value.obj(o), name, v);
        }
        // SetMutableBinding observes an uninitialized declarative binding before
        // its mutability. In particular `const x = (x = 1)` is a ReferenceError,
        // not the TypeError used for assignment after initialization.
        if (self.env.get(name)) |current|
            if (self.isTdz(current)) return self.throwError("ReferenceError", name);
        if (self.env.isAlias(name)) return self.throwError("TypeError", "Assignment to constant variable.");
        if (self.env.isConst(name)) |c| {
            if (c) return self.throwError("TypeError", "Assignment to constant variable.");
        }
        if (self.env.isFnName(name)) {
            if (self.strict) return self.throwError("TypeError", "Assignment to constant variable.");
            return;
        }
        if (self.env.get(name) == null) {
            if (self.strict and !try self.globalHasBinding(name))
                return self.throwError("ReferenceError", name);
            if (self.currentGlobalObject()) |g| return self.setMember(Value.obj(g), name, v);
        }
        if (self.globalBindingObject(name)) |g| {
            try self.setMember(Value.obj(g), name, v);
            if (g.getOwn(name)) |nv| try self.env.assign(name, nv);
            return;
        }
        try self.env.assign(name, v);
    }

    /// GetValue for a dynamically captured identifier Reference. Static
    /// frame/upvalue fallbacks are handled by the VM because their storage does
    /// not live in an Environment Record. Object Environment Records repeat
    /// HasProperty for GetBindingValue but never repeat the earlier
    /// @@unscopables query from HasBinding.
    pub fn loadCapturedBindingReference(
        self: *Interpreter,
        reference: BindingReference,
        name: []const u8,
        allow_unresolvable: bool,
    ) EvalError!CapturedBindingValue {
        switch (reference) {
            .empty => return self.throwError("InternalError", "uninitialized binding reference"),
            .static => unreachable,
            .with_object, .global_object => |object| {
                const object_fallback = Value.obj(object);
                const object_root = try self.pushTempRoot(object_fallback);
                defer self.restoreTempRoots(object_root);
                if (!try self.hasPropertyResult(self.tempRoot(object_root, object_fallback).asObj(), name)) {
                    if (self.strict) return self.throwError("ReferenceError", name);
                    return .{ .value = Value.undef() };
                }
                const result = try self.getProperty(self.tempRoot(object_root, object_fallback), name);
                return .{
                    .value = result,
                    .with_base = if (reference == .with_object)
                        self.tempRoot(object_root, object_fallback)
                    else
                        Value.undef(),
                };
            },
            .unresolvable => {
                if (allow_unresolvable) return .{ .value = Value.undef() };
                return self.throwError("ReferenceError", name);
            },
            .environment => |environment| {
                const result = environment.getOwnResolved(name) orelse
                    return self.throwError("ReferenceError", name);
                if (self.isTdz(result)) return self.throwError("ReferenceError", name);
                return .{ .value = result };
            },
        }
    }

    pub fn resolveBindingValue(self: *Interpreter, name: []const u8, allow_unresolvable: bool) EvalError!CapturedBindingValue {
        // GetValue is immediate: do not first create a captured Reference and
        // then probe the same declarative binding a second time. Exact retained
        // References remain mandatory for assignment/update/destructuring paths
        // whose RHS can retarget the environment before PutValue.
        if (try self.lookupIdentValue(name)) |resolved| {
            if (self.isTdz(resolved.value)) return self.throwError("ReferenceError", name);
            return resolved;
        }
        if (try self.globalProp(name)) |global| return .{ .value = global };
        if (allow_unresolvable) return .{ .value = Value.undef() };
        return self.throwError("ReferenceError", name);
    }

    /// PutValue for a dynamically captured identifier Reference. Static
    /// frame/upvalue fallbacks are handled by the VM because their storage does
    /// not live in an Environment Record.
    pub fn storeCapturedBindingReference(self: *Interpreter, reference: BindingReference, name: []const u8, v: Value) EvalError!void {
        const value_root = try self.pushTempRoot(v);
        defer self.restoreTempRoots(value_root);
        switch (reference) {
            .empty => return self.throwError("InternalError", "uninitialized binding reference"),
            .static => unreachable,
            .with_object, .global_object => |object| {
                // Object Environment Record SetMutableBinding performs its own
                // HasProperty after Reference creation, but never repeats the
                // earlier `@@unscopables` query for a `with` record. HasProperty
                // is observable and may force moving GC, so refresh the base
                // before the later Set.
                const object_fallback = Value.obj(object);
                const object_root = try self.pushTempRoot(object_fallback);
                defer self.restoreTempRoots(object_root);
                const still = try self.hasPropertyResult(self.tempRoot(object_root, object_fallback).asObj(), name);
                if (!still and self.strict) return self.throwError("ReferenceError", name);
                return self.setMember(
                    self.tempRoot(object_root, object_fallback),
                    name,
                    self.tempRoot(value_root, v),
                );
            },
            .unresolvable => {
                if (self.strict) return self.throwError("ReferenceError", name);
                const global = self.currentGlobalObject() orelse return self.env.assign(name, self.tempRoot(value_root, v));
                return self.setMember(Value.obj(global), name, self.tempRoot(value_root, v));
            },
            .environment => |environment| {
                switch (environment.resolvedBindingState(name, self.tdz_marker)) {
                    .tdz => return self.throwError("ReferenceError", name),
                    .immutable => return self.throwError("TypeError", "Assignment to constant variable."),
                    .function_name => {
                        if (self.strict) return self.throwError("TypeError", "Assignment to constant variable.");
                        return;
                    },
                    .missing => return self.throwError("ReferenceError", name),
                    .mutable => {},
                }

                if (!environment.assignOwnResolved(name, self.tempRoot(value_root, v)))
                    return self.throwError("ReferenceError", name);
            },
        }
    }

    pub fn defineLexicalVM(self: *Interpreter, name: []const u8, v: Value, is_const: bool) EvalError!void {
        try self.checkRestrictedGlobalLexical(name);
        if (is_const)
            try self.env.putConst(name, v)
        else
            try self.env.put(name, v);
    }

    fn assignTo(self: *Interpreter, target: *Node, v: Value) EvalError!void {
        switch (target.*) {
            .identifier => |name| {
                // A `with` object that provides this name (and isn't shadowed by a
                // closer binding) takes the write (honoring `[Symbol.unscopables]`).
                if (try self.assignWithObject(name)) |o| return self.setMember(Value.obj(o), name, v);
                // Assigning to a binding still in its TDZ is a ReferenceError.
                if (self.env.get(name)) |cur| {
                    if (self.isTdz(cur)) return self.throwError("ReferenceError", name);
                }
                // An imported binding is immutable (a module indirect binding):
                // assigning to it is a TypeError.
                if (self.env.isAlias(name)) return self.throwError("TypeError", "Assignment to constant variable.");
                // Assigning to a `const` binding is a TypeError.
                if (self.env.isConst(name)) |c| {
                    if (c) return self.throwError("TypeError", "Assignment to constant variable.");
                }
                // A named function expression's own name is immutable: throw in
                // strict code, silently ignore in sloppy code.
                if (self.env.isFnName(name)) {
                    if (self.strict) return self.throwError("TypeError", "Assignment to constant variable.");
                    return;
                }
                // Strict mode forbids creating a global by assigning to an
                // undeclared binding. Sloppy mode creates/configures a global
                // object property, not a non-deletable `var` binding.
                if (self.env.get(name) == null) {
                    if (self.strict and !try self.globalHasBinding(name))
                        return self.throwError("ReferenceError", name);
                    if (self.global_object) |g| return self.setMember(Value.obj(g), name, v);
                }
                if (self.globalBindingObject(name)) |g| {
                    try self.setMember(Value.obj(g), name, v);
                    if (g.getOwn(name)) |nv| try self.env.assign(name, nv);
                    return;
                }
                try self.env.assign(name, v);
            },
            .member => |m| {
                const recv = try self.eval(m.object);
                if (m.computed) |ce| {
                    // Same spec order as a member read: key expression first, then
                    // the null/undefined base check, then ToPropertyKey.
                    const kv = try self.eval(ce);
                    if (recv.isNull() or recv.isUndefined())
                        return self.throwError("TypeError", notAnObjectMessage(recv));
                    var fast_key_buf: [24]u8 = undefined;
                    const key = if (fastNumericIndex(kv)) |idx| blk: {
                        if (try self.setFastArrayNumericIndex(recv, idx, v)) return;
                        break :blk std.fmt.bufPrint(&fast_key_buf, "{d}", .{idx}) catch unreachable;
                    } else try self.keyOf(kv);
                    return self.setMember(recv, key, v);
                }
                try self.setMember(recv, m.property, v);
            },
            // `super.x = v` / `super[e] = v`: PutValue on a super reference sets
            // the property with `this` as the receiver, so the write lands on (or
            // through an inherited setter of) the current instance.
            .super_member => |m| {
                const home = self.home_object orelse return self.throwError("SyntaxError", "'super' outside a method");
                // GetThisBinding precedes evaluating the key (see the read path): a
                // derived-ctor `super[expr] = …` before `super()` is a ReferenceError.
                if (!self.this_initialized) return self.throwError("ReferenceError", "Must call super constructor before using 'this'");
                // GetSuperBase before ToPropertyKey of the computed key (see the
                // read path), so a key `toString` that mutates the home prototype
                // can't redirect the write.
                const parent = home.protoAtomic() orelse return self.throwError("TypeError", "Cannot set property of null (super)");
                const key = try self.memberKey(m.property, m.computed);
                if (!try self.setMemberResult(Value.obj(parent), key, v, self.this_value)) {
                    if (self.strict) return self.throwError("TypeError", "Cannot set property");
                }
            },
            .call => {
                _ = try self.eval(target);
                return self.throwError("ReferenceError", "invalid assignment target");
            },
            // Assignment destructuring: `[a, b] = x` / `({a} = o)`.
            .obj_pattern, .arr_pattern => try self.bindPattern(target, v, false),
            else => return self.throwError("ReferenceError", "invalid assignment target"),
        }
    }

    /// Assign `recv[key] = v`. Arrays route integer keys to the dense element
    /// store (growing with holes); everything else is a named property. Shared
    /// by the tree-walker and the VM.
    pub fn setMember(self: *Interpreter, recv: Value, key: []const u8, v: Value) EvalError!void {
        if (!try self.setMemberResult(recv, key, v, recv)) {
            if (self.strict) return self.throwError("TypeError", "Cannot set property");
        }
    }

    /// Internal [[Set]] returning the spec boolean result. Assignment callers
    /// translate a false result into a strict-mode TypeError; Reflect.set returns
    /// the boolean directly.
    pub fn setMemberResult(self: *Interpreter, recv: Value, key: []const u8, v: Value, receiver: Value) EvalError!bool {
        if (recv.isObject()) try self.checkRestricted(recv.asObj());
        // PrivateSet is not OrdinarySet: it resolves the PrivateElement (writing a
        // field, invoking a setter, or a TypeError for a method / getter-only
        // accessor / unbranded object) — never creating a new own property.
        if (value.isPrivateKey(key)) {
            try self.privateSet(recv, key, v);
            return true;
        }
        if (recv.isObject() and (recv.asObj().is_symbol or recv.asObj().is_bigint))
            return self.setPrimitiveMemberResult(recv, key, v);
        if (!recv.isObject()) {
            if (recv.isNull() or recv.isUndefined())
                return self.throwError("TypeError", notAnObjectMessage(recv));
            return self.setPrimitiveMemberResult(recv, key, v);
        }
        const o = recv.asObj();
        if (o.proxyHandler() != null or o.proxy_revoked) return self.proxySet(o, key, v, receiver);
        // A module namespace's [[Set]] always fails: strict throws, sloppy is a
        // silent no-op.
        if (o.moduleNs() != null) return false;
        if (o.typedArray()) |ta| {
            // Integer-Indexed Exotic [[Set]] for a canonical numeric key.
            const numkey: ?f64 = if (arrayIndex(key)) |i| @as(f64, @floatFromInt(i)) else canonicalNumericIndexString(key);
            if (numkey) |n| {
                const same = (receiver.isObject() and receiver.asObj() == o);
                if (same) {
                    // IntegerIndexedElementSet: ToNumber/ToBigInt always runs (an
                    // observable valueOf, can throw) even for an out-of-bounds /
                    // detached index — and BEFORE the validity check, because the
                    // coercion can resize the buffer and change which index is
                    // valid; the store happens only if the index is valid after.
                    if (ta.kind.isBigInt()) {
                        const bv = try self.toBigIntValueImpl(v, false);
                        if (isValidIntegerIndex(ta, n)) value.taWriteBig(ta, @intFromFloat(n), bv.asObj().bigIntValue());
                    } else {
                        const num = try self.toNumberV(v);
                        if (isValidIntegerIndex(ta, n)) value.taWrite(ta, @intFromFloat(n), num);
                    }
                    return true;
                }
                // A different Receiver: an invalid index on the target is a no-op
                // that does NOT coerce the value. A valid target index does
                // OrdinarySet → CreateDataProperty(Receiver, P, V): on a typed-array
                // receiver that is a [[DefineOwnProperty]] (false for a bad index,
                // never an inherited setter); on any other object an ordinary set.
                if (!isValidIntegerIndex(ta, n)) return true;
                if (!receiver.isObject()) return true;
                const rcv = receiver.asObj();
                if (rcv.typedArray()) |rta| {
                    if (!isValidIntegerIndex(rta, n)) return false;
                    if (rta.kind.isBigInt()) {
                        const bv = try self.toBigIntValueImpl(v, false);
                        value.taWriteBig(rta, @intFromFloat(n), bv.asObj().bigIntValue());
                    } else {
                        value.taWrite(rta, @intFromFloat(n), try self.toNumberV(v));
                    }
                    return true;
                }
                if (rcv.proxyHandler() != null or rcv.proxy_revoked) {
                    const existing = try builtins.objectGetOwnPropertyDescriptor(@ptrCast(self), Value.undef(), &.{ Value.obj(rcv), try self.keyToValue(key) });
                    const desc = (try self.newObject()).asObj();
                    try desc.setOwn(self.arena, self.root_shape, "value", v);
                    if (existing.isObject()) {
                        if (existing.asObj().getOwn("get") != null or existing.asObj().getOwn("set") != null) return false;
                        if (existing.asObj().getOwn("writable")) |w| if (!w.toBoolean()) return false;
                    } else {
                        try desc.setOwn(self.arena, self.root_shape, "writable", Value.boolVal(true));
                        try desc.setOwn(self.arena, self.root_shape, "enumerable", Value.boolVal(true));
                        try desc.setOwn(self.arena, self.root_shape, "configurable", Value.boolVal(true));
                    }
                    return try builtins.defineOneResult(self, rcv, key, desc);
                }
                if (rcv.getAccessor(key) != null) return false;
                if (rcv.getOwn(key)) |_| {
                    if (!rcv.getAttr(key).writable) return false;
                    try self.setProp(rcv, key, v);
                    return true;
                }
                if (!rcv.isExtensible()) return false;
                const desc = (try self.newObject()).asObj();
                try desc.setOwn(self.arena, self.root_shape, "value", v);
                try desc.setOwn(self.arena, self.root_shape, "writable", Value.boolVal(true));
                try desc.setOwn(self.arena, self.root_shape, "enumerable", Value.boolVal(true));
                try desc.setOwn(self.arena, self.root_shape, "configurable", Value.boolVal(true));
                return builtins.defineOneResult(self, rcv, key, desc);
            }
            // non-index keys fall through to ordinary [[Set]].
        }
        if (o.boxedPrimitive()) |p| {
            if (p.isString()) {
                if (std.mem.eql(u8, key, "length")) return false;
                if (arrayIndex(key)) |i| if (i < utf16LenOfValue(p)) return false;
            }
        }
        if (o.is_arguments) {
            if (std.mem.eql(u8, key, "length")) {
                try self.setProp(o, key, v);
                return true;
            }
            if (arrayElementIndex(key)) |i| {
                // A mapped index writes through to its parameter binding (the
                // element is kept in sync so the descriptor's value stays current).
                if (argMapHas(o, i)) {
                    argMapSet(o, i, v);
                    _ = o.setElementAt(i, v);
                    return true;
                }
                // An accessor installed on this index (via defineProperty) routes
                // the write to its setter through the ordinary [[Set]] path below,
                // rather than overwriting the mapped element directly.
                if (o.getAccessor(key) == null and o.denseElementInBounds(i)) {
                    // A per-index descriptor may mark the element non-writable:
                    // sloppy ignores the write, strict throws (handled by caller).
                    if (o.attrsMap() != null and !o.getAttr(key).writable) return false;
                    _ = o.setDenseElement(i, v);
                    return true;
                }
            }
        }
        if (o.is_array and !o.is_arguments) {
            if (std.mem.eql(u8, key, "length") and receiver.isObject() and receiver.asObj() == o) {
                const u = try self.arrayLengthFromValue(v);
                // ArraySetLength: a non-writable `length` rejects the assignment
                // (the RangeError above still precedes this) — sloppy silently,
                // strict throws.
                if (o.attrsMap() != null and !o.getAttr("length").writable) return false;
                return try self.setArrayLength(o, u);
            }
            // An accessor defined on an index routes the write to its setter
            // (handled by the prototype-chain setter walk below), not the store.
            if (arrayElementIndex(key) != null and o.getAccessor(key) != null) {
                // fall through to the setter walk
            } else if (arrayElementIndex(key) != null and self.arrayProtoMayInterceptSet(o, key) and
                !o.denseElementPresent(arrayElementIndex(key).?))
            {
                // The index isn't an own present element and an inherited
                // accessor or Proxy can intercept the write — OrdinarySet routes
                // through the prototype chain before creating a local element.
            } else if (arrayElementIndex(key)) |i| {
                // A per-index descriptor (recorded in `attrs`) may mark the
                // element non-writable: sloppy ignores the write, strict throws.
                if (o.attrsMap() != null and !o.getAttr(key).writable) return false;
                if (receiver.isObject() and receiver.asObj() == o and o.denseElementPresent(i)) {
                    _ = o.setDenseElement(i, v); // an assignment fills a hole
                    return true;
                }
                // Holes and out-of-bounds writes must first run OrdinarySet's
                // prototype walk: inherited setters and non-writable data
                // descriptors block creating a local dense element.
            }
        }
        // A function's own `.prototype` is materialized lazily, so an assignment
        // that arrives before any read finds no own slot. Realize it first (with its
        // correct attributes — writable, non-enumerable, NON-configurable) so the
        // assignment updates the existing slot's VALUE rather than creating a fresh
        // {writable,enumerable,configurable} data property. This also lets a
        // generator's own writable slot shadow the non-writable `prototype`
        // (%GeneratorPrototype%) its [[Prototype]] carries, which would otherwise
        // reject the write.
        if (std.mem.eql(u8, key, "prototype") and receiver.isObject() and receiver.asObj() == o and
            o.getOwn("prototype") == null and o.getAccessor("prototype") == null and
            Interpreter.jsFunctionHasOwnPrototypeSlot(o))
        {
            _ = try self.getProperty(Value.obj(o), "prototype");
        }
        // A setter anywhere on the prototype chain intercepts the assignment.
        var cur: ?*value.Object = o;
        while (cur) |c| {
            if (c.proxyHandler() != null or c.proxy_revoked)
                return self.proxySet(c, key, v, receiver);
            // OrdinarySet delegates to an ancestor's [[Set]]: an Integer-Indexed
            // Exotic ancestor handles a canonical numeric key itself (writing to a
            // valid index of the Receiver, else a no-op), so a same-keyed accessor
            // further up the chain is never reached.
            if (c.typedArray() != null and canonicalNumericIndexString(key) != null)
                return self.setMemberResult(Value.obj(c), key, v, receiver);
            // String exotic character/length descriptors are non-writable own
            // data properties. They terminate OrdinarySet before an accessor
            // higher in the prototype chain can observe the write.
            if (c.boxedPrimitive()) |primitive| if (primitive.isString()) {
                if (std.mem.eql(u8, key, "length")) return false;
                if (arrayIndex(key)) |index| if (index < utf16LenOfValue(primitive)) return false;
            };
            // A real Array's `length` is an exotic own data descriptor rather
            // than a shape slot. A writable descriptor continues with the
            // Receiver; a frozen length rejects the set at this holder.
            if (c.is_array and !c.is_arguments and std.mem.eql(u8, key, "length")) {
                if (c.attrsMap() != null and !c.getAttr("length").writable) return false;
                break;
            }
            if (arrayElementIndex(key) == null and !isLazyFunctionPrototypeSlot(c, key)) {
                switch (c.namedOwnPropertySnapshot(key)) {
                    .accessor => |own| {
                        if (own.set) |s| {
                            // An explicit `set: undefined` means "no setter".
                            if (!s.isUndefined()) {
                                _ = try self.callValueWithThis(s, &.{v}, receiver);
                                return true;
                            }
                        }
                        return false;
                    },
                    .data => |own| {
                        if (!own.attr.writable) return false;
                        break;
                    },
                    .absent => {},
                }
            } else {
                if (c.getAccessor(key)) |acc| {
                    if (acc.set) |s| {
                        if (!s.isUndefined()) {
                            _ = try self.callValueWithThis(s, &.{v}, receiver);
                            return true;
                        }
                    }
                    return false;
                }
                // Integer-indexed/dense exotic descriptors are not represented
                // by the ordinary named-property snapshot.
                if (objectHasOwn(c, key)) {
                    if (!c.getAttr(key).writable) return false;
                    break;
                }
            }
            if (c.hostClassHooks()) |hooks| if (hooks.set) |set| {
                self.recordExecutionTier(.host_callbacks);
                switch (try set(@ptrCast(self), c, key, v)) {
                    .unhandled => {},
                    .declined => return true,
                    .accepted => |accepted| return accepted,
                }
            };
            cur = self.effectiveProto(c);
        }
        // [[Set]] attribute checks.
        if (arrayElementIndex(key) != null or isLazyFunctionPrototypeSlot(o, key)) {
            if (o.getOwn(key)) |_| {
                if (!o.getAttr(key).writable) return false;
            }
        }
        if (!builtins.isRealObject(receiver)) return false;
        const ro = receiver.asObj();
        if (ro.proxyHandler() != null or ro.proxy_revoked) {
            const existing = try builtins.objectGetOwnPropertyDescriptor(@ptrCast(self), Value.undef(), &.{ Value.obj(ro), try self.keyToValue(key) });
            const desc = (try self.newObject()).asObj();
            try desc.setOwn(self.arena, self.root_shape, "value", v);
            if (existing.isObject()) {
                if (existing.asObj().getOwn("get") != null or existing.asObj().getOwn("set") != null) return false;
                if (existing.asObj().getOwn("writable")) |w| {
                    if (!w.toBoolean()) return false;
                }
            } else {
                try desc.setOwn(self.arena, self.root_shape, "writable", Value.boolVal(true));
                try desc.setOwn(self.arena, self.root_shape, "enumerable", Value.boolVal(true));
                try desc.setOwn(self.arena, self.root_shape, "configurable", Value.boolVal(true));
            }
            return try builtins.defineOneResult(self, ro, key, desc);
        }
        if (moduleNsOf(ro) != null) {
            // OrdinarySetWithOwnDescriptor's [[GetOwnProperty]] on a namespace
            // receiver (e.g. `super[k] = v` whose receiver is a namespace): a
            // string key triggers a deferred module's evaluation. The define
            // itself fails (exports are non-configurable).
            try triggerDeferForKey(self, ro, key);
            _ = try moduleNsDesc(self, ro, key);
            return false;
        }
        const plain_named_receiver = arrayElementIndex(key) == null and !isLazyFunctionPrototypeSlot(ro, key);
        // With no published native shape dependency, finish the overwhelmingly
        // common same-receiver ordinary data write in one receiver lock. The
        // helper rechecks accessor/attribute/extensibility state after the
        // prototype walk, so a racing mutation cannot turn the fusion into a
        // stale descriptor decision. Published JIT artifacts retain the exact
        // pre-transition invalidation path below.
        if (plain_named_receiver and ro == o and
            (self.jit_owner == null or !self.jit_owner.?.hasPublishedArtifacts()))
        {
            switch (try ro.setOrdinaryOwnData(self.arena, self.root_shape, key, v)) {
                .blocked => return false,
                .created => return true,
                .updated => {
                    if (self.global_object != null and ro == self.global_object.?) {
                        const root = rootEnv(self.env);
                        const locked = root.lockBindingsForWrite();
                        defer root.unlockBindingsForWrite(locked);
                        if (!root.consts.contains(key)) {
                            if (root.vars.getPtr(key)) |slot| slot.* = v;
                        }
                    }
                    return true;
                },
            }
        }
        const had_receiver_own = if (plain_named_receiver) own: {
            switch (ro.namedOwnPropertySnapshot(key)) {
                .accessor => return false,
                .data => |own| {
                    if (!own.attr.writable) return false;
                    break :own true;
                },
                .absent => {
                    if (!ro.isExtensible()) return false;
                    break :own false;
                },
            }
        } else own: {
            if (ro.getAccessor(key) != null) return false;
            const present = ro.getOwn(key) != null or
                (if (arrayElementIndex(key)) |i| ro.denseElementPresent(i) else false);
            if (present) {
                if (!ro.getAttr(key).writable) return false;
            } else if (!ro.isExtensible()) return false;
            break :own present;
        };
        if (ro.is_array and !ro.is_arguments) {
            if (arrayElementIndex(key)) |i| {
                const old_len = ro.arrayLength();
                if (i >= old_len and ro.attrsMap() != null and !ro.getAttr("length").writable) return false;
                if (ro.attrsMap() != null and !ro.getAttr(key).writable) return false;
                const dense_cap: usize = 1 << 24;
                const dense_len = ro.elementsLen();
                if (i < dense_cap and i <= dense_len + 1024) {
                    _ = try ro.growDenseElement(self.arena, i, v);
                    return true;
                }
                try ro.extendArrayLengthFloor(self.arena, i + 1);
            }
        }
        try self.setProp(ro, key, v);
        if (self.global_object != null and ro == self.global_object.? and had_receiver_own) {
            const root = rootEnv(self.env);
            // consts + vars read under one lock hold: a peer `putConst` writes
            // consts under this lock (the no-GIL Environment race class), so the
            // membership test must not read it unlocked.
            const locked = root.lockBindingsForWrite();
            defer root.unlockBindingsForWrite(locked);
            if (!root.consts.contains(key)) {
                if (root.vars.getPtr(key)) |slot| slot.* = v;
            }
        }
        return true;
    }

    /// [[Set]] on a primitive base: ToObject(base), then walk inherited setters
    /// and Proxy set traps, but a data-property/no-property write ultimately
    /// fails because the original receiver is not an Object. Sloppy code ignores
    /// that false result; strict code throws.
    fn setPrimitiveMemberResult(self: *Interpreter, recv: Value, key: []const u8, v: Value) EvalError!bool {
        const boxed = try self.boxPrimitiveBase(recv);
        var cur: ?*value.Object = boxed;
        while (cur) |c| {
            if (c.proxyHandler() != null or c.proxy_revoked)
                return self.proxySet(c, key, v, recv);
            if (c.getAccessor(key)) |acc| {
                if (acc.set) |s| {
                    if (!s.isUndefined()) {
                        _ = try self.callValueWithThis(s, &.{v}, recv);
                        return true;
                    }
                }
                return false;
            }
            if (c.getOwn(key)) |_| return false;
            cur = self.effectiveProto(c);
        }
        return false;
    }

    /// `delete obj[key]`: remove an own property, returning whether the object
    /// no longer has it. Non-configurable own properties can't be deleted
    /// (returns false); a missing property "deletes" successfully (true).
    pub fn deleteOwn(self: *Interpreter, o: *value.Object, key: []const u8) EvalError!bool {
        try self.checkRestricted(o);
        if (o.proxyHandler() != null or o.proxy_revoked) return self.proxyDelete(o, key);
        // A module namespace's own properties (exports + @@toStringTag) are
        // non-configurable → [[Delete]] returns false; a non-own key "deletes".
        if (moduleNsOf(o)) |ns| {
            try triggerDeferIfString(self, ns, key);
            return !moduleNsHas(ns, key);
        }
        // Integer-Indexed Exotic [[Delete]]: a canonical numeric key cannot be
        // deleted when it is a valid index (returns false); any other numeric key
        // (out of bounds, "-0", fractional) "deletes" as a no-op (returns true).
        if (o.typedArray()) |ta| {
            if (canonicalNumericIndexString(key)) |n| return !isValidIntegerIndex(ta, n);
        }
        if (o.boxedPrimitive()) |p| {
            if (p.isString()) {
                if (std.mem.eql(u8, key, "length")) return false;
                if (arrayIndex(key)) |i| if (i < utf16LenOfValue(p)) return false;
            }
        }
        if (o.hostClassHooks()) |hooks| if (hooks.delete) |delete| {
            self.recordExecutionTier(.host_callbacks);
            switch (try delete(@ptrCast(self), o, key)) {
                .unhandled => {},
                .accepted => |accepted| return accepted,
            }
        };
        // Without published native shape dependencies, ordinary named deletion
        // needs no pre-mutation JIT stop. Delete accessor and data state under
        // one receiver lock; exotic/indexed/lazy-prototype cases keep their
        // dedicated paths below.
        if (value.canonicalIndex(key) == null and
            !(o.is_array and !o.is_arguments and std.mem.eql(u8, key, "length")) and
            !isLazyFunctionPrototypeSlot(o, key) and
            (self.jit_owner == null or !self.jit_owner.?.hasPublishedArtifacts()))
            return o.deleteOrdinaryNamedOwn(self.arena, self.root_shape, key);
        // Deletion rebuilds the named-data shape or changes the accessor
        // representation. Close code guarding the exact pre-delete shape
        // before either mutation; a missing/non-configurable property performs
        // no mutation and must not manufacture a Class-A stop (#471).
        var ordinary_delete_invalidated = false;
        if ((o.getAccessor(key) != null or o.getOwn(key) != null) and o.getAttr(key).configurable) {
            self.invalidateJitHeapFactsFor(o);
            ordinary_delete_invalidated = true;
        }
        const indexed_locked = value.canonicalIndex(key) != null;
        if (indexed_locked) o.lockIndexedProperty();
        defer if (indexed_locked) o.unlockIndexedProperty();
        // Accessor property.
        switch (try o.deleteAccessorOwn(self.arena, key)) {
            .absent => {},
            .blocked => return false,
            .deleted => return true,
            .removed_continue => {},
        }
        // Dense indexed element → leave a hole (reads as absent), length unchanged.
        // A per-index descriptor may mark it non-configurable (delete fails).
        if (o.is_array and std.mem.eql(u8, key, "length")) {
            // A real Array's `length` is non-configurable (not deletable); an
            // arguments object's is an ordinary own property → delete it,
            // honoring [[Configurable]].
            if (!o.is_arguments) return false;
            return o.deleteNamedDataOwn(self.arena, self.root_shape, key);
        }
        if (arrayElementIndex(key)) |i| {
            if (o.getOwn(key) == null and o.denseElementInBounds(i)) {
                if (o.attrsMap() != null and !o.getAttr(key).configurable) return false;
                // Deleting a mapped arguments index severs its parameter link.
                if (o.is_arguments) argMapSever(o, i);
                _ = try o.deleteDenseElement(self.arena, i);
                return true;
            }
        }
        if (std.mem.eql(u8, key, "prototype") and o.jsFunction() != null and o.getOwn("prototype") == null and o.getAccessor("prototype") == null)
            _ = try self.getProperty(Value.obj(o), key);
        // A function's lazy own `prototype` may have materialized after the
        // initial ordinary-property probe above.
        if (!ordinary_delete_invalidated and o.getOwn(key) != null and o.getAttr(key).configurable)
            self.invalidateJitHeapFactsFor(o);
        return try o.deleteNamedDataOwn(self.arena, self.root_shape, key);
    }

    /// Define an accessor (get/set) on an object via its `setAccessor`.
    fn defineAccessor(self: *Interpreter, obj: *value.Object, name: []const u8, get: ?Value, set: ?Value) EvalError!void {
        if (obj.getOwn(name) != null) {
            if (!try obj.deleteNamedDataOwnPreserveOrder(self.arena, self.root_shape, name))
                return self.throwError("TypeError", "Cannot redefine non-configurable data property");
        }
        try obj.setAccessor(self.arena, name, get, set);
    }

    const AutoAccessorData = struct { storage_key: []const u8 };

    fn autoAccessorGetFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
        _ = args;
        const self: *Interpreter = @ptrCast(@alignCast(ctx));
        const fnobj = self.active_native orelse return Value.undef();
        const data: *AutoAccessorData = @ptrCast(@alignCast(fnobj.private_data.?));
        return self.privateGet(this, data.storage_key);
    }

    fn autoAccessorSetFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
        const self: *Interpreter = @ptrCast(@alignCast(ctx));
        const fnobj = self.active_native orelse return Value.undef();
        const data: *AutoAccessorData = @ptrCast(@alignCast(fnobj.private_data.?));
        try self.privateSet(this, data.storage_key, if (args.len > 0) args[0] else Value.undef());
        return Value.undef();
    }

    fn defineAutoAccessor(self: *Interpreter, obj: *value.Object, name: []const u8, storage_key: []const u8, display: []const u8) EvalError!void {
        const data = try self.arena.create(AutoAccessorData);
        data.* = .{ .storage_key = storage_key };

        const getter = try gc_mod.allocObj(self.arena);
        getter.* = .{ .native = autoAccessorGetFn, .private_data = @ptrCast(data) };
        try installNativeProps(self.arena, self.root_shape, getter, try std.fmt.allocPrint(self.arena, "get {s}", .{display}), 0);

        const setter = try gc_mod.allocObj(self.arena);
        setter.* = .{ .native = autoAccessorSetFn, .private_data = @ptrCast(data) };
        try installNativeProps(self.arena, self.root_shape, setter, try std.fmt.allocPrint(self.arena, "set {s}", .{display}), 1);

        try obj.setAccessor(self.arena, name, Value.obj(getter), Value.obj(setter));
    }

    /// Call `recv[name](args)` with `this = recv`. Dispatches the builtin
    /// methods that aren't stored as own properties first. Shared by the
    /// tree-walker's `evalCall` and the VM's `call_method`.
    pub fn callMethod(self: *Interpreter, recv: Value, name: []const u8, args: []const Value) EvalError!Value {
        // A real (possibly user-reassigned) method property found on the receiver
        // or its prototype chain takes precedence over the engine's native
        // fast-path, so an override like `Date.prototype.toString =
        // Object.prototype.toString` is honored. The brand fast-paths
        // (dateMethod / arrayMethod / mapMethod / …) remain the implementation of
        // the unshadowed intrinsics and the fallback for method names that aren't
        // installed as real own properties (synthesized push/getDay/etc.).
        const method = try self.getProperty(recv, name);
        return self.callResolvedMethod(recv, name, method, args);
    }

    fn callResolvedMethod(self: *Interpreter, recv: Value, name: []const u8, method: Value, args: []const Value) EvalError!Value {
        if (method.isObject() and method.asObj().isCallableObject())
            return self.callValueWithThis(method, args, recv);
        if (try self.builtinMethod(recv, name, args)) |result| return result;
        return self.callValueWithThis(method, args, recv);
    }

    pub const IteratorRecord = struct {
        iterator: Value,
        next_method: Value,
    };

    /// The object-acquisition half of synchronous GetIterator: read and call the
    /// observable @@iterator method and require its result to be an Object. VM
    /// bytecode uses this boundary because compiled sites capture `next` in their
    /// own activation immediately afterward.
    pub fn getIterator(self: *Interpreter, v: Value) EvalError!Value {
        // GetIterator(v) begins with GetMethod(v, @@iterator), i.e. a property
        // read on `v` — so a nullish `v` fails RequireObjectCoercible, not an
        // iterability check. Report it as the nullish-base error, as JSC does.
        if (v.isUndefined() or v.isNull())
            return self.throwError("TypeError", notAnObjectMessage(v));
        const key = self.symbolIteratorKey() orelse
            return self.throwError("TypeError", "value is not iterable");
        const method = try self.getProperty(v, key);
        if (!method.isCallable())
            return self.throwError("TypeError", "Symbol.iterator is not callable");
        return self.requireIteratorObject(try self.callValueWithThis(method, &.{}, v));
    }

    /// GetIterator(obj, sync): acquire the iterator object and capture its
    /// [[NextMethod]] exactly once. GetIteratorDirect/GetIteratorFlattenable
    /// consumers use their own entry points instead of this language contract.
    pub fn getIteratorRecord(self: *Interpreter, v: Value) EvalError!IteratorRecord {
        const iterator = try self.getIterator(v);
        return .{
            .iterator = iterator,
            .next_method = try self.getProperty(iterator, "next"),
        };
    }

    /// Legacy iterator-object entry point retained while its remaining callers
    /// are classified as GetIterator, GetIteratorDirect, or an internal cursor.
    /// Unlike `getIteratorRecord`, this accepts a `.next`-only object and bypasses
    /// an observable generator @@iterator; new language GetIterator consumers
    /// must not use it.
    pub fn iteratorOf(self: *Interpreter, v: Value) EvalError!Value {
        switch (v.kind()) {
            .object => {
                const o = v.asObj();
                if (o.generator() != null) return v;
                // A user-defined `[Symbol.iterator]()` method takes precedence.
                if (self.symbolIteratorKey()) |ik| {
                    const itfn = try self.getProperty(v, ik);
                    if (!itfn.isUndefined() and !itfn.isNull()) {
                        if (itfn.isObject() and itfn.asObj().isCallableObject())
                            return try self.requireIteratorObject(try self.callValueWithThis(itfn, &.{}, v));
                        return self.throwError("TypeError", "value is not iterable");
                    }
                }
                // An array honors a deleted/overridden `Array.prototype[Symbol.iterator]`.
                if (o.is_array) {
                    switch (self.arrayIterState()) {
                        .intact => return self.makeCursorIterator(v),
                        .deleted => return self.throwError("TypeError", "value is not iterable"),
                        .custom => |m| {
                            if (!m.isCallable()) return self.throwError("TypeError", "value is not iterable");
                            return try self.requireIteratorObject(try self.callValueWithThis(m, &.{}, v));
                        },
                    }
                }
                if (hasProperty(o, "next")) return v; // already an iterator (manual or generator-like)
                // Sets (element = value) and Maps (element = [k,v] pair) iterate
                // their dense `elements` store via an index cursor.
                if (o.is_set or o.is_map) return self.makeCursorIterator(v);
                return self.throwError("TypeError", "value is not iterable");
            },
            .string, .number, .boolean => {
                if (self.symbolIteratorKey()) |ik| {
                    const itfn = try self.getProperty(v, ik);
                    if (!itfn.isUndefined() and !itfn.isNull()) {
                        if (itfn.isObject() and itfn.asObj().isCallableObject())
                            return try self.requireIteratorObject(try self.callValueWithThis(itfn, &.{}, v));
                        return self.throwError("TypeError", "value is not iterable");
                    }
                    return self.throwError("TypeError", "value is not iterable");
                }
                if (v.isString()) return self.makeCursorIterator(v);
                return self.throwError("TypeError", "value is not iterable");
            },
            else => return self.throwError("TypeError", "value is not iterable"),
        }
    }

    fn requireIteratorObject(self: *Interpreter, it: Value) EvalError!Value {
        if (!it.isObject() or it.asObj().is_symbol or it.asObj().is_bigint)
            return self.throwError("TypeError", "iterator is not an object");
        return it;
    }

    /// JavaScriptCore's private `hasIteratorMethod` boundary. Unlike the
    /// language iterator path, this helper deliberately rejects primitives
    /// without boxing. Object lookup is ordinary GetMethod: accessors run,
    /// null/undefined mean absent, and a present non-callable value throws.
    pub fn hasIteratorMethod(self: *Interpreter, v: Value) EvalError!bool {
        if (!v.isObject() or v.asObj().is_symbol or v.asObj().is_bigint) return false;
        const key = self.symbolIteratorKey() orelse return false;
        const method = try self.getProperty(v, key);
        if (method.isUndefined() or method.isNull()) return false;
        if (!method.isCallable())
            return self.throwError("TypeError", "Symbol.iterator property should be callable");
        return true;
    }

    /// The internal key of the well-known `Symbol.iterator`, for resolving
    /// `obj[Symbol.iterator]`.
    fn symbolIteratorKey(self: *Interpreter) ?[]const u8 {
        return self.wellKnownSymbolKey("iterator");
    }

    fn symbolAsyncIteratorKey(self: *Interpreter) ?[]const u8 {
        return self.wellKnownSymbolKey("asyncIterator");
    }

    fn wellKnownSymbolHiddenName(name: []const u8) ?[]const u8 {
        inline for (.{ "iterator", "asyncIterator", "hasInstance", "isConcatSpreadable", "match", "matchAll", "replace", "search", "species", "split", "toPrimitive", "toStringTag", "unscopables", "dispose", "asyncDispose" }) |known| {
            if (std.mem.eql(u8, name, known)) return "\x00Symbol." ++ known;
        }
        return null;
    }

    /// The internal property key of a well-known `Symbol.<name>` (e.g. `species`).
    pub fn wellKnownSymbolKey(self: *Interpreter, name: []const u8) ?[]const u8 {
        if (wellKnownSymbolHiddenName(name)) |hidden| {
            if (self.env.get(hidden)) |intrinsic| {
                if (intrinsic.isObject() and intrinsic.asObj().is_symbol) return intrinsic.asObj().symbolKey();
            }
        }
        const sym = self.env.get("Symbol") orelse return null;
        if (!sym.isObject()) return null;
        const it = sym.asObj().getOwn(name) orelse return null;
        if (!it.isObject() or !it.asObj().is_symbol) return null;
        return it.asObj().symbolKey();
    }

    /// SpeciesConstructor(O, defaultConstructor): `O.constructor[Symbol.species]`,
    /// falling back to the default when `constructor` or its species slot is
    /// undefined/null; a non-constructor species throws a TypeError.
    pub fn speciesConstructor(self: *Interpreter, o: Value, default_ctor: Value) EvalError!Value {
        const ctor = try self.getProperty(o, "constructor");
        if (ctor.isUndefined()) return default_ctor;
        // Type(C) must be Object: Symbol/BigInt primitives are wrapped as objects
        // (is_symbol/is_bigint) in this engine, so reject them explicitly too.
        if (!ctor.isObject() or ctor.asObj().is_symbol or ctor.asObj().is_bigint)
            return self.throwError("TypeError", "constructor is not an object");
        const skey = self.wellKnownSymbolKey("species") orelse return default_ctor;
        const s = try self.getProperty(ctor, skey);
        if (s.isUndefined() or s.isNull()) return default_ctor;
        if (!isConstructorValue(s)) return self.throwError("TypeError", "Symbol.species is not a constructor");
        return s;
    }

    /// ArraySpeciesCreate(originalArray, length): the result array a method like
    /// `map`/`filter`/`slice` produces. The default is a plain Array, but
    /// `originalArray.constructor[Symbol.species]` can redirect it: a null/
    /// undefined species (or the intrinsic Array) gives a plain array, a
    /// non-constructor species throws a TypeError, and any other constructor is
    /// `new`-ed with the length (its abrupt completion propagates).
    pub fn arraySpeciesCreate(self: *Interpreter, original: Value, len: usize) EvalError!Value {
        const default_realm: *Environment = if (self.active_native) |nat| blk: {
            if (nat.private_data) |pd| break :blk @ptrCast(@alignCast(pd));
            break :blk self.env;
        } else self.env;
        if (!original.isObject() or !try objectToStringIsArray(self, original.asObj())) return self.newArrayWithLengthInRealm(default_realm, len);
        const c = try self.getProperty(original, "constructor");
        if (c.isObject() and (c.asObj().is_symbol or c.asObj().is_bigint))
            return self.throwError("TypeError", "Array species is not a constructor");
        // GetFunctionRealm cross-realm check: a `constructor` that is another
        // realm's %Array% is treated as the default — ArrayCreate, WITHOUT
        // consulting its @@species (so a cross-realm species getter is untouched).
        if (c.isObject() and c.asObj().native == builtins.arrayConstructor) {
            const cur = default_realm.get("Array");
            if (cur == null or !cur.?.isObject() or c.asObj() != cur.?.asObj()) return self.newArrayWithLengthInRealm(default_realm, len);
        }
        var ctor: Value = c;
        if (c.isObject()) {
            const skey = self.wellKnownSymbolKey("species") orelse return self.newArrayWithLengthInRealm(default_realm, len);
            const s = try self.getProperty(c, skey);
            if (s.isNull() or s.isUndefined()) return self.newArrayWithLengthInRealm(default_realm, len);
            ctor = s;
        } else if (c.isUndefined()) {
            return self.newArrayWithLengthInRealm(default_realm, len);
        }
        // The intrinsic Array constructor → a plain array (fast path, matching
        // `new Array(len)` then filling in 0..len).
        if (default_realm.get("Array")) |arr| {
            if (ctor.isObject() and arr.isObject() and ctor.asObj() == arr.asObj()) return self.newArrayWithLengthInRealm(default_realm, len);
        }
        if (!isConstructorValue(ctor)) return self.throwError("TypeError", "Array species is not a constructor");
        return self.construct(ctor, &.{Value.num(@floatFromInt(len))});
    }

    /// TypedArraySpeciesCreate(exemplar, «length»): the result a method like
    /// `map`/`filter`/`slice`/`toSorted` produces. `exemplar.constructor`'s
    /// `Symbol.species` (a real constructor, else TypeError) is `new`-ed with the
    /// length; the result must be a non-detached typed array of at least `len`
    /// elements and the same content type (BigInt vs Number) as the exemplar.
    fn typedArraySpeciesCreate(self: *Interpreter, exemplar: *value.Object, len: usize, immutable_same_buffer_ok: ?*value.Object) EvalError!*value.Object {
        const kind = exemplar.typedArray().?.kind;
        const default_ctor = self.env.get(kind.ctorName()) orelse return newTypedArray(self, kind, len);
        const ctor = try self.speciesConstructor(Value.obj(exemplar), default_ctor);
        // Fast path: the intrinsic constructor for this view kind.
        if (ctor.isObject() and default_ctor.isObject() and ctor.asObj() == default_ctor.asObj())
            return newTypedArray(self, kind, len);
        const res = try self.construct(ctor, &.{Value.num(@floatFromInt(len))});
        if (!res.isObject() or res.asObj().typedArray() == null)
            return self.throwError("TypeError", "TypedArray species did not return a TypedArray");
        const rta = res.asObj().typedArray().?;
        if (rta.kind.isBigInt() != kind.isBigInt())
            return self.throwError("TypeError", "TypedArray species content type does not match");
        // The callers write into the result, so ValidateTypedArray is normally
        // in ~write~ mode: an immutable destination buffer is a TypeError. Slice
        // has one spec-visible overlap case where the species result aliases the
        // source buffer; its byte-copy loop is allowed to perform those internal
        // writes even when the shared buffer is immutable.
        if (rta.buffer.arrayBuffer().?.immutable and (immutable_same_buffer_ok == null or rta.buffer != immutable_same_buffer_ok.?))
            return self.throwError("TypeError", "TypedArray species result is backed by an immutable buffer");
        // ValidateTypedArray + the single-Number length guard use the LIVE length:
        // a result whose (resizable) buffer is detached/out-of-bounds, or now
        // shorter than requested, is a TypeError.
        if ((rta.currentLength() orelse 0) < len)
            return self.throwError("TypeError", "TypedArray species result is too short or out of bounds");
        return res.asObj();
    }

    /// TypedArraySpeciesCreate(exemplar, «buffer, byteOffset, length?») — the
    /// form `subarray` uses: the species constructor is `new`-ed with the shared
    /// buffer and a byte range (so the result is a view, not a copy). Constructing
    /// over a detached buffer throws TypeError (ValidateTypedArray); a wrong
    /// content type or non-TypedArray result also throws.
    fn typedArraySubarrayCreate(self: *Interpreter, exemplar: *value.Object, buffer: *value.Object, byte_offset: usize, len: ?usize) EvalError!Value {
        const kind = exemplar.typedArray().?.kind;
        const default_ctor = self.env.get(kind.ctorName()) orelse return self.throwError("TypeError", "missing TypedArray constructor");
        const ctor = try self.speciesConstructor(Value.obj(exemplar), default_ctor);
        const res = if (len) |length| try self.construct(ctor, &.{
            Value.obj(buffer),
            Value.num(@floatFromInt(byte_offset)),
            Value.num(@floatFromInt(length)),
        }) else try self.construct(ctor, &.{
            Value.obj(buffer),
            Value.num(@floatFromInt(byte_offset)),
        });
        if (!res.isObject() or res.asObj().typedArray() == null)
            return self.throwError("TypeError", "TypedArray species did not return a TypedArray");
        if (res.asObj().typedArray().?.buffer.arrayBuffer().?.isDetached())
            return self.throwError("TypeError", "TypedArray species returned a detached TypedArray");
        if (res.asObj().typedArray().?.kind.isBigInt() != kind.isBigInt())
            return self.throwError("TypeError", "TypedArray species content type does not match");
        return res;
    }

    /// Create a zero-filled `ArrayBuffer` object of `len` bytes. The bytes are
    /// 8-byte aligned so every typed-array element is naturally aligned (the
    /// atomic element paths in value.zig rely on this).
    pub fn makeArrayBuffer(self: *Interpreter, len: usize) EvalError!*value.Object {
        return self.makeArrayBufferWithInitialization(len, true);
    }

    /// Create an ArrayBuffer whose backing bytes are intentionally left
    /// uninitialized. This is only for private native boundaries whose callers
    /// immediately overwrite the full view; ECMAScript constructors continue
    /// to route through `makeArrayBuffer` and remain zero-filled.
    pub fn makeUninitializedArrayBuffer(self: *Interpreter, len: usize) EvalError!*value.Object {
        return self.makeArrayBufferWithInitialization(len, false);
    }

    fn makeArrayBufferWithInitialization(self: *Interpreter, len: usize, zero_fill: bool) EvalError!*value.Object {
        const o = (try self.newObject()).asObj();
        const data = try self.allocArrayBufferBytesWithInitialization(len, zero_fill);
        errdefer self.freeArrayBufferBytes(data, self.gc_side_storage != null);
        const ab = try self.allocArrayBufferData();
        errdefer self.destroyArrayBufferData(ab);
        ab.* = .{ .local_data = data, .gc_owned = self.gc_side_storage != null };
        try o.setArrayBuffer(self.arena, ab);
        errdefer o.clearArrayBuffer();
        if (self.env.get("ArrayBuffer")) |c| {
            if (c.isObject()) o.setProtoAtomic(try self.protoObject(c.asObj()));
        }
        return o;
    }

    /// Create a fixed-length ArrayBuffer over embedder-owned bytes without
    /// copying. `owner` is context-owned and idempotently releases the backing
    /// from either the GC finalizer or arena-context teardown.
    pub fn makeExternalArrayBuffer(self: *Interpreter, bytes: []u8, owner: *value.ExternalBufferOwner) EvalError!*value.Object {
        const o = (try self.newObject()).asObj();
        const ab = try self.allocArrayBufferData();
        errdefer self.destroyArrayBufferData(ab);
        ab.* = .{
            .local_data = bytes,
            .gc_owned = self.gc_side_storage != null,
            .external_owner = owner,
        };
        try o.setArrayBuffer(self.arena, ab);
        errdefer o.clearArrayBuffer();
        if (self.env.get("ArrayBuffer")) |c| {
            if (c.isObject()) o.setProtoAtomic(try self.protoObject(c.asObj()));
        }
        return o;
    }

    /// Rebuild a Blob/File from structured-clone data (called by structured_clone).
    pub fn makeClonedBlob(self: *Interpreter, is_file: bool, bytes: []const u8, blob_type: []const u8, name: []const u8, last_mod: f64) EvalError!Value {
        const obj = try blobMake(self, if (is_file) "File" else "Blob", bytes, blob_type);
        if (is_file) {
            try obj.setOwn(self.arena, self.root_shape, "\x00filename", try Value.strAlloc(self.arena, name));
            try obj.setOwn(self.arena, self.root_shape, "\x00filemod", Value.num(last_mod));
        }
        return Value.obj(obj);
    }

    pub fn makeImmutableUint8ArrayFromBytes(self: *Interpreter, bytes: []const u8) EvalError!*value.Object {
        const o = try newTypedArray(self, .u8, bytes.len);
        const ab = o.typedArray().?.buffer.arrayBuffer().?;
        if (bytes.len > 0) @memcpy(ab.bytes()[0..bytes.len], bytes);
        ab.immutable = true;
        return o;
    }

    pub fn makeUninitializedTypedArray(self: *Interpreter, kind: value.TAKind, len: usize) EvalError!*value.Object {
        return newTypedArrayWithInitialization(self, kind, len, false);
    }

    fn allocArrayBufferBytes(self: *Interpreter, len: usize) EvalError![]u8 {
        return self.allocArrayBufferBytesWithInitialization(len, true);
    }

    fn allocArrayBufferBytesWithInitialization(self: *Interpreter, len: usize, zero_fill: bool) EvalError![]u8 {
        if (len == 0) return &.{};
        const data = if (self.gc_side_storage) |a| blk: {
            const p = a.rawAlloc(len, .@"8", @returnAddress()) orelse retry: {
                if (self.gc_checkpoint_ctx) |ctx| {
                    if (self.gc_recover_allocation_fn) |recover| {
                        if (recover(ctx)) {
                            break :retry a.rawAlloc(len, .@"8", @returnAddress()) orelse return error.OutOfMemory;
                        }
                    }
                }
                return error.OutOfMemory;
            };
            if (self.gc_array_buffer_bytes_live) |live| _ = @atomicRmw(usize, live, .Add, len, .monotonic);
            break :blk p[0..len];
        } else try self.arena.alignedAlloc(u8, .@"8", len);
        if (zero_fill) @memset(data, 0);
        return data;
    }

    fn freeArrayBufferBytes(self: *Interpreter, bytes: []u8, gc_owned: bool) void {
        if (!gc_owned or bytes.len == 0) return;
        const a = self.gc_side_storage orelse return;
        a.rawFree(bytes, .@"8", @returnAddress());
        if (self.gc_array_buffer_bytes_live) |live| {
            _ = @atomicRmw(usize, live, .Sub, bytes.len, .monotonic);
        }
    }

    fn allocArrayBufferData(self: *Interpreter) EvalError!*value.ArrayBufferData {
        if (self.gc_side_storage) |a| return a.create(value.ArrayBufferData);
        return self.arena.create(value.ArrayBufferData);
    }

    fn destroyArrayBufferData(self: *Interpreter, ab: *value.ArrayBufferData) void {
        if (!ab.gc_owned) return;
        const a = self.gc_side_storage orelse return;
        a.destroy(ab);
    }

    fn typedArrayLengthLimit(size: usize) usize {
        return @min(std.math.maxInt(usize) / size, max_typed_array_bytes / size);
    }

    fn initTypedArrayProto(self: *Interpreter, o: *value.Object, kind: value.TAKind) EvalError!void {
        // GetPrototypeFromConstructor(newTarget, %TAPrototype%): newTarget.prototype
        // (a getter runs and may throw), or — when that is not an Object — the
        // *newTarget's realm's* typed-array prototype for this kind.
        if (self.new_target.isObject()) {
            o.setProtoAtomic(try self.ctorRealmIntrinsicProto(self.new_target.asObj(), kind.ctorName()));
        } else if (self.env.get(kind.ctorName())) |c| {
            if (c.isObject()) {
                o.setProtoAtomic(try self.protoObject(c.asObj()));
            }
        }
    }

    /// Construct a typed array of `kind` from the constructor arguments: a
    /// length, an `(buffer, byteOffset?, length?)` view, or a copy of a typed
    /// array / array-like / iterable.
    pub fn makeTypedArray(self: *Interpreter, kind: value.TAKind, args: []const Value) EvalError!Value {
        const size = kind.byteSize();
        const a0 = if (args.len > 0) args[0] else Value.undef();
        const o = (try self.newObject()).asObj();
        const ta = try (try o.typedArrayAllocator(self.arena)).create(value.TypedArrayData);
        var ta_installed = false;
        errdefer if (!ta_installed) o.destroyUninstalledTypedArray(self.arena, ta);

        if (a0.isObject() and a0.asObj().arrayBuffer() != null) {
            // AllocateTypedArray runs before byteOffset/length coercion, so a
            // throwing newTarget.prototype getter wins over poisoned arguments.
            try self.initTypedArrayProto(o, kind);
            // new TA(buffer, byteOffset?, length?). byteOffset/length are ToIndex
            // (a negative or non-integer-huge value is a RangeError), the offset
            // alignment is checked before the length coerces, and the buffer is
            // re-checked for detachment AFTER both coercions run user code.
            const buffer = a0.asObj();
            const byte_offset: usize = @intCast(if (args.len > 1) try toIndexArg(self, args[1]) else 0);
            if (byte_offset % size != 0) return self.throwError("RangeError", "invalid typed array offset");
            const has_len = args.len > 2 and !args[2].isUndefined();
            const req_len: usize = if (has_len) @intCast(try toIndexArg(self, args[2])) else 0;
            // Snapshot detached + byte length under the buffer lock: a peer's
            // ArrayBuffer.resize swaps `local_data` concurrently (no-GIL), which
            // this read of `bytes()` would otherwise race. The earlier
            // byteOffset/length coercions run user code, so they stay outside.
            const abuf = buffer.arrayBuffer().?;
            abuf.lockBuffer();
            const ab_detached = abuf.isDetached();
            const buflen = if (ab_detached) 0 else abuf.bytes().len;
            abuf.unlockBuffer();
            if (ab_detached) return self.throwError("TypeError", "Cannot construct a TypedArray on a detached buffer");
            if (byte_offset > buflen) return self.throwError("RangeError", "invalid typed array offset");
            var length: usize = undefined;
            // Omitting the length on a resizable buffer makes the view
            // length-tracking; on a fixed buffer it spans the remaining bytes.
            const track = !has_len and buffer.arrayBuffer().?.max_byte_length != null;
            if (has_len) {
                length = req_len;
            } else {
                // A length-tracking view over a resizable buffer just tracks
                // floor(available / elementSize); only a fixed-length view
                // requires the byte length to be an exact multiple.
                if (!track and (buflen - byte_offset) % size != 0) return self.throwError("RangeError", "byte length not a multiple of element size");
                length = (buflen - byte_offset) / size;
            }
            if (byte_offset + length * size > buflen) return self.throwError("RangeError", "invalid typed array length");
            ta.* = .{ .buffer = buffer, .byte_offset = byte_offset, .length = length, .kind = kind, .track_length = track };
            try o.setTypedArray(self.arena, ta);
            ta_installed = true;
            return Value.obj(o);
        }
        if (a0.isObject() and a0.asObj().typedArray() != null) {
            // new TA(typedArray): copy elements (converting numeric types). A
            // BigInt and a non-BigInt element type can't be mixed.
            const src = a0.asObj().typedArray().?;
            if (src.kind.isBigInt() != kind.isBigInt()) return self.throwError("TypeError", "Cannot mix BigInt and other types when constructing a TypedArray");
            const length = src.currentLength() orelse return self.throwError("TypeError", "Cannot construct from an out-of-bounds TypedArray");
            try self.initTypedArrayProto(o, kind);
            ta.* = .{ .buffer = try self.makeArrayBuffer(length * size), .byte_offset = 0, .length = length, .kind = kind };
            try o.setTypedArray(self.arena, ta);
            ta_installed = true;
            var i: usize = 0;
            while (i < length) : (i += 1) {
                if (kind.isBigInt()) value.taWriteBig(ta, i, value.taReadBig(src, i)) else value.taWrite(ta, i, value.taRead(src, i).asNum());
            }
            return Value.obj(o);
        }
        if (a0.isObject() and !a0.asObj().is_symbol and !a0.asObj().is_bigint) {
            // new TA(arrayLike | iterable): collect the values, then coerce + copy
            // (ToBigInt for a BigInt view, ToNumber otherwise). The iterable path
            // is taken only when GetMethod(@@iterator) yields a callable — a null
            // or undefined @@iterator falls back to the array-like length path.
            const ik = self.symbolIteratorKey();
            const itm = if (ik) |k| try self.getProperty(a0, k) else Value.undef();
            const use_iter = !itm.isUndefined() and !itm.isNull();
            if (use_iter and !itm.isCallable()) return self.throwError("TypeError", "@@iterator is not a function");
            const list = if (use_iter) try self.iterableToListFromMethod(a0, itm) else blk: {
                const len = toLen(try self.toNumberV(try self.getProperty(a0, "length")));
                if (len > typedArrayLengthLimit(size)) return self.throwError("RangeError", "invalid typed array length");
                break :blk try self.arrayLikeToListLen(a0, len);
            };
            if (list.len > typedArrayLengthLimit(size)) return self.throwError("RangeError", "invalid typed array length");
            try self.initTypedArrayProto(o, kind);
            ta.* = .{ .buffer = try self.makeArrayBuffer(list.len * size), .byte_offset = 0, .length = list.len, .kind = kind };
            try o.setTypedArray(self.arena, ta);
            ta_installed = true;
            var i: usize = 0;
            while (i < list.len) : (i += 1) try self.taStore(ta, i, list[i]);
            return Value.obj(o);
        }
        // new TA(length): ToIndex(length) — truncates (0.9→0, 1.9→1), a Symbol or
        // BigInt throws (ToNumber), a negative or >2^53-1 value is a RangeError.
        const len_idx = try toIndexArg(self, a0);
        if (len_idx > typedArrayLengthLimit(size)) return self.throwError("RangeError", "invalid typed array length");
        const length: usize = @intCast(len_idx);
        try self.initTypedArrayProto(o, kind);
        ta.* = .{ .buffer = try self.makeArrayBuffer(length * size), .byte_offset = 0, .length = length, .kind = kind };
        try o.setTypedArray(self.arena, ta);
        ta_installed = true;
        return Value.obj(o);
    }

    /// Store `v` into typed-array element `i`, coercing per the element type:
    /// ToBigInt for a BigInt view (rejecting a Number), ToNumber otherwise.
    fn taStoreInternal(self: *Interpreter, ta: *value.TypedArrayData, i: usize, v: Value, allow_immutable: bool) EvalError!void {
        if (ta.kind.isBigInt()) {
            const bv = try self.toBigIntValueImpl(v, false);
            // TypedArraySetElement coerces first, then skips the store for an
            // invalid/out-of-bounds index or immutable buffer (a silent no-op,
            // not a throw).
            if (i >= (ta.currentLength() orelse 0) or (ta.buffer.arrayBuffer().?.immutable and !allow_immutable)) return;
            value.taWriteBig(ta, i, bv.asObj().bigIntValue());
        } else {
            const num = try self.toNumberV(v);
            if (i >= (ta.currentLength() orelse 0) or (ta.buffer.arrayBuffer().?.immutable and !allow_immutable)) return;
            value.taWrite(ta, i, num);
        }
    }

    fn taStore(self: *Interpreter, ta: *value.TypedArrayData, i: usize, v: Value) EvalError!void {
        return self.taStoreInternal(ta, i, v, false);
    }

    /// Read typed-array element `i` as a Value (a BigInt for a BigInt view, a
    /// Number otherwise).
    pub fn taLoad(self: *Interpreter, ta: *const value.TypedArrayData, i: usize) EvalError!Value {
        if (ta.kind.isBigInt()) return self.makeBigInt(value.taReadBig(ta, i));
        return value.taRead(ta, i);
    }

    /// `taLoad` but yielding `undefined` for an index at/past the current length
    /// (a resizable buffer shrank, or detached, mid-iteration) — matching `[[Get]]`
    /// on the integer-indexed exotic, which the iteration methods read through.
    fn taLoadIdx(self: *Interpreter, ta: *const value.TypedArrayData, i: usize) EvalError!Value {
        if (i >= (ta.currentLength() orelse 0)) return Value.undef();
        return self.taLoad(ta, i);
    }

    /// Copy same-kind TypedArray slice bytes directly. This preserves floating
    /// NaN payload bits, unlike the numeric read/write path used for conversions.
    fn taSliceRawCopy(self: *Interpreter, src: *const value.TypedArrayData, dst: *value.TypedArrayData, start: usize, count: usize) EvalError!void {
        _ = self;
        if (count == 0) return;
        const esz = src.kind.byteSize();
        const src_ab = src.buffer.arrayBuffer().?;
        const dst_ab = dst.buffer.arrayBuffer().?;
        const lock_src = src_ab.needsElementLock();
        const lock_dst = dst_ab.needsElementLock() and dst_ab != src_ab;
        if (lock_src and lock_dst) {
            if (@intFromPtr(src_ab) < @intFromPtr(dst_ab)) {
                src_ab.lockBuffer();
                dst_ab.lockBuffer();
            } else {
                dst_ab.lockBuffer();
                src_ab.lockBuffer();
            }
        } else {
            if (lock_src) src_ab.lockBuffer();
            if (lock_dst) dst_ab.lockBuffer();
        }
        defer {
            if (lock_dst) dst_ab.unlockBuffer();
            if (lock_src) src_ab.unlockBuffer();
        }

        const src_bytes = src_ab.bytes();
        const dst_bytes = dst_ab.bytes();
        const src_off = src.byte_offset + start * esz;
        const dst_off = dst.byte_offset;
        const src_avail = if (src_off < src_bytes.len) (src_bytes.len - src_off) / esz else 0;
        const dst_avail = if (dst_off < dst_bytes.len) (dst_bytes.len - dst_off) / esz else 0;
        const n = @min(count, @min(src_avail, dst_avail)) * esz;
        if (n == 0) return;
        value.copyArrayBufferBytes(dst_ab, dst_bytes, dst_off, src_ab, src_bytes, src_off, n);
    }

    /// TypedArray construction's iterable branch. `method` is the exact
    /// GetMethod(@@iterator) result already read by the constructor; calling it
    /// here avoids a second observable property lookup before capturing `next`.
    fn iterableToListFromMethod(self: *Interpreter, v: Value, method: Value) EvalError![]Value {
        var out: std.ArrayListUnmanaged(Value) = .empty;
        const iterator = try self.requireIteratorObject(try self.callValueWithThis(method, &.{}, v));
        const iter_root = try self.pushTempRoot(iterator);
        defer self.restoreTempRoots(iter_root);
        const next_method = try self.getProperty(iterator, "next");
        const next_root = try self.pushTempRoot(next_method);
        defer self.restoreTempRoots(next_root);
        while (true) {
            const result = try self.callValueWithThis(next_method, &.{}, iterator);
            if (!builtins.isRealObject(result)) return self.throwError("TypeError", "iterator result is not an object");
            if ((try self.getProperty(result, "done")).toBoolean()) break;
            try out.append(self.arena, try self.getProperty(result, "value"));
        }
        return out.items;
    }

    /// GetIteratorFlattenable(obj, reject-primitives) per the joint-iteration
    /// proposal: `obj` must be an Object (strings and other primitives throw).
    /// Reads `@@iterator` (GetMethod); if absent uses `obj` itself, else calls
    /// it. The resulting iterator must be an Object; its `next` is captured in
    /// the returned GetIteratorDirect record.
    pub fn getIteratorFlattenableRecord(self: *Interpreter, obj: Value) EvalError!IteratorRecord {
        if (!obj.isObject() or obj.asObj().is_bigint or obj.asObj().is_symbol)
            return self.throwError("TypeError", "value is not an iterable object");
        var iterator: Value = obj;
        if (self.symbolIteratorKey()) |ik| {
            const method = try self.getProperty(obj, ik);
            if (!method.isUndefined() and !method.isNull()) {
                if (!method.isObject() or !method.asObj().isCallableObject())
                    return self.throwError("TypeError", "Symbol.iterator is not callable");
                iterator = try self.callValueWithThis(method, &.{}, obj);
            }
        }
        if (!iterator.isObject()) return self.throwError("TypeError", "iterator is not an object");
        return .{
            .iterator = iterator,
            .next_method = try self.getProperty(iterator, "next"),
        };
    }

    fn arrayLikeToListLen(self: *Interpreter, v: Value, len: usize) EvalError![]Value {
        var out: std.ArrayListUnmanaged(Value) = .empty;
        var i: usize = 0;
        while (i < len) : (i += 1) {
            var kb: [24]u8 = undefined;
            const k = std.fmt.bufPrint(&kb, "{d}", .{i}) catch unreachable;
            try out.append(self.arena, try self.getProperty(v, k));
        }
        return out.items;
    }

    /// Append `v` as the next element of a method's result (an array uses its
    /// dense store; a custom species object gets a `[[Set]]` at `idx`).
    fn arrayResultPush(self: *Interpreter, result: Value, idx: usize, v: Value) EvalError!void {
        if (result.isObject() and result.asObj().is_array and result.asObj().accessorsMap() == null and
            result.asObj().attrsMap() == null and !result.asObj().proxy_revoked and result.asObj().proxyHandler() == null and
            result.asObj().isExtensible() and
            try result.asObj().appendElementIfLen(self.arena, idx, v))
        {
            return;
        } else {
            // CreateDataPropertyOrThrow(result, ToString(idx), v) — a non-Array
            // species result (or one carrying accessors) takes the generic define
            // path, which throws if the index is non-writable / non-extensible.
            var key_storage: [32]u8 = undefined;
            const k = borrowedIndexKey(&key_storage, idx);
            const desc = (try self.newObject()).asObj();
            try desc.setOwn(self.arena, self.root_shape, "value", v);
            try desc.setOwn(self.arena, self.root_shape, "writable", Value.boolVal(true));
            try desc.setOwn(self.arena, self.root_shape, "enumerable", Value.boolVal(true));
            try desc.setOwn(self.arena, self.root_shape, "configurable", Value.boolVal(true));
            if (!result.isObject() or !try builtins.defineOneResult(self, result.asObj(), k, desc))
                return self.throwError("TypeError", "Cannot create array result property");
        }
    }

    fn makeAsyncFromSyncIterator(self: *Interpreter, sync_iter: Value) EvalError!Value {
        const it = (try self.newObject()).asObj();
        try self.setProp(it, "__sync", sync_iter);
        try self.setProp(it, "__next", try self.getProperty(sync_iter, "next"));
        try setNative(self.arena, self.root_shape, it, "next", 1, asyncFromSyncNextFn);
        try setNative(self.arena, self.root_shape, it, "return", 1, asyncFromSyncReturnFn);
        try setNative(self.arena, self.root_shape, it, "throw", 1, asyncFromSyncThrowFn);
        return Value.obj(it);
    }

    /// The async iterator for `for await`: `obj[Symbol.asyncIterator]()` if
    /// present, else an Async-from-Sync wrapper over `obj[Symbol.iterator]()`.
    pub fn asyncIteratorOf(self: *Interpreter, v: Value) EvalError!Value {
        if (self.symbolAsyncIteratorKey()) |ik| {
            if (v.isObject() and hasProperty(v.asObj(), ik)) {
                const m = try self.getProperty(v, ik);
                // GetMethod: undefined/null → method absent (fall back to sync);
                // present but not callable → TypeError.
                if (!m.isUndefined() and !m.isNull()) {
                    if (m.isObject() and m.asObj().isCallableObject())
                        return try self.callValueWithThis(m, &.{}, v);
                    return self.throwError("TypeError", "[Symbol.asyncIterator] is not a function");
                }
            }
        }
        return self.makeAsyncFromSyncIterator(try self.iteratorOf(v));
    }

    /// Wrap an array/string/collection in an iterator object. Map/Set use true
    /// internal slots and a logical insertion cursor; the generic array/string
    /// path retains its existing indexed cursor.
    fn makeCursorIterator(self: *Interpreter, src: Value) EvalError!Value {
        return self.makeCursorIteratorWithKind(src, 0);
    }

    fn makeCursorIteratorWithKind(self: *Interpreter, src: Value, kind: u8) EvalError!Value {
        const it = try gc_mod.allocObj(self.arena);
        it.* = .{};
        const is_strong_collection = src.isObject() and
            (src.asObj().is_map or src.asObj().is_set) and !src.asObj().is_weak;
        if (is_strong_collection) {
            try it.initCollectionIterator(self.arena, src, kind);
        } else {
            try self.setProp(it, "__src", src);
            try self.setProp(it, "__i", Value.num(0));
            try self.setProp(it, "__kind", Value.num(@floatFromInt(kind)));
        }
        // Inherit the per-kind built-in iterator prototype (%ArrayIteratorPrototype%
        // etc.) — which carries `next`, the @@toStringTag, and (via
        // %IteratorPrototype%) the iterator-helper methods.
        const proto_key: []const u8 = switch (src.kind()) {
            .string => "\x00StrIterProto",
            .object => if (src.asObj().is_map) "\x00MapIterProto" else if (src.asObj().is_set) "\x00SetIterProto" else "\x00ArrIterProto",
            else => "\x00ArrIterProto",
        };
        if (self.env.get(proto_key)) |p| {
            if (p.isObject()) it.setProtoAtomic(p.asObj());
        } else {
            // Before %IteratorPrototype% exists (early bootstrap): a plain `next`.
            try setNative(self.arena, self.root_shape, it, "next", 0, cursorIterNext);
        }
        return Value.obj(it);
    }

    /// A fresh `{ value, done }` IteratorResult object.
    pub fn iterResultObj(self: *Interpreter, val: Value, done: bool) EvalError!Value {
        const o = (try self.newObject()).asObj();
        try self.setProp(o, "value", val);
        try self.setProp(o, "done", Value.boolVal(done));
        return Value.obj(o);
    }

    /// The `{ read, written }` record returned by Uint8Array.prototype.setFrom*.
    fn readWrittenResult(self: *Interpreter, read: usize, written: usize) EvalError!Value {
        const o = (try self.newObject()).asObj();
        try self.setProp(o, "read", Value.num(@floatFromInt(read)));
        try self.setProp(o, "written", Value.num(@floatFromInt(written)));
        return Value.obj(o);
    }

    /// Pull the next result from iterator `it`, returning `{ done, value }`.
    const IterStepResult = struct { done: bool, value: Value };

    /// Pull one step from a GetIteratorDirect record. Call the captured
    /// `next_method` exactly as recorded: if it is non-callable, Call throws
    /// without re-reading `it.next` or observing a later replacement.
    fn iterStepM(self: *Interpreter, it: Value, next_method: Value) EvalError!IterStepResult {
        const r = try self.callValueWithThis(next_method, &.{}, it);
        if (!builtins.isRealObject(r)) return self.throwError("TypeError", "iterator result is not an object");
        const done = (try self.getProperty(r, "done")).toBoolean();
        const val = if (done) Value.undef() else try self.getProperty(r, "value");
        return .{ .done = done, .value = val };
    }

    /// IteratorStep: pull one step and report only whether the iterator is done
    /// (the `value` is not read). Used by `Iterator.zip` strict-mode checking.
    fn iterStepDoneOnlyM(self: *Interpreter, it: Value, next_method: Value) EvalError!bool {
        const r = try self.callValueWithThis(next_method, &.{}, it);
        if (!builtins.isRealObject(r)) return self.throwError("TypeError", "iterator result is not an object");
        return (try self.getProperty(r, "done")).toBoolean();
    }

    /// `Array.prototype` (the global), for consulting/observing its
    /// `[Symbol.iterator]` slot. Arrays don't carry a `proto` pointer, so this
    /// resolves it through the `Array` global instead.
    fn arrayProtoObj(self: *Interpreter) ?*value.Object {
        const av = self.env.get("Array") orelse return null;
        if (!av.isObject()) return null;
        const p = av.asObj().getOwn("prototype") orelse return null;
        return if (p.isObject()) p.asObj() else null;
    }

    /// The current `Array.prototype[Symbol.iterator]` slot: `.intact` (still the
    /// native array-values iterator → fast index cursor is valid), `.deleted`
    /// (no iterator → not iterable), or `.custom` (a user replacement to call).
    const ArrayIter = union(enum) { intact, deleted, custom: Value };
    fn arrayIterState(self: *Interpreter) ArrayIter {
        const ap = self.arrayProtoObj() orelse return .intact;
        const ik = self.symbolIteratorKey() orelse return .intact;
        const slot = ap.getOwn(ik) orelse return .deleted;
        if (slot.isObject() and slot.asObj().native == arrayValuesIterFn) return .intact;
        return .{ .custom = slot };
    }

    /// Whether `Array.prototype[Symbol.iterator]` is still the native iterator,
    /// so the array index fast paths are valid.
    fn arrayIterIntact(self: *Interpreter) bool {
        return switch (self.arrayIterState()) {
            .intact => true,
            else => false,
        };
    }

    /// Does array `o` carry its OWN `[Symbol.iterator]` (data or accessor),
    /// overriding `Array.prototype`'s? Internal collection snapshots must defer
    /// to the iterator protocol when so.
    fn arrayHasOwnIterator(self: *Interpreter, o: *value.Object) bool {
        const ikey = self.wellKnownSymbolKey("iterator") orelse return false;
        return o.getOwn(ikey) != null or o.getAccessor(ikey) != null;
    }

    fn objectProtoHasOwn(self: *Interpreter, o: *value.Object, key: []const u8) EvalError!bool {
        if (moduleNsOf(o)) |ns| {
            try triggerDeferIfString(self, ns, key);
            return !(try moduleNsDesc(self, o, key)).isUndefined();
        }
        if (o.proxyHandler() != null or o.proxy_revoked) {
            const desc = try builtins.objectGetOwnPropertyDescriptor(@ptrCast(self), Value.undef(), &.{ Value.obj(o), try self.keyToValue(key) });
            return !desc.isUndefined();
        }
        if (objectHasOwn(o, key)) return true;
        if (o.hostClassHooks()) |hooks| if (hooks.has) |has| {
            self.recordExecutionTier(.host_callbacks);
            return try has(@ptrCast(self), o, key);
        };
        return false;
    }

    pub fn hasOwnPropertyResult(self: *Interpreter, o: *value.Object, key: []const u8) EvalError!bool {
        return self.objectProtoHasOwn(o, key);
    }

    fn objectProtoPropertyIsEnumerable(self: *Interpreter, o: *value.Object, key: []const u8) EvalError!bool {
        if (moduleNsOf(o)) |ns| {
            try triggerDeferIfString(self, ns, key);
            _ = try moduleNsDesc(self, o, key);
            return moduleNsEnumerable(o, key);
        }
        if (o.proxyHandler() != null or o.proxy_revoked) {
            const desc = try builtins.objectGetOwnPropertyDescriptor(@ptrCast(self), Value.undef(), &.{ Value.obj(o), try self.keyToValue(key) });
            if (!desc.isObject()) return false;
            if (desc.asObj().getOwn("enumerable")) |enumerable| return enumerable.toBoolean();
            return false;
        }
        if (isLazyFunctionPrototypeSlot(o, key)) return false;
        if (o.boxedPrimitive()) |p| {
            if (p.isString() and std.mem.eql(u8, key, "length")) return false;
        }
        if (!objectHasOwn(o, key)) if (o.hostClassHooks()) |hooks| if (hooks.has) |has| {
            self.recordExecutionTier(.host_callbacks);
            _ = try has(@ptrCast(self), o, key);
        };
        return objectHasOwn(o, key) and o.getAttr(key).enumerable and
            !(o.is_array and std.mem.eql(u8, key, "length"));
    }

    pub fn propertyIsEnumerableResult(self: *Interpreter, o: *value.Object, key: []const u8) EvalError!bool {
        return self.objectProtoPropertyIsEnumerable(o, key);
    }

    pub fn enumerableOwnPropertyResult(self: *Interpreter, o: *value.Object, key: []const u8) EvalError!bool {
        if (objectHasOwn(o, key)) return o.getAttr(key).enumerable and
            !(o.is_array and std.mem.eql(u8, key, "length"));
        if (o.hostClassHooks()) |hooks| if (hooks.attributes) |attributes| {
            self.recordExecutionTier(.host_callbacks);
            return if (try attributes(@ptrCast(self), o, key)) |attr| attr.enumerable else false;
        };
        return false;
    }

    /// Dispatch `Array.prototype` / `String.prototype` methods (which aren't
    /// stored as own properties). Returns null when `name` isn't a recognized
    /// builtin for `recv`, so the caller falls back to a property lookup + call.
    pub fn objectPrototypeMethod(self: *Interpreter, recv: Value, name: []const u8, args: []const Value) EvalError!?Value {
        if (eq(name, "hasOwnProperty")) {
            const k = if (args.len > 0) try self.keyOf(args[0]) else "undefined";
            const o = try self.toObject(recv);
            return Value.boolVal(try self.objectProtoHasOwn(o, k));
        }
        if (eq(name, "propertyIsEnumerable")) {
            const k = if (args.len > 0) try self.keyOf(args[0]) else "undefined";
            const o = try self.toObject(recv);
            return Value.boolVal(try self.objectProtoPropertyIsEnumerable(o, k));
        }
        if (eq(name, "isPrototypeOf")) {
            if (!(args.len > 0 and args[0].isObject() and !args[0].asObj().is_symbol and !args[0].asObj().is_bigint)) return Value.boolVal(false);
            const o = try self.toObject(recv);
            var cur: Value = args[0];
            while (cur.isObject()) {
                const next = if (cur.asObj().proxyHandler() != null or cur.asObj().proxy_revoked)
                    try self.proxyGetProto(cur.asObj())
                else if (cur.asObj().proto) |p| Value.obj(p) else Value.nul();
                if (!next.isObject()) return Value.boolVal(false);
                if (next.asObj() == o) return Value.boolVal(true);
                cur = next;
            }
            return Value.boolVal(false);
        }
        const o = try self.toObject(recv);
        if (eq(name, "valueOf")) return Value.obj(o);
        if (eq(name, "__defineGetter__") or eq(name, "__defineSetter__")) {
            const f = arg(args, 1);
            if (!f.isCallable()) return self.throwError("TypeError", "Object.prototype.__define[GS]etter__: Expecting function");
            const key = try self.keyOf(arg0(args));
            const desc = (try self.newObject()).asObj();
            try desc.setOwn(self.arena, self.root_shape, if (eq(name, "__defineGetter__")) "get" else "set", f);
            try desc.setOwn(self.arena, self.root_shape, "enumerable", Value.boolVal(true));
            try desc.setOwn(self.arena, self.root_shape, "configurable", Value.boolVal(true));
            try builtins.defineOne(self, o, key, desc);
            return Value.undef();
        }
        if (eq(name, "__lookupGetter__") or eq(name, "__lookupSetter__")) {
            const key = try self.keyOf(arg0(args));
            const key_v = try self.keyToValue(key);
            const want_get = eq(name, "__lookupGetter__");
            var cur: Value = recv;
            while (cur.isObject()) {
                const desc = try builtins.objectGetOwnPropertyDescriptor(@ptrCast(self), Value.undef(), &.{ cur, key_v });
                if (desc.isObject()) {
                    const d = desc.asObj();
                    if (d.getOwn("get") != null or d.getOwn("set") != null)
                        return (if (want_get) d.getOwn("get") else d.getOwn("set")) orelse Value.undef();
                    return Value.undef();
                }
                const c = cur.asObj();
                cur = if (c.proxyHandler() != null or c.proxy_revoked)
                    try self.proxyGetProto(c)
                else if (c.protoAtomic()) |p| Value.obj(p) else Value.nul();
            }
            return Value.undef();
        }
        return null;
    }

    pub fn builtinMethod(self: *Interpreter, recv: Value, name: []const u8, args: []const Value) EvalError!?Value {
        switch (recv.kind()) {
            .object => {
                const o = recv.asObj();
                if (o.generator() != null) {
                    const sent: Value = if (args.len > 0) args[0] else Value.undef();
                    if (eq(name, "next")) return try vm.genNext(self, o, sent);
                    if (eq(name, "return")) return try vm.genReturn(self, o, sent);
                    if (eq(name, "throw")) return try vm.genThrow(self, o, sent);
                }
                // Universal prototype methods (Function.prototype +
                // Object.prototype), checked before the array/regex/map/set
                // builtins so they reach every object kind. Own properties of
                // the same name shadow them.
                if (o.getOwn(name) == null) {
                    if (o.isCallableObject()) {
                        if (eq(name, "call")) {
                            const t: Value = if (args.len > 0) args[0] else Value.undef();
                            return try self.callValueWithThis(recv, if (args.len > 1) args[1..] else &.{}, t);
                        }
                        if (eq(name, "apply")) {
                            const t: Value = if (args.len > 0) args[0] else Value.undef();
                            const list = try self.argListFromArrayLike(if (args.len > 1) args[1] else Value.undef());
                            return try self.callValueWithThis(recv, list, t);
                        }
                        if (eq(name, "bind")) {
                            return try self.makeBound(o, if (args.len > 0) args[0] else Value.undef(), if (args.len > 1) args[1..] else &.{});
                        }
                        if (eq(name, "toString")) return try self.functionToString(o);
                    }
                    if (eq(name, "hasOwnProperty")) {
                        const k = if (args.len > 0) try self.keyOf(args[0]) else "undefined";
                        return Value.boolVal(try self.objectProtoHasOwn(o, k));
                    }
                    if (eq(name, "propertyIsEnumerable")) {
                        const k = if (args.len > 0) try self.keyOf(args[0]) else "undefined";
                        return Value.boolVal(try self.objectProtoPropertyIsEnumerable(o, k));
                    }
                    if (eq(name, "isPrototypeOf")) {
                        if (!(args.len > 0 and args[0].isObject() and !args[0].asObj().is_symbol and !args[0].asObj().is_bigint)) return Value.boolVal(false);
                        var cur: Value = args[0];
                        while (cur.isObject()) {
                            const next = if (cur.asObj().proxyHandler() != null or cur.asObj().proxy_revoked)
                                try self.proxyGetProto(cur.asObj())
                            else if (cur.asObj().proto) |p| Value.obj(p) else Value.nul();
                            if (!next.isObject()) return Value.boolVal(false);
                            if (next.asObj() == o) return Value.boolVal(true);
                            cur = next;
                        }
                        return Value.boolVal(false);
                    }
                    // Annex-B legacy accessor helpers.
                    if (eq(name, "__defineGetter__") or eq(name, "__defineSetter__")) {
                        const f = arg(args, 1);
                        if (!f.isCallable()) return self.throwError("TypeError", "Object.prototype.__define[GS]etter__: Expecting function");
                        // ToPropertyKey(P): a Symbol key is honored and a thrown
                        // valueOf/toString propagates.
                        const key = try self.keyOf(arg0(args));
                        // DefinePropertyOrThrow with { get|set, enumerable, configurable }:
                        // route through the shared descriptor machinery so a
                        // non-configurable existing property or a non-extensible
                        // object throws a TypeError (not a silent overwrite).
                        const desc = (try self.newObject()).asObj();
                        try desc.setOwn(self.arena, self.root_shape, if (eq(name, "__defineGetter__")) "get" else "set", f);
                        try desc.setOwn(self.arena, self.root_shape, "enumerable", Value.boolVal(true));
                        try desc.setOwn(self.arena, self.root_shape, "configurable", Value.boolVal(true));
                        try builtins.defineOne(self, o, key, desc);
                        return Value.undef();
                    }
                    if (eq(name, "__lookupGetter__") or eq(name, "__lookupSetter__")) {
                        // Spec walk: at each level take [[GetOwnProperty]](key); if it
                        // exists, return its accessor get/set (or undefined for a data
                        // property); else step [[GetPrototypeOf]]. Both steps are
                        // proxy-aware, so a throwing trap propagates (per the err tests).
                        const key = try self.keyOf(arg0(args)); // ToPropertyKey once
                        const key_v = try self.keyToValue(key);
                        const want_get = eq(name, "__lookupGetter__");
                        var cur: Value = recv;
                        while (cur.isObject()) {
                            const desc = try builtins.objectGetOwnPropertyDescriptor(@ptrCast(self), Value.undef(), &.{ cur, key_v });
                            if (desc.isObject()) {
                                const d = desc.asObj();
                                if (d.getOwn("get") != null or d.getOwn("set") != null)
                                    return (if (want_get) d.getOwn("get") else d.getOwn("set")) orelse Value.undef();
                                return Value.undef(); // a data property shadows
                            }
                            const c = cur.asObj();
                            cur = if (c.proxyHandler() != null or c.proxy_revoked)
                                try self.proxyGetProto(c)
                            else if (c.protoAtomic()) |p| Value.obj(p) else Value.nul();
                        }
                        return Value.undef();
                    }
                    // Error.prototype.toString — before the generic Array `toString`
                    // (join) fallback below would wrongly intercept error objects.
                    if (o.behavior.is_error and eq(name, "toString")) return try errorToStringFn(@ptrCast(self), recv, args);
                    if (o.is_symbol and eq(name, "toString")) return try symbolToStringFn(@ptrCast(self), recv, args);
                    if (o.is_symbol and eq(name, "valueOf")) return recv;
                }
                if (o.behavior.is_regex) return try self.regexMethod(o, name, args);
                if (o.behavior.is_date) return try self.dateMethod(o, name, args);
                if (o.is_map) return try self.mapMethod(o, name, args);
                if (o.is_set) return try self.setMethod(o, name, args);
                // A typed array's own methods take precedence over the Array-like
                // coercion path (slice/indexOf/map/… are shared names).
                if (o.typedArray() != null and o.getOwn(name) == null) {
                    if (try typedArrayMethod(self, o, name, args)) |r| return r;
                }
                // A String wrapper object (`new String("…")`): its String.prototype
                // methods take precedence over the generic Array-like coercion for
                // names both share (slice/indexOf/lastIndexOf/includes/concat/at).
                if (o.boxedPrimitive() != null and o.boxedPrimitive().?.isString() and o.getOwn(name) == null) {
                    const bp = o.boxedPrimitive().?;
                    if (eq(name, "valueOf") or eq(name, "toString")) return bp;
                    if (eq(name, "concat")) return try self.stringConcatReceiverValue(recv, args, false);
                    const string = try self.toStringValue(recv);
                    if (try self.stringMethodValue(string, name, args, true, recv)) |r| return r;
                }
                if (o.is_array and o.getOwn(name) == null) return try self.arrayMethod(o, name, args);
                // Generic Array.prototype methods on an array-like `this`
                // (`Array.prototype.map.call(obj, …)`).
                if (o.getOwn(name) == null and isArrayGeneric(name)) {
                    if (try self.arrayMethod(o, name, args)) |r| return r;
                }
                // Generic String.prototype methods coerce `this` to string
                // (`String.prototype.split.call(obj)`).
                if (o.getOwn(name) == null and isStringGeneric(name)) {
                    if (eq(name, "concat")) return try self.stringConcatReceiverValue(recv, args, false);
                    return try self.stringMethodValue(try self.toStringValue(recv), name, args, true, recv);
                }
                // `Object.prototype.valueOf` for an ordinary object returns the
                // object itself (ToObject(this)). Reached only after the kind
                // dispatch above (Date/Array/Map/… handle their own valueOf) and
                // only for a non-wrapper (a wrapper delegates to its `.boxedPrimitive()` below).
                if (o.getOwn(name) == null and o.boxedPrimitive() == null and eq(name, "valueOf")) return recv;
                // A primitive-wrapper object (`new Number/String/Boolean`)
                // delegates unmatched methods to its boxed primitive, so
                // `(new Number(5)).valueOf()`, `.toFixed(2)`, `.charAt(0)`, … work.
                if (o.boxedPrimitive()) |p| {
                    if (o.getOwn(name) == null) {
                        if (try self.builtinMethod(p, name, args)) |r| return r;
                    }
                }
            },
            .string => {
                if (eq(name, "valueOf") or eq(name, "toString")) return recv;
                return try self.stringMethodValue(recv, name, args, true, recv);
            },
            .number => {
                if (try self.numberMethod(recv.asNum(), name, args)) |r| return r;
                if (eq(name, "concat")) return try self.stringConcatReceiverValue(recv, args, false);
                if (isStringGeneric(name)) return try self.stringMethodValue(try self.toStringValue(recv), name, args, true, recv);
            },
            .boolean => {
                if (try self.booleanMethod(recv.asBool(), name, args)) |r| return r;
                if (eq(name, "concat")) return try self.stringConcatReceiverValue(recv, args, false);
                if (isStringGeneric(name)) return try self.stringMethodValue(try self.toStringValue(recv), name, args, true, recv);
            },
            else => {},
        }
        return null;
    }

    /// String.prototype methods that coerce `this` to a string (so e.g.
    /// `String.prototype.trim.call(42)` works). Excludes toString/valueOf.
    fn isStringGeneric(name: []const u8) bool {
        const names = [_][]const u8{
            "charAt",        "charCodeAt", "codePointAt", "indexOf",      "lastIndexOf",       "includes",
            "startsWith",    "endsWith",   "slice",       "substring",    "substr",            "toUpperCase",
            "toLowerCase",   "trim",       "trimStart",   "trimEnd",      "repeat",            "concat",
            "split",         "at",         "padStart",    "padEnd",       "replace",           "replaceAll",
            "localeCompare", "normalize",  "search",      "match",        "toLocaleUpperCase", "toLocaleLowerCase",
            "matchAll",      "trimLeft",   "trimRight",   "isWellFormed", "toWellFormed",      "anchor",
            "big",           "blink",      "bold",        "fixed",        "fontcolor",         "fontsize",
            "italics",       "link",       "small",       "strike",       "sub",               "sup",
        };
        for (names) |n| if (eq(name, n)) return true;
        return false;
    }

    /// Generic read-only Array.prototype methods that work on any array-like
    /// `this` (e.g. `Array.prototype.map.call(arrayLikeObj, fn)`). Mutators stay
    /// real-array-only.
    /// Methods that ArraySpeciesCreate (or otherwise ArrayCreate) a result whose
    /// length comes from the source `length` — so a length above 2^32-1 is a
    /// RangeError. Read-only / in-place methods don't create such a result.
    fn arrayCreatesResult(name: []const u8) bool {
        const names = [_][]const u8{
            "map", "concat", "with", "toReversed", "toSorted",
        };
        for (names) |n| if (eq(name, n)) return true;
        return false;
    }

    /// Methods that read an array-like through live short-circuiting [[Get]]
    /// (returning as soon as a match is found, or only touching the tail) — so
    /// they accept a huge-length array-like without iterating it to exhaustion.
    /// Every OTHER method that loops the full length bails (returns null) on a
    /// pathological array-like length to avoid an unbounded native loop.
    fn arraySearchReadsLive(name: []const u8) bool {
        return eq(name, "indexOf") or eq(name, "lastIndexOf") or eq(name, "includes") or
            eq(name, "push") or eq(name, "pop") or
            eq(name, "forEach") or eq(name, "filter") or eq(name, "reduce") or
            eq(name, "reduceRight") or
            eq(name, "some") or eq(name, "every") or eq(name, "find") or
            eq(name, "findIndex") or eq(name, "findLast") or eq(name, "findLastIndex");
    }

    fn isArrayGeneric(name: []const u8) bool {
        const names = [_][]const u8{
            "join",          "indexOf",   "lastIndexOf", "includes",       "slice", "concat",     "map",       "filter",
            "forEach",       "reduce",    "reduceRight", "some",           "every", "find",       "findIndex", "findLast",
            "findLastIndex", "at",        "flat",        "flatMap",        "keys",  "values",     "entries",   "toReversed",
            "toSorted",      "toSpliced", "with",        "toLocaleString",
            // fill/copyWithin operate purely through [[Get]]/[[Set]] over the
            // receiver, so they work on an array-like `this` (and read its
            // `length` via ToLength, throwing for a Symbol/BigInt length).
            "fill",  "copyWithin",
        };
        // NB: `toString` is intentionally NOT generic here — a plain object's
        // `.toString()` must reach `Object.prototype.toString` (the `[object
        // Tag]` native), not join an array-like into "". Real arrays still join
        // via the `is_array` branch in `builtinMethod`.
        for (names) |n| if (eq(name, n)) return true;
        return false;
    }

    /// Decimal index keys are invocation-local observations, not realm state.
    /// Every consumer below either finishes synchronously (including Proxy traps,
    /// which first materialize a JS String) or copies a newly published ordinary
    /// property into its Shape/key-order owner before returning. Keeping this
    /// contract explicit prevents attacker-controlled logical lengths from
    /// retaining one arena allocation per observed index (#529).
    fn borrowedIndexKey(storage: *[32]u8, index: anytype) []const u8 {
        return std.fmt.bufPrint(storage, "{d}", .{index}) catch unreachable;
    }

    /// Whether array/array-like index `i` is present (own dense non-hole, own
    /// sparse named, or inherited) — the HasProperty the iteration methods use to
    /// skip holes.
    fn arrIndexPresent(self: *Interpreter, o: *value.Object, i: usize) EvalError!bool {
        // Dense fast path: a real (non-hole) in-range element of a plain array
        // is definitely present — no per-index string allocation. A *hole*
        // falls through, because an index property inherited from the prototype
        // chain can still make it present (HasProperty walks the chain).
        if (o.is_array and o.accessorsMap() == null and o.denseElementPresent(i))
            return true;
        if (o.typedArray()) |ta| {
            if (i < (ta.currentLength() orelse 0)) return true;
        }
        var key_storage: [32]u8 = undefined;
        const ks = borrowedIndexKey(&key_storage, i);
        return try self.hasPropertyResult(o, ks);
    }

    /// `o[i]` via [[Get]] (so an accessor index runs its getter, and inherited
    /// indices resolve) — used by the iteration methods.
    fn arrIndexGet(self: *Interpreter, o: *value.Object, i: usize) EvalError!Value {
        // Dense fast path mirrors `arrIndexPresent`; a hole goes through [[Get]]
        // so an inherited index (accessor or value) on the prototype resolves.
        if (o.is_array and o.accessorsMap() == null) {
            if (o.denseElement(i)) |v| return v;
        }
        var key_storage: [32]u8 = undefined;
        const ks = borrowedIndexKey(&key_storage, i);
        return self.getProperty(Value.obj(o), ks);
    }

    /// Set(O, ToString(i), v, true) — SetPropertyOrThrow on an integer index.
    fn arrIndexSetOrThrow(self: *Interpreter, o: *value.Object, i: usize, v: Value) EvalError!void {
        // Dense fast path, mirroring `arrIndexPresent`/`arrIndexGet` above: on a
        // plain extensible array with no accessors/attributes and a clean
        // prototype chain, [[Set]] of an integer index *is* the dense store, so
        // no key is needed at all. Before #529, the generic path formatted the
        // index into the realm arena, whose memory is never reclaimed within a
        // Context, so a whole-array `fill`/`copyWithin` burned one permanently-
        // retained key per element. Under `heap_limit_bytes` that made a single
        // `new Array(1 << 16).fill(2)` consume megabytes of budget that no
        // collection could recover, turning a later ordinary allocation into an
        // unrecoverable OOM (#100).
        if (try self.setFastArrayNumericIndex(Value.obj(o), i, v)) return;
        var key_storage: [32]u8 = undefined;
        const ks = borrowedIndexKey(&key_storage, i);
        if (!try self.setMemberResult(Value.obj(o), ks, v, Value.obj(o)))
            return self.throwError("TypeError", "Cannot set array index");
    }

    /// DeletePropertyOrThrow(O, ToString(i)).
    fn arrIndexDeleteOrThrow(self: *Interpreter, o: *value.Object, i: usize) EvalError!void {
        var key_storage: [32]u8 = undefined;
        const ks = borrowedIndexKey(&key_storage, i);
        if (!try self.deleteOwn(o, ks))
            return self.throwError("TypeError", "Cannot delete array index");
    }

    /// Spread one concat-spreadable source into `dst`, preserving holes: a real
    /// Array uses its sparse `length`, an array-like reads ToLength(.length).
    /// A pathological 2**53-style length throws (instead of OOM-crashing).
    fn concatSpreadInto(self: *Interpreter, dst: Value, src: *value.Object, n: *usize) EvalError!void {
        const slen: usize = if (src.is_array and !src.is_arguments) src.arrayLength() else blk: {
            break :blk toArrayLikeLen((try self.toPrimitive(try self.getProperty(Value.obj(src), "length"), .number)).toNumber());
        };
        const max_safe_len: usize = 9007199254740991;
        if (slen > max_safe_len - n.*) return self.throwError("TypeError", "Invalid array length");
        // A plain dense Array result preserves holes (append + markHole); a
        // species/exotic result leaves a hole as an absent index (CreateDataProperty
        // only for present elements).
        const dense = dst.isObject() and dst.asObj().is_array and dst.asObj().accessorsMap() == null and
            dst.asObj().attrsMap() == null and dst.asObj().proxyHandler() == null and !dst.asObj().proxy_revoked;
        var j: usize = 0;
        while (j < slen) : (j += 1) {
            if (j > (1 << 22)) return self.throwError("TypeError", "Invalid array length");
            if (try self.arrIndexPresent(src, j)) {
                try self.arrayResultPush(dst, n.*, try self.arrIndexGet(src, j));
            } else if (dense) {
                const base = dst.asObj().elementsLen();
                try dst.asObj().appendElement(self.arena, Value.undef());
                try dst.asObj().markHole(self.arena, base);
            }
            n.* += 1;
        }
    }

    /// Process one concat operand: spread it when concat-spreadable (per the
    /// `Symbol.isConcatSpreadable` override, else only real Arrays), else
    /// CreateDataProperty it whole at the running result index `n`. `ck` is the
    /// cached `Symbol.isConcatSpreadable` property key.
    fn concatProcessOne(self: *Interpreter, dst: Value, v: Value, ck: ?[]const u8, n: *usize) EvalError!void {
        var spread: bool = false;
        if (v.isObject() and !v.asObj().is_symbol and !v.asObj().is_bigint) {
            if (ck) |k| {
                const flag = try self.getProperty(v, k);
                spread = if (!flag.isUndefined()) flag.toBoolean() else try objectToStringIsArray(self, v.asObj());
            } else {
                spread = try objectToStringIsArray(self, v.asObj());
            }
        }
        if (spread) {
            try self.concatSpreadInto(dst, v.asObj(), n);
        } else {
            try self.arrayResultPush(dst, n.*, v);
            n.* += 1;
        }
    }

    /// ToIntegerOrInfinity-based start index for the forward searches
    /// (indexOf/includes): a negative `fromIndex` counts from the end, `+∞`
    /// (or any value ≥ len) yields `len` (no iterations), NaN/undefined → 0.
    fn fromIndexForward(self: *Interpreter, v: Value, len: usize) EvalError!usize {
        const n = try self.toNumberV(v);
        if (std.math.isNan(n)) return 0;
        const flen: f64 = @floatFromInt(len);
        const fl = @trunc(n);
        if (fl >= flen) return len;
        if (fl < 0) {
            const from_end = flen + fl;
            return if (from_end < 0) 0 else @intFromFloat(from_end);
        }
        return @intFromFloat(fl);
    }

    /// The real array's *sparse* own integer-index keys lying in `[lo, hi)`,
    /// returned in ascending order. These are indices stored as named
    /// properties (past the dense `elements` store, e.g. `a[2**31]=x`), so the
    /// search methods can visit them without walking the whole logical length.
    fn arrSparseIndices(self: *Interpreter, o: *value.Object, lo: usize, hi: usize) EvalError![]usize {
        var list: std.ArrayListUnmanaged(usize) = .empty;
        const keys = try o.ownKeysWithScratch(self.arena, self.scratch_allocator orelse self.arena);
        for (keys) |k| {
            if (arrayIndex(k)) |idx| {
                if (idx >= lo and idx < hi) try list.append(self.arena, idx);
            }
        }
        std.mem.sort(usize, list.items, {}, std.sort.asc(usize));
        return list.items;
    }

    /// Whether a real array's `length` is writable — `Set(O, "length", …, true)`
    /// (the final step of pop/push/shift/unshift/splice) throws when it is not.
    fn arrayLenWritable(o: *value.Object) bool {
        return !(o.attrsMap() != null and !o.getAttr("length").writable);
    }

    /// Whether some object on `o`'s *prototype* chain can intercept a
    /// (array-index) write — so an assignment to a hole/out-of-range index routes
    /// through OrdinarySet instead of the dense store.
    fn arrayProtoMayInterceptSet(self: *Interpreter, o: *value.Object, key: []const u8) bool {
        var cur: ?*value.Object = self.effectiveProto(o);
        while (cur) |c| {
            if (c.proxyHandler() != null or c.proxy_revoked) return true;
            if (c.typedArray() != null and canonicalNumericIndexString(key) != null) return true;
            if (c.getAccessor(key) != null) return true;
            if (objectHasOwn(c, key)) return true;
            cur = self.effectiveProto(c);
        }
        return false;
    }

    /// `Set(O, ToString(i), v, true)` — the throwing element store used by
    /// push/unshift: fires an inherited index setter and rejects a non-extensible
    /// / non-writable slot (forcing strict so the rejection throws). User setters
    /// keep their own strictness.
    fn arraySetIndexThrowing(self: *Interpreter, o: *value.Object, i: usize, v: Value) EvalError!void {
        var key_storage: [32]u8 = undefined;
        const idx = borrowedIndexKey(&key_storage, i);
        const saved = self.strict;
        self.strict = true;
        defer self.strict = saved;
        return self.setMember(Value.obj(o), idx, v);
    }

    /// `Set(O, "length", newLen, true)` for a grow (push/unshift): a real array
    /// with non-writable `length` throws; otherwise the logical length advances.
    /// An array-like routes through [[Set]].
    fn arraySetLengthThrowing(self: *Interpreter, o: *value.Object, new_len: usize) EvalError!void {
        if (o.is_array) {
            if (new_len > 4294967295) return self.throwError("RangeError", "Invalid array length");
            if (!arrayLenWritable(o)) return self.throwError("TypeError", "Cannot assign to read only property 'length'");
            if (!try self.setArrayLength(o, new_len))
                return self.throwError("TypeError", "Cannot delete a non-configurable array element");
            return;
        }
        if (o.boxedPrimitive()) |p| if (p.isString())
            return self.throwError("TypeError", "Cannot assign to read only property 'length'");
        // Set(O, "length", newLen, true) — force strict so a non-writable /
        // setter-less length on an array-like rejects with a TypeError.
        const saved = self.strict;
        self.strict = true;
        defer self.strict = saved;
        try self.setMember(Value.obj(o), "length", Value.num(@floatFromInt(new_len)));
    }

    /// Whether the array's element at dense index `i` carries an explicit
    /// non-configurable attribute (only possible after `seal`/`freeze` or a
    /// `defineProperty`) — so deleting it (pop/shift) must throw.
