        if (eq(name, "toPrecision")) {
            // `precision === undefined` returns ToString(x) without coercion;
            // otherwise ToIntegerOrInfinity(precision) runs before the not-finite
            // return.
            if (args.len == 0 or args[0].isUndefined()) return try Value.strAlloc(self.arena, try value.numberToString(self.arena, n));
            const p = try self.toNumberV(args[0]);
            if (std.math.isNan(n)) return Value.str("NaN");
            if (std.math.isInf(n)) return if (n < 0) Value.str("-Infinity") else Value.str("Infinity");
            const pf = if (std.math.isNan(p)) @as(f64, 0) else @trunc(p);
            if (pf < 1 or pf > 100) return self.throwError("RangeError", "toPrecision() argument must be between 1 and 100");
            return try Value.strAlloc(self.arena, try toPrecisionStr(self.arena, n, @intFromFloat(pf)));
        }
        return null;
    }

    fn booleanMethod(self: *Interpreter, b: bool, name: []const u8, args: []const Value) EvalError!?Value {
        _ = self;
        _ = args;
        if (eq(name, "valueOf")) return Value.boolVal(b);
        if (eq(name, "toString")) return if (b) Value.str("true") else Value.str("false");
        return null;
    }

    /// The well-known Symbol whose method backs a String regex-protocol method
    /// (`replaceAll` shares `Symbol.replace`), or null for a plain method.
    fn stringProtocolSymbol(_: *Interpreter, name: []const u8) ?[]const u8 {
        if (eq(name, "split")) return "split";
        if (eq(name, "match")) return "match";
        // `matchAll`/`replaceAll` are intentionally absent: their branches perform
        // the full spec dispatch (IsRegExp/global-flag check, GetMethod for objects).
        if (eq(name, "search")) return "search";
        if (eq(name, "replace")) return "replace";
        return null;
    }

    /// IsRegExp(v): true if `v` is an object whose `[Symbol.match]` is truthy
    /// (or, when that property is absent, has a [[RegExpMatcher]] — `is_regex`).
    pub fn isRegExp(self: *Interpreter, v: Value) EvalError!bool {
        if (!v.isObject()) return false;
        if (self.wellKnownSymbolKey("match")) |mkey| {
            const m = try self.getProperty(v, mkey);
            if (!m.isUndefined()) return m.toBoolean();
        }
        return v.asObj().behavior.is_regex;
    }

    fn stringProtocolDispatch(self: *Interpreter, name: []const u8, receiver: Value, args: []const Value) EvalError!?Value {
        const sym = self.stringProtocolSymbol(name) orelse return null;
        const target = arg0(args);
        if (!builtins.isRealObject(target)) return null;
        const key = self.wellKnownSymbolKey(sym) orelse return null;
        const method = try self.getProperty(target, key);
        if (method.isUndefined() or method.isNull()) return null;
        if (!method.isCallable()) return self.throwError("TypeError", "String.prototype protocol method is not callable");
        var argv: std.ArrayListUnmanaged(Value) = .empty;
        try argv.append(self.arena, receiver);
        if (args.len > 1) try argv.appendSlice(self.arena, args[1..]);
        return try self.callValueWithThis(method, argv.items, target);
    }

    fn replaceAllProtocolDispatch(self: *Interpreter, receiver: Value, args: []const Value) EvalError!?Value {
        const search = arg0(args);
        if (search.isUndefined() or search.isNull()) return null;
        if (try self.isRegExp(search)) {
            const flags_v = try self.getProperty(search, "flags");
            if (flags_v.isUndefined() or flags_v.isNull())
                return self.throwError("TypeError", "String.prototype.replaceAll called with a RegExp whose flags is undefined or null");
            const flags_s = try self.toStringWtf8(flags_v);
            if (std.mem.indexOfScalar(u8, flags_s, 'g') == null)
                return self.throwError("TypeError", "String.prototype.replaceAll must be called with a global RegExp");
        }
        if (!builtins.isRealObject(search)) return null;
        const key = self.wellKnownSymbolKey("replace") orelse return null;
        const method = try self.getProperty(search, key);
        if (method.isUndefined() or method.isNull()) return null;
        if (!method.isCallable()) return self.throwError("TypeError", "searchValue[Symbol.replace] is not callable");
        return try self.callValueWithThis(method, &.{ receiver, arg(args, 1) }, search);
    }

    fn stringReceiverValue(self: *Interpreter, s: []const u8, s_cell: ?*const StringCell) EvalError!Value {
        if (s_cell) |cell| return Value.strCell(cell);
        return Value.strAlloc(self.arena, s);
    }

    fn stringMethodUsesCodeUnitCell(name: []const u8) bool {
        return eq(name, "charAt") or eq(name, "charCodeAt") or eq(name, "at") or eq(name, "codePointAt");
    }

    /// Methods whose implementation is exact on a flat latin1 image: they do
    /// UTF-16 index arithmetic (where a byte offset IS the index) and copy out a
    /// byte range, never decoding the bytes as WTF-8. `stringSliceUtf16` re-encodes
    /// just the extracted range, so the cost is O(result) rather than O(receiver).
    fn stringMethodReadsFlatImage(name: []const u8) bool {
        return eq(name, "slice") or eq(name, "substring") or eq(name, "substr") or
            eq(name, "indexOf") or eq(name, "lastIndexOf") or eq(name, "includes") or
            eq(name, "startsWith") or eq(name, "endsWith") or
            eq(name, "padStart") or eq(name, "padEnd") or
            eq(name, "trim") or eq(name, "trimStart") or eq(name, "trimEnd") or
            eq(name, "trimLeft") or eq(name, "trimRight");
    }

    fn stringMethodValue(
        self: *Interpreter,
        string: Value,
        name: []const u8,
        args: []const Value,
        check_protocol: bool,
        protocol_receiver: ?Value,
    ) EvalError!?Value {
        std.debug.assert(string.isString());
        if (eq(name, "repeat")) return try self.stringRepeatValue(string, args);
        if (eq(name, "concat")) return try self.stringConcatValue(string, args);
        // A flat latin1 cell stores one byte per code unit, so `asWtf8` has to
        // re-encode the WHOLE receiver — O(n) per call, which turns a loop of
        // short slices into O(n^2). Methods that only need fixed-width index
        // math read the stored image directly instead; everything else keeps the
        // WTF-8 view, so no other reader can meet a flat byte.
        const flat = string.strIsFlatLatin1() and stringMethodReadsFlatImage(name);
        const bytes = if (flat or stringMethodUsesCodeUnitCell(name))
            string.asStr()
        else
            try string.asWtf8(self.arena);
        return self.stringMethod(bytes, name, args, check_protocol, string.asStringCell(), protocol_receiver, flat);
    }

    fn canonicalStringByteLength(string: Value) EvalError!usize {
        std.debug.assert(string.isString());
        const source = string.asStr();
        var len = source.len;
        if (string.strIsFlatLatin1()) for (source) |byte| {
            if (byte >= 0x80)
                len = std.math.add(usize, len, 1) catch return error.OutOfMemory;
        };
        return len;
    }

    fn copyCanonicalString(string: Value, output: []u8) usize {
        std.debug.assert(string.isString());
        const source = string.asStr();
        if (!string.strIsFlatLatin1()) {
            @memcpy(output[0..source.len], source);
            return source.len;
        }
        var written: usize = 0;
        for (source) |byte| {
            if (byte < 0x80) {
                output[written] = byte;
                written += 1;
            } else {
                output[written] = @intCast(0xC0 | (byte >> 6));
                output[written + 1] = @intCast(0x80 | (byte & 0x3F));
                written += 2;
            }
        }
        return written;
    }

    fn stringStartsWithLowSurrogate(string: Value) bool {
        if (string.strIsFlatLatin1()) return false;
        const unit = wtf8SurrogateAt(string.asStr(), 0) orelse return false;
        return isLowSurrogate(unit);
    }

    fn stringEndsWithHighSurrogate(string: Value) bool {
        if (string.strIsFlatLatin1()) return false;
        const source = string.asStr();
        if (source.len < 3) return false;
        const unit = wtf8SurrogateAt(source, source.len - 3) orelse return false;
        return isHighSurrogate(unit);
    }

    fn concatStringSequence(self: *Interpreter, strings: []const Value) EvalError!Value {
        std.debug.assert(strings.len != 0);
        // Coercion is already complete. Size the canonical WTF-8 result before
        // allocating it, while accounting for surrogate pairs formed across
        // empty pieces, then stream every physical representation exactly once.
        var output_len: usize = 0;
        var nonempty_count: usize = 0;
        var sole_nonempty = strings[0];
        var previous: ?Value = null;
        for (strings) |string| {
            std.debug.assert(string.isString());
            if (string.asStringCell().utf16Len() == 0) continue;
            const piece_len = try canonicalStringByteLength(string);
            output_len = std.math.add(usize, output_len, piece_len) catch return error.OutOfMemory;
            if (previous) |left| {
                if (stringEndsWithHighSurrogate(left) and stringStartsWithLowSurrogate(string)) output_len -= 2;
            }
            if (output_len > max_string_bytes) return self.throwError("RangeError", "Invalid string length");
            nonempty_count += 1;
            sole_nonempty = string;
            previous = string;
        }

        if (nonempty_count == 0) return strings[0];
        if (nonempty_count == 1) return sole_nonempty;

        const output = try self.arena.alloc(u8, output_len);
        var written: usize = 0;
        previous = null;
        for (strings) |string| {
            if (string.asStringCell().utf16Len() == 0) continue;
            const joins_surrogate_pair = if (previous) |left|
                stringEndsWithHighSurrogate(left) and stringStartsWithLowSurrogate(string)
            else
                false;
            if (joins_surrogate_pair) {
                std.debug.assert(written >= 3);
                written -= 3;
                const left_source = previous.?.asStr();
                const right_source = string.asStr();
                const high = wtf8SurrogateAt(left_source, left_source.len - 3).?;
                const low = wtf8SurrogateAt(right_source, 0).?;
                const code_point: u21 = 0x10000 + ((@as(u21, high) - 0xD800) << 10) + (@as(u21, low) - 0xDC00);
                var encoded: [4]u8 = undefined;
                const encoded_len = std.unicode.utf8Encode(code_point, &encoded) catch unreachable;
                std.debug.assert(encoded_len == encoded.len);
                @memcpy(output[written..][0..encoded.len], &encoded);
                written += encoded.len;
                @memcpy(output[written..][0 .. right_source.len - 3], right_source[3..]);
                written += right_source.len - 3;
            } else {
                written += copyCanonicalString(string, output[written..]);
            }
            previous = string;
        }
        std.debug.assert(written == output.len);
        return Value.strOwned(self.arena, output);
    }

    fn concatStringValues(self: *Interpreter, left: Value, right: Value) EvalError!Value {
        return self.concatStringSequence(&.{ left, right });
    }

    fn stringConcatReceiverValue(
        self: *Interpreter,
        receiver: Value,
        args: []const Value,
        receiver_is_string: bool,
    ) EvalError!Value {
        std.debug.assert(!receiver_is_string or receiver.isString());
        if (args.len == 0 and receiver_is_string) return receiver;
        const piece_count = std.math.add(usize, args.len, 1) catch return error.OutOfMemory;

        // Receiver/argument coercion can execute arbitrary JavaScript and
        // trigger a moving collection. Publish every *original* value before
        // the first ToString, then replace each slot with its completed string.
        // Rooting only completed results would leave later object arguments as
        // stale raw Values after an earlier coercion crossed a moving safepoint.
        const roots_mark = try self.pushTempRoot(receiver);
        defer self.restoreTempRoots(roots_mark);
        if (self.gc != null) {
            for (args, 1..) |argument, index| {
                const argument_root = try self.pushTempRoot(argument);
                std.debug.assert(argument_root == roots_mark + index);
            }
            if (!receiver_is_string)
                self.setTempRoot(roots_mark, try self.toStringValue(self.tempRoot(roots_mark, receiver)));
            for (args, 1..) |argument, index| {
                const root = roots_mark + index;
                self.setTempRoot(root, try self.toStringValue(self.tempRoot(root, argument)));
            }
            return self.concatStringSequence(
                self.gc_temp_roots.items[roots_mark .. roots_mark + piece_count],
            );
        }

        const string = if (receiver_is_string) receiver else try self.toStringValue(receiver);
        // Keep ordinary short calls metadata-allocation-free. Larger calls use
        // one exact compile-time-independent slice so each observable ToString
        // runs once and its immutable result survives until final construction.
        var inline_pieces: [8]Value = undefined;
        const pieces = if (piece_count <= inline_pieces.len)
            inline_pieces[0..piece_count]
        else
            try self.arena.alloc(Value, piece_count);
        pieces[0] = string;
        for (args, 1..) |argument, index|
            pieces[index] = try self.toStringValue(argument);
        return self.concatStringSequence(pieces);
    }

    fn stringConcatValue(self: *Interpreter, string: Value, args: []const Value) EvalError!Value {
        return self.stringConcatReceiverValue(string, args, true);
    }

    fn stringRepeatValue(self: *Interpreter, string: Value, args: []const Value) EvalError!Value {
        const count_number = try self.toNumberV(arg0(args));
        const count_integer = if (std.math.isNan(count_number)) @as(f64, 0) else @trunc(count_number);
        if (count_integer < 0 or std.math.isInf(count_integer))
            return self.throwError("RangeError", "Invalid count value");
        if (count_integer == 0) return Value.str("");
        if (string.asStringCell().utf16Len() == 0) return string;
        if (count_integer == 1) return string;

        const source = string.asStr();
        const source_flat = string.strIsFlatLatin1();
        const canonical_source_len = try canonicalStringByteLength(string);

        const first_surrogate = if (!source_flat) wtf8SurrogateAt(source, 0) else null;
        const last_surrogate = if (!source_flat and source.len >= 3) wtf8SurrogateAt(source, source.len - 3) else null;
        const joins_surrogate_pair = first_surrogate != null and last_surrogate != null and
            isLowSurrogate(first_surrogate.?) and isHighSurrogate(last_surrogate.?);
        const per_additional_copy = canonical_source_len - @as(usize, if (joins_surrogate_pair) 2 else 0);
        if (canonical_source_len > max_string_bytes) return self.throwError("RangeError", "Invalid string length");
        const max_count = 1 + (max_string_bytes - canonical_source_len) / per_additional_copy;
        if (count_integer > @as(f64, @floatFromInt(max_count)))
            return self.throwError("RangeError", "Invalid string length");
        const count: usize = @intFromFloat(count_integer);
        const tail_len = std.math.mul(usize, count - 1, per_additional_copy) catch return error.OutOfMemory;
        const output_len = std.math.add(usize, canonical_source_len, tail_len) catch return error.OutOfMemory;
        const output = try self.arena.alloc(u8, output_len);

        if (source_flat) {
            var initialized = copyCanonicalString(string, output);
            std.debug.assert(initialized == canonical_source_len);
            while (initialized < output.len) {
                const copy_len = @min(initialized, output.len - initialized);
                @memcpy(output[initialized .. initialized + copy_len], output[0..copy_len]);
                initialized += copy_len;
            }
        } else if (joins_surrogate_pair) {
            const prefix_len = source.len - 3;
            @memcpy(output[0..prefix_len], source[0..prefix_len]);
            var initialized = prefix_len;
            const high = last_surrogate.?;
            const low = first_surrogate.?;
            const code_point: u21 = 0x10000 + ((@as(u21, high) - 0xD800) << 10) + (@as(u21, low) - 0xDC00);
            var encoded: [4]u8 = undefined;
            const encoded_len = std.unicode.utf8Encode(code_point, &encoded) catch unreachable;
            std.debug.assert(encoded_len == encoded.len);
            const middle = source[3 .. source.len - 3];
            for (1..count) |_| {
                @memcpy(output[initialized..][0..encoded.len], &encoded);
                initialized += encoded.len;
                @memcpy(output[initialized..][0..middle.len], middle);
                initialized += middle.len;
            }
            @memcpy(output[initialized..][0..3], source[source.len - 3 ..]);
            initialized += 3;
            std.debug.assert(initialized == output.len);
        } else {
            @memcpy(output[0..source.len], source);
            var initialized = source.len;
            while (initialized < output.len) {
                const copy_len = @min(initialized, output.len - initialized);
                @memcpy(output[initialized .. initialized + copy_len], output[0..copy_len]);
                initialized += copy_len;
            }
        }
        return Value.strOwned(self.arena, output);
    }

    /// ToIntegerOrInfinity(v) clamped into `[0, len]` — the position argument of
    /// `includes`/`startsWith`/`endsWith` (a Symbol/BigInt throws via toNumberV).
    fn clampPos(self: *Interpreter, v: Value, len: usize) EvalError!usize {
        const n = try self.toNumberV(v);
        if (std.math.isNan(n) or n <= 0) return 0;
        const flen: f64 = @floatFromInt(len);
        if (n >= flen) return len;
        return @intFromFloat(@trunc(n));
    }

    // `s_cell` retains immutable receiver metadata when ToString returned an
    // existing StringData cell. Raw coerced bytes pass null. ASCII byte-offset
    // fast paths and the bounded non-ASCII index are selected from the cell.
    fn stringMethod(
        self: *Interpreter,
        s: []const u8,
        name: []const u8,
        args: []const Value,
        check_protocol: bool,
        s_cell: ?*const StringCell,
        protocol_receiver: ?Value,
        /// `s` is the receiver's flat latin1 image rather than its WTF-8 view —
        /// set only for `stringMethodReadsFlatImage` names. It describes the
        /// BYTES, not the cell: a flat cell reached through `asWtf8` is false.
        s_flat: bool,
    ) EvalError!?Value {
        // Both representations are one byte per UTF-16 code unit, so a byte
        // offset into `s` is a code-unit index.
        const s_ascii = s_flat or if (s_cell) |cell| cell.isAscii() else false;
        if (check_protocol and eq(name, "replaceAll"))
            if (try self.replaceAllProtocolDispatch(protocol_receiver orelse try self.stringReceiverValue(s, s_cell), args)) |r| return r;
        // Well-known Symbol method protocol: `split`/`match`/`matchAll`/`search`/
        // `replace`/`replaceAll` first check their first argument for the matching
        // `Symbol.*` method and, if it is callable, delegate to it (with `this` =
        // that argument and the string as the first parameter). RegExp instances
        // use the protocol for methods whose spec algorithms are implemented.
        // Plain methods have no protocol lookup, so they must not materialize a
        // receiver Value at all. Protocol methods retain an existing immutable
        // StringData cell instead of copying its canonical bytes into a new one.
        if (check_protocol and self.stringProtocolSymbol(name) != null)
            if (try self.stringProtocolDispatch(name, protocol_receiver orelse try self.stringReceiverValue(s, s_cell), args)) |r| return r;
        if (eq(name, "charAt")) {
            const pos = try self.stringPosition(s, arg0(args), s_ascii, s_cell) orelse return Value.str("");
            const cu = try self.stringCodeUnitAtAccess(s, pos, s_ascii, s_cell) orelse return Value.str("");
            return try Value.strAlloc(self.arena, try self.stringFromCodeUnit(cu.unit));
        }
        if (eq(name, "charCodeAt")) {
            const pos = try self.stringPosition(s, arg0(args), s_ascii, s_cell) orelse return Value.num(std.math.nan(f64));
            const cu = try self.stringCodeUnitAtAccess(s, pos, s_ascii, s_cell) orelse return Value.num(std.math.nan(f64));
            return Value.num(@floatFromInt(cu.unit));
        }
        if (eq(name, "indexOf")) {
            // ToString(searchString) precedes ToInteger(position), and each runs
            // the argument's valueOf/toString (so an abrupt completion in either
            // propagates in spec order).
            const sub = try self.toStringWtf8(arg0(args));
            // ECMA-262 String.prototype.indexOf steps 5–10: both `start` and
            // StringIndexOf are defined over UTF-16 code units.
            const len = stringLengthForAccess(s, s_ascii, s_cell);
            const start = try self.clampPos(arg(args, 1), len);
            return Value.num(if (try self.stringIndexOfUtf16(s, sub, start, len, s_ascii, s_flat)) |index| @floatFromInt(index) else -1);
        }
        if (eq(name, "includes")) {
            if (try self.isRegExp(arg0(args))) return self.throwError("TypeError", "First argument to String.prototype.includes must not be a regular expression");
            const sub = try self.toStringWtf8(arg0(args));
            // ECMA-262 String.prototype.includes steps 7–10: positions and
            // StringIndexOf operate on UTF-16 code units, not backing bytes.
            const len = stringLengthForAccess(s, s_ascii, s_cell);
            const pos = try self.clampPos(arg(args, 1), len);
            return Value.boolVal((try self.stringIndexOfUtf16(s, sub, pos, len, s_ascii, s_flat)) != null);
        }
        if (eq(name, "startsWith")) {
            if (try self.isRegExp(arg0(args))) return self.throwError("TypeError", "First argument to String.prototype.startsWith must not be a regular expression");
            const sub = try self.toStringWtf8(arg0(args));
            // ECMA-262 String.prototype.startsWith steps 7–15: `start` and the
            // extracted substring are UTF-16 code-unit boundaries.
            const len = stringLengthForAccess(s, s_ascii, s_cell);
            const pos = try self.clampPos(arg(args, 1), len);
            const sub_len = utf16LenOfStringA(sub, stringBytesAreAscii(sub));
            if (sub_len > len - pos) return Value.boolVal(false);
            // On a flat receiver put the needle in the same representation and
            // compare bytes; a needle holding a unit above 0xFF cannot match.
            const sub_flat = if (s_flat) (try self.flatLatin1Needle(sub)) orelse return Value.boolVal(false) else sub;
            return Value.boolVal(stringCodeUnitsEqualAt(s, sub_flat, pos, s_ascii, s_flat));
        }
        if (eq(name, "endsWith")) {
            if (try self.isRegExp(arg0(args))) return self.throwError("TypeError", "First argument to String.prototype.endsWith must not be a regular expression");
            const sub = try self.toStringWtf8(arg0(args));
            // ECMA-262 String.prototype.endsWith steps 7–14: compute the
            // candidate substring entirely in UTF-16 code-unit space.
            const len = stringLengthForAccess(s, s_ascii, s_cell);
            const end_pos = if (args.len > 1 and !args[1].isUndefined()) try self.clampPos(args[1], len) else len;
            const sub_len = utf16LenOfStringA(sub, stringBytesAreAscii(sub));
            if (sub_len > end_pos) return Value.boolVal(false);
            const sub_flat = if (s_flat) (try self.flatLatin1Needle(sub)) orelse return Value.boolVal(false) else sub;
            return Value.boolVal(stringCodeUnitsEqualAt(s, sub_flat, end_pos - sub_len, s_ascii, s_flat));
        }
        if (eq(name, "slice")) {
            const len = stringLengthForAccess(s, s_ascii, s_cell);
            const start = try relIndex(self, arg0(args), len, 0);
            const end = try relIndex(self, arg(args, 1), len, @floatFromInt(len));
            if (start < end) return try Value.strAlloc(self.arena, try self.stringSliceUtf16A(s, start, end, s_flat));
            return Value.str("");
        }
        if (eq(name, "substring")) {
            const len = stringLengthForAccess(s, s_ascii, s_cell);
            var a0 = try self.stringClampPosition(s, arg0(args), 0, s_ascii, s_cell);
            var b0 = try self.stringClampPosition(s, arg(args, 1), len, s_ascii, s_cell);
            if (a0 > b0) {
                const t = a0;
                a0 = b0;
                b0 = t;
            }
            return try Value.strAlloc(self.arena, try self.stringSliceUtf16A(s, a0, b0, s_flat));
        }
        if (eq(name, "toUpperCase") or eq(name, "toLocaleUpperCase")) {
            if (eq(name, "toLocaleUpperCase")) {
                const locs = try canonicalizeLocaleList(self, if (args.len > 0) args[0] else Value.undef());
                const loc = localeListFirstOr(locs, "");
                if (localeIsLithuanian(loc)) return try Value.strAlloc(self.arena, try lithuanianUpper(self, s));
                if (localeIsTurkic(loc)) return try Value.strAlloc(self.arena, try turkicUpper(self, s));
            }
            return try Value.strAlloc(self.arena, try unicode_case.toUpper(self.arena, s));
        }
        if (eq(name, "toLowerCase") or eq(name, "toLocaleLowerCase")) {
            if (eq(name, "toLocaleLowerCase")) {
                const locs = try canonicalizeLocaleList(self, if (args.len > 0) args[0] else Value.undef());
                const loc = localeListFirstOr(locs, "");
                if (localeIsLithuanian(loc)) return try Value.strAlloc(self.arena, try lithuanianLower(self, s));
                if (localeIsTurkic(loc)) return try Value.strAlloc(self.arena, try turkicLower(self, s));
            }
            return try Value.strAlloc(self.arena, try unicode_case.toLower(self.arena, s));
        }
