const en_days_narrow = [_][]const u8{ "S", "M", "T", "W", "T", "F", "S" };

/// Closed metadata set for DateTimeFormat structural output. Keeping the native
/// representation typed makes it impossible to borrow dynamic storage for a
/// result's `type`; the exposed strings are process-lifetime immutable cells.
const DtfPartType = enum {
    weekday,
    era,
    year,
    month,
    day,
    hour,
    minute,
    second,
    fractional_second,
    day_period,
    time_zone_name,
    related_year,
    year_name,
    literal,

    fn isNumeric(self: DtfPartType) bool {
        return switch (self) {
            .year, .month, .day, .hour, .minute, .second, .fractional_second => true,
            else => false,
        };
    }

    fn value(self: DtfPartType) Value {
        return switch (self) {
            .weekday => Value.str("weekday"),
            .era => Value.str("era"),
            .year => Value.str("year"),
            .month => Value.str("month"),
            .day => Value.str("day"),
            .hour => Value.str("hour"),
            .minute => Value.str("minute"),
            .second => Value.str("second"),
            .fractional_second => Value.str("fractionalSecond"),
            .day_period => Value.str("dayPeriod"),
            .time_zone_name => Value.str("timeZoneName"),
            .related_year => Value.str("relatedYear"),
            .year_name => Value.str("yearName"),
            .literal => Value.str("literal"),
        };
    }
};

/// Resolve closed CLDR fragments to process-lifetime cells before result
/// materialization. JavaScript strings are primitives, so reusing one immutable
/// cell for punctuation, names, and day-period labels is unobservable while it
/// avoids manufacturing the same managed cell for every format invocation.
fn dtfStaticPartValue(bytes: []const u8) ?Value {
    inline for (.{
        en_months_long,
        en_months_short,
        en_months_narrow,
        en_islamic_months_long,
        en_hebrew_common_months,
        en_hebrew_leap_months,
        en_days_long,
        en_days_short,
        en_days_narrow,
    }) |candidates| inline for (candidates) |candidate|
        if (std.mem.eql(u8, bytes, candidate)) return Value.str(candidate);

    inline for ([_][]const u8{
        ", ",           " ",             ".",             "/",                          " at ",                           ":",              "\xd9\xab",    "\u{5e74}",
        "AM",           "PM",            "noon",          "in the morning",             "in the afternoon",               "in the evening", "at night",    "n",
        "UTC",          "GMT",           "GMT+1",         "Coordinated Universal Time", "Central European Standard Time", "BE",             "Anno Domini", "AD",
        "A",            "Before Christ", "BC",            "B",                          "Reiwa",                          "R",              "Heisei",      "H",
        "Sh\u{014d}wa", "S",             "Taish\u{014d}", "T",                          "Meiji",                          "M",
    }) |candidate| if (std.mem.eql(u8, bytes, candidate)) return Value.str(candidate);
    return null;
}

/// One element of a DateTimeFormat formatToParts result: an immutable field,
/// its invocation-owned bytes, and an optional allocation-free publication
/// value when those bytes belong to the closed metadata set above.
const DtfPart = struct {
    typ: DtfPartType,
    value: []const u8,
    static_value: ?Value,

    fn materialize(self: DtfPart, allocator: std.mem.Allocator) EvalError!Value {
        return self.static_value orelse try Value.strAlloc(allocator, self.value);
    }
};

/// The DateTimeFormat pattern has eleven component slots plus their separators,
/// with Chinese related-year/year-name expansion as its widest date field. The
/// closed emitter therefore tops out below 24 parts. Keep that common and
/// specification-bounded structure in the native frame; an unexpected future
/// emitter expansion fails closed instead of turning a formatter into an
/// input-sized stack allocation.
const DtfParts = struct {
    const capacity = 24;

    storage: [capacity]DtfPart = undefined,
    len: usize = 0,

    fn append(self: *DtfParts, interpreter: *Interpreter, part: DtfPart) EvalError!void {
        if (self.len == capacity)
            return interpreter.throwError("InternalError", "DateTimeFormat structural part bound exceeded");
        self.storage[self.len] = part;
        self.len += 1;
    }

    fn items(self: *const DtfParts) []const DtfPart {
        return self.storage[0..self.len];
    }
};

const DtfOutput = struct {
    mode: enum { text, parts },
    text: std.ArrayListUnmanaged(u8) = .empty,
    /// Present only for the structural sink. Keeping the fixed buffer in its
    /// caller avoids adding it to the dominant text-only formatter frame.
    parts: ?*DtfParts = null,
    /// Structural output is invocation-local. Callers keep this allocator alive
    /// through range comparison and managed result materialization.
    scratch: ?std.mem.Allocator = null,
    numbering_system: []const u8 = "latn",
    part_count: usize = 0,

    fn storageAllocator(self: *const DtfOutput, interpreter: *Interpreter) std.mem.Allocator {
        return self.scratch orelse interpreter.arena;
    }

    fn push(self: *DtfOutput, interpreter: *Interpreter, typ: DtfPartType, bytes: []const u8) EvalError!void {
        const digit_set = if (typ.isNumeric() and !std.mem.eql(u8, self.numbering_system, "latn"))
            numbering_systems.digits(self.numbering_system)
        else
            null;
        switch (self.mode) {
            .text => if (digit_set) |digits| {
                for (bytes) |byte| {
                    if (byte >= '0' and byte <= '9')
                        try self.text.appendSlice(interpreter.arena, numbering_systems.nth(digits, byte - '0'))
                    else
                        try self.text.append(interpreter.arena, byte);
                }
            } else {
                try self.text.appendSlice(interpreter.arena, bytes);
            },
            .parts => {
                const value_bytes = if (digit_set) |digits| try translateDigitsAlloc(self.storageAllocator(interpreter), bytes, digits) else bytes;
                try self.parts.?.append(interpreter, .{
                    .typ = typ,
                    .value = value_bytes,
                    .static_value = if (digit_set == null) dtfStaticPartValue(value_bytes) else null,
                });
            },
        }
        self.part_count += 1;
    }

    /// `bytes` may point into a caller-owned stack buffer. The text sink consumes
    /// it immediately; the structural sink gives the part arena-backed storage.
    fn pushCopied(self: *DtfOutput, interpreter: *Interpreter, typ: DtfPartType, bytes: []const u8) EvalError!void {
        const translates = typ.isNumeric() and !std.mem.eql(u8, self.numbering_system, "latn") and
            numbering_systems.digits(self.numbering_system) != null;
        if (self.mode == .parts and !translates)
            return self.push(interpreter, typ, try self.storageAllocator(interpreter).dupe(u8, bytes));
        return self.push(interpreter, typ, bytes);
    }

    fn pushInt(self: *DtfOutput, interpreter: *Interpreter, typ: DtfPartType, v: anytype, two: bool) EvalError!void {
        var scratch: [32]u8 = undefined;
        const bytes = if (two)
            std.fmt.bufPrint(&scratch, "{d:0>2}", .{v}) catch unreachable
        else
            std.fmt.bufPrint(&scratch, "{d}", .{v}) catch unreachable;
        try self.pushCopied(interpreter, typ, bytes);
    }
};

fn dtfTimeZoneOffsetMs(this: Value, epoch_ms: f64) i64 {
    const data = this.asObj().intlDateTimeFormatData() orelse return 0;
    const s = data.time_zone;
    if (std.mem.startsWith(u8, s, "Etc/GMT+") or std.mem.startsWith(u8, s, "Etc/GMT-")) {
        const sign_ch = s["Etc/GMT".len];
        const hours = std.fmt.parseInt(i64, s["Etc/GMT+".len..], 10) catch return 0;
        if (hours == 0) return 0;
        const sign: i64 = if (sign_ch == '+') -1 else 1;
        return sign * hours * 60 * 60_000;
    }
    const epoch_ns: i128 = @as(i128, @intFromFloat(@trunc(epoch_ms))) * 1_000_000;
    if (s.len != 6 or (s[0] != '+' and s[0] != '-') or s[3] != ':')
        return @intCast(@divTrunc(timeZoneOffsetAtEpoch(s, epoch_ns, 0), 1_000_000));
    const hh = std.fmt.parseInt(i64, s[1..3], 10) catch return 0;
    const mm = std.fmt.parseInt(i64, s[4..6], 10) catch return 0;
    const sign: i64 = if (s[0] == '-') -1 else 1;
    const fallback = sign * (hh * 60 + mm) * 60_000;
    return @intCast(@divTrunc(timeZoneOffsetAtEpoch(s, epoch_ns, fallback * 1_000_000), 1_000_000));
}

/// The English era name for a calendar's raw era, per era width (long/short/
/// narrow). Gregorian ce/bce and the modern Japanese eras have distinct widths;
/// the Buddhist era is "BE" throughout.
fn dtfEraName(cal: []const u8, raw: []const u8, width: []const u8) []const u8 {
    const long = std.mem.eql(u8, width, "long");
    const narrow = std.mem.eql(u8, width, "narrow");
    if (asciiEqlIgnoreCase(cal, "buddhist")) return "BE";
    if (asciiEqlIgnoreCase(raw, "ce")) return if (long) "Anno Domini" else if (narrow) "A" else "AD";
    if (asciiEqlIgnoreCase(raw, "bce")) return if (long) "Before Christ" else if (narrow) "B" else "BC";
    const Jp = struct { k: []const u8, name: []const u8, n: []const u8 };
    const jp = [_]Jp{
        .{ .k = "reiwa", .name = "Reiwa", .n = "R" },
        .{ .k = "heisei", .name = "Heisei", .n = "H" },
        .{ .k = "showa", .name = "Sh\u{014d}wa", .n = "S" },
        .{ .k = "taisho", .name = "Taish\u{014d}", .n = "T" },
        .{ .k = "meiji", .name = "Meiji", .n = "M" },
    };
    for (jp) |j| if (asciiEqlIgnoreCase(raw, j.k)) return if (narrow) j.n else j.name;
    return raw;
}
fn dtfMonthName(cal: []const u8, month: u8, width: []const u8) ?[]const u8 {
    if (month < 1 or month > 12) return null;
    const idx = month - 1;
    if (std.mem.startsWith(u8, cal, "islamic"))
        return en_islamic_months_long[idx];
    return if (eq(width, "narrow")) en_months_narrow[idx] else if (eq(width, "short")) en_months_short[idx] else en_months_long[idx];
}

fn dtfOffsetZoneName(allocator: std.mem.Allocator, off_ns: i64) EvalError![]const u8 {
    if (off_ns == 0) return "GMT";
    const neg = off_ns < 0;
    var v: u64 = @intCast(if (neg) -off_ns else off_ns);
    const hh = v / 3_600_000_000_000;
    v %= 3_600_000_000_000;
    const mm = v / 60_000_000_000;
    if (mm == 0) return std.fmt.allocPrint(allocator, "GMT{s}{d}", .{ if (neg) "-" else "+", hh });
    return std.fmt.allocPrint(allocator, "GMT{s}{d}:{d:0>2}", .{ if (neg) "-" else "+", hh, mm });
}

fn dtfTimeZoneName(allocator: std.mem.Allocator, name: []const u8, off_ns: i64, width: []const u8) EvalError![]const u8 {
    if (std.mem.eql(u8, name, "UTC")) {
        return if (eq(width, "long") or eq(width, "longGeneric")) "Coordinated Universal Time" else "UTC";
    }
    if (name.len > 0 and (name[0] == '+' or name[0] == '-')) return dtfOffsetZoneName(allocator, off_ns);
    if (std.mem.eql(u8, name, "Europe/Vienna")) {
        return if (eq(width, "long") or eq(width, "longGeneric")) "Central European Standard Time" else "GMT+1";
    }
    if (std.mem.eql(u8, name, "Europe/Berlin")) {
        return if (eq(width, "long") or eq(width, "longGeneric")) "Central European Standard Time" else "GMT+1";
    }
    return if (eq(width, "long") or eq(width, "longGeneric")) "Coordinated Universal Time" else "UTC";
}

fn dtfChineseYearName(allocator: std.mem.Allocator, year: i64) EvalError![]const u8 {
    const stems = [_][]const u8{ "\u{7532}", "\u{4e59}", "\u{4e19}", "\u{4e01}", "\u{620a}", "\u{5df1}", "\u{5e9a}", "\u{8f9b}", "\u{58ec}", "\u{7678}" };
    const branches = [_][]const u8{ "\u{5b50}", "\u{4e11}", "\u{5bc5}", "\u{536f}", "\u{8fb0}", "\u{5df3}", "\u{5348}", "\u{672a}", "\u{7533}", "\u{9149}", "\u{620c}", "\u{4ea5}" };
    const offset = year - 4;
    return std.fmt.allocPrint(allocator, "{s}{s}", .{ stems[@intCast(@mod(offset, 10))], branches[@intCast(@mod(offset, 12))] });
}

fn dtfAppendYearPart(self: *Interpreter, output: *DtfOutput, cal: []const u8, display_year: i64, fmt: []const u8) EvalError!void {
    const two = std.mem.eql(u8, fmt, "2-digit");
    if (std.mem.eql(u8, cal, "chinese") or std.mem.eql(u8, cal, "dangi")) {
        if (two)
            try output.pushInt(self, .related_year, @as(u8, @intCast(@mod(display_year, 100))), true)
        else
            try output.pushInt(self, .related_year, display_year, false);
        try output.push(self, .year_name, try dtfChineseYearName(output.storageAllocator(self), display_year));
        try output.push(self, .literal, "\u{5e74}");
        return;
    }
    if (two)
        try output.pushInt(self, .year, @as(u8, @intCast(@mod(display_year, 100))), true)
    else
        try output.pushInt(self, .year, display_year, false);
}

fn dtfAppendMonthPart(self: *Interpreter, output: *DtfOutput, cal: []const u8, year: i64, month: u8, fmt: []const u8) EvalError!void {
    if (std.mem.eql(u8, cal, "hebrew")) {
        const names = if (calInLeapYear(cal, year)) &en_hebrew_leap_months else &en_hebrew_common_months;
        if (month >= 1 and month <= names.len) {
            try output.push(self, .month, names[month - 1]);
            return;
        }
    }
    if (std.mem.eql(u8, cal, "chinese") or std.mem.eql(u8, cal, "dangi")) {
        const info = calMonthCodeInfo(cal, year, month);
        const two = eq(fmt, "2-digit");
        if (!info.leap) return output.pushInt(self, .month, info.month, two);
        var scratch: [32]u8 = undefined;
        const s = if (two)
            std.fmt.bufPrint(&scratch, "{d:0>2}bis", .{info.month}) catch unreachable
        else
            std.fmt.bufPrint(&scratch, "{d}bis", .{info.month}) catch unreachable;
        try output.pushCopied(self, .month, s);
        return;
    }
    try output.pushInt(self, .month, month, eq(fmt, "2-digit"));
}

/// Run the DateTimeFormat emission algorithm once. The text sink appends into
/// the returned string without materializing structural parts; the parts sink
/// preserves exact boundaries for formatToParts and range formatting.
fn dtfBuildOutput(self: *Interpreter, this: Value, args: []const Value, output: *DtfOutput) value.HostError!void {
    // Construction publishes the complete immutable record before the object is
    // observable. Reject a non-branded direct caller before converting its
    // attacker-controlled value argument.
    const data = this.asObj().intlDateTimeFormatData() orelse
        return self.throwError("TypeError", "Intl.DateTimeFormat has no resolved state");
    // The value to format. A Temporal PlainDate/Time/DateTime/YearMonth/MonthDay
    // supplies its ISO fields directly (no TimeClip — its range exceeds Date's);
    // an Instant uses its epoch nanoseconds; everything else is a TimeClip'd time
    // value. `temporal_kind` (when set) restricts which components may be shown.
    var temporal_kind: ?value.TemporalData.Kind = null;
    var temporal_calendar: []const u8 = "iso8601";
    var temporal_tz_name: []const u8 = "UTC";
    var temporal_tz_offset_ns: i64 = 0;
    var civ: Civil = .{ .y = 1970, .m = 1, .d = 1 };
    var hour24: u8 = 0;
    var minute: u8 = 0;
    var second: u8 = 0;
    var frac_ms: u32 = 0;
    {
        const t_obj: ?*value.TemporalData = if (args.len > 0 and args[0].isObject()) args[0].asObj().temporalData() else null;
        const direct = t_obj != null and switch (t_obj.?.kind) {
            .plain_date, .plain_time, .plain_date_time, .plain_year_month, .plain_month_day, .zoned_date_time => true,
            else => false,
        };
        if (direct) {
            const t = t_obj.?;
            if (t.kind == .zoned_date_time and !data.allow_temporal_zoned_date_time)
                return self.throwError("TypeError", "Intl.DateTimeFormat does not support Temporal.ZonedDateTime");
            temporal_kind = t.kind;
            temporal_calendar = t.calendar;
            if (t.kind == .zoned_date_time) {
                temporal_tz_name = t.tz_name;
                temporal_tz_offset_ns = timeZoneOffsetAtEpoch(t.tz_name, t.epoch_ns, t.tz_offset_ns);
                const local_ns = t.epoch_ns + @as(i128, temporal_tz_offset_ns);
                const days = @divFloor(local_ns, 86_400_000_000_000);
                const iso = tCivilFromDays(@intCast(days));
                const cal = calendarDateFromIso(t.calendar, iso.y, iso.m, iso.d);
                civ = .{ .y = cal.y, .m = cal.m, .d = cal.d };
                hour24 = @intCast(@divFloor(@mod(local_ns, 86_400_000_000_000), 3_600_000_000_000));
                minute = @intCast(@divFloor(@mod(local_ns, 3_600_000_000_000), 60_000_000_000));
                second = @intCast(@divFloor(@mod(local_ns, 60_000_000_000), 1_000_000_000));
                frac_ms = @intCast(@divFloor(@mod(local_ns, 1_000_000_000), 1_000_000));
            } else if (t.kind == .plain_month_day) {
                const cal = calendarDateFromIso(t.calendar, t.year, t.month, t.day);
                civ = .{ .y = cal.y, .m = cal.m, .d = cal.d };
                hour24 = t.hour;
                minute = t.minute;
                second = t.second;
                frac_ms = t.millisecond;
            } else {
                civ = .{ .y = @as(i64, t.year), .m = t.month, .d = t.day };
                hour24 = t.hour;
                minute = t.minute;
                second = t.second;
                frac_ms = t.millisecond;
            }
        } else {
            const is_instant = t_obj != null and t_obj.?.kind == .instant;
            if (is_instant) temporal_kind = .instant;
            const ms: f64 = if (is_instant)
                @as(f64, @floatFromInt(@divFloor(t_obj.?.epoch_ns, 1_000_000)))
            else if (args.len == 0 or args[0].isUndefined())
                0
            else
                try self.toNumberV(args[0]);
            if (std.math.isNan(ms) or @abs(ms) > 8.64e15) return self.throwError("RangeError", "Invalid time value");
            const day_ms: i64 = 86_400_000;
            const total_ms: i64 = @intFromFloat(@trunc(ms + @as(f64, @floatFromInt(dtfTimeZoneOffsetMs(this, ms)))));
            const epoch_days = @divFloor(total_ms, day_ms);
            var tod = @mod(total_ms, day_ms);
            if (tod < 0) tod += day_ms;
            civ = tCivilFromDays(epoch_days);
            hour24 = @intCast(@divFloor(tod, 3_600_000));
            minute = @intCast(@divFloor(@mod(tod, 3_600_000), 60_000));
            second = @intCast(@divFloor(@mod(tod, 60_000), 1000));
            frac_ms = @intCast(@mod(tod, 1000));
        }
    }
    const wday = isoDayOfWeek(civ.y, civ.m, civ.d) % 7; // 0=Sun..6=Sat

    // Constructor resolution publishes immutable native state. No user or
    // internal ordinary property lookup occurs on a steady consumer call.
    var o_weekday = data.weekday.string();
    var o_era = data.era.string();
    var o_year = data.year.string();
    var o_month = data.month.string();
    var o_day = data.day.string();
    var o_hour = data.hour.string();
    var o_minute = data.minute.string();
    var o_second = data.second.string();
    var o_frac: usize = data.fractional_second_digits;
    var o_day_period = data.day_period.field().string();
    var o_tzname = data.time_zone_name.string();
    const o_calendar = data.calendar;
    var hour12 = data.hour12;
    var hour_cycle = data.hour_cycle.string();
    var any_comp = o_weekday.len + o_era.len + o_year.len + o_month.len + o_day.len + o_hour.len + o_minute.len + o_second.len + o_day_period.len + o_tzname.len + o_frac > 0;
    const defaults_applied = data.defaults_applied;
    const explicit_hour_setting = data.hour_cycle != .none;
    if (!any_comp) {
        o_year = "numeric";
        o_month = "numeric";
        o_day = "numeric";
    }
    const requested_era = o_era;
    const requested_tzname = o_tzname;
    if (defaults_applied) if (temporal_kind) |tk| {
        o_weekday = "";
        o_era = "";
        o_year = "";
        o_month = "";
        o_day = "";
        o_hour = "";
        o_minute = "";
        o_second = "";
        o_frac = 0;
        o_day_period = "";
        o_tzname = "";
        switch (tk) {
            .plain_date => {
                o_era = requested_era;
                o_year = "numeric";
                o_month = "numeric";
                o_day = "numeric";
            },
            .plain_date_time, .instant => {
                o_era = requested_era;
                o_year = "numeric";
                o_month = "numeric";
                o_day = "numeric";
                o_hour = "numeric";
                o_minute = "numeric";
                o_second = "numeric";
                if (tk == .instant and requested_tzname.len > 0) o_tzname = requested_tzname;
            },
            .plain_time => {
                o_hour = "numeric";
                o_minute = "numeric";
                o_second = "numeric";
            },
            .zoned_date_time => {
                o_era = requested_era;
                o_year = "numeric";
                o_month = "numeric";
                o_day = "numeric";
                o_hour = "numeric";
                o_minute = "numeric";
                o_second = "numeric";
                o_tzname = if (requested_tzname.len > 0) requested_tzname else "short";
            },
            .plain_year_month => {
                o_era = requested_era;
                o_year = "numeric";
                o_month = "numeric";
            },
            .plain_month_day => {
                o_month = "numeric";
                o_day = "numeric";
            },
            else => {},
        }
        any_comp = true;
    };
    if (temporal_kind != null and !explicit_hour_setting and o_hour.len > 0) {
        hour_cycle = try dtfResolveHourCycle(self, data.locale, hour_cycle, null);
        hour12 = std.mem.eql(u8, hour_cycle, "h11") or std.mem.eql(u8, hour_cycle, "h12");
    }
    if (temporal_kind == null or temporal_kind.? == .instant) {
        civ = calendarDateFromIso(o_calendar, civ.y, civ.m, civ.d);
    }

    // Restrict the components to those the Temporal value's type can provide; a
    // requested component the type lacks is dropped, and if NOTHING the formatter
    // wants overlaps the value's data model it is a TypeError.
    if (temporal_kind) |tk| {
        const has_date = tk == .plain_date or tk == .plain_date_time or tk == .instant or tk == .zoned_date_time;
        const has_time = tk == .plain_time or tk == .plain_date_time or tk == .instant or tk == .zoned_date_time;
        const a_year = has_date or tk == .plain_year_month;
        const a_month = has_date or tk == .plain_year_month or tk == .plain_month_day;
        const a_day = has_date or tk == .plain_month_day;
        const a_tz = tk == .instant or tk == .zoned_date_time;
        var req = false;
        var kept = false;
        const F = struct {
            fn f(ok: bool, slot: *[]const u8, r: *bool, k: *bool) void {
                if (slot.len == 0) return;
                r.* = true;
                if (ok) k.* = true else slot.* = "";
            }
        }.f;
        F(a_year, &o_year, &req, &kept);
        F(a_year, &o_era, &req, &kept);
        F(a_month, &o_month, &req, &kept);
        F(a_day, &o_day, &req, &kept);
        F(has_date, &o_weekday, &req, &kept);
        F(has_time, &o_hour, &req, &kept);
        F(has_time, &o_minute, &req, &kept);
        F(has_time, &o_second, &req, &kept);
        F(has_time, &o_day_period, &req, &kept);
        F(a_tz, &o_tzname, &req, &kept);
        if (o_frac > 0) {
            req = true;
            if (has_time) kept = true else o_frac = 0;
        }
        if (req and !kept) return self.throwError("TypeError", "Intl.DateTimeFormat: options do not overlap the Temporal value's fields");
    }

    const numbering_system = data.numbering_system;
    const dtf_locale = data.locale;
    output.numbering_system = numbering_system;

    const P = struct {
        fn lit(s: *Interpreter, out: *DtfOutput, v: []const u8) EvalError!void {
            try out.push(s, .literal, v);
        }
        fn num(s: *Interpreter, out: *DtfOutput, typ: DtfPartType, v: u64, two: bool) EvalError!void {
            try out.pushInt(s, typ, v, two);
        }
    };

    // Weekday prefix.
    if (o_weekday.len > 0) {
        const name = if (eq(o_weekday, "narrow")) en_days_narrow[wday] else if (eq(o_weekday, "short")) en_days_short[wday] else en_days_long[wday];
        try output.push(self, .weekday, name);
    }
    // Date part. Numeric month → "M/D/YYYY"; long/short month → "Month D, YYYY".
    const have_date = o_year.len > 0 or o_month.len > 0 or o_day.len > 0;
    if (have_date) {
        const era_info = calEraOf(o_calendar, civ.y, civ.m, civ.d);
        const use_era_year = era_info.era != null and (o_era.len > 0 or std.mem.eql(u8, o_calendar, "japanese"));
        const display_year = if (use_era_year) era_info.era_year else civ.y;
        if (output.part_count > 0) try P.lit(self, output, ", ");
        const month_textual = o_month.len > 0 and !eq(o_month, "numeric") and !eq(o_month, "2-digit");
        const part_calendar = if (std.mem.eql(u8, temporal_calendar, "iso8601")) o_calendar else temporal_calendar;
        if (month_textual) {
            const mn = dtfMonthName(part_calendar, civ.m, o_month);
            if (mn) |name|
                try output.push(self, .month, name)
            else
                try output.pushInt(self, .month, civ.m, false);
            if (o_day.len > 0) {
                try P.lit(self, output, " ");
                try P.num(self, output, .day, civ.d, false);
            }
            if (o_year.len > 0) {
                // "Month Day, Year" but "Month Year" when there is no day.
                try P.lit(self, output, if (o_day.len > 0) ", " else " ");
                try dtfAppendYearPart(self, output, part_calendar, display_year, o_year);
            }
        } else if (std.mem.eql(u8, parseTriple(dtf_locale).l, "de")) {
            // German numeric dates are day.month.year, and ECMA-402 internal
            // formatting must not observe user changes to String.prototype.split.
            var first = true;
            if (o_day.len > 0) {
                try P.num(self, output, .day, civ.d, eq(o_day, "2-digit"));
                first = false;
            }
            if (o_month.len > 0) {
                if (!first) try P.lit(self, output, ".");
                first = false;
                try dtfAppendMonthPart(self, output, part_calendar, civ.y, civ.m, o_month);
            }
            if (o_year.len > 0) {
                if (!first) try P.lit(self, output, ".");
                first = false;
                try dtfAppendYearPart(self, output, part_calendar, display_year, o_year);
            }
        } else {
            // All-numeric "M/D/Y" (only the requested parts, slash-separated).
            var first = true;
            if (o_month.len > 0) {
                try dtfAppendMonthPart(self, output, part_calendar, civ.y, civ.m, o_month);
                first = false;
            }
            if (o_day.len > 0) {
                if (!first) try P.lit(self, output, "/");
                first = false;
                try P.num(self, output, .day, civ.d, eq(o_day, "2-digit"));
            }
            if (o_year.len > 0) {
                if (!first) try P.lit(self, output, "/");
                first = false;
                try dtfAppendYearPart(self, output, part_calendar, display_year, o_year);
            }
        }
        if (o_era.len > 0) if (era_info.era) |raw_era| {
            try P.lit(self, output, " ");
            try output.push(self, .era, dtfEraName(part_calendar, raw_era, o_era));
        };
    }
    // Time part: "h:mm:ss AM/PM" (or 24-hour).
    const have_clock = o_hour.len > 0 or o_minute.len > 0 or o_second.len > 0;
    const have_time = have_clock or o_day_period.len > 0 or o_tzname.len > 0;
    if (have_time) {
        // CLDR dateTime connector: a long month uses " at "; a weekday-only date
        // uses a plain space; otherwise ", ".
        const dtsep: []const u8 = if (std.mem.eql(u8, o_month, "long"))
            " at "
        else if (o_weekday.len > 0 and o_year.len == 0 and o_month.len == 0 and o_day.len == 0)
            " "
        else
            ", ";
        if (output.part_count > 0) try P.lit(self, output, dtsep);
        var h = hour24;
        var ap: []const u8 = "";
        if (o_day_period.len > 0) {
            ap = if (data.day_period.isFlexible())
                enDayPeriod(hour24, o_day_period)
            else if (h < 12) "AM" else "PM";
        } else if (temporal_kind != null and hour12 and o_hour.len > 0) {
            ap = if (h < 12) "AM" else "PM";
        }
        if (hour12 and o_hour.len > 0) {
            h = h % 12;
            if (h == 0 and !std.mem.eql(u8, hour_cycle, "h11")) h = 12;
        } else if (std.mem.eql(u8, hour_cycle, "h24") and o_hour.len > 0 and h == 0) {
            h = 24;
        }
        const two_hour = eq(o_hour, "2-digit") or (temporal_kind != null and !hour12 and h < 10);
        if (o_hour.len > 0) try P.num(self, output, .hour, h, two_hour);
        if (o_minute.len > 0) {
            if (o_hour.len > 0) try P.lit(self, output, ":");
            try P.num(self, output, .minute, minute, eq(o_minute, "2-digit") or (temporal_kind != null and o_hour.len > 0));
        }
        if (o_second.len > 0) {
            if (o_hour.len > 0 or o_minute.len > 0) try P.lit(self, output, ":");
            try P.num(self, output, .second, second, eq(o_second, "2-digit") or (temporal_kind != null and o_hour.len > 0));
        }
        // fractionalSecondDigits: the first N digits of the millisecond (the
        // sub-second is truncated, not rounded), after the seconds.
        if (o_frac > 0 and o_second.len > 0) {
            var mbuf: [3]u8 = .{ '0', '0', '0' };
            _ = std.fmt.bufPrint(&mbuf, "{d:0>3}", .{frac_ms}) catch {};
            const frac_sep = if (std.mem.eql(u8, numbering_system, "arab") or std.mem.eql(u8, numbering_system, "arabext")) "\xd9\xab" else ".";
            try P.lit(self, output, frac_sep);
            try output.pushCopied(self, .fractional_second, mbuf[0..o_frac]);
        }
        if (ap.len > 0) {
            if (have_clock) try P.lit(self, output, " ");
            try output.push(self, .day_period, ap);
        }
        if (o_tzname.len > 0) {
            const tzn: []const u8 = if (temporal_kind != null and temporal_kind.? == .zoned_date_time)
                try dtfTimeZoneName(output.storageAllocator(self), temporal_tz_name, temporal_tz_offset_ns, o_tzname)
            else if (eq(o_tzname, "long"))
                "Coordinated Universal Time"
            else if (eq(o_tzname, "longOffset") or eq(o_tzname, "shortOffset"))
                "GMT"
            else if (eq(o_tzname, "longGeneric"))
                "Coordinated Universal Time"
            else
                "UTC"; // "short", "shortGeneric"
            if (have_clock or ap.len > 0) try P.lit(self, output, " ");
            try output.push(self, .time_zone_name, tzn);
        }
    }
}

fn dtfBuildParts(self: *Interpreter, this: Value, args: []const Value, scratch: std.mem.Allocator) value.HostError!DtfParts {
    var parts = DtfParts{};
    var output = DtfOutput{ .mode = .parts, .parts = &parts, .scratch = scratch };
    try dtfBuildOutput(self, this, args, &output);
    return parts;
}

fn dtfBuildText(self: *Interpreter, this: Value, args: []const Value) value.HostError![]u8 {
    var output = DtfOutput{ .mode = .text };
    try dtfBuildOutput(self, this, args, &output);
    return output.text.toOwnedSlice(self.arena);
}

/// en flexible day period for an hour. Per CLDR's *format* dayPeriodRules:
/// noon at 12 (any minute), morning 00–11, afternoon 13–17, evening 18–20, else
/// night (21–23). ("n" is narrow noon; the other periods have no narrow form.)
fn enDayPeriod(h: u8, width: []const u8) []const u8 {
    if (h == 12) return if (std.mem.eql(u8, width, "narrow")) "n" else "noon";
    if (h < 12) return "in the morning";
    if (h >= 13 and h < 18) return "in the afternoon";
    if (h >= 18 and h < 21) return "in the evening";
    return "at night";
}

fn intlDateTimeFormatFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!intlBrandOk(this, "DateTimeFormat")) return self.throwError("TypeError", "Intl.DateTimeFormat.prototype.format on incompatible receiver");
    return try Value.strOwned(self.arena, try dtfBuildText(self, this, args));
}

fn intlDateTimeFormatToPartsFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!intlBrandOk(this, "DateTimeFormat")) return self.throwError("TypeError", "Intl.DateTimeFormat.prototype.formatToParts on incompatible receiver");
    var scratch = std.heap.ArenaAllocator.init(self.scratch_allocator orelse gc_mod.temporaryAllocator(self.arena));
    defer scratch.deinit();
    const parts = try dtfBuildParts(self, this, args, scratch.allocator());
    const arr = (try self.newArray()).asObj();
    for (parts.items()) |p| {
        const o = (try self.newObject()).asObj();
        try self.setProp(o, "type", p.typ.value());
        try self.setProp(o, "value", try p.materialize(self.arena));
        try arr.appendElement(self.arena, Value.obj(o));
    }
    return Value.obj(arr);
}

/// Range separator shared by DateTimeFormat formatRange/formatRangeToParts.
/// CLDR uses a thin space (U+2009) on both sides of the en dash (U+2013) across
/// locales (en/de/fr/… all agree), matching ICU/Node.
const dtf_range_sep = "\u{2009}\u{2013}\u{2009}";

/// Like part types, range sources are specification-owned immutable metadata.
/// The enum keeps dynamic formatted bytes out of the static string-cell path.
const IntlRangeSource = enum {
    shared,
    start_range,
    end_range,

    fn value(self: IntlRangeSource) Value {
        return switch (self) {
            .shared => Value.str("shared"),
            .start_range => Value.str("startRange"),
            .end_range => Value.str("endRange"),
        };
    }
};

/// The "kind" of a formatRange argument: a Temporal kind, or null for a legacy
/// time value (number/Date). The two arguments of formatRange must agree.
fn dtfArgKind(v: Value) ?value.TemporalData.Kind {
    if (v.isObject() and v.asObj().temporalData() != null) return v.asObj().temporalData().?.kind;
    return null;
}

/// FormatDateTimeRange step: the two arguments must be the same kind (both legacy
/// time values, or the same Temporal type) — otherwise a TypeError.
fn dtfRangeCheckKinds(self: *Interpreter, a: Value, b: Value) value.HostError!void {
    const ka = dtfArgKind(a);
    const kb = dtfArgKind(b);
    const same = (ka == null and kb == null) or (ka != null and kb != null and ka.? == kb.?);
    if (!same) return self.throwError("TypeError", "Intl.DateTimeFormat range: start and end must be the same type");
    if (ka != null and a.isObject() and b.isObject()) {
        const ta = a.asObj().temporalData() orelse return;
        const tb = b.asObj().temporalData() orelse return;
        if (temporalCarriesCalendar(ta) and !std.mem.eql(u8, ta.calendar, tb.calendar))
            return self.throwError("RangeError", "Intl.DateTimeFormat range: start and end calendars must match");
    }
}

fn dtfToDateTimeFormattable(self: *Interpreter, v: Value) value.HostError!Value {
    if (dtfArgKind(v) != null) return v;
    return Value.num(try self.toNumberV(v));
}

/// An identical canonical formattable needs only one FormatDateTime call. Both
/// user arguments have already been converted in order before this check. A
/// distinct Temporal object deliberately stays on the structural comparison
/// path even when its fields happen to be equal.
fn dtfFormattableSame(a: Value, b: Value) bool {
    if (a.isNumber() and b.isNumber()) return a.asNum() == b.asNum();
    return a.isObject() and b.isObject() and a.asObj() == b.asObj() and dtfArgKind(a) != null;
}

fn dtfAppendPartValues(self: *Interpreter, buf: *std.ArrayListUnmanaged(u8), parts: []const DtfPart) EvalError!void {
    for (parts) |p| try buf.appendSlice(self.arena, p.value);
}

fn dtfPartsSameValues(xp: []const DtfPart, yp: []const DtfPart) bool {
    if (xp.len != yp.len) return false;
    for (xp, 0..) |p, i| {
        if (!std.mem.eql(u8, p.value, yp[i].value)) return false;
    }
    return true;
}

fn dtfSharedDateTimePrefixLen(xp: []const DtfPart, yp: []const DtfPart) usize {
    const n = @min(xp.len, yp.len);
    var i: usize = 0;
    while (i < n) : (i += 1) {
        const a = xp[i];
        const b = yp[i];
        if (a.typ != b.typ or !std.mem.eql(u8, a.value, b.value)) break;
        if (a.typ == .literal and std.mem.eql(u8, a.value, ", ")) return i + 1;
    }
    return 0;
}

fn dtfIsTextualDateOnly(parts: []const DtfPart) bool {
    return parts.len == 5 and
        parts[0].typ == .month and
        parts[1].typ == .literal and std.mem.eql(u8, parts[1].value, " ") and
        parts[2].typ == .day and
        parts[3].typ == .literal and std.mem.eql(u8, parts[3].value, ", ") and
        parts[4].typ == .year;
}

fn dtfAppendTextualDateRangeText(self: *Interpreter, buf: *std.ArrayListUnmanaged(u8), xp: []const DtfPart, yp: []const DtfPart) EvalError!bool {
    if (!dtfIsTextualDateOnly(xp) or !dtfIsTextualDateOnly(yp)) return false;
    if (!std.mem.eql(u8, xp[4].value, yp[4].value)) return false;
    if (std.mem.eql(u8, xp[0].value, yp[0].value)) {
        try dtfAppendPartValues(self, buf, xp[0..3]);
        try buf.appendSlice(self.arena, dtf_range_sep);
        try buf.appendSlice(self.arena, yp[2].value);
        try dtfAppendPartValues(self, buf, xp[3..5]);
    } else {
        try dtfAppendPartValues(self, buf, xp[0..3]);
        try buf.appendSlice(self.arena, dtf_range_sep);
        try dtfAppendPartValues(self, buf, yp[0..3]);
        try dtfAppendPartValues(self, buf, xp[3..5]);
    }
    return true;
}

fn dtfFormatRangePartsText(self: *Interpreter, xp: []const DtfPart, yp: []const DtfPart) EvalError![]const u8 {
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    if (dtfPartsSameValues(xp, yp)) {
        try dtfAppendPartValues(self, &buf, xp);
        return buf.toOwnedSlice(self.arena);
    }
    if (try dtfAppendTextualDateRangeText(self, &buf, xp, yp))
        return buf.toOwnedSlice(self.arena);
    if (dtfIsTextualDateOnly(xp) and dtfIsTextualDateOnly(yp)) {
        try dtfAppendPartValues(self, &buf, xp);
        try buf.appendSlice(self.arena, dtf_range_sep);
        try dtfAppendPartValues(self, &buf, yp);
        return buf.toOwnedSlice(self.arena);
    }
    const shared_prefix = dtfSharedDateTimePrefixLen(xp, yp);
    if (shared_prefix > 0) {
        try dtfAppendPartValues(self, &buf, xp[0..shared_prefix]);
        try dtfAppendPartValues(self, &buf, xp[shared_prefix..]);
        try buf.appendSlice(self.arena, dtf_range_sep);
        try dtfAppendPartValues(self, &buf, yp[shared_prefix..]);
        return buf.toOwnedSlice(self.arena);
    }
    try dtfAppendPartValues(self, &buf, xp);
    try buf.appendSlice(self.arena, dtf_range_sep);
    try dtfAppendPartValues(self, &buf, yp);
    return buf.toOwnedSlice(self.arena);
}

/// `Intl.DateTimeFormat.prototype.formatRange(start, end)` — compact en range
/// formatting with equal dates collapsed and textual date intervals sharing
/// stable month/year fields.
fn intlDateTimeFormatRangeFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!intlBrandOk(this, "DateTimeFormat")) return self.throwError("TypeError", "Intl.DateTimeFormat.prototype.formatRange on incompatible receiver");
    if (args.len < 2 or args[0].isUndefined() or args[1].isUndefined()) return self.throwError("TypeError", "formatRange requires two defined arguments");
    const start = try dtfToDateTimeFormattable(self, args[0]);
    const end = try dtfToDateTimeFormattable(self, args[1]);
    try dtfRangeCheckKinds(self, start, end);
    if (dtfFormattableSame(start, end))
        return try Value.strOwned(self.arena, try dtfBuildText(self, this, &.{start}));
    var scratch = std.heap.ArenaAllocator.init(self.scratch_allocator orelse gc_mod.temporaryAllocator(self.arena));
    defer scratch.deinit();
    const xp = try dtfBuildParts(self, this, &.{start}, scratch.allocator()); // dtfBuildParts TimeClips (RangeError on bad value)
    const yp = try dtfBuildParts(self, this, &.{end}, scratch.allocator());
    return try Value.strAlloc(self.arena, try dtfFormatRangePartsText(self, xp.items(), yp.items()));
}

fn intlDateTimeFormatRangeToPartsFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!intlBrandOk(this, "DateTimeFormat")) return self.throwError("TypeError", "Intl.DateTimeFormat.prototype.formatRangeToParts on incompatible receiver");
    if (args.len < 2 or args[0].isUndefined() or args[1].isUndefined()) return self.throwError("TypeError", "formatRangeToParts requires two defined arguments");
    const start = try dtfToDateTimeFormattable(self, args[0]);
    const end = try dtfToDateTimeFormattable(self, args[1]);
    try dtfRangeCheckKinds(self, start, end);
    var scratch = std.heap.ArenaAllocator.init(self.scratch_allocator orelse gc_mod.temporaryAllocator(self.arena));
    defer scratch.deinit();
    const xp = try dtfBuildParts(self, this, &.{start}, scratch.allocator());
    const yp = if (dtfFormattableSame(start, end)) xp else try dtfBuildParts(self, this, &.{end}, scratch.allocator());
    const xparts = xp.items();
    const yparts = yp.items();
    const arr = (try self.newArray()).asObj();
    const emit = struct {
        fn part(s: *Interpreter, a: *value.Object, p: DtfPart, src: IntlRangeSource) value.HostError!void {
            const o = (try s.newObject()).asObj();
            try s.setProp(o, "type", p.typ.value());
            try s.setProp(o, "value", try p.materialize(s.arena));
            try s.setProp(o, "source", src.value());
            try a.appendElement(s.arena, Value.obj(o));
        }
        fn one(s: *Interpreter, a: *value.Object, prts: []const DtfPart, src: IntlRangeSource) value.HostError!void {
            for (prts) |p| try part(s, a, p, src);
        }
    }.one;
    if (dtfPartsSameValues(xparts, yparts)) {
        try emit(self, arr, xparts, .shared);
        return Value.obj(arr);
    }
    if (dtfIsTextualDateOnly(xparts) and dtfIsTextualDateOnly(yparts) and std.mem.eql(u8, xparts[4].value, yparts[4].value)) {
        if (std.mem.eql(u8, xparts[0].value, yparts[0].value)) {
            try emit(self, arr, xparts[0..2], .shared);
            try emit(self, arr, xparts[2..3], .start_range);
            const lo = (try self.newObject()).asObj();
            try self.setProp(lo, "type", Value.str("literal"));
            try self.setProp(lo, "value", Value.str("\u{2009}\u{2013}\u{2009}"));
            try self.setProp(lo, "source", Value.str("shared"));
            try arr.appendElement(self.arena, Value.obj(lo));
            try emit(self, arr, yparts[2..3], .end_range);
            try emit(self, arr, xparts[3..5], .shared);
        } else {
            try emit(self, arr, xparts[0..3], .start_range);
            const lo = (try self.newObject()).asObj();
            try self.setProp(lo, "type", Value.str("literal"));
            try self.setProp(lo, "value", Value.str("\u{2009}\u{2013}\u{2009}"));
            try self.setProp(lo, "source", Value.str("shared"));
            try arr.appendElement(self.arena, Value.obj(lo));
            try emit(self, arr, yparts[0..3], .end_range);
            try emit(self, arr, xparts[3..5], .shared);
        }
        return Value.obj(arr);
    }
    if (dtfIsTextualDateOnly(xparts) and dtfIsTextualDateOnly(yparts)) {
        try emit(self, arr, xparts, .start_range);
        const lo = (try self.newObject()).asObj();
        try self.setProp(lo, "type", Value.str("literal"));
        try self.setProp(lo, "value", Value.str("\u{2009}\u{2013}\u{2009}"));
        try self.setProp(lo, "source", Value.str("shared"));
        try arr.appendElement(self.arena, Value.obj(lo));
        try emit(self, arr, yparts, .end_range);
        return Value.obj(arr);
    }
    const shared_prefix = dtfSharedDateTimePrefixLen(xparts, yparts);
    if (shared_prefix > 0) {
        try emit(self, arr, xparts[0..shared_prefix], .shared);
        try emit(self, arr, xparts[shared_prefix..], .start_range);
        const lo = (try self.newObject()).asObj();
        try self.setProp(lo, "type", Value.str("literal"));
        try self.setProp(lo, "value", Value.str("\u{2009}\u{2013}\u{2009}"));
        try self.setProp(lo, "source", Value.str("shared"));
        try arr.appendElement(self.arena, Value.obj(lo));
        try emit(self, arr, yparts[shared_prefix..], .end_range);
        return Value.obj(arr);
    }
    try emit(self, arr, xparts, .start_range);
    const lo = (try self.newObject()).asObj();
    try self.setProp(lo, "type", Value.str("literal"));
    try self.setProp(lo, "value", Value.str("\u{2009}\u{2013}\u{2009}"));
    try self.setProp(lo, "source", Value.str("shared"));
    try arr.appendElement(self.arena, Value.obj(lo));
    try emit(self, arr, yparts, .end_range);
    return Value.obj(arr);
}

fn appendNum(self: *Interpreter, buf: *std.ArrayListUnmanaged(u8), first: *bool, sep: u8, v: anytype, two_digit: bool) EvalError!void {
    if (!first.*) try buf.append(self.arena, sep);
    first.* = false;
    if (two_digit) try tfmt(self, buf, "{d:0>2}", .{v}) else try tfmt(self, buf, "{d}", .{v});
}

/// Per-locale/system number symbols from the complete pinned CLDR number-data
/// inventory, combined with the compact locale table's currency placement.
fn localeNumberSymbols(locale: []const u8, numbering_system: []const u8) cldr_numbers.NumSym {
    var syms = cldr_numbers.lookupFor(locale, numbering_system);
    const t = parseTriple(locale);
    if (std.mem.eql(u8, numbering_system, "latn") and std.ascii.eqlIgnoreCase(t.l, "pt") and std.ascii.eqlIgnoreCase(t.r, "PT")) {
        syms.group = "\u{00a0}";
        syms.symbol_before = false;
    }
    return syms;
}

/// Per-currency display info: the en symbol and the ISO 4217 default fraction
/// digits. Unknown currencies fall back to the code with 2 digits.
const CurrencyInfo = struct { symbol: []const u8, digits: u8 };
fn currencyInfo(code: []const u8) CurrencyInfo {
    const pairs = .{
        .{ "USD", "$", 2 },
        .{ "EUR", "€", 2 },
        .{ "GBP", "£", 2 },
        .{ "JPY", "¥", 0 },
        .{ "CNY", "CN¥", 2 },
        .{ "INR", "₹", 2 },
        .{ "KRW", "₩", 0 },
        .{ "RUB", "₽", 2 },
        .{ "BRL", "R$", 2 },
        .{ "CAD", "CA$", 2 },
        .{ "AUD", "A$", 2 },
        .{ "CHF", "CHF", 2 },
        .{ "HKD", "HK$", 2 },
        .{ "NZD", "NZ$", 2 },
        .{ "MXN", "MX$", 2 },
        .{ "BHD", "BHD", 3 },
        .{ "KWD", "KWD", 3 },
        .{ "OMR", "OMR", 3 },
        .{ "CLP", "CLP", 0 },
        .{ "VND", "₫", 0 },
        .{ "TWD", "NT$", 2 },
    };
    inline for (pairs) |p| if (std.mem.eql(u8, code, p[0])) return .{ .symbol = p[1], .digits = p[2] };
    return .{ .symbol = code, .digits = 2 };
}

/// Round a non-negative magnitude `m` to an integer per an ECMA-402 rounding
/// mode (directed modes are sign-aware via `neg`). Ties are decided on the
/// f64 fractional remainder — which matches the spec, since the value being
/// formatted is already the nearest f64 to the source decimal.
fn roundMag(m: f64, neg: bool, mode: []const u8) f64 {
    const low = @floor(m);
    const frac = m - low;
    const eps = 1e-12 * @max(@as(f64, 1), @abs(m));
    if (frac <= eps) return low;
    const eqs = std.mem.eql;
    const up = blk: {
        if (eqs(u8, mode, "ceil")) break :blk !neg;
        if (eqs(u8, mode, "floor")) break :blk neg;
        if (eqs(u8, mode, "expand")) break :blk true;
        if (eqs(u8, mode, "trunc")) break :blk false;
        if (frac < 0.5 - eps) break :blk false;
        if (frac > 0.5 + eps) break :blk true;
        if (eqs(u8, mode, "halfCeil")) break :blk !neg;
        if (eqs(u8, mode, "halfFloor")) break :blk neg;
        if (eqs(u8, mode, "halfTrunc")) break :blk false;
        if (eqs(u8, mode, "halfEven")) break :blk @mod(low, 2) != 0;
        break :blk true; // halfExpand (default) — ties away from zero
    };
    return if (up) low + 1 else low;
}

const NfRound = struct { int_str: []const u8, frac_str: []const u8, is_zero: bool };

/// Native decimal workspace for one NumberFormat emission. A finite f64 has at
/// most 309 integer digits. Its minimum decimal order is -324; combined with
/// ECMA-402's maximum 21 significant digits, 345 fraction positions cover the
/// smallest subnormal. Fraction-digit options are independently capped at 100.
const NfDecimalScratch = struct {
    integer: [309]u8 = undefined,
    fraction: [345]u8 = undefined,
    digits: [309]u8 = undefined,
    exponent: [24]u8 = undefined,

    fn unsignedDigits(self: *NfDecimalScratch, n: u64) []const u8 {
        return std.fmt.bufPrint(&self.digits, "{d}", .{n}) catch unreachable;
    }

    fn finiteIntegerDigits(self: *NfDecimalScratch, n: f64) []const u8 {
        return std.fmt.bufPrint(&self.digits, "{d:.0}", .{n}) catch unreachable;
    }

    fn integerFromDigits(self: *NfDecimalScratch, digits: []const u8, trailing_zeros: usize, min_digits: usize) []const u8 {
        const natural_len = digits.len + trailing_zeros;
        const total_len = @max(natural_len, min_digits);
        std.debug.assert(total_len <= self.integer.len);
        const leading_zeros = total_len - natural_len;
        @memset(self.integer[0..leading_zeros], '0');
        @memcpy(self.integer[leading_zeros .. leading_zeros + digits.len], digits);
        @memset(self.integer[leading_zeros + digits.len .. total_len], '0');
        return self.integer[0..total_len];
    }

    fn fractionFromDigits(self: *NfDecimalScratch, leading_zeros: usize, digits: []const u8, trailing_zeros: usize, min_digits: usize, max_digits: ?usize) []const u8 {
        const raw_len = leading_zeros + digits.len + trailing_zeros;
        std.debug.assert(raw_len <= self.fraction.len);
        @memset(self.fraction[0..leading_zeros], '0');
        @memcpy(self.fraction[leading_zeros .. leading_zeros + digits.len], digits);
        @memset(self.fraction[leading_zeros + digits.len .. raw_len], '0');
        var len = if (max_digits) |limit| @min(raw_len, limit) else raw_len;
        while (len > min_digits and self.fraction[len - 1] == '0') len -= 1;
        std.debug.assert(min_digits <= self.fraction.len);
        if (len < min_digits) @memset(self.fraction[len..min_digits], '0');
        return self.fraction[0..@max(len, min_digits)];
    }

    fn exponentDigits(self: *NfDecimalScratch, n: u64) []const u8 {
        return std.fmt.bufPrint(&self.exponent, "{d}", .{n}) catch unreachable;
    }

    fn owns(self: *const NfDecimalScratch, bytes: []const u8) bool {
        if (bytes.len == 0) return false;
        const ptr = @intFromPtr(bytes.ptr);
        inline for (.{ &self.integer, &self.fraction, &self.exponent }) |buffer| {
            const start = @intFromPtr(buffer);
            if (ptr >= start and ptr < start + buffer.len) return true;
        }
        return false;
    }
};

/// The integer power of ten just below `m` (m > 0): floor(log10(m)), corrected
/// for the float error that makes log10 of an exact power of ten land low.
fn orderOfMagnitude(m: f64) i32 {
    var e: i32 = @intFromFloat(@floor(std.math.log10(m)));
    if (powi10(e + 1) <= m) e += 1;
    if (powi10(e) > m) e -= 1;
    return e;
}

fn powi10(e: i32) f64 {
    return std.math.pow(f64, 10, @floatFromInt(e));
}

/// Round `mag` (>= 0) to a decimal string per the NumberFormat digit options:
/// significant digits (when set / chosen by roundingPriority) else fraction
/// digits, with a rounding increment and rounding mode. Returns the integer and
/// (trimmed) fraction digit strings.
fn nfRound(scratch: *NfDecimalScratch, mag: f64, neg: bool, min_int: usize, min_frac: usize, max_frac: usize, min_sig: ?usize, max_sig: ?usize, frac_set: bool, priority: []const u8, rinc: u64, mode: []const u8) NfRound {
    const Inner = struct {
        // Build int/frac strings from an unsigned integer `r` whose decimal
        // point sits `scale_exp` places from its right end (scale_exp may be < 0).
        fn fromScaled(work: *NfDecimalScratch, r: u64, scale_exp: i32, min_int_digits: usize, lo_frac: usize, hi_frac: ?usize) struct { i: []const u8, f: []const u8 } {
            const rs = work.unsignedDigits(r);
            var int_str: []const u8 = undefined;
            var frac_str: []const u8 = undefined;
            if (scale_exp <= 0) {
                // Integer; append the trailing zeros the negative exponent implies.
                int_str = work.integerFromDigits(rs, @intCast(-scale_exp), min_int_digits);
                frac_str = work.fractionFromDigits(0, "", 0, lo_frac, hi_frac);
            } else {
                const se: usize = @intCast(scale_exp);
                if (se >= rs.len) {
                    int_str = work.integerFromDigits("0", 0, min_int_digits);
                    frac_str = work.fractionFromDigits(se - rs.len, rs, 0, lo_frac, hi_frac);
                } else {
                    int_str = work.integerFromDigits(rs[0 .. rs.len - se], 0, min_int_digits);
                    frac_str = work.fractionFromDigits(0, rs[rs.len - se ..], 0, lo_frac, hi_frac);
                }
            }
            return .{ .i = int_str, .f = frac_str };
        }
    };

    const use_sig = blk: {
        if (max_sig == null) break :blk false;
        if (std.mem.eql(u8, priority, "auto") or !frac_set) break :blk true;
        const e = if (mag == 0) 0 else orderOfMagnitude(mag);
        const sig_round_mag: i32 = e - @as(i32, @intCast(max_sig.?)) + 1;
        const frac_round_mag: i32 = -@as(i32, @intCast(max_frac));
        break :blk if (std.mem.eql(u8, priority, "morePrecision"))
            sig_round_mag < frac_round_mag
        else
            sig_round_mag > frac_round_mag;
    };
    if (use_sig) {
        const msig = max_sig.?;
        const lsig = min_sig orelse 1;
        if (mag == 0) {
            return .{
                .int_str = scratch.integerFromDigits("0", 0, min_int),
                .frac_str = scratch.fractionFromDigits(0, "", lsig - 1, lsig - 1, null),
                .is_zero = true,
            };
        }
        const e = orderOfMagnitude(mag);
        var scale_exp: i32 = @as(i32, @intCast(msig)) - 1 - e;
        var scaled = if (scale_exp >= 0) mag * powi10(scale_exp) else mag / powi10(-scale_exp);
        while (!std.math.isFinite(scaled) or scaled >= 9.0e18) {
            scale_exp -= 1;
            scaled = if (scale_exp >= 0) mag * powi10(scale_exp) else mag / powi10(-scale_exp);
        }
        const r: u64 = @intFromFloat(roundMag(scaled, neg, mode));
        // Rounding up can add a digit (9.99 -> 10.0); the decimal point keeps the
        // same scale_exp, so fromScaled handles the extra integer digit.
        // Significant mode shows at least lsig digits: lo_frac forces trailing zeros.
        const lo_frac: usize = blk: {
            // Rounding can add an integer digit (0.9995 -> 1.0). Minimum
            // precision is based on that rounded magnitude, not the input e.
            var rounded_digits: i32 = 1;
            var remaining = r;
            while (remaining >= 10) : (rounded_digits += 1) remaining /= 10;
            const rounded_order = rounded_digits - 1 - scale_exp;
            const int_sig: i32 = rounded_order + 1;
            const need: i32 = @as(i32, @intCast(lsig)) - int_sig;
            break :blk if (need > 0) @intCast(need) else 0;
        };
        const res = Inner.fromScaled(scratch, r, scale_exp, min_int, lo_frac, null);
        return .{ .int_str = res.i, .frac_str = res.f, .is_zero = false };
    }

    // Fixed (fraction-digit) path with optional rounding increment. Rounding is
    // done with at most 18 fraction digits (u64 range; further digits are zero
    // at f64 precision), then the string is padded out to min_frac.
    // Cap the fraction scaling so `mag * 10^eff` stays within u64 (a large
    // integer magnitude has no representable fraction anyway; the dropped digits
    // are zero and get padded back below).
    var eff: usize = @min(max_frac, 18);
    var scale: f64 = 1;
    while (true) {
        scale = 1;
        for (0..eff) |_| scale *= 10;
        if (eff == 0 or mag * scale < 9.0e18) break;
        eff -= 1;
    }
    const scaled = mag * scale;
    const rinc_f: f64 = @floatFromInt(rinc);
    const r: u64 = if (rinc > 1) @intFromFloat(roundMag(scaled / rinc_f, neg, mode) * rinc_f) else @intFromFloat(roundMag(scaled, neg, mode));
    const divi: u64 = @intFromFloat(scale);
    const int_part: u64 = if (divi == 0) r else r / divi;
    const frac_part: u64 = if (divi == 0) 0 else r % divi;
    const int_digits = scratch.unsignedDigits(int_part);
    const int_str = scratch.integerFromDigits(int_digits, 0, min_int);
    const frac_str = if (max_frac > 0) blk: {
        const frac_digits = scratch.unsignedDigits(frac_part);
        const leading_zeros = if (eff > frac_digits.len) eff - frac_digits.len else 0;
        break :blk scratch.fractionFromDigits(leading_zeros, frac_digits, max_frac - eff, min_frac, max_frac);
    } else "";
    return .{ .int_str = int_str, .frac_str = frac_str, .is_zero = (int_part == 0 and frac_part == 0) };
}

fn nfRoundedMagnitude(rounded: NfRound) ?i32 {
    for (rounded.int_str, 0..) |digit, index| {
        if (digit != '0') return @as(i32, @intCast(rounded.int_str.len - index)) - 1;
    }
    for (rounded.frac_str, 0..) |digit, index| {
        if (digit != '0') return -@as(i32, @intCast(index)) - 1;
    }
    return null;
}

fn nfRoundCompact(scratch: *NfDecimalScratch, scaled: f64, scaled_order: i32, neg: bool, min_int: usize, min_frac: usize, max_frac: usize, min_sig: ?usize, max_sig: ?usize, frac_set: bool, priority: []const u8, rinc: u64, mode: []const u8) NfRound {
    const explicit_precision = min_sig != null or max_sig != null or frac_set or !std.mem.eql(u8, priority, "auto");
    if (explicit_precision) {
        // Non-auto priority makes both precision families participate even if
        // the caller omitted explicit fraction settings (ECMA-402 16.1.2).
        const compare_fraction = frac_set or !std.mem.eql(u8, priority, "auto");
        return nfRound(scratch, scaled, neg, min_int, min_frac, max_frac, min_sig, max_sig, compare_fraction, priority, rinc, mode);
    }
    // Compact's option-free default is morePrecision between fraction 0 and
    // significant 1..2. For the already-scaled value that is equivalent to
    // retaining max(2, integer digit count) significant digits.
    const significant_digits: usize = @intCast(@max(2, scaled_order + 1));
    return nfRound(scratch, scaled, neg, min_int, 0, 0, 1, significant_digits, false, "auto", 1, mode);
}

fn nfDigitsNonzero(digits: []const u8) bool {
    for (digits) |digit| if (digit != '0') return true;
    return false;
}

/// Compare an exact decimal fraction encoded as digits with one half. Trailing
/// digits matter for ties: "5001" is above one half, while "5000" is equal.
fn nfExactHalfCmp(digits: []const u8) std.math.Order {
    if (digits.len == 0) return .lt;
    if (digits[0] < '5') return .lt;
    if (digits[0] > '5') return .gt;
    return if (nfDigitsNonzero(digits[1..])) .gt else .eq;
}

fn nfExactRoundUp(neg: bool, mode: []const u8, remainder_nonzero: bool, half_cmp: std.math.Order, lower_odd: bool) bool {
    if (!remainder_nonzero) return false;
    if (std.mem.eql(u8, mode, "ceil")) return !neg;
    if (std.mem.eql(u8, mode, "floor")) return neg;
    if (std.mem.eql(u8, mode, "expand")) return true;
    if (std.mem.eql(u8, mode, "trunc")) return false;
    if (half_cmp == .lt) return false;
    if (half_cmp == .gt) return true;
    if (std.mem.eql(u8, mode, "halfCeil")) return !neg;
    if (std.mem.eql(u8, mode, "halfFloor")) return neg;
    if (std.mem.eql(u8, mode, "halfTrunc")) return false;
    if (std.mem.eql(u8, mode, "halfEven")) return lower_odd;
    return true; // halfExpand
}

fn nfDecimalMod(digits: []const u8, modulus: u64) u64 {
    if (modulus == 1) return 0;
    var result: u64 = 0;
    for (digits) |digit| result = (result * 10 + digit - '0') % modulus;
    return result;
}

/// Add a small signed delta to a non-negative decimal integer. Work is linear in
/// the changed suffix (not the increment), so even a maximum-width BigInt with
/// roundingIncrement:5000 cannot amplify CPU use through repeated adjustment.
fn nfDecimalAdjust(self: *Interpreter, digits_in: []const u8, delta: i64) EvalError![]const u8 {
    var digits = try self.arena.dupe(u8, digits_in);
    if (delta > 0) {
        var carry: u64 = @intCast(delta);
        var index = digits.len;
        while (index > 0 and carry > 0) {
            index -= 1;
            const sum = @as(u64, digits[index] - '0') + carry % 10;
            carry /= 10;
            digits[index] = @intCast('0' + sum % 10);
            carry += sum / 10;
        }
        if (carry > 0) {
            const prefix = try std.fmt.allocPrint(self.arena, "{d}", .{carry});
            var carried: std.ArrayListUnmanaged(u8) = .empty;
            try carried.appendSlice(self.arena, prefix);
            try carried.appendSlice(self.arena, digits);
            digits = try carried.toOwnedSlice(self.arena);
        }
    } else if (delta < 0) {
        var remaining: u64 = @intCast(-delta);
        var borrow: u64 = 0;
        var index = digits.len;
        while (index > 0 and (remaining > 0 or borrow > 0)) {
            index -= 1;
            const subtrahend = remaining % 10 + borrow;
            remaining /= 10;
            const digit = @as(u64, digits[index] - '0');
            if (digit < subtrahend) {
                digits[index] = @intCast('0' + digit + 10 - subtrahend);
                borrow = 1;
            } else {
                digits[index] = @intCast('0' + digit - subtrahend);
                borrow = 0;
            }
        }
    }
    var first: usize = 0;
    while (first + 1 < digits.len and digits[first] == '0') first += 1;
    return digits[first..];
}

fn nfExactFromCoefficient(self: *Interpreter, coefficient: []const u8, scale: isize, min_int: usize, min_frac: usize) EvalError!NfRound {
    const decimal_pos = @as(isize, @intCast(coefficient.len)) + scale;
    const natural_int_len: usize = if (decimal_pos > 0) @intCast(decimal_pos) else 1;
    const int_len = @max(natural_int_len, min_int);
    var int_str = try self.arena.alloc(u8, int_len);
    @memset(int_str, '0');
    if (decimal_pos <= 0) {
        int_str[int_len - 1] = '0';
    } else {
        const point: usize = @intCast(decimal_pos);
        const copied = @min(point, coefficient.len);
        const start = int_len - point;
        @memcpy(int_str[start .. start + copied], coefficient[0..copied]);
    }

    const natural_frac_len: usize = if (decimal_pos < @as(isize, @intCast(coefficient.len)))
        @intCast(@as(isize, @intCast(coefficient.len)) - decimal_pos)
    else
        0;
    const frac_capacity = @max(natural_frac_len, min_frac);
    var frac_str = try self.arena.alloc(u8, frac_capacity);
    @memset(frac_str, '0');
    if (natural_frac_len > 0) {
        if (decimal_pos <= 0) {
            const leading: usize = @intCast(-decimal_pos);
            @memcpy(frac_str[leading .. leading + coefficient.len], coefficient);
        } else {
            const point: usize = @intCast(decimal_pos);
            @memcpy(frac_str[0 .. coefficient.len - point], coefficient[point..]);
        }
    }
    var frac_len = frac_capacity;
    while (frac_len > min_frac and frac_str[frac_len - 1] == '0') frac_len -= 1;
    frac_str = frac_str[0..frac_len];
    return .{ .int_str = int_str, .frac_str = frac_str, .is_zero = !nfDigitsNonzero(coefficient) };
}

/// Format an exact positive decimal coefficient whose decimal point is after
/// `decimal_pos` digits. This is the arbitrary-precision counterpart of
/// `nfRound`; it never converts the source mathematical value through f64.
fn nfRoundExact(self: *Interpreter, coefficient: []const u8, decimal_pos: usize, neg: bool, min_int: usize, min_frac: usize, max_frac: usize, min_sig: ?usize, max_sig: ?usize, frac_set: bool, priority: []const u8, rinc: u64, mode: []const u8) EvalError!NfRound {
    const zero = !nfDigitsNonzero(coefficient);
    const order: isize = if (zero) 0 else @as(isize, @intCast(decimal_pos)) - 1;
    const use_sig = blk: {
        if (max_sig == null) break :blk false;
        if (std.mem.eql(u8, priority, "auto") or !frac_set) break :blk true;
        const sig_round_mag = order - @as(isize, @intCast(max_sig.?)) + 1;
        const frac_round_mag = -@as(isize, @intCast(max_frac));
        break :blk if (std.mem.eql(u8, priority, "morePrecision"))
            sig_round_mag < frac_round_mag
        else
            sig_round_mag > frac_round_mag;
    };

    if (use_sig) {
        const hi = max_sig.?;
        const lo = min_sig orelse 1;
        if (zero) return nfExactFromCoefficient(self, "0", 0, min_int, lo - 1);
        const kept_len = @min(coefficient.len, hi);
        var kept = coefficient[0..kept_len];
        const scale = @as(isize, @intCast(decimal_pos)) - @as(isize, @intCast(kept_len));
        if (coefficient.len > kept_len) {
            const tail = coefficient[kept_len..];
            const lower_odd = ((kept[kept.len - 1] - '0') & 1) != 0;
            if (nfExactRoundUp(neg, mode, nfDigitsNonzero(tail), nfExactHalfCmp(tail), lower_odd)) {
                kept = try nfDecimalAdjust(self, kept, 1);
            }
        }
        var result = try nfExactFromCoefficient(self, kept, scale, min_int, 0);
        var first_nonzero: usize = 0;
        while (first_nonzero < result.int_str.len and result.int_str[first_nonzero] == '0') first_nonzero += 1;
        const integer_significant = if (first_nonzero < result.int_str.len) result.int_str.len - first_nonzero else 1;
        const required_frac = if (integer_significant < lo) lo - integer_significant else 0;
        if (result.frac_str.len < required_frac) {
            var padded = try self.arena.alloc(u8, required_frac);
            @memcpy(padded[0..result.frac_str.len], result.frac_str);
            @memset(padded[result.frac_str.len..], '0');
            result.frac_str = padded;
        }
        return result;
    }

    const cut = decimal_pos + max_frac;
    if (rinc == 1 and cut >= coefficient.len) {
        return nfExactFromCoefficient(
            self,
            coefficient,
            @as(isize, @intCast(decimal_pos)) - @as(isize, @intCast(coefficient.len)),
            min_int,
            min_frac,
        );
    }
    var quantized_buf = try self.arena.alloc(u8, @max(cut, 1));
    @memset(quantized_buf, '0');
    const copied = @min(cut, coefficient.len);
    if (copied > 0) @memcpy(quantized_buf[0..copied], coefficient[0..copied]);
    var quantized: []const u8 = quantized_buf;
    const tail = if (cut < coefficient.len) coefficient[cut..] else "";
    const remainder = nfDecimalMod(quantized, rinc);
    const remainder_nonzero = remainder != 0 or nfDigitsNonzero(tail);
    const twice = remainder * 2;
    const half_cmp: std.math.Order = if (twice > rinc)
        .gt
    else if (twice == rinc)
        if (nfDigitsNonzero(tail)) .gt else .eq
    else if (rinc - twice == 1)
        nfExactHalfCmp(tail)
    else
        .lt;
    const modulo_twice = nfDecimalMod(quantized, rinc * 2);
    const lower_odd = modulo_twice >= rinc;
    const round_up = nfExactRoundUp(neg, mode, remainder_nonzero, half_cmp, lower_odd);
    const delta: i64 = if (round_up)
        @intCast(rinc - remainder)
    else
        -@as(i64, @intCast(remainder));
    if (delta != 0) quantized = try nfDecimalAdjust(self, quantized, delta);
    return nfExactFromCoefficient(self, quantized, -@as(isize, @intCast(max_frac)), min_int, min_frac);
}

const IntlResolvedNumbering = struct {
    locale: []const u8,
    numbering_system: []const u8,
};

/// ResolveLocale's numbering-system key once for constructors and reflected
/// options. A supported option wins, then a supported `-u-nu-` extension, then
/// the locale's generated CLDR default. Retain the extension spelling only
/// when that extension selected the final system.
fn intlResolvedNumbering(self: *Interpreter, tag: []const u8, opt_ns: ?[]const u8) EvalError!IntlResolvedNumbering {
    const ext_ns = localeUValue(tag, "nu");
    const ext_ok = if (ext_ns) |e| numbering_systems.digits(e) != null else false;
    const opt_ok = if (opt_ns) |p| numbering_systems.digits(p) != null else false;
    const ns: []const u8 = if (opt_ok) opt_ns.? else if (ext_ok) ext_ns.? else localeDefaultNumberingSystem(tag);
    const keep_ext = ext_ok and std.mem.eql(u8, ext_ns.?, ns);
    const lang_base = if (std.mem.indexOf(u8, tag, "-u-")) |u| tag[0..u] else tag;
    const rloc: []const u8 = if (keep_ext)
        try std.fmt.allocPrint(self.arena, "{s}-u-nu-{s}", .{ lang_base, ns })
    else
        lang_base;
    return .{ .locale = rloc, .numbering_system = ns };
}

/// Set `locale` and `numberingSystem` on an Intl `resolvedOptions` result.
fn intlResolveNumbering(self: *Interpreter, out: *value.Object, tag: []const u8, opt_ns: ?[]const u8) value.HostError!void {
    const resolved = try intlResolvedNumbering(self, tag, opt_ns);
    try self.setProp(out, "locale", try Value.strAlloc(self.arena, resolved.locale));
    try self.setProp(out, "numberingSystem", try Value.strAlloc(self.arena, resolved.numbering_system));
}

fn installDurationFormatData(
    self: *Interpreter,
    formatter: *value.Object,
    locale: []const u8,
    options: *const DurationFormatOptions,
) EvalError!void {
    const resolved = try intlResolvedNumbering(self, locale, options.numbering_system);
    const allocator = try formatter.intlDurationFormatAllocator(self.arena);
    const data = try allocator.create(value.IntlDurationFormatData);
    data.* = .{
        .style = options.style,
        .unit_styles = options.unit_styles,
        .unit_displays = options.unit_displays,
        .fractional_digits = options.fractional_digits,
    };
    var installed = false;
    errdefer if (!installed) formatter.destroyUninstalledIntlDurationFormat(self.arena, data);
    data.owned_locale = try allocator.dupe(u8, resolved.locale);
    data.locale = data.owned_locale.?;
    data.owned_numbering_system = try allocator.dupe(u8, resolved.numbering_system);
    data.numbering_system = data.owned_numbering_system.?;
    try formatter.setIntlDurationFormatData(self.arena, data);
    installed = true;
}

/// Resolve and publish the complete RelativeTimeFormat record after all
/// user-observable option reads. The locale spelling follows ResolveLocale:
/// retain `-u-nu-` only when it selected the supported resolved system.
fn installRelativeTimeFormatData(
    self: *Interpreter,
    formatter: *value.Object,
    locale: []const u8,
    option_numbering_system: ?[]const u8,
    style: []const u8,
    numeric: []const u8,
) EvalError!void {
    const resolved = try intlResolvedNumbering(self, locale, option_numbering_system);

    const allocator = try formatter.intlRelativeTimeFormatAllocator(self.arena);
    const data = try allocator.create(value.IntlRelativeTimeFormatData);
    data.* = .{
        .style = .fromString(style),
        .numeric = .fromString(numeric),
    };
    var installed = false;
    errdefer if (!installed) formatter.destroyUninstalledIntlRelativeTimeFormat(self.arena, data);
    data.owned_locale = try allocator.dupe(u8, resolved.locale);
    data.locale = data.owned_locale.?;
    data.owned_numbering_system = try allocator.dupe(u8, resolved.numbering_system);
    data.numbering_system = data.owned_numbering_system.?;
    try formatter.setIntlRelativeTimeFormatData(self.arena, data);
    installed = true;
}

