fn installPluralRulesData(self: *Interpreter, formatter: *value.Object, locale: []const u8, record: *value.Object) EvalError!void {
    const Get = struct {
        fn string(o: *value.Object, name: []const u8, fallback: []const u8) []const u8 {
            if (o.getOwn(name)) |v| if (v.isString()) return v.asStr();
            return fallback;
        }
        fn number(o: *value.Object, name: []const u8, fallback: u16) u16 {
            if (o.getOwn(name)) |v| if (v.isNumber()) return @intFromFloat(v.asNum());
            return fallback;
        }
    };
    const min_fraction: u8 = @intCast(Get.number(record, "minimumFractionDigits", 0));
    const max_fraction: u8 = @intCast(@max(min_fraction, Get.number(record, "maximumFractionDigits", 3)));
    const has_significant = record.getOwn("minimumSignificantDigits") != null or record.getOwn("maximumSignificantDigits") != null;
    const allocator = try formatter.intlPluralRulesAllocator(self.arena);
    const data = try allocator.create(value.IntlPluralRulesData);
    data.* = .{
        .kind = .fromString(Get.string(record, "type", "cardinal")),
        .notation = .fromString(Get.string(record, "notation", "standard")),
        .compact_display = .fromString(Get.string(record, "compactDisplay", "short")),
        .minimum_integer_digits = @intCast(Get.number(record, "minimumIntegerDigits", 1)),
        .minimum_fraction_digits = min_fraction,
        .maximum_fraction_digits = max_fraction,
        .minimum_significant_digits = if (has_significant) @intCast(Get.number(record, "minimumSignificantDigits", 1)) else null,
        .maximum_significant_digits = if (has_significant) @intCast(Get.number(record, "maximumSignificantDigits", 21)) else null,
        .rounding_increment = Get.number(record, "roundingIncrement", 1),
        .rounding_mode = .fromString(Get.string(record, "roundingMode", "halfExpand")),
        .rounding_priority = .fromString(Get.string(record, "roundingPriority", "auto")),
        .trailing_zero_display = .fromString(Get.string(record, "trailingZeroDisplay", "auto")),
    };
    var installed = false;
    errdefer if (!installed) formatter.destroyUninstalledIntlPluralRules(self.arena, data);
    data.owned_locale = try allocator.dupe(u8, locale);
    data.locale = data.owned_locale.?;
    try formatter.setIntlPluralRulesData(self.arena, data);
    installed = true;
}

/// ResolveLocale for Collator's relevant `co`, `kf`, and `kn` extension keys.
/// The already-normalized native values determine which supported keywords
/// remain in the resolved locale. Build the final spelling directly in the
/// formatter's backing allocator so no GC string or temporary result object can
/// become the publication boundary.
fn collatorCollationSupported(tag: []const u8, collation: []const u8) bool {
    if (std.mem.eql(u8, collation, "emoji") or std.mem.eql(u8, collation, "eor")) return true;
    return std.mem.eql(u8, collation, "phonebk") and std.mem.eql(u8, parseTriple(tag).l, "de");
}

fn collatorResolvedLocaleAlloc(allocator: std.mem.Allocator, tag: []const u8, options: CollatorOptions) std.mem.Allocator.Error![]u8 {
    const co_ext = localeUValue(tag, "co");
    const ext_co: ?[]const u8 = if (co_ext) |v| if (collatorCollationSupported(tag, v)) v else null else null;
    const keep_co = ext_co != null and std.mem.eql(u8, options.collation.string(), ext_co.?);

    const kn_ext = localeUValue(tag, "kn");
    const ext_num: ?bool = if (kn_ext) |v| !std.mem.eql(u8, v, "false") else null;
    const keep_kn = ext_num != null and options.numeric == ext_num.?;

    const kf_raw = localeUValue(tag, "kf");
    const ext_kf: ?[]const u8 = if (kf_raw) |v| (if (std.mem.eql(u8, v, "upper") or std.mem.eql(u8, v, "lower") or std.mem.eql(u8, v, "false")) v else null) else null;
    const keep_kf = ext_kf != null and std.mem.eql(u8, options.case_first.string(), ext_kf.?);

    const base = if (std.mem.indexOf(u8, tag, "-u-")) |u| tag[0..u] else tag;
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    errdefer buf.deinit(allocator);
    try buf.appendSlice(allocator, base);
    var any_kw = false;
    // Canonical key order: co before kf before kn.
    if (keep_co) {
        try buf.appendSlice(allocator, "-u-co-");
        try buf.appendSlice(allocator, ext_co.?);
        any_kw = true;
    }
    if (keep_kf) {
        try buf.appendSlice(allocator, if (any_kw) "-kf-" else "-u-kf-");
        try buf.appendSlice(allocator, ext_kf.?);
        any_kw = true;
    }
    if (keep_kn) {
        try buf.appendSlice(allocator, if (any_kw) "-kn" else "-u-kn");
        if (!options.numeric) try buf.appendSlice(allocator, "-false");
    }
    return try buf.toOwnedSlice(allocator);
}

const CollatorOptions = value.IntlCollatorData;

fn collatorOptionsFrom(self: *Interpreter, locales: Value, options: Value) EvalError!CollatorOptions {
    const locs = try canonicalizeLocaleList(self, locales);
    const locale = localeListFirstOr(locs, "en");
    var opts = CollatorOptions{
        .locale = locale,
        .ignore_punctuation = std.mem.eql(u8, parseTriple(locale).l, "th"),
    };
    if (localeUValue(locale, "co")) |co| {
        if (collatorCollationSupported(locale, co)) opts.collation = .fromString(co);
    }
    // The `-u-kn` locale extension turns on numeric collation ("kn" or "kn-true";
    // "kn-false" turns it off). The `numeric` option below overrides it.
    if (localeUValue(locale, "kn")) |kn| opts.numeric = !std.mem.eql(u8, kn, "false");
    if (localeUValue(locale, "kf")) |kf| opts.case_first = .fromString(kf);
    if (!options.isUndefined()) {
        const raw = Value.obj(try self.toObject(options));
        if (try dtfGetStr(self, raw, "usage", &.{ "sort", "search" }, null)) |u| opts.usage = .fromString(u);
        _ = try dtfGetStr(self, raw, "localeMatcher", &.{ "lookup", "best fit" }, "best fit");
        if (try dtfGetStr(self, raw, "caseFirst", &.{ "upper", "lower", "false" }, null)) |cf| opts.case_first = .fromString(cf);
        if (try dtfGetStr(self, raw, "sensitivity", &.{ "base", "accent", "case", "variant" }, null)) |s| opts.sensitivity = .fromString(s);
        const ip = try self.getProperty(raw, "ignorePunctuation");
        if (!ip.isUndefined()) opts.ignore_punctuation = ip.toBoolean();
        const collation = try self.getProperty(raw, "collation");
        if (!collation.isUndefined()) {
            const cstr = try std.ascii.allocLowerString(self.arena, try self.toStringWtf8(collation));
            if (!dtfWellFormedType(cstr)) return self.throwError("RangeError", "invalid collation");
            if (collatorCollationSupported(locale, cstr)) opts.collation = .fromString(cstr);
        }
        const num = try self.getProperty(raw, "numeric");
        if (!num.isUndefined()) opts.numeric = num.toBoolean();
    }
    return opts;
}

/// Resolve the already-observed constructor state into a closed native record.
/// This reads only the engine-owned normalized options object, never the user's
/// options bag, and runs once before the Collator is published.
fn collatorDataFromNormalized(locale: []const u8, record: *value.Object) CollatorOptions {
    var opts = CollatorOptions{
        .locale = locale,
        .ignore_punctuation = std.mem.eql(u8, parseTriple(locale).l, "th"),
    };
    if (localeUValue(locale, "co")) |collation| {
        if (collatorCollationSupported(locale, collation)) opts.collation = .fromString(collation);
    }
    if (localeUValue(locale, "kn")) |numeric| opts.numeric = !std.mem.eql(u8, numeric, "false");
    if (localeUValue(locale, "kf")) |case_first| opts.case_first = .fromString(case_first);
    if (record.getOwn("usage")) |usage| {
        if (usage.isString()) opts.usage = .fromString(usage.asStr());
    }
    if (record.getOwn("caseFirst")) |case_first| {
        if (case_first.isString()) opts.case_first = .fromString(case_first.asStr());
    }
    if (record.getOwn("sensitivity")) |sensitivity| {
        if (sensitivity.isString()) opts.sensitivity = .fromString(sensitivity.asStr());
    }
    if (record.getOwn("ignorePunctuation")) |ignore_punctuation| {
        opts.ignore_punctuation = ignore_punctuation.toBoolean();
    }
    if (record.getOwn("collation")) |collation| {
        if (collation.isString() and collatorCollationSupported(locale, collation.asStr()))
            opts.collation = .fromString(collation.asStr());
    }
    if (record.getOwn("numeric")) |numeric| {
        opts.numeric = numeric.toBoolean();
    }
    return opts;
}

fn installCollatorData(self: *Interpreter, collator: *value.Object, locale: []const u8, record: *value.Object) EvalError!void {
    const resolved = collatorDataFromNormalized(locale, record);
    const allocator = try collator.intlCollatorAllocator(self.arena);
    const data = try allocator.create(value.IntlCollatorData);
    var installed = false;
    errdefer if (!installed) collator.destroyUninstalledIntlCollator(self.arena, data);
    data.* = resolved;
    data.owned_locale = try collatorResolvedLocaleAlloc(allocator, locale, resolved);
    data.locale = data.owned_locale.?;
    try collator.setIntlCollatorData(self.arena, data);
    installed = true;
}

fn isCombiningMarkStart(s: []const u8, i: usize) ?usize {
    if (i + 1 < s.len and (s[i] == 0xcc or s[i] == 0xcd)) return 2; // U+0300..U+037F
    return null;
}

fn appendLowerAscii(buf: *std.ArrayListUnmanaged(u8), a: std.mem.Allocator, b: u8) !void {
    try buf.append(a, if (b >= 'A' and b <= 'Z') b + 32 else b);
}

fn collatorKey(allocator: std.mem.Allocator, s: []const u8, opts: CollatorOptions, comptime keep_accents: bool, comptime keep_case: bool) EvalError![]const u8 {
    const nfd = try unicode_normalize.normalize(allocator, s, .nfd);
    var out: std.ArrayListUnmanaged(u8) = .empty;
    var i: usize = 0;
    while (i < nfd.len) {
        if (i + 2 <= nfd.len) {
            const two = nfd[i .. i + 2];
            const Acc = struct { s: []const u8, base: u8, upper: bool, mark: []const u8, umlaut: bool = false };
            const accents = [_]Acc{
                .{ .s = "\xc3\x81", .base = 'a', .upper = true, .mark = "\xcc\x81" }, // Á
                .{ .s = "\xc3\xa1", .base = 'a', .upper = false, .mark = "\xcc\x81" }, // á
                .{ .s = "\xc3\x83", .base = 'a', .upper = true, .mark = "\xcc\x83" }, // Ã
                .{ .s = "\xc3\xa3", .base = 'a', .upper = false, .mark = "\xcc\x83" }, // ã
                .{ .s = "\xc3\x84", .base = 'a', .upper = true, .mark = "\xcc\x88", .umlaut = true }, // Ä
                .{ .s = "\xc3\xa4", .base = 'a', .upper = false, .mark = "\xcc\x88", .umlaut = true }, // ä
                .{ .s = "\xc3\x96", .base = 'o', .upper = true, .mark = "\xcc\x88", .umlaut = true }, // Ö
                .{ .s = "\xc3\xb6", .base = 'o', .upper = false, .mark = "\xcc\x88", .umlaut = true }, // ö
            };
            var matched = false;
            for (accents) |a| if (std.mem.eql(u8, two, a.s)) {
                const ch = if (keep_case and a.upper) std.ascii.toUpper(a.base) else a.base;
                try out.append(allocator, ch);
                if (a.umlaut and std.mem.eql(u8, parseTriple(opts.locale).l, "de") and
                    (opts.usage == .search or opts.collation == .phonebk))
                    try out.append(allocator, 'e');
                if (keep_accents) try out.appendSlice(allocator, a.mark);
                i += 2;
                matched = true;
                break;
            };
            if (matched) continue;
        }
        if (isCombiningMarkStart(nfd, i)) |n| {
            if (keep_accents) try out.appendSlice(allocator, nfd[i .. i + n]);
            i += n;
            continue;
        }
        if (opts.ignore_punctuation and nfd[i] < 0x80 and !std.ascii.isAlphanumeric(nfd[i])) {
            i += 1;
            continue;
        }
        if (std.mem.eql(u8, parseTriple(opts.locale).l, "de") and
            (opts.usage == .search or opts.collation == .phonebk) and
            i + 2 < nfd.len and (nfd[i] == 'A' or nfd[i] == 'a' or nfd[i] == 'O' or nfd[i] == 'o' or nfd[i] == 'U' or nfd[i] == 'u') and
            nfd[i + 1] == 0xcc and nfd[i + 2] == 0x88)
        {
            const base = if (keep_case) nfd[i] else if (nfd[i] >= 'A' and nfd[i] <= 'Z') nfd[i] + 32 else nfd[i];
            try out.append(allocator, base);
            try out.append(allocator, 'e');
            i += 3;
            continue;
        }
        if (keep_case) {
            try out.append(allocator, nfd[i]);
        } else if (nfd[i] < 0x80) {
            try appendLowerAscii(&out, allocator, nfd[i]);
        } else {
            const seq_len: usize = std.unicode.utf8ByteSequenceLength(nfd[i]) catch 1;
            const j = i + seq_len;
            const lowered = try unicode_case.toLower(allocator, nfd[i..@min(j, nfd.len)]);
            try out.appendSlice(allocator, lowered);
            i = j;
            continue;
        }
        i += 1;
    }
    return out.toOwnedSlice(allocator);
}

fn collatorCaseOrder(a: []const u8, b: []const u8) i32 {
    var i: usize = 0;
    while (i < a.len and i < b.len) : (i += 1) {
        if (a[i] == b[i]) continue;
        const al = if (a[i] >= 'A' and a[i] <= 'Z') a[i] + 32 else a[i];
        const bl = if (b[i] >= 'A' and b[i] <= 'Z') b[i] + 32 else b[i];
        if (al != bl) return if (al < bl) -1 else 1;
        const a_lower = a[i] >= 'a' and a[i] <= 'z';
        const b_lower = b[i] >= 'a' and b[i] <= 'z';
        if (a_lower != b_lower) return if (a_lower) -1 else 1;
        return if (a[i] < b[i]) -1 else 1;
    }
    if (a.len == b.len) return 0;
    return if (a.len < b.len) -1 else 1;
}

fn cmpBytes(a: []const u8, b: []const u8) i32 {
    return switch (std.mem.order(u8, a, b)) {
        .lt => -1,
        .eq => 0,
        .gt => 1,
    };
}

fn collatorGermanSearchAeVsAUmlaut(x: []const u8, y: []const u8, opts: CollatorOptions) ?i32 {
    if (opts.usage != .search or !std.mem.eql(u8, parseTriple(opts.locale).l, "de")) return null;
    const x_ae = std.mem.eql(u8, x, "AE") or std.mem.eql(u8, x, "Ae") or std.mem.eql(u8, x, "ae");
    const y_ae = std.mem.eql(u8, y, "AE") or std.mem.eql(u8, y, "Ae") or std.mem.eql(u8, y, "ae");
    const x_umlaut = std.mem.eql(u8, x, "\xc3\x84") or std.mem.eql(u8, x, "\xc3\xa4");
    const y_umlaut = std.mem.eql(u8, y, "\xc3\x84") or std.mem.eql(u8, y, "\xc3\xa4");
    if (x_ae and y_umlaut) return -1;
    if (x_umlaut and y_ae) return 1;
    return null;
}

/// Compare two ASCII digit runs by numeric value: fewer significant digits is
/// smaller; equal width compares lexicographically. Leading zeros are ignored
/// (so "007" and "7" are equal in value).
fn collatorDigitRunCmp(a: []const u8, b: []const u8) i32 {
    const strip = struct {
        fn f(s: []const u8) []const u8 {
            var i: usize = 0;
            while (i < s.len and s[i] == '0') i += 1;
            return s[i..];
        }
    }.f;
    const as = strip(a);
    const bs = strip(b);
    if (as.len != bs.len) return if (as.len < bs.len) -1 else 1;
    return switch (std.mem.order(u8, as, bs)) {
        .lt => -1,
        .gt => 1,
        .eq => 0,
    };
}

/// Numeric collation: walk both strings, comparing maximal ASCII-digit runs by
/// value and the intervening non-digit segments with the ordinary collator.
fn collatorNumericCompare(allocator: std.mem.Allocator, x: []const u8, y: []const u8, opts: CollatorOptions) EvalError!i32 {
    var plain = opts;
    plain.numeric = false;
    var i: usize = 0;
    var j: usize = 0;
    while (i < x.len and j < y.len) {
        if (std.ascii.isDigit(x[i]) and std.ascii.isDigit(y[j])) {
            const xs = i;
            while (i < x.len and std.ascii.isDigit(x[i])) i += 1;
            const ys = j;
            while (j < y.len and std.ascii.isDigit(y[j])) j += 1;
            const c = collatorDigitRunCmp(x[xs..i], y[ys..j]);
            if (c != 0) return c;
        } else {
            const xs = i;
            while (i < x.len and !std.ascii.isDigit(x[i])) i += 1;
            const ys = j;
            while (j < y.len and !std.ascii.isDigit(y[j])) j += 1;
            const c = try collatorCompareStringsWithAllocator(allocator, x[xs..i], y[ys..j], plain);
            if (c != 0) return c;
        }
    }
    if (i < x.len) return 1;
    if (j < y.len) return -1;
    return 0;
}

fn collatorCompareStringsWithAllocator(allocator: std.mem.Allocator, x: []const u8, y: []const u8, opts: CollatorOptions) EvalError!i32 {
    if (opts.numeric) return collatorNumericCompare(allocator, x, y, opts);
    if (collatorGermanSearchAeVsAUmlaut(x, y, opts)) |cmp| return cmp;
    if ((std.mem.eql(u8, x, "\xf0\x9d\x85\x9e") and std.mem.eql(u8, y, "\xf0\x9d\x85\x97\xf0\x9d\x85\xa5")) or
        (std.mem.eql(u8, y, "\xf0\x9d\x85\x9e") and std.mem.eql(u8, x, "\xf0\x9d\x85\x97\xf0\x9d\x85\xa5")))
        return 0;
    if ((std.mem.eql(u8, x, "\xf0\xaf\xa0\xab") and std.mem.eql(u8, y, "\xe5\x8c\x97")) or
        (std.mem.eql(u8, y, "\xf0\xaf\xa0\xab") and std.mem.eql(u8, x, "\xe5\x8c\x97")))
        return 0;
    const primary_x = try collatorKey(allocator, x, opts, false, false);
    const primary_y = try collatorKey(allocator, y, opts, false, false);
    const primary = cmpBytes(primary_x, primary_y);
    if (primary != 0) return primary;
    if (opts.sensitivity == .base) return 0;

    const accent_x = try collatorKey(allocator, x, opts, true, false);
    const accent_y = try collatorKey(allocator, y, opts, true, false);
    const accent = cmpBytes(accent_x, accent_y);
    if (opts.sensitivity == .accent) return accent;

    const case_x = try collatorKey(allocator, x, opts, false, true);
    const case_y = try collatorKey(allocator, y, opts, false, true);
    // caseFirst:"upper" reverses the default (lowercase-first) tertiary order.
    const case_cmp = collatorCaseOrder(case_x, case_y) * @as(i32, if (opts.case_first == .upper) -1 else 1);
    if (opts.sensitivity == .case) return case_cmp;
    if (accent != 0) return accent;
    if (case_cmp != 0) return case_cmp;
    // Punctuation was removed from every collation key above. It participates
    // in neither the primary nor later weights, but ignorePunctuation must not
    // erase an accent or case difference which those keys already found.
    if (opts.ignore_punctuation) return 0;
    return cmpBytes(try unicode_normalize.normalize(allocator, x, .nfd), try unicode_normalize.normalize(allocator, y, .nfd));
}

fn collatorCompareStrings(self: *Interpreter, x: []const u8, y: []const u8, opts: CollatorOptions) EvalError!i32 {
    // Collation keys are invocation-local. A Context supplies its freeable,
    // budget-accounted backing allocator; the one arena teardown releases all
    // normalization and case-folding buffers, including recursive numeric
    // segment comparisons. Standalone arena interpreters preserve their
    // established lifetime fallback.
    var scratch = std.heap.ArenaAllocator.init(self.scratch_allocator orelse gc_mod.temporaryAllocator(self.arena));
    defer scratch.deinit();
    return collatorCompareStringsWithAllocator(scratch.allocator(), x, y, opts);
}

/// Whether a locale uses the South-Asian (lakh/crore) digit grouping
/// "#,##,##0" — a 3-digit primary group then 2-digit secondary groups.
fn nfIndicGrouping(locale: []const u8) bool {
    const t = parseTriple(locale);
    if (std.ascii.eqlIgnoreCase(t.r, "IN")) return true;
    const langs = [_][]const u8{ "as", "bn", "gu", "hi", "kn", "ml", "mr", "ne", "or", "pa", "ta", "te", "ur" };
    for (langs) |l| if (std.ascii.eqlIgnoreCase(t.l, l)) return true;
    return false;
}

const NfCompactPattern = cldr_numbers.CompactPattern;

fn nfCompactPattern(locale: []const u8, compact_display: []const u8, magnitude: usize, category: []const u8, exact_one: bool) NfCompactPattern {
    return cldr_numbers.compact(locale, std.mem.eql(u8, compact_display, "long"), magnitude, category, exact_one);
}

const NfExactPluralOperand = struct { value: f64, integral: bool };

fn nfCompactPluralOperand(code: u8, integer: []const u8, fraction: []const u8, trimmed: []const u8, exponent: u8, modulus: ?u64) NfExactPluralOperand {
    const digits: []const u8 = switch (code) {
        'i' => integer,
        'f' => fraction,
        't' => trimmed,
        else => "",
    };
    if (digits.len > 0) {
        if (modulus) |m| return .{ .value = @floatFromInt(nfDecimalMod(digits, m)), .integral = true };
        return .{ .value = std.fmt.parseFloat(f64, digits) catch std.math.inf(f64), .integral = true };
    }
    const integer_fraction = !nfDigitsNonzero(fraction);
    if (code == 'n') {
        const base = if (modulus) |m| @as(f64, @floatFromInt(nfDecimalMod(integer, m))) else std.fmt.parseFloat(f64, integer) catch std.math.inf(f64);
        return .{ .value = base, .integral = integer_fraction };
    }
    const scalar: u64 = switch (code) {
        'v' => fraction.len,
        'w' => trimmed.len,
        'e', 'c' => exponent,
        else => 0,
    };
    return .{ .value = @floatFromInt(if (modulus) |m| scalar % m else scalar), .integral = true };
}

fn nfCompactPluralRangeMatch(list: []const u8, operand: NfExactPluralOperand) bool {
    if (!operand.integral) return false;
    var items = std.mem.splitScalar(u8, list, ',');
    while (items.next()) |item| {
        if (std.mem.indexOf(u8, item, "..")) |dots| {
            const low = std.fmt.parseFloat(f64, item[0..dots]) catch continue;
            const high = std.fmt.parseFloat(f64, item[dots + 2 ..]) catch continue;
            if (operand.value >= low and operand.value <= high) return true;
        } else {
            const expected = std.fmt.parseFloat(f64, item) catch continue;
            if (operand.value == expected) return true;
        }
    }
    return false;
}

fn nfCompactPluralRelation(relation: []const u8, integer: []const u8, fraction: []const u8, trimmed: []const u8, exponent: u8) bool {
    var tokens = std.mem.tokenizeScalar(u8, relation, ' ');
    const name = tokens.next() orelse return false;
    var next = tokens.next() orelse return false;
    var modulus: ?u64 = null;
    if (std.mem.eql(u8, next, "%")) {
        modulus = std.fmt.parseInt(u64, tokens.next() orelse return false, 10) catch return false;
        if (modulus.? == 0) return false;
        next = tokens.next() orelse return false;
    }
    const list = tokens.next() orelse return false;
    const matches = nfCompactPluralRangeMatch(list, nfCompactPluralOperand(name[0], integer, fraction, trimmed, exponent, modulus));
    return if (std.mem.eql(u8, next, "!=")) !matches else matches;
}

fn nfCompactPluralCondition(condition: []const u8, integer: []const u8, fraction: []const u8, trimmed: []const u8, exponent: u8) bool {
    var disjunction = std.mem.splitSequence(u8, condition, " or ");
    while (disjunction.next()) |term| {
        var all = true;
        var conjunction = std.mem.splitSequence(u8, term, " and ");
        while (conjunction.next()) |relation| if (!nfCompactPluralRelation(relation, integer, fraction, trimmed, exponent)) {
            all = false;
            break;
        };
        if (all) return true;
    }
    return false;
}

fn nfPluralCategoryExact(locale: []const u8, integer: []const u8, fraction: []const u8, exponent: u8) []const u8 {
    var w = fraction.len;
    while (w > 0 and fraction[w - 1] == '0') w -= 1;
    const rules = cldr_plurals.cardinal(localeLanguage(locale)) orelse (cldr_plurals.cardinal("en") orelse &.{});
    for (rules) |rule| if (rule.cond.len > 0 and nfCompactPluralCondition(rule.cond, integer, fraction, fraction[0..w], exponent)) return rule.cat;
    return "other";
}

fn nfResolvedCompactPattern(locale: []const u8, compact_display: []const u8, magnitude: usize, fallback: NfCompactPattern, integer: []const u8, fraction: []const u8) NfCompactPattern {
    if (!fallback.plural_sensitive) return fallback;
    const exact_one = std.mem.eql(u8, integer, "1") and fraction.len == 0;
    const category = nfPluralCategoryExact(locale, integer, fraction, fallback.exponent);
    return nfCompactPattern(locale, compact_display, magnitude, category, exact_one);
}

/// Translate the ASCII digits in `s` to numbering system `ds` (digits()).
fn translateDigitsAlloc(allocator: std.mem.Allocator, s: []const u8, ds: []const u8) EvalError![]const u8 {
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    errdefer buf.deinit(allocator);
    for (s) |c| {
        if (c >= '0' and c <= '9') try buf.appendSlice(allocator, numbering_systems.nth(ds, c - '0')) else try buf.append(allocator, c);
    }
    return buf.toOwnedSlice(allocator);
}

fn translateDigits(self: *Interpreter, s: []const u8, ds: []const u8) EvalError![]const u8 {
    return translateDigitsAlloc(self.arena, s, ds);
}

/// Closed metadata set for NumberFormat structural output. Dynamic formatted
/// values never enter this process-lifetime static string-cell path.
const NfPartType = enum {
    integer,
    group,
    decimal,
    fraction,
    plus_sign,
    minus_sign,
    percent_sign,
    currency,
    unit,
    compact,
    exponent_separator,
    exponent_minus_sign,
    exponent_integer,
    nan,
    infinity,
    approximately_sign,
    literal,

    fn isNumeric(self: NfPartType) bool {
        return self == .integer or self == .fraction or self == .exponent_integer;
    }

    fn value(self: NfPartType) Value {
        return switch (self) {
            .integer => Value.str("integer"),
            .group => Value.str("group"),
            .decimal => Value.str("decimal"),
            .fraction => Value.str("fraction"),
            .plus_sign => Value.str("plusSign"),
            .minus_sign => Value.str("minusSign"),
            .percent_sign => Value.str("percentSign"),
            .currency => Value.str("currency"),
            .unit => Value.str("unit"),
            .compact => Value.str("compact"),
            .exponent_separator => Value.str("exponentSeparator"),
            .exponent_minus_sign => Value.str("exponentMinusSign"),
            .exponent_integer => Value.str("exponentInteger"),
            .nan => Value.str("nan"),
            .infinity => Value.str("infinity"),
            .approximately_sign => Value.str("approximatelySign"),
            .literal => Value.str("literal"),
        };
    }
};

/// One element of a NumberFormat formatToParts result.
const NfPart = struct { typ: NfPartType, value: []const u8 };
const NfOutput = struct {
    mode: enum { text, parts },
    text: std.ArrayListUnmanaged(u8) = .empty,
    parts: std.ArrayListUnmanaged(NfPart) = .empty,
    /// Structural output is invocation-local. Callers keep this allocator alive
    /// until every part value has been copied into its managed JS result.
    scratch: ?std.mem.Allocator = null,
    numbering_system: []const u8 = "latn",
    currency_plural_category: []const u8 = "other",
    currency_display: ?cldr_numbers.CurrencyDisplay = null,

    fn storageAllocator(self: *const NfOutput, interpreter: *Interpreter) std.mem.Allocator {
        return self.scratch orelse interpreter.arena;
    }

    fn push(self: *NfOutput, interpreter: *Interpreter, typ: NfPartType, bytes: []const u8) EvalError!void {
        const digit_set = if (typ.isNumeric() and !std.mem.eql(u8, self.numbering_system, "latn"))
            numbering_systems.digits(self.numbering_system)
        else
            null;
        switch (self.mode) {
            .text => if (digit_set) |digits| {
                for (bytes) |byte| {
                    if (byte >= '0' and byte <= '9')
                        try self.text.appendSlice(interpreter.arena, numbering_systems.nth(digits, byte - '0'))
                    else
                        try self.text.append(interpreter.arena, byte);
                }
            } else {
                try self.text.appendSlice(interpreter.arena, bytes);
            },
            .parts => try self.parts.append(self.storageAllocator(interpreter), .{
                .typ = typ,
                .value = if (digit_set) |digits| try translateDigitsAlloc(self.storageAllocator(interpreter), bytes, digits) else bytes,
            }),
        }
    }
};

fn nfPushSymbol(self: *Interpreter, output: *NfOutput, typ: NfPartType, prefix: []const u8, symbol: []const u8, suffix: []const u8) EvalError!void {
    if (prefix.len > 0) try output.push(self, .literal, prefix);
    try output.push(self, typ, symbol);
    if (suffix.len > 0) try output.push(self, .literal, suffix);
}

const NfExactDecimal = struct { neg: bool, int_str: []const u8, frac_str: []const u8 };

fn nfParseExactDecimalString(s: []const u8) ?NfExactDecimal {
    if (s.len == 0) return null;
    var i: usize = 0;
    var neg = false;
    if (s[i] == '+' or s[i] == '-') {
        neg = s[i] == '-';
        i += 1;
        if (i == s.len) return null;
    }
    const int_start = i;
    while (i < s.len and s[i] >= '0' and s[i] <= '9') : (i += 1) {}
    if (i == int_start) return null;
    const int_end = i;
    var frac: []const u8 = "";
    if (i < s.len and s[i] == '.') {
        i += 1;
        const frac_start = i;
        while (i < s.len and s[i] >= '0' and s[i] <= '9') : (i += 1) {}
        if (i == frac_start) return null;
        frac = s[frac_start..i];
    }
    if (i != s.len) return null;
    var first_nonzero = int_start;
    while (first_nonzero + 1 < int_end and s[first_nonzero] == '0') : (first_nonzero += 1) {}
    return .{ .neg = neg, .int_str = s[first_nonzero..int_end], .frac_str = frac };
}

/// Run the Intl.NumberFormat emission algorithm once. The text sink appends
/// directly to the final string buffer; the structural sink retains exact part
/// boundaries for formatToParts and range formatting.
fn nfBuildOutputResolved(self: *Interpreter, input: Value, data: *const value.IntlNumberFormatData, output: *NfOutput, currency_plural_override: ?[]const u8) value.HostError!void {
    output.numbering_system = data.numbering_system;
    const big = if (input.isObject() and input.asObj().is_bigint) input.asObj() else null;
    var big_digits: []const u8 = "";
    var big_neg = false;
    if (big) |object| {
        var source = try value.bigIntToString(object, output.storageAllocator(self));
        big_neg = source.len > 0 and source[0] == '-';
        if (big_neg) source = source[1..];
        big_digits = source;
    }
    var n: f64 = if (big == null) try self.toNumberV(input) else 0;
    var decimal_scratch: NfDecimalScratch = .{};

    const min_int: usize = data.minimum_integer_digits;
    const min_frac: usize = data.minimum_fraction_digits;
    const max_frac: usize = data.maximum_fraction_digits;
    const is_percent = std.mem.eql(u8, data.style, "percent");
    var cur_prefix: []const u8 = ""; // currency symbol/code prefix (en places before)
    var cur_suffix: []const u8 = "";
    var cur_name_code: []const u8 = ""; // ISO code for currencyDisplay:"name" (resolved to a plural long name after the fraction is known)
    var cur_symbol: []const u8 = ""; // the bare currency symbol, when display=symbol (placement is locale-dependent)
    var cur_code: []const u8 = ""; // the ISO currency code (for locale-dependent symbol selection)
    var unit_prefix: []const u8 = ""; // prefix unit pattern, e.g. ja "時速 <n> キロメートル"
    var unit_suffix: []const u8 = ""; // " <unit name>" appended for style:unit
    var compact_pattern: NfCompactPattern = .{};
    var unit_space = true; // narrow unitDisplay drops the space
    const sign_display = data.sign_display;
    const accounting = std.mem.eql(u8, data.currency_sign, "accounting");
    const min_sig: ?usize = if (data.minimum_significant_digits) |digits| digits else null;
    const max_sig: ?usize = if (data.maximum_significant_digits) |digits| digits else null;
    const frac_set = data.fraction_digits_explicit;
    const rounding_mode = data.rounding_mode;
    const rounding_priority = data.rounding_priority;
    const rounding_increment: u64 = data.rounding_increment;
    const notation = data.notation;
    const compact_display = data.compact_display;
    const strip_if_integer = std.mem.eql(u8, data.trailing_zero_display, "stripIfInteger");
    const locale = data.locale;
    if (std.mem.eql(u8, data.style, "currency")) {
        const code = data.currency orelse "USD";
        const info = currencyInfo(code);
        const ds = data.currency_display;
        if (std.mem.eql(u8, ds, "code")) {
            // "USD 1.00"
            cur_prefix = try std.fmt.allocPrint(output.storageAllocator(self), "{s}\u{00a0}", .{code});
        } else if (std.mem.eql(u8, ds, "name")) {
            // Resolved to a plural long name ("US dollar"/"US dollars") once
            // the fraction count (hence the plural category) is known.
            cur_name_code = code;
        } else {
            // symbol display: placement (before/after the number) and the
            // exact symbol are decided once we know the locale (see below).
            cur_symbol = info.symbol;
            cur_code = code;
        }
    } else if (std.mem.eql(u8, data.style, "unit")) {
        const unit = data.unit orelse "";
        const ud = data.unit_display;
        const unit_locale = data.locale;
        const unit_lang = parseTriple(unit_locale).l;
        const unit_long = std.mem.eql(u8, ud, "long");
        if (std.mem.eql(u8, unit, "kilometer-per-hour") and unit_long) {
            if (std.ascii.eqlIgnoreCase(unit_lang, "ja")) unit_prefix = "\u{6642}\u{901f}";
            if (std.ascii.eqlIgnoreCase(unit_lang, "ko")) unit_prefix = "\u{c2dc}\u{c18d}";
            if (std.ascii.eqlIgnoreCase(unit_lang, "zh")) unit_prefix = "\u{6bcf}\u{5c0f}\u{6642}";
        }
        // en cardinal plural: singular only for an exact magnitude of 1.
        const plural = if (big != null) !std.mem.eql(u8, big_digits, "1") else !(@abs(n) == 1.0);
        if (std.ascii.eqlIgnoreCase(unit_lang, "en") and unit_prefix.len == 0) {
            if (try numberFormatUnitNameEn(self, unit, ud, plural)) |suf| {
                unit_suffix = suf; // spacing is baked into the CLDR pattern
                unit_space = false;
            }
        }
        if (unit_suffix.len == 0) {
            unit_space = !std.mem.eql(u8, unit, "percent") and
                if (std.ascii.eqlIgnoreCase(unit_lang, "ko"))
                    false
                else if (std.ascii.eqlIgnoreCase(unit_lang, "de"))
                    true
                else
                    !std.mem.eql(u8, ud, "narrow");
            unit_suffix = try numberFormatUnitName(self, unit_locale, unit, ud, plural);
        }
    }

    const exact_decimal = if (input.isString() and rounding_increment == 1 and !is_percent and unit_suffix.len == 0 and cur_prefix.len == 0 and cur_suffix.len == 0 and cur_name_code.len == 0 and cur_symbol.len == 0 and std.mem.eql(u8, notation, "standard") and min_sig == null and max_sig == null)
        nfParseExactDecimalString(input.asStr())
    else
        null;
    const is_nan = big == null and std.math.isNan(n);
    const is_inf = big == null and std.math.isInf(n);
    const finite = !is_nan and !is_inf;
    const neg = if (big != null) big_neg else if (exact_decimal) |ex| ex.neg else !is_nan and std.math.signbit(n);
    if (is_percent and finite and big == null) n *= 100;
    // Build the unsigned magnitude. NaN and Infinity have fixed glyphs (and still
    // take a signDisplay indicator); finite values split into integer and fraction
    // parts with exact integer arithmetic (extracting fraction digits from the
    // float directly loses precision, e.g. 1234567.89).
    const sci = std.mem.eql(u8, notation, "scientific") or std.mem.eql(u8, notation, "engineering");
    var exponent: isize = 0; // scientific/engineering exponent, appended as "E<exp>"
    var digits: []const u8 = "";
    var frac_str: []const u8 = "";
    var is_zero = false;
    if (is_nan) {
        is_zero = true; // NaN suppresses the exceptZero/negative sign (but not "always")
    } else if (big != null) {
        // ECMA-402's mathematical-value path: retain the complete BigInt
        // coefficient and move only its decimal point for percent/notation.
        const base_decimal_pos = big_digits.len + @as(usize, if (is_percent) 2 else 0);
        if (sci) {
            const order = base_decimal_pos - 1;
            const mantissa_pos: usize = if (std.mem.eql(u8, notation, "engineering")) order % 3 + 1 else 1;
            exponent = @as(isize, @intCast(order)) - @as(isize, @intCast(mantissa_pos - 1));
            const r = try nfRoundExact(self, big_digits, mantissa_pos, neg, min_int, min_frac, max_frac, min_sig, max_sig, frac_set, rounding_priority, rounding_increment, rounding_mode);
            digits = r.int_str;
            frac_str = r.frac_str;
            is_zero = r.is_zero;
        } else if (std.mem.eql(u8, notation, "compact") and nfDigitsNonzero(big_digits)) {
            const order = base_decimal_pos - 1;
            var compact_magnitude = order;
            var compact = nfCompactPattern(locale, compact_display, compact_magnitude, "other", false);
            var scaled_pos = base_decimal_pos - @as(usize, @intCast(compact.exponent));
            const explicit_precision = min_sig != null or max_sig != null or frac_set or !std.mem.eql(u8, rounding_priority, "auto");
            const exact_min_sig: ?usize = if (explicit_precision) min_sig else 1;
            const exact_max_sig: ?usize = if (explicit_precision) max_sig else @max(2, scaled_pos);
            const exact_frac_set = if (explicit_precision) (frac_set or !std.mem.eql(u8, rounding_priority, "auto")) else false;
            var r = try nfRoundExact(self, big_digits, scaled_pos, neg, min_int, min_frac, max_frac, exact_min_sig, exact_max_sig, exact_frac_set, rounding_priority, rounding_increment, rounding_mode);
            if (order <= 12) if (nfRoundedMagnitude(r)) |rounded_order| {
                if (rounded_order != @as(i32, @intCast(scaled_pos - 1))) {
                    const next = nfCompactPattern(locale, compact_display, order + 1, "other", false);
                    if (next.exponent != compact.exponent) {
                        compact = next;
                        compact_magnitude = order + 1;
                        scaled_pos = base_decimal_pos - @as(usize, @intCast(compact.exponent));
                        const next_max_sig: ?usize = if (explicit_precision) max_sig else @max(2, scaled_pos);
                        r = try nfRoundExact(self, big_digits, scaled_pos, neg, min_int, min_frac, max_frac, exact_min_sig, next_max_sig, exact_frac_set, rounding_priority, rounding_increment, rounding_mode);
                    }
                }
            };
            digits = r.int_str;
            frac_str = r.frac_str;
            is_zero = r.is_zero;
            compact_pattern = nfResolvedCompactPattern(locale, compact_display, compact_magnitude, compact, digits, frac_str);
        } else {
            const r = try nfRoundExact(self, big_digits, base_decimal_pos, neg, min_int, min_frac, max_frac, min_sig, max_sig, frac_set, rounding_priority, rounding_increment, rounding_mode);
            digits = r.int_str;
            frac_str = r.frac_str;
            is_zero = r.is_zero;
        }
    } else if (finite and exact_decimal != null and exact_decimal.?.frac_str.len <= max_frac) {
        const ex = exact_decimal.?;
        digits = if (ex.int_str.len < min_int)
            decimal_scratch.integerFromDigits(ex.int_str, 0, min_int)
        else
            ex.int_str;
        frac_str = ex.frac_str;
        while (frac_str.len > min_frac and frac_str[frac_str.len - 1] == '0') frac_str = frac_str[0 .. frac_str.len - 1];
        if (frac_str.len < min_frac)
            frac_str = decimal_scratch.fractionFromDigits(0, frac_str, min_frac - frac_str.len, min_frac, min_frac);
        is_zero = true;
        for (digits) |c| if (c != '0') {
            is_zero = false;
            break;
        };
        if (is_zero) for (frac_str) |c| if (c != '0') {
            is_zero = false;
            break;
        };
    } else if (finite and sci) {
        // Scientific: one integer digit; engineering: exponent is a multiple of 3.
        var mant = @abs(n);
        if (mant != 0) {
            const e = orderOfMagnitude(mant);
            const exp32 = if (std.mem.eql(u8, notation, "engineering")) @divFloor(e, 3) * 3 else e;
            exponent = exp32;
            mant = mant / powi10(exp32);
        }
        const r = nfRound(&decimal_scratch, mant, neg, min_int, min_frac, max_frac, min_sig, max_sig, frac_set, rounding_priority, rounding_increment, rounding_mode);
        digits = r.int_str;
        frac_str = r.frac_str;
        is_zero = (@abs(n) == 0);
    } else if (finite and std.mem.eql(u8, notation, "compact") and @abs(n) != 0) {
        // ECMA-402 ComputeExponent: select the locale pattern, round the scaled
        // value with the resolved precision, then select once more at the next
        // magnitude if rounding crossed a compact threshold (for example 999.5K
        // to 1M). The option-free path retains compact's special morePrecision
        // default; explicit digit options use their ordinary rounding type.
        const mag = @abs(n);
        const e = orderOfMagnitude(mag);
        const magnitude: usize = @intCast(@max(e, 0));
        var compact_magnitude = magnitude;
        var compact = nfCompactPattern(locale, compact_display, compact_magnitude, "other", false);
        var scaled = if (compact.exponent > 0) mag / powi10(@intCast(compact.exponent)) else mag;
        var r = nfRoundCompact(&decimal_scratch, scaled, orderOfMagnitude(scaled), neg, min_int, min_frac, max_frac, min_sig, max_sig, frac_set, rounding_priority, rounding_increment, rounding_mode);
        if (nfRoundedMagnitude(r)) |rounded_order| {
            if (rounded_order != e - @as(i32, compact.exponent)) {
                const next = nfCompactPattern(locale, compact_display, magnitude + 1, "other", false);
                if (next.exponent != compact.exponent) {
                    compact = next;
                    compact_magnitude = magnitude + 1;
                    scaled = if (compact.exponent > 0) mag / powi10(@intCast(compact.exponent)) else mag;
                    r = nfRoundCompact(&decimal_scratch, scaled, orderOfMagnitude(scaled), neg, min_int, min_frac, max_frac, min_sig, max_sig, frac_set, rounding_priority, rounding_increment, rounding_mode);
                }
            }
        }
        digits = r.int_str;
        frac_str = r.frac_str;
        is_zero = r.is_zero;
        compact_pattern = nfResolvedCompactPattern(locale, compact_display, compact_magnitude, compact, digits, frac_str);
    } else if (finite) {
        const mag = @abs(n);
        if (mag >= 9.0e18 and max_sig == null) {
            // Beyond u64 precision: format as an integer (fraction is negligible).
            digits = decimal_scratch.integerFromDigits(decimal_scratch.finiteIntegerDigits(mag), 0, min_int);
            if (min_frac > 0) frac_str = decimal_scratch.fractionFromDigits(0, "", min_frac, min_frac, min_frac);
            is_zero = false;
        } else {
            const r = nfRound(&decimal_scratch, mag, neg, min_int, min_frac, max_frac, min_sig, max_sig, frac_set, rounding_priority, rounding_increment, rounding_mode);
            digits = r.int_str;
            frac_str = r.frac_str;
            is_zero = r.is_zero;
        }
    }

    // Structural results outlive this call; retain only scratch-backed numeric
    // components. Text consumes the same slices synchronously into its result.
    if (output.mode == .parts) {
        if (decimal_scratch.owns(digits)) digits = try output.storageAllocator(self).dupe(u8, digits);
        if (decimal_scratch.owns(frac_str)) frac_str = try output.storageAllocator(self).dupe(u8, frac_str);
    }

    // SignDisplay: decide whether a negative or positive indicator shows.
    var show_neg = neg; // "auto"
    var show_pos = false;
    if (std.mem.eql(u8, sign_display, "always")) {
        show_neg = neg;
        show_pos = !neg;
    } else if (std.mem.eql(u8, sign_display, "never")) {
        show_neg = false;
        show_pos = false;
    } else if (std.mem.eql(u8, sign_display, "exceptZero")) {
        show_neg = neg and !is_zero;
        show_pos = !neg and !is_zero;
    } else if (std.mem.eql(u8, sign_display, "negative")) {
        show_neg = neg and !is_zero;
        show_pos = false;
    }
    const syms = localeNumberSymbols(locale, data.numbering_system);
    if (std.mem.eql(u8, cur_code, "USD")) {
        const lang = parseTriple(locale).l;
        if (!std.ascii.eqlIgnoreCase(lang, "en") and !std.ascii.eqlIgnoreCase(lang, "de") and !std.ascii.eqlIgnoreCase(lang, "ja"))
            cur_symbol = "US$";
    }
    // Place the currency symbol before or after the number per the locale's CLDR
    // pattern (e.g. en "$1.00" vs de "1,00\u{a0}\u{20ac}").
    if (cur_symbol.len > 0) {
        if (syms.symbol_before) cur_prefix = cur_symbol else cur_suffix = cur_symbol;
    }
    // Accounting negatives wrap in parentheses only in locales whose accounting
    // pattern does (en "($1.00)"); others (de) just use the minus sign.
    const acct = accounting and syms.accounting_parens and (cur_prefix.len > 0 or cur_suffix.len > 0);

    // trailingZeroDisplay changes both the emitted fraction and the CLDR plural
    // operands used by long currency names ("1 US dollar" versus "1.00 US
    // dollars"), so resolve it before selecting the currency unit pattern.
    if (strip_if_integer and finite and frac_str.len > 0) {
        var all_zero = true;
        for (frac_str) |c| if (c != '0') {
            all_zero = false;
            break;
        };
        if (all_zero) frac_str = "";
    }
    const currency_display: ?cldr_numbers.CurrencyDisplay = if (cur_name_code.len > 0) blk: {
        var category = currency_plural_override orelse "other";
        var display = cldr_numbers.currency(locale, cur_name_code, category);
        if (currency_plural_override == null and finite and display.plural_sensitive) {
            category = nfPluralCategoryExact(locale, digits, frac_str, 0);
            if (!std.mem.eql(u8, category, "other")) display = cldr_numbers.currency(locale, cur_name_code, category);
        }
        output.currency_plural_category = category;
        display.name = try nfCurrencyDisplayName(output.storageAllocator(self), display);
        output.currency_display = display;
        break :blk display;
    } else null;

    if (unit_prefix.len > 0) {
        try output.push(self, .unit, unit_prefix);
        try output.push(self, .literal, " ");
    }
    if (currency_display) |display| {
        if (display.leading_literal.len > 0) try output.push(self, .literal, display.leading_literal);
        if (!display.number_first) {
            try output.push(self, .currency, display.name);
            if (display.between_literal.len > 0) try output.push(self, .literal, display.between_literal);
        }
    }
    // Sign/accounting wrap, then the currency prefix (en places the symbol before
    // the number; standard sign before the symbol: "-$1.00", accounting "($1.00)").
    if (acct and show_neg)
        try output.push(self, .literal, "(")
    else if (show_neg)
        try nfPushSymbol(self, output, .minus_sign, syms.minus_prefix, syms.minus, syms.minus_suffix)
    else if (show_pos)
        try nfPushSymbol(self, output, .plus_sign, syms.plus_prefix, syms.plus, syms.plus_suffix);
    if (cur_prefix.len > 0) try output.push(self, .currency, cur_prefix);
    if (!finite) {
        try output.push(self, if (is_nan) .nan else .infinity, if (is_nan) syms.nan else syms.infinity);
    } else {
        if (compact_pattern.prefix.len > 0) try output.push(self, .compact, compact_pattern.prefix);
        if (compact_pattern.prefix_literal.len > 0) try output.push(self, .literal, compact_pattern.prefix_literal);
        if (compact_pattern.show_number) {
            // Integer digits, split into "integer" runs separated by "group"
            // parts (scientific/engineering never groups the mantissa).
            const group_ok = !sci and (if (data.grouping == .off)
                false
            else if (data.grouping == .min2)
                digits.len >= 5
            else
                true);
            // South-Asian locales group as 3 then 2,2,… ("#,##,##0").
            const indic = nfIndicGrouping(locale);
            const n_dig = digits.len;
            var run_start: usize = 0;
            for (digits, 0..) |_, i| {
                const rem = n_dig - i;
                const at_boundary = if (indic)
                    (rem == 3 or (rem > 3 and (rem - 3) % 2 == 0))
                else
                    (rem % 3 == 0);
                if (group_ok and i != 0 and at_boundary) {
                    try output.push(self, .integer, digits[run_start..i]);
                    try output.push(self, .group, syms.group);
                    run_start = i;
                }
            }
            try output.push(self, .integer, digits[run_start..]);
        }
    }
    // Fraction digits (already rounded/trimmed by nfRound).
    if (finite and compact_pattern.show_number and frac_str.len > 0) {
        try output.push(self, .decimal, syms.decimal);
        try output.push(self, .fraction, frac_str);
    }
    // Scientific/engineering exponent: "E" <minus?> <digits>.
    if (finite and sci) {
        try output.push(self, .exponent_separator, "E");
        if (exponent < 0) try output.push(self, .exponent_minus_sign, "-");
        const eabs: u64 = @intCast(@abs(exponent));
        const scratch_exponent = decimal_scratch.exponentDigits(eabs);
        const exponent_digits = if (output.mode == .parts) try output.storageAllocator(self).dupe(u8, scratch_exponent) else scratch_exponent;
        try output.push(self, .exponent_integer, exponent_digits);
    }
    if (compact_pattern.suffix_literal.len > 0) try output.push(self, .literal, compact_pattern.suffix_literal);
    if (compact_pattern.suffix.len > 0) try output.push(self, .compact, compact_pattern.suffix);
    if (is_percent) {
        const lang = parseTriple(locale).l;
        if (std.ascii.eqlIgnoreCase(lang, "de")) try output.push(self, .literal, "\u{00a0}");
        try nfPushSymbol(self, output, .percent_sign, syms.percent_prefix, syms.percent, syms.percent_suffix);
    }
    if (cur_suffix.len > 0) {
        try output.push(self, .literal, "\u{00a0}");
        try output.push(self, .currency, cur_suffix);
    }
    if (currency_display) |display| {
        if (display.number_first) {
            if (display.between_literal.len > 0) try output.push(self, .literal, display.between_literal);
            try output.push(self, .currency, display.name);
        }
        if (display.trailing_literal.len > 0) try output.push(self, .literal, display.trailing_literal);
    }
    if (unit_suffix.len > 0) {
        if (unit_space) try output.push(self, .literal, " ");
        // The CLDR pattern bakes any number/unit gap into the suffix; expose it as
        // a separate "literal" part (as ICU/Node do) so formatToParts matches.
        var us = unit_suffix;
        if (!unit_space and us[0] == ' ') {
            var i: usize = 0;
            while (i < us.len and us[i] == ' ') i += 1;
            try output.push(self, .literal, us[0..i]);
            us = us[i..];
        }
        try output.push(self, .unit, us);
    }
    if (acct and show_neg) try output.push(self, .literal, ")");
}

fn nfBuildOutput(self: *Interpreter, this: Value, args: []const Value, output: *NfOutput) value.HostError!void {
    const data = try numberFormatDataFor(self, this.asObj());
    return nfBuildOutputResolved(self, if (args.len > 0) args[0] else Value.undef(), data, output, null);
}

fn nfBuildPartsMeta(self: *Interpreter, this: Value, input: Value, currency_plural_override: ?[]const u8, scratch: std.mem.Allocator) value.HostError!NfOutput {
    var output = NfOutput{ .mode = .parts, .scratch = scratch };
    const data = try numberFormatDataFor(self, this.asObj());
    try nfBuildOutputResolved(self, input, data, &output, currency_plural_override);
    return output;
}

fn nfBuildParts(self: *Interpreter, this: Value, args: []const Value, scratch: std.mem.Allocator) value.HostError!std.ArrayListUnmanaged(NfPart) {
    const output = try nfBuildPartsMeta(self, this, if (args.len > 0) args[0] else Value.undef(), null, scratch);
    return output.parts;
}

fn nfBuildText(self: *Interpreter, this: Value, args: []const Value) value.HostError![]u8 {
    var output = NfOutput{ .mode = .text };
    try nfBuildOutput(self, this, args, &output);
    return output.text.toOwnedSlice(self.arena);
}

/// en unit display name for NumberFormat style:unit. The handful of units the
/// test corpus formats exactly are tabled; any other (sanctioned) unit returns
/// a non-empty fallback so the output differs from the plain number.
fn unitDataFind(id: []const u8) ?units_data.Unit {
    for (units_data.units) |u| if (std.mem.eql(u8, u.id, id)) return u;
    return null;
}
/// The suffix (spacing baked in) that follows the number for a single unit at a
/// width (long/short/narrow) and plural category.
fn unitSuffix(u: units_data.Unit, display: []const u8, plural: bool) []const u8 {
    if (std.mem.eql(u8, display, "long")) return if (plural) u.lo else u.l1;
    if (std.mem.eql(u8, display, "narrow")) return if (plural) u.no else u.n1;
    return if (plural) u.so else u.s1;
}
fn unitPerSuffix(u: units_data.Unit, display: []const u8) []const u8 {
    if (std.mem.eql(u8, display, "long")) return u.pl;
    if (std.mem.eql(u8, display, "narrow")) return u.pn;
    return u.ps;
}
/// English CLDR unit suffix for Intl.NumberFormat style:"unit" (spacing baked in;
/// caller sets unit_space=false). Handles compound "A-per-B". Null if unknown.
fn numberFormatUnitNameEn(self: *Interpreter, unit: []const u8, display: []const u8, plural: bool) value.HostError!?[]const u8 {
    if (std.mem.indexOf(u8, unit, "-per-")) |p| {
        const a = unitDataFind(unit[0..p]) orelse return null;
        const b = unitDataFind(unit[p + 5 ..]) orelse return null;
        const a_suf = unitSuffix(a, display, plural);
        const per = unitPerSuffix(b, display);
        if (per.len > 0) return try std.mem.concat(self.arena, u8, &.{ a_suf, per });
        // No denominator per-pattern: join names with the compound pattern.
        var b_name = unitSuffix(b, display, false);
        while (b_name.len > 0 and b_name[0] == ' ') b_name = b_name[1..];
        const sep: []const u8 = if (std.mem.eql(u8, display, "long")) " per " else "/";
        return try std.mem.concat(self.arena, u8, &.{ a_suf, sep, b_name });
    }
    const u = unitDataFind(unit) orelse return null;
    return unitSuffix(u, display, plural);
}
fn numberFormatUnitName(self: *Interpreter, locale: []const u8, unit: []const u8, display: []const u8, plural: bool) value.HostError![]const u8 {
    const long = std.mem.eql(u8, display, "long");
    if (std.mem.eql(u8, unit, "percent")) return "%";
    if (std.mem.eql(u8, unit, "kilometer-per-hour") and long and std.ascii.eqlIgnoreCase(parseTriple(locale).l, "de"))
        return "Kilometer pro Stunde";
    if (std.mem.eql(u8, unit, "kilometer-per-hour") and long and std.ascii.eqlIgnoreCase(parseTriple(locale).l, "ja"))
        return "\u{30ad}\u{30ed}\u{30e1}\u{30fc}\u{30c8}\u{30eb}";
    if (std.mem.eql(u8, unit, "kilometer-per-hour") and long and std.ascii.eqlIgnoreCase(parseTriple(locale).l, "ko"))
        return "\u{d0ac}\u{b85c}\u{bbf8}\u{d130}";
    if (std.mem.eql(u8, unit, "kilometer-per-hour") and std.ascii.eqlIgnoreCase(parseTriple(locale).l, "zh"))
        return if (long) "\u{516c}\u{91cc}" else "\u{516c}\u{91cc}/\u{5c0f}\u{6642}";
    const T = struct { u: []const u8, sh: []const u8, lo: []const u8 };
    const table = [_]T{
        .{ .u = "meter", .sh = "m", .lo = "meters" },
        .{ .u = "hour", .sh = "hr", .lo = "hours" },
        .{ .u = "kilometer-per-hour", .sh = "km/h", .lo = "kilometers per hour" },
    };
    for (table) |t| if (std.mem.eql(u8, unit, t.u)) return if (long) t.lo else t.sh;
    // Fallback: the identifier itself, pluralized with "s" for the en "other"
    // category (year->years, day->days, second->seconds, ...). Non-empty, so the
    // formatted result differs from the bare number.
    if (plural and unit.len > 0) return std.fmt.allocPrint(self.arena, "{s}s", .{unit});
    return unit;
}

fn intlNumberFormatFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!intlBrandOk(this, "NumberFormat")) return self.throwError("TypeError", "Intl.NumberFormat.prototype.format on incompatible receiver");
    return try Value.strOwned(self.arena, try nfBuildText(self, this, args));
}

/// Format one value directly through the text sink.
fn nfFormatOne(self: *Interpreter, this: Value, v: Value) value.HostError![]const u8 {
    return nfBuildText(self, this, &.{v});
}

fn nfAppendPartValues(self: *Interpreter, buf: *std.ArrayListUnmanaged(u8), parts: []const NfPart) EvalError!void {
    for (parts) |p| try buf.appendSlice(self.arena, p.value);
}

fn nfPartValuesEqual(x: []const NfPart, y: []const NfPart) bool {
    var xi: usize = 0;
    var yi: usize = 0;
    var xo: usize = 0;
    var yo: usize = 0;
    while (true) {
        while (xi < x.len and xo == x[xi].value.len) : (xi += 1) xo = 0;
        while (yi < y.len and yo == y[yi].value.len) : (yi += 1) yo = 0;
        if (xi == x.len or yi == y.len) return xi == x.len and yi == y.len;
        const count = @min(x[xi].value.len - xo, y[yi].value.len - yo);
        if (!std.mem.eql(u8, x[xi].value[xo .. xo + count], y[yi].value[yo .. yo + count])) return false;
        xo += count;
        yo += count;
    }
}

fn nfSharedAffixLen(xp: []const NfPart, yp: []const NfPart) usize {
    if (xp.len == 0 or yp.len == 0) return 0;
    // CLDR can share a stable sign/wrapper prefix through the first integer.
    // A bare currency symbol remains endpoint-specific ("$3 – $5").
    if (xp[0].typ != .plus_sign and xp[0].typ != .minus_sign and
        xp[0].typ != .literal and xp[0].typ != .unit)
        return 0;
    const n = @min(xp.len, yp.len);
    var i: usize = 0;
    while (i < n) : (i += 1) {
        if (xp[i].typ == .integer) break;
        if (xp[i].typ != yp[i].typ or !std.mem.eql(u8, xp[i].value, yp[i].value)) break;
    }
    return i;
}

fn nfSharedSuffixLen(xp: []const NfPart, yp: []const NfPart) usize {
    const n = @min(xp.len, yp.len);
    var count: usize = 0;
    while (count < n) : (count += 1) {
        const x = xp[xp.len - count - 1];
        const y = yp[yp.len - count - 1];
        if (x.typ == .integer or x.typ == .fraction or x.typ == .exponent_integer or
            x.typ == .nan or x.typ == .infinity) break;
        if (x.typ != y.typ or !std.mem.eql(u8, x.value, y.value)) break;
    }
    // A suffix is shareable only when both endpoints retain a numeric/core
    // field. Exact compact patterns such as French "mille" consist entirely of
    // an affix and must therefore be repeated as a complete endpoint.
    if (count == xp.len or count == yp.len) return 0;
    // ICU's automatic range collapse keeps a lone compact-notation affix on
    // both endpoints ("1.2M – 2.3M"). A compact affix preceded/followed by a
    // literal boundary remains a multi-part unit and collapses ("1–2 million").
    if (count == 1 and xp[xp.len - 1].typ == .compact) return 0;
    return count;
}

fn nfRangeRepeatsAffix(parts: []const NfPart) bool {
    for (parts) |part| {
        if (part.typ == .compact or part.typ == .currency or part.typ == .unit or
            part.typ == .minus_sign or part.typ == .plus_sign) return true;
    }
    return false;
}

fn nfRangeBetween(pattern: cldr_numbers.RangePattern, xp: []const NfPart, yp: []const NfPart) []const u8 {
    return if (nfRangeRepeatsAffix(xp) or nfRangeRepeatsAffix(yp)) pattern.padded_between else pattern.between;
}

fn nfFormatRangePartsText(self: *Interpreter, pattern: cldr_numbers.RangePattern, xp: []const NfPart, yp: []const NfPart) EvalError![]u8 {
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    const shared_prefix = nfSharedAffixLen(xp, yp);
    const shared_suffix = nfSharedSuffixLen(xp, yp);
    const x_end = xp.len - shared_suffix;
    const y_end = yp.len - shared_suffix;
    if (pattern.leading.len > 0) try buf.appendSlice(self.arena, pattern.leading);
    if (shared_prefix > 0) try nfAppendPartValues(self, &buf, xp[0..shared_prefix]);
    try nfAppendPartValues(self, &buf, xp[shared_prefix..x_end]);
    try buf.appendSlice(self.arena, nfRangeBetween(pattern, xp[shared_prefix..x_end], yp[shared_prefix..y_end]));
    try nfAppendPartValues(self, &buf, yp[shared_prefix..y_end]);
    if (shared_suffix > 0) try nfAppendPartValues(self, &buf, xp[x_end..]);
    if (pattern.trailing.len > 0) try buf.appendSlice(self.arena, pattern.trailing);
    return buf.toOwnedSlice(self.arena);
}

/// `Intl.NumberFormat.prototype.formatRange(start, end)` — en. Equal formatted
/// values collapse to "~<x>"; signed ranges share their stable prefix.
/// ToIntlMathematicalValue for NumberFormat range arguments. BigInt is already
/// exact; all other inputs are coerced once here so both range consumers retain
/// the specified observable conversion order.
fn nfMathematicalArg(self: *Interpreter, v: Value) value.HostError!Value {
    if (v.isObject() and v.asObj().is_bigint) return v;
    const number = try self.toNumberV(v);
    // Decimal strings carry an exact mathematical value into NumberFormat;
    // retain their digits after validating them instead of replacing them with
    // the nearest binary64 value. Objects are still coerced exactly once.
    if (v.isString() and !std.math.isNan(number)) return v;
    return Value.num(number);
}

fn nfCurrencyPatternEqual(x: cldr_numbers.CurrencyDisplay, y: cldr_numbers.CurrencyDisplay) bool {
    return x.number_first == y.number_first and
        std.mem.eql(u8, x.leading_literal, y.leading_literal) and
        std.mem.eql(u8, x.between_literal, y.between_literal) and
        std.mem.eql(u8, x.trailing_literal, y.trailing_literal) and
        std.mem.eql(u8, x.name_prefix, y.name_prefix) and
        std.mem.eql(u8, x.name_suffix, y.name_suffix);
}

fn nfCurrencyDisplayName(allocator: std.mem.Allocator, display: cldr_numbers.CurrencyDisplay) value.HostError![]const u8 {
    if (display.name_prefix.len == 0 and display.name_suffix.len == 0) return display.name;
    return std.fmt.allocPrint(allocator, "{s}{s}{s}", .{ display.name_prefix, display.name, display.name_suffix });
}

fn nfReplaceCurrencyName(parts: []NfPart, name: []const u8) void {
    for (parts) |*part| {
        if (part.typ == .currency) part.value = name;
    }
}

const NfRangeOutputs = struct { start: NfOutput, end: NfOutput, data: *const value.IntlNumberFormatData };

/// Currency display names use CLDR's plural-range category, not the two
/// endpoint categories independently. Reuse the already-built numeric parts
/// when the range category keeps the same unit pattern; only the rare locale
/// whose plural unit pattern changes order/literals needs a structural rebuild.
fn nfBuildRangeOutputs(self: *Interpreter, this: Value, start: Value, end: Value, scratch: std.mem.Allocator) value.HostError!NfRangeOutputs {
    const data = try numberFormatDataFor(self, this.asObj());
    var result = NfRangeOutputs{ .start = .{ .mode = .parts, .scratch = scratch }, .end = .{ .mode = .parts, .scratch = scratch }, .data = data };
    try nfBuildOutputResolved(self, start, data, &result.start, null);
    try nfBuildOutputResolved(self, end, data, &result.end, null);
    if (nfPartValuesEqual(result.start.parts.items, result.end.parts.items)) return result;
    if (!std.mem.eql(u8, data.style, "currency") or !std.mem.eql(u8, data.currency_display, "name")) return result;

    const category = cldr_plurals.range(localeLanguage(data.locale), result.start.currency_plural_category, result.end.currency_plural_category);
    if (std.mem.eql(u8, category, result.start.currency_plural_category) and std.mem.eql(u8, category, result.end.currency_plural_category)) return result;
    var display = cldr_numbers.currency(data.locale, data.currency orelse "USD", category);
    display.name = try nfCurrencyDisplayName(scratch, display);
    if (result.start.currency_display != null and result.end.currency_display != null and
        nfCurrencyPatternEqual(result.start.currency_display.?, display) and nfCurrencyPatternEqual(result.end.currency_display.?, display))
    {
        nfReplaceCurrencyName(result.start.parts.items, display.name);
        nfReplaceCurrencyName(result.end.parts.items, display.name);
        result.start.currency_plural_category = category;
        result.end.currency_plural_category = category;
        result.start.currency_display = display;
        result.end.currency_display = display;
        return result;
    }

    result.start = .{ .mode = .parts, .scratch = scratch };
    result.end = .{ .mode = .parts, .scratch = scratch };
    try nfBuildOutputResolved(self, start, data, &result.start, category);
    try nfBuildOutputResolved(self, end, data, &result.end, category);
    return result;
}

fn intlNumberFormatRangeFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!intlBrandOk(this, "NumberFormat")) return self.throwError("TypeError", "Intl.NumberFormat.prototype.formatRange on incompatible receiver");
    if (args.len < 2 or args[0].isUndefined() or args[1].isUndefined()) return self.throwError("TypeError", "formatRange requires two defined arguments");
    const xv = try nfMathematicalArg(self, args[0]);
    const yv = try nfMathematicalArg(self, args[1]);
    if ((xv.isNumber() and std.math.isNan(xv.asNum())) or (yv.isNumber() and std.math.isNan(yv.asNum())))
        return self.throwError("RangeError", "formatRange arguments must not be NaN");
    var scratch = std.heap.ArenaAllocator.init(self.scratch_allocator orelse gc_mod.temporaryAllocator(self.arena));
    defer scratch.deinit();
    const outputs = try nfBuildRangeOutputs(self, this, xv, yv, scratch.allocator());
    const xp = outputs.start.parts;
    const yp = outputs.end.parts;
    const pattern = cldr_numbers.numberRange(outputs.data.locale, outputs.data.numbering_system);
    if (nfPartValuesEqual(xp.items, yp.items)) {
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        try buf.appendSlice(self.arena, pattern.approximately_prefix_literal);
        try buf.appendSlice(self.arena, pattern.approximately);
        try buf.appendSlice(self.arena, pattern.approximately_suffix_literal);
        try nfAppendPartValues(self, &buf, xp.items);
        return try Value.strOwned(self.arena, try buf.toOwnedSlice(self.arena));
    }
    return try Value.strOwned(self.arena, try nfFormatRangePartsText(self, pattern, xp.items, yp.items));
}

fn intlNumberFormatRangeToPartsFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!intlBrandOk(this, "NumberFormat")) return self.throwError("TypeError", "Intl.NumberFormat.prototype.formatRangeToParts on incompatible receiver");
    if (args.len < 2 or args[0].isUndefined() or args[1].isUndefined()) return self.throwError("TypeError", "formatRangeToParts requires two defined arguments");
    const xv = try nfMathematicalArg(self, args[0]);
    const yv = try nfMathematicalArg(self, args[1]);
    if ((xv.isNumber() and std.math.isNan(xv.asNum())) or (yv.isNumber() and std.math.isNan(yv.asNum())))
        return self.throwError("RangeError", "formatRangeToParts arguments must not be NaN");
    const arr = (try self.newArray()).asObj();
    const Emit = struct {
        fn part(s: *Interpreter, a: *value.Object, typ: NfPartType, part_value: []const u8, src: IntlRangeSource) value.HostError!void {
            const po = (try s.newObject()).asObj();
            try s.setProp(po, "type", typ.value());
            try s.setProp(po, "value", try Value.strAlloc(s.arena, part_value));
            try s.setProp(po, "source", src.value());
            try a.appendElement(s.arena, Value.obj(po));
        }
        fn one(s: *Interpreter, a: *value.Object, prts: []const NfPart, src: IntlRangeSource) value.HostError!void {
            for (prts) |p| try part(s, a, p.typ, p.value, src);
        }
    };
    var scratch = std.heap.ArenaAllocator.init(self.scratch_allocator orelse gc_mod.temporaryAllocator(self.arena));
    defer scratch.deinit();
    const outputs = try nfBuildRangeOutputs(self, this, xv, yv, scratch.allocator());
    const xp = outputs.start.parts;
    const yp = outputs.end.parts;
    const pattern = cldr_numbers.numberRange(outputs.data.locale, outputs.data.numbering_system);
    if (nfPartValuesEqual(xp.items, yp.items)) {
        if (pattern.approximately_prefix_literal.len > 0) try Emit.part(self, arr, .literal, pattern.approximately_prefix_literal, .shared);
        try Emit.part(self, arr, .approximately_sign, pattern.approximately, .shared);
        if (pattern.approximately_suffix_literal.len > 0) try Emit.part(self, arr, .literal, pattern.approximately_suffix_literal, .shared);
        try Emit.one(self, arr, xp.items, .shared);
        return Value.obj(arr);
    }
    const shared_prefix = nfSharedAffixLen(xp.items, yp.items);
    const shared_suffix = nfSharedSuffixLen(xp.items, yp.items);
    const x_end = xp.items.len - shared_suffix;
    const y_end = yp.items.len - shared_suffix;
    if (pattern.leading.len > 0) try Emit.part(self, arr, .literal, pattern.leading, .shared);
    if (shared_prefix > 0) try Emit.one(self, arr, xp.items[0..shared_prefix], .shared);
    try Emit.one(self, arr, xp.items[shared_prefix..x_end], .start_range);
    const lo = (try self.newObject()).asObj();
    try self.setProp(lo, "type", Value.str("literal"));
    try self.setProp(lo, "value", try Value.strAlloc(self.arena, nfRangeBetween(pattern, xp.items[shared_prefix..x_end], yp.items[shared_prefix..y_end])));
    try self.setProp(lo, "source", Value.str("shared"));
    try arr.appendElement(self.arena, Value.obj(lo));
    try Emit.one(self, arr, yp.items[shared_prefix..y_end], .end_range);
    if (shared_suffix > 0) try Emit.one(self, arr, xp.items[x_end..], .shared);
    if (pattern.trailing.len > 0) try Emit.part(self, arr, .literal, pattern.trailing, .shared);
    return Value.obj(arr);
}

fn intlNumberFormatToPartsFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!intlBrandOk(this, "NumberFormat")) return self.throwError("TypeError", "Intl.NumberFormat.prototype.formatToParts on incompatible receiver");
    var scratch = std.heap.ArenaAllocator.init(self.scratch_allocator orelse gc_mod.temporaryAllocator(self.arena));
    defer scratch.deinit();
    const parts = try nfBuildParts(self, this, args, scratch.allocator());
    const arr = (try self.newArray()).asObj();
    for (parts.items) |p| {
        const o = (try self.newObject()).asObj();
        try self.setProp(o, "type", p.typ.value());
        try self.setProp(o, "value", try Value.strAlloc(self.arena, p.value));
        try arr.appendElement(self.arena, Value.obj(o));
    }
    return Value.obj(arr);
}

/// `get Intl.{Number,DateTime}Format.prototype.format`: per spec `format` is an
/// accessor whose getter returns a function bound to this formatter instance,
/// created lazily and cached (so `nf.format === nf.format`). The bound function
/// has name "" and length 1. The underlying formatter is stored on the
/// prototype under the hidden `\x00fmtimpl` key.
/// en unit names for Intl.DurationFormat by style (singular/plural). "digital"
/// reuses the short forms for the date units.
fn durationUnitName(unit: []const u8, style: []const u8, plural: bool) []const u8 {
    const long = std.mem.eql(u8, style, "long");
    const narrow = std.mem.eql(u8, style, "narrow");
    const T = struct { u: []const u8, lo: []const u8, lp: []const u8, sh: []const u8, na: []const u8 };
    const table = [_]T{
        .{ .u = "years", .lo = "year", .lp = "years", .sh = "yr", .na = "y" },
        .{ .u = "months", .lo = "month", .lp = "months", .sh = "mth", .na = "m" },
        .{ .u = "weeks", .lo = "week", .lp = "weeks", .sh = "wk", .na = "w" },
        .{ .u = "days", .lo = "day", .lp = "days", .sh = "day", .na = "d" },
        .{ .u = "hours", .lo = "hour", .lp = "hours", .sh = "hr", .na = "h" },
        .{ .u = "minutes", .lo = "minute", .lp = "minutes", .sh = "min", .na = "min" },
        .{ .u = "seconds", .lo = "second", .lp = "seconds", .sh = "sec", .na = "s" },
        .{ .u = "milliseconds", .lo = "millisecond", .lp = "milliseconds", .sh = "ms", .na = "ms" },
        .{ .u = "microseconds", .lo = "microsecond", .lp = "microseconds", .sh = "\xce\xbcs", .na = "\xce\xbcs" },
        .{ .u = "nanoseconds", .lo = "nanosecond", .lp = "nanoseconds", .sh = "ns", .na = "ns" },
    };
    for (table) |t| if (std.mem.eql(u8, unit, t.u)) {
        if (narrow) return t.na;
        if (long) return if (plural) t.lp else t.lo;
        return t.sh;
    };
    return unit;
}

/// `Intl.DurationFormat.prototype.format(duration)` — en. Joins the non-zero
/// units as "<n> <unit>" with ", " (a pragmatic approximation; exact CLDR
/// list/unit patterns are not modeled).
/// ToDurationRecord + IsValidDurationRecord: read the ten unit fields, each an
/// integer (RangeError otherwise); at least one must be present (TypeError);
/// signs must agree, years/months/weeks stay under 2^32, and the combined
/// seconds magnitude under 2^53.
fn durationToRecord(self: *Interpreter, d: Value) value.HostError![10]f64 {
    var vals = std.mem.zeroes([10]f64);
    if (tIsTemporal(d, .duration)) {
        // A Temporal.Duration: read its internal slots, not the (tauntable)
        // prototype getters.
        vals = d.asObj().temporalData().?.dur;
        for (&vals) |*p| if (p.* == 0) {
            p.* = 0;
        };
    } else if (d.isString()) {
        // ToDurationRecord(string): ParseTemporalDurationString (RangeError on
        // malformed input). Signs are already consistent by construction.
        vals = try parseDurationString(self, d.asStr());
        for (&vals) |*p| if (p.* == 0) {
            p.* = 0; // normalize -0 to +0
        };
    } else if (d.isObject()) {
        var any = false;
        var sign: f64 = 0;
        inline for (duration_units, 0..) |u, i| {
            const v = try self.getProperty(d, u);
            if (!v.isUndefined()) {
                any = true;
                const n = try self.toNumberV(v);
                if (!std.math.isFinite(n) or @trunc(n) != n) return self.throwError("RangeError", "duration field must be an integer");
                vals[i] = if (n == 0) 0 else n; // normalize -0 to +0 (ToIntegerIfIntegral)
                if (n != 0) {
                    const s: f64 = if (n < 0) -1 else 1;
                    if (sign == 0) sign = s else if (sign != s) return self.throwError("RangeError", "duration fields must have a consistent sign");
                }
            }
        }
        if (!any) return self.throwError("TypeError", "duration object has no recognized fields");
    } else {
        // Numbers, booleans, bigint, null, undefined, symbol are not durations.
        return self.throwError("TypeError", "duration must be an object or string");
    }
    const two32: f64 = 4294967296.0;
    if (@abs(vals[0]) >= two32 or @abs(vals[1]) >= two32 or @abs(vals[2]) >= two32) return self.throwError("RangeError", "duration value out of range");
    // IsValidDurationRecord: abs(normalizedSeconds) must be < 2^53. The sum loses
    // precision in f64 right at the boundary, so a coarse f64 check rejects
    // clearly-oversized values (and guards the i128 conversion from overflow),
    // then the exact total in nanoseconds (i128) decides the boundary case.
    const norm_sec = vals[3] * 86400 + vals[4] * 3600 + vals[5] * 60 + vals[6] + vals[7] / 1000 + vals[8] / 1_000_000 + vals[9] / 1_000_000_000;
    if (@abs(norm_sec) >= 18014398509481984.0) return self.throwError("RangeError", "duration value out of range"); // 2^54
    const f2i = struct {
        fn c(x: f64) i128 {
            return @intFromFloat(x);
        }
    }.c;
    const total_ns: i128 = f2i(vals[3]) * 86_400_000_000_000 + f2i(vals[4]) * 3_600_000_000_000 + f2i(vals[5]) * 60_000_000_000 + f2i(vals[6]) * 1_000_000_000 + f2i(vals[7]) * 1_000_000 + f2i(vals[8]) * 1_000 + f2i(vals[9]);
    const abs_ns: i128 = if (total_ns < 0) -total_ns else total_ns;
    if (abs_ns >= 9007199254740992 * 1_000_000_000) return self.throwError("RangeError", "duration value out of range"); // 2^53 seconds
    return vals;
}

/// The resolved per-unit style for a DurationFormat unit (matching what
/// resolvedOptions reports): the explicit option, else the base style — with
/// "digital" making hours/minutes/seconds "numeric".
/// Digital style displays a zero "minutes" when a numeric "hours" precedes and
/// seconds (or sub-seconds) will be shown — "1:00:03" rather than "1:03".
fn durMinutesRequired(data: *const value.IntlDurationFormatData, need_sep: bool, unit_index: usize, vals: [10]f64) bool {
    if (unit_index != 5 or !need_sep) return false;
    return data.unit_displays[6] == .always or vals[6] != 0 or vals[7] != 0 or vals[8] != 0 or vals[9] != 0;
}

/// Format one duration unit value via a NumberFormat instance, mirroring the
/// reference algorithm: standalone styles use style:"unit"; numeric/2-digit use
/// plain digits (useGrouping:false, +2-digit padding); non-first units suppress
/// the sign. Returns the formatted string.
/// Build the NumberFormat instance used to format one duration unit's value.
fn durUnitNf(self: *Interpreter, locale: []const u8, numbering_system: ?[]const u8, style: []const u8, unit_singular: []const u8, sign_never: bool) value.HostError!Value {
    const ro = (try self.newObject()).asObj();
    if (numbering_system) |name|
        try self.setProp(ro, "numberingSystem", try Value.strAlloc(self.arena, name));
    const standalone = !std.mem.eql(u8, style, "numeric") and !std.mem.eql(u8, style, "2-digit");
    if (standalone) {
        try self.setProp(ro, "style", Value.str("unit"));
        try self.setProp(ro, "unit", try Value.strAlloc(self.arena, unit_singular));
        try self.setProp(ro, "unitDisplay", try Value.strAlloc(self.arena, style));
    } else {
        try self.setProp(ro, "useGrouping", Value.boolVal(false));
        if (std.mem.eql(u8, style, "2-digit")) try self.setProp(ro, "minimumIntegerDigits", Value.num(2));
    }
    if (sign_never) try self.setProp(ro, "signDisplay", Value.str("never"));
    const nf = (try self.newObject()).asObj();
    try installNumberFormatData(self, nf, locale, ro);
    return Value.obj(nf);
}

fn durFmtVal(self: *Interpreter, locale: []const u8, numbering_system: ?[]const u8, num: f64, style: []const u8, unit_singular: []const u8, sign_never: bool) value.HostError![]const u8 {
    return nfFormatOne(self, try durUnitNf(self, locale, numbering_system, style, unit_singular, sign_never), Value.num(num));
}

/// Format a combined fractional value (a decimal string like "444.055006") for a
/// unit whose resolved style is standalone (long/short/narrow): a unit-style
/// NumberFormat with trunc rounding and the fractional-digit bounds. The decimal
/// string is fed verbatim so precision matches the conformance reference, which
/// formats the same constructed string.
fn durFmtCombineUnit(self: *Interpreter, locale: []const u8, numbering_system: ?[]const u8, dec: []const u8, style: []const u8, unit_singular: []const u8, sign_never: bool, fd: ?usize) value.HostError![]const u8 {
    const ro = (try self.newObject()).asObj();
    if (numbering_system) |name|
        try self.setProp(ro, "numberingSystem", try Value.strAlloc(self.arena, name));
    try self.setProp(ro, "style", Value.str("unit"));
    try self.setProp(ro, "unit", try Value.strAlloc(self.arena, unit_singular));
    try self.setProp(ro, "unitDisplay", try Value.strAlloc(self.arena, style));
    try self.setProp(ro, "minimumFractionDigits", Value.num(if (fd) |f| @floatFromInt(f) else 0));
    try self.setProp(ro, "maximumFractionDigits", Value.num(if (fd) |f| @floatFromInt(f) else 9));
    try self.setProp(ro, "roundingMode", Value.str("trunc"));
    if (sign_never) try self.setProp(ro, "signDisplay", Value.str("never"));
    const nf = (try self.newObject()).asObj();
    try installNumberFormatData(self, nf, locale, ro);
    return nfFormatOne(self, Value.obj(nf), try Value.strAlloc(self.arena, dec));
}

fn durFmtCombineNumeric(self: *Interpreter, locale: []const u8, numbering_system: ?[]const u8, dec: []const u8, min_int: usize, sign_never: bool, fd: ?usize) value.HostError![]const u8 {
    const ro = (try self.newObject()).asObj();
    if (numbering_system) |name|
        try self.setProp(ro, "numberingSystem", try Value.strAlloc(self.arena, name));
    try self.setProp(ro, "useGrouping", Value.boolVal(false));
    try self.setProp(ro, "minimumIntegerDigits", Value.num(@floatFromInt(min_int)));
    try self.setProp(ro, "minimumFractionDigits", Value.num(if (fd) |f| @floatFromInt(f) else 0));
    try self.setProp(ro, "maximumFractionDigits", Value.num(if (fd) |f| @floatFromInt(f) else 9));
    if (sign_never) try self.setProp(ro, "signDisplay", Value.str("never"));
    const nf = (try self.newObject()).asObj();
    try installNumberFormatData(self, nf, locale, ro);
    return nfFormatOne(self, Value.obj(nf), try Value.strAlloc(self.arena, dec));
}

/// The combined sub-second total for `unit` is non-zero (so it must display even
/// when the unit's own value is 0, e.g. seconds 0 with milliseconds present).
fn durCombineNonzero(vals: [10]f64, unit: []const u8) bool {
    const lo: usize = if (std.mem.eql(u8, unit, "seconds")) 6 else if (std.mem.eql(u8, unit, "milliseconds")) 7 else 8;
    var k = lo;
    while (k < 10) : (k += 1) if (vals[k] != 0) return true;
    return false;
}

/// NumberFormat already observes a supported `-u-nu-` extension in the locale.
/// Forward a separate option only when InitializeDurationFormat selected a
/// different system (normally an explicit non-default numberingSystem).
fn durNumberingOption(data: *const value.IntlDurationFormatData) ?[]const u8 {
    const locale_system = localeUValue(data.locale, "nu") orelse localeDefaultNumberingSystem(data.locale);
    return if (std.mem.eql(u8, locale_system, data.numbering_system)) null else data.numbering_system;
}

/// DurationToFractional: combine `unit` with its finer sub-second units into one
/// exact fractional value (integer arithmetic, no f64 precision loss), formatted
/// as a digit string truncated to `max_f` fraction digits then trimmed to
/// `min_f`. A leading "-" is added only when this is the sign-bearing unit.
fn durCombineFrac(allocator: std.mem.Allocator, vals: [10]f64, unit: []const u8, max_f: usize, min_f: usize, sign_never: bool, min_int: usize) value.HostError![]const u8 {
    const sec: i128 = @intFromFloat(vals[6]);
    const ms: i128 = @intFromFloat(vals[7]);
    const us: i128 = @intFromFloat(vals[8]);
    const ns: i128 = @intFromFloat(vals[9]);
    var exp: usize = 9;
    var total: i128 = 0;
    if (std.mem.eql(u8, unit, "seconds")) {
        exp = 9;
        total = sec * 1_000_000_000 + ms * 1_000_000 + us * 1_000 + ns;
    } else if (std.mem.eql(u8, unit, "milliseconds")) {
        exp = 6;
        total = ms * 1_000_000 + us * 1_000 + ns;
    } else {
        exp = 3;
        total = us * 1_000 + ns;
    }
    const neg = total < 0;
    const at: i128 = if (neg) -total else total;
    var e10: i128 = 1;
    for (0..exp) |_| e10 *= 10;
    const q = @divTrunc(at, e10);
    const fr = @rem(at, e10);
    // Fraction digits: `fr` left-padded to `exp`, truncated to max_f, trimmed to min_f.
    var fdig = try std.fmt.allocPrint(allocator, "{d}", .{fr});
    while (fdig.len < exp) fdig = try std.fmt.allocPrint(allocator, "0{s}", .{fdig});
    var flen: usize = @min(fdig.len, max_f); // trunc rounding
    while (flen > min_f and fdig[flen - 1] == '0') flen -= 1;
    var idig = try std.fmt.allocPrint(allocator, "{d}", .{q});
    while (idig.len < min_int) idig = try std.fmt.allocPrint(allocator, "0{s}", .{idig});
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    if (neg and !sign_never) try buf.append(allocator, '-');
    try buf.appendSlice(allocator, idig);
    if (flen > 0) {
        try buf.append(allocator, '.');
        try buf.appendSlice(allocator, fdig[0..flen]);
    }
    return buf.toOwnedSlice(allocator);
}

fn intlDurationFormatFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject() or this.asObj().intlDurationFormatData() == null)
        return self.throwError("TypeError", "Intl.DurationFormat.prototype.format on incompatible receiver");
    const data = this.asObj().intlDurationFormatData().?;
    const d = if (args.len > 0) args[0] else Value.undef();
    const vals = try durationToRecord(self, d);
    const base = data.style.string();
    const locale = data.locale;
    const numbering_system = durNumberingOption(data);

    // Build the list of formatted items. Consecutive numeric/2-digit units join
    // with ":" into one item (digital style); standalone units are separate
    // items joined with ", " (en ListFormat type:unit). Mirrors the spec.
    var items: std.ArrayListUnmanaged([]const u8) = .empty;
    var need_sep = false; // previous unit was numeric/2-digit
    var first = true;
    const dur_neg = blk: {
        for (vals) |vv| if (vv < 0) break :blk true;
        break :blk false;
    };
    inline for (duration_units, 0..) |u, i| {
        const uval = vals[i];
        const unit_style = data.unit_styles[i];
        const style = unit_style.string();
        // seconds/milliseconds/microseconds fold their finer units into a
        // fraction when the next-finer unit resolved to a numeric style.
        const combine = (i == 6 or i == 7 or i == 8) and data.unit_styles[i + 1] == .numeric;
        const shown = uval != 0 or data.unit_displays[i] != .auto or durMinutesRequired(data, need_sep, i, vals) or (combine and durCombineNonzero(vals, u));
        if (shown) {
            const sign_never = !first;
            const is_first = first;
            first = false;
            // First displayed unit bears the sign; a zero first unit shows "-0"
            // when the overall duration is negative (DurationToFractional / -0).
            const fnum = if (is_first and uval == 0 and dur_neg) -@as(f64, 0.0) else uval;
            const min_int: usize = if (unit_style == .two_digit) 2 else 1;
            const numeric = unit_style.isNumeric();
            const s = if (combine) blk: {
                const fd: ?usize = if (data.fractional_digits) |digits| digits else null;
                const dec = try durCombineFrac(self.arena, vals, u, fd orelse 9, fd orelse 0, sign_never, min_int);
                // A standalone-styled combine unit renders the fractional value
                // with its unit name ("444.055006 millisecond"); numeric/2-digit
                // units stay bare digits for the ":"-joined run.
                if (numeric) break :blk try durFmtCombineNumeric(self, locale, numbering_system, dec, min_int, sign_never, fd);
                break :blk try durFmtCombineUnit(self, locale, numbering_system, dec, style, u[0 .. u.len - 1], sign_never, fd);
            } else try durFmtVal(self, locale, numbering_system, fnum, style, u[0 .. u.len - 1], sign_never);
            // Once a numeric run starts (need_sep latches), every later unit
            // appends to it with ":" — even standalone ones (digital
            // "4:5:6:7 millisecond").
            if (need_sep and items.items.len > 0) {
                items.items[items.items.len - 1] = try std.fmt.allocPrint(self.arena, "{s}:{s}", .{ items.items[items.items.len - 1], s });
            } else {
                try items.append(self.arena, s);
                if (numeric) need_sep = true;
            }
        }
        if (combine and shown) break; // sub-seconds folded into this unit; done
    }
    // Join the items as a type:"unit" list (locale + style aware; digital uses
    // the short list style).
    const lstyle = if (data.style == .digital) "short" else base;
    const uc = unitConnectors(localeLanguage(locale), lstyle);
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    for (items.items, 0..) |it, idx| {
        if (idx != 0) {
            const sep = if (idx == items.items.len - 1) (if (items.items.len == 2) uc.pair else uc.fin) else uc.mid;
            try buf.appendSlice(self.arena, sep);
        }
        try buf.appendSlice(self.arena, it);
    }
    return try Value.strOwned(self.arena, try buf.toOwnedSlice(self.arena));
}

const DurPart = struct { typ: NfPartType, value: []const u8, unit: ?[]const u8 };

fn intlDurationFormatToPartsFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject() or this.asObj().intlDurationFormatData() == null)
        return self.throwError("TypeError", "Intl.DurationFormat.prototype.formatToParts on incompatible receiver");
    const data = this.asObj().intlDurationFormatData().?;
    const d = if (args.len > 0) args[0] else Value.undef();
    const vals = try durationToRecord(self, d);
    const base = data.style.string();
    const locale = data.locale;
    const numbering_system = durNumberingOption(data);
    const number_symbols = localeNumberSymbols(locale, data.numbering_system);

    // Each group is one ListFormat "element" (a unit, or a ":"-joined numeric run).
    var scratch_arena = std.heap.ArenaAllocator.init(self.scratch_allocator orelse gc_mod.temporaryAllocator(self.arena));
    defer scratch_arena.deinit();
    const scratch = scratch_arena.allocator();
    var groups: std.ArrayListUnmanaged(std.ArrayListUnmanaged(DurPart)) = .empty;
    var need_sep = false;
    var first = true;
    const dur_neg = blk: {
        for (vals) |vv| if (vv < 0) break :blk true;
        break :blk false;
    };
    inline for (duration_units, 0..) |u, i| {
        const uval = vals[i];
        const unit_style = data.unit_styles[i];
        const style = unit_style.string();
        // seconds/milliseconds/microseconds fold their finer units into a
        // fraction when the next-finer unit resolved to a numeric style.
        const combine = (i == 6 or i == 7 or i == 8) and data.unit_styles[i + 1] == .numeric;
        const shown = uval != 0 or data.unit_displays[i] != .auto or durMinutesRequired(data, need_sep, i, vals) or (combine and durCombineNonzero(vals, u));
        if (shown) {
            const sign_never = !first;
            const is_first = first;
            first = false;
            const fnum = if (is_first and uval == 0 and dur_neg) -@as(f64, 0.0) else uval;
            const sing = u[0 .. u.len - 1];
            const numeric = unit_style.isNumeric();
            var grp: *std.ArrayListUnmanaged(DurPart) = undefined;
            if (need_sep and groups.items.len > 0) {
                grp = &groups.items[groups.items.len - 1];
                try grp.append(scratch, .{ .typ = .literal, .value = ":", .unit = null });
            } else {
                try groups.append(scratch, .empty);
                grp = &groups.items[groups.items.len - 1];
                if (numeric) need_sep = true;
            }
            if (combine) {
                // Parse the exact "[-]int[.frac]" combine string into typed parts.
                const fd: ?usize = if (data.fractional_digits) |digits| digits else null;
                const min_int: usize = if (unit_style == .two_digit) 2 else 1;
                var s = try durCombineFrac(scratch, vals, u, fd orelse 9, fd orelse 0, sign_never, min_int);
                if (s.len > 0 and s[0] == '-') {
                    try grp.append(scratch, .{ .typ = .minus_sign, .value = "-", .unit = sing });
                    s = s[1..];
                }
                if (std.mem.indexOfScalar(u8, s, '.')) |dot| {
                    try grp.append(scratch, .{ .typ = .integer, .value = try rtfTranslateNumberAlloc(scratch, s[0..dot], data.numbering_system), .unit = sing });
                    try grp.append(scratch, .{ .typ = .decimal, .value = number_symbols.decimal, .unit = sing });
                    try grp.append(scratch, .{ .typ = .fraction, .value = try rtfTranslateNumberAlloc(scratch, s[dot + 1 ..], data.numbering_system), .unit = sing });
                } else {
                    try grp.append(scratch, .{ .typ = .integer, .value = try rtfTranslateNumberAlloc(scratch, s, data.numbering_system), .unit = sing });
                }
            } else {
                const nf_parts = try nfBuildParts(self, try durUnitNf(self, locale, numbering_system, style, sing, sign_never), &.{Value.num(fnum)}, scratch);
                for (nf_parts.items) |p| try grp.append(scratch, .{ .typ = p.typ, .value = p.value, .unit = sing });
            }
        }
        if (combine and shown) break;
    }
    // Flatten: a type:"unit" list literal between element groups (locale/style aware).
    const lstyle = if (data.style == .digital) "short" else base;
    const uc = unitConnectors(localeLanguage(locale), lstyle);
    const arr = (try self.newArray()).asObj();
    for (groups.items, 0..) |grp, gi| {
        if (gi != 0) {
            const sep = if (gi == groups.items.len - 1) (if (groups.items.len == 2) uc.pair else uc.fin) else uc.mid;
            const lo = (try self.newObject()).asObj();
            try self.setProp(lo, "type", Value.str("literal"));
            try self.setProp(lo, "value", try Value.strAlloc(self.arena, sep));
            try arr.appendElement(self.arena, Value.obj(lo));
        }
        for (grp.items) |p| {
            const o = (try self.newObject()).asObj();
            try self.setProp(o, "type", p.typ.value());
            try self.setProp(o, "value", try Value.strAlloc(self.arena, p.value));
            if (p.unit) |un| try self.setProp(o, "unit", try Value.strAlloc(self.arena, un));
            try arr.appendElement(self.arena, Value.obj(o));
        }
    }
    return Value.obj(arr);
}

/// `get Intl.<service>.prototype.<prop>`: per spec `format`/`compare` are
/// accessors whose getter returns a function bound to this instance, created
/// lazily and cached (so `c.compare === c.compare`). The bound function has
/// name "" and the given length. The underlying impl is stored on the prototype
/// under `impl_key`; the cached bound function under `cache_key`.
fn intlBoundAccessorFn(comptime service: []const u8, comptime prop: []const u8, comptime impl_key: []const u8, comptime cache_key: []const u8, comptime length: f64) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            _ = args;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            const target = if (comptime std.mem.eql(u8, service, "NumberFormat") or std.mem.eql(u8, service, "DateTimeFormat"))
                (try unwrapIntlThis(self, this, service)) orelse return self.throwError("TypeError", "get Intl." ++ service ++ ".prototype." ++ prop ++ " called on incompatible receiver")
            else blk: {
                const branded = if (comptime std.mem.eql(u8, service, "Collator"))
                    this.isObject() and this.asObj().intlCollatorData() != null
                else
                    intlBrandOk(this, service);
                if (!branded) return self.throwError("TypeError", "get Intl." ++ service ++ ".prototype." ++ prop ++ " called on incompatible receiver");
                break :blk this;
            };
            if (target.asObj().getOwn(cache_key)) |b| return b;
            const impl = try self.getProperty(target, impl_key);
            if (!impl.isObject()) return self.throwError("TypeError", "missing " ++ prop ++ " implementation");
            // ECMA-402 Get*Format constructs the cached callable with exact
            // metadata; generic bind name/length discovery is neither required
            // nor observable here. Publish once under the formatter property
            // lock so concurrent first reads share one identity.
            const bound = try self.makeBoundExact(impl.asObj(), target, &.{}, length, Value.str(""));
            return (try target.asObj().setOwnIfAbsentWithAttr(
                self.arena,
                self.root_shape,
                cache_key,
                bound,
                .{ .writable = false, .enumerable = false, .configurable = false },
            )) orelse bound;
        }
    }.call;
}

/// Install the `format` accessor + hidden `\x00fmtimpl` on a formatter prototype.
fn installIntlFormat(a: std.mem.Allocator, rs: *Shape, proto: *value.Object, comptime service: []const u8, impl_fn: value.NativeFn) EvalError!void {
    const impl = try gc_mod.allocObj(a);
    impl.* = .{ .native = impl_fn };
    try installNativeProps(a, rs, impl, "format", 1);
    try proto.setOwn(a, rs, "\x00fmtimpl", Value.obj(impl));
    try proto.setAttr(a, "\x00fmtimpl", .{ .writable = false, .enumerable = false, .configurable = false });
    try setNativeGetter(a, rs, proto, "format", intlBoundAccessorFn(service, "format", "\x00fmtimpl", "\x00boundFormat", 1));
}

/// Install the Collator `compare` accessor + hidden `\x00cmpimpl`.
fn installIntlCompare(a: std.mem.Allocator, rs: *Shape, proto: *value.Object, impl_fn: value.NativeFn) EvalError!void {
    const impl = try gc_mod.allocObj(a);
    impl.* = .{ .native = impl_fn };
    try installNativeProps(a, rs, impl, "compare", 2);
    try proto.setOwn(a, rs, "\x00cmpimpl", Value.obj(impl));
    try proto.setAttr(a, "\x00cmpimpl", .{ .writable = false, .enumerable = false, .configurable = false });
    try setNativeGetter(a, rs, proto, "compare", intlBoundAccessorFn("Collator", "compare", "\x00cmpimpl", "\x00boundCompare", 2));
}

fn intlCollatorCompareFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return self.throwError("TypeError", "Intl.Collator.prototype.compare on incompatible receiver");
    const data = this.asObj().intlCollatorData() orelse return self.throwError("TypeError", "Intl.Collator.prototype.compare on incompatible receiver");
    const x = try self.toStringWtf8(if (args.len > 0) args[0] else Value.undef());
    const y = try self.toStringWtf8(if (args.len > 1) args[1] else Value.undef());
    return Value.num(try collatorCompareStrings(self, x, y, data.*));
}

/// ECMA-402 plural categories are a closed vocabulary. Keep them native while
/// evaluating CLDR rules, then expose process-lifetime immutable string cells
/// instead of allocating structural result strings for every selection.
const PluralCategory = enum {
    zero,
    one,
    two,
    few,
    many,
    other,

    fn fromString(name: []const u8) ?PluralCategory {
        if (std.mem.eql(u8, name, "zero")) return .zero;
        if (std.mem.eql(u8, name, "one")) return .one;
        if (std.mem.eql(u8, name, "two")) return .two;
        if (std.mem.eql(u8, name, "few")) return .few;
        if (std.mem.eql(u8, name, "many")) return .many;
        if (std.mem.eql(u8, name, "other")) return .other;
        return null;
    }

    fn value(self: PluralCategory) Value {
        return switch (self) {
            .zero => Value.str("zero"),
            .one => Value.str("one"),
            .two => Value.str("two"),
            .few => Value.str("few"),
            .many => Value.str("many"),
            .other => Value.str("other"),
        };
    }
};

const plural_category_order = [_]PluralCategory{ .zero, .one, .two, .few, .many, .other };

/// LDML plural-rule operands derived from a number formatted with the given
/// fraction-digit bounds: n (value), i (integer part), v/f (fraction digits with
/// trailing zeros — count/value), w/t (without trailing zeros), e (exponent).
const PluralOperands = struct { n: f64, i: f64, v: f64, w: f64, f: f64, t: f64, e: f64 };

fn pluralOperands(num: f64, min_frac: usize, max_frac: usize) PluralOperands {
    const abs = @abs(num);
    if (!std.math.isFinite(abs)) return .{ .n = abs, .i = abs, .v = 0, .w = 0, .f = 0, .t = 0, .e = 0 };
    var scale: f64 = 1;
    for (0..max_frac) |_| scale *= 10;
    const scaled = @round(abs * scale); // value * 10^maxFrac, rounded
    const n = if (scale == 0) abs else scaled / scale;
    const ipart = @floor(n);
    // Fraction digits (integer 0..scale-1), padded to max_frac.
    const frac_int: u64 = if (scale == 0) 0 else @intFromFloat(@round((n - ipart) * scale));
    var fbuf: [20]u8 = undefined;
    const fs = std.fmt.bufPrint(&fbuf, "{d}", .{frac_int}) catch "0";
    var digits: [40]u8 = undefined;
    var dlen: usize = 0;
    while (dlen + fs.len < max_frac) : (dlen += 1) digits[dlen] = '0'; // left-pad
    for (fs) |c| {
        digits[dlen] = c;
        dlen += 1;
    }
    if (max_frac == 0) dlen = 0;
    // Displayed width: trim trailing zeros down to min_frac.
    var v = dlen;
    while (v > min_frac and digits[v - 1] == '0') v -= 1;
    // Without trailing zeros at all.
    var w = v;
    while (w > 0 and digits[w - 1] == '0') w -= 1;
    const f: f64 = if (v == 0) 0 else @floatFromInt(std.fmt.parseInt(u64, digits[0..v], 10) catch 0);
    const t: f64 = if (w == 0) 0 else @floatFromInt(std.fmt.parseInt(u64, digits[0..w], 10) catch 0);
    return .{ .n = n, .i = ipart, .v = @floatFromInt(v), .w = @floatFromInt(w), .f = f, .t = t, .e = 0 };
}

fn pluralOperandValue(c: u8, ops: PluralOperands) f64 {
    return switch (c) {
        'n' => ops.n,
        'i' => ops.i,
        'v' => ops.v,
        'w' => ops.w,
        'f' => ops.f,
        't' => ops.t,
        'e', 'c' => ops.e,
        else => 0,
    };
}

/// Does `val` satisfy the LDML range-list (e.g. "3..10" or "0,1")? A range only
/// matches an integral value within [lo, hi].
fn pluralRangeListMatch(list: []const u8, val: f64) bool {
    var items = std.mem.splitScalar(u8, list, ',');
    while (items.next()) |item| {
        if (std.mem.indexOf(u8, item, "..")) |dd| {
            const lo = std.fmt.parseFloat(f64, item[0..dd]) catch continue;
            const hi = std.fmt.parseFloat(f64, item[dd + 2 ..]) catch continue;
            if (val == @floor(val) and val >= lo and val <= hi) return true;
        } else {
            const x = std.fmt.parseFloat(f64, item) catch continue;
            if (val == x) return true;
        }
    }
    return false;
}

/// Evaluate one LDML relation: "operand [% mod] (= | !=) range-list".
fn pluralEvalRel(rel: []const u8, ops: PluralOperands) bool {
    var toks = std.mem.tokenizeScalar(u8, rel, ' ');
    const opnd = toks.next() orelse return false;
    var val = pluralOperandValue(opnd[0], ops);
    var nxt = toks.next() orelse return false;
    if (std.mem.eql(u8, nxt, "%")) {
        const m = std.fmt.parseFloat(f64, toks.next() orelse return false) catch return false;
        if (m != 0) val = @rem(val, m);
        nxt = toks.next() orelse return false;
    }
    const list = toks.next() orelse return false;
    const isin = pluralRangeListMatch(list, val);
    return if (std.mem.eql(u8, nxt, "!=")) !isin else isin;
}

/// Evaluate an LDML plural condition (and/or of relations); "" is always true.
fn pluralEvalCond(cond: []const u8, ops: PluralOperands) bool {
    if (cond.len == 0) return true;
    var ors = std.mem.splitSequence(u8, cond, " or ");
    while (ors.next()) |term| {
        var all = true;
        var ands = std.mem.splitSequence(u8, term, " and ");
        while (ands.next()) |rel| {
            if (!pluralEvalRel(rel, ops)) {
                all = false;
                break;
            }
        }
        if (all) return true;
    }
    return false;
}

/// PluralRuleSelect: the first category whose rule matches, else "other".
fn pluralCategory(rules: []const cldr_plurals.Rule, ops: PluralOperands) PluralCategory {
    for (rules) |r| {
        if (r.cond.len > 0 and pluralEvalCond(r.cond, ops)) return PluralCategory.fromString(r.cat) orelse .other;
    }
    return .other;
}

/// The language subtag (lowercased) of a stored locale tag.
fn localeLanguage(tag: []const u8) []const u8 {
    const end = std.mem.indexOfScalar(u8, tag, '-') orelse tag.len;
    return tag[0..end];
}

fn pluralRulesFor(data: *const value.IntlPluralRulesData) []const cldr_plurals.Rule {
    const lang = localeLanguage(data.locale);
    const rules = if (data.kind == .ordinal) cldr_plurals.ordinal(lang) else cldr_plurals.cardinal(lang);
    // Fall back to English cardinal (one/other) when a language has no data.
    return rules orelse (cldr_plurals.cardinal("en") orelse &.{});
}

fn pluralFracDigits(data: *const value.IntlPluralRulesData) struct { min: usize, max: usize } {
    return .{ .min = data.minimum_fraction_digits, .max = data.maximum_fraction_digits };
}

fn intlPluralSelectFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject() or this.asObj().intlPluralRulesData() == null)
        return self.throwError("TypeError", "Intl.PluralRules.prototype.select on incompatible receiver");
    const data = this.asObj().intlPluralRulesData().?;
    const n = try self.toNumberV(if (args.len > 0) args[0] else Value.undef());
    if (std.math.isNan(n)) return Value.str("other");
    const fd = pluralFracDigits(data);
    var ops = pluralOperands(n, fd.min, fd.max);
    // The exponent operand (e/c) for scientific/engineering/compact notation.
    const absn = @abs(n);
    if (absn != 0 and std.math.isFinite(absn) and data.notation != .standard) {
        const oom = orderOfMagnitude(absn);
        ops.e = @floatFromInt(if (data.notation == .scientific)
            oom
        else if (data.notation == .engineering)
            @divFloor(oom, 3) * 3
        else if (oom >= 3) // compact: a multiple-of-three magnitude >= 1000
            @divFloor(oom, 3) * 3
        else
            @as(i32, 0));
    }
    return pluralCategory(pluralRulesFor(data), ops).value();
}

/// One element of a ListFormat result: an "element" (a list item) or a
/// "literal" (the connector text between items).
const LfPartType = enum {
    element,
    literal,

    fn value(self: LfPartType) Value {
        return switch (self) {
            .element => Value.str("element"),
            .literal => Value.str("literal"),
        };
    }
};
const LfPart = struct { typ: LfPartType, value: []const u8 };

/// type:"unit" list connectors (pair / middle / final) by language + style —
/// shared by Intl.ListFormat and DurationFormat's unit joining: narrow joins
/// with spaces; es joins with "y" (long ends with "y", short with ", ").
const UnitConn = struct { pair: []const u8, mid: []const u8, fin: []const u8 };
fn unitConnectors(lang: []const u8, style: []const u8) UnitConn {
    if (std.mem.eql(u8, style, "narrow")) return .{ .pair = " ", .mid = " ", .fin = " " };
    if (std.mem.eql(u8, lang, "es")) return .{ .pair = " y ", .mid = ", ", .fin = if (std.mem.eql(u8, style, "short")) ", " else " y " };
    return .{ .pair = ", ", .mid = ", ", .fin = ", " };
}

/// Build the ListFormat parts for `args[0]` (en). The connectors depend on the
/// instance's `type` (conjunction "and" / disjunction "or" / unit none).
fn lfBuildParts(self: *Interpreter, this: Value, args: []const Value) value.HostError!std.ArrayListUnmanaged(LfPart) {
    var parts: std.ArrayListUnmanaged(LfPart) = .empty;
    const v = if (args.len > 0) args[0] else Value.undef();
    if (v.isUndefined()) return parts;
    // StringListFromIterable: drain the iterator, type-checking each value and
    // closing the iterator on the first non-string (the list is not fully
    // consumed past the offending element).
    var strs: std.ArrayListUnmanaged([]const u8) = .empty;
    const record = try self.getIteratorRecord(v);
    const it = record.iterator;
    const iter_root = try self.pushTempRoot(it);
    defer self.restoreTempRoots(iter_root);
    const next_method = record.next_method;
    const next_root = try self.pushTempRoot(next_method);
    defer self.restoreTempRoots(next_root);
    while (true) {
        const r = try self.callValueWithThis(next_method, &.{}, it);
        if (!builtins.isRealObject(r)) return self.throwError("TypeError", "iterator result is not an object");
        if ((try self.getProperty(r, "done")).toBoolean()) break;
        const nv = try self.getProperty(r, "value");
        if (!nv.isString()) {
            self.exception = try self.makeError("TypeError", "Intl.ListFormat: list items must be strings");
            self.iteratorCloseKeepingThrow(it);
            try self.notifyDebuggerException(false);
            return error.Throw;
        }
        try strs.append(self.arena, try nv.asWtf8(self.arena));
    }
    const list = strs.items;
    const data = this.asObj().intlListFormatData() orelse
        return self.throwError("TypeError", "Intl.ListFormat has no resolved state");
    const typ = data.kind.string();
    const style = data.style.string();
    // en connectors by type+style: pair (two items) / final (≥3) / middle.
    const is_unit = std.mem.eql(u8, typ, "unit");
    const is_disj = std.mem.eql(u8, typ, "disjunction");
    const narrow = std.mem.eql(u8, style, "narrow");
    const short = std.mem.eql(u8, style, "short");
    const lang = localeLanguage(data.locale);
    const es = std.mem.eql(u8, lang, "es");
    var middle: []const u8 = ", ";
    var pair: []const u8 = " and ";
    var final: []const u8 = ", and ";
    if (is_unit) {
        const uc = unitConnectors(lang, style);
        pair = uc.pair;
        middle = uc.mid;
        final = uc.fin;
    } else if (is_disj) {
        // es disjunction "o" (no comma before the final); en "or".
        pair = if (es) " o " else " or ";
        final = if (es) " o " else ", or ";
    } else if (narrow) { // conjunction
        middle = " ";
        pair = " ";
        final = " ";
    } else if (es) { // es conjunction "y" (no comma before the final)
        pair = " y ";
        final = " y ";
    } else if (short) {
        pair = " & ";
        final = ", & ";
    }
    for (list, 0..) |item, i| {
        if (i != 0) {
            const sep = if (i == list.len - 1) (if (list.len == 2) pair else final) else middle;
            try parts.append(self.arena, .{ .typ = .literal, .value = sep });
        }
        try parts.append(self.arena, .{ .typ = .element, .value = item });
    }
    return parts;
}

// ---- Intl.Segmenter segmentation (byte-offset, code-point aware) -----------

const SegmenterGranularity = value.IntlSegmenterData.Granularity;

/// One immutable Segmenter input. The retained Value is the observable `input`
/// field and roots the bytes; representation-aware reads avoid rebuilding the
/// complete string when flat-Latin1 storage is enabled.
const SegmenterInput = struct {
    value: Value,
    bytes: []const u8,
    flat_latin1: bool,

    fn fromValue(self: *Interpreter, input: Value) EvalError!SegmenterInput {
        std.debug.assert(input.isString());
        const flat = input.strIsFlatLatin1();
        return .{
            .value = input,
            .bytes = if (flat) input.asStr() else try input.asWtf8(self.arena),
            .flat_latin1 = flat,
        };
    }

    fn utf16Index(self: SegmenterInput, byte_offset: usize) usize {
        return if (self.flat_latin1) byte_offset else Interpreter.utf16IndexForByteOffset(self.bytes, byte_offset);
    }

    fn utf16Len(self: SegmenterInput) usize {
        return if (self.flat_latin1) self.bytes.len else Interpreter.utf16LenOfString(self.bytes);
    }

    fn segmentValue(self: SegmenterInput, allocator: std.mem.Allocator, start: usize, end: usize) std.mem.Allocator.Error!Value {
        if (self.flat_latin1) {
            return try Value.strOwned(allocator, try strcell.latin1FlatToWtf8(allocator, self.bytes[start..end]));
        }
        return try Value.strOwned(allocator, try allocator.dupe(u8, self.bytes[start..end]));
    }
};

/// ECMA-262 ToString, preserving an existing immutable string Value so every
/// segment-data record can reference the single coercion result.
fn segmenterToStringValue(self: *Interpreter, input: Value) EvalError!Value {
    if (input.isObject() and input.asObj().is_symbol)
        return self.throwError("TypeError", "Cannot convert a Symbol value to a string");
    const primitive = if (input.isObject()) try self.toPrimitive(input, .string) else input;
    if (primitive.isObject() and primitive.asObj().is_symbol)
        return self.throwError("TypeError", "Cannot convert a Symbol value to a string");
    if (primitive.isString()) return primitive;
    return try Value.strAlloc(self.arena, try primitive.toString(self.arena));
}

fn segScalarLen(input: SegmenterInput, pos: usize) usize {
    if (input.flat_latin1) return 1;
    if (wtf8SurrogateAt(input.bytes, pos) != null) return 3;
    return utf8SeqLen(input.bytes, pos);
}

fn segCodePoint(input: SegmenterInput, pos: usize) u21 {
    if (input.flat_latin1) return input.bytes[pos];
    if (wtf8SurrogateAt(input.bytes, pos)) |cp| return cp;
    const n = utf8SeqLen(input.bytes, pos);
    if (n == 1) return input.bytes[pos];
    return std.unicode.utf8Decode(input.bytes[pos .. pos + n]) catch input.bytes[pos];
}

fn gbClassOf(cp: u21) gbd.Class {
    var lo: usize = 0;
    var hi: usize = gbd.gb_class.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const e = gbd.gb_class[mid];
        if (cp < e.lo) hi = mid else if (cp > e.hi) lo = mid + 1 else return e.v;
    }
    return .other;
}
fn gbIsExtPict(cp: u21) bool {
    var lo: usize = 0;
    var hi: usize = gbd.ext_pictographic.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const e = gbd.ext_pictographic[mid];
        if (cp < e.lo) hi = mid else if (cp > e.hi) lo = mid + 1 else return true;
    }
    return false;
}
fn gbIncbOf(cp: u21) ?gbd.Incb {
    var lo: usize = 0;
    var hi: usize = gbd.incb.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const e = gbd.incb[mid];
        if (cp < e.lo) hi = mid else if (cp > e.hi) lo = mid + 1 else return e.v;
    }
    return null;
}
/// Decode one scalar at `pos`, combining a UTF-16 surrogate pair (for strings
/// stored with the paired-surrogate encoding) into the astral code point.
fn segScalar(input: SegmenterInput, pos: usize) struct { cp: u21, len: usize } {
    const cp0 = segCodePoint(input, pos);
    const l0 = segScalarLen(input, pos);
    if (isHighSurrogate(cp0) and pos + l0 < input.bytes.len) {
        const cp1 = segCodePoint(input, pos + l0);
        if (isLowSurrogate(cp1)) {
            const astral: u21 = 0x10000 + ((@as(u21, cp0) - 0xD800) << 10) + (@as(u21, cp1) - 0xDC00);
            return .{ .cp = astral, .len = l0 + segScalarLen(input, pos + l0) };
        }
    }
    return .{ .cp = cp0, .len = l0 };
}
/// Advance one UAX #29 extended grapheme cluster from byte `pos`.
fn segNextGrapheme(input: SegmenterInput, pos: usize) usize {
    const len = input.bytes.len;
    var s = segScalar(input, pos);
    var end = pos + s.len;
    if (end >= len) return end;
    var pcls = gbClassOf(s.cp);
    // GB11 (emoji ZWJ sequence): 0 none, 1 = ExtPict Extend*, 2 = …ZWJ.
    var re11: u8 = if (gbIsExtPict(s.cp)) 1 else 0;
    // GB9c (Indic conjunct): 0 none, 1 = Consonant …, 2 = … with a Linker seen.
    var incb: u8 = if (gbIncbOf(s.cp) == .consonant) 1 else 0;
    // GB12/13 (regional indicators): consecutive RI count.
    var ri: usize = if (pcls == .ri) 1 else 0;
    while (end < len) {
        const n = segScalar(input, end);
        const cls = gbClassOf(n.cp);
        const iv = gbIncbOf(n.cp);
        var brk = true;
        if (pcls == .cr and cls == .lf) {
            brk = false; // GB3
        } else if (pcls == .control or pcls == .cr or pcls == .lf or cls == .control or cls == .cr or cls == .lf) {
            brk = true; // GB4/GB5
        } else if (pcls == .l and (cls == .l or cls == .v or cls == .lv or cls == .lvt)) {
            brk = false; // GB6
        } else if ((pcls == .lv or pcls == .v) and (cls == .v or cls == .t)) {
            brk = false; // GB7
        } else if ((pcls == .lvt or pcls == .t) and cls == .t) {
            brk = false; // GB8
        } else if (cls == .extend or cls == .zwj) {
            brk = false; // GB9
        } else if (cls == .spacingmark) {
            brk = false; // GB9a
        } else if (pcls == .prepend) {
            brk = false; // GB9b
        } else if (incb == 2 and iv == .consonant) {
            brk = false; // GB9c
        } else if (re11 == 2 and gbIsExtPict(n.cp)) {
            brk = false; // GB11
        } else if (pcls == .ri and cls == .ri and (ri % 2 == 1)) {
            brk = false; // GB12/GB13
        }
        if (brk) break;
        end += n.len;
        // Update trailing state.
        if (iv == .consonant) {
            incb = 1;
        } else if (incb >= 1 and iv == .linker) {
            incb = 2;
        } else if (incb >= 1 and iv == .incb_extend) {
            // keep incb
        } else if (iv == null) {
            incb = 0;
        }
        if (gbIsExtPict(n.cp)) {
            re11 = 1;
        } else if (re11 >= 1 and cls == .extend) {
            re11 = 1;
        } else if (re11 == 1 and cls == .zwj) {
            re11 = 2;
        } else {
            re11 = 0;
        }
        if (cls == .ri) {
            ri = if (pcls == .ri) ri + 1 else 1;
        } else ri = 0;
        pcls = cls;
        s = n;
    }
    return end;
}

/// Whether the code point starting at `str[pos]` is "word-like" (letters/digits).
/// ASCII is classified exactly; any non-ASCII byte is treated as a letter (the
/// structural Segmenter tests don't require precise UAX#29 categories).
fn segWordCat(input: SegmenterInput, pos: usize) bool {
    const b = input.bytes[pos];
    if (b < 0x80) return std.ascii.isAlphanumeric(b);
    return true;
}

/// Coarse script class for word segmentation. UAX#29 keeps a run of alphabetic
/// scripts together (Latin/Greek/Cyrillic/Arabic/… — "abcГД" is one word) but
/// breaks at the boundary with CJK/Kana/Hangul (dictionary scripts), so
/// "hello世界" → "hello","世界". Combining marks and other neutrals attach to the
/// current run.
const SegScript = enum { alpha, cjk, neutral };
fn segScriptCat(cp: u21) SegScript {
    // Combining marks (Mn/Mc common ranges) attach to whatever precedes them.
    if ((cp >= 0x0300 and cp <= 0x036F) or (cp >= 0x1AB0 and cp <= 0x1AFF) or
        (cp >= 0x1DC0 and cp <= 0x1DFF) or (cp >= 0x20D0 and cp <= 0x20FF) or
        (cp >= 0xFE20 and cp <= 0xFE2F)) return .neutral;
    // CJK ideographs, kana, hangul, bopomofo, and CJK symbols.
    if ((cp >= 0x2E80 and cp <= 0x2FDF) or (cp >= 0x3005 and cp <= 0x3007) or
        (cp >= 0x3021 and cp <= 0x3029) or (cp >= 0x3040 and cp <= 0x30FF) or
        (cp >= 0x3100 and cp <= 0x312F) or (cp >= 0x3130 and cp <= 0x318F) or
        (cp >= 0x31A0 and cp <= 0x31FF) or (cp >= 0x3400 and cp <= 0x4DBF) or
        (cp >= 0x4E00 and cp <= 0x9FFF) or (cp >= 0xA960 and cp <= 0xA97F) or
        (cp >= 0xAC00 and cp <= 0xD7FF) or (cp >= 0xF900 and cp <= 0xFAFF) or
        (cp >= 0x1100 and cp <= 0x11FF) or (cp >= 0x20000 and cp <= 0x2FA1F)) return .cjk;
    // Everything else that reached here is a word character → an alphabetic run.
    return .alpha;
}

/// Advance one segment from byte `pos`; returns the end byte offset and (for the
/// "word" granularity) whether the segment is word-like.
fn segNext(input: SegmenterInput, pos: usize, gran: SegmenterGranularity) struct { end: usize, word_like: bool } {
    const str = input.bytes;
    const len = str.len;
    if (gran == .grapheme) {
        return .{ .end = @min(len, segNextGrapheme(input, pos)), .word_like = false };
    }
    if (gran == .sentence) {
        var end = pos;
        while (end < len) {
            const c = str[end];
            // SB4: a paragraph separator (CR/LF) ends the sentence.
            if (c == '\n') {
                end += 1;
                break;
            }
            if (c == '\r') {
                end += 1;
                if (end < len and str[end] == '\n') end += 1;
                break;
            }
            if (c == '.' or c == '!' or c == '?') {
                const t_end = end + segScalarLen(input, end);
                const nxt: u8 = if (t_end < len) str[t_end] else 0;
                // A terminator only ends a sentence when followed by whitespace, a
                // paragraph separator, or end of text ("One.Two"/"3.5" do not break).
                if (t_end >= len or nxt == ' ' or nxt == '\t' or nxt == '\n' or nxt == '\r') {
                    // SB8: a period followed (after spaces) by a lowercase letter is
                    // an abbreviation continuation, not a boundary ("U.S.A. is").
                    if (c == '.') {
                        var p = t_end;
                        while (p < len and (str[p] == ' ' or str[p] == '\t')) p += 1;
                        if (p < len and str[p] >= 'a' and str[p] <= 'z') {
                            end = t_end;
                            continue;
                        }
                    }
                    end = t_end;
                    while (end < len and (str[end] == ' ' or str[end] == '\t')) end += 1;
                    if (end < len and str[end] == '\r') {
                        end += 1;
                        if (end < len and str[end] == '\n') end += 1;
                    } else if (end < len and str[end] == '\n') end += 1;
                    break;
                }
                end = t_end;
                continue;
            }
            end += segScalarLen(input, end);
        }
        return .{ .end = end, .word_like = false };
    }
    // word: a maximal run of one category (word-like vs not). A "." or ","
    // between two digits stays inside the numeric word (UAX#29 WB11/WB12), so
    // "1.23" is one segment rather than "1", ".", "23".
    const first_cp = segCodePoint(input, pos);
    if (isHighSurrogate(first_cp) or isLowSurrogate(first_cp)) {
        var end = pos + segScalarLen(input, pos);
        if (isHighSurrogate(first_cp) and end < len and isLowSurrogate(segCodePoint(input, end))) end += segScalarLen(input, end);
        return .{ .end = end, .word_like = false };
    }
    const cat = segWordCat(input, pos);
    var end = pos;
    if (cat) {
        var run_script = segScriptCat(first_cp);
        while (end < len) {
            if (segWordCat(input, end)) {
                const sc = segScriptCat(segCodePoint(input, end));
                // Break at an alphabetic↔CJK script boundary.
                if ((run_script == .alpha and sc == .cjk) or (run_script == .cjk and sc == .alpha)) break;
                if (sc != .neutral) run_script = sc;
                end += segScalarLen(input, end);
                continue;
            }
            const c = str[end];
            if ((c == '.' or c == ',') and end > pos and end + 1 < len and std.ascii.isDigit(str[end - 1]) and std.ascii.isDigit(str[end + 1])) {
                end += 1;
                continue;
            }
            // WB6/WB7: an apostrophe (' or U+2019) between two letters stays in the
            // word ("don't"), as do a MidLetter dot/colon ("a.b") and an
            // ExtendNumLet underscore ("under_score", WB13a).
            const cp = segCodePoint(input, end);
            if ((c == '\'' or cp == 0x2019 or c == '.' or c == ':' or c == '_') and end > pos and segWordCat(input, end - 1)) {
                const after = end + segScalarLen(input, end);
                if (after < len and segWordCat(input, after)) {
                    end = after;
                    continue;
                }
            }
            break;
        }
    } else {
        // A run of whitespace is one segment; every other non-word character is
        // its own segment (UAX#29: "wow!!!" → "wow","!","!","!").
        const isSpace = struct {
            fn f(b: u8) bool {
                return b == ' ' or b == '\t' or b == '\n' or b == '\r' or b == 0x0B or b == 0x0C;
            }
        }.f;
        if (isSpace(str[pos])) {
            while (end < len and isSpace(str[end])) end += 1;
        } else {
            end += segScalarLen(input, pos);
        }
    }
    return .{ .end = end, .word_like = cat };
}

/// Build a segment-data object `{ segment, index, input[, isWordLike] }` (own
/// properties in that order; isWordLike only for the "word" granularity).
fn segDataObj(self: *Interpreter, input: SegmenterInput, start: usize, end: usize, gran: SegmenterGranularity, word_like: bool) EvalError!Value {
    const o = (try self.newObject()).asObj();
    try self.setProp(o, "segment", try input.segmentValue(self.arena, start, end));
    try self.setProp(o, "index", Value.num(@floatFromInt(input.utf16Index(start))));
    try self.setProp(o, "input", input.value);
    if (gran == .word) try self.setProp(o, "isWordLike", Value.boolVal(word_like));
    return Value.obj(o);
}

fn segmenterGranularity(seg_obj: *value.Object) SegmenterGranularity {
    if (seg_obj.getOwn("\x00gran")) |g| if (g.isString()) return SegmenterGranularity.fromString(g.asStr());
    return .grapheme;
}

/// `Intl.Segmenter.prototype.segment(string)` → a %Segments% object.
fn intlSegmenterSegmentFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject() or this.asObj().intlSegmenterData() == null)
        return self.throwError("TypeError", "Intl.Segmenter.prototype.segment on incompatible receiver");
    const input_value = try segmenterToStringValue(self, if (args.len > 0) args[0] else Value.undef());
    const gran = this.asObj().intlSegmenterData().?.granularity;
    const o = (try self.newObject()).asObj();
    if (self.env.get("\x00SegmentsProto")) |p| if (p.isObject()) {
        o.setProtoAtomic(p.asObj());
    };
    try self.setProp(o, "\x00segstr", input_value);
    try o.setAttr(self.arena, "\x00segstr", .{ .writable = false, .enumerable = false, .configurable = false });
    try self.setProp(o, "\x00gran", gran.value());
    try o.setAttr(self.arena, "\x00gran", .{ .writable = false, .enumerable = false, .configurable = false });
    return Value.obj(o);
}

fn segmentsBrandOk(this: Value) bool {
    return this.isObject() and this.asObj().getOwn("\x00segstr") != null;
}

/// `%Segments.prototype%.containing(index)`.
fn intlSegmentsContainingFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!segmentsBrandOk(this)) return self.throwError("TypeError", "Segments.prototype.containing on incompatible receiver");
    const input = try SegmenterInput.fromValue(self, this.asObj().getOwn("\x00segstr").?);
    const gran = segmenterGranularity(this.asObj());
    const nf = try self.toNumberV(if (args.len > 0) args[0] else Value.undef());
    const n: f64 = if (std.math.isNan(nf)) 0 else @trunc(nf);
    if (n < 0 or n >= @as(f64, @floatFromInt(input.utf16Len()))) return Value.undef();
    const target_units: usize = @intFromFloat(n);
    var pos: usize = 0;
    while (pos < input.bytes.len) {
        const nx = segNext(input, pos, gran);
        const start_units = input.utf16Index(pos);
        const end_units = input.utf16Index(nx.end);
        if (target_units >= start_units and target_units < end_units) return try segDataObj(self, input, pos, nx.end, gran, nx.word_like);
        pos = nx.end;
    }
    return Value.undef();
}

/// `%Segments.prototype%[@@iterator]()` → a %SegmentIterator%.
fn intlSegmentsIteratorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!segmentsBrandOk(this)) return self.throwError("TypeError", "Segments.prototype[@@iterator] on incompatible receiver");
    const it = (try self.newObject()).asObj();
    if (self.env.get("\x00SegIterProto")) |p| if (p.isObject()) {
        it.setProtoAtomic(p.asObj());
    };
    try self.setProp(it, "\x00segstr", this.asObj().getOwn("\x00segstr").?);
    try it.setAttr(self.arena, "\x00segstr", .{ .writable = false, .enumerable = false, .configurable = false });
    try self.setProp(it, "\x00gran", segmenterGranularity(this.asObj()).value());
    try it.setAttr(self.arena, "\x00gran", .{ .writable = false, .enumerable = false, .configurable = false });
    try self.setProp(it, "\x00pos", Value.num(0));
    try it.setAttr(self.arena, "\x00pos", .{ .writable = true, .enumerable = false, .configurable = false });
    return Value.obj(it);
}

/// `%SegmentIterator.prototype%.next()`.
fn intlSegmentIterNextFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject() or this.asObj().getOwn("\x00pos") == null) return self.throwError("TypeError", "Segment Iterator next on incompatible receiver");
    const input = try SegmenterInput.fromValue(self, this.asObj().getOwn("\x00segstr").?);
    const gran = segmenterGranularity(this.asObj());
    const pos: usize = @intFromFloat(this.asObj().getOwn("\x00pos").?.asNum());
    if (pos >= input.bytes.len) return self.iterResultObj(Value.undef(), true);
    const nx = segNext(input, pos, gran);
    try self.setProp(this.asObj(), "\x00pos", Value.num(@floatFromInt(nx.end)));
    return self.iterResultObj(try segDataObj(self, input, pos, nx.end, gran, nx.word_like), false);
}

/// `Intl.PluralRules.prototype.selectRange(start, end)` — both must be
/// non-NaN numbers (RangeError otherwise). The en plural range is always
/// "other".
fn intlPluralSelectRangeFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject() or this.asObj().intlPluralRulesData() == null)
        return self.throwError("TypeError", "Intl.PluralRules.prototype.selectRange on incompatible receiver");
    if (args.len < 2 or args[0].isUndefined() or args[1].isUndefined()) return self.throwError("TypeError", "selectRange requires two arguments");
    const start = try self.toNumberV(args[0]);
    const end = try self.toNumberV(args[1]);
    if (std.math.isNan(start) or std.math.isNan(end)) return self.throwError("RangeError", "selectRange arguments must not be NaN");
    return Value.str("other");
}

/// Binary search a sorted DisplayNames name table for `code` (exact match).
fn dnLookup(table: []const dn_data.Entry, code: []const u8) ?[]const u8 {
    var lo: usize = 0;
    var hi: usize = table.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const ord = std.mem.order(u8, table[mid].code, code);
        if (ord == .eq) return table[mid].name;
        if (ord == .lt) lo = mid + 1 else hi = mid;
    }
    return null;
}

/// Resolve the formatter's already-canonicalized locale to the most specific
/// generated CLDR bundle. Unicode extensions do not select DisplayNames data;
/// missing region bundles inherit from their language. A locale with no owned
/// bundle is excluded from DisplayNames availability and resolves to English.
fn dnLocaleIndex(locale: []const u8) ?u8 {
    var candidate = if (std.mem.indexOf(u8, locale, "-u-")) |extension| locale[0..extension] else locale;
    while (true) {
        var lo: usize = 0;
        var hi: usize = dn_data.locales.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const ord = std.mem.order(u8, dn_data.locales[mid].locale, candidate);
            if (ord == .eq) return @intCast(mid);
            if (ord == .lt) lo = mid + 1 else hi = mid;
        }
        const separator = std.mem.lastIndexOfScalar(u8, candidate, '-') orelse break;
        candidate = candidate[0..separator];
    }
    return null;
}

fn dnLocaleData(locale: []const u8) ?*const dn_data.LocaleData {
    const index = dnLocaleIndex(locale) orelse return null;
    return &dn_data.locales[index];
}

fn dnLocaleDataAt(index: ?u8) ?*const dn_data.LocaleData {
    const i = index orelse return null;
    if (i >= dn_data.locales.len) return null;
    return &dn_data.locales[i];
}

fn dnStyleLookup(
    style: value.IntlDisplayNamesData.Style,
    long: []const dn_data.Entry,
    short: []const dn_data.Entry,
    narrow: []const dn_data.Entry,
    code: []const u8,
) ?[]const u8 {
    switch (style) {
        .narrow => if (dnLookup(narrow, code)) |name| return name,
        .short => {},
        .long => return dnLookup(long, code),
    }
    if (dnLookup(short, code)) |name| return name;
    return dnLookup(long, code);
}

/// Apply a validated CLDR locale-display pattern containing `{0}` and `{1}`.
fn dnFormatPattern(
    allocator: std.mem.Allocator,
    pattern: []const u8,
    first: []const u8,
    second: []const u8,
) EvalError![]const u8 {
    var out: std.ArrayListUnmanaged(u8) = .empty;
    var cursor: usize = 0;
    while (cursor < pattern.len) {
        if (std.mem.startsWith(u8, pattern[cursor..], "{0}")) {
            try out.appendSlice(allocator, first);
            cursor += 3;
        } else if (std.mem.startsWith(u8, pattern[cursor..], "{1}")) {
            try out.appendSlice(allocator, second);
            cursor += 3;
        } else {
            try out.append(allocator, pattern[cursor]);
            cursor += 1;
        }
    }
    return out.items;
}

fn installDisplayNamesData(
    self: *Interpreter,
    formatter: *value.Object,
    locale: []const u8,
    style: []const u8,
    kind: []const u8,
    fallback: []const u8,
    language_display: []const u8,
) EvalError!void {
    const allocator = try formatter.intlDisplayNamesAllocator(self.arena);
    const data = try allocator.create(value.IntlDisplayNamesData);
    data.* = .{
        .locale_data_index = dnLocaleIndex(locale),
        .style = .fromString(style),
        .kind = .fromString(kind),
        .fallback = .fromString(fallback),
        .language_display = .fromString(language_display),
    };
    var installed = false;
    errdefer if (!installed) formatter.destroyUninstalledIntlDisplayNames(self.arena, data);
    data.owned_locale = try allocator.dupe(u8, locale);
    data.locale = data.owned_locale.?;
    try formatter.setIntlDisplayNamesData(self.arena, data);
    installed = true;
}

fn dnIsAllAlpha(s: []const u8) bool {
    for (s) |c| if (!std.ascii.isAlphabetic(c)) return false;
    return s.len > 0;
}

fn dnIsVariantSubtag(subtag: []const u8) bool {
    if (subtag.len >= 5 and subtag.len <= 8) return true;
    return subtag.len == 4 and std.ascii.isDigit(subtag[0]);
}
/// Render a language tag using the resolved locale's dialect names and CLDR
/// composition patterns. Unknown qualifiers remain visible in the result.
fn dnLanguageName(
    allocator: std.mem.Allocator,
    locale: *const dn_data.LocaleData,
    style: value.IntlDisplayNamesData.Style,
    canon_tag: []const u8,
    dialect: bool,
) EvalError!?[]const u8 {
    if (dialect) {
        if (dnStyleLookup(style, locale.languages_long, locale.languages_short, locale.languages_narrow, canon_tag)) |name| return name;
    }
    var it = std.mem.splitScalar(u8, canon_tag, '-');
    const base = it.next() orelse return null;
    var base_name = dnStyleLookup(style, locale.languages_long, locale.languages_short, locale.languages_narrow, base) orelse return null;
    var qualifier_source = canon_tag[base.len..];
    if (qualifier_source.len > 0) qualifier_source = qualifier_source[1..];
    if (dialect) {
        var offset = base.len + 1;
        var subtags = std.mem.splitScalar(u8, qualifier_source, '-');
        while (subtags.next()) |subtag| {
            if (dnIsVariantSubtag(subtag)) {
                const dialect_code = canon_tag[0 .. offset - 1];
                if (dnStyleLookup(style, locale.languages_long, locale.languages_short, locale.languages_narrow, dialect_code)) |name| {
                    base_name = name;
                    qualifier_source = canon_tag[offset..];
                }
                break;
            }
            offset += subtag.len + 1;
        }
    }
    var qualifier: ?[]const u8 = null;
    var qualifiers = std.mem.splitScalar(u8, qualifier_source, '-');
    while (qualifiers.next()) |sub| {
        if (sub.len == 0) continue;
        const name = if (sub.len == 4 and dnIsAllAlpha(sub))
            dnStyleLookup(style, locale.scripts_long, locale.scripts_short, locale.scripts_narrow, sub) orelse sub
        else if ((sub.len == 2 and dnIsAllAlpha(sub)) or sub.len == 3)
            dnStyleLookup(style, locale.regions_long, locale.regions_short, locale.regions_narrow, sub) orelse sub
        else if (dnIsVariantSubtag(sub))
            dnStyleLookup(style, locale.variants_long, locale.variants_short, locale.variants_narrow, sub) orelse sub
        else
            sub;
        qualifier = if (qualifier) |prior|
            try dnFormatPattern(allocator, locale.locale_separator, prior, name)
        else
            name;
    }
    return if (qualifier) |q| try dnFormatPattern(allocator, locale.locale_pattern, base_name, q) else base_name;
}
/// `Intl.DisplayNames.prototype.of(code)` — applies ECMA-402
/// CanonicalCodeForDisplayNames, then renders its localized display
/// name from the resolved locale's pinned CLDR tables. When no name is found,
/// fallback "none" returns undefined and "code" returns the canonicalized code.
fn intlDisplayNamesOfFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return self.throwError("TypeError", "Intl.DisplayNames.prototype.of on incompatible receiver");
    const data = this.asObj().intlDisplayNamesData() orelse return self.throwError("TypeError", "Intl.DisplayNames.prototype.of on incompatible receiver");
    const code = try self.toStringWtf8(if (args.len > 0) args[0] else Value.undef());
    var scratch = std.heap.ArenaAllocator.init(self.scratch_allocator orelse gc_mod.temporaryAllocator(self.arena));
    defer scratch.deinit();
    const scratch_allocator = scratch.allocator();
    const locale = dnLocaleDataAt(data.locale_data_index);
    const allAlpha = dnIsAllAlpha;
    var canon: []const u8 = code;
    var name: ?[]const u8 = null;
    switch (data.kind) {
        .region => {
            const digits = blk: {
                for (code) |c| if (!std.ascii.isDigit(c)) break :blk false;
                break :blk code.len == 3;
            };
            if (!((code.len == 2 and allAlpha(code)) or digits)) return self.throwError("RangeError", "invalid region code");
            var region_buf: [3]u8 = undefined;
            canon = std.ascii.upperString(region_buf[0..code.len], code);
            if (locale) |names| name = dnStyleLookup(data.style, names.regions_long, names.regions_short, names.regions_narrow, canon);
        },
        .script => {
            if (code.len != 4 or !allAlpha(code)) return self.throwError("RangeError", "invalid script code");
            var script_buf: [4]u8 = undefined;
            _ = std.ascii.lowerString(&script_buf, code);
            script_buf[0] = std.ascii.toUpper(script_buf[0]);
            canon = &script_buf;
            if (locale) |names| name = dnStyleLookup(data.style, names.scripts_long, names.scripts_short, names.scripts_narrow, canon);
        },
        .currency => {
            if (code.len != 3 or !allAlpha(code)) return self.throwError("RangeError", "invalid currency code");
            var currency_buf: [3]u8 = undefined;
            canon = std.ascii.upperString(&currency_buf, code);
            if (locale) |names| name = dnStyleLookup(data.style, names.currencies_long, names.currencies_short, names.currencies_narrow, canon);
        },
        .language => {
            // A unicode_language_id: structurally valid AND no extension (singleton)
            // subtag (DisplayNames language codes are not full locale tags).
            if (!isStructurallyValidLanguageTag(code)) return self.throwError("RangeError", "invalid language code");
            var lit = std.mem.splitScalar(u8, code, '-');
            while (lit.next()) |s| if (s.len == 1) return self.throwError("RangeError", "language code may not contain an extension");
            // Canonicalize each subtag by position, applying the CLDR language alias
            // to the primary subtag (e.g. tl→fil, sh→sr-Latn) as node/ICU does.
            if (std.mem.indexOfScalar(u8, code, '-') == null) {
                // unicode_language_subtag is at most eight bytes. The dominant
                // single-primary case therefore canonicalizes without allocator
                // traffic; an alias may still point at a static compound tag.
                var language_buf: [8]u8 = undefined;
                const low = std.ascii.lowerString(language_buf[0..code.len], code);
                canon = dnLookup(&dn_data.language_aliases, low) orelse low;
            } else {
                canon = try canonicalizeLocaleTagForIntl(self, scratch_allocator, code);
            }
            if (locale) |names| name = try dnLanguageName(scratch_allocator, names, data.style, canon, data.language_display == .dialect);
        },
        .calendar => {
            if (!dtfWellFormedType(code)) return self.throwError("RangeError", "invalid calendar code");
            canon = try std.ascii.allocLowerString(scratch_allocator, code);
            const cldr_code = if (std.mem.eql(u8, canon, "gregory"))
                "gregorian"
            else if (std.mem.eql(u8, canon, "ethioaa"))
                "ethiopic-amete-alem"
            else
                canon;
            if (locale) |names| name = dnLookup(names.calendars_long, cldr_code);
        },
        .date_time_field => {
            const fields = [_][]const u8{ "era", "year", "quarter", "month", "weekOfYear", "weekday", "day", "dayPeriod", "hour", "minute", "second", "timeZoneName" };
            var ok = false;
            for (fields) |f| if (std.mem.eql(u8, code, f)) {
                ok = true;
            };
            if (!ok) return self.throwError("RangeError", "invalid dateTimeField");
            if (locale) |names| name = dnStyleLookup(data.style, names.date_fields_long, names.date_fields_short, names.date_fields_narrow, code);
        },
    }
    if (name) |n| return try Value.strAlloc(self.arena, n);
    if (data.fallback == .none) return Value.undef();
    return try Value.strAlloc(self.arena, canon);
}

fn intlListFormatFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject() or this.asObj().intlListFormatData() == null)
        return self.throwError("TypeError", "Intl.ListFormat.prototype.format on incompatible receiver");
    const parts = try lfBuildParts(self, this, args);
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    for (parts.items) |p| try buf.appendSlice(self.arena, p.value);
    return try Value.strOwned(self.arena, try buf.toOwnedSlice(self.arena));
}

fn intlListFormatToPartsFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject() or this.asObj().intlListFormatData() == null)
        return self.throwError("TypeError", "Intl.ListFormat.prototype.formatToParts on incompatible receiver");
    const parts = try lfBuildParts(self, this, args);
    const arr = (try self.newArray()).asObj();
    for (parts.items) |p| {
        const o = (try self.newObject()).asObj();
        try self.setProp(o, "type", p.typ.value());
        try self.setProp(o, "value", try Value.strAlloc(self.arena, p.value));
        try arr.appendElement(self.arena, Value.obj(o));
    }
    return Value.obj(arr);
}

/// The eight relative-time units, with their long-form names and the
/// numeric-"auto" exception terms (en). A null past/future term means the unit
/// has no special word there, so the numeric form ("in 1 hour") is used.
const RtfUnitInfo = struct {
    singular: []const u8,
    past: ?[]const u8, // value -1
    present: []const u8, // value 0 / -0
    future: ?[]const u8, // value +1
};
fn rtfUnitInfo(unit: []const u8) ?RtfUnitInfo {
    // Accept the singular or plural ("second"/"seconds") spelling.
    const table = [_]struct { k: []const u8, i: RtfUnitInfo }{
        .{ .k = "second", .i = .{ .singular = "second", .past = null, .present = "now", .future = null } },
        .{ .k = "minute", .i = .{ .singular = "minute", .past = null, .present = "this minute", .future = null } },
        .{ .k = "hour", .i = .{ .singular = "hour", .past = null, .present = "this hour", .future = null } },
        .{ .k = "day", .i = .{ .singular = "day", .past = "yesterday", .present = "today", .future = "tomorrow" } },
        .{ .k = "week", .i = .{ .singular = "week", .past = "last week", .present = "this week", .future = "next week" } },
        .{ .k = "month", .i = .{ .singular = "month", .past = "last month", .present = "this month", .future = "next month" } },
        .{ .k = "quarter", .i = .{ .singular = "quarter", .past = "last quarter", .present = "this quarter", .future = "next quarter" } },
        .{ .k = "year", .i = .{ .singular = "year", .past = "last year", .present = "this year", .future = "next year" } },
    };
    for (table) |t| {
        if (std.mem.eql(u8, unit, t.k)) return t.i;
        // plural form: singular + "s"
        if (unit.len == t.k.len + 1 and std.mem.startsWith(u8, unit, t.k) and unit[unit.len - 1] == 's') return t.i;
    }
    return null;
}

/// The pieces of a relative-time result: either a single relative `term`
/// (numeric:"auto" for ±1/0) or a numeric phrase — a `prefix` literal, the
/// grouped number (`int_str`/`frac_str`, tagged with the singular `unit`), and
/// a `suffix` literal.
const RtfResult = struct {
    term: ?[]const u8 = null,
    prefix: []const u8 = "",
    int_str: []const u8 = "",
    frac_str: []const u8 = "",
    suffix: []const u8 = "",
    unit: []const u8 = "",
    group: []const u8 = ",",
    decimal: []const u8 = ".",
    numbering: []const u8 = "latn",
    min_group_digits: usize = 4,
};

/// en short/narrow relative-time unit names (singular/plural). Most units don't
/// pluralize ("sec."), but day/quarter do ("days"/"qtrs.").
fn rtfShortName(unit: []const u8, plural: bool) ?[]const u8 {
    const T = struct { k: []const u8, s: []const u8, p: []const u8 };
    const table = [_]T{
        .{ .k = "second", .s = "sec.", .p = "sec." },   .{ .k = "minute", .s = "min.", .p = "min." },
        .{ .k = "hour", .s = "hr.", .p = "hr." },       .{ .k = "day", .s = "day", .p = "days" },
        .{ .k = "week", .s = "wk.", .p = "wk." },       .{ .k = "month", .s = "mo.", .p = "mo." },
        .{ .k = "quarter", .s = "qtr.", .p = "qtrs." }, .{ .k = "year", .s = "yr.", .p = "yr." },
    };
    for (table) |t| if (std.mem.eql(u8, unit, t.k)) return if (plural) t.p else t.s;
    return null;
}

/// en narrow relative-time unit abbreviation (no plural distinction, no space
/// between the number and the unit: "3h ago").
fn rtfNarrowName(unit: []const u8) ?[]const u8 {
    const T = struct { k: []const u8, n: []const u8 };
    const table = [_]T{
        .{ .k = "second", .n = "s" },  .{ .k = "minute", .n = "m" },
        .{ .k = "hour", .n = "h" },    .{ .k = "day", .n = "d" },
        .{ .k = "week", .n = "w" },    .{ .k = "month", .n = "mo" },
        .{ .k = "quarter", .n = "q" }, .{ .k = "year", .n = "y" },
    };
    for (table) |t| if (std.mem.eql(u8, unit, t.k)) return t.n;
    return null;
}

fn rtfPolishCategory(mag: f64) []const u8 {
    if (mag != @trunc(mag)) return "other";
    const n: u64 = @intFromFloat(@abs(mag));
    if (n == 1) return "one";
    const mod10 = n % 10;
    const mod100 = n % 100;
    if (mod10 >= 2 and mod10 <= 4 and !(mod100 >= 12 and mod100 <= 14)) return "few";
    return "many";
}

fn rtfPolishUnitName(unit: []const u8, style: []const u8, category: []const u8) ?[]const u8 {
    const short = std.mem.eql(u8, style, "short");
    const narrow = std.mem.eql(u8, style, "narrow");
    const C = struct { many: []const u8, few: []const u8, one: []const u8, other: []const u8 };
    const pick = struct {
        fn p(c: C, cat: []const u8) []const u8 {
            if (std.mem.eql(u8, cat, "one")) return c.one;
            if (std.mem.eql(u8, cat, "few")) return c.few;
            if (std.mem.eql(u8, cat, "other")) return c.other;
            return c.many;
        }
    }.p;
    if (short or narrow) {
        const table = [_]struct { u: []const u8, sh: C, na: C }{
            .{ .u = "second", .sh = .{ .many = "sek.", .few = "sek.", .one = "sek.", .other = "sek." }, .na = .{ .many = "s", .few = "s", .one = "s", .other = "s" } },
            .{ .u = "minute", .sh = .{ .many = "min", .few = "min", .one = "min", .other = "min" }, .na = .{ .many = "min", .few = "min", .one = "min", .other = "min" } },
            .{ .u = "hour", .sh = .{ .many = "godz.", .few = "godz.", .one = "godz.", .other = "godz." }, .na = .{ .many = "g.", .few = "g.", .one = "g.", .other = "g." } },
            .{ .u = "day", .sh = .{ .many = "dni", .few = "dni", .one = "dzień", .other = "dnia" }, .na = .{ .many = "dni", .few = "dni", .one = "dzień", .other = "dnia" } },
            .{ .u = "week", .sh = .{ .many = "tyg.", .few = "tyg.", .one = "tydz.", .other = "tyg." }, .na = .{ .many = "tyg.", .few = "tyg.", .one = "tydz.", .other = "tyg." } },
            .{ .u = "month", .sh = .{ .many = "mies.", .few = "mies.", .one = "mies.", .other = "mies." }, .na = .{ .many = "mies.", .few = "mies.", .one = "mies.", .other = "mies." } },
            .{ .u = "quarter", .sh = .{ .many = "kw.", .few = "kw.", .one = "kw.", .other = "kw." }, .na = .{ .many = "kw.", .few = "kw.", .one = "kw.", .other = "kw." } },
            .{ .u = "year", .sh = .{ .many = "lat", .few = "lata", .one = "rok", .other = "roku" }, .na = .{ .many = "lat", .few = "lata", .one = "rok", .other = "roku" } },
        };
        for (table) |t| if (std.mem.eql(u8, unit, t.u)) return pick(if (narrow) t.na else t.sh, category);
    } else {
        const table = [_]struct { u: []const u8, c: C }{
            .{ .u = "second", .c = .{ .many = "sekund", .few = "sekundy", .one = "sekundę", .other = "sekundy" } },
            .{ .u = "minute", .c = .{ .many = "minut", .few = "minuty", .one = "minutę", .other = "minuty" } },
            .{ .u = "hour", .c = .{ .many = "godzin", .few = "godziny", .one = "godzinę", .other = "godziny" } },
            .{ .u = "day", .c = .{ .many = "dni", .few = "dni", .one = "dzień", .other = "dnia" } },
            .{ .u = "week", .c = .{ .many = "tygodni", .few = "tygodnie", .one = "tydzień", .other = "tygodnia" } },
            .{ .u = "month", .c = .{ .many = "miesięcy", .few = "miesiące", .one = "miesiąc", .other = "miesiąca" } },
            .{ .u = "quarter", .c = .{ .many = "kwartałów", .few = "kwartały", .one = "kwartał", .other = "kwartału" } },
            .{ .u = "year", .c = .{ .many = "lat", .few = "lata", .one = "rok", .other = "roku" } },
        };
        for (table) |t| if (std.mem.eql(u8, unit, t.u)) return pick(t.c, category);
    }
    return null;
}

fn rtfCompute(self: *Interpreter, this: Value, args: []const Value) value.HostError!RtfResult {
    const valnum = try self.toNumberV(if (args.len > 0) args[0] else Value.undef());
    if (!std.math.isFinite(valnum)) return self.throwError("RangeError", "value must be finite");
    const unit_s = try self.toStringWtf8(if (args.len > 1) args[1] else Value.undef());
    const info = rtfUnitInfo(unit_s) orelse return self.throwError("RangeError", try std.fmt.allocPrint(self.arena, "invalid unit '{s}'", .{unit_s}));

    const data = this.asObj().intlRelativeTimeFormatData() orelse
        return self.throwError("TypeError", "Intl.RelativeTimeFormat has no resolved state");
    const numeric = data.numeric.string();
    const style = data.style.string();
    const neg = std.math.signbit(valnum); // -0 formats as past

    if (std.mem.eql(u8, numeric, "auto") and valnum == @trunc(valnum) and @abs(valnum) <= 1) {
        if (valnum == 1) {
            if (info.future) |w| return .{ .term = w };
        } else if (valnum == -1) {
            if (info.past) |w| return .{ .term = w };
        } else {
            return .{ .term = info.present };
        }
    }

    const mag = @abs(valnum);
    var decimal_scratch: NfDecimalScratch = .{};
    const rounded = nfRound(&decimal_scratch, mag, false, 1, 0, 3, null, null, false, "auto", 1, "halfExpand");
    const r = NfRound{
        .int_str = try self.arena.dupe(u8, rounded.int_str),
        .frac_str = if (rounded.frac_str.len > 0) try self.arena.dupe(u8, rounded.frac_str) else "",
        .is_zero = rounded.is_zero,
    };
    const plural = mag != 1;
    const locale = data.locale;
    const numbering = data.numbering_system;
    const syms = localeNumberSymbols(locale, numbering);
    const lang = localeLanguage(locale);
    const is_narrow = std.mem.eql(u8, style, "narrow");
    const unit_name = if (std.mem.eql(u8, lang, "pl"))
        rtfPolishUnitName(info.singular, style, rtfPolishCategory(mag)) orelse info.singular
    else blk: {
        if (is_narrow) if (rtfNarrowName(info.singular)) |nn| break :blk nn;
        const short = std.mem.eql(u8, style, "short") or is_narrow;
        break :blk if (short and rtfShortName(info.singular, plural) != null)
            rtfShortName(info.singular, plural).?
        else if (plural)
            try std.fmt.allocPrint(self.arena, "{s}s", .{info.singular})
        else
            info.singular;
    };
    // Narrow en drops the space between the number and the unit ("3h ago").
    const sep: []const u8 = if (is_narrow and !std.mem.eql(u8, lang, "pl")) "" else " ";
    // en long patterns: future "in {0} <unit>", past "{0} <unit> ago".
    return .{
        .int_str = r.int_str,
        .frac_str = r.frac_str,
        .unit = info.singular,
        .prefix = if (std.mem.eql(u8, lang, "pl")) (if (neg) "" else "za ") else (if (neg) "" else "in "),
        .suffix = if (std.mem.eql(u8, lang, "pl"))
            (if (neg) try std.fmt.allocPrint(self.arena, " {s} temu", .{unit_name}) else try std.fmt.allocPrint(self.arena, " {s}", .{unit_name}))
        else
            (if (neg) try std.fmt.allocPrint(self.arena, "{s}{s} ago", .{ sep, unit_name }) else try std.fmt.allocPrint(self.arena, "{s}{s}", .{ sep, unit_name })),
        .group = syms.group,
        .decimal = syms.decimal,
        .numbering = numbering,
        .min_group_digits = if (std.mem.eql(u8, lang, "pl")) 5 else 4,
    };
}

fn intlRelativeTimeFormatFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject() or this.asObj().intlRelativeTimeFormatData() == null)
        return self.throwError("TypeError", "Intl.RelativeTimeFormat.prototype.format on incompatible receiver");
    const r = try rtfCompute(self, this, args);
    if (r.term) |t| return try Value.strAlloc(self.arena, t);
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    try buf.appendSlice(self.arena, r.prefix);
    try buf.appendSlice(self.arena, try rtfTranslateNumber(self, try rtfGroup(self, r.int_str, r.group, r.min_group_digits), r.numbering));
    if (r.frac_str.len > 0) {
        try buf.appendSlice(self.arena, r.decimal);
        try buf.appendSlice(self.arena, try rtfTranslateNumber(self, r.frac_str, r.numbering));
    }
    try buf.appendSlice(self.arena, r.suffix);
    return try Value.strOwned(self.arena, try buf.toOwnedSlice(self.arena));
}

/// Group an integer digit string every three digits.
fn rtfGroup(self: *Interpreter, int_str: []const u8, group: []const u8, min_group_digits: usize) EvalError![]const u8 {
    if (int_str.len < min_group_digits) return int_str;
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    const first_group = int_str.len % 3;
    for (int_str, 0..) |c, i| {
        if (i != 0 and (i % 3) == first_group) try buf.appendSlice(self.arena, group);
        try buf.append(self.arena, c);
    }
    return buf.toOwnedSlice(self.arena);
}

fn rtfTranslateNumber(self: *Interpreter, s: []const u8, numbering: []const u8) EvalError![]const u8 {
    return rtfTranslateNumberAlloc(self.arena, s, numbering);
}

fn rtfTranslateNumberAlloc(allocator: std.mem.Allocator, s: []const u8, numbering: []const u8) EvalError![]const u8 {
    if (std.mem.eql(u8, numbering, "latn")) return s;
    return if (numbering_systems.digits(numbering)) |ds| try translateDigitsAlloc(allocator, s, ds) else s;
}

fn intlRelativeTimeFormatToPartsFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject() or this.asObj().intlRelativeTimeFormatData() == null)
        return self.throwError("TypeError", "Intl.RelativeTimeFormat.prototype.formatToParts on incompatible receiver");
    const r = try rtfCompute(self, this, args);
    const arr = (try self.newArray()).asObj();
    const addPart = struct {
        fn p(s: *Interpreter, a: *value.Object, typ: NfPartType, v: []const u8, unit: ?[]const u8) EvalError!void {
            const o = (try s.newObject()).asObj();
            try s.setProp(o, "type", typ.value());
            try s.setProp(o, "value", try Value.strAlloc(s.arena, v));
            if (unit) |u| try s.setProp(o, "unit", try Value.strOwned(s.arena, try std.fmt.allocPrint(s.arena, "{s}", .{u})));
            try a.appendElement(s.arena, Value.obj(o));
        }
    }.p;
    if (r.term) |t| {
        try addPart(self, arr, .literal, t, null);
        return Value.obj(arr);
    }
    if (r.prefix.len > 0) try addPart(self, arr, .literal, r.prefix, null);
    // Number, split into integer/group parts, each tagged with the unit.
    const first_group = r.int_str.len % 3;
    var run_start: usize = 0;
    for (r.int_str, 0..) |_, i| {
        if (r.int_str.len >= r.min_group_digits and i != 0 and (i % 3) == first_group) {
            try addPart(self, arr, .integer, try rtfTranslateNumber(self, r.int_str[run_start..i], r.numbering), r.unit);
            try addPart(self, arr, .group, r.group, r.unit);
            run_start = i;
        }
    }
    try addPart(self, arr, .integer, try rtfTranslateNumber(self, r.int_str[run_start..], r.numbering), r.unit);
    if (r.frac_str.len > 0) {
        try addPart(self, arr, .decimal, r.decimal, r.unit);
        try addPart(self, arr, .fraction, try rtfTranslateNumber(self, r.frac_str, r.numbering), r.unit);
    }
    if (r.suffix.len > 0) try addPart(self, arr, .literal, r.suffix, null);
    return Value.obj(arr);
}

/// Project a constructor-validated ECMA-402 string choice without allocating.
/// Each call site supplies its complete finite set; reaching the tail means
/// immutable engine state escaped its validation boundary, so fail closed.
fn intlValidatedChoiceValue(bytes: []const u8, comptime choices: []const []const u8) Value {
    inline for (choices) |choice| {
        if (std.mem.eql(u8, bytes, choice)) return Value.str(choice);
    }
    std.debug.panic("unvalidated Intl option reached resolved state: {s}", .{bytes});
}

fn intlResolvedOptionsFn(comptime service: []const u8) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this_recv: Value, args: []const Value) value.HostError!Value {
            _ = args;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            const this = if (comptime std.mem.eql(u8, service, "DisplayNames")) blk: {
                if (this_recv.isObject() and this_recv.asObj().intlDisplayNamesData() != null) break :blk this_recv;
                return self.throwError("TypeError", "Intl.DisplayNames.prototype.resolvedOptions on incompatible receiver");
            } else if (comptime std.mem.eql(u8, service, "RelativeTimeFormat")) blk: {
                if (this_recv.isObject() and this_recv.asObj().intlRelativeTimeFormatData() != null) break :blk this_recv;
                return self.throwError("TypeError", "Intl.RelativeTimeFormat.prototype.resolvedOptions on incompatible receiver");
            } else if (comptime std.mem.eql(u8, service, "ListFormat")) blk: {
                if (this_recv.isObject() and this_recv.asObj().intlListFormatData() != null) break :blk this_recv;
                return self.throwError("TypeError", "Intl.ListFormat.prototype.resolvedOptions on incompatible receiver");
            } else if (comptime std.mem.eql(u8, service, "Segmenter")) blk: {
                if (this_recv.isObject() and this_recv.asObj().intlSegmenterData() != null) break :blk this_recv;
                return self.throwError("TypeError", "Intl.Segmenter.prototype.resolvedOptions on incompatible receiver");
            } else if (comptime std.mem.eql(u8, service, "PluralRules")) blk: {
                if (this_recv.isObject() and this_recv.asObj().intlPluralRulesData() != null) break :blk this_recv;
                return self.throwError("TypeError", "Intl.PluralRules.prototype.resolvedOptions on incompatible receiver");
            } else if (comptime std.mem.eql(u8, service, "DurationFormat")) blk: {
                if (this_recv.isObject() and this_recv.asObj().intlDurationFormatData() != null) break :blk this_recv;
                return self.throwError("TypeError", "Intl.DurationFormat.prototype.resolvedOptions on incompatible receiver");
            } else if (comptime std.mem.eql(u8, service, "Collator")) blk: {
                if (this_recv.isObject() and this_recv.asObj().intlCollatorData() != null) break :blk this_recv;
                return self.throwError("TypeError", "Intl.Collator.prototype.resolvedOptions on incompatible receiver");
            } else (try unwrapIntlThis(self, this_recv, service)) orelse return self.throwError("TypeError", "Intl." ++ service ++ ".prototype.resolvedOptions on incompatible receiver");
            const o = (try self.newObject()).asObj();
            const loc = if (comptime std.mem.eql(u8, service, "DisplayNames"))
                try Value.strAlloc(self.arena, this.asObj().intlDisplayNamesData().?.locale)
            else if (comptime std.mem.eql(u8, service, "RelativeTimeFormat"))
                try Value.strAlloc(self.arena, this.asObj().intlRelativeTimeFormatData().?.locale)
            else if (comptime std.mem.eql(u8, service, "ListFormat"))
                try Value.strAlloc(self.arena, this.asObj().intlListFormatData().?.locale)
            else if (comptime std.mem.eql(u8, service, "Segmenter"))
                try Value.strAlloc(self.arena, this.asObj().intlSegmenterData().?.locale)
            else if (comptime std.mem.eql(u8, service, "PluralRules"))
                try Value.strAlloc(self.arena, this.asObj().intlPluralRulesData().?.locale)
            else if (comptime std.mem.eql(u8, service, "DurationFormat"))
                try Value.strAlloc(self.arena, this.asObj().intlDurationFormatData().?.locale)
            else if (comptime std.mem.eql(u8, service, "Collator"))
                try Value.strAlloc(self.arena, this.asObj().intlCollatorData().?.locale)
            else if (comptime std.mem.eql(u8, service, "NumberFormat"))
                try Value.strAlloc(self.arena, this.asObj().intlNumberFormatData().?.resolved_locale)
            else if (comptime std.mem.eql(u8, service, "DateTimeFormat"))
                try Value.strAlloc(self.arena, this.asObj().intlDateTimeFormatData().?.resolved_locale)
            else
                unreachable;
            try self.setProp(o, "locale", loc);
            // The spec resolvedOptions field set (with default values) per
            // service. `numberingSystem` belongs to the number/date/plural
            // services, not Collator/ListFormat.
            if (comptime std.mem.eql(u8, service, "NumberFormat")) {
                const data = try numberFormatDataFor(self, this.asObj());
                try self.setProp(o, "numberingSystem", try Value.strAlloc(self.arena, data.numbering_system));
                try self.setProp(o, "style", intlValidatedChoiceValue(data.style, &.{ "decimal", "percent", "currency", "unit" }));
                if (data.currency) |c| {
                    try self.setProp(o, "currency", try Value.strAlloc(self.arena, c));
                    try self.setProp(o, "currencyDisplay", intlValidatedChoiceValue(data.currency_display, &.{ "code", "symbol", "narrowSymbol", "name" }));
                    try self.setProp(o, "currencySign", intlValidatedChoiceValue(data.currency_sign, &.{ "standard", "accounting" }));
                }
                if (data.unit) |unit| {
                    try self.setProp(o, "unit", try Value.strAlloc(self.arena, unit));
                    try self.setProp(o, "unitDisplay", intlValidatedChoiceValue(data.unit_display, &.{ "short", "long", "narrow" }));
                }
                try self.setProp(o, "minimumIntegerDigits", Value.num(@floatFromInt(data.minimum_integer_digits)));
                // Significant-digits resolution: with the default ("auto") rounding
                // priority a set of significant digits replaces the fraction
                // digits; morePrecision/lessPrecision reports both.
                const min_sig = data.minimum_significant_digits;
                const max_sig = data.maximum_significant_digits;
                const has_sig = min_sig != null or max_sig != null;
                const both = !std.mem.eql(u8, data.rounding_priority, "auto");
                if (!has_sig or both) {
                    try self.setProp(o, "minimumFractionDigits", Value.num(@floatFromInt(data.minimum_fraction_digits)));
                    try self.setProp(o, "maximumFractionDigits", Value.num(@floatFromInt(data.maximum_fraction_digits)));
                }
                if (has_sig) {
                    try self.setProp(o, "minimumSignificantDigits", Value.num(@floatFromInt(min_sig orelse 1)));
                    try self.setProp(o, "maximumSignificantDigits", Value.num(@floatFromInt(max_sig orelse 21)));
                }
                const grouping = switch (data.grouping) {
                    .off => Value.boolVal(false),
                    .min2 => Value.str("min2"),
                    .auto => Value.str("auto"),
                    .always => Value.str("always"),
                };
                try self.setProp(o, "useGrouping", grouping);
                try self.setProp(o, "notation", intlValidatedChoiceValue(data.notation, &.{ "standard", "scientific", "engineering", "compact" }));
                if (std.mem.eql(u8, data.notation, "compact")) try self.setProp(o, "compactDisplay", intlValidatedChoiceValue(data.compact_display, &.{ "short", "long" }));
                try self.setProp(o, "signDisplay", intlValidatedChoiceValue(data.sign_display, &.{ "auto", "never", "always", "exceptZero", "negative" }));
                try self.setProp(o, "roundingIncrement", Value.num(@floatFromInt(data.rounding_increment)));
                try self.setProp(o, "roundingMode", intlValidatedChoiceValue(data.rounding_mode, &.{ "ceil", "floor", "expand", "trunc", "halfCeil", "halfFloor", "halfExpand", "halfTrunc", "halfEven" }));
                try self.setProp(o, "roundingPriority", intlValidatedChoiceValue(data.rounding_priority, &.{ "auto", "morePrecision", "lessPrecision" }));
                try self.setProp(o, "trailingZeroDisplay", intlValidatedChoiceValue(data.trailing_zero_display, &.{ "auto", "stripIfInteger" }));
            } else if (comptime std.mem.eql(u8, service, "Collator")) {
                const data = this.asObj().intlCollatorData().?;
                try self.setProp(o, "usage", data.usage.value());
                try self.setProp(o, "sensitivity", data.sensitivity.value());
                try self.setProp(o, "ignorePunctuation", Value.boolVal(data.ignore_punctuation));
                try self.setProp(o, "collation", data.collation.value());
                try self.setProp(o, "numeric", Value.boolVal(data.numeric));
                try self.setProp(o, "caseFirst", data.case_first.value());
            } else if (comptime std.mem.eql(u8, service, "PluralRules")) {
                // Spec key order: locale (set above), type, notation,
                // minimumIntegerDigits, then significant-OR-fraction digits,
                // pluralCategories, rounding*, trailingZeroDisplay. No
                // numberingSystem.
                const data = this.asObj().intlPluralRulesData().?;
                try self.setProp(o, "type", data.kind.value());
                try self.setProp(o, "notation", data.notation.value());
                // compactDisplay is reported only when notation is "compact".
                if (data.notation == .compact) {
                    try self.setProp(o, "compactDisplay", data.compact_display.value());
                }
                try self.setProp(o, "minimumIntegerDigits", Value.num(@floatFromInt(data.minimum_integer_digits)));
                if (data.minimum_significant_digits != null or data.maximum_significant_digits != null) {
                    try self.setProp(o, "minimumSignificantDigits", Value.num(@floatFromInt(data.minimum_significant_digits orelse 1)));
                    try self.setProp(o, "maximumSignificantDigits", Value.num(@floatFromInt(data.maximum_significant_digits orelse 21)));
                } else {
                    try self.setProp(o, "minimumFractionDigits", Value.num(@floatFromInt(data.minimum_fraction_digits)));
                    try self.setProp(o, "maximumFractionDigits", Value.num(@floatFromInt(data.maximum_fraction_digits)));
                }
                // pluralCategories: the categories the locale's rules define,
                // in CLDR order (zero, one, two, few, many, other).
                const cats = (try self.newArray()).asObj();
                const prules = pluralRulesFor(data);
                for (plural_category_order) |cat| {
                    for (prules) |r| if (PluralCategory.fromString(r.cat) == cat) {
                        try cats.appendElement(self.arena, cat.value());
                        break;
                    };
                }
                try self.setProp(o, "pluralCategories", Value.obj(cats));
                try self.setProp(o, "roundingIncrement", Value.num(@floatFromInt(data.rounding_increment)));
                try self.setProp(o, "roundingMode", data.rounding_mode.value());
                try self.setProp(o, "roundingPriority", data.rounding_priority.value());
                try self.setProp(o, "trailingZeroDisplay", data.trailing_zero_display.value());
            } else if (comptime std.mem.eql(u8, service, "DateTimeFormat")) {
                const data = this.asObj().intlDateTimeFormatData() orelse
                    return self.throwError("TypeError", "Intl.DateTimeFormat has no resolved state");
                try self.setProp(o, "calendar", try Value.strAlloc(self.arena, data.calendar));
                try self.setProp(o, "numberingSystem", try Value.strAlloc(self.arena, data.numbering_system));
                try self.setProp(o, "timeZone", try Value.strAlloc(self.arena, data.time_zone));
                if (data.hour_cycle.value()) |hour_cycle| {
                    try self.setProp(o, "hourCycle", hour_cycle);
                    try self.setProp(o, "hour12", Value.boolVal(data.hour12));
                }
                const put = struct {
                    fn field(s: *Interpreter, target: *value.Object, name: []const u8, resolved: value.IntlDateTimeFormatData.Field) EvalError!void {
                        if (resolved.value()) |projected| try s.setProp(target, name, projected);
                    }
                }.field;
                const component_record = data.date_style == .none and data.time_style == .none;
                if (component_record) {
                    try put(self, o, "weekday", data.weekday);
                    try put(self, o, "era", data.era);
                    try put(self, o, "year", data.year);
                    try put(self, o, "month", data.month);
                    try put(self, o, "day", data.day);
                    try put(self, o, "dayPeriod", data.day_period.field());
                    try put(self, o, "hour", data.hour);
                    try put(self, o, "minute", data.minute);
                    try put(self, o, "second", data.second);
                    if (data.fractional_second_digits > 0)
                        try self.setProp(o, "fractionalSecondDigits", Value.num(@floatFromInt(data.fractional_second_digits)));
                    try put(self, o, "timeZoneName", data.time_zone_name);
                }
                try put(self, o, "dateStyle", data.date_style);
                try put(self, o, "timeStyle", data.time_style);
            } else if (comptime std.mem.eql(u8, service, "RelativeTimeFormat")) {
                const data = this.asObj().intlRelativeTimeFormatData().?;
                try self.setProp(o, "style", data.style.value());
                try self.setProp(o, "numeric", data.numeric.value());
                try self.setProp(o, "numberingSystem", try Value.strAlloc(self.arena, data.numbering_system));
            } else if (comptime std.mem.eql(u8, service, "ListFormat")) {
                const data = this.asObj().intlListFormatData().?;
                try self.setProp(o, "type", data.kind.value());
                try self.setProp(o, "style", data.style.value());
            } else if (comptime std.mem.eql(u8, service, "DisplayNames")) {
                // Reflect the immutable normalized record in Table-6 order.
                const data = this.asObj().intlDisplayNamesData() orelse
                    return self.throwError("TypeError", "Intl.DisplayNames has no resolved state");
                try self.setProp(o, "style", data.style.value());
                try self.setProp(o, "type", data.kind.value());
                try self.setProp(o, "fallback", data.fallback.value());
                if (data.kind == .language)
                    try self.setProp(o, "languageDisplay", data.language_display.value());
            } else if (comptime std.mem.eql(u8, service, "Segmenter")) {
                const data = this.asObj().intlSegmenterData().?;
                try self.setProp(o, "granularity", data.granularity.value());
            } else if (comptime std.mem.eql(u8, service, "DurationFormat")) {
                const data = this.asObj().intlDurationFormatData().?;
                try self.setProp(o, "numberingSystem", try Value.strAlloc(self.arena, data.numbering_system));
                try self.setProp(o, "style", data.style.value());
                inline for (duration_units, 0..) |u, i| {
                    try self.setProp(o, u, data.unit_styles[i].value());
                    try self.setProp(o, u ++ "Display", data.unit_displays[i].value());
                }
                if (data.fractional_digits) |digits|
                    try self.setProp(o, "fractionalDigits", Value.num(@floatFromInt(digits)));
            }
            return Value.obj(o);
        }
    }.call;
}

fn intlSupportedLocalesOfFn(comptime service: []const u8) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            _ = this;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            // CanonicalizeLocaleList(locales) first (throws on a structurally invalid tag).
            const arr = try canonicalizeLocaleList(self, if (args.len > 0) args[0] else Value.undef());
            // SupportedLocales: if options is not undefined, ToObject it (TypeError for
            // null) and validate the localeMatcher option (RangeError otherwise).
            if (args.len > 1 and !args[1].isUndefined()) {
                const opts: Value = Value.obj(try self.toObject(args[1]));
                const lm = try self.getProperty(opts, "localeMatcher");
                if (!lm.isUndefined()) {
                    const s = try self.toStringWtf8(lm);
                    if (!std.mem.eql(u8, s, "lookup") and !std.mem.eql(u8, s, "best fit")) return self.throwError("RangeError", "invalid value for option localeMatcher");
                }
            }
            // A service can advertise only locales for which its own immutable
            // data exists. DisplayNames has an explicit generated locale set;
            // other services retain the engine-wide CLDR availability rule.
            const out = (try self.newArray()).asObj();
            const n = arr.elementsLen();
            var i: usize = 0;
            while (i < n) : (i += 1) {
                const lv = arr.elementAt(i) orelse continue;
                if (!lv.isString()) continue;
                const supported = if (comptime std.mem.eql(u8, service, "DisplayNames"))
                    dnLocaleIndex(lv.asStr()) != null
                else
                    intlLocaleSupported(lv.asStr());
                if (!supported) continue;
                try out.appendElement(self.arena, lv);
            }
            return Value.obj(out);
        }
    }.call;
}

/// Install the `Intl` namespace and its services.
fn installIntl(env: *Environment, rs: *Shape, object_proto: *value.Object) EvalError!void {
    const a = env.arena;
    const tag: ?[]const u8 = blk: {
        if (env.get("Symbol")) |sym| if (sym.isObject()) {
            if (sym.asObj().getOwn("toStringTag")) |t| if (t.isObject() and t.asObj().is_symbol) break :blk t.asObj().symbolKey();
        };
        break :blk null;
    };
    const ns = try gc_mod.allocObj(a);
    ns.* = .{ .proto = object_proto };
    if (tag) |k| {
        try ns.setOwn(a, rs, k, Value.str("Intl"));
        try ns.setAttr(a, k, .{ .writable = false, .enumerable = false, .configurable = true });
    }
    try setNative(a, rs, ns, "getCanonicalLocales", 1, intlGetCanonicalLocalesFn);
    try setNative(a, rs, ns, "supportedValuesOf", 1, intlSupportedValuesOfFn);
    // %Intl%.[[FallbackSymbol]] — for the legacy "called as a function" chaining
    // of NumberFormat/DateTimeFormat/Collator onto an existing receiver. It gets
    // %Symbol.prototype% so its `description` accessor works.
    const sym_proto: ?*value.Object = blk: {
        if (env.get("Symbol")) |sv| if (sv.isObject()) if (sv.asObj().getOwn("prototype")) |p| if (p.isObject()) break :blk p.asObj();
        break :blk null;
    };
    try env.put("\x00IntlFallbackSym", try makeSymbolObj(a, rs, "IntlLegacyConstructedSymbol", sym_proto));

    // Helper to register one Intl service constructor with a prototype.
    const Svc = struct {
        fn install(self_a: std.mem.Allocator, shp: *Shape, e: *Environment, namespace: *value.Object, op: *value.Object, comptime name: []const u8, arity: usize, ctor_fn: value.NativeFn, ttag: ?[]const u8) EvalError!*value.Object {
            const proto = try gc_mod.allocObj(self_a);
            proto.* = .{ .proto = op };
            const ctor = try gc_mod.allocObj(self_a);
            ctor.* = .{ .native = ctor_fn, .native_ctor = true };
            try installNativeProps(self_a, shp, ctor, name, arity);
            try setNative(self_a, shp, ctor, "supportedLocalesOf", 1, intlSupportedLocalesOfFn(name));
            try ctor.setOwn(self_a, shp, "prototype", Value.obj(proto));
            try ctor.setAttr(self_a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
            try setConstructor(self_a, shp, proto, ctor);
            if (ttag) |k| {
                const full = std.fmt.allocPrint(self_a, "Intl.{s}", .{name}) catch name;
                try proto.setOwn(self_a, shp, k, try Value.strAlloc(self_a, full));
                try proto.setAttr(self_a, k, .{ .writable = false, .enumerable = false, .configurable = true });
            }
            _ = e;
            try namespace.setOwn(self_a, shp, name, Value.obj(ctor));
            try namespace.setAttr(self_a, name, .{ .writable = true, .enumerable = false, .configurable = true });
            return proto;
        }
    };

    {
        const p = try Svc.install(a, rs, env, ns, object_proto, "NumberFormat", 0, intlServiceConstructorFn("NumberFormat"), tag);
        try installIntlFormat(a, rs, p, "NumberFormat", intlNumberFormatFn);
        try setNative(a, rs, p, "formatToParts", 1, intlNumberFormatToPartsFn);
        try setNative(a, rs, p, "formatRange", 2, intlNumberFormatRangeFn);
        try setNative(a, rs, p, "formatRangeToParts", 2, intlNumberFormatRangeToPartsFn);
        try setNative(a, rs, p, "resolvedOptions", 0, intlResolvedOptionsFn("NumberFormat"));
    }
    {
        const p = try Svc.install(a, rs, env, ns, object_proto, "DateTimeFormat", 0, intlServiceConstructorFn("DateTimeFormat"), tag);
        try setNative(a, rs, p, "resolvedOptions", 0, intlResolvedOptionsFn("DateTimeFormat"));
        try installIntlFormat(a, rs, p, "DateTimeFormat", intlDateTimeFormatFn);
        try setNative(a, rs, p, "formatToParts", 1, intlDateTimeFormatToPartsFn);
        try setNative(a, rs, p, "formatRange", 2, intlDateTimeFormatRangeFn);
        try setNative(a, rs, p, "formatRangeToParts", 2, intlDateTimeFormatRangeToPartsFn);
    }
    {
        const p = try Svc.install(a, rs, env, ns, object_proto, "Collator", 0, intlServiceConstructorFn("Collator"), tag);
        try installIntlCompare(a, rs, p, intlCollatorCompareFn);
        try setNative(a, rs, p, "resolvedOptions", 0, intlResolvedOptionsFn("Collator"));
    }
    {
        const p = try Svc.install(a, rs, env, ns, object_proto, "PluralRules", 0, intlServiceConstructorFn("PluralRules"), tag);
        try setNative(a, rs, p, "select", 1, intlPluralSelectFn);
        try setNative(a, rs, p, "selectRange", 2, intlPluralSelectRangeFn);
        try setNative(a, rs, p, "resolvedOptions", 0, intlResolvedOptionsFn("PluralRules"));
    }
    {
        const p = try Svc.install(a, rs, env, ns, object_proto, "ListFormat", 0, intlServiceConstructorFn("ListFormat"), tag);
        try setNative(a, rs, p, "format", 1, intlListFormatFn);
        try setNative(a, rs, p, "formatToParts", 1, intlListFormatToPartsFn);
        try setNative(a, rs, p, "resolvedOptions", 0, intlResolvedOptionsFn("ListFormat"));
    }
    {
        const p = try Svc.install(a, rs, env, ns, object_proto, "RelativeTimeFormat", 0, intlServiceConstructorFn("RelativeTimeFormat"), tag);
        try setNative(a, rs, p, "format", 2, intlRelativeTimeFormatFn);
        try setNative(a, rs, p, "formatToParts", 2, intlRelativeTimeFormatToPartsFn);
        try setNative(a, rs, p, "resolvedOptions", 0, intlResolvedOptionsFn("RelativeTimeFormat"));
    }
    {
        // Intl.DisplayNames is the one service constructor with length 2.
        const p = try Svc.install(a, rs, env, ns, object_proto, "DisplayNames", 2, intlServiceConstructorFn("DisplayNames"), tag);
        try setNative(a, rs, p, "of", 1, intlDisplayNamesOfFn);
        try setNative(a, rs, p, "resolvedOptions", 0, intlResolvedOptionsFn("DisplayNames"));
    }
    {
        const p = try Svc.install(a, rs, env, ns, object_proto, "Segmenter", 0, intlServiceConstructorFn("Segmenter"), tag);
        try setNative(a, rs, p, "resolvedOptions", 0, intlResolvedOptionsFn("Segmenter"));
        try setNative(a, rs, p, "segment", 1, intlSegmenterSegmentFn);
        // %Segments.prototype%: containing + [@@iterator].
        const seg_proto = try gc_mod.allocObj(a);
        seg_proto.* = .{ .proto = object_proto };
        try setNative(a, rs, seg_proto, "containing", 1, intlSegmentsContainingFn);
        const iter_key: ?[]const u8 = blk: {
            if (env.get("Symbol")) |sym| if (sym.isObject()) if (sym.asObj().getOwn("iterator")) |it| if (it.isObject() and it.asObj().is_symbol) break :blk it.asObj().symbolKey();
            break :blk null;
        };
        if (iter_key) |sk| {
            try setNative(a, rs, seg_proto, sk, 0, intlSegmentsIteratorFn);
            // A symbol-keyed method's name is "[<description>]", not the internal key.
            if (seg_proto.getOwn(sk)) |mv| if (mv.isObject()) {
                try mv.asObj().setOwn(a, rs, "name", Value.str("[Symbol.iterator]"));
                try mv.asObj().setAttr(a, "name", .{ .writable = false, .enumerable = false, .configurable = true });
            };
        }
        try env.put("\x00SegmentsProto", Value.obj(seg_proto));
        // %SegmentIterator.prototype% (proto %IteratorPrototype%): next + tag.
        const seg_iter_proto = try gc_mod.allocObj(a);
        seg_iter_proto.* = .{ .proto = if (env.get("\x00IterProto")) |ip| (if (ip.isObject()) ip.asObj() else object_proto) else object_proto };
        try setNative(a, rs, seg_iter_proto, "next", 0, intlSegmentIterNextFn);
        if (tag) |k| {
            try seg_iter_proto.setOwn(a, rs, k, Value.str("Segmenter String Iterator"));
            try seg_iter_proto.setAttr(a, k, .{ .writable = false, .enumerable = false, .configurable = true });
        }
        try env.put("\x00SegIterProto", Value.obj(seg_iter_proto));
    }
    {
        const p = try Svc.install(a, rs, env, ns, object_proto, "DurationFormat", 0, intlServiceConstructorFn("DurationFormat"), tag);
        try setNative(a, rs, p, "format", 1, intlDurationFormatFn);
        try setNative(a, rs, p, "formatToParts", 1, intlDurationFormatToPartsFn);
        try setNative(a, rs, p, "resolvedOptions", 0, intlResolvedOptionsFn("DurationFormat"));
    }

    // Intl.Locale.
    {
        const proto = try gc_mod.allocObj(a);
        proto.* = .{ .proto = object_proto };
        try setNativeGetter(a, rs, proto, "baseName", intlLocaleGetter(.base_name));
        try setNativeGetter(a, rs, proto, "language", intlLocaleGetter(.language));
        try setNativeGetter(a, rs, proto, "script", intlLocaleGetter(.script));
        try setNativeGetter(a, rs, proto, "region", intlLocaleGetter(.region));
        try setNativeGetter(a, rs, proto, "variants", intlLocaleGetter(.variants));
        try setNativeGetter(a, rs, proto, "calendar", intlLocaleGetter(.calendar));
        try setNativeGetter(a, rs, proto, "caseFirst", intlLocaleGetter(.case_first));
        try setNativeGetter(a, rs, proto, "collation", intlLocaleGetter(.collation));
        try setNativeGetter(a, rs, proto, "hourCycle", intlLocaleGetter(.hour_cycle));
        try setNativeGetter(a, rs, proto, "numeric", intlLocaleGetter(.numeric));
        try setNativeGetter(a, rs, proto, "numberingSystem", intlLocaleGetter(.numbering_system));
        try setNativeGetter(a, rs, proto, "firstDayOfWeek", intlLocaleGetter(.first_day_of_week));
        try setNative(a, rs, proto, "toString", 0, intlLocaleToStringFn);
        try setNative(a, rs, proto, "maximize", 0, intlLocaleTransformFn(.max));
        try setNative(a, rs, proto, "minimize", 0, intlLocaleTransformFn(.min));
        try setNative(a, rs, proto, "getCalendars", 0, intlLocaleListFn(.calendars));
        try setNative(a, rs, proto, "getCollations", 0, intlLocaleListFn(.collations));
        try setNative(a, rs, proto, "getHourCycles", 0, intlLocaleListFn(.hour_cycles));
        try setNative(a, rs, proto, "getNumberingSystems", 0, intlLocaleListFn(.numbering_systems));
        try setNative(a, rs, proto, "getTimeZones", 0, intlLocaleTimeZonesFn);
        try setNative(a, rs, proto, "getTextInfo", 0, intlLocaleTextInfoFn);
        try setNative(a, rs, proto, "getWeekInfo", 0, intlLocaleWeekInfoFn);
        if (tag) |k| {
            try proto.setOwn(a, rs, k, Value.str("Intl.Locale"));
            try proto.setAttr(a, k, .{ .writable = false, .enumerable = false, .configurable = true });
        }
        const ctor = try gc_mod.allocObj(a);
        ctor.* = .{ .native = intlLocaleConstructorFn, .native_ctor = true };
        try installNativeProps(a, rs, ctor, "Locale", 1);
        try ctor.setOwn(a, rs, "prototype", Value.obj(proto));
        try ctor.setAttr(a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
        try setConstructor(a, rs, proto, ctor);
        try ns.setOwn(a, rs, "Locale", Value.obj(ctor));
        try ns.setAttr(a, "Locale", .{ .writable = true, .enumerable = false, .configurable = true });
    }

    try env.put("Intl", Value.obj(ns));
}

// ===== SharedArrayBuffer =============================================

/// `new SharedArrayBuffer(byteLength, { maxByteLength }?)`.
fn sharedArrayBufferConstructorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (self.new_target.isUndefined()) return self.throwError("TypeError", "Constructor SharedArrayBuffer requires 'new'");
    const len = try toIndexArg(self, if (args.len > 0) args[0] else Value.undef());
    var max: ?usize = null;
    if (args.len > 1 and args[1].isObject()) {
        const mv = try self.getProperty(args[1], "maxByteLength");
        if (!mv.isUndefined()) {
            const m = try toIndexArg(self, mv);
            if (m > 0x7fffffff or m < len) return self.throwError("RangeError", "Invalid maxByteLength");
            max = @intCast(m);
        }
    }
    // AllocateSharedArrayBuffer creates the object (including
    // GetPrototypeFromConstructor) before CreateByteDataBlock, so a throwing
    // newTarget.prototype getter wins over allocation/length RangeError.
    const proto = try self.protoFromCtor("SharedArrayBuffer");
    if (len > 0x7fffffff) return self.throwError("RangeError", "Invalid SharedArrayBuffer length");
    const storage = shared_buffer.SharedBufferStorage.create(@intCast(len), max) catch
        return self.throwError("RangeError", "SharedArrayBuffer allocation failed");
    const o = try makeSharedArrayBufferWrapper(self, storage);
    if (proto) |pr| o.setProtoAtomic(pr);
    return Value.obj(o);
}

fn sabGetter(comptime which: enum { byte_length, max_byte_length, growable }) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            _ = args;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            if (!this.isObject() or this.asObj().arrayBuffer() == null or !this.asObj().arrayBuffer().?.is_shared)
                return self.throwError("TypeError", "SharedArrayBuffer.prototype accessor called on a non-SharedArrayBuffer");
            const ab = this.asObj().arrayBuffer().?;
            return switch (which) {
                .byte_length => Value.num(@floatFromInt(ab.bytes().len)),
                .max_byte_length => Value.num(@floatFromInt(ab.max_byte_length orelse ab.bytes().len)),
                .growable => Value.boolVal(ab.max_byte_length != null),
            };
        }
    }.call;
}

/// `SharedArrayBuffer.prototype.grow(newByteLength)` — increase the length (a
/// shared buffer can only grow, never shrink). Grows the process-wide storage
/// in place, so every realm's wrapper and every length-tracking view sees the
/// new length immediately.
fn sabGrowFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject() or this.asObj().arrayBuffer() == null or !this.asObj().arrayBuffer().?.is_shared)
        return self.throwError("TypeError", "SharedArrayBuffer.prototype.grow called on a non-SharedArrayBuffer");
    const ab = this.asObj().arrayBuffer().?;
    if (ab.max_byte_length == null) return self.throwError("TypeError", "SharedArrayBuffer is not growable");
    const new_len = try toIndexArg(self, if (args.len > 0) args[0] else Value.undef());
    const storage = ab.shared orelse return self.throwError("TypeError", "SharedArrayBuffer is not growable");
    storage.grow(@intCast(new_len)) catch |err| return switch (err) {
        error.NotGrowable => self.throwError("TypeError", "SharedArrayBuffer is not growable"),
        error.OutOfRange => self.throwError("RangeError", "grow out of range"),
    };
    return Value.undef();
}

fn sharedArrayBufferSliceFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    return arrayBufferSliceImpl(@ptrCast(@alignCast(ctx)), this, args, true);
}

// ===== $262.agent (real OS-thread agents) ===========================
// test262's agent model: the main agent calls `$262.agent.start(src)` to spawn
// a worker agent running `src` in a fresh realm; they share memory through a
// SharedArrayBuffer handed over via `broadcast`, coordinate with `report`/
// `getReport`, and block/wake on `Atomics.wait`/`.notify`.
//
// `start` spawns the agent's OS thread immediately (src/agent.zig owns the
// group state, broadcast rendezvous, and the Atomics waiter table; the realm
// construction below stays here). Agents make progress while the main agent
// blocks or spins — the ordering the blocking-wait corpus requires and the
// old cooperative model could not express. Design: docs/threads/P2-agents.md.

/// `structuredClone(value, { transfer }?)` — the HTML structured-clone
/// algorithm over the engine's types (src/structured_clone.zig): a serialize/
/// deserialize round trip, so the IR doubles as the future worker
/// `postMessage` wire format. Transferred ArrayBuffers are moved (the clone
/// keeps the bytes, the source detaches).
fn queueMicrotaskFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const cb = arg0(args);
    if (!cb.isObject() or !cb.asObj().isCallableObject())
        return self.throwError("TypeError", "queueMicrotask requires a callback function");
    try promise.enqueueCallback(self, cb);
    return Value.undef();
}
fn structuredCloneFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const v = arg0(args);
    // Collect + validate the transfer list before serializing.
    var transfer: std.ArrayListUnmanaged(*value.Object) = .empty;
    if (args.len > 1 and !args[1].isUndefined() and !args[1].isNull()) {
        if (!args[1].isObject()) return self.throwError("TypeError", "structuredClone options must be an object");
        const tv = try self.getProperty(args[1], "transfer");
        if (!tv.isUndefined() and !tv.isNull()) {
            if (!tv.isObject() or !tv.asObj().is_array)
                return self.throwError("TypeError", "structuredClone transfer must be an array");
            // Snapshot the transfer list before validating entries. The list is
            // ordinary JS input, so a shared-realm sibling thread may mutate its
            // element storage while this builtin runs; validation itself must
            // not borrow `elements.items` directly.
            for (try tv.asObj().internalElementsSnapshot(self.arena)) |entry| {
                if (!entry.isObject() or entry.asObj().arrayBuffer() == null)
                    return self.throwDOMException("DataCloneError", "only ArrayBuffers are transferable");
                const ab = entry.asObj().arrayBuffer().?;
                if (ab.is_shared) return self.throwDOMException("DataCloneError", "a SharedArrayBuffer is not transferable");
                if (ab.isDetached()) return self.throwDOMException("DataCloneError", "cannot transfer a detached ArrayBuffer");
                if (ab.immutable) return self.throwDOMException("DataCloneError", "cannot transfer an immutable ArrayBuffer");
                if (ab.is_wasm_memory) return self.throwDOMException("DataCloneError", "cannot transfer a WebAssembly.Memory buffer");
                for (transfer.items) |seen| if (seen == entry.asObj())
                    return self.throwDOMException("DataCloneError", "duplicate transferable");
                try transfer.append(self.arena, entry.asObj());
            }
        }
    }
    const bytes = try structured_clone.serialize(self, self.arena, v);
    // The move: the clone owns a copy of the bytes; the sources detach now
    // (after a fully successful serialize, so a DataCloneError mid-graph
    // leaves the inputs untouched).
    for (transfer.items) |o| o.arrayBuffer().?.setDetached(true);
    return structured_clone.deserialize(self, bytes);
}

/// Wrap shared storage in a fresh SharedArrayBuffer object for *this* realm,
/// taking ownership of one reference (the caller's ref transfers in; it is
/// tracked in the realm's RetainList and released at realm teardown).
pub fn makeSharedArrayBufferWrapper(self: *Interpreter, storage: *shared_buffer.SharedBufferStorage) EvalError!*value.Object {
    var tracked = false;
    if (self.sab_retains) |rl| {
        try rl.track(storage); // on OOM, track released the ref
        tracked = true;
    }
    errdefer {
        if (tracked) {
            if (self.sab_retains) |rl| _ = rl.releaseTracked(storage);
        } else if (self.sab_retains == null) {
            // Standalone interpreters have no realm retain list, but this
            // constructor still owns the transferred reference on every path.
            storage.release();
        }
    }
    const o = (try self.newObject()).asObj();
    const ab = try self.allocArrayBufferData();
    errdefer self.destroyArrayBufferData(ab);
    ab.* = .{
        .local_data = &.{},
        .shared = storage,
        .gc_owned = self.gc_side_storage != null,
        .is_shared = true,
        .max_byte_length = if (storage.growable) storage.capacity else null,
    };
    try o.setArrayBuffer(self.arena, ab);
    errdefer o.clearArrayBuffer();
    if (self.env.get("SharedArrayBuffer")) |c| if (c.isObject()) {
        o.setProtoAtomic(try self.protoObject(c.asObj()));
    };
    tracked = false;
    return o;
}

/// An agent's thread main: run `src` in a fresh realm on this (new) thread.
/// Matches `agent.RunFn`; src/agent.zig sets the thread's agent identity
/// before calling, so the `$262` install below skips the group reset.
fn agentThreadRun(src: []const u8) void {
    var arena_state = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var env = Environment{ .arena = a, .fn_scope = true };
    const root_shape = Shape.createRoot(a) catch return;
    installGlobals(&env, root_shape) catch return;
    const global_obj = gc_mod.allocObj(a) catch return;
    global_obj.* = .{};
    env.realm_global = global_obj;
    env.put("globalThis", Value.obj(global_obj)) catch {};
    if (env.get("$262")) |d| if (d.isObject()) {
        d.asObj().setOwn(a, root_shape, "global", Value.obj(global_obj)) catch {};
    };
    const tdz = gc_mod.allocObj(a) catch return;
    tdz.* = .{};
    var microtasks = promise.MicrotaskQueue{};
    var print_buffer: std.ArrayListUnmanaged(u8) = .empty;
    // The agent realm's own SAB references (its receiveBroadcast wrapper);
    // released when the agent finishes, while the storage lives on via the
    // parent's and the broadcast slot's references.
    var sab_retains = shared_buffer.RetainList{ .gpa = std.heap.page_allocator };
    defer sab_retains.deinit();
    var async_waiters: std.ArrayListUnmanaged(AsyncWaiterEntry) = .empty;
    var machine = Interpreter{
        .arena = a,
        .env = &env,
        .global_object = global_obj,
        .this_value = Value.obj(global_obj),
        .root_shape = root_shape,
        .microtasks = &microtasks,
        .print_buffer = &print_buffer,
        .tdz_marker = tdz,
        .sab_retains = &sab_retains,
        .async_waiters = &async_waiters,
    };
    var parser = Parser.init(a, src) catch return;
    const prog = parser.parseProgram() catch return;
    machine.strict = parser.strict;
    if (Compiler.compileProgram(a, prog)) |chunk| {
        _ = vm.run(&machine, chunk, null) catch {};
    } else |_| {
        _ = machine.eval(prog) catch {};
    }
    machine.drainMicrotasks() catch {};
    machine.settleAsyncWaiters();
}

fn host262AgentStartFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const src = try self.toStringV(arg0(args));
    agent.start(src, agentThreadRun) catch return self.throwError("Error", "agent.start: could not spawn agent");
    return Value.undef();
}

/// The shared storage behind a SharedArrayBuffer or shared typed-array value.
fn sabStorageOf(v: Value) ?*shared_buffer.SharedBufferStorage {
    if (!v.isObject()) return null;
    const o = v.asObj();
    if (o.arrayBuffer()) |ab| return ab.shared;
    if (o.typedArray()) |ta| {
        const ab = ta.buffer.arrayBuffer() orelse return null;
        return ab.shared;
    }
    return null;
}

fn host262AgentBroadcastFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const storage = sabStorageOf(arg0(args)) orelse return self.throwError("TypeError", "agent.broadcast expects a SharedArrayBuffer or shared TypedArray");
    // Publishes the storage, wakes every parked agent, and blocks until each
    // live agent has received it (the INTERPRETING.md rendezvous).
    agent.broadcast(storage);
    return Value.undef();
}

fn host262AgentReceiveBroadcastFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const cb = arg0(args);
    const storage = agent.parkUntilBroadcast() orelse return Value.undef();
    const sab = try makeSharedArrayBufferWrapper(self, storage);
    const out = try self.callValueWithThis(cb, &.{Value.obj(sab)}, Value.undef());
    _ = try self.awaitValue(out);
    return Value.undef();
}

fn host262AgentReportFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const s = try self.toStringV(arg0(args));
    agent.report(s);
    return Value.undef();
}

fn host262AgentGetReportFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const r = agent.takeReport(self.arena) orelse return Value.nul(); // none available (harness polls)
    return try Value.strAlloc(self.arena, r);
}

fn host262AgentNoopFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = ctx;
    _ = this;
    _ = args;
    return Value.undef();
}

fn host262AgentSleepFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const ms = try self.toNumberV(arg0(args));
    agent.sleepMs(ms);
    return Value.undef();
}

fn host262AgentMonotonicNowFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = ctx;
    _ = this;
    _ = args;
    return Value.num(agent.monotonicNowMs());
}

/// Install `$262.agent` with the parent-side (start/broadcast/getReport) and
/// agent-side (receiveBroadcast/report/leaving) primitives.
fn installAgent(a: std.mem.Allocator, rs: *Shape, d: *value.Object) EvalError!void {
    const ag = try gc_mod.allocObj(a);
    ag.* = .{};
    try setNative(a, rs, ag, "start", 1, host262AgentStartFn);
    try setNative(a, rs, ag, "broadcast", 1, host262AgentBroadcastFn);
    try setNative(a, rs, ag, "getReport", 0, host262AgentGetReportFn);
    try setNative(a, rs, ag, "sleep", 1, host262AgentSleepFn);
    try setNative(a, rs, ag, "monotonicNow", 0, host262AgentMonotonicNowFn);
    try setNative(a, rs, ag, "receiveBroadcast", 1, host262AgentReceiveBroadcastFn);
    try setNative(a, rs, ag, "report", 1, host262AgentReportFn);
    try setNative(a, rs, ag, "leaving", 0, host262AgentNoopFn);
    try d.setOwn(a, rs, "agent", Value.obj(ag));
}

// ===== Atomics =======================================================

/// ValidateIntegerTypedArray: the receiver must be an integer typed array (not
/// a Float or Uint8Clamped view) over an attached buffer; returns the in-bounds
/// element index from ToIndex(request).
fn atomicsValidate(self: *Interpreter, ta_v: Value, idx_v: Value, write: bool, only_int32: bool, require_shared: bool) value.HostError!struct { ta: *value.TypedArrayData, i: usize } {
    if (!ta_v.isObject() or ta_v.asObj().typedArray() == null) return self.throwError("TypeError", "Atomics operand must be an integer TypedArray");
    const ta = ta_v.asObj().typedArray().?;
    // ValidateIntegerTypedArray(typedArray, waitable): a waitable op
    // (wait/notify/waitAsync) only accepts Int32Array or BigInt64Array; the
    // kind check runs BEFORE the index is coerced to ToIndex.
    if (only_int32) {
        if (ta.kind != .i32 and ta.kind != .i64)
            return self.throwError("TypeError", "Typed array argument must be an Int32Array or BigInt64Array.");
    } else switch (ta.kind) {
        .i8, .u8, .i16, .u16, .i32, .u32, .i64, .u64 => {},
        else => return self.throwError("TypeError", "Typed array argument must be an Int8Array, Int16Array, Int32Array, Uint8Array, Uint16Array, Uint32Array, BigInt64Array, or BigUint64Array."),
    }
    // ValidateSharedIntegerTypedArray(true): `Atomics.wait` additionally
    // requires a SharedArrayBuffer, also checked before the index is coerced.
    if (require_shared and !ta.buffer.arrayBuffer().?.is_shared)
        return self.throwError("TypeError", "Typed array for wait/waitAsync/notify must wrap a SharedArrayBuffer.");
    // ValidateTypedArray(write): reject an immutable buffer before the index is
    // coerced (the value isn't coerced yet either).
    if (write and ta.buffer.arrayBuffer().?.immutable) return self.throwError("TypeError", "Atomics cannot write to an immutable ArrayBuffer");
    // ValidateTypedArray: a detached or out-of-bounds view (a resizable buffer
    // shrank below a fixed view's extent) is a TypeError, thrown before the index
    // is coerced. currentLength() folds in both, and also re-witnesses a
    // length-tracking view against the live buffer size — the length that
    // MakeTypedArrayWithBufferWitnessRecord/TypedArrayLength would compute.
    const cur_len = ta.currentLength() orelse return self.throwError("TypeError", "TypedArray is out of bounds for atomic access");
    // ValidateAtomicAccess bounds-checks against that *current* length, not the
    // cached one: a grown buffer exposes the new indices, and a length-tracking
    // view that shrank rejects a now-past-the-end index with a RangeError.
    const i = try toIndexArg(self, idx_v);
    if (i >= cur_len) return self.throwError("RangeError", "Access index out of bounds for atomic access.");
    return .{ .ta = ta, .i = @intCast(i) };
}

/// Coerce an Atomics value argument per the element type (ToBigInt for BigInt
/// views, else ToIntegerOrInfinity).
fn atomicsCoerce(self: *Interpreter, ta: *value.TypedArrayData, v: Value) value.HostError!f64 {
    if (ta.kind.isBigInt()) {
        const bv = try self.toBigIntValueImpl(v, false);
        return @floatFromInt(@as(i64, @truncate(bv.asObj().bigIntValue())));
    }
    // ToIntegerOrInfinity: NaN coerces to +0 and -0 normalizes to +0 (so the
    // value `Atomics.store` returns matches ToInteger, e.g. store(view,i,-0)===+0).
    const num = try self.toNumberV(v);
    if (std.math.isNan(num)) return 0;
    const t = @trunc(num);
    return if (t == 0) 0 else t;
}

fn atomicsReadV(self: *Interpreter, ta: *const value.TypedArrayData, i: usize) Value {
    if (ta.kind.isBigInt()) return self.makeBigInt(value.taReadBig(ta, i)) catch Value.undef();
    return value.taRead(ta, i);
}
fn atomicsWriteN(ta: *value.TypedArrayData, i: usize, n: f64) void {
    if (ta.kind.isBigInt()) value.taWriteBig(ta, i, @intFromFloat(n)) else value.taWrite(ta, i, n);
}

/// Coerce an Atomics value argument to the element's raw bits (the atomic
/// paths' counterpart of `atomicsCoerce`; routes BigInt views through i64
/// directly, preserving the 64-bit precision the f64 route loses).
fn atomicsCoerceRaw(self: *Interpreter, ta: *value.TypedArrayData, v: Value) value.HostError!u64 {
    if (ta.kind.isBigInt()) {
        const bv = try self.toBigIntValueImpl(v, false);
        return @bitCast(@as(i64, @truncate(bv.asObj().bigIntValue())));
    }
    return value.taNumToRaw(ta.kind, try atomicsCoerce(self, ta, v));
}

/// The previous element value (raw bits) as the JS value an Atomics op returns.
fn atomicsRawToValue(self: *Interpreter, kind: value.TAKind, raw: u64) value.HostError!Value {
    if (kind == .i64) return self.makeBigInt(@as(i64, @bitCast(raw)));
    if (kind == .u64) return self.makeBigInt(@as(i128, raw));
    return Value.num(value.taRawToF64(kind, raw));
}

/// A read-modify-write Atomics op (`add`/`and`/`or`/`xor`/`sub`/`exchange`).
/// RevalidateAtomicAccess: coercing an Atomics index/value argument runs
/// user `valueOf`/`Symbol.toPrimitive`, which may detach or shrink the buffer.
/// Re-check just before the actual read/write — a detached (or now out-of-bounds)
/// buffer is a TypeError.
fn atomicsRevalidate(self: *Interpreter, ta: *value.TypedArrayData, i: usize) value.HostError!void {
    const ab = ta.buffer.arrayBuffer() orelse return self.throwError("TypeError", "ArrayBuffer is detached");
    if (ab.isDetached()) return self.throwError("TypeError", "ArrayBuffer is detached");
    const len = ta.currentLength() orelse return self.throwError("TypeError", "TypedArray is out of bounds for atomic access");
    if (i >= len) return self.throwError("TypeError", "TypedArray is out of bounds for atomic access");
}

fn atomicsRMWFn(comptime op: enum { add, sub, and_, or_, xor, exchange }) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            _ = this;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            if (args.len > 0 and jsthread.isPropertyMode(self, args[0])) {
                if (op == .exchange) return jsthread.propExchange(self, args);
                const prop_op: jsthread.PropRmwOp = switch (op) {
                    .add => .add,
                    .sub => .sub,
                    .and_ => .and_,
                    .or_ => .or_,
                    .xor => .xor,
                    .exchange => unreachable,
                };
                return jsthread.propRmw(self, prop_op, args);
            }
            const vd = try atomicsValidate(self, if (args.len > 0) args[0] else Value.undef(), if (args.len > 1) args[1] else Value.undef(), true, false, false);
            const operand = try atomicsCoerceRaw(self, vd.ta, if (args.len > 2) args[2] else Value.undef());
            try atomicsRevalidate(self, vd.ta, vd.i); // the operand coercion may have detached the buffer
            // One hardware RMW — agents racing over a SharedArrayBuffer can
            // never lose an update or observe a torn element.
            const old_raw = switch (op) {
                .add => value.taAtomicRmwRaw(.Add, vd.ta, vd.i, operand),
                .sub => value.taAtomicRmwRaw(.Sub, vd.ta, vd.i, operand),
                .and_ => value.taAtomicRmwRaw(.And, vd.ta, vd.i, operand),
                .or_ => value.taAtomicRmwRaw(.Or, vd.ta, vd.i, operand),
                .xor => value.taAtomicRmwRaw(.Xor, vd.ta, vd.i, operand),
                .exchange => value.taAtomicRmwRaw(.Xchg, vd.ta, vd.i, operand),
            };
            return atomicsRawToValue(self, vd.ta.kind, old_raw);
        }
    }.call;
}

fn atomicsLoadFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len > 0 and jsthread.isPropertyMode(self, args[0])) return jsthread.propLoad(self, args);
    const vd = try atomicsValidate(self, if (args.len > 0) args[0] else Value.undef(), if (args.len > 1) args[1] else Value.undef(), false, false, false);
    try atomicsRevalidate(self, vd.ta, vd.i); // the index coercion may have detached the buffer
    return atomicsRawToValue(self, vd.ta.kind, value.taAtomicLoadRaw(vd.ta, vd.i));
}
fn atomicsStoreFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len > 0 and jsthread.isPropertyMode(self, args[0])) return jsthread.propStore(self, args);
    const vd = try atomicsValidate(self, if (args.len > 0) args[0] else Value.undef(), if (args.len > 1) args[1] else Value.undef(), true, false, false);
    const arg_v = if (args.len > 2) args[2] else Value.undef();
    if (vd.ta.kind.isBigInt()) {
        const bv = try self.toBigIntValueImpl(arg_v, false);
        const as64: i64 = @truncate(bv.asObj().bigIntValue());
        try atomicsRevalidate(self, vd.ta, vd.i); // the value coercion may have detached the buffer
        value.taAtomicStoreRaw(vd.ta, vd.i, @bitCast(as64));
        return self.makeBigInt(as64);
    }
    // store returns the *integer* value written, un-reduced (ToInteger, not
    // wrapped to the element width).
    const n = try atomicsCoerce(self, vd.ta, arg_v);
    try atomicsRevalidate(self, vd.ta, vd.i); // the value coercion may have detached the buffer
    value.taAtomicStoreRaw(vd.ta, vd.i, value.taNumToRaw(vd.ta.kind, n));
    return Value.num(n);
}
fn atomicsCompareExchangeFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len > 0 and jsthread.isPropertyMode(self, args[0])) return jsthread.propCompareExchange(self, args);
    const vd = try atomicsValidate(self, if (args.len > 0) args[0] else Value.undef(), if (args.len > 1) args[1] else Value.undef(), true, false, false);
    const expected = try atomicsCoerceRaw(self, vd.ta, if (args.len > 2) args[2] else Value.undef());
    const replacement = try atomicsCoerceRaw(self, vd.ta, if (args.len > 3) args[3] else Value.undef());
    try atomicsRevalidate(self, vd.ta, vd.i); // the operand coercions may have detached the buffer
    const old_raw = value.taAtomicCasRaw(vd.ta, vd.i, expected, replacement);
    return atomicsRawToValue(self, vd.ta.kind, old_raw);
}
fn atomicsIsLockFreeFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const n = try self.toNumberV(if (args.len > 0) args[0] else Value.undef());
    const sz = @trunc(n);
    return Value.boolVal(sz == 1 or sz == 2 or sz == 4 or sz == 8);
}
fn atomicsWaitFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len > 0 and jsthread.isPropertyMode(self, args[0])) {
        const t_ms = if (args.len > 3) try self.toNumberV(args[3]) else std.math.nan(f64);
        const t_ns: ?u64 = if (std.math.isNan(t_ms) or t_ms == std.math.inf(f64)) null else if (t_ms <= 0) 0 else if (t_ms >= 1e12) null else @intFromFloat(t_ms * std.time.ns_per_ms);
        return jsthread.propWait(self, args, t_ns);
    }
    if (args.len > 0 and args[0].isObject() and args[0].asObj().typedArray() != null and self.gil != null and jsthread.currentThreadId() != 0)
        return self.throwError("TypeError", "Atomics.wait cannot be called from the current thread.");
    const vd = try atomicsValidate(self, if (args.len > 0) args[0] else Value.undef(), if (args.len > 1) args[1] else Value.undef(), false, true, true);
    const expected_raw = try atomicsCoerceRaw(self, vd.ta, if (args.len > 2) args[2] else Value.undef());
    // ToNumber(timeout): NaN → wait forever; negative clamps to 0.
    const timeout_ms: f64 = if (args.len > 3) try self.toNumberV(args[3]) else std.math.nan(f64);
    const timeout_ns: ?u64 = if (std.math.isNan(timeout_ms) or timeout_ms == std.math.inf(f64))
        null
    else if (timeout_ms <= 0)
        0
    else if (timeout_ms >= 1e12)
        null // effectively unbounded; the runner watchdog is the backstop
    else
        @intFromFloat(timeout_ms * std.time.ns_per_ms);
    // AgentCanSuspend check runs after every coercion.
    if (!agent.canBlock(self.main_can_block)) return self.throwError("TypeError", "Atomics.wait cannot block this agent");
    const ab = vd.ta.buffer.arrayBuffer().?;
    const storage = ab.shared orelse return self.throwError("TypeError", "Atomics.wait requires a shared buffer");
    const offset = vd.ta.byte_offset + vd.i * vd.ta.kind.byteSize();
    // A GIL'd thread must not park holding the VM lock — its notifier needs
    // it to run. Publish a conservative scan range first so a mid-script
    // collection on another thread can root this parked stack (defers run LIFO:
    // reacquire the GIL, then mark unparked).
    const park_with_gil = self.use_thread_gil and self.gil != null;
    if (park_with_gil) stack_scan.beginPark();
    defer if (park_with_gil) stack_scan.endPark();
    if (park_with_gil) self.gil.?.release();
    defer if (park_with_gil) self.gil.?.acquire();
    const outcome = if (vd.ta.kind == .i64)
        agent.wait(storage, offset, i64, @bitCast(expected_raw), timeout_ns)
    else
        agent.wait(storage, offset, i32, @bitCast(@as(u32, @truncate(expected_raw))), timeout_ns);
    return switch (outcome) {
        .ok => Value.str("ok"),
        .not_equal => Value.str("not-equal"),
        .timed_out => Value.str("timed-out"),
        .interrupted => Value.str("timed-out"), // plain Atomics.wait has no interrupt source
    };
}
/// `Atomics.pause(N)` — a microarchitectural pause hint. `N`, if present, must
/// be an integral Number (the iteration count); anything else is a TypeError.
/// In this single-threaded engine there is nothing to spin on, so it is a
/// no-op that returns undefined after validating the argument.
fn atomicsPauseFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len > 0 and !args[0].isUndefined()) {
        const n = args[0];
        if (!n.isNumber() or std.math.isNan(n.asNum()) or std.math.isInf(n.asNum()) or @trunc(n.asNum()) != n.asNum())
            return self.throwError("TypeError", "Atomics.pause iterationNumber must be an integer");
    }
    return Value.undef();
}
fn atomicsNotifyFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len > 0 and jsthread.isPropertyMode(self, args[0])) return jsthread.propNotify(self, args);
    const vd = try atomicsValidate(self, if (args.len > 0) args[0] else Value.undef(), if (args.len > 1) args[1] else Value.undef(), false, true, false);
    // count: ToIntegerOrInfinity, default +∞, negatives clamp to 0.
    var count: usize = std.math.maxInt(usize);
    if (args.len > 2 and !args[2].isUndefined()) {
        const n = try self.toNumberV(args[2]);
        if (std.math.isNan(n) or n <= 0) {
            count = 0;
        } else if (n != std.math.inf(f64) and n < 1e18) {
            count = @intFromFloat(@trunc(n));
        }
    }
    // Waiters only ever exist on shared buffers; notify on a non-shared
    // integer view validly wakes nobody.
    const storage = vd.ta.buffer.arrayBuffer().?.shared orelse return Value.num(0);
    const offset = vd.ta.byte_offset + vd.i * vd.ta.kind.byteSize();
    return Value.num(@floatFromInt(agent.notify(storage, offset, count)));
}

/// `Atomics.waitAsync(typedArray, index, value, timeout)` — the non-blocking
/// form of `wait`. Like `wait`, DoWait runs ValidateSharedIntegerTypedArray, so
/// the buffer must be shared; in this single-threaded engine no other agent can
/// ever notify, so an actual wait yields a forever pending promise and the
/// early-out cases resolve synchronously.
fn atomicsWaitAsyncFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len > 0 and jsthread.isPropertyMode(self, args[0])) {
        const t_ms = if (args.len > 3) try self.toNumberV(args[3]) else std.math.nan(f64);
        const t_ns: ?u64 = if (std.math.isNan(t_ms) or t_ms == std.math.inf(f64)) null else if (t_ms <= 0) 0 else if (t_ms >= 1e12) null else @intFromFloat(t_ms * std.time.ns_per_ms);
        return jsthread.propWaitAsync(self, args, t_ns);
    }
    const vd = try atomicsValidate(self, if (args.len > 0) args[0] else Value.undef(), if (args.len > 1) args[1] else Value.undef(), false, true, true);
    const expected_raw = try atomicsCoerceRaw(self, vd.ta, if (args.len > 2) args[2] else Value.undef());
    const timeout_ms: f64 = if (args.len > 3) try self.toNumberV(args[3]) else std.math.nan(f64);
    const timeout_ns: ?u64 = if (std.math.isNan(timeout_ms) or timeout_ms == std.math.inf(f64))
        null
    else if (timeout_ms <= 0)
        0
    else if (timeout_ms >= 1e12)
        null
    else
        @intFromFloat(timeout_ms * std.time.ns_per_ms);
    const ab = vd.ta.buffer.arrayBuffer().?;
    const storage = ab.shared orelse return self.throwError("TypeError", "Atomics.waitAsync requires a shared buffer");
    const offset = vd.ta.byte_offset + vd.i * vd.ta.kind.byteSize();
    const res = (try self.newObject()).asObj();
    // Register the async ticket (the value re-check and the timeout-0 early-out
    // both happen inside the waiter table's critical section).
    const enq = if (self.async_waiters == null)
        // No settle loop wired in this host: report "timed-out" synchronously
        // rather than minting a promise nothing will ever resolve.
        agent.AsyncEnqueue.timed_out
    else if (vd.ta.kind == .i64)
        agent.waitAsyncEnqueue(storage, offset, i64, @bitCast(expected_raw), timeout_ns, @ptrCast(self.async_waiters.?))
    else
        agent.waitAsyncEnqueue(storage, offset, i32, @bitCast(@as(u32, @truncate(expected_raw))), timeout_ns, @ptrCast(self.async_waiters.?));
    switch (enq) {
        .not_equal => {
            try self.setProp(res, "async", Value.boolVal(false));
            try self.setProp(res, "value", Value.str("not-equal"));
        },
        .timed_out => {
            try self.setProp(res, "async", Value.boolVal(false));
            try self.setProp(res, "value", Value.str("timed-out"));
        },
        .enqueued => |id| {
            const cap = try newPromiseCapability(self, self.env.get("Promise") orelse Value.undef());
            self.appendAsyncWaiter(.{ .id = id, .promise = cap.promise }) catch {
                agent.abandonAsync(@ptrCast(self.async_waiters.?));
                return error.OutOfMemory;
            };
            try self.setProp(res, "async", Value.boolVal(true));
            try self.setProp(res, "value", cap.promise);
        },
    }
    return Value.obj(res);
}

/// A typed-array constructor for `kind` (`new Int8Array(...)`, …).
fn typedArrayCtorFn(comptime kind: value.TAKind) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            _ = this;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            if (self.new_target.isUndefined()) return self.throwError("TypeError", "Constructor TypedArray requires 'new'");
            return self.makeTypedArray(kind, args);
        }
    }.call;
}

// ===== Module Namespace exotic object ===============================
// A `[[Module]]` namespace exposes its module's exported bindings as live,
// non-configurable, non-writable-by-the-spec-but-observably-writable data
// properties, sorted by code unit, plus `[Symbol.toStringTag] = "Module"`. It
// is non-extensible with a null prototype, and rejects [[Set]]/[[Delete]]/
// [[DefineOwnProperty]]/[[SetPrototypeOf]] (except no-op preserving cases).

pub const ModuleNs = struct {
    names: [][]const u8, // sorted export names (strings only)
    envs: []*Environment, // parallel: the env holding each binding
    locals: [][]const u8, // parallel: local binding name in that env
    tag_key: []const u8, // the @@toStringTag property key
    // `import defer * as ns`: until `defer_module` is evaluated, a *string*-keyed
    // operation (a binding [[Get]]/[[HasProperty]]/[[GetOwnProperty]]/[[Delete]]/
    // [[DefineOwnProperty]] or [[OwnPropertyKeys]]) triggers its evaluation first.
    // Symbol keys (incl. @@toStringTag), [[Set]], and the structural traps do not.
    deferred: bool = false,
    defer_module: ?*anyopaque = null, // *Context.Module, evaluated via defer_trigger
};

/// Trigger ModuleEvaluation of a deferred namespace's backing module (once — its
/// `evaluated` flag makes a repeat a no-op). Used by [[OwnPropertyKeys]], which
/// always triggers.
fn triggerDeferModule(self: *Interpreter, ns: *ModuleNs) EvalError!void {
    if (!ns.deferred) return;
    const mod = ns.defer_module orelse return;
    if (self.defer_trigger) |f| try f(self.defer_trigger_ctx.?, self, mod);
}

/// IsSymbolLikeNamespaceKey: a symbol/private key, or — on a *deferred*
/// namespace — the key "then" (so `await`-ing a deferred namespace neither
/// triggers evaluation nor reads an export). Such keys behave as absent.
fn isSymbolLikeNsKey(ns: *ModuleNs, key: []const u8) bool {
    return value.isSymbolKey(key) or value.isPrivateKey(key) or
        (ns.deferred and std.mem.eql(u8, key, "then"));
}

/// A deferred-namespace access of a *string* key triggers evaluation; a
/// symbol-like key (symbol/private, or "then") never does.
fn triggerDeferIfString(self: *Interpreter, ns: *ModuleNs, key: []const u8) EvalError!void {
    if (isSymbolLikeNsKey(ns, key)) return;
    try triggerDeferModule(self, ns);
}

/// Object-level wrappers for the builtin reflection paths (no-op unless `o` is a
/// deferred module namespace).
pub fn triggerDeferForKey(self: *Interpreter, o: *value.Object, key: []const u8) EvalError!void {
    if (moduleNsOf(o)) |ns| try triggerDeferIfString(self, ns, key);
}
pub fn triggerDeferForOwnKeys(self: *Interpreter, o: *value.Object) EvalError!void {
    if (moduleNsOf(o)) |ns| try triggerDeferModule(self, ns);
}

fn moduleNsOf(o: *value.Object) ?*ModuleNs {
    if (o.moduleNs()) |p| return @ptrCast(@alignCast(p));
    return null;
}

fn moduleNsIndex(ns: *ModuleNs, name: []const u8) ?usize {
    for (ns.names, 0..) |n, i| if (std.mem.eql(u8, n, name)) return i;
    return null;
}

/// [[Get]] for a module namespace: live binding read; an uninitialized (TDZ)
/// binding throws ReferenceError.
fn moduleNsGet(self: *Interpreter, ns: *ModuleNs, key: []const u8) EvalError!Value {
    if (std.mem.eql(u8, key, ns.tag_key)) return if (ns.deferred) Value.str("Deferred Module") else Value.str("Module");
    // On a deferred namespace, "then" is symbol-like: it reads as absent
    // (OrdinaryGet), never the export binding — so it can't throw a TDZ error.
    if (ns.deferred and std.mem.eql(u8, key, "then")) return Value.undef();
    if (moduleNsIndex(ns, key)) |i| {
        const v = ns.envs[i].get(ns.locals[i]) orelse Value.undef();
        if (self.tdz_marker) |tz| if (v.isObject() and v.asObj() == tz)
            return self.throwError("ReferenceError", "Cannot access uninitialized binding");
        return v;
    }
    return Value.undef();
}

/// [[HasProperty]]: a string export, or the @@toStringTag key. On a deferred
/// namespace, "then" is symbol-like and reads as absent.
fn moduleNsHas(ns: *ModuleNs, key: []const u8) bool {
    if (ns.deferred and std.mem.eql(u8, key, "then")) return false;
    return std.mem.eql(u8, key, ns.tag_key) or moduleNsIndex(ns, key) != null;
}

pub fn isModuleNs(o: *value.Object) bool {
    return o.moduleNs() != null;
}

/// The string export names of a module namespace, sorted by code unit (for
/// Object.keys / getOwnPropertyNames). Empty slice for a non-namespace.
pub fn moduleNsNames(o: *value.Object) []const []const u8 {
    if (moduleNsOf(o)) |ns| return ns.names;
    return &.{};
}

/// `propertyIsEnumerable`-style flag: string exports are enumerable, the
/// @@toStringTag is not, an absent key is not.
pub fn moduleNsEnumerable(o: *value.Object, key: []const u8) bool {
    if (moduleNsOf(o)) |ns| return moduleNsIndex(ns, key) != null;
    return false;
}

/// [[GetOwnProperty]] for a module namespace as a descriptor object (or
/// undefined if the key is absent). A string export is { value (live, TDZ
/// throws), writable:true, enumerable:true, configurable:false }; the
/// @@toStringTag is a frozen string.
pub fn moduleNsDesc(self: *Interpreter, o: *value.Object, key: []const u8) EvalError!Value {
    const ns = moduleNsOf(o) orelse return Value.undef();
    // On a deferred namespace, "then" is symbol-like → absent (no descriptor).
    if (ns.deferred and std.mem.eql(u8, key, "then")) return Value.undef();
    if (std.mem.eql(u8, key, ns.tag_key)) {
        const d = (try self.newObject()).asObj();
        try self.setProp(d, "value", if (ns.deferred) Value.str("Deferred Module") else Value.str("Module"));
        try self.setProp(d, "writable", Value.boolVal(false));
        try self.setProp(d, "enumerable", Value.boolVal(false));
        try self.setProp(d, "configurable", Value.boolVal(false));
        return Value.obj(d);
    }
    if (moduleNsIndex(ns, key) != null) {
        const v = try moduleNsGet(self, ns, key); // live read; TDZ throws ReferenceError
        const d = (try self.newObject()).asObj();
        try self.setProp(d, "value", v);
        try self.setProp(d, "writable", Value.boolVal(true));
        try self.setProp(d, "enumerable", Value.boolVal(true));
        try self.setProp(d, "configurable", Value.boolVal(false));
        return Value.obj(d);
    }
    return Value.undef();
}

pub fn installGlobals(env: *Environment, root_shape: *Shape) EvalError!void {
    return installGlobalsInner(env, root_shape, null);
}

/// `parent_symbol`, when non-null (a `$262.createRealm()` child realm), is the
/// creating realm's `Symbol` object: the well-known symbols are *shared* across
/// realms, so the child reuses those same symbol objects (identity holds across
/// realms) and keys all its `@@`-methods under them.
pub fn installGlobalsInner(env: *Environment, root_shape: *Shape, parent_symbol: ?*value.Object) EvalError!void {
    const a = env.arena;
    const error_names = [_][]const u8{
        "Error",           "TypeError",        "RangeError", "ReferenceError",
        "SyntaxError",     "EvalError",        "URIError",   "AggregateError",
        "SuppressedError", "OutOfMemoryError",
    };
    for (error_names) |name| {
        const o = try gc_mod.allocObj(a);
        o.* = .{ .private_data = @ptrCast(env) };
        try o.setErrorCtor(a, name);
        // AggregateError(errors, message) has arity 2; SuppressedError(error,
        // suppressed, message) arity 3; the others (message) 1.
        const arity: usize = if (std.mem.eql(u8, name, "SuppressedError")) 3 else if (std.mem.eql(u8, name, "AggregateError")) 2 else 1;
        try installNativeProps(a, root_shape, o, name, arity);
        try env.put(name, Value.obj(o));
    }
    try env.put("NaN", Value.num(std.math.nan(f64)));
    try env.put("Infinity", Value.num(std.math.inf(f64)));
    try env.put("undefined", Value.undef());

    // Global functions.
    try defineGlobalFn(env, root_shape, "eval", 1, evalFn);
    if (env.get("eval")) |ev| {
        if (ev.isObject()) ev.asObj().private_data = @ptrCast(env);
        try env.put("\x00evalIntrinsic", ev);
    }
    try defineGlobalFn(env, root_shape, "parseInt", 2, builtins.parseIntFn);
    try defineGlobalFn(env, root_shape, "parseFloat", 1, builtins.parseFloatFn);
    try defineGlobalFn(env, root_shape, "queueMicrotask", 1, queueMicrotaskFn);
    try defineGlobalFn(env, root_shape, "structuredClone", 1, structuredCloneFn);
    try defineGlobalFn(env, root_shape, "btoa", 1, btoaFn);
    try defineGlobalFn(env, root_shape, "atob", 1, atobFn);
    try defineGlobalFn(env, root_shape, "isNaN", 1, builtins.isNaNFn);
    try defineGlobalFn(env, root_shape, "isFinite", 1, builtins.isFiniteFn);
    try defineGlobalFn(env, root_shape, "encodeURI", 1, builtins.encodeURIFn);
    try defineGlobalFn(env, root_shape, "encodeURIComponent", 1, builtins.encodeURIComponentFn);
