        try date_proto.setAttr(a, "toGMTString", .{ .enumerable = false, .configurable = true, .writable = true });
    }
    // Date.prototype.toJSON is intentionally *generic* (works on any object),
    // not brand-checked: ToObject(this), ToPrimitive(number); a non-finite value
    // returns null, otherwise Invoke(O, "toISOString").
    try setNative(a, root_shape, date_proto, "toJSON", 1, dateToJSONFn);
    try setNative(a, root_shape, date_proto, "toTemporalInstant", 0, dateToTemporalInstantFn);
    // Date.prototype[Symbol.toPrimitive] — non-enumerable, non-writable,
    // configurable; OrdinaryToPrimitive with a validated hint.
    if (env.get("Symbol")) |sym| if (sym.isObject()) {
        if (sym.asObj().getOwn("toPrimitive")) |tp| if (tp.isObject() and tp.asObj().is_symbol) {
            const m = try gc_mod.allocObj(a);
            m.* = .{ .native = dateSymbolToPrimitiveFn };
            try installNativeProps(a, root_shape, m, "[Symbol.toPrimitive]", 1);
            try date_proto.setOwn(a, root_shape, tp.asObj().symbolKey(), Value.obj(m));
            try date_proto.setAttr(a, tp.asObj().symbolKey(), .{ .writable = false, .enumerable = false, .configurable = true });
        };
    };
    try date_ns.setOwn(a, root_shape, "prototype", Value.obj(date_proto));
    try date_ns.setAttr(a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
    try setConstructor(a, root_shape, date_proto, date_ns);
    try env.put("Date", Value.obj(date_ns));

    // ArrayBuffer + typed arrays last, after Object.prototype exists.
    try installTypedArrays(env, root_shape);

    // BigInt is callable and has [[Construct]] for IsConstructor probes, but
    // the constructor path throws inside bigIntFn.
    {
        const bi_proto = try gc_mod.allocObj(a);
        bi_proto.* = .{ .proto = object_proto };
        try setNative(a, root_shape, bi_proto, "toString", 0, bigIntToStringFn);
        try setNative(a, root_shape, bi_proto, "valueOf", 0, bigIntValueOfFn);
        try setNative(a, root_shape, bi_proto, "toLocaleString", 0, bigIntToLocaleStringFn);
        // BigInt.prototype[Symbol.toStringTag] = "BigInt" (so
        // `Object.prototype.toString.call(1n)` → "[object BigInt]").
        if (env.get("Symbol")) |sym| if (sym.isObject()) {
            if (sym.asObj().getOwn("toStringTag")) |tt| if (tt.isObject() and tt.asObj().is_symbol) {
                try bi_proto.setOwn(a, root_shape, tt.asObj().symbolKey(), Value.str("BigInt"));
                try bi_proto.setAttr(a, tt.asObj().symbolKey(), .{ .writable = false, .enumerable = false, .configurable = true });
            };
        };
        const bi_ns = try gc_mod.allocObj(a);
        bi_ns.* = .{ .native = bigIntFn, .native_ctor = true, .proto = func_proto, .private_data = @ptrCast(env) };
        try installNativeProps(a, root_shape, bi_ns, "BigInt", 1);
        try setNative(a, root_shape, bi_ns, "asIntN", 2, bigIntAsIntNFn(true));
        try setNative(a, root_shape, bi_ns, "asUintN", 2, bigIntAsIntNFn(false));
        try bi_ns.setOwn(a, root_shape, "prototype", Value.obj(bi_proto));
        try bi_ns.setAttr(a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
        try setConstructor(a, root_shape, bi_proto, bi_ns);
        try env.put("BigInt", Value.obj(bi_ns));
    }

    // The test262 `$262` host object (its `global` is set by the realm owner).
    try install262(env, root_shape, object_proto);

    // The WebAssembly JS API (issue #141, part 1): the WebAssembly namespace,
    // its CompileError/LinkError/RuntimeError constructors, and Module.
    try wasm_api.installWebAssembly(env, root_shape);
}

/// `next()` for a `makeCursorIterator` object: yields successive elements of the
/// captured array/string, then `{ done: true }`.
/// `Array.prototype[Symbol.iterator]` / `Array.prototype.values`: returns a
/// fresh index cursor over `this`. Installed as a real own property so it can be
/// deleted or replaced; the iteration paths recognize this exact native to take
/// their fast index path.
fn arrayValuesIterFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (this.isUndefined() or this.isNull())
        return self.throwError("TypeError", "Array.prototype.values called on null or undefined");
    return self.makeCursorIterator(this);
}

/// `String.prototype[Symbol.iterator]` — RequireObjectCoercible(this), then a
/// String Iterator over ToString(this).
fn stringIteratorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (this.isUndefined() or this.isNull())
        return self.throwError("TypeError", "String.prototype[Symbol.iterator] called on null or undefined");
    return self.makeCursorIterator(try Value.strAlloc(self.arena, try self.toStringWtf8(this)));
}

/// %RegExpStringIteratorPrototype%.next — lazily RegExpExec the matcher against
/// the saved string, advancing past empty matches when the matcher is global.
fn regexpStringIterNext(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return self.throwError("TypeError", "next called on non-object");
    const o = this.asObj();
    const matcher = o.getOwn("__re") orelse
        return self.throwError("TypeError", "next called on an incompatible receiver");
    if (o.getOwn("__done")) |d| if (d.toBoolean()) return self.iterResultObj(Value.undef(), true);
    const s = try (o.getOwn("__str") orelse Value.str("")).asWtf8(self.arena);
    const global = (o.getOwn("__g") orelse Value.boolVal(false)).toBoolean();
    const unicode = (o.getOwn("__u") orelse Value.boolVal(false)).toBoolean();
    const match = try self.regexpExecGeneric(matcher, s);
    if (match.isNull()) {
        try self.setProp(o, "__done", Value.boolVal(true));
        return self.iterResultObj(Value.undef(), true);
    }
    if (!global) {
        try self.setProp(o, "__done", Value.boolVal(true));
        return self.iterResultObj(match, false);
    }
    // Global: a zero-length match would otherwise stall lastIndex; bump it past
    // the current position (honouring surrogate pairs under the `u`/`v` flag).
    const match_str = try self.toStringWtf8(try self.getProperty(match, "0"));
    if (match_str.len == 0) {
        const this_index = toLen(try self.toNumberV(try self.getProperty(matcher, "lastIndex")));
        const next_index = Interpreter.advanceStringIndex(s, this_index, unicode);
        try self.setRegExpLikeLastIndex(matcher, @floatFromInt(next_index));
    }
    return self.iterResultObj(match, false);
}

fn canonicalCollectionKey(v: Value) Value {
    return if (v.isNumber() and v.asNum() == 0) Value.num(0) else v;
}

var collection_key_comparisons_for_testing: std.atomic.Value(u64) = .init(0);

pub fn resetCollectionKeyComparisonsForTesting() void {
    if (builtin.is_test) collection_key_comparisons_for_testing.store(0, .release);
}

pub fn collectionKeyComparisonsForTesting() u64 {
    return if (builtin.is_test) collection_key_comparisons_for_testing.load(.acquire) else 0;
}

inline fn collectionKeyEquals(a: Value, b: Value) bool {
    if (builtin.is_test) _ = collection_key_comparisons_for_testing.fetchAdd(1, .monotonic);
    return value.sameValueZero(a, b);
}

fn liveMapEntry(v: Value) ?*value.Object {
    if (!v.isObject() or v.asObj().elementsLen() < 2) return null;
    return v.asObj();
}

fn mapEntryMatches(entry: *value.Object, key: Value) bool {
    const entry_key = entry.elementAt(0) orelse return false;
    return collectionKeyEquals(entry_key, key);
}

fn mapEntryValue(entry: *value.Object) Value {
    return entry.elementAt(1) orelse Value.undef();
}

fn liveMapEntryCount(o: *value.Object) usize {
    return o.strongCollectionLiveCount();
}

fn liveSetEntry(v: Value) ?Value {
    if (v.isObject() and v.asObj().behavior.is_set_deleted) return null;
    return v;
}

fn liveSetEntryAt(o: *value.Object, i: usize) ?Value {
    const elements_locked_20 = o.lockElements();
    defer o.unlockElements(elements_locked_20);
    if (i >= o.elementsItems().len) return null;
    return liveSetEntry(o.elementsItems()[i]);
}

fn liveSetEntryCount(o: *value.Object) usize {
    return o.strongCollectionLiveCount();
}

/// Seeded hash of every Map/Set key kind, consistent with `SameValueZero`.
/// Precise-heap objects use zig-gc's relocation-stable identity; arena objects
/// use their lifetime-stable address. Per-kind tags separate primitive domains,
/// while exact equality in the bucket chain remains authoritative on collision.
fn hashKey(seed: u64, key: Value) u64 {
    var h = std.hash.Wyhash.init(seed);
    switch (key.kind()) {
        .number => {
            const n = key.asNum();
            if (std.math.isNan(n)) {
                h.update("N");
                return h.final();
            }
            if (n == 0) {
                h.update("z");
                return h.final();
            }
            h.update("d");
            h.update(std.mem.asBytes(&n));
            return h.final();
        },
        .string => {
            h.update("s");
            h.update(key.asStr());
            return h.final();
        },
        .boolean => {
            h.update(if (key.asBool()) "bT" else "bF");
            return h.final();
        },
        .null => {
            h.update("0n");
            return h.final();
        },
        .undefined => {
            h.update("0u");
            return h.final();
        },
        .object => {
            const o = key.asObj();
            if (!o.is_bigint) {
                h.update("o");
                const identity = gc_mod.stableCellIdentity(@ptrCast(o)) orelse @as(u64, @intCast(@intFromPtr(o)));
                h.update(std.mem.asBytes(&identity));
                return h.final();
            }
            h.update("i");
            if (o.bigIntText()) |t| {
                // `bigIntEquals` permits a canonical decimal sidecar to equal
                // an i128-backed value. Hash that overlap through the same
                // binary representation so equal BigInts share one bucket.
                if (std.fmt.parseInt(i128, t, 10)) |small| {
                    h.update(std.mem.asBytes(&small));
                } else |_| {
                    h.update(t);
                }
            } else {
                const v = o.bigIntValue();
                h.update(std.mem.asBytes(&v));
            }
            return h.final();
        },
    }
}

/// Release an ArrayList's unused tail only when the allocator can resize it in
/// place. This never moves elements and never allocates; allocators that cannot
/// contract the block simply retain the already-bounded high-water reserve.
fn trimCollectionListCapacity(list: anytype, allocator: std.mem.Allocator) void {
    if (list.capacity == list.items.len) return;
    if (list.items.len == 0) {
        list.clearAndFree(allocator);
        return;
    }
    const old = list.items.ptr[0..list.capacity];
    if (allocator.resize(old, list.items.len)) {
        list.capacity = list.items.len;
        list.items = old.ptr[0..list.items.len];
    }
}

/// Bound historical Map/Set storage without changing observable insertion
/// order. Logical serial cursors make physical positions unobservable; stable
/// in-place compaction can therefore discard tombstones once they dominate.
/// The acceleration index is rebuilt from retained capacity, so this delete
/// path introduces no allocation requirement. Caller holds `elements_lock`.
fn maybeCompactStrongCollection(o: *value.Object, arena: std.mem.Allocator) void {
    const state = o.collectionState() orelse return;
    const len = o.elementsItems().len;
    std.debug.assert(state.coll_serials.items.len == len);
    if (len < 64 or len - state.coll_live_count <= state.coll_live_count) return;

    var write: usize = 0;
    for (0..len) |read| {
        const live = if (o.is_map)
            liveMapEntry(o.elementsItems()[read]) != null
        else
            liveSetEntry(o.elementsItems()[read]) != null;
        if (!live) continue;
        if (write != read) {
            o.elementsItems()[write] = o.elementsItems()[read];
            state.coll_serials.items[write] = state.coll_serials.items[read];
        }
        write += 1;
    }
    std.debug.assert(write == state.coll_live_count);
    o.elementsState().?.list.shrinkRetainingCapacity(write);
    state.coll_serials.shrinkRetainingCapacity(write);

    const alloc = o.elementsAllocator(arena);
    if (write == 0) {
        o.elementsState().?.list.clearAndFree(alloc);
        state.coll_serials.clearAndFree(alloc);
        state.coll_index.clearAndFree(alloc);
        state.coll_next.clearAndFree(alloc);
        state.coll_unindexed = false;
        o.collRecordLayoutChange();
        return;
    }
    trimCollectionListCapacity(&o.elementsState().?.list, alloc);
    trimCollectionListCapacity(&state.coll_serials, alloc);
    o.collRecordLayoutChange();

    if (state.coll_unindexed) return;
    state.coll_index.clearRetainingCapacity();
    state.coll_next.clearRetainingCapacity();
    const seed = state.coll_hash_seed;
    for (o.elementsItems(), 0..) |entry_value, pos| {
        const key = if (o.is_map)
            liveMapEntry(entry_value).?.elementAt(0) orelse Value.undef()
        else
            entry_value;
        if (!o.collIndexPut(arena, hashKey(seed, key), @intCast(pos))) {
            o.collDisableIndex(arena);
            return;
        }
    }
    trimCollectionListCapacity(&state.coll_next, alloc);
}

/// Position of the live Map entry for `key` in `o.elementsItems()`, or null.
/// Consults the exact-equality collision chain: an exhausted bucket is an
/// authoritative absence. Only a prior index-allocation failure falls back to
/// the ordered scan. Caller holds the elements lock.
fn mapFindPos(o: *value.Object, key: Value, arena: std.mem.Allocator) ?usize {
    if (!o.collUnindexed()) if (o.collHashSeed()) |seed| {
        const hkey = hashKey(seed, key);
        var cursor = o.collIndexHead(hkey);
        var remaining = o.elementsItems().len;
        while (cursor) |pos| {
            if (remaining == 0 or pos >= o.elementsItems().len) {
                o.collDisableIndex(arena);
                break;
            }
            remaining -= 1;
            if (liveMapEntry(o.elementsItems()[pos])) |entry|
                if (mapEntryMatches(entry, key)) return pos;
            cursor = o.collIndexNext(pos);
        }
        if (!o.collUnindexed()) return null;
    };
    for (o.elementsItems(), 0..) |e, i|
        if (liveMapEntry(e)) |entry| if (mapEntryMatches(entry, key)) return i;
    return null;
}

/// Set analogue of `mapFindPos`: position of the live Set entry equal to `val`.
fn setFindPos(o: *value.Object, val: Value, arena: std.mem.Allocator) ?usize {
    if (!o.collUnindexed()) if (o.collHashSeed()) |seed| {
        const hkey = hashKey(seed, val);
        var cursor = o.collIndexHead(hkey);
        var remaining = o.elementsItems().len;
        while (cursor) |pos| {
            if (remaining == 0 or pos >= o.elementsItems().len) {
                o.collDisableIndex(arena);
                break;
            }
            remaining -= 1;
            if (liveSetEntry(o.elementsItems()[pos])) |entry|
                if (collectionKeyEquals(entry, val)) return pos;
            cursor = o.collIndexNext(pos);
        }
        if (!o.collUnindexed()) return null;
    };
    for (o.elementsItems(), 0..) |e, i|
        if (liveSetEntry(e)) |entry| if (collectionKeyEquals(entry, val)) return i;
    return null;
}

/// The byte length of the well-formed UTF-8 sequence starting at `s[i]`; 1 for a
/// lone/invalid byte (so iteration always progresses without ever decoding past
/// the end of the string).
fn utf8SeqLen(s: []const u8, i: usize) usize {
    const n = std.unicode.utf8ByteSequenceLength(s[i]) catch return 1;
    if (i + n > s.len) return 1;
    return if (std.unicode.utf8ValidateSlice(s[i .. i + n])) n else 1;
}

fn writeWtf8CodeUnit(out: []u8, cu: u16) void {
    std.debug.assert(out.len >= 3);
    out[0] = @intCast(0xE0 | (cu >> 12));
    out[1] = @intCast(0x80 | ((cu >> 6) & 0x3F));
    out[2] = @intCast(0x80 | (cu & 0x3F));
}

/// Non-Unicode RegExp matching observes UTF-16 code units. Convert each astral
/// UTF-8 scalar into its two WTF-8 surrogate encodings, but keep BMP, ASCII,
/// lone-surrogate, and `/u`/`v` input borrowed byte-for-byte. The changed result
/// may be a subslice of one bounded allocation, so this private helper requires
/// the arena-style lifetime used by every caller.
fn regexpSearchInputAlloc(allocator: std.mem.Allocator, input: []const u8, unicode: bool) ![]const u8 {
    if (unicode) return input;

    var first_astral: ?usize = null;
    var i: usize = 0;
    while (i < input.len) {
        const seq_len = utf8SeqLen(input, i);
        if (seq_len == 4) {
            const cp = std.unicode.utf8Decode(input[i .. i + seq_len]) catch unreachable;
            if (cp > 0xFFFF) {
                first_astral = i;
                break;
            }
        }
        i += seq_len;
    }
    const first = first_astral orelse return input;

    // Every expansion consumes four input bytes and produces six. Starting at
    // the first confirmed astral scalar, this is a safe one-allocation upper
    // bound (<= 1.5x input) even when every remaining byte belongs to one.
    const max_astral = (input.len - first) / 4;
    const extra = std.math.mul(usize, max_astral, 2) catch return error.OutOfMemory;
    const capacity = std.math.add(usize, input.len, extra) catch return error.OutOfMemory;
    const out = try allocator.alloc(u8, capacity);
    @memcpy(out[0..first], input[0..first]);
    var written = first;
    i = first;
    while (i < input.len) {
        const seq_len = utf8SeqLen(input, i);
        if (seq_len == 4) {
            const cp = std.unicode.utf8Decode(input[i .. i + seq_len]) catch unreachable;
            if (cp > 0xFFFF) {
                const scalar = cp - 0x10000;
                writeWtf8CodeUnit(out[written..], @intCast(0xD800 + (scalar >> 10)));
                writeWtf8CodeUnit(out[written + 3 ..], @intCast(0xDC00 + (scalar & 0x3FF)));
                written += 6;
                i += seq_len;
                continue;
            }
        }
        @memcpy(out[written .. written + seq_len], input[i .. i + seq_len]);
        written += seq_len;
        i += seq_len;
    }
    std.debug.assert(written <= out.len);
    return out[0..written];
}

test "RegExp search input borrows no-op encodings and owns one bounded astral expansion" {
    var no_memory: [0]u8 = .{};
    var fixed = std.heap.FixedBufferAllocator.init(&no_memory);
    for ([_][]const u8{
        "plain ASCII",
        "BMP: é水",
        "lone surrogate: \xED\xA0\x80",
    }) |input| {
        const borrowed = try regexpSearchInputAlloc(fixed.allocator(), input, false);
        try std.testing.expectEqual(@intFromPtr(input.ptr), @intFromPtr(borrowed.ptr));
        try std.testing.expectEqualStrings(input, borrowed);
    }
    const unicode_input = "unicode 😀";
    const unicode_borrowed = try regexpSearchInputAlloc(fixed.allocator(), unicode_input, true);
    try std.testing.expectEqual(@intFromPtr(unicode_input.ptr), @intFromPtr(unicode_borrowed.ptr));

    var measured = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    var measured_arena = std.heap.ArenaAllocator.init(measured.allocator());
    defer measured_arena.deinit();
    const expanded = try regexpSearchInputAlloc(measured_arena.allocator(), "A😀B𐐷C", false);
    try std.testing.expectEqualStrings("A\xED\xA0\xBD\xED\xB8\x80B\xED\xA0\x81\xED\xB0\xB7C", expanded);
    try std.testing.expectEqual(@as(usize, 1), measured.allocations);
    try std.testing.expect(measured.allocated_bytes >= expanded.len);

    var exhausted_memory: [0]u8 = .{};
    var exhausted = std.heap.FixedBufferAllocator.init(&exhausted_memory);
    try std.testing.expectError(error.OutOfMemory, regexpSearchInputAlloc(exhausted.allocator(), "😀", false));
}

fn isHighSurrogate(cp: u21) bool {
    return cp >= 0xD800 and cp <= 0xDBFF;
}

fn isLowSurrogate(cp: u21) bool {
    return cp >= 0xDC00 and cp <= 0xDFFF;
}

/// String Iterator operates over JS UTF-16 code points. Most engine strings are
/// UTF-8, but lone surrogates are preserved as WTF-8; a high+low WTF-8 pair
/// created by concatenation must be yielded as one iteration result.
fn stringIteratorSeqLen(s: []const u8, i: usize) usize {
    if (wtf8SurrogateAt(s, i)) |first| {
        if (isHighSurrogate(first)) {
            if (wtf8SurrogateAt(s, i + 3)) |second| {
                if (isLowSurrogate(second)) return 6;
            }
        }
        return 3;
    }
    return utf8SeqLen(s, i);
}

fn arrayIteratorValue(self: *Interpreter, kind: usize, index: usize, elem: Value) EvalError!Value {
    return switch (kind) {
        1 => Value.num(@floatFromInt(index)),
        2 => blk: {
            const pair = (try self.newArray()).asObj();
            try pair.appendElement(self.arena, Value.num(@floatFromInt(index)));
            try pair.appendElement(self.arena, elem);
            break :blk Value.obj(pair);
        },
        else => elem,
    };
}

/// Map/Set iterator `next` over logical insertion serials. The caller holds the
/// iterator's property lock for the entire inspect-and-advance transaction
/// (#643): a dispatch probe that read rare-state outside the lock raced peer
/// threads' locked cursor-field stores once codegen materialized those contents
/// into the probe. The collection's elements lock then snapshots one live
/// result under the same critical section, and both locks are released before
/// allocating the observable IteratorResult/entry array.
///
/// Synchronization ruling: every published cursor lives behind its owning
/// iterator object's `property_lock` (per-activation writers, peer iterators
/// unaffected); GC trace reads `source` through the backing lock and relocation
/// rewrites it only at a world-stopped commit.
fn collectionCursorIterNext(self: *Interpreter, iterator: *value.Object) value.HostError!Value {
    var done = false;
    var kind: u8 = 0;
    var entry_key: Value = Value.undef();
    var entry_value: Value = Value.undef();
    var is_map = false;

    const cursor = iterator.collectionIteratorState() orelse {
        iterator.unlockProperties();
        return self.throwError("TypeError", "next called on an incompatible receiver");
    };
    if (cursor.done) {
        iterator.unlockProperties();
        return self.iterResultObj(Value.undef(), true);
    }
    kind = cursor.kind;
    const src = cursor.source;
    if (!src.isObject() or (!(src.asObj().is_map or src.asObj().is_set)) or src.asObj().is_weak) {
        iterator.unlockProperties();
        return self.throwError("TypeError", "next called on an incompatible receiver");
    }
    const collection = src.asObj();
    is_map = collection.is_map;
    const source_elements_locked = collection.lockElements();
    var search_serial = cursor.next_serial;
    var pos = collection.collCursorStart(
        search_serial,
        cursor.next_pos,
        if (cursor.layout_hint_valid) cursor.layout_generation else null,
    );
    if (collection.collLayoutGeneration()) |generation| {
        cursor.layout_generation = generation;
        cursor.layout_hint_valid = true;
    } else {
        cursor.layout_hint_valid = false;
    }
    while (pos < collection.elementsItems().len) : (pos += 1) {
        const serial = collection.collSerialAt(pos);
        // Insertions reject maxInt(u64), so increment cannot wrap and every
        // tombstone consumes cursor progress exactly once.
        search_serial = serial + 1;
        cursor.next_serial = search_serial;
        cursor.next_pos = pos + 1;
        if (is_map) {
            const entry = liveMapEntry(collection.elementsItems()[pos]) orelse continue;
            entry_key = entry.elementAt(0) orelse Value.undef();
            entry_value = mapEntryValue(entry);
        } else {
            entry_value = liveSetEntry(collection.elementsItems()[pos]) orelse continue;
            entry_key = entry_value;
        }
        break;
    } else {
        cursor.done = true;
        done = true;
    }
    collection.unlockElements(source_elements_locked);
    iterator.unlockProperties();

    if (done) return self.iterResultObj(Value.undef(), true);
    const result = if (is_map)
        switch (kind) {
            1 => entry_key,
            2 => pair: {
                const entry = (try self.newArray()).asObj();
                try entry.appendElement(self.arena, entry_key);
                try entry.appendElement(self.arena, entry_value);
                break :pair Value.obj(entry);
            },
            else => entry_value,
        }
    else if (kind == 2) pair: {
        const entry = (try self.newArray()).asObj();
        try entry.appendElement(self.arena, entry_value);
        try entry.appendElement(self.arena, entry_value);
        break :pair Value.obj(entry);
    } else entry_value;
    return self.iterResultObj(result, false);
}

fn cursorIterNext(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return self.throwError("TypeError", "next called on non-object");
    const o = this.asObj();
    // Inspecting and advancing a shared collection cursor is one atomic logical
    // transaction (#643): the rare-state probe runs inside the same property
    // lock critical section that guards every cursor-field store, so no
    // toolchain can hoist a torn content read into the unlocked dispatch. The
    // content-free tag pre-check keeps non-collection iterators (the hot array
    // case) off the lock entirely; the tag is immutable once published.
    if (o.hasCollectionIterator()) {
        o.lockProperties();
        if (o.collectionIteratorState() != null) return collectionCursorIterNext(self, o);
        o.unlockProperties();
    }
    // Brand check: a genuine Array/Map/Set/String iterator carries its `__src`
    // cursor slot as an OWN property. A bare object, a boxed primitive, the
    // iterator *prototype* itself, or `Object.create(anIterator)` (which only
    // inherits the slot) has none — `next` must throw, not yield {done:true}.
    const src = o.getOwn("__src") orelse
        return self.throwError("TypeError", "next called on an incompatible receiver");
    if (o.getOwn("__done")) |d| {
        if (d.toBoolean()) return self.iterResultObj(Value.undef(), true);
    }
    const i = toLen((o.getOwn("__i") orelse Value.num(0)).asNum());
    const kind = if (o.getOwn("__kind")) |k| if (k.isNumber()) toLen(k.asNum()) else 0 else 0;
    var done = true;
    var val: Value = Value.undef();
    var advance: usize = 1;
    switch (src.kind()) {
        .object => {
            const so = src.asObj();
            if (so.is_arguments) {
                const len = toLen(try self.toNumberV(try self.getProperty(src, "length")));
                if (i < len) {
                    val = try arrayIteratorValue(self, kind, i, try self.getProperty(src, try std.fmt.allocPrint(self.arena, "{d}", .{i})));
                    done = false;
                }
            } else if (so.is_array) {
                // Arrays iterate the *logical* length, reading via [[Get]] so a hole
                // (or the sparse tail) yields `undefined` and accessor indices run.
                if (i < so.arrayLength()) {
                    val = try arrayIteratorValue(self, kind, i, try self.arrIndexGet(so, i));
                    done = false;
                }
            } else if (so.proxyHandler() != null or so.proxy_revoked) {
                const len = toLen((try self.toPrimitive(try self.getProperty(src, "length"), .number)).toNumber());
                if (i < len) {
                    val = try arrayIteratorValue(self, kind, i, try self.getProperty(src, try std.fmt.allocPrint(self.arena, "{d}", .{i})));
                    done = false;
                }
            } else if (so.typedArray()) |ta| {
                const len = ta.currentLength() orelse
                    return self.throwError("TypeError", "Cannot operate on a TypedArray whose buffer is detached or out of bounds");
                if (i < len) {
                    val = switch (kind) {
                        1 => Value.num(@floatFromInt(i)), // keys
                        2 => blk: {
                            const pair = (try self.newArray()).asObj();
                            try pair.appendElement(self.arena, Value.num(@floatFromInt(i)));
                            try pair.appendElement(self.arena, try self.taLoad(ta, i));
                            break :blk Value.obj(pair);
                        },
                        else => try self.taLoad(ta, i), // values
                    };
                    done = false;
                }
            } else if (so.is_map) {
                var j = i;
                var entry_key: Value = Value.undef();
                var entry_value: Value = Value.undef();
                const source_elements_locked = so.lockElements();
                while (j < so.elementsItems().len) : (j += 1) {
                    const entry = liveMapEntry(so.elementsItems()[j]) orelse continue;
                    val = switch (kind) {
                        1 => entry.elementAt(0) orelse Value.undef(), // keys
                        2 => capture: {
                            // Iterator entry arrays are fresh observable values,
                            // never the engine's internal Map storage pair.
                            entry_key = entry.elementAt(0) orelse Value.undef();
                            entry_value = mapEntryValue(entry);
                            break :capture Value.undef();
                        },
                        else => mapEntryValue(entry), // values
                    };
                    done = false;
                    advance = j + 1 - i;
                    break;
                }
                so.unlockElements(source_elements_locked);
                if (!done and kind == 2) {
                    const pair = (try self.newArray()).asObj();
                    try pair.appendElement(self.arena, entry_key);
                    try pair.appendElement(self.arena, entry_value);
                    val = Value.obj(pair);
                }
            } else if (so.is_set) {
                var j = i;
                var entry_value: ?Value = null;
                const source_elements_locked = so.lockElements();
                while (j < so.elementsItems().len) : (j += 1) {
                    const e = liveSetEntry(so.elementsItems()[j]) orelse continue;
                    entry_value = e;
                    done = false;
                    advance = j + 1 - i;
                    break;
                }
                so.unlockElements(source_elements_locked);
                if (entry_value) |e| if (kind == 2) {
                    const pair = (try self.newArray()).asObj();
                    try pair.appendElement(self.arena, e);
                    try pair.appendElement(self.arena, e);
                    val = Value.obj(pair);
                } else {
                    val = e;
                };
            } else {
                const len = toLen((try self.toPrimitive(try self.getProperty(src, "length"), .number)).toNumber());
                if (i < len) {
                    val = try arrayIteratorValue(self, kind, i, try self.getProperty(src, try std.fmt.allocPrint(self.arena, "{d}", .{i})));
                    done = false;
                }
            }
        },
        .string => {
            const s = try src.asWtf8(self.arena);
            if (i < s.len) {
                // A String iterator yields one JS code point, not one byte. That is
                // normally one UTF-8 scalar, but can also be a WTF-8 surrogate pair
                // when two UTF-16 code units were concatenated at runtime.
                advance = stringIteratorSeqLen(s, i);
                val = try Value.strOwned(self.arena, try self.arena.dupe(u8, s[i .. i + advance]));
                done = false;
            }
        },
        else => {},
    }
    if (done) {
        try self.setProp(o, "__done", Value.boolVal(true));
    } else {
        try self.setProp(o, "__i", Value.num(@floatFromInt(i + advance)));
    }
    return self.iterResultObj(val, done);
}

/// Install the `length` and `name` own properties on a function object, per the
/// spec: both are `{ writable: false, enumerable: false, configurable: true }`.
/// `length` is the count of parameters before the first one that has a default
/// value or is a rest (`...`) parameter; `name` is the function's name ("" for an
/// anonymous function expression). test262's propertyHelper + countless
/// `fn.name`/`fn.length` assertions depend on these existing as own properties.
pub fn installFunctionProps(
    arena: std.mem.Allocator,
    root_shape: *Shape,
    obj: *value.Object,
    params: []const ast.Param,
    name: []const u8,
) EvalError!void {
    var len: usize = 0;
    for (params) |p| {
        if (p.is_rest or p.default != null) break;
        len += 1;
    }
    const ro_attr: value.PropAttr = .{ .writable = false, .enumerable = false, .configurable = true };
    try obj.setOwnWithAttr(arena, root_shape, "length", Value.num(@floatFromInt(len)), ro_attr);
    try obj.setOwnWithAttr(arena, root_shape, "name", try Value.strAlloc(arena, name), ro_attr);
}

/// Install the `name` and `length` own properties on a *native* (built-in)
/// function object, per the spec: both are
/// `{ writable: false, enumerable: false, configurable: true }`. `name` is the
/// property the function is reached through; `length` is its spec arity. Mirrors
/// `installFunctionProps` for user functions — test262's propertyHelper checks
/// `name.js` / `length.js` for essentially every built-in method.
pub fn installNativeProps(a: std.mem.Allocator, rs: *Shape, obj: *value.Object, name: []const u8, len: usize) EvalError!void {
    const ro_attr: value.PropAttr = .{ .writable = false, .enumerable = false, .configurable = true };
    try obj.setOwnWithAttr(a, rs, "length", Value.num(@floatFromInt(len)), ro_attr);
    try obj.setOwnWithAttr(a, rs, "name", try Value.strAlloc(a, name), ro_attr);
}

fn defineGlobalFn(env: *Environment, rs: *Shape, name: []const u8, len: usize, f: value.NativeFn) EvalError!void {
    try defineGlobalFnC(env, rs, name, len, false, f);
}

fn defineGlobalFnC(env: *Environment, rs: *Shape, name: []const u8, len: usize, is_ctor: bool, f: value.NativeFn) EvalError!void {
    const o = try gc_mod.allocObj(env.arena);
    o.* = .{ .native = f, .native_ctor = is_ctor, .private_data = if (is_ctor) @ptrCast(env) else null };
    try installNativeProps(env.arena, rs, o, name, len);
    // A constructor's `.prototype` is an own, non-writable/-enumerable/
    // -configurable data property (so `getOwnPropertyDescriptor(C, "prototype")`
    // and reflection see it). Methods still dispatch via `builtinMethod`, and
    // `instanceof` keeps working through its `ctorRef()`/`errorCtor()` fallbacks.
    if (is_ctor) {
        const proto = try gc_mod.allocObj(env.arena);
        proto.* = .{};
        try setConstructor(env.arena, rs, proto, o);
        try o.setOwnWithAttr(env.arena, rs, "prototype", Value.obj(proto), .{ .writable = false, .enumerable = false, .configurable = false });
    }
    try env.put(name, Value.obj(o));
}

fn setNativeWithData(a: std.mem.Allocator, root_shape: *Shape, obj: *value.Object, name: []const u8, len: usize, f: value.NativeFn, data: ?*anyopaque) EvalError!void {
    const m = try gc_mod.allocObj(a);
    m.* = .{ .native = f, .private_data = data };
    try installNativeProps(a, root_shape, m, name, len);
    // Built-in methods/statics are non-enumerable (writable + configurable), per
    // spec — so `Object.keys`/`for-in` skip them and verifyProperty is satisfied.
    try obj.setOwnWithAttr(a, root_shape, name, Value.obj(m), .{ .enumerable = false, .configurable = true, .writable = true });
}

pub fn setNative(a: std.mem.Allocator, root_shape: *Shape, obj: *value.Object, name: []const u8, len: usize, f: value.NativeFn) EvalError!void {
    return setNativeWithData(a, root_shape, obj, name, len, f, null);
}

/// A prototype-object method: a native thunk that routes to the existing
/// `builtinMethod` dispatch using `this`. Lets `X.prototype.method` be a real
/// property whose value is callable (and `.call`/`.bind` work on it via the
/// universal callable dispatch) — what test262's propertyHelper relies on.
fn protoMethod(comptime name: []const u8) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            // Object.prototype methods own their argument/receiver ordering in
            // objectPrototypeMethod; e.g. hasOwnProperty coerces the key before
            // ToObject(this), while isPrototypeOf coerces this first.
            if (try self.objectPrototypeMethod(this, name, args)) |r| return r;
            return (try self.builtinMethod(this, name, args)) orelse Value.undef();
        }
    }.call;
}

/// Install a set of prototype methods, each given as a `.{ name, arity }` tuple
/// so the spec `length` is carried onto every method (the same name can have a
/// different arity on different prototypes — e.g. `toString`).
fn setProtoMethods(a: std.mem.Allocator, rs: *Shape, proto: *value.Object, comptime specs: anytype) EvalError!void {
    inline for (specs) |s| try setNative(a, rs, proto, s[0], s[1], protoMethod(s[0]));
}

/// Install Array.prototype methods that dispatch straight to `arrayMethod` after
/// ToObject(this). Going direct (rather than through `builtinMethod`'s
/// name-keyed dispatch) makes a *borrowed* generic method work — e.g. `obj.slice
/// = Array.prototype.slice; obj.slice(0, 3)` — where `obj` has an own property of
/// that name (which would otherwise suppress the array-generic path).
fn setArrayProtoMethods(a: std.mem.Allocator, rs: *Shape, proto: *value.Object, env: *Environment, comptime specs: anytype) EvalError!void {
    inline for (specs) |s| try setNativeWithData(a, rs, proto, s[0], s[1], arrayProtoMethod(s[0]), @ptrCast(env));
}

fn arrayProtoMethod(comptime name: []const u8) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            const saved_env = self.env;
            if (self.active_native) |callee| {
                if (callee.private_data) |pd| self.env = @ptrCast(@alignCast(pd));
            }
            defer self.env = saved_env;
            if (this.isNull() or this.isUndefined())
                return self.throwError("TypeError", "Array.prototype." ++ name ++ " called on null or undefined");
            const o = try self.toObject(this);
            if (try self.arrayMethod(o, name, args)) |r| return r;
            // `toString`/`toLocaleString` aren't in `arrayMethod`; fall back to the
            // generic dispatcher (which reaches Object.prototype.toString etc.).
            return (try self.builtinMethod(Value.obj(o), name, args)) orelse Value.undef();
        }
    }.call;
}

/// `Function.prototype` is itself a built-in function that ignores its arguments
/// and returns undefined (so `typeof Function.prototype === "function"`).
fn funcProtoNoop(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = ctx;
    _ = this;
    _ = args;
    return Value.undef();
}

/// The `%ThrowTypeError%` intrinsic — the shared poison-pill backing the
/// `caller`/`arguments` accessors on `Function.prototype` (and the strict /
/// bound restricted properties). Always throws a TypeError.
fn throwTypeErrorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const saved_env = self.env;
    if (self.active_native) |callee| {
        if (callee.private_data) |pd| self.env = @ptrCast(@alignCast(pd));
    }
    defer self.env = saved_env;
    return self.throwError("TypeError", "'caller', 'callee', and 'arguments' properties may not be accessed on strict mode functions or the arguments objects for calls to them");
}

/// A generic `String.prototype` method: RequireObjectCoercible(this) then
/// `ToString(this)` (running user `toString`/`valueOf`, propagating throws, and
/// rejecting Symbols), then dispatch to `stringMethod`. Installing these as a
/// String-specific thunk (rather than the name-ambiguous `protoMethod`) means
/// `String.prototype.slice.call(obj)` uses *String* slice, not Array slice.
fn stringProtoMethod(comptime name: []const u8) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            if (this.isNull() or this.isUndefined())
                return self.throwError("TypeError", "String.prototype." ++ name ++ " called on null or undefined");
            if (comptime std.mem.eql(u8, name, "replaceAll"))
                if (try self.replaceAllProtocolDispatch(this, args)) |r| return r;
            if (try self.stringProtocolDispatch(name, this, args)) |r| return r;
            if (comptime std.mem.eql(u8, name, "concat"))
                return self.stringConcatReceiverValue(this, args, this.isString());
            const string = try self.toStringValue(this);
            return (try self.stringMethodValue(string, name, args, false, null)) orelse Value.undef();
        }
    }.call;
}

/// `String.prototype.toString`/`valueOf`: a brand check — the receiver must be a
/// String primitive or a String wrapper (else a TypeError), returning the
/// underlying string (these do NOT ToString an arbitrary `this`).
fn stringValueMethod(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    return switch (this.kind()) {
        .string => this,
        .object => blk: {
            const primitive = this.asObj().boxedPrimitive() orelse return throwStringValueTypeError(self);
            if (!primitive.isString()) return throwStringValueTypeError(self);
            break :blk primitive;
        },
        else => return throwStringValueTypeError(self),
    };
}

fn throwStringValueTypeError(self: *Interpreter) EvalError {
    const message = "String.prototype.toString/valueOf called on a non-String";
    if (self.active_native) |callee| {
        if (callee.private_data) |pd| {
            const realm: *Environment = @ptrCast(@alignCast(pd));
            return throwErrorInRealm(self, realm, "TypeError", message);
        }
    }
    return self.throwError("TypeError", message);
}

/// A `Function.prototype` method (`call`/`apply`/`bind`/`toString`) that first
/// requires `this` to be callable (a TypeError otherwise — `IsCallable`), then
/// dispatches to the shared `builtinMethod`.
fn funcProtoMethod(comptime name: []const u8) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            const saved_env = self.env;
            if (self.active_native) |callee| {
                if (callee.private_data) |pd| self.env = @ptrCast(@alignCast(pd));
            }
            defer self.env = saved_env;
            if (!(this.isObject() and this.asObj().isCallableObject()))
                return self.throwError("TypeError", "Function.prototype." ++ name ++ " requires that 'this' be callable");
            if (std.mem.eql(u8, name, "toString")) return self.functionToString(this.asObj());
            return (try self.builtinMethod(this, name, args)) orelse Value.undef();
        }
    }.call;
}

/// A `Date.prototype` method that brand-checks `this` (a TypeError otherwise),
/// then dispatches to `dateMethod`.
fn dateProtoMethod(comptime name: []const u8) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            if (!this.isObject() or !this.asObj().behavior.is_date)
                return self.throwError("TypeError", "Date.prototype method called on a non-Date");
            return (try self.dateMethod(this.asObj(), name, args)) orelse Value.undef();
        }
    }.call;
}

fn setDateProtoMethods(a: std.mem.Allocator, rs: *Shape, proto: *value.Object, comptime specs: anytype) EvalError!void {
    inline for (specs) |s| try setNative(a, rs, proto, s[0], s[1], dateProtoMethod(s[0]));
}

/// `Date.prototype.toJSON(key)` — generic (no [[DateValue]] brand check):
/// ToObject(this), ToPrimitive(O, number); a non-finite primitive returns null,
/// otherwise `Invoke(O, "toISOString")` (which need not be the built-in).
fn dateToJSONFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const o = try self.toObject(this); // null/undefined throw
    // ToPrimitive(O, number); a non-finite *Number* result returns null. For a
    // Date the numeric primitive is its [[DateValue]] (the engine's `toPrimitive`
    // skips the native valueOf, so read it directly); other objects observe
    // their own valueOf/toString.
    if (o.behavior.is_date) {
        if (!std.math.isFinite(o.dateMs())) return Value.nul();
    } else {
        const tv = try self.toPrimitive(Value.obj(o), .number);
        if (tv.isNumber() and !std.math.isFinite(tv.asNum())) return Value.nul();
    }
    const iso = try self.getProperty(Value.obj(o), "toISOString");
    if (!iso.isCallable()) return self.throwError("TypeError", "toISOString is not callable");
    return self.callValueWithThis(iso, &.{}, Value.obj(o));
}

fn dateToTemporalInstantFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject() or !this.asObj().behavior.is_date)
        return self.throwError("TypeError", "Date.prototype.toTemporalInstant called on a non-Date");
    const ms = this.asObj().dateMs();
    if (!std.math.isFinite(ms)) return self.throwError("RangeError", "invalid Date");
    const o = try makeTemporal(self, .instant, "\x00T.Instant");
    o.temporalData().?.epoch_ns = @as(i128, @intFromFloat(ms)) * 1_000_000;
    return Value.obj(o);
}

/// A `Set.prototype` method that brand-checks `this` then dispatches to
/// `setMethod` — making the methods real own properties of `Set.prototype` (so
/// reflection and `Set.prototype.m.call(...)` work) on top of the existing
/// instance dispatch.
fn setProtoMethod(comptime name: []const u8, comptime weak: bool) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            // A WeakSet shares `is_set` with a Set, so the brand check also
            // requires the weakness to match (a Set method rejects a WeakSet and
            // vice versa).
            if (!this.isObject() or !this.asObj().is_set or this.asObj().is_weak != weak)
                return self.throwError("TypeError", if (weak) "WeakSet.prototype method called on an incompatible receiver" else "Set.prototype method called on a non-Set");
            return (try self.setMethod(this.asObj(), name, args)) orelse Value.undef();
        }
    }.call;
}

/// A `Number.prototype` method: extracts the number from `this` (a number
/// primitive or a Number wrapper), throws TypeError otherwise, then dispatches
/// to `numberMethod`. Makes the methods real own properties (reflection) and
/// brand-checks the receiver.
fn numberProtoMethod(comptime name: []const u8) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            const n: f64 = switch (this.kind()) {
                .number => this.asNum(),
                .object => if (this.asObj().boxedPrimitive() != null and this.asObj().boxedPrimitive().?.isNumber()) this.asObj().boxedPrimitive().?.asNum() else return self.throwError("TypeError", "Number.prototype method called on a non-Number"),
                else => return self.throwError("TypeError", "Number.prototype method called on a non-Number"),
            };
            return (try self.numberMethod(n, name, args)) orelse Value.undef();
        }
    }.call;
}

/// A brand-checked `Map.prototype` method dispatching to `mapMethod`.
fn mapProtoMethod(comptime name: []const u8, comptime weak: bool) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            // A WeakMap shares `is_map` with a Map, so the brand check also
            // requires the weakness to match (a Map method rejects a WeakMap and
            // vice versa).
            if (!this.isObject() or !this.asObj().is_map or this.asObj().is_weak != weak)
                return self.throwError("TypeError", if (weak) "WeakMap.prototype method called on an incompatible receiver" else "Map.prototype method called on a non-Map");
            return (try self.mapMethod(this.asObj(), name, args)) orelse Value.undef();
        }
    }.call;
}

/// `Map.prototype.size` / `Set.prototype.size` — an accessor getter (not an own
/// data property of instances) returning the live entry count; brand-checked so
/// it rejects a WeakMap/WeakSet or any non-collection receiver.
fn collectionSizeGetter(comptime is_set_kind: bool) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            _ = args;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            const ok = this.isObject() and !this.asObj().is_weak and
                (if (is_set_kind) this.asObj().is_set else this.asObj().is_map);
            if (!ok) return self.throwError("TypeError", if (is_set_kind) "Set.prototype.size getter called on a non-Set" else "Map.prototype.size getter called on a non-Map");
            const size = if (is_set_kind) liveSetEntryCount(this.asObj()) else liveMapEntryCount(this.asObj());
            return Value.num(@floatFromInt(size));
        }
    }.call;
}

/// Install an accessor property `prop` on `obj` whose getter is the native `f`
/// (a function named "get <prop>" with length 0, per spec), non-enumerable and
/// configurable.
pub fn setNativeGetter(a: std.mem.Allocator, rs: *Shape, obj: *value.Object, comptime prop: []const u8, f: value.NativeFn) EvalError!void {
    return setNativeGetterWithData(a, rs, obj, prop, f, null);
}

pub fn setNativeGetterWithData(a: std.mem.Allocator, rs: *Shape, obj: *value.Object, comptime prop: []const u8, f: value.NativeFn, data: ?*anyopaque) EvalError!void {
    const g = try gc_mod.allocObj(a);
    g.* = .{ .native = f, .private_data = data };
    try installNativeProps(a, rs, g, "get " ++ prop, 0);
    try obj.setAccessor(a, prop, Value.obj(g), null);
    try obj.setAttr(a, prop, .{ .enumerable = false, .configurable = true });
}

/// Install `ArrayBuffer` and the typed-array constructors (`Int8Array` …
/// `Float64Array`), sharing one `%TypedArray%.prototype` for the methods.
/// EscapeRegExpPattern: render a RegExp's source so that `/<source>/` re-parses
/// to the same pattern — escape an unescaped `/` and the line terminators. An
/// empty pattern is "(?:)".
fn escapeRegexSource(a: std.mem.Allocator, src: []const u8) ![]const u8 {
    if (src.len == 0) return "(?:)";
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    var i: usize = 0;
    var in_class = false;
    while (i < src.len) {
        const c = src[i];
        if (c == '\\' and i + 1 < src.len) {
            switch (src[i + 1]) {
                '\n' => {
                    try buf.appendSlice(a, "\\n");
                    i += 2;
                    continue;
                },
                '\r' => {
                    try buf.appendSlice(a, "\\r");
                    i += if (i + 2 < src.len and src[i + 2] == '\n') 3 else 2;
                    continue;
                },
                0xE2 => if (i + 3 < src.len and src[i + 2] == 0x80) {
                    if (src[i + 3] == 0xA8) {
                        try buf.appendSlice(a, "\\u2028");
                        i += 4;
                        continue;
                    }
                    if (src[i + 3] == 0xA9) {
                        try buf.appendSlice(a, "\\u2029");
                        i += 4;
                        continue;
                    }
                },
                else => {},
            }
        }
        var escaped = false;
        var j = i;
        while (j > 0 and src[j - 1] == '\\') {
            escaped = !escaped;
            j -= 1;
        }
        switch (c) {
            '/' => {
                if (!in_class and !escaped) try buf.append(a, '\\');
                try buf.append(a, '/');
            },
            '\n' => try buf.appendSlice(a, "\\n"),
            '\r' => try buf.appendSlice(a, "\\r"),
            0xE2 => if (i + 2 < src.len and src[i + 1] == 0x80 and src[i + 2] == 0xA8) {
                try buf.appendSlice(a, "\\u2028");
                i += 3;
                continue;
            } else if (i + 2 < src.len and src[i + 1] == 0x80 and src[i + 2] == 0xA9) {
                try buf.appendSlice(a, "\\u2029");
                i += 3;
                continue;
            } else try buf.append(a, c),
            else => try buf.append(a, c),
        }
        if (!escaped) {
            if (c == '[') in_class = true;
            if (c == ']') in_class = false;
        }
        i += 1;
    }
    return buf.toOwnedSlice(a);
}

fn appendHex2(buf: *std.ArrayListUnmanaged(u8), a: std.mem.Allocator, b: u8) !void {
    const digits = "0123456789abcdef";
    try buf.appendSlice(a, "\\x");
    try buf.append(a, digits[b >> 4]);
    try buf.append(a, digits[b & 0x0f]);
}

fn appendHex4(buf: *std.ArrayListUnmanaged(u8), a: std.mem.Allocator, cp: u21) !void {
    const digits = "0123456789abcdef";
    try buf.appendSlice(a, "\\u");
    try buf.append(a, digits[(cp >> 12) & 0x0f]);
    try buf.append(a, digits[(cp >> 8) & 0x0f]);
    try buf.append(a, digits[(cp >> 4) & 0x0f]);
    try buf.append(a, digits[cp & 0x0f]);
}

fn wtf8SurrogateAt(s: []const u8, i: usize) ?u21 {
    if (i + 2 >= s.len or s[i] != 0xED) return null;
    if (s[i + 1] < 0xA0 or s[i + 1] > 0xBF) return null;
    if ((s[i + 2] & 0xC0) != 0x80) return null;
    return (@as(u21, s[i] & 0x0F) << 12) | (@as(u21, s[i + 1] & 0x3F) << 6) | @as(u21, s[i + 2] & 0x3F);
}

fn regexpEscapeFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len == 0 or !args[0].isString())
        return self.throwError("TypeError", "RegExp.escape requires a string");
    const s = try args[0].asWtf8(self.arena);
    var out: std.ArrayListUnmanaged(u8) = .empty;
    var i: usize = 0;
    var first = true;
    while (i < s.len) {
        const b = s[i];
        if (b < 0x80) {
            if (first and std.ascii.isAlphanumeric(b)) {
                try appendHex2(&out, self.arena, b);
            } else switch (b) {
                '^', '$', '\\', '.', '*', '+', '?', '(', ')', '[', ']', '{', '}', '|', '/' => {
                    try out.append(self.arena, '\\');
                    try out.append(self.arena, b);
                },
                ',', '-', '=', '<', '>', '#', '&', '!', '%', ':', ';', '@', '~', '\'', '`', '"' => try appendHex2(&out, self.arena, b),
                '\x0c' => try out.appendSlice(self.arena, "\\f"),
                '\n' => try out.appendSlice(self.arena, "\\n"),
                '\r' => try out.appendSlice(self.arena, "\\r"),
                '\t' => try out.appendSlice(self.arena, "\\t"),
                '\x0b' => try out.appendSlice(self.arena, "\\v"),
                ' ' => try appendHex2(&out, self.arena, b),
                else => try out.append(self.arena, b),
            }
            i += 1;
        } else {
            if (wtf8SurrogateAt(s, i)) |cp| {
                try appendHex4(&out, self.arena, cp);
                i += 3;
            } else {
                const len = std.unicode.utf8ByteSequenceLength(b) catch 1;
                if (i + len <= s.len and len > 1 and std.unicode.utf8ValidateSlice(s[i .. i + len])) {
                    const cp = std.unicode.utf8Decode(s[i .. i + len]) catch 0;
                    if (cp == 0x2028 or cp == 0x2029 or isJsTrimCp(cp)) {
                        if (cp <= 0xFF) {
                            try appendHex2(&out, self.arena, @intCast(cp));
                        } else {
                            try appendHex4(&out, self.arena, cp);
                        }
                    } else {
                        try out.appendSlice(self.arena, s[i .. i + len]);
                    }
                    i += len;
                } else {
                    try out.append(self.arena, b);
                    i += 1;
                }
            }
        }
        first = false;
    }
    return try Value.strOwned(self.arena, try out.toOwnedSlice(self.arena));
}

/// A `RegExp.prototype` accessor remembers the realm/prototype it was installed
/// for. Off-brand special-casing is SameValue against that accessor's home
/// %RegExp.prototype%, not the caller's current realm.
const RegExpAccessorData = struct {
    proto: *value.Object,
    realm: *Environment,
};

fn regExpAccessorData(self: *Interpreter) ?*RegExpAccessorData {
    const native = self.active_native orelse return null;
    return @ptrCast(@alignCast(native.private_data orelse return null));
}

fn isHomeRegExpProto(self: *Interpreter, o: *value.Object) bool {
    if (regExpAccessorData(self)) |data| return data.proto == o;
    return self.isRegExpProto(o);
}

fn throwRegExpAccessorTypeError(self: *Interpreter, message: []const u8) EvalError {
    if (regExpAccessorData(self)) |data| return throwErrorInRealm(self, data.realm, "TypeError", message);
    return self.throwError("TypeError", message);
}

/// A `RegExp.prototype` flag accessor (`global`/`ignoreCase`/…) — true iff the
/// flag char is present in [[OriginalFlags]]. Off-brand on the accessor's home
/// %RegExp.prototype% returns undefined; any other non-RegExp throws.
fn regexFlagGetter(comptime flag: u8) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            _ = args;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            if (!this.isObject()) return throwRegExpAccessorTypeError(self, "RegExp.prototype accessor called on a non-object");
            const o = this.asObj();
            if (!o.behavior.is_regex) {
                if (isHomeRegExpProto(self, o)) return Value.undef();
                return throwRegExpAccessorTypeError(self, "RegExp.prototype accessor called on a non-RegExp");
            }
            return Value.boolVal(std.mem.indexOfScalar(u8, o.regexFlags(), flag) != null);
        }
    }.call;
}

fn regexSourceGetter(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return throwRegExpAccessorTypeError(self, "RegExp.prototype.source called on a non-object");
    const o = this.asObj();
    if (!o.behavior.is_regex) {
        if (isHomeRegExpProto(self, o)) return Value.str("(?:)");
        return throwRegExpAccessorTypeError(self, "RegExp.prototype.source called on a non-RegExp");
    }
    return try Value.strAlloc(self.arena, try escapeRegexSource(self.arena, o.regexSource()));
}

fn regexFlagsGetter(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!builtins.isRealObject(this)) return self.throwError("TypeError", "RegExp.prototype.flags called on a non-object");
    const o = this.asObj();
    if (self.isRegExpProto(o)) return Value.str("");

    var buf: [8]u8 = undefined;
    var n: usize = 0;
    const specs = [_]struct { c: u8, name: []const u8 }{
        .{ .c = 'd', .name = "hasIndices" },
        .{ .c = 'g', .name = "global" },
        .{ .c = 'i', .name = "ignoreCase" },
        .{ .c = 'm', .name = "multiline" },
        .{ .c = 's', .name = "dotAll" },
        .{ .c = 'u', .name = "unicode" },
        .{ .c = 'v', .name = "unicodeSets" },
        .{ .c = 'y', .name = "sticky" },
    };
    for (specs) |spec| {
        if ((try self.getProperty(this, spec.name)).toBoolean()) {
            buf[n] = spec.c;
            n += 1;
        }
    }
    return try Value.strOwned(self.arena, try self.arena.dupe(u8, buf[0..n]));
}

/// A `RegExp.prototype` method thunk (`exec`/`test`/`toString`) dispatching to
/// `regexMethod`. `toString` also works on %RegExp.prototype% ("/(?:)/").
fn regexProtoMethod(comptime name: []const u8) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            if (comptime std.mem.eql(u8, name, "toString")) {
                return try self.regexpToString(this);
            }
            if (comptime std.mem.eql(u8, name, "test")) {
                const str_src = if (args.len > 0) args[0] else Value.undef();
                // Fast path when `exec` is the built-in (not subclass-overridden):
                // regexpTestBuiltin avoids regexpExecGeneric's per-call O(n) input
                // copy, so test-in-a-loop is O(n) (matches the match/replace/split
                // fast-path guard). Otherwise honor the overridden exec via generic.
                if (self.regexpHasBuiltinExec(this))
                    return Value.boolVal(try self.regexpTestBuiltin(this.asObj(), str_src));
                const r = try self.regexpExecGeneric(this, try self.toStringWtf8(str_src));
                return Value.boolVal(!r.isNull());
            }
            if (!this.isObject() or !this.asObj().behavior.is_regex) {
                return self.throwError("TypeError", "RegExp.prototype." ++ name ++ " called on a non-RegExp");
            }
            return (try self.regexMethod(this.asObj(), name, args)) orelse Value.undef();
        }
    }.call;
}

/// Install `RegExp.prototype` accessor getters (source/flags + the eight flag
/// getters) and the `exec`/`test`/`toString` methods on the existing prototype.
/// `RegExp.prototype[@@match/@@search/@@matchAll/@@replace/@@split]` — the
/// well-known-symbol methods. For a real RegExp receiver they reuse the engine's
/// String-method regex algorithms (`s.match(re)` == `re[@@match](s)`); the
/// `op`-specific extra argument (replacement / limit) is forwarded.
fn regexpSymbolMethod(comptime op: []const u8) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            if (!this.isObject()) return self.throwError("TypeError", "RegExp.prototype[Symbol." ++ op ++ "] called on a non-object");
            const str_src = if (args.len > 0) args[0] else Value.undef();
            const string = try self.toStringValue(str_src);
            const str = try string.asWtf8(self.arena);
            if (comptime std.mem.eql(u8, op, "match")) {
                return try self.regexpMatch(this, str);
            }
            if (comptime std.mem.eql(u8, op, "search")) {
                return try self.regexpSearch(this, str);
            }
            if (comptime std.mem.eql(u8, op, "replace")) {
                const replace_value: Value = if (args.len > 1) args[1] else Value.undef();
                return try self.regexpReplace(this, str, replace_value);
            }
            if (comptime std.mem.eql(u8, op, "split")) {
                const limit: Value = if (args.len > 1) args[1] else Value.undef();
                return try self.regexpSplit(this, str, limit);
            }
            if (comptime std.mem.eql(u8, op, "matchAll")) {
                return try self.regexpMatchAll(this, str);
            }
            return (try self.stringMethod(str, op, &.{this}, false, string.asStringCell(), null, false)) orelse Value.undef();
        }
    }.call;
}

/// Record a successful match into the legacy static RegExp state (`RegExp.input`,
/// `$&`, `` $` ``, `$'`, `$1`..`$9`). `captures` are the 1-based capture-group
/// substrings (group i at index i-1); an absent group is the empty string. The
/// whole-input parts are stored as borrowed slices into `input` (O(1), no copy)
/// instead of duping the entire string per match — so exec/test/replace in a loop
/// stay O(n) rather than O(n^2). Safe only when `input` is arena/cell-lifetime
/// (it outlives the legacy statics), which every caller guarantees; `captures`
/// may come from a reused match buffer, so those small values are still copied.
pub fn recordRegexpLegacyBorrowed(self: *Interpreter, input: []const u8, start: usize, end: usize, captures: []const []const u8) void {
    const s = @min(start, input.len);
    const e = @min(end, input.len);
    self.re_legacy.input = input;
    self.re_legacy.last_match = input[s..e];
    self.re_legacy.left_context = input[0..s];
    self.re_legacy.right_context = input[e..];
    // The whole-input parts above are arena-stable slices (O(1)); capture strings
    // may come from a reused match buffer, so copy those small values.
    var last_paren: []const u8 = "";
    for (self.re_legacy.groups[0..], 0..) |*g, i| {
        const cap: []const u8 = if (i < captures.len) (self.arena.dupe(u8, captures[i]) catch "") else "";
        g.* = cap;
        if (cap.len > 0) last_paren = cap;
    }
    self.re_legacy.last_paren = last_paren;
}

/// A legacy RegExp accessor getter/setter must be invoked with the %RegExp%
/// constructor itself as the receiver (so a subclass / cross-realm / arbitrary
/// receiver throws a TypeError).
fn regexpLegacyBrandCheck(self: *Interpreter, this: Value) EvalError!void {
    const ctor = self.env.get("RegExp") orelse return self.throwError("TypeError", "RegExp is not defined");
    if (!this.isObject() or !ctor.isObject() or this.asObj() != ctor.asObj())
        return self.throwError("TypeError", "RegExp legacy accessor requires the RegExp constructor as receiver");
}

const ReLegacyField = enum { input, last_match, last_paren, left_context, right_context, g1, g2, g3, g4, g5, g6, g7, g8, g9 };

fn regexpLegacyGetter(comptime field: ReLegacyField) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            _ = args;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            try regexpLegacyBrandCheck(self, this);
            const s: []const u8 = switch (field) {
                .input => self.re_legacy.input,
                .last_match => self.re_legacy.last_match,
                .last_paren => self.re_legacy.last_paren,
                .left_context => self.re_legacy.left_context,
                .right_context => self.re_legacy.right_context,
                .g1 => self.re_legacy.groups[0],
                .g2 => self.re_legacy.groups[1],
                .g3 => self.re_legacy.groups[2],
                .g4 => self.re_legacy.groups[3],
                .g5 => self.re_legacy.groups[4],
                .g6 => self.re_legacy.groups[5],
                .g7 => self.re_legacy.groups[6],
                .g8 => self.re_legacy.groups[7],
                .g9 => self.re_legacy.groups[8],
            };
            return try Value.strAlloc(self.arena, s);
        }
    }.call;
}

/// `RegExp.input` / `RegExp.$_` setter — stores ToString(value) as the input.
fn regexpLegacyInputSetter(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    try regexpLegacyBrandCheck(self, this);
    self.re_legacy.input = try self.toStringWtf8(if (args.len > 0) args[0] else Value.undef());
    return Value.undef();
}

fn installRegExpProto(env: *Environment, rs: *Shape) EvalError!void {
    const a = env.arena;
    const ctor = env.get("RegExp") orelse return;
    if (!ctor.isObject()) return;
    const pv = ctor.asObj().getOwn("prototype") orelse return;
    if (!pv.isObject()) return;
    const p = pv.asObj();
    const accessor_data = try a.create(RegExpAccessorData);
    accessor_data.* = .{ .proto = p, .realm = env };
    try setNativeGetterWithData(a, rs, p, "source", regexSourceGetter, @ptrCast(accessor_data));
    try setNativeGetter(a, rs, p, "flags", regexFlagsGetter);
    try setNativeGetterWithData(a, rs, p, "global", regexFlagGetter('g'), @ptrCast(accessor_data));
    try setNativeGetterWithData(a, rs, p, "ignoreCase", regexFlagGetter('i'), @ptrCast(accessor_data));
    try setNativeGetterWithData(a, rs, p, "multiline", regexFlagGetter('m'), @ptrCast(accessor_data));
    try setNativeGetterWithData(a, rs, p, "dotAll", regexFlagGetter('s'), @ptrCast(accessor_data));
    try setNativeGetterWithData(a, rs, p, "sticky", regexFlagGetter('y'), @ptrCast(accessor_data));
    try setNativeGetterWithData(a, rs, p, "unicode", regexFlagGetter('u'), @ptrCast(accessor_data));
    try setNativeGetterWithData(a, rs, p, "unicodeSets", regexFlagGetter('v'), @ptrCast(accessor_data));
    try setNativeGetterWithData(a, rs, p, "hasIndices", regexFlagGetter('d'), @ptrCast(accessor_data));
    try setNative(a, rs, p, "exec", 1, regexProtoMethod("exec"));
    if (p.getOwn("exec")) |exec| try env.put("\x00RegExpBuiltinExec", exec);
    try setNative(a, rs, p, "test", 1, regexProtoMethod("test"));
    try setNativeWithData(a, rs, p, "compile", 2, regexProtoMethod("compile"), @ptrCast(accessor_data));
    try setNative(a, rs, p, "toString", 0, regexProtoMethod("toString"));
    // Legacy static RegExp accessors (Annex B) on the constructor itself — each a
    // {enumerable:false, configurable:true} accessor that brand-checks %RegExp%.
    const co = ctor.asObj();
    const mkGetSet = struct {
        // The accessor functions are anonymous (name ""), matching other engines —
        // a name like "get $`" would not be a valid NativeFunction IdentifierName.
        fn f(arena: std.mem.Allocator, shape: *Shape, obj: *value.Object, name: []const u8, getf: value.NativeFn, setf: ?value.NativeFn) EvalError!void {
            const g = try gc_mod.allocObj(arena);
            g.* = .{ .native = getf };
            try installNativeProps(arena, shape, g, "", 0);
            var sv: ?Value = null;
            if (setf) |sf| {
                const s = try gc_mod.allocObj(arena);
                s.* = .{ .native = sf };
                try installNativeProps(arena, shape, s, "", 1);
                sv = Value.obj(s);
            }
            try obj.setAccessor(arena, name, Value.obj(g), sv);
            try obj.setAttr(arena, name, .{ .enumerable = false, .configurable = true });
        }
    }.f;
    try mkGetSet(a, rs, co, "input", regexpLegacyGetter(.input), regexpLegacyInputSetter);
    try mkGetSet(a, rs, co, "$_", regexpLegacyGetter(.input), regexpLegacyInputSetter);
    try mkGetSet(a, rs, co, "lastMatch", regexpLegacyGetter(.last_match), null);
    try mkGetSet(a, rs, co, "$&", regexpLegacyGetter(.last_match), null);
    try mkGetSet(a, rs, co, "lastParen", regexpLegacyGetter(.last_paren), null);
    try mkGetSet(a, rs, co, "$+", regexpLegacyGetter(.last_paren), null);
    try mkGetSet(a, rs, co, "leftContext", regexpLegacyGetter(.left_context), null);
    try mkGetSet(a, rs, co, "$`", regexpLegacyGetter(.left_context), null);
    try mkGetSet(a, rs, co, "rightContext", regexpLegacyGetter(.right_context), null);
    try mkGetSet(a, rs, co, "$'", regexpLegacyGetter(.right_context), null);
    try mkGetSet(a, rs, co, "$1", regexpLegacyGetter(.g1), null);
    try mkGetSet(a, rs, co, "$2", regexpLegacyGetter(.g2), null);
    try mkGetSet(a, rs, co, "$3", regexpLegacyGetter(.g3), null);
    try mkGetSet(a, rs, co, "$4", regexpLegacyGetter(.g4), null);
    try mkGetSet(a, rs, co, "$5", regexpLegacyGetter(.g5), null);
    try mkGetSet(a, rs, co, "$6", regexpLegacyGetter(.g6), null);
    try mkGetSet(a, rs, co, "$7", regexpLegacyGetter(.g7), null);
    try mkGetSet(a, rs, co, "$8", regexpLegacyGetter(.g8), null);
    try mkGetSet(a, rs, co, "$9", regexpLegacyGetter(.g9), null);
    // The @@match/@@replace/@@search/@@split/@@matchAll methods are installed
    // later (after Symbol's well-known symbols exist) in installGlobalsInner.
}

fn installTypedArrays(env: *Environment, rs: *Shape) EvalError!void {
    const a = env.arena;
    const obj_ctor = env.get("Object") orelse return;
    if (!obj_ctor.isObject()) return;
    const op = obj_ctor.asObj().getOwn("prototype") orelse return;
    if (!op.isObject()) return;
    const object_proto = op.asObj();

    // ArrayBuffer.
    const ab_proto = try gc_mod.allocObj(a);
    ab_proto.* = .{ .proto = object_proto };
    try setNative(a, rs, ab_proto, "slice", 2, arrayBufferSliceFn);
    try setNative(a, rs, ab_proto, "resize", 1, arrayBufferResizeFn);
    try setNative(a, rs, ab_proto, "transfer", 0, arrayBufferTransferFn(false));
    try setNative(a, rs, ab_proto, "transferToFixedLength", 0, arrayBufferTransferFn(true));
    try setNative(a, rs, ab_proto, "transferToImmutable", 0, arrayBufferTransferToImmutableFn);
    try setNative(a, rs, ab_proto, "sliceToImmutable", 2, arrayBufferSliceToImmutableFn);
    try setNativeGetter(a, rs, ab_proto, "byteLength", arrayBufferGetter(.byte_length));
    try setNativeGetter(a, rs, ab_proto, "maxByteLength", arrayBufferGetter(.max_byte_length));
    try setNativeGetter(a, rs, ab_proto, "resizable", arrayBufferGetter(.resizable));
