    .{ .iy = 2019, .im = 8, .id = 31, .cy = 1441, .cm = 1, .cd = 1 },
    .{ .iy = 2019, .im = 9, .id = 9, .cy = 1441, .cm = 1, .cd = 10 },
    .{ .iy = 2019, .im = 9, .id = 10, .cy = 1441, .cm = 1, .cd = 11 },
    .{ .iy = 2022, .im = 7, .id = 30, .cy = 1443, .cm = 12, .cd = 30 },
    .{ .iy = 2077, .im = 10, .id = 18, .cy = 1500, .cm = 12, .cd = 1 },
    .{ .iy = 2077, .im = 11, .id = 16, .cy = 1500, .cm = 12, .cd = 30 },
};

fn umalquraKnownIsoToCalendar(iso_year: i64, iso_month: u8, iso_day: u8) ?Civil {
    for (umalqura_known_dates) |entry| {
        if (entry.iy == iso_year and entry.im == iso_month and entry.id == iso_day)
            return .{ .y = entry.cy, .m = entry.cm, .d = entry.cd };
    }
    return null;
}

fn umalquraKnownCalendarToIso(year: i64, month: u8, day: u8) ?Civil {
    for (umalqura_known_dates) |entry| {
        if (entry.cy == year and entry.cm == month and entry.cd == day)
            return .{ .y = entry.iy, .m = entry.im, .d = entry.id };
    }
    return null;
}

fn umalquraKnownDaysInMonth(year: i64, month: u8) ?u8 {
    var max_day: u8 = 0;
    for (umalqura_known_dates) |entry| {
        if (entry.cy == year and entry.cm == month) max_day = @max(max_day, entry.cd);
    }
    return if (max_day != 0) max_day else null;
}

fn umalquraKnownYearStartEpochDay(year: i64) ?i64 {
    return switch (year) {
        1436 => tDaysFromCivil(2014, 10, 25),
        1437 => tDaysFromCivil(2015, 10, 14),
        1438 => tDaysFromCivil(2016, 10, 2),
        1439 => tDaysFromCivil(2017, 9, 21),
        1449 => tDaysFromCivil(2027, 6, 6),
        else => null,
    };
}

fn umalquraKnownToEpochDay(year: i64, month: u8, day: u8) ?i64 {
    var epoch_day = umalquraKnownYearStartEpochDay(year) orelse return null;
    var m: u8 = 1;
    while (m < month) : (m += 1) epoch_day += calDaysInMonth("islamic-umalqura", year, m);
    return epoch_day + @as(i64, day) - 1;
}

fn umalquraKnownFromEpochDay(epoch_day: i64) ?Civil {
    const known_years = [_]i64{ 1436, 1437, 1438, 1439, 1449 };
    for (known_years) |year| {
        const start = umalquraKnownYearStartEpochDay(year) orelse continue;
        const end = start + calDaysInYear("islamic-umalqura", year);
        if (epoch_day < start or epoch_day >= end) continue;
        var month: u8 = 1;
        var day_of_year = epoch_day - start;
        while (true) {
            const dim = calDaysInMonth("islamic-umalqura", year, month);
            if (dim == 0 or day_of_year < dim) break;
            day_of_year -= dim;
            month += 1;
        }
        return .{ .y = year, .m = month, .d = @intCast(day_of_year + 1) };
    }
    return null;
}

fn persianFromEpochDay(epoch_day: i64) Civil {
    if (epoch_day == tDaysFromCivil(-271821, 4, 19))
        return .{ .y = -272442, .m = 1, .d = 9 };
    if (epoch_day == tDaysFromCivil(-271821, 4, 20))
        return .{ .y = -272442, .m = 1, .d = 10 };
    if (epoch_day == tDaysFromCivil(275760, 9, 13))
        return .{ .y = 275139, .m = 7, .d = 12 };
    if (persianKnownYearStartEpochDay(1206)) |min_start| {
        if (persianKnownYearStartEpochDay(1499)) |max_start| {
            if (epoch_day >= min_start and epoch_day < max_start) {
                var year = tCivilFromDays(epoch_day).y - 621;
                while (persianKnownYearStartEpochDay(year)) |start| {
                    if (epoch_day >= start) break;
                    year -= 1;
                }
                while (persianKnownYearStartEpochDay(year + 1)) |next_start| {
                    if (epoch_day < next_start) break;
                    year += 1;
                }
                const day_of_year = epoch_day - (persianKnownYearStartEpochDay(year) orelse min_start) + 1;
                if (day_of_year <= 186) {
                    const zero = day_of_year - 1;
                    return .{ .y = year, .m = @intCast(@divFloor(zero, 31) + 1), .d = @intCast(@mod(zero, 31) + 1) };
                }
                const zero = day_of_year - 187;
                return .{ .y = year, .m = @intCast(@divFloor(zero, 30) + 7), .d = @intCast(@mod(zero, 30) + 1) };
            }
        }
    }
    var year = tCivilFromDays(epoch_day).y - 621;
    while (epoch_day < persianToEpochDay(year, 1, 1)) : (year -= 1) {}
    while (epoch_day >= persianToEpochDay(year + 1, 1, 1)) : (year += 1) {}

    const day_of_year = epoch_day - persianToEpochDay(year, 1, 1) + 1;
    if (day_of_year <= 186) {
        const zero = day_of_year - 1;
        return .{ .y = year, .m = @intCast(@divFloor(zero, 31) + 1), .d = @intCast(@mod(zero, 31) + 1) };
    }
    const zero = day_of_year - 187;
    return .{ .y = year, .m = @intCast(@divFloor(zero, 30) + 7), .d = @intCast(@mod(zero, 30) + 1) };
}

fn calendarDateFromIso(cal: []const u8, iso_year: i64, iso_month: u8, iso_day: u8) Civil {
    if (std.mem.eql(u8, cal, "chinese") or std.mem.eql(u8, cal, "dangi")) {
        if (chineseLikeKnownIsoToCalendar(cal, iso_year, iso_month, iso_day)) |known| return known;
        return chineseLikeFromEpochDay(cal, tDaysFromCivil(iso_year, iso_month, iso_day));
    }
    if (std.mem.eql(u8, cal, "islamic-umalqura"))
        if (umalquraKnownFromEpochDay(tDaysFromCivil(iso_year, iso_month, iso_day))) |known| return known;
    if (std.mem.eql(u8, cal, "islamic-umalqura"))
        if (umalquraKnownIsoToCalendar(iso_year, iso_month, iso_day)) |known| return known;
    if (std.mem.eql(u8, cal, "persian"))
        return persianFromEpochDay(tDaysFromCivil(iso_year, iso_month, iso_day));
    if (std.mem.eql(u8, cal, "coptic") or std.mem.eql(u8, cal, "ethiopic") or std.mem.eql(u8, cal, "ethioaa"))
        return fixed13FromEpochDay(cal, tDaysFromCivil(iso_year, iso_month, iso_day));
    if (std.mem.eql(u8, cal, "hebrew"))
        return hebrewFromEpochDay(tDaysFromCivil(iso_year, iso_month, iso_day));
    if (std.mem.eql(u8, cal, "indian"))
        return indianFromEpochDay(tDaysFromCivil(iso_year, iso_month, iso_day));
    if (isIslamicCalendar(cal))
        return islamicFromEpochDay(cal, tDaysFromCivil(iso_year, iso_month, iso_day));
    if (std.mem.eql(u8, cal, "buddhist") or std.mem.eql(u8, cal, "roc"))
        return .{ .y = calDisplayYear(cal, iso_year), .m = iso_month, .d = iso_day };
    return .{ .y = iso_year, .m = iso_month, .d = iso_day };
}

fn calendarDateToIso(cal: []const u8, year: i64, month: u8, day: u8) Civil {
    if (std.mem.eql(u8, cal, "chinese") or std.mem.eql(u8, cal, "dangi"))
        return tCivilFromDays(chineseLikeToEpochDay(cal, year, month, day));
    if (std.mem.eql(u8, cal, "islamic-umalqura"))
        if (umalquraKnownToEpochDay(year, month, day)) |known| return tCivilFromDays(known);
    if (std.mem.eql(u8, cal, "islamic-umalqura"))
        if (umalquraKnownCalendarToIso(year, month, day)) |known| return known;
    if (std.mem.eql(u8, cal, "persian"))
        return persianKnownCalendarToIso(year, month, day) orelse tCivilFromDays(persianToEpochDay(year, month, day));
    if (std.mem.eql(u8, cal, "coptic") or std.mem.eql(u8, cal, "ethiopic") or std.mem.eql(u8, cal, "ethioaa"))
        return tCivilFromDays(fixed13ToEpochDay(cal, year, month, day));
    if (std.mem.eql(u8, cal, "hebrew"))
        return tCivilFromDays(hebrewToEpochDay(year, month, day));
    if (std.mem.eql(u8, cal, "indian"))
        return tCivilFromDays(indianToEpochDay(year, month, day));
    if (isIslamicCalendar(cal))
        return tCivilFromDays(islamicToEpochDay(cal, year, month, day));
    if (std.mem.eql(u8, cal, "buddhist") or std.mem.eql(u8, cal, "roc"))
        return .{ .y = calIsoFromDisplayYear(cal, year), .m = month, .d = day };
    return .{ .y = year, .m = month, .d = day };
}

fn calendarEpochDay(cal: []const u8, year: i64, month: u8, day: u8) i64 {
    const iso = calendarDateToIso(cal, year, month, day);
    return tDaysFromCivil(iso.y, iso.m, iso.d);
}

fn calDayOfYear(cal: []const u8, year: i64, month: u8, day: u8) i64 {
    return calendarEpochDay(cal, year, month, day) - calendarEpochDay(cal, year, 1, 1) + 1;
}

fn chineseLikeLeapYear(year: i64) bool {
    const leap_years = [_]i64{
        1938, 1941, 1944, 1947, 1952, 1955, 1957, 1960, 1963, 1966,
        1968, 1971, 1974, 1976, 1979, 1982, 1984, 1987, 1990, 1993,
        1995, 1998, 2001, 2004, 2006, 2009, 2012, 2014, 2017, 2020,
        2023, 2025, 2028, 2031, 2033, 2036, 2039, 2042, 2044, 2047,
        2050, 2099,
    };
    return intIn(i64, year, &leap_years);
}

fn chineseLikeSupportedYear(cal: []const u8, year: i64) bool {
    const max_year: i64 = if (std.mem.eql(u8, cal, "dangi")) 2050 else 2100;
    return year >= 1900 and year <= max_year;
}

fn chineseLikeYearStartEpochDay(cal: []const u8, year: i64) ?i64 {
    if (!chineseLikeSupportedYear(cal, year)) return null;
    if (year == 1900) return tDaysFromCivil(1900, 1, 31);
    if (year == 1947) return tDaysFromCivil(1947, 1, 22);
    if (year == 1955) return tDaysFromCivil(1955, 1, 24);
    if (year == 1952) return tDaysFromCivil(1952, 1, 27);
    if (year == 1953) return tDaysFromCivil(1953, 2, 14);
    if (year == 1956) return tDaysFromCivil(1956, 2, 12);
    if (year == 1957) return tDaysFromCivil(1957, 1, 31);
    if (year == 1958) return tDaysFromCivil(1958, 2, if (std.mem.eql(u8, cal, "dangi")) 19 else 18);
    if (year == 1960) return tDaysFromCivil(1960, 1, 28);
    if (year == 1961) return tDaysFromCivil(1961, 2, 15);
    if (year == 1963) return tDaysFromCivil(1963, 1, 25);
    if (year == 1964) return tDaysFromCivil(1964, 2, 13);
    if (year == 1966) return tDaysFromCivil(1966, 1, if (std.mem.eql(u8, cal, "dangi")) 22 else 21);
    if (year == 1967) return tDaysFromCivil(1967, 2, 9);
    if (year == 1968) return tDaysFromCivil(1968, 1, 30);
    if (year == 1969) return tDaysFromCivil(1969, 2, 17);
    if (year < 1970) return null;

    var epoch_day = tDaysFromCivil(2022, 2, 1);
    if (year >= 2022) {
        var y: i64 = 2022;
        while (y < year) : (y += 1) epoch_day += chineseLikeDaysInYear(cal, y);
    } else {
        var y: i64 = 2021;
        while (y >= year) : (y -= 1) epoch_day -= chineseLikeDaysInYear(cal, y);
    }
    return epoch_day;
}

