fn skippedMidnightStartEpoch(tz_name: []const u8, iso_year: i64, iso_month: u8, iso_day: u8) ?i128 {
    if (std.mem.eql(u8, tz_name, "America/Toronto") and iso_year == 1919 and iso_month == 3 and iso_day == 31)
        return (@as(i128, tDaysFromCivil(1919, 3, 31)) * nsPerUnit(.day)) + 4 * nsPerUnit(.hour) + 30 * nsPerUnit(.minute);
    if (std.mem.eql(u8, tz_name, "Asia/Singapore") and iso_year == 1933 and iso_month == 1 and iso_day == 1)
        return (@as(i128, tDaysFromCivil(1933, 1, 1)) * nsPerUnit(.day)) - 7 * nsPerUnit(.hour);
    if (std.mem.eql(u8, tz_name, "Pacific/Apia") and iso_year == 2011 and iso_month == 12 and iso_day == 30)
        return (@as(i128, tDaysFromCivil(2011, 12, 30)) * nsPerUnit(.day)) + 10 * nsPerUnit(.hour);
    if (std.mem.eql(u8, tz_name, "America/Noronha") and iso_year == 2000 and iso_month == 10 and iso_day == 8)
        return (@as(i128, tDaysFromCivil(2000, 10, 8)) * nsPerUnit(.day)) + 2 * nsPerUnit(.hour);
    if (std.mem.eql(u8, tz_name, "America/Boa_Vista") and iso_year == 2000 and iso_month == 10 and iso_day == 8)
        return (@as(i128, tDaysFromCivil(2000, 10, 8)) * nsPerUnit(.day)) + 4 * nsPerUnit(.hour);
    return null;
}

fn zdtOffsetMatchesLocal(tz: TimeZone, local_ns: i128, offset_ns: i128) bool {
    if (offset_ns < std.math.minInt(i64) or offset_ns > std.math.maxInt(i64)) return false;
    const off: i64 = @intCast(offset_ns);
    const candidate_epoch = local_ns - offset_ns;
    return timeZoneOffsetAtEpoch(tz.name, candidate_epoch, tz.offset_ns) == off;
}

fn zdtEpochFromParsed(self: *Interpreter, tz: TimeZone, p: ParsedDT, behavior: ZdtOffsetBehavior, disambiguation: ZdtDisambiguation) EvalError!i128 {
    const local_ns = p.epoch_ns + p.offset_ns;
    const skip_wall_range = p.has_offset and (behavior == .use or (behavior == .ignore and isFixedTimeZone(tz)));
    if (!skip_wall_range) try checkZdtLocalDateTimeNs(self, local_ns);
    const epoch_ns: i128 = if (p.z) p.epoch_ns else blk: {
        const actual = if (p.has_offset and p.offset_has_seconds)
            timeZoneOffsetAtEpoch(tz.name, p.epoch_ns, tz.offset_ns)
        else
            try zdtOffsetForLocalDisambiguation(self, tz, local_ns, disambiguation);
        if (!p.has_offset) break :blk local_ns - @as(i128, actual);
        if (isFixedTimeZone(tz)) {
            const tz_off: i128 = @as(i128, tz.offset_ns);
            break :blk switch (behavior) {
                .use => local_ns - p.offset_ns,
                .ignore => local_ns - tz_off,
                .prefer => if (p.offset_ns == tz_off) local_ns - tz_off else local_ns - p.offset_ns,
                .reject => if (p.offset_ns == tz_off) local_ns - tz_off else return self.throwError("RangeError", "offset does not match time zone"),
            };
        }
        const exact_match = zdtOffsetMatchesLocal(tz, local_ns, p.offset_ns);
        const rounded_match = !p.offset_has_seconds and p.offset_ns == roundOffsetToMinute(@as(i128, actual));
        break :blk switch (behavior) {
            .use => local_ns - p.offset_ns,
            .ignore => local_ns - @as(i128, actual),
            .prefer => if (rounded_match) local_ns - @as(i128, actual) else if (exact_match) local_ns - p.offset_ns else local_ns - @as(i128, actual),
            .reject => if (rounded_match) local_ns - @as(i128, actual) else if (exact_match) local_ns - p.offset_ns else return self.throwError("RangeError", "offset does not match time zone"),
        };
    };
    try checkInstantEpochNs(self, epoch_ns);
    return epoch_ns;
}

// ---- Process-wide default time zone (WTF::setTimeZoneOverride) -----------

var tz_override_lock: std.atomic.Mutex = .unlocked;
var tz_override: ?[]const u8 = null;

fn tzOverrideLock() void {
    var spins: usize = 0;
    while (!tz_override_lock.tryLock()) : (spins += 1) {
        if ((spins & 0xff) == 0) std.Thread.yield() catch {} else std.atomic.spinLoopHint();
    }
}

/// `WTF::setTimeZoneOverride`: a process-wide default time zone consulted when
/// a consumer (Intl.DateTimeFormat, Temporal.Now) supplies no explicit zone.
/// `canonical_name` must already pass `validCanonicalTimeZoneName`; null clears
/// the override (WTF's empty-input reset). The slice is duplicated with
/// `allocator` and never freed — overrides are a boot-time rarity, like WTF's
/// process-lifetime global.
pub fn setTimeZoneOverride(allocator: std.mem.Allocator, canonical_name: ?[]const u8) bool {
    const owned: ?[]const u8 = if (canonical_name) |n| allocator.dupe(u8, n) catch return false else null;
    tzOverrideLock();
    tz_override = owned;
    tz_override_lock.unlock();
    return true;
}

pub fn timeZoneOverride() ?[]const u8 {
    tzOverrideLock();
    defer tz_override_lock.unlock();
    return tz_override;
}

fn nowTimeZone() TimeZone {
    return .{ .name = timeZoneOverride() orelse "UTC", .offset_ns = 0 };
}

/// Validate a candidate named zone the way the Intl pipeline does — ASCII
/// word-case normalization per `/`_`-` segment, then alias resolution and the
/// canonical IANA table — returning the canonical name, or null when the zone
/// is unknown, malformed, or longer than `buf`. Offset-form zones are not
/// named zones and are rejected here like the Intl named-zone path.
pub fn validCanonicalTimeZoneName(name: []const u8, buf: []u8) ?[]const u8 {
    if (name.len == 0 or name.len > buf.len) return null;
    if (name[0] == '+' or name[0] == '-' or name[0] >= 0x80) return null;
    var word_start = true;
    for (name, 0..) |c, i| {
        if (std.ascii.isAlphabetic(c)) {
            buf[i] = if (word_start) std.ascii.toUpper(c) else std.ascii.toLower(c);
            word_start = false;
        } else {
            buf[i] = c;
            word_start = (c == '/' or c == '_' or c == '-');
        }
    }
    const canonical = canonicalTimeZoneName(buf[0..name.len]);
    if (!iana_zones.isCanonical(canonical)) return null;
    return canonical;
}

fn canonicalTimeZoneName(name: []const u8) []const u8 {
    if (std.mem.eql(u8, name, "Africa/Asmera")) return "Africa/Asmara";
    if (std.mem.eql(u8, name, "Africa/Timbuktu")) return "Africa/Bamako";
    if (std.mem.eql(u8, name, "America/Argentina/ComodRivadavia")) return "America/Argentina/Catamarca";
    if (std.mem.eql(u8, name, "America/Atka")) return "America/Adak";
    if (std.mem.eql(u8, name, "America/Buenos_Aires")) return "America/Argentina/Buenos_Aires";
    if (std.mem.eql(u8, name, "America/Catamarca")) return "America/Argentina/Catamarca";
    if (std.mem.eql(u8, name, "America/Coral_Harbour")) return "America/Atikokan";
    if (std.mem.eql(u8, name, "America/Cordoba")) return "America/Argentina/Cordoba";
    if (std.mem.eql(u8, name, "America/Ensenada")) return "America/Tijuana";
    if (std.mem.eql(u8, name, "America/Fort_Wayne")) return "America/Indiana/Indianapolis";
    if (std.mem.eql(u8, name, "America/Godthab")) return "America/Nuuk";
    if (std.mem.eql(u8, name, "America/Indianapolis")) return "America/Indiana/Indianapolis";
    if (std.mem.eql(u8, name, "America/Jujuy")) return "America/Argentina/Jujuy";
    if (std.mem.eql(u8, name, "America/Knox_IN")) return "America/Indiana/Knox";
    if (std.mem.eql(u8, name, "America/Louisville")) return "America/Kentucky/Louisville";
    if (std.mem.eql(u8, name, "America/Mendoza")) return "America/Argentina/Mendoza";
    if (std.mem.eql(u8, name, "America/Montreal") or std.mem.eql(u8, name, "America/Nipigon") or std.mem.eql(u8, name, "America/Thunder_Bay")) return "America/Toronto";
    if (std.mem.eql(u8, name, "America/Pangnirtung")) return "America/Iqaluit";
    if (std.mem.eql(u8, name, "America/Porto_Acre")) return "America/Rio_Branco";
    if (std.mem.eql(u8, name, "America/Rainy_River")) return "America/Winnipeg";
