// ===== DOMException (WebIDL) ==========================================
// The legacy error-code table: each entry maps a `*_ERR` constant (installed on
// the constructor and its prototype) to a numeric code, and — where a modern
// name exists — to the DOMException `name` that yields that code.
const DomExceptionCode = struct { constant: []const u8, code: u16, err_name: []const u8 };
const dom_exception_codes = [_]DomExceptionCode{
    .{ .constant = "INDEX_SIZE_ERR", .code = 1, .err_name = "IndexSizeError" },
    .{ .constant = "DOMSTRING_SIZE_ERR", .code = 2, .err_name = "" },
    .{ .constant = "HIERARCHY_REQUEST_ERR", .code = 3, .err_name = "HierarchyRequestError" },
    .{ .constant = "WRONG_DOCUMENT_ERR", .code = 4, .err_name = "WrongDocumentError" },
    .{ .constant = "INVALID_CHARACTER_ERR", .code = 5, .err_name = "InvalidCharacterError" },
    .{ .constant = "NO_DATA_ALLOWED_ERR", .code = 6, .err_name = "" },
    .{ .constant = "NO_MODIFICATION_ALLOWED_ERR", .code = 7, .err_name = "NoModificationAllowedError" },
    .{ .constant = "NOT_FOUND_ERR", .code = 8, .err_name = "NotFoundError" },
    .{ .constant = "NOT_SUPPORTED_ERR", .code = 9, .err_name = "NotSupportedError" },
    .{ .constant = "INUSE_ATTRIBUTE_ERR", .code = 10, .err_name = "InUseAttributeError" },
    .{ .constant = "INVALID_STATE_ERR", .code = 11, .err_name = "InvalidStateError" },
    .{ .constant = "SYNTAX_ERR", .code = 12, .err_name = "SyntaxError" },
    .{ .constant = "INVALID_MODIFICATION_ERR", .code = 13, .err_name = "InvalidModificationError" },
    .{ .constant = "NAMESPACE_ERR", .code = 14, .err_name = "NamespaceError" },
    .{ .constant = "INVALID_ACCESS_ERR", .code = 15, .err_name = "InvalidAccessError" },
    .{ .constant = "VALIDATION_ERR", .code = 16, .err_name = "" },
    .{ .constant = "TYPE_MISMATCH_ERR", .code = 17, .err_name = "TypeMismatchError" },
    .{ .constant = "SECURITY_ERR", .code = 18, .err_name = "SecurityError" },
    .{ .constant = "NETWORK_ERR", .code = 19, .err_name = "NetworkError" },
    .{ .constant = "ABORT_ERR", .code = 20, .err_name = "AbortError" },
    .{ .constant = "URL_MISMATCH_ERR", .code = 21, .err_name = "URLMismatchError" },
    .{ .constant = "QUOTA_EXCEEDED_ERR", .code = 22, .err_name = "QuotaExceededError" },
    .{ .constant = "TIMEOUT_ERR", .code = 23, .err_name = "TimeoutError" },
    .{ .constant = "INVALID_NODE_TYPE_ERR", .code = 24, .err_name = "InvalidNodeTypeError" },
    .{ .constant = "DATA_CLONE_ERR", .code = 25, .err_name = "DataCloneError" },
};

/// The legacy `code` a DOMException `name` maps to (0 for a name with no code).
fn domExceptionCode(name: []const u8) u16 {
    for (dom_exception_codes) |ec| {
        if (ec.err_name.len > 0 and std.mem.eql(u8, name, ec.err_name)) return ec.code;
    }
    return 0;
}

// `name`/`message`/`code` are WebIDL attributes (prototype accessors), reading
// per-instance state: `name` from cold error metadata, `message` from a
// hidden slot, `code` derived from `name`.
fn domExceptionNameGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return self.throwError("TypeError", "DOMException name getter called on non-object");
    const en = this.asObj().errorName();
    return try Value.strAlloc(self.arena, en);
}
fn domExceptionMessageGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return self.throwError("TypeError", "DOMException message getter called on non-object");
    if (this.asObj().getOwn("\x00dommsg")) |m| return m;
    return Value.str("");
}
fn domExceptionCodeGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return self.throwError("TypeError", "DOMException code getter called on non-object");
    return Value.num(@floatFromInt(domExceptionCode(this.asObj().errorName())));
}

fn domExceptionConstructorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (self.new_target.isUndefined()) return self.throwError("TypeError", "Failed to construct 'DOMException': Please use the 'new' operator");
    const message = if (args.len > 0 and !args[0].isUndefined()) try self.toStringWtf8(args[0]) else "";
    const name = if (args.len > 1 and !args[1].isUndefined()) try self.toStringWtf8(args[1]) else "Error";
    return self.makeDOMException(name, message);
}

fn installDOMException(env: *Environment, rs: *Shape, object_proto: *value.Object) EvalError!void {
    const a = env.arena;
    // DOMException.prototype's [[Prototype]] is %Error.prototype% (so a
    // DOMException is `instanceof Error`), falling back to Object.prototype.
    const error_proto: *value.Object = blk: {
        if (env.get("Error")) |e| if (e.isObject()) {
            if (e.asObj().getOwn("prototype")) |p| if (p.isObject()) break :blk p.asObj();
        };
        break :blk object_proto;
    };
    const sym_tag: ?[]const u8 = blk: {
        if (env.get("Symbol")) |sym| if (sym.isObject()) {
            if (sym.asObj().getOwn("toStringTag")) |t| if (t.isObject() and t.asObj().is_symbol) break :blk t.asObj().symbolKey();
        };
        break :blk null;
    };
    const proto = try gc_mod.allocObj(a);
    proto.* = .{ .proto = error_proto };
    // WebIDL attributes are enumerable, configurable accessors.
    inline for (.{ .{ "name", domExceptionNameGet }, .{ "message", domExceptionMessageGet }, .{ "code", domExceptionCodeGet } }) |g| {
        try setNativeGetter(a, rs, proto, g[0], g[1]);
        try proto.setAttr(a, g[0], .{ .enumerable = true, .configurable = true });
    }
    if (sym_tag) |k| {
        try proto.setOwn(a, rs, k, Value.str("DOMException"));
        try proto.setAttr(a, k, .{ .writable = false, .enumerable = false, .configurable = true });
    }
    const ctor = try gc_mod.allocObj(a);
    ctor.* = .{ .native = domExceptionConstructorFn, .native_ctor = true };
    // WebIDL constructor `length` counts REQUIRED args; both message and name are
    // optional, so DOMException.length is 0.
    try installNativeProps(a, rs, ctor, "DOMException", 0);
    try ctor.setOwn(a, rs, "prototype", Value.obj(proto));
    try ctor.setAttr(a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
    try setConstructor(a, rs, proto, ctor);
    // The legacy code constants live on both the constructor and its prototype,
    // { !writable, enumerable, !configurable }.
    inline for (dom_exception_codes) |ec| {
        const cv = Value.num(@floatFromInt(ec.code));
        const attr = value.PropAttr{ .writable = false, .enumerable = true, .configurable = false };
        try ctor.setOwn(a, rs, ec.constant, cv);
        try ctor.setAttr(a, ec.constant, attr);
        try proto.setOwn(a, rs, ec.constant, cv);
        try proto.setAttr(a, ec.constant, attr);
    }
    try env.put("DOMException", Value.obj(ctor));
}

// ===== TextEncoder (Encoding standard) ================================
/// Convert a WTF-8 JS string to valid UTF-8 bytes: combine a surrogate pair into
/// its scalar, and replace every LONE surrogate with U+FFFD.
fn wtf8ToUtf8Bytes(arena: std.mem.Allocator, s: []const u8) EvalError![]const u8 {
    var first_surrogate: ?usize = null;
    var i: usize = 0;
    while (i < s.len) {
        if (wtf8SurrogateAt(s, i) != null) {
            first_surrogate = i;
            break;
        }
        i += utf8SeqLen(s, i);
    }
    const first_changed = first_surrogate orelse return s;

    // Pair combination shortens six WTF-8 bytes to four valid UTF-8 bytes;
    // lone-surrogate replacement stays three bytes. One input-sized arena
    // allocation is therefore a complete upper bound, and the returned result
    // may be its shorter subslice.
    const out = try arena.alloc(u8, s.len);
    @memcpy(out[0..first_changed], s[0..first_changed]);
    var written = first_changed;
    i = first_changed;
    while (i < s.len) {
        if (wtf8SurrogateAt(s, i)) |first| {
            if (isHighSurrogate(first)) {
                if (wtf8SurrogateAt(s, i + 3)) |second| if (isLowSurrogate(second)) {
                    const cp: u21 = 0x10000 + ((@as(u21, first - 0xD800) << 10) | (second - 0xDC00));
                    const n = std.unicode.utf8Encode(cp, out[written..][0..4]) catch unreachable;
                    std.debug.assert(n == 4);
                    written += n;
                    i += 6;
                    continue;
                };
            }
            @memcpy(out[written .. written + 3], "\u{FFFD}");
            written += 3;
            i += 3;
        } else {
            const n = utf8SeqLen(s, i);
            @memcpy(out[written .. written + n], s[i .. i + n]);
            written += n;
            i += n;
        }
    }
    std.debug.assert(written <= out.len);
    return out[0..written];
}

test "UTF-8 egress borrows valid input and transforms WTF-8 with one bounded allocation" {
    var no_memory: [0]u8 = .{};
    var fixed = std.heap.FixedBufferAllocator.init(&no_memory);
    for ([_][]const u8{ "plain ASCII", "BMP é水 and astral 😀" }) |input| {
        const borrowed = try wtf8ToUtf8Bytes(fixed.allocator(), input);
        try std.testing.expectEqual(@intFromPtr(input.ptr), @intFromPtr(borrowed.ptr));
        try std.testing.expectEqualStrings(input, borrowed);
    }

    var measured = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    var measured_arena = std.heap.ArenaAllocator.init(measured.allocator());
    defer measured_arena.deinit();
    const transformed = try wtf8ToUtf8Bytes(
        measured_arena.allocator(),
        "A\xED\xA0\xBD\xED\xB8\x80B\xED\xA0\x80C\xED\xB0\x80",
    );
    try std.testing.expectEqualStrings("A😀B\u{FFFD}C\u{FFFD}", transformed);
    try std.testing.expectEqual(@as(usize, 1), measured.allocations);
    try std.testing.expect(measured.allocated_bytes >= transformed.len);

    var exhausted_memory: [0]u8 = .{};
    var exhausted = std.heap.FixedBufferAllocator.init(&exhausted_memory);
    try std.testing.expectError(error.OutOfMemory, wtf8ToUtf8Bytes(exhausted.allocator(), "\xED\xA0\x80"));
}

fn textEncoderConstructorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (self.new_target.isUndefined()) return self.throwError("TypeError", "Failed to construct 'TextEncoder': Please use the 'new' operator");
    const obj = try gc_mod.allocObj(self.arena);
    obj.* = .{};
    if (self.env.get("TextEncoder")) |c| if (c.isObject()) {
        if (c.asObj().getOwn("prototype")) |p| if (p.isObject()) obj.setProtoAtomic(p.asObj());
    };
    return Value.obj(obj);
}
fn textEncoderEncodingGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = ctx;
    _ = this;
    _ = args;
    return Value.str("utf-8");
}
fn textEncoderEncodeFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const s = if (args.len > 0 and !args[0].isUndefined()) try self.toStringWtf8(args[0]) else "";
    const bytes = try wtf8ToUtf8Bytes(self.arena, s);
    const o = try newTypedArray(self, .u8, bytes.len);
    if (bytes.len > 0) @memcpy(o.typedArray().?.buffer.arrayBuffer().?.bytes()[0..bytes.len], bytes);
    return Value.obj(o);
}
/// `encodeInto(source, destination)` — encode as much of `source` as fits in the
/// Uint8Array `destination`, never splitting a character, and report
/// `{ read, written }` (read = source UTF-16 code units consumed).
fn textEncoderEncodeIntoFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const s = if (args.len > 0 and !args[0].isUndefined()) try self.toStringWtf8(args[0]) else "";
    const dv = if (args.len > 1) args[1] else Value.undef();
    if (!dv.isObject() or dv.asObj().typedArray() == null or dv.asObj().typedArray().?.kind != .u8)
        return self.throwError("TypeError", "TextEncoder.encodeInto destination must be a Uint8Array");
    const ta = dv.asObj().typedArray().?;
    const dest_buf = ta.buffer.arrayBuffer().?;
    const locked = dest_buf.needsElementLock();
    if (locked) dest_buf.lockBuffer();
    const dest = dest_buf.bytes()[ta.byte_offset .. ta.byte_offset + (ta.currentLength() orelse 0)];
    var read: usize = 0;
    var written: usize = 0;
    var i: usize = 0;
    var b: [4]u8 = undefined;
    while (i < s.len) {
        var cp: u21 = undefined;
        var byte_adv: usize = undefined;
        var cu: usize = undefined;
        if (wtf8SurrogateAt(s, i)) |first| {
            var handled_pair = false;
            if (isHighSurrogate(first)) {
                if (wtf8SurrogateAt(s, i + 3)) |second| {
                    if (isLowSurrogate(second)) {
                        cp = 0x10000 + ((@as(u21, first - 0xD800) << 10) | (second - 0xDC00));
                        byte_adv = 6;
                        cu = 2;
                        handled_pair = true;
                    }
                }
            }
            if (!handled_pair) {
                cp = 0xFFFD;
                byte_adv = 3;
                cu = 1;
            }
        } else {
            const n = utf8SeqLen(s, i);
            cp = std.unicode.utf8Decode(s[i .. i + n]) catch 0xFFFD;
            byte_adv = n;
            cu = if (cp >= 0x10000) 2 else 1;
        }
        const enc_n = std.unicode.utf8Encode(cp, &b) catch unreachable;
        if (written + enc_n > dest.len) break;
        value.writeArrayBufferBytes(dest_buf, dest, written, b[0..enc_n]);
        written += enc_n;
        read += cu;
        i += byte_adv;
    }
    if (locked) dest_buf.unlockBuffer();
    const res = (try self.newObject()).asObj();
    try self.setProp(res, "read", Value.num(@floatFromInt(read)));
    try self.setProp(res, "written", Value.num(@floatFromInt(written)));
    return Value.obj(res);
}

fn installTextEncoder(env: *Environment, rs: *Shape, object_proto: *value.Object) EvalError!void {
    const a = env.arena;
    const sym_tag: ?[]const u8 = blk: {
        if (env.get("Symbol")) |sym| if (sym.isObject()) {
            if (sym.asObj().getOwn("toStringTag")) |t| if (t.isObject() and t.asObj().is_symbol) break :blk t.asObj().symbolKey();
        };
        break :blk null;
    };
    const proto = try gc_mod.allocObj(a);
    proto.* = .{ .proto = object_proto };
    try setNativeGetter(a, rs, proto, "encoding", textEncoderEncodingGet);
    try proto.setAttr(a, "encoding", .{ .enumerable = true, .configurable = true });
    try setNative(a, rs, proto, "encode", 0, textEncoderEncodeFn);
    try setNative(a, rs, proto, "encodeInto", 2, textEncoderEncodeIntoFn);
    if (sym_tag) |k| {
        try proto.setOwn(a, rs, k, Value.str("TextEncoder"));
        try proto.setAttr(a, k, .{ .writable = false, .enumerable = false, .configurable = true });
    }
    const ctor = try gc_mod.allocObj(a);
    ctor.* = .{ .native = textEncoderConstructorFn, .native_ctor = true };
    try installNativeProps(a, rs, ctor, "TextEncoder", 0);
    try ctor.setOwn(a, rs, "prototype", Value.obj(proto));
    try ctor.setAttr(a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
    try setConstructor(a, rs, proto, ctor);
    try env.put("TextEncoder", Value.obj(ctor));
}

// ===== TextDecoder (Encoding standard, common encodings) ==============
/// Map an encoding label (trimmed, case-insensitive) to its canonical name, or
/// null for an unsupported/unknown label (→ RangeError).
fn textDecoderEncoding(label: []const u8) ?[]const u8 {
    // The full WHATWG label→name map (utf-8/utf-16le/utf-16be + all single-byte
    // encodings). Multi-byte (big5/gbk/gb18030/shift_jis/euc-*) is not yet
    // supported, so their labels are absent → RangeError.
    return enc_data.labelToName(std.mem.trim(u8, label, " \t\n\r\x0c"));
}

/// The bytes a BufferSource (ArrayBuffer/SharedArrayBuffer/TypedArray/DataView)
/// currently views, or null if `v` is not a buffer source.
fn bufferSourceBytes(v: Value) ?[]const u8 {
    if (!v.isObject()) return null;
    const o = v.asObj();
    if (o.typedArray()) |ta| {
        const ab = ta.buffer.arrayBuffer() orelse return null;
        if (ab.isDetached()) return &.{};
        const len = (ta.currentLength() orelse 0) * ta.kind.byteSize();
        return ab.bytes()[ta.byte_offset .. ta.byte_offset + len];
    }
    if (o.dataView()) |dv| {
        const ab = dv.buffer.arrayBuffer() orelse return null;
        if (ab.isDetached()) return &.{};
        return ab.bytes()[dv.byte_offset .. dv.byte_offset + (dv.currentByteLength() orelse 0)];
    }
    if (o.arrayBuffer()) |ab| {
        if (ab.isDetached()) return &.{};
        return ab.bytes();
    }
    return null;
}

fn tdEmit(self: *Interpreter, out: *std.ArrayListUnmanaged(u8), cp: u21) EvalError!void {
    var b: [4]u8 = undefined;
    const n = std.unicode.utf8Encode(cp, &b) catch {
        try out.appendSlice(self.arena, "\u{FFFD}");
        return;
    };
    try out.appendSlice(self.arena, b[0..n]);
}

fn textDecoderConstructorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (self.new_target.isUndefined()) return self.throwError("TypeError", "Failed to construct 'TextDecoder': Please use the 'new' operator");
    const label = if (args.len > 0 and !args[0].isUndefined()) try self.toStringV(args[0]) else "utf-8";
    const enc = textDecoderEncoding(label) orelse return self.throwError("RangeError", "The encoding label provided is invalid.");
    var fatal = false;
    var ignore_bom = false;
    if (args.len > 1 and args[1].isObject()) {
        fatal = (try self.getProperty(args[1], "fatal")).toBoolean();
        ignore_bom = (try self.getProperty(args[1], "ignoreBOM")).toBoolean();
    }
    const obj = try gc_mod.allocObj(self.arena);
    obj.* = .{};
    if (self.env.get("TextDecoder")) |c| if (c.isObject()) {
        if (c.asObj().getOwn("prototype")) |p| if (p.isObject()) obj.setProtoAtomic(p.asObj());
    };
    try obj.setOwn(self.arena, self.root_shape, "\x00tdenc", try Value.strAlloc(self.arena, enc));
    try obj.setOwn(self.arena, self.root_shape, "\x00tdfatal", Value.boolVal(fatal));
    try obj.setOwn(self.arena, self.root_shape, "\x00tdbom", Value.boolVal(ignore_bom));
    return Value.obj(obj);
}
fn tdSlotStr(this: Value, key: []const u8, dflt: []const u8) []const u8 {
    if (this.isObject()) if (this.asObj().getOwn(key)) |v| if (v.isString()) return v.asStr();
    return dflt;
}
fn tdSlotBool(this: Value, key: []const u8) bool {
    if (this.isObject()) if (this.asObj().getOwn(key)) |v| return v.toBoolean();
    return false;
}
fn textDecoderEncodingGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = ctx;
    _ = args;
    if (this.isObject()) if (this.asObj().getOwn("\x00tdenc")) |v| return v;
    return Value.str("utf-8");
}
fn textDecoderFatalGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = ctx;
    _ = args;
    return Value.boolVal(tdSlotBool(this, "\x00tdfatal"));
}
fn textDecoderIgnoreBomGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = ctx;
    _ = args;
    return Value.boolVal(tdSlotBool(this, "\x00tdbom"));
}
fn textDecoderDecodeFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return self.throwError("TypeError", "TextDecoder.decode called on non-object");
    const enc = tdSlotStr(this, "\x00tdenc", "utf-8");
    const fatal = tdSlotBool(this, "\x00tdfatal");
    const ignore_bom = tdSlotBool(this, "\x00tdbom");
    var bytes: []const u8 = "";
    if (args.len > 0 and !args[0].isUndefined()) {
        bytes = bufferSourceBytes(args[0]) orelse return self.throwError("TypeError", "TextDecoder.decode input must be a BufferSource");
    }
    var out: std.ArrayListUnmanaged(u8) = .empty;
    if (std.mem.eql(u8, enc, "utf-8")) {
        var i: usize = 0;
        if (!ignore_bom and bytes.len >= 3 and bytes[0] == 0xEF and bytes[1] == 0xBB and bytes[2] == 0xBF) i = 3;
        while (i < bytes.len) {
            const n = std.unicode.utf8ByteSequenceLength(bytes[i]) catch {
                if (fatal) return self.throwError("TypeError", "The encoded data was not valid.");
                try out.appendSlice(self.arena, "\u{FFFD}");
                i += 1;
                continue;
            };
            if (i + n > bytes.len or (std.unicode.utf8Decode(bytes[i .. i + n]) catch null) == null) {
                if (fatal) return self.throwError("TypeError", "The encoded data was not valid.");
                try out.appendSlice(self.arena, "\u{FFFD}");
                i += 1;
                continue;
            }
            try out.appendSlice(self.arena, bytes[i .. i + n]);
            i += n;
        }
    } else if (std.mem.eql(u8, enc, "windows-1252")) {
        // node/V8 decodes windows-1252 (and its iso-8859-1/latin1/ascii aliases)
        // as latin1 — a raw byte→code-point map, not the WHATWG index.
        for (bytes) |b| try tdEmit(self, &out, b);
    } else if (enc_mb.isMultibyte(enc)) {
        enc_mb.decode(self.arena, &out, enc, bytes, fatal) catch |e| switch (e) {
            error.DecodeInvalid => return self.throwError("TypeError", "The encoded data was not valid."),
            error.OutOfMemory => return error.OutOfMemory,
        };
    } else if (enc_data.singleByteTable(enc)) |tbl| {
        // WHATWG single-byte decoder: 0x00–0x7F is ASCII; a high byte indexes the
        // table, and a 0xFFFD entry is an unmapped byte (error / U+FFFD).
        for (bytes) |b| {
            if (b < 0x80) {
                try tdEmit(self, &out, b);
            } else {
                const cp = tbl[b - 0x80];
                if (cp == 0xFFFD and fatal) return self.throwError("TypeError", "The encoded data was not valid.");
                try tdEmit(self, &out, cp);
            }
        }
    } else { // utf-16le / utf-16be
        const le = std.mem.eql(u8, enc, "utf-16le");
        var i: usize = 0;
        if (!ignore_bom and bytes.len >= 2) {
            if (le and bytes[0] == 0xFF and bytes[1] == 0xFE) i = 2 else if (!le and bytes[0] == 0xFE and bytes[1] == 0xFF) i = 2;
        }
        while (i + 1 < bytes.len) : (i += 2) {
            const unit: u16 = if (le) @as(u16, bytes[i]) | (@as(u16, bytes[i + 1]) << 8) else (@as(u16, bytes[i]) << 8) | bytes[i + 1];
            if (unit >= 0xD800 and unit <= 0xDBFF and i + 3 < bytes.len) {
                const lo: u16 = if (le) @as(u16, bytes[i + 2]) | (@as(u16, bytes[i + 3]) << 8) else (@as(u16, bytes[i + 2]) << 8) | bytes[i + 3];
                if (lo >= 0xDC00 and lo <= 0xDFFF) {
                    const cp: u21 = 0x10000 + ((@as(u21, unit - 0xD800) << 10) | (lo - 0xDC00));
                    try tdEmit(self, &out, cp);
                    i += 2;
                    continue;
                }
            }
            if (unit >= 0xD800 and unit <= 0xDFFF) {
                if (fatal) return self.throwError("TypeError", "The encoded data was not valid.");
                try out.appendSlice(self.arena, "\u{FFFD}");
            } else try tdEmit(self, &out, unit);
        }
        if (i < bytes.len) { // dangling odd byte
            if (fatal) return self.throwError("TypeError", "The encoded data was not valid.");
            try out.appendSlice(self.arena, "\u{FFFD}");
        }
    }
    return try Value.strAlloc(self.arena, out.items);
}

fn installTextDecoder(env: *Environment, rs: *Shape, object_proto: *value.Object) EvalError!void {
    const a = env.arena;
    const sym_tag: ?[]const u8 = blk: {
        if (env.get("Symbol")) |sym| if (sym.isObject()) {
            if (sym.asObj().getOwn("toStringTag")) |t| if (t.isObject() and t.asObj().is_symbol) break :blk t.asObj().symbolKey();
        };
        break :blk null;
    };
    const proto = try gc_mod.allocObj(a);
    proto.* = .{ .proto = object_proto };
    inline for (.{ .{ "encoding", textDecoderEncodingGet }, .{ "fatal", textDecoderFatalGet }, .{ "ignoreBOM", textDecoderIgnoreBomGet } }) |g| {
        try setNativeGetter(a, rs, proto, g[0], g[1]);
        try proto.setAttr(a, g[0], .{ .enumerable = true, .configurable = true });
    }
    try setNative(a, rs, proto, "decode", 0, textDecoderDecodeFn);
    if (sym_tag) |k| {
        try proto.setOwn(a, rs, k, Value.str("TextDecoder"));
        try proto.setAttr(a, k, .{ .writable = false, .enumerable = false, .configurable = true });
    }
    const ctor = try gc_mod.allocObj(a);
    ctor.* = .{ .native = textDecoderConstructorFn, .native_ctor = true };
    try installNativeProps(a, rs, ctor, "TextDecoder", 0);
    try ctor.setOwn(a, rs, "prototype", Value.obj(proto));
    try ctor.setAttr(a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
    try setConstructor(a, rs, proto, ctor);
    try env.put("TextDecoder", Value.obj(ctor));
}

// ===== URL (WHATWG, common schemes) ==================================
pub const UrlParts = struct {
    scheme: []const u8 = "",
    username: []const u8 = "",
    password: []const u8 = "",
    host: ?[]const u8 = null, // null = no host (opaque-path URLs)
    port: []const u8 = "", // "" = default/none
    path: []const u8 = "", // serialized path (incl. leading '/' for special), or opaque path
    query: ?[]const u8 = null,
    fragment: ?[]const u8 = null,
    opaque_path: bool = false,
};
fn urlIsSpecialScheme(s: []const u8) bool {
    const special = [_][]const u8{ "http", "https", "ws", "wss", "ftp", "file" };
    for (special) |sp| if (std.mem.eql(u8, s, sp)) return true;
    return false;
}
fn urlDefaultPort(s: []const u8) ?[]const u8 {
    if (std.mem.eql(u8, s, "http") or std.mem.eql(u8, s, "ws")) return "80";
    if (std.mem.eql(u8, s, "https") or std.mem.eql(u8, s, "wss")) return "443";
    if (std.mem.eql(u8, s, "ftp")) return "21";
    return null;
}
pub const UrlEncSet = enum { c0, fragment, query, special_query, path, userinfo };
fn urlShouldEncode(set: UrlEncSet, b: u8) bool {
    if (b <= 0x1F or b > 0x7E) return true;
    const in = struct {
        fn f(c: u8, chars: []const u8) bool {
            return std.mem.indexOfScalar(u8, chars, c) != null;
        }
    }.f;
    return switch (set) {
        .c0 => false,
        .fragment => b == ' ' or in(b, "\"<>`"),
        .query => b == ' ' or in(b, "\"#<>"),
        .special_query => b == ' ' or in(b, "\"#<>'"),
        .path => b == ' ' or in(b, "\"#<>?`{}"),
        .userinfo => b == ' ' or in(b, "\"#<>?`{}/:;=@[\\]^|"),
    };
}
pub fn urlPercentEncode(arena: std.mem.Allocator, out: *std.ArrayListUnmanaged(u8), s: []const u8, set: UrlEncSet) EvalError!void {
    const utf8 = try wtf8ToUtf8Bytes(arena, s);
    const hex = "0123456789ABCDEF";
    for (utf8) |b| {
        if (urlShouldEncode(set, b)) {
            try out.append(arena, '%');
            try out.append(arena, hex[b >> 4]);
            try out.append(arena, hex[b & 0x0F]);
        } else try out.append(arena, b);
    }
}
/// Percent-decode `%XX` sequences (allocator-first). Unlike the
/// form-urlencoded decoder there is no `+` rule — this is for URL paths.
pub fn urlPercentDecode(arena: std.mem.Allocator, s: []const u8) error{OutOfMemory}![]const u8 {
    var out: std.ArrayListUnmanaged(u8) = .empty;
    var i: usize = 0;
    while (i < s.len) {
        const c = s[i];
        if (c == '%' and i + 2 < s.len) {
            if (hexDigit(s[i + 1])) |hi| {
                if (hexDigit(s[i + 2])) |lo| {
                    try out.append(arena, hi * 16 + lo);
                    i += 3;
                    continue;
                }
            }
        }
        try out.append(arena, c);
        i += 1;
    }
    return out.items;
}
fn urlStripTabsNewlines(a: std.mem.Allocator, s: []const u8) ![]const u8 {
    var out: std.ArrayListUnmanaged(u8) = .empty;
    for (s) |c| if (c != '\t' and c != '\n' and c != '\r') try out.append(a, c);
    return out.items;
}
fn isC0OrSpace(c: u8) bool {
    return c <= 0x20;
}
/// Parse a URL string (optionally against a base). Handles special schemes with
/// an authority, opaque-path non-special schemes, and basic relative resolution.
pub fn urlParse(arena: std.mem.Allocator, input_raw: []const u8, base: ?UrlParts) EvalError!?UrlParts {
    // Trim leading/trailing C0-control-or-space, then remove all tab/newline.
    var t = input_raw;
    while (t.len > 0 and isC0OrSpace(t[0])) t = t[1..];
    while (t.len > 0 and isC0OrSpace(t[t.len - 1])) t = t[0 .. t.len - 1];
    const input = try urlStripTabsNewlines(arena, t);

    var p = UrlParts{};
    var rest = input;
    // Scheme: ALPHA *( ALPHA / DIGIT / "+" / "-" / "." ) ":"
    var scheme_end: ?usize = null;
    if (input.len > 0 and std.ascii.isAlphabetic(input[0])) {
        var i: usize = 1;
        while (i < input.len) : (i += 1) {
            const c = input[i];
            if (c == ':') {
                scheme_end = i;
                break;
            }
            if (!(std.ascii.isAlphanumeric(c) or c == '+' or c == '-' or c == '.')) break;
        }
    }
    if (scheme_end) |se| {
        var sb: std.ArrayListUnmanaged(u8) = .empty;
        for (input[0..se]) |c| try sb.append(arena, std.ascii.toLower(c));
        p.scheme = sb.items;
        rest = input[se + 1 ..];
    } else {
        // No scheme → relative reference; requires a base.
        const b = base orelse return null;
        p = b;
        p.query = b.query;
        p.fragment = null;
        return try urlParseRelative(arena, &p, input);
    }

    const special = urlIsSpecialScheme(p.scheme);
    const has_authority = std.mem.startsWith(u8, rest, "//") or (special and std.mem.startsWith(u8, rest, "/"));
    if (special or std.mem.startsWith(u8, rest, "//")) {
        // A special non-file scheme tolerates ANY number of leading `/`/`\`
        // before the authority (`http:///path` → host `path`). A non-special
        // scheme takes exactly the `//` that introduced the authority. `file`
        // keeps its original handling (strip the `//`, else skip slashes) so its
        // Windows-drive-letter path logic is unaffected.
        var body = rest;
        const is_file = std.mem.eql(u8, p.scheme, "file");
        if (special and !is_file) {
            while (body.len > 0 and (body[0] == '/' or body[0] == '\\')) body = body[1..];
        } else if (std.mem.startsWith(u8, body, "//")) {
            body = body[2..];
        } else if (special) { // file, no leading "//"
            while (body.len > 0 and (body[0] == '/' or body[0] == '\\')) body = body[1..];
        }
        // Authority ends at the first / \ ? #
        var auth_end: usize = body.len;
        for (body, 0..) |c, i| {
            if (c == '/' or c == '?' or c == '#' or (special and c == '\\')) {
                auth_end = i;
                break;
            }
        }
        const authority = body[0..auth_end];
        const after = body[auth_end..];
        // userinfo (last '@' in authority)
        var hostport = authority;
        if (std.mem.lastIndexOfScalar(u8, authority, '@')) |at| {
            const userinfo = authority[0..at];
            hostport = authority[at + 1 ..];
            if (std.mem.indexOfScalar(u8, userinfo, ':')) |colon| {
                var ub: std.ArrayListUnmanaged(u8) = .empty;
                try urlPercentEncode(arena, &ub, userinfo[0..colon], .userinfo);
                p.username = ub.items;
                var pb: std.ArrayListUnmanaged(u8) = .empty;
                try urlPercentEncode(arena, &pb, userinfo[colon + 1 ..], .userinfo);
                p.password = pb.items;
            } else {
                var ub: std.ArrayListUnmanaged(u8) = .empty;
                try urlPercentEncode(arena, &ub, userinfo, .userinfo);
                p.username = ub.items;
            }
        }
        // host[:port] — an IPv6 literal in brackets is parsed and re-serialized
        // to its canonical compressed form (`[2001:db8:0:0:0:0:0:1]` → `[2001:db8::1]`).
        var host_str = hostport;
        var ipv6_host: ?[]const u8 = null;
        if (hostport.len > 0 and hostport[0] == '[') {
            const close = std.mem.indexOfScalar(u8, hostport, ']') orelse return null;
            const addr = urlParseIPv6(hostport[1..close]) orelse return null;
            ipv6_host = try urlSerializeIPv6(arena, addr);
            const tail = hostport[close + 1 ..];
            if (tail.len > 0) {
                if (tail[0] != ':') return null; // junk after `]` is invalid
                p.port = try urlNormalizePort(arena, p.scheme, tail[1..]) orelse return null;
            }
        } else if (std.mem.lastIndexOfScalar(u8, hostport, ':')) |colon| {
            host_str = hostport[0..colon];
            p.port = try urlNormalizePort(arena, p.scheme, hostport[colon + 1 ..]) orelse return null;
        }
        // Host: a special scheme's host is a domain (ASCII-lowercased); a
        // non-special scheme's is an opaque host (case preserved, only C0-encoded).
        if (ipv6_host) |h6| {
            p.host = h6;
        } else if (host_str.len == 0) {
            if (special and !std.mem.eql(u8, p.scheme, "file")) return null;
            p.host = "";
        } else {
            // Special: lowercase / IDNA-to-ASCII / IPv4. Non-special: opaque host
            // (C0-percent-encoded). Shared with the host/hostname setters.
            p.host = (try urlCanonHost(arena, p.scheme, host_str)) orelse return null;
        }
        // A file URL may not carry credentials or a port.
        if (std.mem.eql(u8, p.scheme, "file") and (p.username.len > 0 or p.password.len > 0 or p.port.len > 0)) return null;
        try urlParsePathQueryFrag(arena, &p, after, special, true);
    } else {
        // No authority: opaque path (non-special) — the rest up to ?/# is the path.
        _ = has_authority;
        try urlParsePathQueryFrag(arena, &p, rest, false, false);
        p.opaque_path = !std.mem.startsWith(u8, rest, "/");
    }
    return p;
}
fn urlNormalizePort(arena: std.mem.Allocator, scheme: []const u8, s: []const u8) EvalError!?[]const u8 {
    if (s.len == 0) return "";
    var n: u32 = 0;
    for (s) |c| {
        if (!std.ascii.isDigit(c)) return null;
        n = n * 10 + (c - '0');
        if (n > 65535) return null;
    }
    if (urlDefaultPort(scheme)) |dp| {
        var buf: [8]u8 = undefined;
        const ns = std.fmt.bufPrint(&buf, "{d}", .{n}) catch return null;
        if (std.mem.eql(u8, ns, dp)) return ""; // default port omitted
    }
    // Serialize the parsed number, not the raw text: WHATWG stores the port as
    // an integer, so leading zeros are dropped (`:007` → `7`).
    return try std.fmt.allocPrint(arena, "{d}", .{n});
}

/// WHATWG IPv4-number parser: decode one dotted part as decimal, `0x…` hex, or
/// `0…` octal. Returns null on an invalid digit or >32-bit overflow. An empty
/// part (or a bare `0x`) is 0.
fn urlParseIPv4Number(part: []const u8) ?u32 {
    if (part.len == 0) return null; // an originally-empty part fails (`1..2` is invalid)
    var s = part;
    var radix: u8 = 10;
    if (s.len >= 2 and s[0] == '0' and (s[1] == 'x' or s[1] == 'X')) {
        radix = 16;
        s = s[2..];
    } else if (s.len >= 2 and s[0] == '0') {
        radix = 8;
        s = s[1..];
    }
    if (s.len == 0) return 0;
    var n: u64 = 0;
    for (s) |c| {
        const d = std.fmt.charToDigit(c, radix) catch return null;
        n = n * radix + d;
        if (n > 0xFFFFFFFF) return null;
    }
    return @intCast(n);
}

/// WHATWG "ends in a number" check: does the host's last dot-part (a single
/// trailing empty part removed) parse as an IPv4 number? Gates IPv4 parsing so a
/// real domain (`example.com`) is never mis-parsed.
fn urlHostEndsInNumber(host: []const u8) bool {
    var last = host;
    if (std.mem.lastIndexOfScalar(u8, host, '.')) |dot| {
        if (dot == host.len - 1) {
            const head = host[0..dot];
            last = if (std.mem.lastIndexOfScalar(u8, head, '.')) |d2| head[d2 + 1 ..] else head;
        } else last = host[dot + 1 ..];
    }
    if (last.len == 0) return false;
    var all_digits = true;
    for (last) |c| if (!std.ascii.isDigit(c)) {
        all_digits = false;
        break;
    };
    if (all_digits) return true;
    return urlParseIPv4Number(last) != null and last.len >= 2 and last[0] == '0' and (last[1] == 'x' or last[1] == 'X');
}

/// WHATWG IPv4 parser + serializer: parse `host` (already known to end in a
/// number) into a 32-bit address and return it as canonical dotted decimal, or
/// null on failure (too many parts, a bad number, or an out-of-range value).
fn urlParseIPv4(arena: std.mem.Allocator, host: []const u8) EvalError!?[]const u8 {
    var parts: [5][]const u8 = undefined;
    var np: usize = 0;
    var it = std.mem.splitScalar(u8, host, '.');
    while (it.next()) |part| {
        if (np == 5) return null; // >5 tokens can never be a valid IPv4
        parts[np] = part;
        np += 1;
    }
    if (np > 1 and parts[np - 1].len == 0) np -= 1; // drop a single trailing empty
    if (np == 0 or np > 4) return null;
    var numbers: [4]u32 = undefined;
    for (parts[0..np], 0..) |part, i| numbers[i] = urlParseIPv4Number(part) orelse return null;
    // Every part but the last must fit in a byte.
    var i: usize = 0;
    while (i + 1 < np) : (i += 1) if (numbers[i] > 255) return null;
    // The last part absorbs the remaining bytes: it must be < 256^(5 − np).
    const last = numbers[np - 1];
    const max_shift: u6 = @intCast(8 * (5 - np));
    if (max_shift < 32 and last >= (@as(u64, 1) << max_shift)) return null;
    var ipv4: u32 = last;
    i = 0;
    while (i + 1 < np) : (i += 1) {
        const shift: u5 = @intCast(8 * (3 - i));
        ipv4 +%= numbers[i] << shift;
    }
    return try std.fmt.allocPrint(arena, "{d}.{d}.{d}.{d}", .{
        (ipv4 >> 24) & 0xff, (ipv4 >> 16) & 0xff, (ipv4 >> 8) & 0xff, ipv4 & 0xff,
    });
}

/// WHATWG IPv6 parser: `input` is the text between the `[` `]` brackets. Returns
/// the 8 16-bit pieces, or null on any malformation (too many pieces, a second
/// `::`, a bad hextet, a malformed embedded IPv4 tail).
fn urlParseIPv6(input: []const u8) ?[8]u16 {
    var address = std.mem.zeroes([8]u16);
    var piece_index: usize = 0;
    var compress: ?usize = null;
    var i: usize = 0;
    const n = input.len;
    if (i < n and input[i] == ':') {
        if (i + 1 >= n or input[i + 1] != ':') return null;
        i += 2;
        piece_index += 1;
        compress = piece_index;
    }
    while (i < n) {
        if (piece_index == 8) return null;
        if (input[i] == ':') {
            if (compress != null) return null;
            i += 1;
            piece_index += 1;
            compress = piece_index;
            continue;
        }
        var hextet: u16 = 0;
        var length: usize = 0;
        while (length < 4 and i < n and std.ascii.isHex(input[i])) : (length += 1) {
            hextet = hextet *% 0x10 + @as(u16, std.fmt.charToDigit(input[i], 16) catch return null);
            i += 1;
        }
        if (i < n and input[i] == '.') {
            if (length == 0) return null;
            i -= length; // rewind over the digits just consumed as hex
            if (piece_index > 6) return null;
            var numbers_seen: usize = 0;
            while (i < n) {
                var ipv4_piece: ?u16 = null;
                if (numbers_seen > 0) {
                    if (input[i] == '.' and numbers_seen < 4) i += 1 else return null;
                }
                if (i >= n or !std.ascii.isDigit(input[i])) return null;
                while (i < n and std.ascii.isDigit(input[i])) : (i += 1) {
                    const d: u16 = input[i] - '0';
                    if (ipv4_piece == null) {
                        ipv4_piece = d;
                    } else if (ipv4_piece.? == 0) {
                        return null; // no leading zeros
                    } else ipv4_piece = ipv4_piece.? * 10 + d;
                    if (ipv4_piece.? > 255) return null;
                }
                address[piece_index] = address[piece_index] * 0x100 + ipv4_piece.?;
                numbers_seen += 1;
                if (numbers_seen == 2 or numbers_seen == 4) piece_index += 1;
            }
            if (numbers_seen != 4) return null;
            break;
        } else if (i < n and input[i] == ':') {
            i += 1;
            if (i >= n) return null;
        } else if (i < n) return null;
        address[piece_index] = hextet;
        piece_index += 1;
    }
    if (compress) |c| {
        var swaps = piece_index - c;
        piece_index = 7;
        while (piece_index != 0 and swaps > 0) {
            const tmp = address[piece_index];
            address[piece_index] = address[c + swaps - 1];
            address[c + swaps - 1] = tmp;
            piece_index -= 1;
            swaps -= 1;
        }
    } else if (piece_index != 8) return null;
    return address;
}

/// WHATWG IPv6 serializer: compress the first longest run (>1) of zero pieces to
/// `::`, lowercase hex, no embedded IPv4. Returns the bracketed `[…]` form.
fn urlSerializeIPv6(arena: std.mem.Allocator, address: [8]u16) EvalError![]const u8 {
    var compress: ?usize = null;
    var best_len: usize = 1;
    var idx: usize = 0;
    while (idx < 8) {
        if (address[idx] == 0) {
            var j = idx;
            while (j < 8 and address[j] == 0) : (j += 1) {}
            if (j - idx > best_len) {
                best_len = j - idx;
                compress = idx;
            }
            idx = j;
        } else idx += 1;
    }
    var out: std.ArrayListUnmanaged(u8) = .empty;
    try out.append(arena, '[');
    var ignore0 = false;
    var pi: usize = 0;
    while (pi < 8) : (pi += 1) {
        if (ignore0 and address[pi] == 0) continue;
        ignore0 = false;
        if (compress == pi) {
            try out.appendSlice(arena, if (pi == 0) "::" else ":");
            ignore0 = true;
            continue;
        }
        var buf: [4]u8 = undefined;
        try out.appendSlice(arena, std.fmt.bufPrint(&buf, "{x}", .{address[pi]}) catch unreachable);
        if (pi != 7) try out.append(arena, ':');
    }
    try out.append(arena, ']');
    return out.items;
}

/// Canonicalize a host string for `scheme`: an IPv6 literal `[…]` → compressed
/// form; a special-scheme host → lowercased domain or parsed IPv4; a non-special
/// host → C0-percent-encoded opaque host. Returns null on failure. Shared by the
/// `host`/`hostname` setters (the constructor path inlines the same logic).
fn urlCanonHost(arena: std.mem.Allocator, scheme: []const u8, host_str: []const u8) EvalError!?[]const u8 {
    if (host_str.len > 0 and host_str[0] == '[') {
        const close = std.mem.indexOfScalar(u8, host_str, ']') orelse return null;
        return try urlSerializeIPv6(arena, urlParseIPv6(host_str[1..close]) orelse return null);
    }
    if (urlIsSpecialScheme(scheme)) {
        // WHATWG host parser: UTF-8 percent-decode, then domain-to-ASCII (UTS-46
        // mapping + NFC + Punycode, lowercasing ASCII, validating `xn--` labels,
        // rejecting forbidden domain code points). `%C3%A9.com` → `xn--9ca.com`.
        // IPv4 detection then runs on the resulting ASCII domain.
        const decoded = try urlPercentDecode(arena, host_str);
        const domain = (try idna.domainToAscii(arena, decoded)) orelse return null;
        if (urlHostEndsInNumber(domain)) return (try urlParseIPv4(arena, domain)) orelse return null;
        return domain;
    }
    var hb: std.ArrayListUnmanaged(u8) = .empty;
    try urlPercentEncode(arena, &hb, host_str, .c0);
    return hb.items;
}
fn urlParsePathQueryFrag(arena: std.mem.Allocator, p: *UrlParts, s_in: []const u8, special: bool, has_host: bool) EvalError!void {
    var s = s_in;
    // Fragment
    if (std.mem.indexOfScalar(u8, s, '#')) |h| {
        var fb: std.ArrayListUnmanaged(u8) = .empty;
        try urlPercentEncode(arena, &fb, s[h + 1 ..], .fragment);
        p.fragment = fb.items;
        s = s[0..h];
    }
    // Query
    if (std.mem.indexOfScalar(u8, s, '?')) |q| {
        var qb: std.ArrayListUnmanaged(u8) = .empty;
        try urlPercentEncode(arena, &qb, s[q + 1 ..], if (special) .special_query else .query);
        p.query = qb.items;
        s = s[0..q];
    }
    // Path
    var pb: std.ArrayListUnmanaged(u8) = .empty;
    if (has_host or special or std.mem.startsWith(u8, s, "/")) {
        // Path-absolute: normalize segments (resolve '.' and '..').
        try urlEncodeNormalizePath(arena, &pb, s, special);
    } else {
        // Opaque path: percent-encode with the C0 set, no normalization.
        try urlPercentEncode(arena, &pb, s, .c0);
    }
    p.path = pb.items;
}
fn urlEncodeNormalizePath(arena: std.mem.Allocator, out: *std.ArrayListUnmanaged(u8), s: []const u8, special: bool) EvalError!void {
    var segs: std.ArrayListUnmanaged([]const u8) = .empty;
    var body = s;
    // A special scheme treats '\' as '/'.
    var norm: std.ArrayListUnmanaged(u8) = .empty;
    if (special) {
        for (body) |c| try norm.append(arena, if (c == '\\') '/' else c);
        body = norm.items;
    }
    if (body.len == 0 or body[0] != '/') {
        // ensure leading slash context handled by caller; here split on '/'
    }
    var it = std.mem.splitScalar(u8, body, '/');
    // The first split piece before a leading '/' is empty — skip it.
    var first = true;
    while (it.next()) |seg| {
        const is_last = it.peek() == null;
        if (first) {
            first = false;
            if (seg.len == 0) continue; // leading slash
        }
        if (std.mem.eql(u8, seg, ".") or std.ascii.eqlIgnoreCase(seg, "%2e")) {
            // A terminal "." leaves a trailing slash (empty final segment).
            if (is_last) try segs.append(arena, "");
            continue;
        }
        if (std.mem.eql(u8, seg, "..") or std.ascii.eqlIgnoreCase(seg, "%2e%2e") or std.ascii.eqlIgnoreCase(seg, ".%2e") or std.ascii.eqlIgnoreCase(seg, "%2e.")) {
            if (segs.items.len > 0) _ = segs.pop();
            if (is_last) try segs.append(arena, "");
            continue;
        }
        var eb: std.ArrayListUnmanaged(u8) = .empty;
        try urlPercentEncode(arena, &eb, seg, .path);
        try segs.append(arena, eb.items);
    }
    for (segs.items) |seg| {
        try out.append(arena, '/');
        try out.appendSlice(arena, seg);
    }
    // A special scheme defaults an empty path to "/"; a non-special scheme with
    // an authority keeps an empty path empty ("custom://h" → pathname "").
    if (out.items.len == 0 and (special or s.len > 0)) try out.append(arena, '/');
