    try urlStore(self, obj, parts);
    if (self.env.get("URLSearchParams")) |uspc| if (uspc.isObject()) {
        const sp = try self.construct(uspc, &.{if (parts.query) |q| try Value.strAlloc(self.arena, q) else Value.str("")});
        try obj.setOwn(self.arena, self.root_shape, "\x00Usp", sp);
        if (sp.isObject()) try sp.asObj().setOwn(self.arena, self.root_shape, "\x00Uspurl", Value.obj(obj));
    };
    return Value.obj(obj);
}
fn urlGetter(comptime which: []const u8) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            _ = args;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            if (!this.isObject()) return self.throwError("TypeError", "URL getter on non-object");
            const o = this.asObj();
            const p = urlLoad(o);
            if (std.mem.eql(u8, which, "searchParams")) return o.getOwn("\x00Usp") orelse Value.undef();
            const s: []const u8 = blk: {
                if (std.mem.eql(u8, which, "href")) break :blk try urlSerialize(self.arena, p, false);
                if (std.mem.eql(u8, which, "protocol")) break :blk try std.mem.concat(self.arena, u8, &.{ p.scheme, ":" });
                if (std.mem.eql(u8, which, "username")) break :blk p.username;
                if (std.mem.eql(u8, which, "password")) break :blk p.password;
                if (std.mem.eql(u8, which, "hostname")) break :blk (p.host orelse "");
                if (std.mem.eql(u8, which, "port")) break :blk p.port;
                if (std.mem.eql(u8, which, "pathname")) break :blk p.path;
                if (std.mem.eql(u8, which, "host")) {
                    if (p.host) |h| {
                        if (p.port.len > 0) break :blk try std.mem.concat(self.arena, u8, &.{ h, ":", p.port });
                        break :blk h;
                    }
                    break :blk "";
                }
                if (std.mem.eql(u8, which, "search")) break :blk if (p.query) |q| (if (q.len == 0) "" else try std.mem.concat(self.arena, u8, &.{ "?", q })) else "";
                if (std.mem.eql(u8, which, "hash")) break :blk if (p.fragment) |f| (if (f.len == 0) "" else try std.mem.concat(self.arena, u8, &.{ "#", f })) else "";
                if (std.mem.eql(u8, which, "origin")) break :blk try urlOrigin(self.arena, p);
                break :blk "";
            };
            return try Value.strAlloc(self.arena, s);
        }
    }.call;
}
fn urlHashSetFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return Value.undef();
    var p = urlLoad(this.asObj());
    var v = try self.toStringWtf8(if (args.len > 0) args[0] else Value.undef());
    if (v.len > 0 and v[0] == '#') v = v[1..];
    if (v.len == 0) {
        p.fragment = null;
    } else {
        var fb: std.ArrayListUnmanaged(u8) = .empty;
        try urlPercentEncode(self.arena, &fb, v, .fragment);
        p.fragment = fb.items;
    }
    try urlStore(self, this.asObj(), p);
    return Value.undef();
}
fn urlToStringFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return self.throwError("TypeError", "URL.toString on non-object");
    return try Value.strAlloc(self.arena, try urlSerialize(self.arena, urlLoad(this.asObj()), false));
}
/// Re-seed the URL's live `.searchParams` pairs from a new query string (identity
/// of the URLSearchParams object is preserved).
fn urlRefreshSearchParams(self: *Interpreter, o: *value.Object, query: ?[]const u8) EvalError!void {
    const spv = o.getOwn("\x00Usp") orelse return;
    if (!spv.isObject()) return;
    const pairs = (try self.newArray()).asObj();
    if (query) |q| try uspParseString(self, pairs, q);
    try spv.asObj().setOwn(self.arena, self.root_shape, "\x00usp", Value.obj(pairs));
}
/// The `href`/`protocol`/`username`/`password`/`host`/`hostname`/`port`/
/// `pathname`/`search` setters (basic-URL-parse with a state override, per WHATWG).
fn urlSetter(comptime which: []const u8) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            if (!this.isObject()) return Value.undef();
            const o = this.asObj();
            var p = urlLoad(o);
            const val = try self.toStringWtf8(if (args.len > 0) args[0] else Value.undef());
            const special = urlIsSpecialScheme(p.scheme);
            const enc = struct {
                fn f(s: *Interpreter, in: []const u8, set: UrlEncSet) EvalError![]const u8 {
                    var b: std.ArrayListUnmanaged(u8) = .empty;
                    try urlPercentEncode(s.arena, &b, in, set);
                    return b.items;
                }
            }.f;
            if (comptime std.mem.eql(u8, which, "href")) {
                const np = (try urlParse(self.arena, val, null)) orelse return self.throwError("TypeError", "Invalid URL");
                try urlStore(self, o, np);
                try urlRefreshSearchParams(self, o, np.query);
                return Value.undef();
            }
            if (comptime std.mem.eql(u8, which, "protocol")) {
                var s = val;
                if (s.len > 0 and s[s.len - 1] == ':') s = s[0 .. s.len - 1];
                if (s.len == 0 or !std.ascii.isAlphabetic(s[0])) return Value.undef();
                var sb: std.ArrayListUnmanaged(u8) = .empty;
                for (s) |c| {
                    if (!(std.ascii.isAlphanumeric(c) or c == '+' or c == '-' or c == '.')) return Value.undef();
                    try sb.append(self.arena, std.ascii.toLower(c));
                }
                // WHATWG forbids toggling the special/non-special class of a scheme.
                if (urlIsSpecialScheme(sb.items) != special) return Value.undef();
                p.scheme = sb.items;
                try urlStore(self, o, p);
                return Value.undef();
            }
            // The authority-bearing setters are inert on a host-less/opaque URL.
            const authority_setter = comptime (std.mem.eql(u8, which, "username") or std.mem.eql(u8, which, "password") or
                std.mem.eql(u8, which, "host") or std.mem.eql(u8, which, "hostname") or std.mem.eql(u8, which, "port"));
            if (authority_setter and (p.host == null or p.opaque_path)) return Value.undef();
            if (comptime std.mem.eql(u8, which, "username")) {
                p.username = try enc(self, val, .userinfo);
            } else if (comptime std.mem.eql(u8, which, "password")) {
                p.password = try enc(self, val, .userinfo);
            } else if (comptime std.mem.eql(u8, which, "port")) {
                if (val.len == 0) {
                    p.port = "";
                } else {
                    var end: usize = 0;
                    while (end < val.len and std.ascii.isDigit(val[end])) end += 1;
                    if (end == 0) return Value.undef();
                    p.port = (try urlNormalizePort(self.arena, p.scheme, val[0..end])) orelse return Value.undef();
                }
            } else if (comptime std.mem.eql(u8, which, "hostname")) {
                if (val.len == 0 and special) return Value.undef();
                p.host = if (val.len == 0) "" else (try urlCanonHost(self.arena, p.scheme, val)) orelse return Value.undef();
            } else if (comptime std.mem.eql(u8, which, "host")) {
                var hs = val;
                var new_port: ?[]const u8 = null;
                if (hs.len > 0 and hs[0] == '[') {
                    const close = std.mem.indexOfScalar(u8, hs, ']') orelse return Value.undef();
                    const tail = hs[close + 1 ..];
                    if (tail.len > 0 and tail[0] == ':') new_port = (try urlNormalizePort(self.arena, p.scheme, tail[1..])) orelse return Value.undef();
                    hs = hs[0 .. close + 1];
                } else if (std.mem.lastIndexOfScalar(u8, hs, ':')) |colon| {
                    new_port = (try urlNormalizePort(self.arena, p.scheme, hs[colon + 1 ..])) orelse return Value.undef();
                    hs = hs[0..colon];
                }
                if (hs.len == 0 and special) return Value.undef();
                p.host = (try urlCanonHost(self.arena, p.scheme, hs)) orelse return Value.undef();
                if (new_port) |np| p.port = np;
            } else if (comptime std.mem.eql(u8, which, "pathname")) {
                if (p.opaque_path) return Value.undef();
                var pb: std.ArrayListUnmanaged(u8) = .empty;
                try urlEncodeNormalizePath(self.arena, &pb, val, special);
                p.path = pb.items;
            } else if (comptime std.mem.eql(u8, which, "search")) {
                var s = val;
                if (s.len > 0 and s[0] == '?') s = s[1..];
                p.query = if (s.len == 0) null else try enc(self, s, if (special) .special_query else .query);
                try urlStore(self, o, p);
                try urlRefreshSearchParams(self, o, p.query);
                return Value.undef();
            }
            try urlStore(self, o, p);
            return Value.undef();
        }
    }.call;
}
fn urlCanParseFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const input = try self.toStringWtf8(if (args.len > 0) args[0] else Value.undef());
    var base: ?UrlParts = null;
    if (args.len > 1 and !args[1].isUndefined()) {
        base = (try urlParse(self.arena, try self.toStringWtf8(args[1]), null)) orelse return Value.boolVal(false);
    }
    return Value.boolVal((try urlParse(self.arena, input, base)) != null);
}

// ===== process EventEmitter =========================================
// Bun's private process/rejection ABI dispatches through the realm's process
// object. Keep the listener graph in hidden JS-owned slots so callbacks remain
// precise-GC roots and every realm gets an isolated emitter. Listener records
// contain the normalized event key, callback, and once flag.
fn processIsProcess(v: Value) bool {
    return v.isObject() and evBool(v.asObj(), "#processBrand\x00runtime");
}

fn processListeners(self: *Interpreter, process_obj: *value.Object) EvalError!*value.Object {
    if (process_obj.getOwn("#processListeners\x00runtime")) |v| if (v.isObject()) return v.asObj();
    const listeners = (try self.newArray()).asObj();
    try process_obj.setOwn(self.arena, self.root_shape, "#processListeners\x00runtime", Value.obj(listeners));
    return listeners;
}

fn processEventKey(self: *Interpreter, event: Value) EvalError!Value {
    return Value.strOwned(self.arena, try self.arena.dupe(u8, try self.keyOf(event)));
}

fn processListenerMatches(rec: Value, event_key: Value, listener: ?Value) bool {
    if (!rec.isObject()) return false;
    const ro = rec.asObj();
    const rk = ro.getOwn("#processEvent\x00runtime") orelse return false;
    if (!value.strictEquals(rk, event_key)) return false;
    if (listener) |wanted| {
        const callback = ro.getOwn("#processCallback\x00runtime") orelse return false;
        return value.strictEquals(callback, wanted);
    }
    return true;
}

fn processRemoveRecord(self: *Interpreter, process_obj: *value.Object, record: *value.Object) EvalError!void {
    const listeners = try processListeners(self, process_obj);
    const fresh = (try self.newArray()).asObj();
    for (try listeners.internalElementsSnapshot(self.arena)) |rec| {
        if (rec.isObject() and rec.asObj() == record) continue;
        try fresh.appendElement(self.arena, rec);
    }
    try process_obj.setOwn(self.arena, self.root_shape, "#processListeners\x00runtime", Value.obj(fresh));
}

fn processAddListener(self: *Interpreter, this: Value, args: []const Value, once: bool) value.HostError!Value {
    if (!processIsProcess(this)) return self.throwError("TypeError", "process EventEmitter method called on an incompatible receiver");
    const event_key = try processEventKey(self, arg(args, 0));
    const listener = arg(args, 1);
    if (!listener.isObject() or !listener.asObj().isCallableObject())
        return self.throwError("TypeError", "The \"listener\" argument must be a function");

    const record = try gc_mod.allocObj(self.arena);
    record.* = .{};
    try record.setOwn(self.arena, self.root_shape, "#processEvent\x00runtime", event_key);
    try record.setOwn(self.arena, self.root_shape, "#processCallback\x00runtime", listener);
    try record.setOwn(self.arena, self.root_shape, "#processOnce\x00runtime", Value.boolVal(once));
    try (try processListeners(self, this.asObj())).appendElement(self.arena, Value.obj(record));
    return this;
}

fn processOnFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    return processAddListener(self, this, args, false);
}

fn processOnceFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    return processAddListener(self, this, args, true);
}

fn processRemoveListenerFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!processIsProcess(this)) return self.throwError("TypeError", "process EventEmitter method called on an incompatible receiver");
    const event_key = try processEventKey(self, arg(args, 0));
    const listener = arg(args, 1);
    if (!listener.isObject() or !listener.asObj().isCallableObject())
        return self.throwError("TypeError", "The \"listener\" argument must be a function");

    const listeners = try processListeners(self, this.asObj());
    const snapshot = try listeners.internalElementsSnapshot(self.arena);
    var remove_index: ?usize = null;
    var i = snapshot.len;
    while (i > 0) {
        i -= 1;
        if (processListenerMatches(snapshot[i], event_key, listener)) {
            remove_index = i;
            break;
        }
    }
    if (remove_index) |drop| {
        const fresh = (try self.newArray()).asObj();
        for (snapshot, 0..) |rec, index| if (index != drop) try fresh.appendElement(self.arena, rec);
        try this.asObj().setOwn(self.arena, self.root_shape, "#processListeners\x00runtime", Value.obj(fresh));
    }
    return this;
}

fn processListenerCountFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!processIsProcess(this)) return self.throwError("TypeError", "process EventEmitter method called on an incompatible receiver");
    const event_key = try processEventKey(self, arg(args, 0));
    const listener: ?Value = if (args.len > 1) args[1] else null;
    if (listener) |candidate| if (!candidate.isObject() or !candidate.asObj().isCallableObject())
        return Value.num(0);
    var count: usize = 0;
    for (try (try processListeners(self, this.asObj())).internalElementsSnapshot(self.arena)) |rec| {
        if (processListenerMatches(rec, event_key, listener)) count += 1;
    }
    return Value.num(@floatFromInt(count));
}

fn processEmitFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!processIsProcess(this)) return self.throwError("TypeError", "process EventEmitter method called on an incompatible receiver");
    const event_key = try processEventKey(self, arg(args, 0));
    const snapshot = try (try processListeners(self, this.asObj())).internalElementsSnapshot(self.arena);
    var emitted = false;
    for (snapshot) |rec| {
        if (!processListenerMatches(rec, event_key, null)) continue;
        emitted = true;
        const ro = rec.asObj();
        if (evBool(ro, "#processOnce\x00runtime")) try processRemoveRecord(self, this.asObj(), ro);
        const callback = ro.getOwn("#processCallback\x00runtime") orelse continue;
        _ = try self.callValueWithThis(callback, if (args.len > 1) args[1..] else &.{}, this);
    }
    if (!emitted and event_key.isString() and std.mem.eql(u8, event_key.asStr(), "error")) {
        const reason = arg(args, 1);
        if (reason.isObject() and reason.asObj().behavior.is_error) {
            self.exception = reason;
            try self.notifyDebuggerException(false);
            return error.Throw;
        }
        const err = try self.makeError("Error", "Unhandled 'error' event");
        if (!reason.isUndefined()) try err.asObj().setOwn(self.arena, self.root_shape, "context", reason);
        self.exception = err;
        try self.notifyDebuggerException(false);
        return error.Throw;
    }
    return Value.boolVal(emitted);
}

fn processWarningJobFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const job = self.active_native orelse return Value.undef();
    const warning = job.getOwn("#processWarning\x00runtime") orelse return Value.undef();
    const process_obj = self.env.get("process") orelse return Value.undef();
    return processEmitFn(self, process_obj, &.{ Value.str("warning"), warning });
}

fn processNextTickFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const callback = arg(args, 0);
    if (!callback.isCallable())
        return self.throwError("TypeError", "The \"callback\" argument must be a function");
    const process_obj = self.env.get("process") orelse return Value.undef();
    if ((process_obj.asObj().getOwn("_exiting") orelse Value.boolVal(false)).toBoolean())
        return Value.undef();
    try promise.enqueueNextTick(self, callback, if (args.len > 1) args[1..] else &.{});
    return Value.undef();
}

/// Queue one process `warning` turn. Bun implements warning delivery through
/// process.nextTick, so it shares the distinct next-tick FIFO and runs before
/// Promise jobs at the next host checkpoint.
pub fn enqueueProcessWarning(self: *Interpreter, warning: Value) EvalError!void {
    const job = try gc_mod.allocObj(self.arena);
    job.* = .{ .native = processWarningJobFn };
    try job.setOwn(self.arena, self.root_shape, "#processWarning\x00runtime", warning);
    try promise.enqueueNextTick(self, Value.obj(job), &.{});
}

/// Dispatch a realm process event synchronously through the same EventEmitter
/// path used by JavaScript. The return value reports whether listeners ran.
pub fn emitProcessEvent(self: *Interpreter, event: []const u8, args: []const Value) EvalError!bool {
    const process_obj = self.env.get("process") orelse return false;
    var call_args = try self.arena.alloc(Value, args.len + 1);
    call_args[0] = try Value.strAlloc(self.arena, event);
    @memcpy(call_args[1..], args);
    return (try processEmitFn(self, process_obj, call_args)).toBoolean();
}

pub fn processEventListenerCount(self: *Interpreter, event: []const u8) EvalError!usize {
    const process_obj = self.env.get("process") orelse return 0;
    const result = try processListenerCountFn(self, process_obj, &.{try Value.strAlloc(self.arena, event)});
    return @intFromFloat(result.asNum());
}

/// Shared fatal-dispatch policy used by the private C ABI and process.nextTick.
/// The monitor observes first, a capture callback takes precedence over the
/// ordinary event, and the return value says whether userland handled it.
pub fn handleProcessUncaughtException(self: *Interpreter, thrown: Value, is_rejection: bool) EvalError!bool {
    const origin = if (is_rejection) Value.str("unhandledRejection") else Value.str("uncaughtException");
    const event_args = [_]Value{ thrown, origin };
    if (try processEventListenerCount(self, "uncaughtExceptionMonitor") != 0)
        _ = try emitProcessEvent(self, "uncaughtExceptionMonitor", &event_args);
    if (processCaptureCallback(self)) |capture| {
        _ = try self.callValueWithThis(capture, &event_args, Value.undef());
        return true;
    }
    if (try processEventListenerCount(self, "uncaughtException") == 0) return false;
    _ = try emitProcessEvent(self, "uncaughtException", &event_args);
    return true;
}

/// The realm's uncaught-exception capture callback, if one is installed.
pub fn processCaptureCallback(self: *Interpreter) ?Value {
    const process_obj = self.env.get("process") orelse return null;
    if (!processIsProcess(process_obj)) return null;
    const callback = process_obj.asObj().getOwn("#processCapture\x00runtime") orelse return null;
    if (!callback.isObject() or !callback.asObj().isCallableObject()) return null;
    return callback;
}

fn processSetCaptureCallbackFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!processIsProcess(this)) return self.throwError("TypeError", "process EventEmitter method called on an incompatible receiver");
    const callback = arg(args, 0);
    if (!callback.isNull() and (!callback.isObject() or !callback.asObj().isCallableObject()))
        return self.throwError("TypeError", "The \"fn\" argument must be a function or null");
    try this.asObj().setOwn(self.arena, self.root_shape, "#processCapture\x00runtime", callback);
    return Value.undef();
}

fn processHasCaptureCallbackFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!processIsProcess(this)) return self.throwError("TypeError", "process EventEmitter method called on an incompatible receiver");
    const callback = this.asObj().getOwn("#processCapture\x00runtime") orelse Value.nul();
    return Value.boolVal(callback.isObject() and callback.asObj().isCallableObject());
}

fn installProcess(env: *Environment, rs: *Shape, object_proto: *value.Object) EvalError!void {
    const a = env.arena;
    const process_obj = try gc_mod.allocObj(a);
    process_obj.* = .{ .proto = object_proto };
    try process_obj.setOwn(a, rs, "#processBrand\x00runtime", Value.boolVal(true));
    try process_obj.setOwn(a, rs, "#processCapture\x00runtime", Value.nul());

    try setNative(a, rs, process_obj, "on", 2, processOnFn);
    try setNative(a, rs, process_obj, "once", 2, processOnceFn);
    try setNative(a, rs, process_obj, "removeListener", 2, processRemoveListenerFn);
    try setNative(a, rs, process_obj, "listenerCount", 1, processListenerCountFn);
    try setNative(a, rs, process_obj, "emit", 1, processEmitFn);
    try setNative(a, rs, process_obj, "nextTick", 1, processNextTickFn);
    try setNative(a, rs, process_obj, "setUncaughtExceptionCaptureCallback", 1, processSetCaptureCallbackFn);
    try setNative(a, rs, process_obj, "hasUncaughtExceptionCaptureCallback", 0, processHasCaptureCallbackFn);

    const on = process_obj.getOwn("on").?;
    try process_obj.setOwn(a, rs, "addListener", on);
    try process_obj.setAttr(a, "addListener", .{ .enumerable = false, .configurable = true, .writable = true });
    const remove_listener = process_obj.getOwn("removeListener").?;
    try process_obj.setOwn(a, rs, "off", remove_listener);
    try process_obj.setAttr(a, "off", .{ .enumerable = false, .configurable = true, .writable = true });

    if (env.get("Symbol")) |symbol| if (symbol.isObject()) {
        if (symbol.asObj().getOwn("toStringTag")) |tag| if (tag.isObject() and tag.asObj().is_symbol) {
            try process_obj.setOwn(a, rs, tag.asObj().symbolKey(), Value.str("process"));
            try process_obj.setAttr(a, tag.asObj().symbolKey(), .{ .writable = false, .enumerable = false, .configurable = true });
        };
    };
    try env.put("process", Value.obj(process_obj));
}

// ===== Event / EventTarget (DOM Events, tree-less flat model) =========
// An Event carries its state in hidden slots: \x00Et type, \x00Eb/Ec/Eo bubbles/
// cancelable/composed, \x00Ed defaultPrevented, \x00Esp/Esi stop(-immediate)
// flags, \x00Edf dispatch-in-progress, \x00Etg/Ect target/currentTarget,
// \x00Ets timeStamp, \x00Eit isTrusted. An EventTarget keeps its listener
// records in the \x00etl array; each record is an object with \x00Lt type,
// \x00Lc callback, \x00Lcap capture, \x00Lonce once.
fn evBool(o: *value.Object, k: []const u8) bool {
    if (o.getOwn(k)) |v| return v.toBoolean();
    return false;
}
fn evIsEvent(v: Value) bool {
    return v.isObject() and v.asObj().getOwn("\x00Et") != null;
}
