        if (!callback.isObject()) continue;
        if (callback.asObj().native == abortOnabortDispatchFn) continue;
        return true;
    }
    return false;
}

fn refreshAbortSignalJsObservation(self: *Interpreter, sig: *value.Object) EvalError!void {
    const native = abortSignalNativeState(sig) orelse return;
    const update = native.set_js_observed orelse return;
    if (!update(native, try abortSignalHasJsObservation(self, sig))) return error.OutOfMemory;
}

pub fn makeAbortSignal(self: *Interpreter) EvalError!*value.Object {
    const sig = try gc_mod.allocObj(self.arena);
    sig.* = .{};
    sig.behavior.is_abort_signal = true;
    if (self.env.get("AbortSignal")) |c| if (c.isObject()) {
        if (c.asObj().getOwn("prototype")) |pp| if (pp.isObject()) sig.setProtoAtomic(pp.asObj());
    };
    const rs = self.root_shape;
    try sig.setOwn(self.arena, rs, "\x00ASsig", Value.boolVal(true));
    try sig.setOwn(self.arena, rs, "\x00ASaborted", Value.boolVal(false));
    try sig.setOwn(self.arena, rs, "\x00ASreason", Value.undef());
    return sig;
}
fn dispatchNamedEvent(self: *Interpreter, target: *value.Object, name: []const u8) EvalError!void {
    const ev = try gc_mod.allocObj(self.arena);
    ev.* = .{};
    if (self.env.get("Event")) |c| if (c.isObject()) {
        if (c.asObj().getOwn("prototype")) |pp| if (pp.isObject()) ev.setProtoAtomic(pp.asObj());
    };
    const rs = self.root_shape;
    try ev.setOwn(self.arena, rs, "\x00Et", try Value.strAlloc(self.arena, name));
    try ev.setOwn(self.arena, rs, "\x00Eb", Value.boolVal(false));
    try ev.setOwn(self.arena, rs, "\x00Ec", Value.boolVal(false));
    try ev.setOwn(self.arena, rs, "\x00Eo", Value.boolVal(false));
    try ev.setOwn(self.arena, rs, "\x00Ed", Value.boolVal(false));
    try ev.setOwn(self.arena, rs, "\x00Etg", Value.nul());
    try ev.setOwn(self.arena, rs, "\x00Ect", Value.nul());
    try ev.setOwn(self.arena, rs, "\x00Ets", Value.num(0));
    _ = try etDispatchFn(self, Value.obj(target), &.{Value.obj(ev)});
}
fn markAbortSignal(self: *Interpreter, sig: *value.Object, reason: Value, ordered: *std.ArrayListUnmanaged(*value.Object)) EvalError!void {
    if (evBool(sig, "\x00ASaborted")) return;
    try sig.setOwn(self.arena, self.root_shape, "\x00ASreason", reason);
    try sig.setOwn(self.arena, self.root_shape, "\x00ASaborted", Value.boolVal(true));
    try ordered.append(self.arena, sig);
    if (sig.getOwn("\x00ASdeps")) |dv| if (dv.isObject()) {
        for (try dv.asObj().internalElementsSnapshot(self.arena)) |dep| {
            if (dep.isObject()) try markAbortSignal(self, dep.asObj(), reason, ordered);
        }
    };
}

fn runAbortSignalSteps(self: *Interpreter, sig: *value.Object, reason: Value) EvalError!void {
    if (abortSignalNativeState(sig)) |native| {
        if (native.cancel_timeout) |cancel| cancel(native);
        if (native.run_abort_steps) |run| run(native.owner, reason);
    }
    // Remove listeners that were added with this signal (addEventListener signal
    // option) before firing, so they do not run for the abort event.
    if (sig.getOwn("\x00ASremovals")) |rv| if (rv.isObject()) {
        for (try rv.asObj().internalElementsSnapshot(self.arena)) |e| {
            if (!e.isObject()) continue;
            const tgt = e.asObj().getOwn("\x00SRtgt") orelse continue;
            const rec = e.asObj().getOwn("\x00SRrec") orelse continue;
            if (tgt.isObject() and rec.isObject()) try etRemoveRecord(self, tgt.asObj(), rec.asObj());
        }
    };
    try dispatchNamedEvent(self, sig, "abort");
}

pub fn signalAbort(self: *Interpreter, sig: *value.Object, reason: Value) EvalError!void {
    if (!sig.behavior.is_abort_signal or evBool(sig, "\x00ASaborted")) return;
    const r = if (reason.isUndefined()) try self.makeDOMException("AbortError", "This operation was aborted") else reason;
    var ordered: std.ArrayListUnmanaged(*value.Object) = .empty;
    try markAbortSignal(self, sig, r, &ordered);
    for (ordered.items) |item| try runAbortSignalSteps(self, item, r);
}

/// DOM's dependent-signal operation for the single-source case used by
/// Request construction and cloning. The dependent is always a fresh signal;
/// an already-aborted source synchronously transfers its exact reason.
fn makeDependentAbortSignal(self: *Interpreter, source: ?*value.Object) EvalError!*value.Object {
    const dependent = try makeAbortSignal(self);
    const parent = source orelse return dependent;
    if (abortSignalAborted(parent)) {
        try signalAbort(self, dependent, abortSignalReason(parent));
        return dependent;
    }
    const deps: *value.Object = blk: {
        if (parent.getOwn("\x00ASdeps")) |stored| if (stored.isObject()) break :blk stored.asObj();
        const created = (try self.newArray()).asObj();
        try parent.setOwn(self.arena, self.root_shape, "\x00ASdeps", Value.obj(created));
        break :blk created;
    };
    try deps.appendElement(self.arena, Value.obj(dependent));
    return dependent;
}

pub fn abortSignalAborted(sig: *value.Object) bool {
    return sig.behavior.is_abort_signal and evBool(sig, "\x00ASaborted");
}

pub fn abortSignalReason(sig: *value.Object) Value {
    if (!sig.behavior.is_abort_signal) return Value.undef();
    return sig.getOwn("\x00ASreason") orelse Value.undef();
}
fn abortSignalGetter(comptime which: []const u8) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            _ = args;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            if (!abortIsSignal(this)) return self.throwError("TypeError", "Illegal invocation");
            const o = this.asObj();
            if (comptime std.mem.eql(u8, which, "aborted")) return Value.boolVal(evBool(o, "\x00ASaborted"));
            if (comptime std.mem.eql(u8, which, "reason")) return o.getOwn("\x00ASreason") orelse Value.undef();
            if (comptime std.mem.eql(u8, which, "onabort")) return o.getOwn("\x00onabort") orelse Value.nul();
            return Value.undef();
        }
    }.call;
}
fn abortThrowIfAbortedFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!abortIsSignal(this)) return self.throwError("TypeError", "Illegal invocation");
    if (evBool(this.asObj(), "\x00ASaborted")) {
        self.exception = this.asObj().getOwn("\x00ASreason") orelse Value.undef();
        return error.Throw;
    }
    return Value.undef();
}
fn abortOnabortDispatchFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    // Internal "abort" listener that forwards to the current onabort handler.
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return Value.undef();
    const h = this.asObj().getOwn("\x00onabort") orelse return Value.undef();
    if (!h.isObject() or !h.asObj().isCallableObject()) return Value.undef();
    _ = try self.callValueWithThis(h, &.{if (args.len > 0) args[0] else Value.undef()}, this);
    return Value.undef();
}
fn abortOnabortSetFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!abortIsSignal(this)) return self.throwError("TypeError", "Illegal invocation");
    const o = this.asObj();
    const v = if (args.len > 0) args[0] else Value.undef();
    try o.setOwn(self.arena, self.root_shape, "\x00onabort", v);
    // Register the internal forwarding listener once, at first assignment, so it
    // occupies the correct position relative to addEventListener listeners.
    if (!evBool(o, "\x00ASob")) {
        try o.setOwn(self.arena, self.root_shape, "\x00ASob", Value.boolVal(true));
        const lst = try gc_mod.allocObj(self.arena);
        lst.* = .{ .native = abortOnabortDispatchFn };
        // The forwarding listener reads the handler off the signal via `this`.
        _ = try etAddListenerFn(self, this, &.{ Value.str("abort"), Value.obj(lst) });
        // Rewire the record's callback `this` binding: the internal listener must
        // run with the signal as `this`; etDispatch already passes the target as
        // `this` for function listeners, so no extra wiring is needed.
    }
    try refreshAbortSignalJsObservation(self, o);
    return Value.undef();
}
fn abortSignalConstructorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    return self.throwError("TypeError", "Illegal constructor.");
}
fn abortSignalStaticAbortFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const sig = try makeAbortSignal(self);
    try signalAbort(self, sig, if (args.len > 0) args[0] else Value.undef());
    return Value.obj(sig);
}

fn abortSignalStaticTimeoutFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len == 0) return self.throwError("TypeError", "AbortSignal.timeout requires a delay");
    const numeric = try self.toNumberV(args[0]);
    if (!std.math.isFinite(numeric))
        return self.throwError("TypeError", "AbortSignal.timeout delay must be a finite number");
    const integer = if (numeric == 0) 0 else @trunc(numeric);
    // Web IDL narrows [EnforceRange] 64-bit integers to the unambiguous Number
    // range, rather than accepting imprecise values up to 2^64 - 1.
    if (integer < 0 or integer > 9007199254740991.0)
        return self.throwError("TypeError", "AbortSignal.timeout delay is outside the safe integer range");
    const schedule = self.abort_timeout_schedule orelse
        return self.throwError("NotSupportedError", "AbortSignal.timeout requires a host event loop");
    const sig = try makeAbortSignal(self);
    try schedule(self.abort_timeout_ctx, self, sig, @intFromFloat(integer));
    return Value.obj(sig);
}

fn abortSignalStaticAnyFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const res = try makeAbortSignal(self);
    const sources = try collectIterable(self, if (args.len > 0) args[0] else Value.undef());
    for (sources) |src| {
        if (!abortIsSignal(src)) return self.throwError("TypeError", "AbortSignal.any expects AbortSignal instances");
        if (evBool(src.asObj(), "\x00ASaborted")) {
            try signalAbort(self, res, src.asObj().getOwn("\x00ASreason") orelse Value.undef());
            return Value.obj(res);
        }
    }
    // Register `res` as a dependent of each source: aborting any source aborts
    // `res` with that source's reason (see signalAbort propagation).
    for (sources) |src| {
        const so = src.asObj();
        const deps: *value.Object = blk: {
            if (so.getOwn("\x00ASdeps")) |d| if (d.isObject()) break :blk d.asObj();
            const arr = (try self.newArray()).asObj();
            try so.setOwn(self.arena, self.root_shape, "\x00ASdeps", Value.obj(arr));
            break :blk arr;
        };
        try deps.appendElement(self.arena, Value.obj(res));
    }
    return Value.obj(res);
}
fn abortControllerConstructorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (self.new_target.isUndefined()) return self.throwError("TypeError", "Failed to construct 'AbortController': Please use the 'new' operator");
    const obj = try gc_mod.allocObj(self.arena);
    obj.* = .{};
    if (self.env.get("AbortController")) |c| if (c.isObject()) {
        if (c.asObj().getOwn("prototype")) |pp| if (pp.isObject()) obj.setProtoAtomic(pp.asObj());
    };
    const sig = try makeAbortSignal(self);
    try obj.setOwn(self.arena, self.root_shape, "\x00ACsig", Value.obj(sig));
    return Value.obj(obj);
}
fn abortControllerSignalGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return self.throwError("TypeError", "Illegal invocation");
    return this.asObj().getOwn("\x00ACsig") orelse Value.undef();
}
fn abortControllerAbortFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return self.throwError("TypeError", "Illegal invocation");
    const sigv = this.asObj().getOwn("\x00ACsig") orelse return Value.undef();
    if (sigv.isObject()) try signalAbort(self, sigv.asObj(), if (args.len > 0) args[0] else Value.undef());
    return Value.undef();
}
fn installAbort(env: *Environment, rs: *Shape, object_proto: *value.Object) EvalError!void {
    const a = env.arena;
    const symKey = struct {
        fn f(e: *Environment, name: []const u8) ?[]const u8 {
            if (e.get("Symbol")) |s| if (s.isObject()) {
                if (s.asObj().getOwn(name)) |t| if (t.isObject() and t.asObj().is_symbol) return t.asObj().symbolKey();
            };
            return null;
        }
    }.f;
    // AbortSignal.prototype chains to EventTarget.prototype.
    const et_proto: *value.Object = blk: {
        if (env.get("EventTarget")) |c| if (c.isObject()) {
            if (c.asObj().getOwn("prototype")) |pp| if (pp.isObject()) break :blk pp.asObj();
        };
        break :blk object_proto;
    };
    const sig_proto = try gc_mod.allocObj(a);
    sig_proto.* = .{ .proto = et_proto };
    inline for (.{ "aborted", "reason" }) |g| {
        try setNativeGetter(a, rs, sig_proto, g, abortSignalGetter(g));
        try sig_proto.setAttr(a, g, .{ .enumerable = true, .configurable = true });
    }
    // onabort is a read/write event-handler attribute.
    {
        const getter = try gc_mod.allocObj(a);
        getter.* = .{ .native = abortSignalGetter("onabort") };
        try installNativeProps(a, rs, getter, "get onabort", 0);
        const setter = try gc_mod.allocObj(a);
        setter.* = .{ .native = abortOnabortSetFn };
        try installNativeProps(a, rs, setter, "set onabort", 1);
        try sig_proto.setAccessor(a, "onabort", Value.obj(getter), Value.obj(setter));
        try sig_proto.setAttr(a, "onabort", .{ .enumerable = true, .configurable = true });
    }
    try setNative(a, rs, sig_proto, "throwIfAborted", 0, abortThrowIfAbortedFn);
    if (symKey(env, "toStringTag")) |k| {
        try sig_proto.setOwn(a, rs, k, Value.str("AbortSignal"));
        try sig_proto.setAttr(a, k, .{ .writable = false, .enumerable = false, .configurable = true });
    }
    const sig_ctor = try gc_mod.allocObj(a);
    sig_ctor.* = .{ .native = abortSignalConstructorFn, .native_ctor = true };
    try installNativeProps(a, rs, sig_ctor, "AbortSignal", 0);
    try sig_ctor.setOwn(a, rs, "prototype", Value.obj(sig_proto));
    try sig_ctor.setAttr(a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
    try setConstructor(a, rs, sig_proto, sig_ctor);
    try setNative(a, rs, sig_ctor, "abort", 1, abortSignalStaticAbortFn);
    try setNative(a, rs, sig_ctor, "timeout", 1, abortSignalStaticTimeoutFn);
    try setNative(a, rs, sig_ctor, "any", 1, abortSignalStaticAnyFn);
    try env.put("AbortSignal", Value.obj(sig_ctor));

    // AbortController.
    const ac_proto = try gc_mod.allocObj(a);
    ac_proto.* = .{ .proto = object_proto };
    try setNativeGetter(a, rs, ac_proto, "signal", abortControllerSignalGet);
    try ac_proto.setAttr(a, "signal", .{ .enumerable = true, .configurable = true });
    try setNative(a, rs, ac_proto, "abort", 0, abortControllerAbortFn);
    if (symKey(env, "toStringTag")) |k| {
        try ac_proto.setOwn(a, rs, k, Value.str("AbortController"));
        try ac_proto.setAttr(a, k, .{ .writable = false, .enumerable = false, .configurable = true });
    }
    const ac_ctor = try gc_mod.allocObj(a);
    ac_ctor.* = .{ .native = abortControllerConstructorFn, .native_ctor = true };
    try installNativeProps(a, rs, ac_ctor, "AbortController", 0);
    try ac_ctor.setOwn(a, rs, "prototype", Value.obj(ac_proto));
    try ac_ctor.setAttr(a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
    try setConstructor(a, rs, ac_proto, ac_ctor);
    try env.put("AbortController", Value.obj(ac_ctor));
}

fn installURL(env: *Environment, rs: *Shape, object_proto: *value.Object) EvalError!void {
    const a = env.arena;
    const symKey = struct {
        fn f(e: *Environment, name: []const u8) ?[]const u8 {
            if (e.get("Symbol")) |s| if (s.isObject()) {
                if (s.asObj().getOwn(name)) |t| if (t.isObject() and t.asObj().is_symbol) return t.asObj().symbolKey();
            };
            return null;
        }
    }.f;
    const proto = try gc_mod.allocObj(a);
    proto.* = .{ .proto = object_proto };
    // Read-only accessors.
    inline for (.{ "origin", "searchParams" }) |g| {
        try setNativeGetter(a, rs, proto, g, urlGetter(g));
        try proto.setAttr(a, g, .{ .enumerable = true, .configurable = true });
    }
    // Read/write accessors (getter + component setter).
    const accessor = struct {
        fn f(al: std.mem.Allocator, sh: *Shape, pr: *value.Object, comptime name: []const u8, set: value.NativeFn) EvalError!void {
            const getter = try gc_mod.allocObj(al);
            getter.* = .{ .native = urlGetter(name) };
            try installNativeProps(al, sh, getter, "get " ++ name, 0);
            const setter = try gc_mod.allocObj(al);
            setter.* = .{ .native = set };
            try installNativeProps(al, sh, setter, "set " ++ name, 1);
            try pr.setAccessor(al, name, Value.obj(getter), Value.obj(setter));
            try pr.setAttr(al, name, .{ .enumerable = true, .configurable = true });
        }
    }.f;
    inline for (.{ "href", "protocol", "username", "password", "host", "hostname", "port", "pathname", "search" }) |g| {
        try accessor(a, rs, proto, g, urlSetter(g));
    }
    try accessor(a, rs, proto, "hash", urlHashSetFn);
    try setNative(a, rs, proto, "toString", 0, urlToStringFn);
    try setNative(a, rs, proto, "toJSON", 0, urlToStringFn);
    if (symKey(env, "toStringTag")) |k| {
        try proto.setOwn(a, rs, k, Value.str("URL"));
        try proto.setAttr(a, k, .{ .writable = false, .enumerable = false, .configurable = true });
    }
    const ctor = try gc_mod.allocObj(a);
    ctor.* = .{ .native = urlConstructorFn, .native_ctor = true };
    try installNativeProps(a, rs, ctor, "URL", 1);
    try ctor.setOwn(a, rs, "prototype", Value.obj(proto));
    try ctor.setAttr(a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
    try setConstructor(a, rs, proto, ctor);
    try setNative(a, rs, ctor, "canParse", 1, urlCanParseFn);
    try env.put("URL", Value.obj(ctor));
}

// ===== URLSearchParams (form-urlencoded) =============================
/// application/x-www-form-urlencoded byte: unreserved bytes pass through, space
/// becomes '+', everything else is percent-encoded (uppercase hex).
fn formUrlEncode(self: *Interpreter, s: []const u8) EvalError![]const u8 {
    const utf8 = try wtf8ToUtf8Bytes(self.arena, s);
    const hex = "0123456789ABCDEF";
    var out: std.ArrayListUnmanaged(u8) = .empty;
    for (utf8) |b| {
        if (b == ' ') {
            try out.append(self.arena, '+');
        } else if ((b >= 'A' and b <= 'Z') or (b >= 'a' and b <= 'z') or (b >= '0' and b <= '9') or b == '*' or b == '-' or b == '.' or b == '_') {
            try out.append(self.arena, b);
        } else {
            try out.append(self.arena, '%');
            try out.append(self.arena, hex[b >> 4]);
            try out.append(self.arena, hex[b & 0x0F]);
        }
    }
    return out.items;
}
/// Encoding Standard UTF-8 decoder with replacement. Invalid continuation
/// bytes terminate one pending sequence and are then reprocessed as possible
/// lead bytes, matching the standard's error-token consumption.
fn utf8DecodeReplacing(self: *Interpreter, bytes: []const u8) EvalError![]const u8 {
    var out: std.ArrayListUnmanaged(u8) = .empty;
    var code_point: u32 = 0;
    var bytes_needed: u3 = 0;
    var bytes_seen: u3 = 0;
    var lower_boundary: u8 = 0x80;
    var upper_boundary: u8 = 0xBF;
    var index: usize = 0;
    while (index < bytes.len) {
        const byte = bytes[index];
        if (bytes_needed == 0) {
            if (byte <= 0x7F) {
                try out.append(self.arena, byte);
                index += 1;
            } else if (byte >= 0xC2 and byte <= 0xDF) {
                bytes_needed = 1;
                code_point = byte & 0x1F;
                index += 1;
            } else if (byte >= 0xE0 and byte <= 0xEF) {
                bytes_needed = 2;
                code_point = byte & 0x0F;
                if (byte == 0xE0) lower_boundary = 0xA0;
                if (byte == 0xED) upper_boundary = 0x9F;
                index += 1;
            } else if (byte >= 0xF0 and byte <= 0xF4) {
                bytes_needed = 3;
                code_point = byte & 0x07;
                if (byte == 0xF0) lower_boundary = 0x90;
                if (byte == 0xF4) upper_boundary = 0x8F;
                index += 1;
            } else {
                try out.appendSlice(self.arena, "\u{FFFD}");
                index += 1;
            }
            continue;
        }

        if (byte < lower_boundary or byte > upper_boundary) {
            code_point = 0;
            bytes_needed = 0;
            bytes_seen = 0;
            lower_boundary = 0x80;
            upper_boundary = 0xBF;
            try out.appendSlice(self.arena, "\u{FFFD}");
            continue;
        }

        lower_boundary = 0x80;
        upper_boundary = 0xBF;
        code_point = (code_point << 6) | (byte & 0x3F);
        bytes_seen += 1;
        index += 1;
        if (bytes_seen != bytes_needed) continue;

        var encoded: [4]u8 = undefined;
        const encoded_len = std.unicode.utf8Encode(@intCast(code_point), &encoded) catch unreachable;
        try out.appendSlice(self.arena, encoded[0..encoded_len]);
        code_point = 0;
        bytes_needed = 0;
        bytes_seen = 0;
    }
    if (bytes_needed != 0) try out.appendSlice(self.arena, "\u{FFFD}");
    return out.items;
}

/// application/x-www-form-urlencoded decode: '+' → space, percent-decode,
/// then UTF-8 decode without BOM using replacement semantics.
fn formUrlDecode(self: *Interpreter, s: []const u8) EvalError![]const u8 {
    var out: std.ArrayListUnmanaged(u8) = .empty;
    var i: usize = 0;
    while (i < s.len) {
        const c = s[i];
        if (c == '+') {
            try out.append(self.arena, ' ');
            i += 1;
        } else if (c == '%' and i + 2 < s.len) {
            if (hexDigit(s[i + 1])) |hi| {
                if (hexDigit(s[i + 2])) |lo| {
                    try out.append(self.arena, hi * 16 + lo);
                    i += 3;
                    continue;
                }
            }
            try out.append(self.arena, c);
            i += 1;
        } else {
            try out.append(self.arena, c);
            i += 1;
        }
    }
    return utf8DecodeReplacing(self, out.items);
}
/// The mutable `[[k,v],…]` pairs array backing a URLSearchParams instance.
fn uspPairs(self: *Interpreter, this: Value) EvalError!*value.Object {
    if (this.isObject()) if (this.asObj().getOwn("\x00usp")) |v| if (v.isObject()) return v.asObj();
    return (try self.newArray()).asObj();
}
fn uspPush(self: *Interpreter, pairs: *value.Object, k: []const u8, v: []const u8) EvalError!void {
    const pair = (try self.newArray()).asObj();
    try pair.appendElement(self.arena, try Value.strAlloc(self.arena, k));
    try pair.appendElement(self.arena, try Value.strAlloc(self.arena, v));
    try pairs.appendElement(self.arena, Value.obj(pair));
}
/// Parse `a=1&b=2` (leading `?` stripped) into the pairs array.
fn uspParseString(self: *Interpreter, pairs: *value.Object, input: []const u8) EvalError!void {
    var s = input;
    if (s.len > 0 and s[0] == '?') s = s[1..];
    if (s.len == 0) return;
    var it = std.mem.splitScalar(u8, s, '&');
    while (it.next()) |seg| {
        if (seg.len == 0) continue;
        const eqi = std.mem.indexOfScalar(u8, seg, '=');
        const k = if (eqi) |e| seg[0..e] else seg;
        const v = if (eqi) |e| seg[e + 1 ..] else "";
        try uspPush(self, pairs, try formUrlDecode(self, k), try formUrlDecode(self, v));
    }
}
/// Read a stored `[key, value]` pair back as WTF-8. The pair cells were built
/// by `strAlloc`, so under the flat-string model a latin1 key/value is stored
/// 1-byte/unit; every consumer here byte-compares (`mem.eql`/`mem.order`),
/// percent-encodes (`formUrlEncode`), or rebuilds (`strAlloc`) these bytes as
/// WTF-8, so the read must route through `asWtf8` (no-op when the flag is off).
fn uspPairKV(self: *Interpreter, pair: Value) EvalError!struct { k: []const u8, v: []const u8 } {
    if (!pair.isObject()) return .{ .k = "", .v = "" };
    const kv = pair.asObj();
    const k = if (kv.elementAt(0)) |x| (if (x.isString()) try x.asWtf8(self.arena) else "") else "";
    const v = if (kv.elementAt(1)) |x| (if (x.isString()) try x.asWtf8(self.arena) else "") else "";
    return .{ .k = k, .v = v };
}
const UspAllocation = struct { obj: *value.Object, pairs: *value.Object };
/// Shared instance setup for the JS constructor and the c_api create shim:
/// realm prototype plus the mutable `\x00usp` pairs slot.
fn uspAllocate(self: *Interpreter) EvalError!UspAllocation {
    const obj = try gc_mod.allocObj(self.arena);
    obj.* = .{};
    if (self.env.get("URLSearchParams")) |c| if (c.isObject()) {
        if (c.asObj().getOwn("prototype")) |p| if (p.isObject()) obj.setProtoAtomic(p.asObj());
    };
    const pairs = (try self.newArray()).asObj();
    try obj.setOwn(self.arena, self.root_shape, "\x00usp", Value.obj(pairs));
    return .{ .obj = obj, .pairs = pairs };
}

/// c_api `URLSearchParams__create`: the `new URLSearchParams(string)` path —
/// the form-urlencoded parse strips one leading `?` (WebKit
/// URLSearchParams.cpp semantics), so `?a=1` and `a=1` are equivalent.
pub fn urlSearchParamsCreateFromString(self: *Interpreter, init: []const u8) EvalError!Value {
    const allocation = try uspAllocate(self);
    try uspParseString(self, allocation.pairs, init);
    return Value.obj(allocation.obj);
}

/// c_api `URLSearchParams__toString`: serialize the pairs slot exactly like
/// the JS `toString` method (empty string when the slot is absent).
pub fn urlSearchParamsSerialize(self: *Interpreter, this: Value) EvalError![]const u8 {
    return uspToString(self, this);
}

fn urlSearchParamsConstructorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const allocation = try uspAllocate(self);
    const pairs = allocation.pairs;
    const init = if (args.len > 0) args[0] else Value.undef();
    if (init.isObject() and init.asObj().is_array) {
        for (try init.asObj().internalElementsSnapshot(self.arena)) |entry| {
            if (!entry.isObject()) return self.throwError("TypeError", "URLSearchParams init sequence entry must be a pair");
            const k = try self.toStringWtf8(if (entry.asObj().elementAt(0)) |x| x else Value.undef());
            const v = try self.toStringWtf8(if (entry.asObj().elementAt(1)) |x| x else Value.undef());
            try uspPush(self, pairs, value.decodeStringKey(k), v);
        }
    } else if (init.isObject() and !init.asObj().is_symbol) {
        for (try self.objectOwnKeysList(init.asObj())) |k| {
            if (value.isRealSymbolKey(k) or value.isHiddenInternalKey(k) or value.isPrivateKey(k)) continue;
            if (!objectHasOwn(init.asObj(), k) or !init.asObj().getAttr(k).enumerable) continue;
            const v = try self.toStringWtf8(try self.getProperty(init, k));
            try uspPush(self, pairs, k, v);
        }
    } else if (!init.isUndefined()) {
        try uspParseString(self, pairs, try self.toStringWtf8(init));
    }
    return Value.obj(allocation.obj);
}
fn uspToString(self: *Interpreter, this: Value) EvalError![]const u8 {
    const pairs = try uspPairs(self, this);
    var out: std.ArrayListUnmanaged(u8) = .empty;
    for (try pairs.internalElementsSnapshot(self.arena), 0..) |pair, idx| {
        const kv = try uspPairKV(self, pair);
        if (idx != 0) try out.append(self.arena, '&');
        try out.appendSlice(self.arena, try formUrlEncode(self, kv.k));
        try out.append(self.arena, '=');
        try out.appendSlice(self.arena, try formUrlEncode(self, kv.v));
    }
    return out.items;
}
fn uspGetFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const name = try self.toStringWtf8(if (args.len > 0) args[0] else Value.undef());
    for (try (try uspPairs(self, this)).internalElementsSnapshot(self.arena)) |pair| {
        const kv = try uspPairKV(self, pair);
        if (std.mem.eql(u8, kv.k, name)) return try Value.strAlloc(self.arena, kv.v);
    }
    return Value.nul();
}
fn uspGetAllFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const name = try self.toStringWtf8(if (args.len > 0) args[0] else Value.undef());
    const res = (try self.newArray()).asObj();
    for (try (try uspPairs(self, this)).internalElementsSnapshot(self.arena)) |pair| {
        const kv = try uspPairKV(self, pair);
        if (std.mem.eql(u8, kv.k, name)) try res.appendElement(self.arena, try Value.strAlloc(self.arena, kv.v));
    }
    return Value.obj(res);
}
fn uspHasFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const name = try self.toStringWtf8(if (args.len > 0) args[0] else Value.undef());
    const check_val = args.len > 1 and !args[1].isUndefined();
    const val = if (check_val) try self.toStringWtf8(args[1]) else "";
    for (try (try uspPairs(self, this)).internalElementsSnapshot(self.arena)) |pair| {
        const kv = try uspPairKV(self, pair);
        if (std.mem.eql(u8, kv.k, name) and (!check_val or std.mem.eql(u8, kv.v, val))) return Value.boolVal(true);
    }
    return Value.boolVal(false);
}
fn uspAppendFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const name = try self.toStringWtf8(if (args.len > 0) args[0] else Value.undef());
    const val = try self.toStringWtf8(if (args.len > 1) args[1] else Value.undef());
    try uspPush(self, try uspPairs(self, this), name, val);
    try uspSyncToUrl(self, this);
    return Value.undef();
}
/// When this URLSearchParams is the live `.searchParams` of a URL object (back-
/// ref in `\x00Uspurl`), push its serialized form into the parent's query.
fn uspSyncToUrl(self: *Interpreter, this: Value) EvalError!void {
    if (!this.isObject()) return;
    const urlv = this.asObj().getOwn("\x00Uspurl") orelse return;
    if (!urlv.isObject()) return;
    var p = urlLoad(urlv.asObj());
    const s = try uspToString(self, this);
    p.query = if (s.len == 0) null else s;
    try urlStore(self, urlv.asObj(), p);
}
/// Rebuild the pairs array applying set/delete semantics.
fn uspRebuild(self: *Interpreter, this: Value, name: []const u8, set_value: ?[]const u8, del_value: ?[]const u8) EvalError!void {
    const old = try uspPairs(self, this);
    const fresh = (try self.newArray()).asObj();
    var placed = false;
    for (try old.internalElementsSnapshot(self.arena)) |pair| {
        const kv = try uspPairKV(self, pair);
        if (std.mem.eql(u8, kv.k, name)) {
            if (set_value) |sv| {
                if (!placed) {
                    try uspPush(self, fresh, name, sv);
                    placed = true;
                }
                continue; // drop other matches
            }
            if (del_value) |dv| {
                if (std.mem.eql(u8, kv.v, dv)) continue; // drop this match
            } else continue; // delete all matches
        }
        try fresh.appendElement(self.arena, pair);
    }
    if (set_value != null and !placed) try uspPush(self, fresh, name, set_value.?);
    try this.asObj().setOwn(self.arena, self.root_shape, "\x00usp", Value.obj(fresh));
    try uspSyncToUrl(self, this);
}
fn uspSetFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const name = try self.toStringWtf8(if (args.len > 0) args[0] else Value.undef());
    const val = try self.toStringWtf8(if (args.len > 1) args[1] else Value.undef());
    try uspRebuild(self, this, name, val, null);
    return Value.undef();
}
fn uspDeleteFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const name = try self.toStringWtf8(if (args.len > 0) args[0] else Value.undef());
    const dv: ?[]const u8 = if (args.len > 1 and !args[1].isUndefined()) try self.toStringWtf8(args[1]) else null;
    try uspRebuild(self, this, name, null, dv);
    return Value.undef();
}
fn uspSortFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const pairs = try uspPairs(self, this);
    const items = try pairs.internalElementsSnapshot(self.arena);
    // Precompute each pair's WTF-8 key so the comparator stays allocation-free
    // and total (`asWtf8` can allocate under the flat-string model), and the
    // per-comparison decode collapses to a single pass.
    const Keyed = struct { key: []const u8, pair: Value };
    const keyed = try self.arena.alloc(Keyed, items.len);
    for (items, 0..) |p, i| keyed[i] = .{ .key = (try uspPairKV(self, p)).k, .pair = p };
    // Stable sort by key (code-unit order — the keys are already UTF-8/code-point
    // ordered for the common ASCII case).
    std.mem.sort(Keyed, keyed, {}, struct {
        fn lt(_: void, x: Keyed, y: Keyed) bool {
            return std.mem.order(u8, x.key, y.key) == .lt;
        }
    }.lt);
    const fresh = (try self.newArray()).asObj();
    for (keyed) |k| try fresh.appendElement(self.arena, k.pair);
    try this.asObj().setOwn(self.arena, self.root_shape, "\x00usp", Value.obj(fresh));
    try uspSyncToUrl(self, this);
    return Value.undef();
}
fn uspToStringFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    return try Value.strAlloc(self.arena, try uspToString(self, this));
}
fn uspSizeGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    return Value.num(@floatFromInt((try uspPairs(self, this)).elementsLen()));
}
fn uspForEachFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const cb = if (args.len > 0) args[0] else Value.undef();
    if (!cb.isObject() or !cb.asObj().isCallableObject()) return self.throwError("TypeError", "URLSearchParams.forEach callback is not a function");
    const this_arg = if (args.len > 1) args[1] else Value.undef();
    for (try (try uspPairs(self, this)).internalElementsSnapshot(self.arena)) |pair| {
        const kv = try uspPairKV(self, pair);
        _ = try self.callValueWithThis(cb, &.{ try Value.strAlloc(self.arena, kv.v), try Value.strAlloc(self.arena, kv.k), this }, this_arg);
    }
    return Value.undef();
}
/// entries/keys/values/@@iterator all return a fresh Array's iterator over a
/// snapshot of the current pairs.
fn uspIterFn(comptime which: enum { entries, keys, values }) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            _ = args;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            const snap = (try self.newArray()).asObj();
            for (try (try uspPairs(self, this)).internalElementsSnapshot(self.arena)) |pair| {
                const kv = try uspPairKV(self, pair);
                switch (which) {
                    .keys => try snap.appendElement(self.arena, try Value.strAlloc(self.arena, kv.k)),
                    .values => try snap.appendElement(self.arena, try Value.strAlloc(self.arena, kv.v)),
                    .entries => {
                        const e = (try self.newArray()).asObj();
                        try e.appendElement(self.arena, try Value.strAlloc(self.arena, kv.k));
                        try e.appendElement(self.arena, try Value.strAlloc(self.arena, kv.v));
                        try snap.appendElement(self.arena, Value.obj(e));
                    },
                }
            }
            return try self.makeCursorIterator(Value.obj(snap));
        }
    }.call;
}
fn installURLSearchParams(env: *Environment, rs: *Shape, object_proto: *value.Object) EvalError!void {
    const a = env.arena;
    const sym = struct {
        fn key(e: *Environment, name: []const u8) ?[]const u8 {
            if (e.get("Symbol")) |s| if (s.isObject()) {
                if (s.asObj().getOwn(name)) |t| if (t.isObject() and t.asObj().is_symbol) return t.asObj().symbolKey();
            };
            return null;
        }
    };
    const proto = try gc_mod.allocObj(a);
    proto.* = .{ .proto = object_proto };
    try setNative(a, rs, proto, "get", 1, uspGetFn);
    try setNative(a, rs, proto, "getAll", 1, uspGetAllFn);
    try setNative(a, rs, proto, "has", 1, uspHasFn);
    try setNative(a, rs, proto, "set", 2, uspSetFn);
    try setNative(a, rs, proto, "append", 2, uspAppendFn);
    try setNative(a, rs, proto, "delete", 1, uspDeleteFn);
    try setNative(a, rs, proto, "sort", 0, uspSortFn);
    try setNative(a, rs, proto, "forEach", 1, uspForEachFn);
    try setNative(a, rs, proto, "toString", 0, uspToStringFn);
    try setNative(a, rs, proto, "entries", 0, uspIterFn(.entries));
    try setNative(a, rs, proto, "keys", 0, uspIterFn(.keys));
    try setNative(a, rs, proto, "values", 0, uspIterFn(.values));
    try setNativeGetter(a, rs, proto, "size", uspSizeGet);
    try proto.setAttr(a, "size", .{ .enumerable = true, .configurable = true });
    if (sym.key(env, "iterator")) |k| try setNative(a, rs, proto, k, 0, uspIterFn(.entries));
    if (sym.key(env, "toStringTag")) |k| {
        try proto.setOwn(a, rs, k, Value.str("URLSearchParams"));
        try proto.setAttr(a, k, .{ .writable = false, .enumerable = false, .configurable = true });
    }
    const ctor = try gc_mod.allocObj(a);
    ctor.* = .{ .native = urlSearchParamsConstructorFn, .native_ctor = true };
    try installNativeProps(a, rs, ctor, "URLSearchParams", 0);
    try ctor.setOwn(a, rs, "prototype", Value.obj(proto));
    try ctor.setAttr(a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
    try setConstructor(a, rs, proto, ctor);
    try env.put("URLSearchParams", Value.obj(ctor));
}

// ===== Headers (Fetch) ===============================================
// JavaScript and the private WebCore ABI share one independently owned native
// record. A wrapper owns exactly one record reference and is branded by the
// private-data tag; prototype spoofing cannot manufacture a Headers instance.
pub fn fetchHeadersRecord(input: Value) ?*fetch_headers.Record {
    if (!input.isObject()) return null;
    const object = input.asObj();
    if (object.private_data_tag != .fetch_headers) return null;
    return @ptrCast(@alignCast(object.private_data orelse return null));
}

fn headersRecord(self: *Interpreter, this: Value) EvalError!*fetch_headers.Record {
    return fetchHeadersRecord(this) orelse self.throwError("TypeError", "Illegal invocation");
}

fn headersThrow(self: *Interpreter, err: fetch_headers.Error) EvalError {
    return switch (err) {
        error.InvalidName => self.throwError("TypeError", "Invalid header name"),
        error.InvalidValue => self.throwError("TypeError", "Invalid header value"),
        error.Immutable => self.throwError("TypeError", "Headers are immutable"),
        error.OutOfMemory => error.OutOfMemory,
    };
}

/// Web IDL ByteString conversion for Fetch header names and values. Header
/// storage is the isomorphic byte image, not the string's WTF-8 encoding.
fn headersByteString(self: *Interpreter, input: Value) EvalError![]const u8 {
    const string = try self.toStringValue(input);
    if (string.strIsAscii()) return string.asStr();
    var length: usize = 0;
    var units = Interpreter.StringCodeUnitIterator.initValue(string);
    while (units.next()) |unit| {
        if (unit.unit > 0xff) return self.throwError("TypeError", "Header value is not a ByteString");
        length += 1;
    }
    const bytes = try self.arena.alloc(u8, length);
    units = Interpreter.StringCodeUnitIterator.initValue(string);
    var index: usize = 0;
    while (units.next()) |unit| : (index += 1) bytes[index] = @intCast(unit.unit);
    return bytes;
}

fn headersStringValue(self: *Interpreter, bytes: []const u8) EvalError!Value {
    for (bytes) |byte| if (byte >= 0x80) {
        return Value.strAlloc(self.arena, try strcell.latin1FlatToWtf8(self.arena, bytes));
    };
    return Value.strAlloc(self.arena, bytes);
}

/// Consume one native record reference and create its genuine JS wrapper.
pub fn fetchHeadersCreateWithRecord(self: *Interpreter, record: *fetch_headers.Record) EvalError!Value {
    var consumed = false;
    defer if (!consumed) record.release();
    const object = try gc_mod.allocObj(self.arena);
    object.* = .{};
    if (self.env.get("Headers")) |constructor| if (constructor.isObject()) {
        if (constructor.asObj().getOwn("prototype")) |prototype| if (prototype.isObject()) object.setProtoAtomic(prototype.asObj());
    };
    if (self.fetch_headers_attach) |attach| {
        try attach(self.fetch_headers_attach_ctx, object, record);
    } else {
        object.private_data = @ptrCast(record);
        object.private_data_tag = .fetch_headers;
    }
    consumed = true;
    return Value.obj(object);
}

pub fn fetchHeadersCreateEmpty(self: *Interpreter) EvalError!Value {
    return fetchHeadersCreateWithRecord(self, fetch_headers.Record.create() catch return error.OutOfMemory);
}

fn fetchHeadersCreateEmptyGuarded(self: *Interpreter, guard: fetch_headers.Guard) EvalError!Value {
    const record = fetch_headers.Record.create() catch return error.OutOfMemory;
    record.setGuard(guard);
    return fetchHeadersCreateWithRecord(self, record);
}

fn fetchHeadersCloneWithGuard(self: *Interpreter, source: Value, guard: fetch_headers.Guard) EvalError!Value {
    const record = fetchHeadersRecord(source) orelse return fetchHeadersCreateEmptyGuarded(self, guard);
    return fetchHeadersCreateWithRecord(self, record.cloneWithGuard(guard) catch return error.OutOfMemory);
}

pub fn fetchHeadersAppendBytes(self: *Interpreter, this: Value, name: []const u8, header_value: []const u8) EvalError!void {
    const record = try headersRecord(self, this);
    record.appendGuarded(name, header_value) catch |err| return headersThrow(self, err);
}

fn fetchHeadersAppendBytesPrivileged(self: *Interpreter, this: Value, name: []const u8, header_value: []const u8) EvalError!void {
    const record = try headersRecord(self, this);
    record.append(name, header_value) catch |err| return headersThrow(self, err);
}

fn headersAppendRaw(self: *Interpreter, this: Value, name_v: Value, value_v: Value) EvalError!void {
    const name = try headersByteString(self, name_v);
    const header_value = try headersByteString(self, value_v);
    try fetchHeadersAppendBytes(self, this, name, header_value);
}
fn headersAppendFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    try headersAppendRaw(self, this, if (args.len > 0) args[0] else Value.undef(), if (args.len > 1) args[1] else Value.undef());
    return Value.undef();
}
fn headersSetFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const name = try headersByteString(self, if (args.len > 0) args[0] else Value.undef());
    const header_value = try headersByteString(self, if (args.len > 1) args[1] else Value.undef());
    const record = try headersRecord(self, this);
    record.setGuarded(name, header_value) catch |err| return headersThrow(self, err);
    return Value.undef();
}
fn headersGetFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const name = try headersByteString(self, if (args.len > 0) args[0] else Value.undef());
    const record = try headersRecord(self, this);
    const result = record.getCopy(self.arena, name) catch |err| return headersThrow(self, err);
    return if (result) |bytes| try headersStringValue(self, bytes) else Value.nul();
}
fn headersHasFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const name = try headersByteString(self, if (args.len > 0) args[0] else Value.undef());
    const record = try headersRecord(self, this);
    return Value.boolVal(record.has(name) catch |err| return headersThrow(self, err));
}
fn headersDeleteFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const name = try headersByteString(self, if (args.len > 0) args[0] else Value.undef());
    const record = try headersRecord(self, this);
    record.removeGuarded(name) catch |err| return headersThrow(self, err);
    return Value.undef();
}
fn headersGetSetCookieFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const arr = (try self.newArray()).asObj();
    const snapshot = (try headersRecord(self, this)).snapshot(self.arena, .lower) catch |err| return headersThrow(self, err);
    defer snapshot.deinit(self.arena);
    for (snapshot.rows) |row| {
        if (std.mem.eql(u8, row.name, "set-cookie")) try arr.appendElement(self.arena, try headersStringValue(self, row.value));
    }
    return Value.obj(arr);
}
fn headersSortedEntries(self: *Interpreter, this: Value) EvalError!*value.Object {
    const snapshot = (try headersRecord(self, this)).snapshot(self.arena, .lower) catch |err| return headersThrow(self, err);
    defer snapshot.deinit(self.arena);
    const out = (try self.newArray()).asObj();
    for (snapshot.rows) |row| {
        const pair = (try self.newArray()).asObj();
        try pair.appendElement(self.arena, try headersStringValue(self, row.name));
        try pair.appendElement(self.arena, try headersStringValue(self, row.value));
        try out.appendElement(self.arena, Value.obj(pair));
    }
    return out;
}
fn headersForEachFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const cb = if (args.len > 0) args[0] else Value.undef();
    if (!cb.isObject() or !cb.asObj().isCallableObject()) return self.throwError("TypeError", "Headers.forEach callback is not a function");
    const this_arg = if (args.len > 1) args[1] else Value.undef();
    for (try (try headersSortedEntries(self, this)).internalElementsSnapshot(self.arena)) |pair| {
        const kv = try uspPairKV(self, pair);
        _ = try self.callValueWithThis(cb, &.{ try Value.strAlloc(self.arena, kv.v), try Value.strAlloc(self.arena, kv.k), this }, this_arg);
    }
    return Value.undef();
}
fn headersIterFn(comptime which: enum { entries, keys, values }) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            _ = args;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            const snap = (try self.newArray()).asObj();
            for (try (try headersSortedEntries(self, this)).internalElementsSnapshot(self.arena)) |pair| {
                const kv = try uspPairKV(self, pair);
                switch (which) {
                    .keys => try snap.appendElement(self.arena, try Value.strAlloc(self.arena, kv.k)),
                    .values => try snap.appendElement(self.arena, try Value.strAlloc(self.arena, kv.v)),
                    .entries => try snap.appendElement(self.arena, pair),
                }
            }
            return try self.makeCursorIterator(Value.obj(snap));
        }
    }.call;
}
pub fn fetchHeadersFill(self: *Interpreter, this: Value, init: Value) EvalError!void {
    if (fetchHeadersRecord(init)) |source| {
        // Another Headers: copy its (already validated) entries.
        const snapshot = source.snapshot(self.arena, .display) catch |err| return headersThrow(self, err);
        defer snapshot.deinit(self.arena);
        for (snapshot.rows) |row| {
            try fetchHeadersAppendBytes(self, this, row.name, row.value);
        }
        return;
    }
    var is_sequence = init.isObject() and init.asObj().is_array;
    if (init.isObject() and !is_sequence) {
        if (self.env.get("Symbol")) |symbol| if (symbol.isObject()) {
            if (symbol.asObj().getOwn("iterator")) |iterator_symbol| if (iterator_symbol.isObject() and iterator_symbol.asObj().is_symbol) {
                const iterator = try self.getProperty(init, iterator_symbol.asObj().symbolKey());
                is_sequence = iterator.isObject() and iterator.asObj().isCallableObject();
            };
        };
    }
    if (is_sequence) {
        // Sequence of [name, value] sequences.
        for (try collectIterable(self, init)) |entry| {
            const pair = try collectIterable(self, entry);
            if (pair.len != 2) return self.throwError("TypeError", "Invalid header init: expected name/value pair");
            try headersAppendRaw(self, this, pair[0], pair[1]);
        }
        return;
    }
    if (init.isObject()) {
        // Record<string, string>: own enumerable string keys in order.
        for (try self.objectOwnKeysList(init.asObj())) |k| {
            try headersAppendRaw(self, this, try Value.strAlloc(self.arena, value.decodeStringKey(k)), try self.getProperty(init, k));
        }
        return;
    }
    return self.throwError("TypeError", "Invalid Headers initializer");
}
fn headersConstructorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (self.new_target.isUndefined()) return self.throwError("TypeError", "Failed to construct 'Headers': Please use the 'new' operator");
    const created = try fetchHeadersCreateEmpty(self);
    if (args.len > 0 and !args[0].isUndefined() and !args[0].isNull()) try fetchHeadersFill(self, created, args[0]);
    return created;
}
fn installHeaders(env: *Environment, rs: *Shape, object_proto: *value.Object) EvalError!void {
    const a = env.arena;
    const symKey = struct {
        fn f(e: *Environment, name: []const u8) ?[]const u8 {
            if (e.get("Symbol")) |s| if (s.isObject()) {
                if (s.asObj().getOwn(name)) |t| if (t.isObject() and t.asObj().is_symbol) return t.asObj().symbolKey();
            };
            return null;
        }
    }.f;
    const proto = try gc_mod.allocObj(a);
    proto.* = .{ .proto = object_proto };
    try setNative(a, rs, proto, "append", 2, headersAppendFn);
    try setNative(a, rs, proto, "set", 2, headersSetFn);
    try setNative(a, rs, proto, "get", 1, headersGetFn);
    try setNative(a, rs, proto, "has", 1, headersHasFn);
    try setNative(a, rs, proto, "delete", 1, headersDeleteFn);
    try setNative(a, rs, proto, "getSetCookie", 0, headersGetSetCookieFn);
    try setNative(a, rs, proto, "forEach", 1, headersForEachFn);
    try setNative(a, rs, proto, "entries", 0, headersIterFn(.entries));
    try setNative(a, rs, proto, "keys", 0, headersIterFn(.keys));
    try setNative(a, rs, proto, "values", 0, headersIterFn(.values));
    if (symKey(env, "iterator")) |k| try setNative(a, rs, proto, k, 0, headersIterFn(.entries));
    if (symKey(env, "toStringTag")) |k| {
        try proto.setOwn(a, rs, k, Value.str("Headers"));
        try proto.setAttr(a, k, .{ .writable = false, .enumerable = false, .configurable = true });
    }
    const ctor = try gc_mod.allocObj(a);
    ctor.* = .{ .native = headersConstructorFn, .native_ctor = true };
    try installNativeProps(a, rs, ctor, "Headers", 0);
    try ctor.setOwn(a, rs, "prototype", Value.obj(proto));
    try ctor.setAttr(a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
    try setConstructor(a, rs, proto, ctor);
    try env.put("Headers", Value.obj(ctor));
}

// ===== FormData ======================================================
// Entries live in \x00fd as [USVString name, USVString|File value] pairs in
// insertion order. The ordinary Value edges are the canonical storage for both
// JS-created and private-ABI-created instances, so GC traces Blob/File values
// without a parallel native list. A File created for an opaque native BlobImpl
// carries that pointer under the `form_data_native_blob` owner tag; it is an
// identity token only and is never dereferenced by the engine.
fn fdList(self: *Interpreter, this: Value) EvalError!*value.Object {
    if (!this.isObject() or !this.asObj().behavior.is_form_data)
        return self.throwError("TypeError", "FormData method called on an incompatible receiver");
    const slot = this.asObj().getOwn("\x00fd") orelse
        return self.throwError("TypeError", "FormData entry list is unavailable");
    if (!slot.isObject()) return self.throwError("TypeError", "FormData entry list is unavailable");
    return slot.asObj();
}

const FormDataAllocation = struct { obj: *value.Object, list: *value.Object };

fn fdAllocate(self: *Interpreter) EvalError!FormDataAllocation {
    const obj = try gc_mod.allocObj(self.arena);
    obj.* = .{ .behavior = .{ .is_form_data = true } };
    if (self.env.get("FormData")) |c| if (c.isObject()) {
        if (c.asObj().getOwn("prototype")) |p| if (p.isObject()) obj.setProtoAtomic(p.asObj());
    };
    const list = (try self.newArray()).asObj();
    try obj.setOwn(self.arena, self.root_shape, "\x00fd", Value.obj(list));
    return .{ .obj = obj, .list = list };
}

fn fdUSVString(self: *Interpreter, input: Value) EvalError![]const u8 {
    return wtf8ToUtf8Bytes(self.arena, try self.toStringWtf8(input));
}

fn fdPair(self: *Interpreter, pair: Value) EvalError!struct { name: []const u8, value: Value } {
    if (!pair.isObject()) return .{ .name = "", .value = Value.str("") };
    const entry = pair.asObj();
    const name_value = entry.elementAt(0) orelse Value.str("");
    return .{
        .name = if (name_value.isString()) try name_value.asWtf8(self.arena) else "",
        .value = entry.elementAt(1) orelse Value.str(""),
    };
}

fn fdPushValue(self: *Interpreter, list: *value.Object, name: []const u8, entry_value: Value) EvalError!void {
    const pair = (try self.newArray()).asObj();
    try pair.appendElement(self.arena, try Value.strAlloc(self.arena, name));
    try pair.appendElement(self.arena, entry_value);
    try list.appendElement(self.arena, Value.obj(pair));
}

fn fdPushString(self: *Interpreter, list: *value.Object, name: []const u8, string: []const u8) EvalError!void {
    try fdPushValue(self, list, name, try Value.strAlloc(self.arena, string));
}

fn fdRequireArgs(self: *Interpreter, args: []const Value, required: usize, method: []const u8) EvalError!void {
    if (args.len >= required) return;
    const message = try std.fmt.allocPrint(self.arena, "Failed to execute '{s}' on 'FormData': {d} arguments required", .{ method, required });
    return self.throwError("TypeError", message);
}

fn fdEntryValue(
    self: *Interpreter,
    input: Value,
    filename: ?[]const u8,
) EvalError!Value {
    if (!blobIsBlob(input)) return try Value.strAlloc(self.arena, try fdUSVString(self, input));
    if (blobIsFile(input) and filename == null) return input;
    return Value.obj(try blobCloneAsFile(self, input.asObj(), filename orelse "blob"));
}

fn fdMethodEntry(self: *Interpreter, args: []const Value, method: []const u8) EvalError!struct { name: []const u8, value: Value } {
    try fdRequireArgs(self, args, 2, method);
    const name = try fdUSVString(self, args[0]);
    if (args.len > 2 and !blobIsBlob(args[1]))
        return self.throwError("TypeError", "FormData filename is only valid for a Blob value");
    const filename_given = args.len > 2 and !args[2].isUndefined();
    const filename: ?[]const u8 = if (filename_given) try fdUSVString(self, args[2]) else null;
    return .{ .name = name, .value = try fdEntryValue(self, args[1], filename) };
}

fn fdAppendFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const entry = try fdMethodEntry(self, args, "append");
    try fdPushValue(self, try fdList(self, this), entry.name, entry.value);
    return Value.undef();
}
fn fdSetFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const entry = try fdMethodEntry(self, args, "set");
    // Replace the first occurrence in place, drop the rest; append if absent.
    const list = try fdList(self, this);
    const fresh = (try self.newArray()).asObj();
    var placed = false;
    for (try list.internalElementsSnapshot(self.arena)) |pair| {
        if (std.mem.eql(u8, (try fdPair(self, pair)).name, entry.name)) {
            if (!placed) {
                try fdPushValue(self, fresh, entry.name, entry.value);
                placed = true;
            }
            continue;
        }
        try fresh.appendElement(self.arena, pair);
    }
    if (!placed) try fdPushValue(self, fresh, entry.name, entry.value);
    try this.asObj().setOwn(self.arena, self.root_shape, "\x00fd", Value.obj(fresh));
    return Value.undef();
}
fn fdGetFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    try fdRequireArgs(self, args, 1, "get");
    const name = try fdUSVString(self, args[0]);
    for (try (try fdList(self, this)).internalElementsSnapshot(self.arena)) |pair| {
        const entry = try fdPair(self, pair);
        if (std.mem.eql(u8, entry.name, name)) return entry.value;
    }
    return Value.nul();
}
fn fdGetAllFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    try fdRequireArgs(self, args, 1, "getAll");
    const name = try fdUSVString(self, args[0]);
    const arr = (try self.newArray()).asObj();
    for (try (try fdList(self, this)).internalElementsSnapshot(self.arena)) |pair| {
        const entry = try fdPair(self, pair);
        if (std.mem.eql(u8, entry.name, name)) try arr.appendElement(self.arena, entry.value);
    }
    return Value.obj(arr);
}
fn fdHasFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    try fdRequireArgs(self, args, 1, "has");
    const name = try fdUSVString(self, args[0]);
    for (try (try fdList(self, this)).internalElementsSnapshot(self.arena)) |pair| {
        if (std.mem.eql(u8, (try fdPair(self, pair)).name, name)) return Value.boolVal(true);
    }
    return Value.boolVal(false);
}
fn fdDeleteFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    try fdRequireArgs(self, args, 1, "delete");
    const name = try fdUSVString(self, args[0]);
    const list = try fdList(self, this);
    const fresh = (try self.newArray()).asObj();
    for (try list.internalElementsSnapshot(self.arena)) |pair| {
        if (std.mem.eql(u8, (try fdPair(self, pair)).name, name)) continue;
        try fresh.appendElement(self.arena, pair);
    }
    try this.asObj().setOwn(self.arena, self.root_shape, "\x00fd", Value.obj(fresh));
    return Value.undef();
}
fn fdForEachFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const cb = if (args.len > 0) args[0] else Value.undef();
    if (!cb.isObject() or !cb.asObj().isCallableObject()) return self.throwError("TypeError", "FormData.forEach callback is not a function");
    const this_arg = if (args.len > 1) args[1] else Value.undef();
    for (try (try fdList(self, this)).internalElementsSnapshot(self.arena)) |pair| {
        const entry = try fdPair(self, pair);
        _ = try self.callValueWithThis(cb, &.{ entry.value, try Value.strAlloc(self.arena, entry.name), this }, this_arg);
    }
    return Value.undef();
}
fn fdIterFn(comptime which: enum { entries, keys, values }) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            _ = args;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            const snap = (try self.newArray()).asObj();
            for (try (try fdList(self, this)).internalElementsSnapshot(self.arena)) |pair| {
                const entry = try fdPair(self, pair);
                switch (which) {
                    .keys => try snap.appendElement(self.arena, try Value.strAlloc(self.arena, entry.name)),
                    .values => try snap.appendElement(self.arena, entry.value),
                    .entries => try snap.appendElement(self.arena, pair),
                }
            }
            return try self.makeCursorIterator(Value.obj(snap));
        }
    }.call;
}
fn fdConstructorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (self.new_target.isUndefined()) return self.throwError("TypeError", "Failed to construct 'FormData': Please use the 'new' operator");
    // A form argument (HTMLFormElement) is the only accepted init; there is no
    // DOM here, so a supplied non-undefined argument is a conversion failure.
    if (args.len > 0 and !args[0].isUndefined()) return self.throwError("TypeError", "Failed to construct 'FormData': parameter 1 is not of type 'HTMLFormElement'.");
    return Value.obj((try fdAllocate(self)).obj);
}

pub const FormDataEntry = struct {
    name: []const u8,
    value: Value,
};

pub fn formDataIsInstance(input: Value) bool {
    return input.isObject() and input.asObj().behavior.is_form_data;
}

pub fn formDataCreate(self: *Interpreter) EvalError!Value {
    return Value.obj((try fdAllocate(self)).obj);
}

pub fn formDataCreateFromURLQuery(self: *Interpreter, query: []const u8) EvalError!Value {
    const allocation = try fdAllocate(self);
    const input = query;
    if (input.len != 0) {
        var segments = std.mem.splitScalar(u8, input, '&');
        while (segments.next()) |segment| {
            if (segment.len == 0) continue;
            const equal = std.mem.indexOfScalar(u8, segment, '=');
            const raw_name = if (equal) |index| segment[0..index] else segment;
            const raw_value = if (equal) |index| segment[index + 1 ..] else "";
            const name = try formUrlDecode(self, raw_name);
            const string = try formUrlDecode(self, raw_value);
            try fdPushString(self, allocation.list, name, string);
        }
    }
    return Value.obj(allocation.obj);
}

pub fn formDataAppendString(self: *Interpreter, form: Value, name: []const u8, string: []const u8) EvalError!void {
    const normalized_name = try wtf8ToUtf8Bytes(self.arena, name);
    const normalized_string = try wtf8ToUtf8Bytes(self.arena, string);
    try fdPushString(self, try fdList(self, form), normalized_name, normalized_string);
}

pub fn formDataAppendNativeBlob(
    self: *Interpreter,
    form: Value,
    name: []const u8,
    raw_blob: *anyopaque,
    filename: []const u8,
    source: ?Value,
) EvalError!void {
    const normalized_name = try wtf8ToUtf8Bytes(self.arena, name);
    const normalized_filename = try wtf8ToUtf8Bytes(self.arena, filename);
    const file = if (source) |blob|
        try blobCloneAsFile(self, blob.asObj(), normalized_filename)
    else
        try blobMakeNativeFile(self, raw_blob, normalized_filename);
    file.private_data = raw_blob;
    file.private_data_tag = .form_data_native_blob;
    try fdPushValue(self, try fdList(self, form), normalized_name, Value.obj(file));
}

pub fn formDataCount(self: *Interpreter, form: Value) EvalError!usize {
    return (try (try fdList(self, form)).internalElementsSnapshot(self.arena)).len;
}

pub fn formDataEntries(self: *Interpreter, form: Value) EvalError![]FormDataEntry {
    const items = try (try fdList(self, form)).internalElementsSnapshot(self.arena);
    const entries = try self.arena.alloc(FormDataEntry, items.len);
    for (items, entries) |pair, *entry| {
        const decoded = try fdPair(self, pair);
        entry.* = .{ .name = decoded.name, .value = decoded.value };
    }
    return entries;
}

pub fn formDataEntryAt(self: *Interpreter, form: Value, index: usize) EvalError!?FormDataEntry {
    const list = try fdList(self, form);
    const pair = list.elementAt(index) orelse return null;
    const decoded = try fdPair(self, pair);
    return .{ .name = decoded.name, .value = decoded.value };
}

pub fn formDataSerialize(self: *Interpreter, form: Value) EvalError![]const u8 {
    var out: std.ArrayListUnmanaged(u8) = .empty;
    var first = true;
    for (try formDataEntries(self, form)) |entry| {
        if (!entry.value.isString()) continue;
        if (!first) try out.append(self.arena, '&');
        first = false;
        try out.appendSlice(self.arena, try formUrlEncode(self, entry.name));
        try out.append(self.arena, '=');
        try out.appendSlice(self.arena, try formUrlEncode(self, try entry.value.asWtf8(self.arena)));
    }
    return out.items;
}

pub fn formDataNativeBlobPointer(input: Value) ?*anyopaque {
    if (!blobIsBlob(input) or input.asObj().private_data_tag != .form_data_native_blob) return null;
    return input.asObj().private_data;
}

pub fn formDataFilename(self: *Interpreter, input: Value) EvalError!?[]const u8 {
    if (!blobIsFile(input)) return null;
    const filename = input.asObj().getOwn("\x00filename") orelse return "";
    return if (filename.isString()) try filename.asWtf8(self.arena) else "";
}
fn installFormData(env: *Environment, rs: *Shape, object_proto: *value.Object) EvalError!void {
    const a = env.arena;
    const symKey = struct {
        fn f(e: *Environment, name: []const u8) ?[]const u8 {
            if (e.get("Symbol")) |s| if (s.isObject()) {
                if (s.asObj().getOwn(name)) |t| if (t.isObject() and t.asObj().is_symbol) return t.asObj().symbolKey();
            };
            return null;
        }
    }.f;
    const proto = try gc_mod.allocObj(a);
    proto.* = .{ .proto = object_proto };
    try setNative(a, rs, proto, "append", 2, fdAppendFn);
    try setNative(a, rs, proto, "set", 2, fdSetFn);
    try setNative(a, rs, proto, "get", 1, fdGetFn);
    try setNative(a, rs, proto, "getAll", 1, fdGetAllFn);
    try setNative(a, rs, proto, "has", 1, fdHasFn);
    try setNative(a, rs, proto, "delete", 1, fdDeleteFn);
    try setNative(a, rs, proto, "forEach", 1, fdForEachFn);
    try setNative(a, rs, proto, "entries", 0, fdIterFn(.entries));
    try setNative(a, rs, proto, "keys", 0, fdIterFn(.keys));
    try setNative(a, rs, proto, "values", 0, fdIterFn(.values));
    if (symKey(env, "iterator")) |k| try setNative(a, rs, proto, k, 0, fdIterFn(.entries));
    if (symKey(env, "toStringTag")) |k| {
        try proto.setOwn(a, rs, k, Value.str("FormData"));
        try proto.setAttr(a, k, .{ .writable = false, .enumerable = false, .configurable = true });
    }
    const ctor = try gc_mod.allocObj(a);
    ctor.* = .{ .native = fdConstructorFn, .native_ctor = true };
    try installNativeProps(a, rs, ctor, "FormData", 1);
    try ctor.setOwn(a, rs, "prototype", Value.obj(proto));
    try ctor.setAttr(a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
    try setConstructor(a, rs, proto, ctor);
    try env.put("FormData", Value.obj(ctor));
}

// ===== Blob / File ===================================================
// A Blob keeps its bytes in a hidden ArrayBuffer (\x00blobbuf) and its MIME type
// in \x00blobtype. File adds \x00filename and \x00filemod (lastModified).
// Private FormData can additionally expose a File whose backing BlobImpl is a
// foreign opaque pointer. Such a File is correctly branded but byte-reading
// APIs reject it instead of fabricating an empty payload.
fn blobIsBlob(v: Value) bool {
    return v.isObject() and v.asObj().behavior.is_blob;
}
fn blobIsFile(v: Value) bool {
    return blobIsBlob(v) and v.asObj().behavior.is_file;
}
fn blobHasBytes(o: *value.Object) bool {
    return o.getOwn("\x00blobbuf") != null;
}
fn blobBytesOf(o: *value.Object) []const u8 {
    if (o.getOwn("\x00blobbuf")) |bv| if (bv.isObject()) if (bv.asObj().arrayBuffer()) |ab| return ab.bytes();
    return &.{};
}
/// Valid Blob/File type: all chars in U+0020..U+007E; lowercased, else "".
fn blobNormalizeType(self: *Interpreter, t: []const u8) EvalError![]const u8 {
    for (t) |c| if (c < 0x20 or c > 0x7E) return "";
    const buf = try self.arena.alloc(u8, t.len);
    for (t, 0..) |c, i| buf[i] = std.ascii.toLower(c);
    return buf;
}
fn blobConcatParts(self: *Interpreter, parts_v: Value) EvalError![]u8 {
    var out: std.ArrayListUnmanaged(u8) = .empty;
    if (parts_v.isUndefined()) return out.items;
    // WebIDL sequence conversion requires an object; a primitive (e.g. a bare
    // string, which is iterable but not an object) is a TypeError.
    if (!parts_v.isObject()) return self.throwError("TypeError", "The provided value cannot be converted to a sequence");
    for (try collectIterable(self, parts_v)) |part| {
        if (blobIsBlob(part)) {
            if (!blobHasBytes(part.asObj())) return self.throwError("TypeError", "Native Blob data is unavailable");
            try out.appendSlice(self.arena, blobBytesOf(part.asObj()));
        } else if (bufferSourceBytes(part)) |b| {
            try out.appendSlice(self.arena, b);
        } else {
            try out.appendSlice(self.arena, try wtf8ToUtf8Bytes(self.arena, try self.toStringWtf8(part)));
        }
    }
    return out.items;
}
fn blobMakeWithBuffer(self: *Interpreter, proto_name: []const u8, buf: *value.Object, blob_type: []const u8) EvalError!*value.Object {
    const obj = try gc_mod.allocObj(self.arena);
    const is_file = std.mem.eql(u8, proto_name, "File");
    obj.* = .{ .behavior = .{ .is_blob = true, .is_file = is_file } };
    if (self.env.get(proto_name)) |c| if (c.isObject()) {
        if (c.asObj().getOwn("prototype")) |pp| if (pp.isObject()) obj.setProtoAtomic(pp.asObj());
    };
    try obj.setOwn(self.arena, self.root_shape, "\x00blobbuf", Value.obj(buf));
    try obj.setOwn(self.arena, self.root_shape, "\x00blobtype", try Value.strAlloc(self.arena, blob_type));
    return obj;
}
fn blobMake(self: *Interpreter, proto_name: []const u8, bytes: []const u8, blob_type: []const u8) EvalError!*value.Object {
    const buf = try self.makeArrayBuffer(bytes.len);
    if (bytes.len > 0) @memcpy(buf.arrayBuffer().?.bytes()[0..bytes.len], bytes);
    return blobMakeWithBuffer(self, proto_name, buf, blob_type);
}
fn blobMakeNativeFile(self: *Interpreter, raw_blob: *anyopaque, filename: []const u8) EvalError!*value.Object {
    const obj = try gc_mod.allocObj(self.arena);
    obj.* = .{
        .behavior = .{ .is_blob = true, .is_file = true },
        .private_data = raw_blob,
        .private_data_tag = .form_data_native_blob,
    };
    if (self.env.get("File")) |c| if (c.isObject()) {
        if (c.asObj().getOwn("prototype")) |p| if (p.isObject()) obj.setProtoAtomic(p.asObj());
    };
    try obj.setOwn(self.arena, self.root_shape, "\x00blobtype", Value.str(""));
    try obj.setOwn(self.arena, self.root_shape, "\x00filename", try Value.strAlloc(self.arena, filename));
    try obj.setOwn(self.arena, self.root_shape, "\x00filemod", Value.num(0));
    return obj;
}
fn blobCloneAsFile(self: *Interpreter, source: *value.Object, filename: []const u8) EvalError!*value.Object {
    const normalized_name = try wtf8ToUtf8Bytes(self.arena, filename);
    if (!blobHasBytes(source)) {
        const raw = source.private_data orelse return self.throwError("TypeError", "Native Blob identity is unavailable");
        return blobMakeNativeFile(self, raw, normalized_name);
    }
    const type_value = source.getOwn("\x00blobtype");
    const blob_type = if (type_value != null and type_value.?.isString()) type_value.?.asStr() else "";
    const clone = try blobMake(self, "File", blobBytesOf(source), blob_type);
    try clone.setOwn(self.arena, self.root_shape, "\x00filename", try Value.strAlloc(self.arena, normalized_name));
    const last_modified = if (source.behavior.is_file) source.getOwn("\x00filemod") orelse Value.num(0) else Value.num(0);
    try clone.setOwn(self.arena, self.root_shape, "\x00filemod", last_modified);
    if (source.private_data_tag == .form_data_native_blob) {
        clone.private_data = source.private_data;
        clone.private_data_tag = .form_data_native_blob;
    }
    return clone;
}
fn blobConstructorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (self.new_target.isUndefined()) return self.throwError("TypeError", "Failed to construct 'Blob': Please use the 'new' operator");
    const bytes = try blobConcatParts(self, if (args.len > 0) args[0] else Value.undef());
    var ty: []const u8 = "";
    if (args.len > 1 and args[1].isObject()) {
        const tv = try self.getProperty(args[1], "type");
        if (!tv.isUndefined()) ty = try blobNormalizeType(self, try self.toStringV(tv));
    }
    return Value.obj(try blobMake(self, "Blob", bytes, ty));
}
fn blobSizeGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!blobIsBlob(this)) return self.throwError("TypeError", "Illegal invocation");
    if (!blobHasBytes(this.asObj())) return self.throwError("TypeError", "Native Blob data is unavailable");
    return Value.num(@floatFromInt(blobBytesOf(this.asObj()).len));
}
fn blobTypeGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!blobIsBlob(this)) return self.throwError("TypeError", "Illegal invocation");
    return this.asObj().getOwn("\x00blobtype") orelse Value.str("");
}
fn blobClampIndex(x: f64, len: usize) usize {
    const l: f64 = @floatFromInt(len);
    var r = x;
    if (std.math.isNan(r)) return 0;
    if (r < 0) {
        r = l + r;
        if (r < 0) r = 0;
    } else if (r > l) r = l;
    return @intFromFloat(r);
}
fn blobSliceFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!blobIsBlob(this)) return self.throwError("TypeError", "Illegal invocation");
    if (!blobHasBytes(this.asObj())) return self.throwError("TypeError", "Native Blob data is unavailable");
    const bytes = blobBytesOf(this.asObj());
    const len = bytes.len;
    const start: usize = if (args.len > 0 and !args[0].isUndefined()) blobClampIndex(try self.toNumberV(args[0]), len) else 0;
    const end: usize = if (args.len > 1 and !args[1].isUndefined()) blobClampIndex(try self.toNumberV(args[1]), len) else len;
    const span: []const u8 = if (end > start) bytes[start..end] else &.{};
    var ty: []const u8 = "";
    if (args.len > 2 and !args[2].isUndefined()) ty = try blobNormalizeType(self, try self.toStringV(args[2]));
    return Value.obj(try blobMake(self, "Blob", span, ty));
}
fn blobTextFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!blobIsBlob(this)) return self.throwError("TypeError", "Illegal invocation");
    if (!blobHasBytes(this.asObj())) return self.throwError("TypeError", "Native Blob data is unavailable");
    // The stored bytes are UTF-8; expose them as a JS string.
    const s = try Value.strAlloc(self.arena, blobBytesOf(this.asObj()));
    return try promiseResolveValue(self, s);
}
fn blobArrayBufferFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!blobIsBlob(this)) return self.throwError("TypeError", "Illegal invocation");
    if (!blobHasBytes(this.asObj())) return self.throwError("TypeError", "Native Blob data is unavailable");
    const bytes = blobBytesOf(this.asObj());
    const buf = try self.makeArrayBuffer(bytes.len);
    if (bytes.len > 0) @memcpy(buf.arrayBuffer().?.bytes()[0..bytes.len], bytes);
    return try promiseResolveValue(self, Value.obj(buf));
}
fn blobBytesFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!blobIsBlob(this)) return self.throwError("TypeError", "Illegal invocation");
    if (!blobHasBytes(this.asObj())) return self.throwError("TypeError", "Native Blob data is unavailable");
    const ta = try newTypedArray(self, .u8, blobBytesOf(this.asObj()).len);
    const bytes = blobBytesOf(this.asObj());
    if (bytes.len > 0) @memcpy(ta.typedArray().?.buffer.arrayBuffer().?.bytes()[0..bytes.len], bytes);
    return try promiseResolveValue(self, Value.obj(ta));
}
fn fileConstructorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (self.new_target.isUndefined()) return self.throwError("TypeError", "Failed to construct 'File': Please use the 'new' operator");
    if (args.len < 2) return self.throwError("TypeError", "Failed to construct 'File': 2 arguments required");
    const bytes = try blobConcatParts(self, args[0]);
    const name = try wtf8ToUtf8Bytes(self.arena, try self.toStringWtf8(args[1]));
    var ty: []const u8 = "";
    var last_mod: f64 = 0;
    if (args.len > 2 and args[2].isObject()) {
        const tv = try self.getProperty(args[2], "type");
        if (!tv.isUndefined()) ty = try blobNormalizeType(self, try self.toStringV(tv));
        const lm = try self.getProperty(args[2], "lastModified");
        if (!lm.isUndefined()) last_mod = try self.toNumberV(lm);
    }
    const obj = try blobMake(self, "File", bytes, ty);
    try obj.setOwn(self.arena, self.root_shape, "\x00filename", try Value.strAlloc(self.arena, name));
    try obj.setOwn(self.arena, self.root_shape, "\x00filemod", Value.num(last_mod));
    return Value.obj(obj);
}
fn fileNameGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!blobIsFile(this)) return self.throwError("TypeError", "Illegal invocation");
    return this.asObj().getOwn("\x00filename") orelse Value.str("");
}
fn fileLastModifiedGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!blobIsFile(this)) return self.throwError("TypeError", "Illegal invocation");
    return this.asObj().getOwn("\x00filemod") orelse Value.num(0);
}
fn installBlob(env: *Environment, rs: *Shape, object_proto: *value.Object) EvalError!void {
    const a = env.arena;
    const symKey = struct {
        fn f(e: *Environment, name: []const u8) ?[]const u8 {
            if (e.get("Symbol")) |s| if (s.isObject()) {
                if (s.asObj().getOwn(name)) |t| if (t.isObject() and t.asObj().is_symbol) return t.asObj().symbolKey();
            };
            return null;
        }
    }.f;
    const proto = try gc_mod.allocObj(a);
    proto.* = .{ .proto = object_proto };
    try setNativeGetter(a, rs, proto, "size", blobSizeGet);
    try proto.setAttr(a, "size", .{ .enumerable = true, .configurable = true });
    try setNativeGetter(a, rs, proto, "type", blobTypeGet);
    try proto.setAttr(a, "type", .{ .enumerable = true, .configurable = true });
    try setNative(a, rs, proto, "slice", 2, blobSliceFn);
    try setNative(a, rs, proto, "text", 0, blobTextFn);
    try setNative(a, rs, proto, "arrayBuffer", 0, blobArrayBufferFn);
    try setNative(a, rs, proto, "bytes", 0, blobBytesFn);
    if (symKey(env, "toStringTag")) |k| {
        try proto.setOwn(a, rs, k, Value.str("Blob"));
        try proto.setAttr(a, k, .{ .writable = false, .enumerable = false, .configurable = true });
    }
    const ctor = try gc_mod.allocObj(a);
    ctor.* = .{ .native = blobConstructorFn, .native_ctor = true };
    try installNativeProps(a, rs, ctor, "Blob", 0);
    try ctor.setOwn(a, rs, "prototype", Value.obj(proto));
    try ctor.setAttr(a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
    try setConstructor(a, rs, proto, ctor);
    try env.put("Blob", Value.obj(ctor));

    // File extends Blob.
    const file_proto = try gc_mod.allocObj(a);
    file_proto.* = .{ .proto = proto };
    try setNativeGetter(a, rs, file_proto, "name", fileNameGet);
    try file_proto.setAttr(a, "name", .{ .enumerable = true, .configurable = true });
    try setNativeGetter(a, rs, file_proto, "lastModified", fileLastModifiedGet);
    try file_proto.setAttr(a, "lastModified", .{ .enumerable = true, .configurable = true });
    if (symKey(env, "toStringTag")) |k| {
        try file_proto.setOwn(a, rs, k, Value.str("File"));
        try file_proto.setAttr(a, k, .{ .writable = false, .enumerable = false, .configurable = true });
    }
    const file_ctor = try gc_mod.allocObj(a);
    file_ctor.* = .{ .native = fileConstructorFn, .native_ctor = true };
    try installNativeProps(a, rs, file_ctor, "File", 0);
    try file_ctor.setOwn(a, rs, "prototype", Value.obj(file_proto));
    try file_ctor.setAttr(a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
    try setConstructor(a, rs, file_proto, file_ctor);
    try env.put("File", Value.obj(file_ctor));
}

// ===== ReadableStream ===============================================
// The default stream/controller/reader state is stored as ordinary hidden
// Value edges. That makes queued chunks, pending read promises, algorithms,
// and conversion continuations precise-GC roots without a second native graph.
// This is deliberately a real pull-driven stream rather than an eager iterable
// adapter: lock/disturbed state and close/error/cancel transitions remain
// observable while private Home/Bun consumers drain it asynchronously.
const RSState = enum { readable, closed, errored };

fn rsState(stream: *value.Object) RSState {
    const slot = stream.getOwn("\x00rsState") orelse return .errored;
    if (!slot.isString()) return .errored;
    if (std.mem.eql(u8, slot.asStr(), "readable")) return .readable;
    if (std.mem.eql(u8, slot.asStr(), "closed")) return .closed;
    return .errored;
}

fn rsSetState(self: *Interpreter, stream: *value.Object, state: RSState) EvalError!void {
    const name = switch (state) {
        .readable => Value.str("readable"),
        .closed => Value.str("closed"),
        .errored => Value.str("errored"),
    };
    try stream.setOwn(self.arena, self.root_shape, "\x00rsState", name);
}

fn rsIsStream(input: Value) bool {
    if (!input.isObject()) return false;
    const object = input.asObj();
    return object.getOwn("\x00rsController") != null and object.getOwn("\x00rsState") != null;
}

fn rsRequireStream(self: *Interpreter, input: Value) EvalError!*value.Object {
    if (!rsIsStream(input)) return self.throwError("TypeError", "ReadableStream method called on an incompatible receiver");
    return input.asObj();
}

fn rsHiddenObject(object: *value.Object, key: []const u8) ?*value.Object {
    const slot = object.getOwn(key) orelse return null;
    return if (slot.isObject()) slot.asObj() else null;
}

fn rsHiddenBool(object: *value.Object, key: []const u8) bool {
    return if (object.getOwn(key)) |slot| slot.toBoolean() else false;
}

fn rsHiddenIndex(object: *value.Object, key: []const u8) usize {
    const slot = object.getOwn(key) orelse return 0;
    if (!slot.isNumber() or slot.asNum() <= 0 or !std.math.isFinite(slot.asNum())) return 0;
    return @intFromFloat(@trunc(slot.asNum()));
}

fn rsSetHiddenIndex(self: *Interpreter, object: *value.Object, key: []const u8, index: usize) EvalError!void {
    try object.setOwn(self.arena, self.root_shape, key, Value.num(@floatFromInt(index)));
}

fn rsPendingCount(object: *value.Object, list_key: []const u8, head_key: []const u8) usize {
    const list = rsHiddenObject(object, list_key) orelse return 0;
    const head = rsHiddenIndex(object, head_key);
    return list.elementsLen() -| head;
}

fn rsTakeHidden(self: *Interpreter, object: *value.Object, list_key: []const u8, head_key: []const u8) EvalError!?Value {
    const list = rsHiddenObject(object, list_key) orelse return null;
    const head = rsHiddenIndex(object, head_key);
    const item = list.elementAt(head) orelse return null;
    try rsSetHiddenIndex(self, object, head_key, head + 1);
    return item;
}

fn rsPromiseValue(self: *Interpreter, state: promise.State, stored: Value) EvalError!Value {
    return Value.obj(try promise.newSettledPromise(self, state, stored));
}

fn rsResolveStoredPromise(self: *Interpreter, promise_value: Value, result: Value) EvalError!void {
    const target = promise.promiseOf(promise_value) orelse return;
    try promise.resolve(self, target, result);
}

fn rsRejectStoredPromise(self: *Interpreter, promise_value: Value, reason: Value) EvalError!void {
    const target = promise.promiseOf(promise_value) orelse return;
    try promise.reject(self, target, reason);
}

fn rsReader(stream: *value.Object) ?*value.Object {
    const slot = stream.getOwn("\x00rsReader") orelse return null;
    return if (slot.isObject()) slot.asObj() else null;
}

fn rsReaderClosedPromise(reader: *value.Object) ?Value {
    const slot = reader.getOwn("\x00rrClosed") orelse return null;
    return if (promise.promiseOf(slot) != null) slot else null;
}

fn rsFinishClosed(self: *Interpreter, stream: *value.Object) EvalError!void {
    if (rsState(stream) != .readable) return;
    try rsSetState(self, stream, .closed);
    while (try rsTakeHidden(self, stream, "\x00rsRequests", "\x00rsRequestsHead")) |request| {
        try rsResolveStoredPromise(self, request, try self.iterResultObj(Value.undef(), true));
    }
    if (rsReader(stream)) |reader| if (rsReaderClosedPromise(reader)) |closed| {
        try rsResolveStoredPromise(self, closed, Value.undef());
    };
}

fn rsError(self: *Interpreter, stream: *value.Object, reason: Value) EvalError!void {
    if (rsState(stream) != .readable) return;
    try stream.setOwn(self.arena, self.root_shape, "\x00rsError", reason);
    try rsSetState(self, stream, .errored);
    while (try rsTakeHidden(self, stream, "\x00rsRequests", "\x00rsRequestsHead")) |request| {
        try rsRejectStoredPromise(self, request, reason);
    }
    if (rsReader(stream)) |reader| if (rsReaderClosedPromise(reader)) |closed| {
        try rsRejectStoredPromise(self, closed, reason);
    };
}

fn rsNativeHandler(self: *Interpreter, function: value.NativeFn, name: []const u8) EvalError!Value {
    const object = try gc_mod.allocObj(self.arena);
    object.* = .{ .native = function };
    try installNativeProps(self.arena, self.root_shape, object, name, 2);
    return Value.obj(object);
}

fn rsShouldPull(stream: *value.Object) bool {
    if (rsState(stream) != .readable or !rsHiddenBool(stream, "\x00rsStarted") or rsHiddenBool(stream, "\x00rsCloseRequested")) return false;
    if (rsPendingCount(stream, "\x00rsRequests", "\x00rsRequestsHead") != 0) return true;
    const queued = rsPendingCount(stream, "\x00rsQueue", "\x00rsQueueHead");
    const high_water = if (stream.getOwn("\x00rsHighWaterMark")) |slot| if (slot.isNumber()) slot.asNum() else 1 else 1;
    return @as(f64, @floatFromInt(queued)) < high_water;
}

fn rsCallPullIfNeeded(self: *Interpreter, stream: *value.Object) EvalError!void {
    if (!rsShouldPull(stream)) return;
    if (rsHiddenBool(stream, "\x00rsPulling")) {
        try stream.setOwn(self.arena, self.root_shape, "\x00rsPullAgain", Value.boolVal(true));
        return;
    }
    const pull = stream.getOwn("\x00rsPull") orelse Value.undef();
    if (!pull.isCallable()) return;
    try stream.setOwn(self.arena, self.root_shape, "\x00rsPulling", Value.boolVal(true));
    const controller = stream.getOwn("\x00rsController") orelse Value.undef();
    const source = stream.getOwn("\x00rsSource") orelse Value.undef();
    const pulled = self.callValueWithThis(pull, &.{controller}, source) catch |err| {
        if (err == error.Throw) {
            const reason = self.exception;
            self.exception = Value.undef();
            try rsError(self, stream, reason);
            return;
        }
        return err;
    };
    const wrapped = try promiseResolveValue(self, pulled);
    const pull_promise = promise.promiseOf(wrapped).?;
    const on_fulfilled = try rsNativeHandler(self, rsPullFulfilledFn, "ReadableStream pull fulfilled");
    const on_rejected = try rsNativeHandler(self, rsPullRejectedFn, "ReadableStream pull rejected");
    try promise.performThenDetached(self, pull_promise, on_fulfilled, on_rejected, Value.obj(stream));
}

fn rsPullFulfilledFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len < 2 or !rsIsStream(args[1])) return Value.undef();
    const stream = args[1].asObj();
    try stream.setOwn(self.arena, self.root_shape, "\x00rsPulling", Value.boolVal(false));
    const again = rsHiddenBool(stream, "\x00rsPullAgain");
    try stream.setOwn(self.arena, self.root_shape, "\x00rsPullAgain", Value.boolVal(false));
    if (again) try rsCallPullIfNeeded(self, stream);
    return Value.undef();
}

fn rsPullRejectedFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len < 2 or !rsIsStream(args[1])) return Value.undef();
    const stream = args[1].asObj();
    try stream.setOwn(self.arena, self.root_shape, "\x00rsPulling", Value.boolVal(false));
    try rsError(self, stream, if (args.len > 0) args[0] else Value.undef());
    return Value.undef();
}

fn rsStartFulfilledFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len < 2 or !rsIsStream(args[1])) return Value.undef();
    const stream = args[1].asObj();
    try stream.setOwn(self.arena, self.root_shape, "\x00rsStarted", Value.boolVal(true));
    try rsCallPullIfNeeded(self, stream);
    return Value.undef();
}

fn rsStartRejectedFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len < 2 or !rsIsStream(args[1])) return Value.undef();
    try rsError(self, args[1].asObj(), if (args.len > 0) args[0] else Value.undef());
    return Value.undef();
}

fn rsControllerStream(self: *Interpreter, input: Value) EvalError!*value.Object {
    if (!input.isObject()) return self.throwError("TypeError", "ReadableStreamDefaultController method called on an incompatible receiver");
    const stream_value = input.asObj().getOwn("\x00rcStream") orelse
        return self.throwError("TypeError", "ReadableStreamDefaultController method called on an incompatible receiver");
    return rsRequireStream(self, stream_value);
}

fn rsControllerEnqueueFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const stream = try rsControllerStream(self, this);
    if (rsState(stream) != .readable or rsHiddenBool(stream, "\x00rsCloseRequested"))
        return self.throwError("TypeError", "ReadableStream is not in a readable state");
    const chunk = if (args.len > 0) args[0] else Value.undef();
    if (try rsTakeHidden(self, stream, "\x00rsRequests", "\x00rsRequestsHead")) |request| {
        try rsResolveStoredPromise(self, request, try self.iterResultObj(chunk, false));
    } else {
        const queue = rsHiddenObject(stream, "\x00rsQueue") orelse return error.OutOfMemory;
        try queue.appendInternalElement(self.arena, chunk);
    }
    try rsCallPullIfNeeded(self, stream);
    return Value.undef();
}

fn rsControllerCloseFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const stream = try rsControllerStream(self, this);
    if (rsState(stream) != .readable or rsHiddenBool(stream, "\x00rsCloseRequested"))
        return self.throwError("TypeError", "ReadableStream is not in a readable state");
    try stream.setOwn(self.arena, self.root_shape, "\x00rsCloseRequested", Value.boolVal(true));
    if (rsPendingCount(stream, "\x00rsQueue", "\x00rsQueueHead") == 0) try rsFinishClosed(self, stream);
    return Value.undef();
}

fn rsControllerErrorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const stream = try rsControllerStream(self, this);
    try rsError(self, stream, if (args.len > 0) args[0] else Value.undef());
    return Value.undef();
}

fn rsControllerDesiredSizeGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const stream = try rsControllerStream(self, this);
    return switch (rsState(stream)) {
        .errored => Value.nul(),
        .closed => Value.num(0),
        .readable => blk: {
            const queued = rsPendingCount(stream, "\x00rsQueue", "\x00rsQueueHead");
            const high_water = if (stream.getOwn("\x00rsHighWaterMark")) |slot| if (slot.isNumber()) slot.asNum() else 1 else 1;
            break :blk Value.num(high_water - @as(f64, @floatFromInt(queued)));
        },
    };
}

fn rsReaderStream(self: *Interpreter, input: Value) EvalError!*value.Object {
    if (!input.isObject() or input.asObj().getOwn("\x00rrClosed") == null)
        return self.throwError("TypeError", "ReadableStreamDefaultReader method called on an incompatible receiver");
    const stream_value = input.asObj().getOwn("\x00rrStream") orelse Value.undef();
    if (!rsIsStream(stream_value)) return self.throwError("TypeError", "ReadableStreamDefaultReader has been released");
    return stream_value.asObj();
}

fn rsReaderRead(self: *Interpreter, reader: *value.Object) EvalError!Value {
    const stream = try rsReaderStream(self, Value.obj(reader));
    try stream.setOwn(self.arena, self.root_shape, "\x00rsDisturbed", Value.boolVal(true));
    if (try rsTakeHidden(self, stream, "\x00rsQueue", "\x00rsQueueHead")) |chunk| {
        if (rsHiddenBool(stream, "\x00rsCloseRequested") and rsPendingCount(stream, "\x00rsQueue", "\x00rsQueueHead") == 0) {
            try rsFinishClosed(self, stream);
        } else try rsCallPullIfNeeded(self, stream);
        return rsPromiseValue(self, .fulfilled, try self.iterResultObj(chunk, false));
    }
    return switch (rsState(stream)) {
        .closed => rsPromiseValue(self, .fulfilled, try self.iterResultObj(Value.undef(), true)),
        .errored => Value.obj(try promise.newRejectedPromise(self, stream.getOwn("\x00rsError") orelse Value.undef())),
        .readable => blk: {
            const request = try promise.newPromise(self);
            const requests = rsHiddenObject(stream, "\x00rsRequests") orelse return error.OutOfMemory;
            try requests.appendInternalElement(self.arena, Value.obj(request));
            try rsCallPullIfNeeded(self, stream);
            break :blk Value.obj(request);
        },
    };
}

fn rsReaderReadFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject() or this.asObj().getOwn("\x00rrClosed") == null)
        return self.throwError("TypeError", "ReadableStreamDefaultReader method called on an incompatible receiver");
    const stream_value = this.asObj().getOwn("\x00rrStream") orelse Value.undef();
    if (!rsIsStream(stream_value)) {
        const reason = try self.makeError("TypeError", "ReadableStreamDefaultReader has been released");
        return Value.obj(try promise.newRejectedPromise(self, reason));
    }
    return rsReaderRead(self, this.asObj());
}

fn rsCancelInternal(self: *Interpreter, stream: *value.Object, reason: Value) EvalError!Value {
    try stream.setOwn(self.arena, self.root_shape, "\x00rsDisturbed", Value.boolVal(true));
    if (rsState(stream) == .closed) return rsPromiseValue(self, .fulfilled, Value.undef());
    if (rsState(stream) == .errored)
        return Value.obj(try promise.newRejectedPromise(self, stream.getOwn("\x00rsError") orelse Value.undef()));
    const empty_queue = (try self.newArray()).asObj();
    try stream.setOwn(self.arena, self.root_shape, "\x00rsQueue", Value.obj(empty_queue));
    try rsSetHiddenIndex(self, stream, "\x00rsQueueHead", 0);
    try rsFinishClosed(self, stream);
    const cancel = stream.getOwn("\x00rsCancel") orelse Value.undef();
    if (!cancel.isCallable()) return rsPromiseValue(self, .fulfilled, Value.undef());
    const source = stream.getOwn("\x00rsSource") orelse Value.undef();
    const result = self.callValueWithThis(cancel, &.{reason}, source) catch |err| {
        if (err == error.Throw) {
            const thrown = self.exception;
            self.exception = Value.undef();
            return Value.obj(try promise.newRejectedPromise(self, thrown));
        }
        return err;
    };
    return promiseResolveValue(self, result);
}

fn rsReaderCancelFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject() or this.asObj().getOwn("\x00rrClosed") == null)
        return self.throwError("TypeError", "ReadableStreamDefaultReader method called on an incompatible receiver");
    const stream_value = this.asObj().getOwn("\x00rrStream") orelse Value.undef();
    if (!rsIsStream(stream_value)) {
        const reason = try self.makeError("TypeError", "ReadableStreamDefaultReader has been released");
        return Value.obj(try promise.newRejectedPromise(self, reason));
    }
    const stream = stream_value.asObj();
    return rsCancelInternal(self, stream, if (args.len > 0) args[0] else Value.undef());
}

fn rsReaderReleaseFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const stream = try rsReaderStream(self, this);
    if (rsPendingCount(stream, "\x00rsRequests", "\x00rsRequestsHead") != 0)
        return self.throwError("TypeError", "Cannot release a reader with pending read requests");
    const released = try self.makeError("TypeError", "ReadableStreamDefaultReader was released");
    if (rsReaderClosedPromise(this.asObj())) |closed| try rsRejectStoredPromise(self, closed, released);
    try stream.setOwn(self.arena, self.root_shape, "\x00rsReader", Value.undef());
    try this.asObj().setOwn(self.arena, self.root_shape, "\x00rrStream", Value.undef());
    return Value.undef();
}

fn rsReaderClosedGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject() or this.asObj().getOwn("\x00rrClosed") == null)
        return self.throwError("TypeError", "ReadableStreamDefaultReader method called on an incompatible receiver");
    return this.asObj().getOwn("\x00rrClosed") orelse Value.undef();
}

fn rsCreateReader(self: *Interpreter, stream: *value.Object) EvalError!*value.Object {
    if (rsReader(stream) != null) return self.throwError("TypeError", "ReadableStream is locked");
    const reader = try gc_mod.allocObj(self.arena);
    reader.* = .{};
    if (self.env.get("ReadableStreamDefaultReader")) |ctor| if (ctor.isObject()) {
        if (ctor.asObj().getOwn("prototype")) |proto| if (proto.isObject()) reader.setProtoAtomic(proto.asObj());
    };
    const closed = switch (rsState(stream)) {
        .readable => Value.obj(try promise.newPromise(self)),
        .closed => try rsPromiseValue(self, .fulfilled, Value.undef()),
        .errored => Value.obj(try promise.newRejectedPromise(self, stream.getOwn("\x00rsError") orelse Value.undef())),
    };
    try reader.setOwn(self.arena, self.root_shape, "\x00rrStream", Value.obj(stream));
    try reader.setOwn(self.arena, self.root_shape, "\x00rrClosed", closed);
    try stream.setOwn(self.arena, self.root_shape, "\x00rsReader", Value.obj(reader));
    return reader;
}

fn rsGetReaderFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const stream = try rsRequireStream(self, this);
    if (args.len > 0 and args[0].isObject()) {
        const mode = try self.getProperty(args[0], "mode");
        if (!mode.isUndefined()) return self.throwError("RangeError", "Only the default ReadableStream reader is supported");
    }
    return Value.obj(try rsCreateReader(self, stream));
}

fn rsLockedGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const stream = try rsRequireStream(self, this);
    return Value.boolVal(rsReader(stream) != null);
}

fn rsCancelFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const stream = try rsRequireStream(self, this);
    if (rsReader(stream) != null) {
        const reason = try self.makeError("TypeError", "Cannot cancel a locked ReadableStream");
        return Value.obj(try promise.newRejectedPromise(self, reason));
    }
    return rsCancelInternal(self, stream, if (args.len > 0) args[0] else Value.undef());
}

const RSAllocation = struct {
    stream: *value.Object,
    controller: *value.Object,
};

fn rsAllocateDefaultStream(
    self: *Interpreter,
    source: Value,
    pull: Value,
    cancel: Value,
    high_water: f64,
) EvalError!RSAllocation {
    const stream = try gc_mod.allocObj(self.arena);
    stream.* = .{};
    if (self.env.get("ReadableStream")) |ctor| if (ctor.isObject()) {
        if (ctor.asObj().getOwn("prototype")) |proto| if (proto.isObject()) stream.setProtoAtomic(proto.asObj());
    };
    const controller = try gc_mod.allocObj(self.arena);
    controller.* = .{};
    if (self.env.get("ReadableStreamDefaultController")) |ctor| if (ctor.isObject()) {
        if (ctor.asObj().getOwn("prototype")) |proto| if (proto.isObject()) controller.setProtoAtomic(proto.asObj());
    };
    const queue = (try self.newArray()).asObj();
    const requests = (try self.newArray()).asObj();
    try stream.setOwn(self.arena, self.root_shape, "\x00rsState", Value.str("readable"));
    try stream.setOwn(self.arena, self.root_shape, "\x00rsQueue", Value.obj(queue));
    try stream.setOwn(self.arena, self.root_shape, "\x00rsQueueHead", Value.num(0));
    try stream.setOwn(self.arena, self.root_shape, "\x00rsRequests", Value.obj(requests));
    try stream.setOwn(self.arena, self.root_shape, "\x00rsRequestsHead", Value.num(0));
    try stream.setOwn(self.arena, self.root_shape, "\x00rsReader", Value.undef());
    try stream.setOwn(self.arena, self.root_shape, "\x00rsDisturbed", Value.boolVal(false));
    try stream.setOwn(self.arena, self.root_shape, "\x00rsCloseRequested", Value.boolVal(false));
    try stream.setOwn(self.arena, self.root_shape, "\x00rsStarted", Value.boolVal(false));
    try stream.setOwn(self.arena, self.root_shape, "\x00rsPulling", Value.boolVal(false));
    try stream.setOwn(self.arena, self.root_shape, "\x00rsPullAgain", Value.boolVal(false));
    try stream.setOwn(self.arena, self.root_shape, "\x00rsHighWaterMark", Value.num(high_water));
    try stream.setOwn(self.arena, self.root_shape, "\x00rsSource", source);
    try stream.setOwn(self.arena, self.root_shape, "\x00rsPull", pull);
    try stream.setOwn(self.arena, self.root_shape, "\x00rsCancel", cancel);
    try stream.setOwn(self.arena, self.root_shape, "\x00rsController", Value.obj(controller));
    try controller.setOwn(self.arena, self.root_shape, "\x00rcStream", Value.obj(stream));
    return .{ .stream = stream, .controller = controller };
}

fn rsClosedStreamFromChunk(self: *Interpreter, chunk: ?Value) EvalError!*value.Object {
    const source = try self.newObject();
    const allocation = try rsAllocateDefaultStream(self, source, Value.undef(), Value.undef(), 1);
    try allocation.stream.setOwn(self.arena, self.root_shape, "\x00rsStarted", Value.boolVal(true));
    if (chunk) |value_| {
        const queue = rsHiddenObject(allocation.stream, "\x00rsQueue") orelse return error.OutOfMemory;
        try queue.appendInternalElement(self.arena, value_);
        try allocation.stream.setOwn(self.arena, self.root_shape, "\x00rsCloseRequested", Value.boolVal(true));
    } else {
        try rsFinishClosed(self, allocation.stream);
    }
    return allocation.stream;
}

fn rsTeeState(self: *Interpreter) EvalError!*value.Object {
    const native = self.active_native orelse return error.OutOfMemory;
    const state = native.elementAt(0) orelse return error.OutOfMemory;
    if (!state.isObject()) return error.OutOfMemory;
    return state.asObj();
}

fn rsTeeBranch(state: *value.Object, index: usize) ?*value.Object {
    const branches = rsHiddenObject(state, "\x00rstBranches") orelse return null;
    const branch = branches.elementAt(index) orelse return null;
    return if (rsIsStream(branch)) branch.asObj() else null;
}

fn rsTeeFinishPull(self: *Interpreter, state: *value.Object, rejected: ?Value) EvalError!void {
    const pull = state.getOwn("\x00rstPullPromise") orelse Value.undef();
    if (rejected) |reason|
        try rsRejectStoredPromise(self, pull, reason)
    else
        try rsResolveStoredPromise(self, pull, Value.undef());
    try state.setOwn(self.arena, self.root_shape, "\x00rstReading", Value.boolVal(false));
    try state.setOwn(self.arena, self.root_shape, "\x00rstPullPromise", Value.undef());
}

fn rsTeeSettleCancel(self: *Interpreter, state: *value.Object, rejected: ?Value) EvalError!void {
    if (!rsHiddenBool(state, "\x00rstCanceled1") and !rsHiddenBool(state, "\x00rstCanceled2")) return;
    const cancel = state.getOwn("\x00rstCancelPromise") orelse Value.undef();
    if (rejected) |reason|
        try rsRejectStoredPromise(self, cancel, reason)
    else
        try rsResolveStoredPromise(self, cancel, Value.undef());
}

fn rsTeeReadFulfilledFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len < 2 or !args[1].isObject()) return Value.undef();
    const state = args[1].asObj();
    const result = if (args.len > 0) args[0] else Value.undef();
    if (!result.isObject()) {
        const reason = try self.makeError("TypeError", "ReadableStream tee received an invalid read result");
        inline for (0..2) |index| if (rsTeeBranch(state, index)) |branch| try rsError(self, branch, reason);
        try rsTeeFinishPull(self, state, reason);
        try rsTeeSettleCancel(self, state, reason);
        return Value.undef();
    }
    const done = (try self.getProperty(result, "done")).toBoolean();
    if (done) {
        inline for (0..2) |index| {
            if (!rsHiddenBool(state, if (index == 0) "\x00rstCanceled1" else "\x00rstCanceled2")) {
                if (rsTeeBranch(state, index)) |branch| {
                    try branch.setOwn(self.arena, self.root_shape, "\x00rsCloseRequested", Value.boolVal(true));
                    if (rsPendingCount(branch, "\x00rsQueue", "\x00rsQueueHead") == 0) try rsFinishClosed(self, branch);
                }
            }
        }
        try rsTeeFinishPull(self, state, null);
        try rsTeeSettleCancel(self, state, null);
        return Value.undef();
    }
    const chunk = try self.getProperty(result, "value");
    inline for (0..2) |index| {
        if (!rsHiddenBool(state, if (index == 0) "\x00rstCanceled1" else "\x00rstCanceled2")) {
            if (rsTeeBranch(state, index)) |branch| {
                const controller = branch.getOwn("\x00rsController") orelse Value.undef();
                _ = try rsControllerEnqueueFn(@ptrCast(self), controller, &.{chunk});
            }
        }
    }
    try rsTeeFinishPull(self, state, null);
    return Value.undef();
}

fn rsTeeReadRejectedFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len < 2 or !args[1].isObject()) return Value.undef();
    const state = args[1].asObj();
    const reason = if (args.len > 0) args[0] else Value.undef();
    inline for (0..2) |index| if (rsTeeBranch(state, index)) |branch| try rsError(self, branch, reason);
    try rsTeeFinishPull(self, state, reason);
    try rsTeeSettleCancel(self, state, reason);
    return Value.undef();
}

fn rsTeePullFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const state = try rsTeeState(self);
    if (rsHiddenBool(state, "\x00rstReading")) return state.getOwn("\x00rstPullPromise") orelse Value.undef();
    const reader_value = state.getOwn("\x00rstReader") orelse Value.undef();
    if (!reader_value.isObject()) return self.throwError("TypeError", "ReadableStream tee reader is unavailable");
    const pull = try promise.newPromise(self);
    try state.setOwn(self.arena, self.root_shape, "\x00rstReading", Value.boolVal(true));
    try state.setOwn(self.arena, self.root_shape, "\x00rstPullPromise", Value.obj(pull));
    const read = try rsReaderRead(self, reader_value.asObj());
    const on_fulfilled = try rsNativeHandler(self, rsTeeReadFulfilledFn, "ReadableStream tee read fulfilled");
    const on_rejected = try rsNativeHandler(self, rsTeeReadRejectedFn, "ReadableStream tee read rejected");
    try promise.performThenDetached(self, promise.promiseOf(read).?, on_fulfilled, on_rejected, Value.obj(state));
    return Value.obj(pull);
}

fn rsTeeCancelSettledFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len < 2 or !args[1].isObject()) return Value.undef();
    try rsTeeSettleCancel(self, args[1].asObj(), null);
    return Value.undef();
}

fn rsTeeCancelRejectedFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len < 2 or !args[1].isObject()) return Value.undef();
    try rsTeeSettleCancel(self, args[1].asObj(), if (args.len > 0) args[0] else Value.undef());
    return Value.undef();
}

fn rsTeeCancelBranch(self: *Interpreter, state: *value.Object, index: usize, reason: Value) EvalError!Value {
    const canceled_key: []const u8 = if (index == 0) "\x00rstCanceled1" else "\x00rstCanceled2";
    const reason_key: []const u8 = if (index == 0) "\x00rstReason1" else "\x00rstReason2";
    try state.setOwn(self.arena, self.root_shape, canceled_key, Value.boolVal(true));
    try state.setOwn(self.arena, self.root_shape, reason_key, reason);
    const cancel_promise = state.getOwn("\x00rstCancelPromise") orelse Value.undef();
    if (!rsHiddenBool(state, "\x00rstCanceled1") or !rsHiddenBool(state, "\x00rstCanceled2")) return cancel_promise;
    const reader = state.getOwn("\x00rstReader") orelse Value.undef();
    if (!reader.isObject()) return cancel_promise;
    const reasons = try self.newArray();
    try reasons.asObj().appendElement(self.arena, state.getOwn("\x00rstReason1") orelse Value.undef());
    try reasons.asObj().appendElement(self.arena, state.getOwn("\x00rstReason2") orelse Value.undef());
    const underlying = try rsCancelInternal(self, try rsReaderStream(self, reader), reasons);
    const on_fulfilled = try rsNativeHandler(self, rsTeeCancelSettledFn, "ReadableStream tee cancel fulfilled");
    const on_rejected = try rsNativeHandler(self, rsTeeCancelRejectedFn, "ReadableStream tee cancel rejected");
    try promise.performThenDetached(self, promise.promiseOf(underlying).?, on_fulfilled, on_rejected, Value.obj(state));
    return cancel_promise;
}

fn rsTeeCancel1Fn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    return rsTeeCancelBranch(self, try rsTeeState(self), 0, if (args.len > 0) args[0] else Value.undef());
}

fn rsTeeCancel2Fn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    return rsTeeCancelBranch(self, try rsTeeState(self), 1, if (args.len > 0) args[0] else Value.undef());
}

fn rsTeeStreams(self: *Interpreter, stream: *value.Object) EvalError![2]*value.Object {
    if (rsReader(stream) != null) return self.throwError("TypeError", "ReadableStream is locked");
    const reader = try rsCreateReader(self, stream);
    const state = try gc_mod.allocObj(self.arena);
    state.* = .{ .proto = null, .proto_explicit_null = true };
    const branches = (try self.newArray()).asObj();
    const cancel_promise = try promise.newPromise(self);
    try state.setOwn(self.arena, self.root_shape, "\x00rstReader", Value.obj(reader));
    try state.setOwn(self.arena, self.root_shape, "\x00rstBranches", Value.obj(branches));
    try state.setOwn(self.arena, self.root_shape, "\x00rstReading", Value.boolVal(false));
    try state.setOwn(self.arena, self.root_shape, "\x00rstPullPromise", Value.undef());
    try state.setOwn(self.arena, self.root_shape, "\x00rstCancelPromise", Value.obj(cancel_promise));
    try state.setOwn(self.arena, self.root_shape, "\x00rstCanceled1", Value.boolVal(false));
    try state.setOwn(self.arena, self.root_shape, "\x00rstCanceled2", Value.boolVal(false));
    try state.setOwn(self.arena, self.root_shape, "\x00rstReason1", Value.undef());
    try state.setOwn(self.arena, self.root_shape, "\x00rstReason2", Value.undef());

    const pull = try rsNativeHandler(self, rsTeePullFn, "ReadableStream tee pull");
    try pull.asObj().appendInternalElement(self.arena, Value.obj(state));
    const cancel1 = try rsNativeHandler(self, rsTeeCancel1Fn, "ReadableStream tee cancel branch 1");
    try cancel1.asObj().appendInternalElement(self.arena, Value.obj(state));
    const cancel2 = try rsNativeHandler(self, rsTeeCancel2Fn, "ReadableStream tee cancel branch 2");
    try cancel2.asObj().appendInternalElement(self.arena, Value.obj(state));
    var result: [2]*value.Object = undefined;
    inline for (0..2) |index| {
        const source = try self.newObject();
        try source.asObj().setOwn(self.arena, self.root_shape, "pull", pull);
        try source.asObj().setOwn(self.arena, self.root_shape, "cancel", if (index == 0) cancel1 else cancel2);
        const allocation = try rsAllocateDefaultStream(self, source, pull, if (index == 0) cancel1 else cancel2, 1);
        try allocation.stream.setOwn(self.arena, self.root_shape, "\x00rsStarted", Value.boolVal(true));
        try branches.appendElement(self.arena, Value.obj(allocation.stream));
        result[index] = allocation.stream;
    }
    return result;
}

fn rsTeeFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const branches = try rsTeeStreams(self, try rsRequireStream(self, this));
    const result = try self.newArray();
    try result.asObj().appendElement(self.arena, Value.obj(branches[0]));
    try result.asObj().appendElement(self.arena, Value.obj(branches[1]));
    return result;
}

fn rsConstructorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (self.new_target.isUndefined()) return self.throwError("TypeError", "Failed to construct 'ReadableStream': Please use the 'new' operator");
    const source = if (args.len > 0 and !args[0].isUndefined()) args[0] else try self.newObject();
    if (!source.isObject()) return self.throwError("TypeError", "ReadableStream underlying source must be an object");
    const source_type = try self.getProperty(source, "type");
    if (!source_type.isUndefined()) return self.throwError("RangeError", "Readable byte streams are not implemented");
    const start = try self.getProperty(source, "start");
    const pull = try self.getProperty(source, "pull");
    const cancel = try self.getProperty(source, "cancel");
    inline for (.{ start, pull, cancel }) |algorithm| {
        if (!algorithm.isUndefined() and !algorithm.isCallable())
            return self.throwError("TypeError", "ReadableStream underlying source algorithm is not callable");
    }
    var high_water: f64 = 1;
    if (args.len > 1 and args[1].isObject()) {
        const hwm = try self.getProperty(args[1], "highWaterMark");
        if (!hwm.isUndefined()) high_water = try self.toNumberV(hwm);
    }
    if (std.math.isNan(high_water) or high_water < 0)
        return self.throwError("RangeError", "ReadableStream highWaterMark must be non-negative");

    const allocation = try rsAllocateDefaultStream(self, source, pull, cancel, high_water);
    const stream = allocation.stream;
    const controller = allocation.controller;

    const started = if (start.isCallable()) self.callValueWithThis(start, &.{Value.obj(controller)}, source) catch |err| {
        if (err == error.Throw) {
            const reason = self.exception;
            self.exception = Value.undef();
            try rsError(self, stream, reason);
            return Value.obj(stream);
        }
        return err;
    } else Value.undef();
    const wrapped = try promiseResolveValue(self, started);
    const on_fulfilled = try rsNativeHandler(self, rsStartFulfilledFn, "ReadableStream start fulfilled");
    const on_rejected = try rsNativeHandler(self, rsStartRejectedFn, "ReadableStream start rejected");
    try promise.performThenDetached(self, promise.promiseOf(wrapped).?, on_fulfilled, on_rejected, Value.obj(stream));
    return Value.obj(stream);
}

fn rsReaderConstructorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (self.new_target.isUndefined())
        return self.throwError("TypeError", "Failed to construct 'ReadableStreamDefaultReader': Please use the 'new' operator");
    const stream_value = if (args.len > 0) args[0] else Value.undef();
    const stream = try rsRequireStream(self, stream_value);
    return Value.obj(try rsCreateReader(self, stream));
}

fn rsIllegalConstructorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    return self.throwError("TypeError", "Illegal constructor");
}

fn installReadableStream(env: *Environment, rs: *Shape, object_proto: *value.Object) EvalError!void {
    const a = env.arena;
    const stream_proto = try gc_mod.allocObj(a);
    stream_proto.* = .{ .proto = object_proto };
    try setNativeGetter(a, rs, stream_proto, "locked", rsLockedGet);
    try setNative(a, rs, stream_proto, "cancel", 1, rsCancelFn);
    try setNative(a, rs, stream_proto, "getReader", 0, rsGetReaderFn);
    try setNative(a, rs, stream_proto, "tee", 0, rsTeeFn);

    const reader_proto = try gc_mod.allocObj(a);
    reader_proto.* = .{ .proto = object_proto };
    try setNativeGetter(a, rs, reader_proto, "closed", rsReaderClosedGet);
    try setNative(a, rs, reader_proto, "read", 0, rsReaderReadFn);
    try setNative(a, rs, reader_proto, "cancel", 1, rsReaderCancelFn);
    try setNative(a, rs, reader_proto, "releaseLock", 0, rsReaderReleaseFn);

    const controller_proto = try gc_mod.allocObj(a);
    controller_proto.* = .{ .proto = object_proto };
    try setNativeGetter(a, rs, controller_proto, "desiredSize", rsControllerDesiredSizeGet);
    try setNative(a, rs, controller_proto, "enqueue", 1, rsControllerEnqueueFn);
    try setNative(a, rs, controller_proto, "close", 0, rsControllerCloseFn);
    try setNative(a, rs, controller_proto, "error", 1, rsControllerErrorFn);

    if (env.get("Symbol")) |sym| if (sym.isObject()) {
        if (sym.asObj().getOwn("toStringTag")) |tag| if (tag.isObject() and tag.asObj().is_symbol) {
            inline for (.{ .{ stream_proto, "ReadableStream" }, .{ reader_proto, "ReadableStreamDefaultReader" }, .{ controller_proto, "ReadableStreamDefaultController" } }) |entry| {
                try entry[0].setOwn(a, rs, tag.asObj().symbolKey(), Value.str(entry[1]));
                try entry[0].setAttr(a, tag.asObj().symbolKey(), .{ .writable = false, .enumerable = false, .configurable = true });
            }
        };
    };

    const stream_ctor = try gc_mod.allocObj(a);
    stream_ctor.* = .{ .native = rsConstructorFn, .native_ctor = true };
    try installNativeProps(a, rs, stream_ctor, "ReadableStream", 0);
    try stream_ctor.setOwn(a, rs, "prototype", Value.obj(stream_proto));
    try stream_ctor.setAttr(a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
    try setConstructor(a, rs, stream_proto, stream_ctor);
    try env.put("ReadableStream", Value.obj(stream_ctor));

    inline for (.{ .{ "ReadableStreamDefaultReader", reader_proto, rsReaderConstructorFn }, .{ "ReadableStreamDefaultController", controller_proto, rsIllegalConstructorFn } }) |entry| {
        const ctor = try gc_mod.allocObj(a);
        ctor.* = .{ .native = entry[2], .native_ctor = true };
        try installNativeProps(a, rs, ctor, entry[0], 0);
        try ctor.setOwn(a, rs, "prototype", Value.obj(entry[1]));
        try ctor.setAttr(a, "prototype", .{ .writable = false, .enumerable = false, .configurable = false });
        try setConstructor(a, rs, entry[1], ctor);
        try env.put(entry[0], Value.obj(ctor));
    }
}

pub const ReadableStreamConsumeKind = enum {
    array_buffer,
    bytes,
    text,
    json,
    blob,
    form_data,
};

pub const ReadableStreamByteSink = struct {
    context: *anyopaque,
    write: *const fn (*anyopaque, *Interpreter, []const u8) EvalError!void,
    finish: *const fn (*anyopaque, *Interpreter) EvalError!Value,
    abort: *const fn (*anyopaque) void,
};

fn rscByteSink(state: *value.Object) ?*ReadableStreamByteSink {
    return @ptrCast(@alignCast(state.private_data orelse return null));
}

fn rscStateValue(state: *value.Object, key: []const u8) Value {
    return state.getOwn(key) orelse Value.undef();
}

fn rscOutputPromise(state: *value.Object) ?*promise.Promise {
    return promise.promiseOf(rscStateValue(state, "\x00rscOutput"));
}

fn rscRelease(self: *Interpreter, state: *value.Object) EvalError!void {
    const reader_value = rscStateValue(state, "\x00rscReader");
    if (!reader_value.isObject()) return;
    const reader = reader_value.asObj();
    const stream_value = reader.getOwn("\x00rrStream") orelse Value.undef();
    if (rsIsStream(stream_value)) try stream_value.asObj().setOwn(self.arena, self.root_shape, "\x00rsReader", Value.undef());
    try reader.setOwn(self.arena, self.root_shape, "\x00rrStream", Value.undef());
}

fn rscReject(self: *Interpreter, state: *value.Object, reason: Value) EvalError!void {
    if (rsHiddenBool(state, "\x00rscSettled")) return;
    try state.setOwn(self.arena, self.root_shape, "\x00rscSettled", Value.boolVal(true));
    if (rscByteSink(state)) |sink| sink.abort(sink.context);
    try rscRelease(self, state);
    if (rscOutputPromise(state)) |output| try promise.reject(self, output, reason);
}

fn rscResolve(self: *Interpreter, state: *value.Object, result: Value) EvalError!void {
    if (rsHiddenBool(state, "\x00rscSettled")) return;
    try state.setOwn(self.arena, self.root_shape, "\x00rscSettled", Value.boolVal(true));
    try rscRelease(self, state);
    if (rscOutputPromise(state)) |output| try promise.resolve(self, output, result);
}

fn rscBufferSourceDetached(input: Value) bool {
    if (!input.isObject()) return false;
    const object = input.asObj();
    if (object.arrayBuffer()) |buffer| return buffer.isDetached();
    if (object.typedArray()) |array| return if (array.buffer.arrayBuffer()) |buffer| buffer.isDetached() else false;
    if (object.dataView()) |view| return if (view.buffer.arrayBuffer()) |buffer| buffer.isDetached() else false;
    return false;
}

fn rscNormalizeChunk(self: *Interpreter, input: Value) EvalError!Value {
    if (input.isString()) return try Value.strAlloc(self.arena, try input.asWtf8(self.arena));
    if (rscBufferSourceDetached(input)) return self.throwError("TypeError", "ReadableStream chunk views a detached ArrayBuffer");
    if (bufferSourceBytes(input)) |bytes| {
        const copy = try self.makeArrayBuffer(bytes.len);
        if (bytes.len != 0) @memcpy(copy.arrayBuffer().?.bytes()[0..bytes.len], bytes);
        return Value.obj(copy);
    }
    return self.throwError("TypeError", "ReadableStream chunk must be a string or BufferSource");
}

fn rscMeasureBytes(self: *Interpreter, chunks: *value.Object) EvalError!usize {
    const items = try chunks.internalElementsSnapshot(self.arena);
    var total: usize = 0;
    for (items) |chunk| {
        const bytes = if (chunk.isString()) try wtf8ToUtf8Bytes(self.arena, try chunk.asWtf8(self.arena)) else bufferSourceBytes(chunk) orelse
            return self.throwError("TypeError", "ReadableStream produced an invalid chunk");
        total = std.math.add(usize, total, bytes.len) catch return self.throwError("RangeError", "ReadableStream body is too large");
    }
    return total;
}

fn rscWriteBytes(self: *Interpreter, chunks: *value.Object, output: []u8) EvalError!void {
    const items = try chunks.internalElementsSnapshot(self.arena);
    var offset: usize = 0;
    for (items) |chunk| {
        const bytes = if (chunk.isString()) try wtf8ToUtf8Bytes(self.arena, try chunk.asWtf8(self.arena)) else bufferSourceBytes(chunk).?;
        if (bytes.len != 0) @memcpy(output[offset .. offset + bytes.len], bytes);
        offset += bytes.len;
    }
}

fn rscCollectBytes(self: *Interpreter, chunks: *value.Object) EvalError![]u8 {
    const output = try self.arena.alloc(u8, try rscMeasureBytes(self, chunks));
    try rscWriteBytes(self, chunks, output);
    return output;
}

fn rscAsciiIndexOfIgnoreCase(haystack: []const u8, needle: []const u8) ?usize {
    if (needle.len == 0) return 0;
    if (needle.len > haystack.len) return null;
    var index: usize = 0;
    while (index + needle.len <= haystack.len) : (index += 1) {
        if (std.ascii.eqlIgnoreCase(haystack[index .. index + needle.len], needle)) return index;
    }
    return null;
}

fn rscMultipartBoundary(self: *Interpreter, content_type: []const u8) EvalError![]const u8 {
    var boundary = std.mem.trim(u8, content_type, " \t\r\n");
    if (rscAsciiIndexOfIgnoreCase(boundary, "boundary=")) |at| {
        boundary = std.mem.trim(u8, boundary[at + "boundary=".len ..], " \t\r\n");
        if (std.mem.indexOfScalar(u8, boundary, ';')) |end| boundary = std.mem.trim(u8, boundary[0..end], " \t\r\n");
    }
    if (boundary.len >= 2 and boundary[0] == '"' and boundary[boundary.len - 1] == '"') boundary = boundary[1 .. boundary.len - 1];
    if (boundary.len == 0) return self.throwError("TypeError", "multipart/form-data boundary is missing");
    if (boundary.len > 70 or std.mem.indexOfAny(u8, boundary, "\r\n") != null)
        return self.throwError("TypeError", "multipart/form-data boundary is invalid");
    return boundary;
}

fn rscHeaderValue(headers: []const u8, wanted: []const u8) ?[]const u8 {
    var lines = std.mem.splitSequence(u8, headers, "\r\n");
    while (lines.next()) |line| {
        const colon = std.mem.indexOfScalar(u8, line, ':') orelse continue;
        const name = std.mem.trim(u8, line[0..colon], " \t");
        if (std.ascii.eqlIgnoreCase(name, wanted)) return std.mem.trim(u8, line[colon + 1 ..], " \t");
    }
    return null;
}

fn rscDispositionParameter(disposition: []const u8, wanted: []const u8) ?[]const u8 {
    var parts = std.mem.splitScalar(u8, disposition, ';');
    _ = parts.next();
    while (parts.next()) |raw_part| {
        const part = std.mem.trim(u8, raw_part, " \t");
        const equal = std.mem.indexOfScalar(u8, part, '=') orelse continue;
        if (!std.ascii.eqlIgnoreCase(std.mem.trim(u8, part[0..equal], " \t"), wanted)) continue;
        var result = std.mem.trim(u8, part[equal + 1 ..], " \t");
        if (result.len >= 2 and result[0] == '"' and result[result.len - 1] == '"') result = result[1 .. result.len - 1];
        return result;
    }
    return null;
}

fn rscParseMultipart(self: *Interpreter, bytes: []const u8, content_type: []const u8) EvalError!Value {
    const boundary = try rscMultipartBoundary(self, content_type);
    const marker = try std.fmt.allocPrint(self.arena, "--{s}", .{boundary});
    const body_marker = try std.fmt.allocPrint(self.arena, "\r\n--{s}", .{boundary});
    const allocation = try fdAllocate(self);
    var cursor: usize = 0;
    var saw_boundary = false;
    var saw_terminal = false;
    while (std.mem.indexOfPos(u8, bytes, cursor, marker)) |marker_at| {
        saw_boundary = true;
        var part_start = marker_at + marker.len;
        if (part_start + 2 <= bytes.len and std.mem.eql(u8, bytes[part_start .. part_start + 2], "--")) {
            saw_terminal = true;
            break;
        }
        if (part_start + 2 > bytes.len or !std.mem.eql(u8, bytes[part_start .. part_start + 2], "\r\n"))
            return self.throwError("TypeError", "Malformed multipart/form-data body");
        part_start += 2;
        const header_end = std.mem.indexOfPos(u8, bytes, part_start, "\r\n\r\n") orelse
            return self.throwError("TypeError", "Malformed multipart/form-data headers");
        const body_start = header_end + 4;
        const body_end = std.mem.indexOfPos(u8, bytes, body_start, body_marker) orelse
            return self.throwError("TypeError", "Malformed multipart/form-data terminator");
        const headers = bytes[part_start..header_end];
        const disposition = rscHeaderValue(headers, "content-disposition") orelse
            return self.throwError("TypeError", "Multipart part is missing Content-Disposition");
        const name = rscDispositionParameter(disposition, "name") orelse
            return self.throwError("TypeError", "Multipart part is missing a name");
        const body = bytes[body_start..body_end];
        if (rscDispositionParameter(disposition, "filename")) |filename| {
            const raw_type = rscHeaderValue(headers, "content-type") orelse "application/octet-stream";
            const normalized_type = try blobNormalizeType(self, raw_type);
            const file = try blobMake(self, "File", body, normalized_type);
            try file.setOwn(self.arena, self.root_shape, "\x00filename", try Value.strAlloc(self.arena, try utf8DecodeReplacing(self, filename)));
            try file.setOwn(self.arena, self.root_shape, "\x00filemod", Value.num(0));
            try fdPushValue(self, allocation.list, try utf8DecodeReplacing(self, name), Value.obj(file));
        } else {
            try fdPushString(self, allocation.list, try utf8DecodeReplacing(self, name), try utf8DecodeReplacing(self, body));
        }
        cursor = body_end + 2;
    }
    if (!saw_boundary or !saw_terminal) return self.throwError("TypeError", "Malformed multipart/form-data boundary");
    return Value.obj(allocation.obj);
}

fn rscContentType(self: *Interpreter, input: Value) EvalError![]const u8 {
    if (input.isUndefined() or input.isNull()) return "";
    if (rscBufferSourceDetached(input)) return self.throwError("TypeError", "FormData content type views a detached ArrayBuffer");
    if (bufferSourceBytes(input)) |bytes| return bytes;
    return wtf8ToUtf8Bytes(self.arena, try self.toStringWtf8(input));
}

fn rscFinalize(self: *Interpreter, state: *value.Object) EvalError!Value {
    if (rscByteSink(state)) |sink| return sink.finish(sink.context, self);
    const chunks = rsHiddenObject(state, "\x00rscChunks") orelse return error.OutOfMemory;
    const kind_value = rscStateValue(state, "\x00rscKind");
    const kind_name = if (kind_value.isString()) kind_value.asStr() else "bytes";
    if (std.mem.eql(u8, kind_name, "array_buffer")) {
        const buffer = try self.makeArrayBuffer(try rscMeasureBytes(self, chunks));
        try rscWriteBytes(self, chunks, buffer.arrayBuffer().?.bytes());
        return Value.obj(buffer);
    }
    if (std.mem.eql(u8, kind_name, "bytes")) {
        const array = try newTypedArray(self, .u8, try rscMeasureBytes(self, chunks));
        try rscWriteBytes(self, chunks, array.typedArray().?.buffer.arrayBuffer().?.bytes());
        return Value.obj(array);
    }
    if (std.mem.eql(u8, kind_name, "blob")) {
        const buffer = try self.makeArrayBuffer(try rscMeasureBytes(self, chunks));
        try rscWriteBytes(self, chunks, buffer.arrayBuffer().?.bytes());
        const content_type = try rscContentType(self, rscStateValue(state, "\x00rscContentType"));
        return Value.obj(try blobMakeWithBuffer(self, "Blob", buffer, try blobNormalizeType(self, content_type)));
    }
    const bytes = try rscCollectBytes(self, chunks);
    if (std.mem.eql(u8, kind_name, "form_data")) {
        const content_type = try rscContentType(self, rscStateValue(state, "\x00rscContentType"));
        if (content_type.len == 0 or rscAsciiIndexOfIgnoreCase(content_type, "application/x-www-form-urlencoded") != null)
            return formDataCreateFromURLQuery(self, bytes);
        return rscParseMultipart(self, bytes, content_type);
    }
    const text_bytes = if (bytes.len >= 3 and bytes[0] == 0xEF and bytes[1] == 0xBB and bytes[2] == 0xBF) bytes[3..] else bytes;
    const decoded = try Value.strAlloc(self.arena, try utf8DecodeReplacing(self, text_bytes));
    if (std.mem.eql(u8, kind_name, "text")) return decoded;
    const json = self.env.get("JSON") orelse return self.throwError("Error", "JSON is unavailable");
    const parse = try self.getProperty(json, "parse");
    return self.callValueWithThis(parse, &.{decoded}, json);
}

fn rscStep(self: *Interpreter, state: *value.Object) EvalError!void {
    if (rsHiddenBool(state, "\x00rscSettled")) return;
    const reader_value = rscStateValue(state, "\x00rscReader");
    if (!reader_value.isObject()) return self.throwError("TypeError", "ReadableStream reader is unavailable");
    const read_result = try rsReaderRead(self, reader_value.asObj());
    const read_promise = promise.promiseOf(read_result) orelse return self.throwError("TypeError", "ReadableStream reader returned a non-Promise");
    try promise.performThenDetached(
        self,
        read_promise,
        rscStateValue(state, "\x00rscFulfilled"),
        rscStateValue(state, "\x00rscRejected"),
        Value.obj(state),
    );
}

fn rscReadFulfilled(self: *Interpreter, result: Value, state: *value.Object) EvalError!void {
    if (!result.isObject()) return self.throwError("TypeError", "ReadableStream read result is not an object");
    if ((try self.getProperty(result, "done")).toBoolean()) {
        try rscResolve(self, state, try rscFinalize(self, state));
        return;
    }
    const chunk = try rscNormalizeChunk(self, try self.getProperty(result, "value"));
    if (rscByteSink(state)) |sink| {
        const bytes = if (chunk.isString()) try wtf8ToUtf8Bytes(self.arena, try chunk.asWtf8(self.arena)) else bufferSourceBytes(chunk) orelse
            return self.throwError("TypeError", "ReadableStream produced an invalid chunk");
        try sink.write(sink.context, self, bytes);
        try rscStep(self, state);
        return;
    }
    const chunks = rsHiddenObject(state, "\x00rscChunks") orelse return error.OutOfMemory;
    try chunks.appendInternalElement(self.arena, chunk);
    try rscStep(self, state);
}

fn rscReadFulfilledFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len < 2 or !args[1].isObject()) return Value.undef();
    const state = args[1].asObj();
    rscReadFulfilled(self, if (args.len > 0) args[0] else Value.undef(), state) catch |err| {
        if (err != error.Throw) {
            if (rscByteSink(state)) |sink| sink.abort(sink.context);
            return err;
        }
        const reason = self.exception;
        self.exception = Value.undef();
        try rscReject(self, state, reason);
    };
    return Value.undef();
}

fn rscReadRejectedFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len < 2 or !args[1].isObject()) return Value.undef();
    try rscReject(self, args[1].asObj(), if (args.len > 0) args[0] else Value.undef());
    return Value.undef();
}

/// Drain a genuine realm-local default ReadableStream and convert its chunks.
/// Brand errors are synchronous; locked/error/parse failures reject the returned
/// intrinsic Promise, matching the pinned JSC builtins used by Home and Bun.
pub fn readableStreamConsume(
    self: *Interpreter,
    stream_value: Value,
    kind: ReadableStreamConsumeKind,
    content_type: Value,
) EvalError!Value {
    return readableStreamConsumeInner(self, stream_value, kind, content_type, null);
}

pub fn readableStreamConsumeToSink(
    self: *Interpreter,
    stream_value: Value,
    sink: *ReadableStreamByteSink,
) EvalError!Value {
    return readableStreamConsumeInner(self, stream_value, .bytes, Value.undef(), sink);
}

fn readableStreamConsumeInner(
    self: *Interpreter,
    stream_value: Value,
    kind: ReadableStreamConsumeKind,
    content_type: Value,
    sink: ?*ReadableStreamByteSink,
) EvalError!Value {
    const stream = try rsRequireStream(self, stream_value);
    if (rsReader(stream) != null) {
        const reason = try self.makeError("TypeError", "ReadableStream is locked");
        return Value.obj(try promise.newRejectedPromise(self, reason));
    }
    const reader = try rsCreateReader(self, stream);
    const output = try promise.newPromise(self);
    const state = try gc_mod.allocObj(self.arena);
    state.* = .{ .proto = null, .proto_explicit_null = true };
    state.private_data = if (sink) |configured| @ptrCast(configured) else null;
    const chunks = (try self.newArray()).asObj();
    const fulfilled = try rsNativeHandler(self, rscReadFulfilledFn, "ReadableStream consume fulfilled");
    const rejected = try rsNativeHandler(self, rscReadRejectedFn, "ReadableStream consume rejected");
    try state.setOwn(self.arena, self.root_shape, "\x00rscOutput", Value.obj(output));
    try state.setOwn(self.arena, self.root_shape, "\x00rscReader", Value.obj(reader));
    try state.setOwn(self.arena, self.root_shape, "\x00rscChunks", Value.obj(chunks));
    const kind_name = switch (kind) {
        .array_buffer => Value.str("array_buffer"),
        .bytes => Value.str("bytes"),
        .text => Value.str("text"),
        .json => Value.str("json"),
        .blob => Value.str("blob"),
        .form_data => Value.str("form_data"),
    };
    try state.setOwn(self.arena, self.root_shape, "\x00rscKind", kind_name);
    try state.setOwn(self.arena, self.root_shape, "\x00rscContentType", content_type);
    try state.setOwn(self.arena, self.root_shape, "\x00rscFulfilled", fulfilled);
    try state.setOwn(self.arena, self.root_shape, "\x00rscRejected", rejected);
    try state.setOwn(self.arena, self.root_shape, "\x00rscSettled", Value.boolVal(false));
    try output.setOwn(self.arena, self.root_shape, "\x00readableStreamConsume", Value.obj(state));
    rscStep(self, state) catch |err| {
        if (err != error.Throw) return err;
        const reason = self.exception;
        self.exception = Value.undef();
        try rscReject(self, state, reason);
    };
    return Value.obj(output);
}

// ===== Request / Response (Fetch bodies) =============================
// Response state: \x00Rstatus/RstatusText/Rheaders/Rtype/Rurl/Rredirected/
// Rbody(ArrayBuffer|ReadableStream|null)/RbodyUsed. Request state: \x00Qurl/Qmethod/Qheaders/
// Qbody/QbodyUsed + the request-init string slots (cache/credentials/…).
const BodyExtract = struct { bytes: ?[]const u8, stream: ?Value = null, ctype: ?[]const u8 };
fn fetchExtractBody(self: *Interpreter, body_v: Value) EvalError!BodyExtract {
    if (body_v.isUndefined() or body_v.isNull()) return .{ .bytes = null, .ctype = null };
    if (rsIsStream(body_v)) return .{ .bytes = null, .stream = body_v, .ctype = null };
    if (blobIsBlob(body_v)) {
        if (!blobHasBytes(body_v.asObj())) return self.throwError("TypeError", "Native Blob data is unavailable");
        const tv = body_v.asObj().getOwn("\x00blobtype");
        const ct: ?[]const u8 = if (tv != null and tv.?.isString() and tv.?.asStr().len > 0) tv.?.asStr() else null;
        return .{ .bytes = blobBytesOf(body_v.asObj()), .ctype = ct };
    }
    if (body_v.isObject() and body_v.asObj().getOwn("\x00usp") != null) {
        return .{ .bytes = try uspToString(self, body_v), .ctype = "application/x-www-form-urlencoded;charset=UTF-8" };
    }
    if (bufferSourceBytes(body_v)) |b| return .{ .bytes = b, .ctype = null };
    return .{ .bytes = try wtf8ToUtf8Bytes(self.arena, try self.toStringWtf8(body_v)), .ctype = "text/plain;charset=UTF-8" };
}
fn fetchMakeHeaders(self: *Interpreter, init_v: Value, guard: fetch_headers.Guard) EvalError!*value.Object {
    const created = try fetchHeadersCreateEmptyGuarded(self, guard);
    if (!init_v.isUndefined() and !init_v.isNull()) try fetchHeadersFill(self, created, init_v);
    return created.asObj();
}
fn fetchHeadersHasName(self: *Interpreter, headers: *value.Object, lower: []const u8) EvalError!bool {
    const record = try headersRecord(self, Value.obj(headers));
    return record.has(lower) catch |err| return headersThrow(self, err);
}
fn fetchStoreBody(self: *Interpreter, obj: *value.Object, slot: []const u8, body: BodyExtract) EvalError!void {
    if (body.stream) |stream| {
        try obj.setOwn(self.arena, self.root_shape, slot, stream);
    } else if (body.bytes) |b| {
        const buf = try self.makeArrayBuffer(b.len);
        if (b.len > 0) @memcpy(buf.arrayBuffer().?.bytes()[0..b.len], b);
        try obj.setOwn(self.arena, self.root_shape, slot, Value.obj(buf));
    } else {
        try obj.setOwn(self.arena, self.root_shape, slot, Value.nul());
    }
}
fn fetchBodyObject(self: *Interpreter, this: Value) EvalError!*value.Object {
    if (!this.isObject()) return self.throwError("TypeError", "Body method called on an incompatible receiver");
    const object = this.asObj();
    if (object.getOwn("\x00Rbody") == null and object.getOwn("\x00Qbody") == null)
        return self.throwError("TypeError", "Body method called on an incompatible receiver");
    return object;
}
fn fetchBodyValue(object: *value.Object) Value {
    return object.getOwn("\x00Rbody") orelse object.getOwn("\x00Qbody") orelse Value.undef();
}
fn fetchBodyUsedSlot(object: *value.Object) []const u8 {
    return if (object.getOwn("\x00Rbody") != null) "\x00RbodyUsed" else "\x00QbodyUsed";
}
fn fetchBodyIsUsed(object: *value.Object) bool {
    if (object.getOwn(fetchBodyUsedSlot(object))) |used| if (used.toBoolean()) return true;
    const body = fetchBodyValue(object);
    return rsIsStream(body) and rsHiddenBool(body.asObj(), "\x00rsDisturbed");
}
fn fetchBodyContentType(self: *Interpreter, object: *value.Object) EvalError!Value {
    const headers_value = object.getOwn("\x00Rheaders") orelse object.getOwn("\x00Qheaders") orelse return Value.str("");
    if (!headers_value.isObject()) return Value.str("");
    const record = try headersRecord(self, headers_value);
    const content_type = (record.getCopy(self.arena, "content-type") catch |err| return headersThrow(self, err)) orelse "";
    return headersStringValue(self, content_type);
}
fn fetchEnsureBodyStream(self: *Interpreter, object: *value.Object) EvalError!?*value.Object {
    const body = fetchBodyValue(object);
    if (body.isNull() or body.isUndefined()) return null;
    if (rsIsStream(body)) return body.asObj();
    if (!body.isObject() or body.asObj().arrayBuffer() == null)
        return self.throwError("TypeError", "Fetch body storage is invalid");
    const stream = try rsClosedStreamFromChunk(self, body);
    const slot: []const u8 = if (object.getOwn("\x00Rbody") != null) "\x00Rbody" else "\x00Qbody";
    try object.setOwn(self.arena, self.root_shape, slot, Value.obj(stream));
    return stream;
}
fn fetchRejectedBodyPromise(self: *Interpreter, message: []const u8) EvalError!Value {
    return Value.obj(try promise.newRejectedPromise(self, try self.makeError("TypeError", message)));
}
fn fetchConsumeBody(self: *Interpreter, this: Value, kind: ReadableStreamConsumeKind) EvalError!Value {
    const object = try fetchBodyObject(self, this);
    const stored = fetchBodyValue(object);
    const has_body = !stored.isNull() and !stored.isUndefined();
    if (has_body and fetchBodyIsUsed(object)) return fetchRejectedBodyPromise(self, "Body has already been consumed");
    if (rsIsStream(stored) and rsReader(stored.asObj()) != null)
        return fetchRejectedBodyPromise(self, "Body stream is locked");
    const stream = (try fetchEnsureBodyStream(self, object)) orelse try rsClosedStreamFromChunk(self, null);
    const content_type = if (kind == .blob or kind == .form_data) try fetchBodyContentType(self, object) else Value.undef();
    return readableStreamConsume(self, Value.obj(stream), kind, content_type);
}
fn fetchBodyMethod(comptime kind: ReadableStreamConsumeKind) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            _ = args;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            return fetchConsumeBody(self, this, kind);
        }
    }.call;
}
fn fetchBodyGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const object = try fetchBodyObject(self, this);
    const stream = try fetchEnsureBodyStream(self, object);
    return if (stream) |body| Value.obj(body) else Value.nul();
}
fn fetchBodyUsedGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    return Value.boolVal(fetchBodyIsUsed(try fetchBodyObject(self, this)));
}

/// Validate and consume the Fetch `Response` required by WebAssembly streaming
/// compilation. The returned intrinsic Promise fulfills with a Uint8Array;
/// all response/body failures are raised for the caller to reject its outer
/// compile Promise without switching parsers or exposing partial bytes.
pub fn wasmStreamingResponseBytes(self: *Interpreter, response: Value) EvalError!Value {
    const object = try wasmStreamingResponseObject(self, response);
    return fetchConsumeBody(self, Value.obj(object), .bytes);
}

pub fn wasmStreamingResponseToSink(
    self: *Interpreter,
    response: Value,
    sink: *ReadableStreamByteSink,
) EvalError!Value {
    const object = try wasmStreamingResponseObject(self, response);
    const stream = (try fetchEnsureBodyStream(self, object)) orelse try rsClosedStreamFromChunk(self, null);
    return readableStreamConsumeToSink(self, Value.obj(stream), sink);
}

fn wasmStreamingResponseObject(self: *Interpreter, response: Value) EvalError!*value.Object {
    if (!response.isObject() or response.asObj().getOwn("\x00Rstatus") == null)
        return self.throwError("TypeError", "WebAssembly streaming source must resolve to a Response");
    const object = response.asObj();
    const status_value = object.getOwn("\x00Rstatus") orelse Value.num(0);
    const status = if (status_value.isNumber()) status_value.asNum() else 0;
    if (status < 200 or status > 299)
        return self.throwError("TypeError", "WebAssembly streaming response has an unsuccessful status");
    const content_type_value = try fetchBodyContentType(self, object);
    const content_type = if (content_type_value.isString()) content_type_value.asStr() else "";
    const normalized_type = std.mem.trim(u8, content_type, " \t\r\n");
    if (!std.ascii.eqlIgnoreCase(normalized_type, "application/wasm"))
        return self.throwError("TypeError", "WebAssembly streaming response has an unsupported MIME type");
    if (fetchBodyIsUsed(object)) return self.throwError("TypeError", "WebAssembly streaming response body has already been used");
    const body = fetchBodyValue(object);
    if (rsIsStream(body) and rsReader(body.asObj()) != null)
        return self.throwError("TypeError", "WebAssembly streaming response body is locked");
    return object;
}
fn fetchSlotStrGetter(comptime slot: []const u8, comptime dflt: []const u8) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            _ = args;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            if (!this.isObject()) return self.throwError("TypeError", "Illegal invocation");
            if (this.asObj().getOwn(slot)) |v| return v;
            return Value.str(dflt);
        }
    }.call;
}
fn fetchBoolSlotGetter(comptime slot: []const u8) value.NativeFn {
    return struct {
        fn call(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
            _ = args;
            const self: *Interpreter = @ptrCast(@alignCast(ctx));
            if (!this.isObject()) return self.throwError("TypeError", "Illegal invocation");
            return Value.boolVal(if (this.asObj().getOwn(slot)) |v| v.toBoolean() else false);
        }
    }.call;
}
// ---- Response -------------------------------------------------------
fn responseMake(self: *Interpreter, status: u32, status_text: []const u8, headers: *value.Object, body: BodyExtract, rtype: []const u8, url: []const u8, redirected: bool) EvalError!*value.Object {
    const obj = try gc_mod.allocObj(self.arena);
    obj.* = .{};
    if (self.env.get("Response")) |c| if (c.isObject()) if (c.asObj().getOwn("prototype")) |pp| if (pp.isObject()) obj.setProtoAtomic(pp.asObj());
    const rs = self.root_shape;
    try obj.setOwn(self.arena, rs, "\x00Rstatus", Value.num(@floatFromInt(status)));
    try obj.setOwn(self.arena, rs, "\x00RstatusText", try Value.strAlloc(self.arena, status_text));
    try obj.setOwn(self.arena, rs, "\x00Rheaders", Value.obj(headers));
    try obj.setOwn(self.arena, rs, "\x00Rtype", try Value.strAlloc(self.arena, rtype));
    try obj.setOwn(self.arena, rs, "\x00Rurl", try Value.strAlloc(self.arena, url));
    try obj.setOwn(self.arena, rs, "\x00Rredirected", Value.boolVal(redirected));
    try obj.setOwn(self.arena, rs, "\x00RbodyUsed", Value.boolVal(false));
    try fetchStoreBody(self, obj, "\x00Rbody", body);
    return obj;
}
fn responseApplyBodyCT(self: *Interpreter, headers: *value.Object, be: BodyExtract) EvalError!void {
    if (be.ctype) |ct| {
        if (!try fetchHeadersHasName(self, headers, "content-type"))
            try headersAppendRaw(self, Value.obj(headers), Value.str("content-type"), try Value.strAlloc(self.arena, ct));
    }
}
fn responseConstructorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (self.new_target.isUndefined()) return self.throwError("TypeError", "Failed to construct 'Response': Please use the 'new' operator");
    const body_v = if (args.len > 0) args[0] else Value.undef();
    var status: f64 = 200;
    var status_text: []const u8 = "";
    var headers_init: Value = Value.undef();
    if (args.len > 1 and args[1].isObject()) {
        const sv = try self.getProperty(args[1], "status");
        if (!sv.isUndefined()) status = try self.toNumberV(sv);
        const stv = try self.getProperty(args[1], "statusText");
        if (!stv.isUndefined()) status_text = try self.toStringWtf8(stv);
        headers_init = try self.getProperty(args[1], "headers");
    }
    if (status < 200 or status > 599) return self.throwError("RangeError", "Failed to construct 'Response': The status provided is outside the range [200, 599].");
    const st: u32 = @intFromFloat(status);
    const headers = try fetchMakeHeaders(self, headers_init, .response);
    const be = try fetchExtractBody(self, body_v);
    if ((be.bytes != null or be.stream != null) and (st == 204 or st == 205 or st == 304))
        return self.throwError("TypeError", "Response with null body status cannot have body");
    try responseApplyBodyCT(self, headers, be);
    return Value.obj(try responseMake(self, st, status_text, headers, be, "default", "", false));
}
fn responseStatusGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return self.throwError("TypeError", "Illegal invocation");
    return this.asObj().getOwn("\x00Rstatus") orelse Value.num(200);
}
fn responseOkGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return self.throwError("TypeError", "Illegal invocation");
    const s = if (this.asObj().getOwn("\x00Rstatus")) |v| v.asNum() else 200;
    return Value.boolVal(s >= 200 and s <= 299);
}
fn responseHeadersGet(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!this.isObject()) return self.throwError("TypeError", "Illegal invocation");
    return this.asObj().getOwn("\x00Rheaders") orelse Value.undef();
}
fn fetchCloneBody(self: *Interpreter, source: *value.Object) EvalError!BodyExtract {
    const body = fetchBodyValue(source);
    if (body.isNull() or body.isUndefined()) return .{ .bytes = null, .ctype = null };
    if (fetchBodyIsUsed(source)) return self.throwError("TypeError", "Cannot clone a consumed body");
    if (rsIsStream(body)) {
        if (rsReader(body.asObj()) != null) return self.throwError("TypeError", "Cannot clone a locked body");
        const branches = try rsTeeStreams(self, body.asObj());
        const slot: []const u8 = if (source.getOwn("\x00Rbody") != null) "\x00Rbody" else "\x00Qbody";
        try source.setOwn(self.arena, self.root_shape, slot, Value.obj(branches[0]));
        return .{ .bytes = null, .stream = Value.obj(branches[1]), .ctype = null };
    }
    if (body.isObject()) if (body.asObj().arrayBuffer()) |buffer|
        return .{ .bytes = buffer.bytes(), .ctype = null };
    return self.throwError("TypeError", "Cannot clone invalid body storage");
}
fn responseCloneFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const source = try fetchBodyObject(self, this);
    if (source.getOwn("\x00Rstatus") == null) return self.throwError("TypeError", "Response.clone called on an incompatible receiver");
    const source_headers = source.getOwn("\x00Rheaders") orelse Value.undef();
    const guard = if (fetchHeadersRecord(source_headers)) |record| record.getGuard() else fetch_headers.Guard.response;
    const headers = (try fetchHeadersCloneWithGuard(self, source_headers, guard)).asObj();
    const status_value = source.getOwn("\x00Rstatus") orelse Value.num(200);
    const status: u32 = if (status_value.isNumber()) @intFromFloat(status_value.asNum()) else 200;
    const status_text = source.getOwn("\x00RstatusText") orelse Value.str("");
    const response_type = source.getOwn("\x00Rtype") orelse Value.str("default");
    const url = source.getOwn("\x00Rurl") orelse Value.str("");
    const redirected = source.getOwn("\x00Rredirected") orelse Value.boolVal(false);
    return Value.obj(try responseMake(
        self,
        status,
        if (status_text.isString()) try status_text.asWtf8(self.arena) else "",
        headers,
        try fetchCloneBody(self, source),
        if (response_type.isString()) response_type.asStr() else "default",
        if (url.isString()) url.asStr() else "",
        redirected.toBoolean(),
    ));
}
fn responseErrorStaticFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    _ = args;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    return Value.obj(try responseMake(self, 0, "", try fetchMakeHeaders(self, Value.undef(), .immutable), .{ .bytes = null, .ctype = null }, "error", "", false));
}
fn responseJsonStaticFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const json = self.env.get("JSON") orelse return self.throwError("Error", "JSON unavailable");
    const stringify = try self.getProperty(json, "stringify");
    const jstr = try self.callValue(stringify, &.{if (args.len > 0) args[0] else Value.undef()});
    if (jstr.isUndefined()) return self.throwError("TypeError", "The data is not JSON serializable");
    const bytes = try wtf8ToUtf8Bytes(self.arena, try self.toStringWtf8(jstr));
    var status: u32 = 200;
    var status_text: []const u8 = "";
    var headers_init: Value = Value.undef();
    if (args.len > 1 and args[1].isObject()) {
        const sv = try self.getProperty(args[1], "status");
        if (!sv.isUndefined()) status = @intFromFloat(try self.toNumberV(sv));
        const stv = try self.getProperty(args[1], "statusText");
        if (!stv.isUndefined()) status_text = try self.toStringWtf8(stv);
        headers_init = try self.getProperty(args[1], "headers");
    }
    const headers = try fetchMakeHeaders(self, headers_init, .response);
    if (!try fetchHeadersHasName(self, headers, "content-type"))
        try headersAppendRaw(self, Value.obj(headers), Value.str("content-type"), Value.str("application/json"));
    return Value.obj(try responseMake(self, status, status_text, headers, .{ .bytes = bytes, .ctype = "application/json" }, "default", "", false));
}
fn responseRedirectStaticFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const url_raw = try self.toStringWtf8(if (args.len > 0) args[0] else Value.undef());
    const parsed = (try urlParse(self.arena, url_raw, null)) orelse return self.throwError("TypeError", "Failed to execute 'redirect' on 'Response': Invalid URL");
    const url = try urlSerialize(self.arena, parsed, false);
    var status: u32 = 302;
    if (args.len > 1 and !args[1].isUndefined()) status = @intFromFloat(try self.toNumberV(args[1]));
    if (status != 301 and status != 302 and status != 303 and status != 307 and status != 308)
        return self.throwError("RangeError", "Failed to execute 'redirect' on 'Response': Invalid status code");
    const headers = try fetchMakeHeaders(self, Value.undef(), .immutable);
    try fetchHeadersAppendBytesPrivileged(self, Value.obj(headers), "location", url);
    return Value.obj(try responseMake(self, status, "", headers, .{ .bytes = null, .ctype = null }, "default", "", false));
}
// ---- Request --------------------------------------------------------
fn requestByteString(self: *Interpreter, input: Value) EvalError![]const u8 {
    const string = try self.toStringValue(input);
    var units = Interpreter.StringCodeUnitIterator.initValue(string);
    while (units.next()) |unit| if (unit.unit > 0xff)
        return self.throwError("TypeError", "Request method is not a ByteString");
    return string.asWtf8(self.arena);
}
fn requestEnum(self: *Interpreter, input: Value, comptime member: []const u8, comptime allowed: anytype) EvalError![]const u8 {
    const string = try self.toStringWtf8(input);
    inline for (allowed) |candidate| if (std.mem.eql(u8, string, candidate)) return candidate;
    return self.throwError("TypeError", "Invalid RequestInit " ++ member);
}
fn requestValidateMethod(self: *Interpreter, method: []const u8) EvalError![]const u8 {
    if (!fetch_headers.validName(method)) return self.throwError("TypeError", "Invalid Request method");
    inline for (.{ "CONNECT", "TRACE", "TRACK" }) |forbidden| if (std.ascii.eqlIgnoreCase(method, forbidden))
        return self.throwError("TypeError", "Forbidden Request method");
    const known = [_][]const u8{ "DELETE", "GET", "HEAD", "OPTIONS", "POST", "PUT" };
    for (known) |candidate| if (std.ascii.eqlIgnoreCase(method, candidate)) return candidate;
    return method;
}
fn requestStoredString(self: *Interpreter, source: *value.Object, slot: []const u8, fallback: []const u8) EvalError![]const u8 {
    const stored = source.getOwn(slot) orelse return fallback;
    return if (stored.isString()) stored.asWtf8(self.arena) else fallback;
}
fn requestParseReferrer(self: *Interpreter, input: []const u8, request_url: []const u8) EvalError![]const u8 {
    if (input.len == 0) return "";
    // This standalone engine has no implicit document base URL. Relative
    // referrers therefore fail closed; embedders must supply an absolute URL.
    const parsed = (try urlParse(self.arena, input, null)) orelse
        return self.throwError("TypeError", "Invalid Request referrer URL");
    if (std.mem.eql(u8, parsed.scheme, "about") and std.mem.eql(u8, parsed.path, "client"))
        return "about:client";
    // A standalone realm has no ambient browsing-context origin. Bind its
    // synthetic Fetch settings to the Request URL's tuple origin and fail
    // closed for opaque or cross-origin referrers.
    const target = (try urlParse(self.arena, request_url, null)) orelse return "about:client";
    const referrer_origin = try urlOrigin(self.arena, parsed);
    const target_origin = try urlOrigin(self.arena, target);
    if (std.mem.eql(u8, referrer_origin, "null") or
        std.mem.eql(u8, target_origin, "null") or
        !std.mem.eql(u8, referrer_origin, target_origin)) return "about:client";
    return urlSerialize(self.arena, parsed, false);
}
fn requestConstructorFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (self.new_target.isUndefined()) return self.throwError("TypeError", "Failed to construct 'Request': Please use the 'new' operator");
    if (args.len == 0 or args[0].isUndefined()) return self.throwError("TypeError", "Failed to construct 'Request': 1 argument required");
    const input = args[0];
    var url: []const u8 = "";
    var method: []const u8 = "GET";
    var cache: []const u8 = "default";
    var credentials: []const u8 = "same-origin";
    var mode: []const u8 = "cors";
    var redirect: []const u8 = "follow";
    var integrity: []const u8 = "";
    var keepalive = false;
    var referrer: []const u8 = "about:client";
    var referrer_policy: []const u8 = "";
    var priority: []const u8 = "auto";
    var headers_init: Value = Value.undef();
    var headers_override: ?*value.Object = null;
    var body_override: ?BodyExtract = null;
    var inherited_body: Value = Value.undef();
    var inherited_source: ?*value.Object = null;
    var signal_source: ?*value.Object = null;
    var input_url: ?[]const u8 = null;
    if (input.isObject() and input.asObj().getOwn("\x00Qurl") != null) {
        // Copy from an existing Request.
        const src = input.asObj();
        url = try requestStoredString(self, src, "\x00Qurl", "");
        method = try requestStoredString(self, src, "\x00Qmethod", "GET");
        cache = try requestStoredString(self, src, "\x00Qcache", "default");
        credentials = try requestStoredString(self, src, "\x00Qcredentials", "same-origin");
        mode = try requestStoredString(self, src, "\x00Qmode", "cors");
        redirect = try requestStoredString(self, src, "\x00Qredirect", "follow");
        integrity = try requestStoredString(self, src, "\x00Qintegrity", "");
        keepalive = if (src.getOwn("\x00Qkeepalive")) |stored| stored.toBoolean() else false;
        referrer = try requestStoredString(self, src, "\x00Qreferrer", "about:client");
        referrer_policy = try requestStoredString(self, src, "\x00QreferrerPolicy", "");
        priority = try requestStoredString(self, src, "\x00Qpriority", "auto");
        if (src.getOwn("\x00Qsignal")) |stored| {
            if (abortIsSignal(stored)) signal_source = stored.asObj();
        }
        if (src.getOwn("\x00Qheaders")) |h| headers_init = h;
        inherited_body = fetchBodyValue(src);
        inherited_source = src;
    } else {
        // RequestInfo is converted before RequestInit, but URL parsing belongs
        // to the constructor algorithm after both arguments are converted.
        input_url = try fdUSVString(self, input);
    }
    const init = if (args.len > 1) args[1] else Value.undef();
    if (!init.isUndefined() and !init.isNull() and !builtins.isRealObject(init))
        return self.throwError("TypeError", "RequestInit must be an object");
    var init_nonempty = false;
    var duplex_present = false;
    var referrer_override: ?[]const u8 = null;
    var referrer_policy_override: ?[]const u8 = null;
    var window_present = false;
    var window_value = Value.undef();
    if (builtins.isRealObject(init)) {
        // Web IDL dictionary conversion reads members lexicographically and
        // converts each value before observing the next property.
        const bv = try self.getProperty(init, "body");
        if (!bv.isUndefined()) {
            init_nonempty = true;
            if (!bv.isNull()) body_override = try fetchExtractBody(self, bv);
        }
        const cv = try self.getProperty(init, "cache");
