fn cryptoGetRandomValuesFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const av = if (args.len > 0) args[0] else Value.undef();
