        try setNative(a, rs, atomics, "sub", 3, atomicsRMWFn(.sub));
        try setNative(a, rs, atomics, "and", 3, atomicsRMWFn(.and_));
        try setNative(a, rs, atomics, "or", 3, atomicsRMWFn(.or_));
        try setNative(a, rs, atomics, "xor", 3, atomicsRMWFn(.xor));
        try setNative(a, rs, atomics, "exchange", 3, atomicsRMWFn(.exchange));
        try setNative(a, rs, atomics, "compareExchange", 4, atomicsCompareExchangeFn);
        try setNative(a, rs, atomics, "isLockFree", 1, atomicsIsLockFreeFn);
        try setNative(a, rs, atomics, "wait", 4, atomicsWaitFn);
        try setNative(a, rs, atomics, "waitAsync", 4, atomicsWaitAsyncFn);
        try setNative(a, rs, atomics, "notify", 3, atomicsNotifyFn);
        try setNative(a, rs, atomics, "pause", 0, atomicsPauseFn);
        if (sym_tag) |k| {
            try atomics.setOwn(a, rs, k, Value.str("Atomics"));
            try atomics.setAttr(a, k, .{ .writable = false, .enumerable = false, .configurable = true });
        }
        try env.put("Atomics", Value.obj(atomics));
    }
}

fn installMapProto(env: *Environment, rs: *Shape) EvalError!void {
    const a = env.arena;
    const ctor = env.get("Map") orelse return;
    if (!ctor.isObject()) return;
    const proto_v = ctor.asObj().getOwn("prototype") orelse return;
    if (!proto_v.isObject()) return;
    const p = proto_v.asObj();
    const specs = .{
        .{ "set", 2 },     .{ "get", 1 },         .{ "has", 1 },                 .{ "delete", 1 },
        .{ "clear", 0 },   .{ "forEach", 1 },     .{ "keys", 0 },                .{ "values", 0 },
        .{ "entries", 0 }, .{ "getOrInsert", 2 }, .{ "getOrInsertComputed", 2 },
    };
    inline for (specs) |s| try setNative(a, rs, p, s[0], s[1], mapProtoMethod(s[0], false));
    try setNativeGetter(a, rs, p, "size", collectionSizeGetter(false));
    // `Map.prototype[Symbol.iterator]` (= `entries`) is aliased after Symbol setup.
}

/// Install the Set.prototype methods (real, brand-checked own properties) on
/// the prototype of the `Set` constructor in `env`.
fn installSetProto(env: *Environment, rs: *Shape) EvalError!void {
    const a = env.arena;
    const ctor = env.get("Set") orelse return;
    if (!ctor.isObject()) return;
    const proto_v = ctor.asObj().getOwn("prototype") orelse return;
    if (!proto_v.isObject()) return;
    const p = proto_v.asObj();
    const specs = .{
        .{ "add", 1 },        .{ "has", 1 },          .{ "delete", 1 },         .{ "clear", 0 },
        .{ "forEach", 1 },    .{ "values", 0 },       .{ "keys", 0 },           .{ "entries", 0 },
        .{ "union", 1 },      .{ "intersection", 1 }, .{ "difference", 1 },     .{ "symmetricDifference", 1 },
        .{ "isSubsetOf", 1 }, .{ "isSupersetOf", 1 }, .{ "isDisjointFrom", 1 },
    };
    inline for (specs) |s| try setNative(a, rs, p, s[0], s[1], setProtoMethod(s[0], false));
    try setNativeGetter(a, rs, p, "size", collectionSizeGetter(true));
    // For a Set, `keys`, `values`, and `[Symbol.iterator]` are all the same
    // function object (`values`), so `new Set()[Symbol.iterator]` is callable and
    // `Set.prototype.keys === Set.prototype.values`.
    if (p.getOwn("values")) |values_fn| {
        try p.setOwn(a, rs, "keys", values_fn);
        try p.setAttr(a, "keys", .{ .writable = true, .enumerable = false, .configurable = true });
    }
    // `Set.prototype[Symbol.iterator]` (= `values`) is aliased after Symbol setup.
}

/// Install `proto[Symbol.iterator]` as the same function object already on
/// `proto[method]` (e.g. Map→entries, Set→values), with the standard method
/// attributes. No-op if the Symbol global or the method isn't present yet.
fn aliasIteratorToMethod(a: std.mem.Allocator, rs: *Shape, env: *Environment, proto: *value.Object, method: []const u8) EvalError!void {
    const symv = env.get("Symbol") orelse return;
    if (!symv.isObject()) return;
    const itv = symv.asObj().getOwn("iterator") orelse return;
    if (!itv.isObject() or !itv.asObj().is_symbol) return;
    const fn_v = proto.getOwn(method) orelse return;
    try proto.setOwn(a, rs, itv.asObj().symbolKey(), fn_v);
    try proto.setAttr(a, itv.asObj().symbolKey(), .{ .writable = true, .enumerable = false, .configurable = true });
}

fn mintUniqueAtomicSerial(comptime T: type, counter: *std.atomic.Value(T)) error{OutOfMemory}!T {
    var current = counter.load(.monotonic);
    while (true) {
        if (current == std.math.maxInt(T)) return error.OutOfMemory;
        const next = current + 1;
        if (counter.cmpxchgWeak(current, next, .monotonic, .monotonic)) |observed| {
            current = observed;
            continue;
        }
        return next;
    }
}

fn mintUniqueLocalSerial(comptime T: type, counter: *T) error{OutOfMemory}!T {
    const next = std.math.add(T, counter.*, 1) catch return error.OutOfMemory;
    counter.* = next;
    return next;
}

/// Monotonic id for unique Symbol property-key encodings. Concurrent agents
/// and shared-realm Threads must never collide, and exhaustion must not wrap
/// into a previously issued key.
var symbol_counter = std.atomic.Value(usize).init(0);

/// Create a Symbol object: a tagged object with a unique `sym_key` (a NUL-led
/// string that can't collide with user property names) and a `description`.
fn makeSymbolObj(a: std.mem.Allocator, rs: *Shape, desc: ?[]const u8, proto: ?*value.Object) EvalError!Value {
    _ = rs;
    const o = try gc_mod.allocObj(a);
    o.* = .{
        .is_symbol = true,
        .proto = proto,
    };
    try o.setPrimitiveState(a, .{ .symbol = .{ .description = .init(desc) } });
    const n = try mintUniqueAtomicSerial(usize, &symbol_counter);
    o.setSymbolKey(try std.fmt.allocPrint(a, "\x00s{d}", .{n}));
    return Value.obj(o);
}

/// `Symbol.prototype`, resolved from the live `Symbol` binding (for linking
/// runtime-created symbols to it). Null only before globals are installed.
fn symbolProto(self: *Interpreter) ?*value.Object {
    const sym = self.env.get("Symbol") orelse return null;
    if (!sym.isObject()) return null;
    const p = sym.asObj().getOwn("prototype") orelse return null;
    return if (p.isObject()) p.asObj() else null;
}

/// `Date(...)` / `new Date(...)` → a Date object for the computed time.
/// Parse an ECMA-262 Date Time String Format string to a time value (ms since
/// epoch), or NaN. Handles YYYY[-MM[-DD]][THH:mm[:ss[.sss]]][Z|±HH:mm]; a
/// date-only or zoneless date-time is interpreted as UTC (this engine has no
/// local time zone).
pub fn parseDateString(s_in: []const u8) f64 {
    const nan = std.math.nan(f64);
    const s = std.mem.trim(u8, s_in, " \t\n\r\x0c\x0b");
    if (s.len == 0) return nan;
    if (s[0] < '0' or s[0] > '9') {
        if (s[0] != '+' and s[0] != '-') return dateParseLegacyUTC(s);
    }
    if (dateParseW3CNoteUTC(s)) |v| return v;
    var i: usize = 0;
    const readN = struct {
        fn f(str: []const u8, idx: *usize, count: usize) ?i64 {
            if (idx.* + count > str.len) return null;
            var v: i64 = 0;
            for (str[idx.* .. idx.* + count]) |c| {
                if (c < '0' or c > '9') return null;
                v = v * 10 + (c - '0');
            }
            idx.* += count;
            return v;
        }
    }.f;
    var ysign: i64 = 1;
    var ylen: usize = 4;
    if (s[0] == '+') {
        i += 1;
        ylen = 6;
    } else if (s[0] == '-') {
        ysign = -1;
        i += 1;
        ylen = 6;
    }
    const yv = readN(s, &i, ylen) orelse return nan;
    if (ysign < 0 and yv == 0) return nan;
    const year = ysign * yv;
    var month: i64 = 1;
    var day: i64 = 1;
    if (i < s.len and s[i] == '-') {
        i += 1;
        month = readN(s, &i, 2) orelse return nan;
        if (i < s.len and s[i] == '-') {
            i += 1;
            day = readN(s, &i, 2) orelse return nan;
        }
    }
    var hour: i64 = 0;
    var minute: i64 = 0;
    var sec: i64 = 0;
    var ms: i64 = 0;
    if (i < s.len and (s[i] == 'T' or s[i] == 't')) {
        i += 1;
        hour = readN(s, &i, 2) orelse return nan;
        if (i >= s.len or s[i] != ':') return nan;
        i += 1;
        minute = readN(s, &i, 2) orelse return nan;
        if (minute > 59) return nan;
        if (i < s.len and s[i] == ':') {
            i += 1;
            sec = readN(s, &i, 2) orelse return nan;
            if (i < s.len and s[i] == '.') {
                i += 1;
                var fcount: usize = 0;
                while (i < s.len and s[i] >= '0' and s[i] <= '9') : (i += 1) {
                    if (fcount < 3) {
                        ms = ms * 10 + (s[i] - '0');
                        fcount += 1;
                    }
                }
                if (fcount == 0) return nan;
                while (fcount < 3) : (fcount += 1) ms *= 10;
            }
        }
    }
    if (i < s.len and (s[i] == 'Z' or s[i] == 'z')) {
        i += 1;
    } else if (i < s.len and (s[i] == '+' or s[i] == '-')) {
        const osign: i64 = if (s[i] == '-') -1 else 1;
        i += 1;
        const oh = readN(s, &i, 2) orelse return nan;
        if (i < s.len and s[i] == ':') i += 1;
        const om = readN(s, &i, 2) orelse return nan;
        minute -= osign * (oh * 60 + om);
    }
    if (i != s.len) return nan;
    if (month < 1 or month > 12 or day < 1 or day > 31) return nan;
    if (hour > 24 or sec > 59) return nan;
    if (hour == 24 and (minute != 0 or sec != 0 or ms != 0)) return nan;
    const days = Interpreter.daysFromCivil(year, month, day);
    const total = days * 86_400_000 + hour * 3_600_000 + minute * 60_000 + sec * 1000 + ms;
    const f: f64 = @floatFromInt(total);
    if (std.math.isNan(f) or @abs(f) > 8.64e15) return nan;
    return f;
}

/// Browser-compatible W3C NOTE-datetime extension used by SpiderMonkey staging:
/// `YYYY-M-D HH:mm[:ss[.sss]][Z|±HH[:mm]|±HHmm]`. The relaxed one/two-digit
/// fields apply only to the space separator form; the ISO `T` form remains strict.
fn dateParseW3CNoteUTC(s: []const u8) ?f64 {
    if (std.mem.indexOfScalar(u8, s, ' ') == null) return null;
    const nan = std.math.nan(f64);
    var i: usize = 0;
    const readFixed = struct {
        fn f(str: []const u8, idx: *usize, count: usize) ?i64 {
            if (idx.* + count > str.len) return null;
            var v: i64 = 0;
            for (str[idx.* .. idx.* + count]) |c| {
                if (c < '0' or c > '9') return null;
                v = v * 10 + (c - '0');
            }
            idx.* += count;
            return v;
        }
    }.f;
    const readOneOrTwo = struct {
        fn f(str: []const u8, idx: *usize) ?i64 {
            if (idx.* >= str.len or str[idx.*] < '0' or str[idx.*] > '9') return null;
            var v: i64 = str[idx.*] - '0';
            idx.* += 1;
            if (idx.* < str.len and str[idx.*] >= '0' and str[idx.*] <= '9') {
                v = v * 10 + (str[idx.*] - '0');
                idx.* += 1;
            }
            return v;
        }
    }.f;

    var ysign: i64 = 1;
    var ylen: usize = 4;
    if (s[0] == '+') {
        i += 1;
        ylen = 6;
    } else if (s[0] == '-') {
        ysign = -1;
        i += 1;
        ylen = 6;
    }
    const yv = readFixed(s, &i, ylen) orelse return null;
    if (ysign < 0 and yv == 0) return nan;
    const year = ysign * yv;
    if (i >= s.len or s[i] != '-') return null;
    i += 1;
    const month = readOneOrTwo(s, &i) orelse return null;
    if (i >= s.len or s[i] != '-') return null;
    i += 1;
    const day = readOneOrTwo(s, &i) orelse return null;
    if (i >= s.len or s[i] != ' ') return null;
    i += 1;

    const hour = readOneOrTwo(s, &i) orelse return null;
    if (i >= s.len or s[i] != ':') return null;
    i += 1;
    var minute = readOneOrTwo(s, &i) orelse return null;
    if (minute > 59) return nan;
    var sec: i64 = 0;
    var ms: i64 = 0;
    if (i < s.len and s[i] == ':') {
        i += 1;
        sec = readOneOrTwo(s, &i) orelse return null;
        if (sec > 59) return nan;
        if (i < s.len and s[i] == '.') {
            i += 1;
            var fcount: usize = 0;
            while (i < s.len and s[i] >= '0' and s[i] <= '9') : (i += 1) {
                if (fcount < 3) {
                    ms = ms * 10 + (s[i] - '0');
                    fcount += 1;
                }
            }
            if (fcount == 0) return nan;
            while (fcount < 3) : (fcount += 1) ms *= 10;
        }
    }

    if (i < s.len and (s[i] == 'Z' or s[i] == 'z')) {
        i += 1;
    } else if (i < s.len and (s[i] == '+' or s[i] == '-')) {
        const osign: i64 = if (s[i] == '-') -1 else 1;
        i += 1;
        const oh = readFixed(s, &i, 2) orelse return nan;
        var om: i64 = 0;
        if (i < s.len and s[i] == ':') {
            i += 1;
            om = readFixed(s, &i, 2) orelse return nan;
        } else if (i < s.len and s[i] >= '0' and s[i] <= '9') {
            om = readFixed(s, &i, 2) orelse return nan;
        }
        if (oh > 23 or om > 59) return nan;
        minute -= osign * (oh * 60 + om);
    }

    if (i != s.len) return null;
    if (month < 1 or month > 12 or day < 1 or day > 31) return nan;
    if (hour > 24) return nan;
    if (hour == 24 and (minute != 0 or sec != 0 or ms != 0)) return nan;
    const days = Interpreter.daysFromCivil(year, month, day);
    const total = days * 86_400_000 + hour * 3_600_000 + minute * 60_000 + sec * 1000 + ms;
    const f: f64 = @floatFromInt(total);
    if (std.math.isNan(f) or @abs(f) > 8.64e15) return nan;
    return f;
}

fn dateMonthIndex(s: []const u8) ?i64 {
    inline for (Interpreter.month_names, 0..) |m, i| {
        if (std.mem.eql(u8, s, m)) return @intCast(i + 1);
    }
    return null;
}

fn dateParseTime(s: []const u8, hour: *i64, minute: *i64, sec: *i64) bool {
    if (s.len != 8 or s[2] != ':' or s[5] != ':') return false;
    const read2 = struct {
        fn f(x: []const u8) ?i64 {
            if (x.len != 2 or x[0] < '0' or x[0] > '9' or x[1] < '0' or x[1] > '9') return null;
            return (x[0] - '0') * 10 + (x[1] - '0');
        }
    }.f;
    hour.* = read2(s[0..2]) orelse return false;
    minute.* = read2(s[3..5]) orelse return false;
    sec.* = read2(s[6..8]) orelse return false;
    return hour.* <= 24 and minute.* <= 59 and sec.* <= 59;
}

fn dateParseLegacyUTC(s: []const u8) f64 {
    const nan = std.math.nan(f64);
    var toks: [8][]const u8 = undefined;
    var n: usize = 0;
    var it = std.mem.tokenizeScalar(u8, s, ' ');
    while (it.next()) |tok| {
        if (n == toks.len) break;
        toks[n] = tok;
        n += 1;
    }
    if (n < 6) return nan;

    var day_tok: []const u8 = "";
    var month_tok: []const u8 = "";
    var year_tok: []const u8 = "";
    var time_tok: []const u8 = "";
    if (dateMonthIndex(toks[1]) != null) {
        day_tok = toks[2];
        month_tok = toks[1];
        year_tok = toks[3];
        time_tok = toks[4];
    } else if (dateMonthIndex(toks[2]) != null) {
        day_tok = toks[1];
        month_tok = toks[2];
        year_tok = toks[3];
        time_tok = toks[4];
    } else return nan;

    const month = dateMonthIndex(month_tok) orelse return nan;
    const day = std.fmt.parseInt(i64, day_tok, 10) catch return nan;
    const year = std.fmt.parseInt(i64, year_tok, 10) catch return nan;
    var hour: i64 = 0;
    var minute: i64 = 0;
    var sec: i64 = 0;
    if (!dateParseTime(time_tok, &hour, &minute, &sec)) return nan;
    if (day < 1 or day > 31) return nan;

    const days = Interpreter.daysFromCivil(year, month, day);
    const total = days * 86_400_000 + hour * 3_600_000 + minute * 60_000 + sec * 1000;
    const f: f64 = @floatFromInt(total);
    if (std.math.isNan(f) or @abs(f) > 8.64e15) return nan;
    return f;
}

fn dateParseFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    const s = try self.toStringV(if (args.len > 0) args[0] else Value.undef());
    return Value.num(parseDateString(s));
}

fn dateConstructor(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (self.new_target.isUndefined()) {
        const d = (try self.makeDate(currentTimeMilliseconds())).asObj();
        return (try self.dateMethod(d, "toString", &.{})) orelse Value.str("Invalid Date");
    }
    if (args.len >= 2) {
        // Multi-component form: ToNumber each component once (invoking valueOf),
        // with years 0–99 mapped to 1900–1999.
        const buf = try self.arena.alloc(Value, args.len);
        for (args, 0..) |av, i| buf[i] = Value.num(try self.toNumberV(av));
        const yi = @trunc(buf[0].asNum());
        if (yi >= 0 and yi <= 99) buf[0] = Value.num(yi + 1900);
        return self.makeDate(Interpreter.dateTimeFromArgs(buf));
    }
    if (args.len == 1) {
        // `new Date(dateObject)` copies its time value; otherwise ToPrimitive
        // (a string would be parsed — not yet — else ToNumber).
        if (args[0].isObject() and args[0].asObj().behavior.is_date)
            return self.makeDate(args[0].asObj().dateMs());
        const prim = try self.toPrimitive(args[0], .default);
        if (prim.isString()) return self.makeDate(parseDateString(prim.asStr()));
        // ToNumber(prim): a Symbol or BigInt primitive throws a TypeError.
        return self.makeDate(try self.toNumberV(prim));
    }
    return self.makeDate(currentTimeMilliseconds());
}

/// `Date.UTC(year [, month, day, hours, min, sec, ms])` — the time value for
/// the given UTC date components (NaN if any component is NaN; years 0–99 map
/// to 1900–1999).
fn dateUTCFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len == 0) return Value.num(std.math.nan(f64));
    const n = @min(args.len, 7);
    var buf: [7]Value = undefined;
    // ToNumber every argument first, in order (each valueOf/toString runs, and a
    // Symbol/BigInt throws) — a NaN does not short-circuit the remaining coercions.
    var any_nan = false;
    for (0..n) |i| {
        const num = try self.toNumberV(args[i]);
        buf[i] = Value.num(num);
        if (std.math.isNan(num)) any_nan = true;
    }
    if (any_nan) return Value.num(std.math.nan(f64));
    // Years 0–99 are offset to 1900–1999.
    const yi = @trunc(buf[0].asNum());
    if (yi >= 0 and yi <= 99) buf[0] = Value.num(yi + 1900);
    var len = n;
    if (len == 1) {
        buf[1] = Value.num(0);
        len = 2;
    }
    return Value.num(Interpreter.dateTimeFromArgs(buf[0..len]));
}

/// Current Unix epoch milliseconds shared by Date construction and private ABI.
pub fn currentTimeMilliseconds() f64 {
    return agent.wallNowMs();
}

/// `Date.now()` — Unix epoch milliseconds from the system wall clock.
fn dateNow(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    _ = args;
    _ = ctx;
    return Value.num(currentTimeMilliseconds());
}

/// `Symbol([description])` — returns a fresh unique symbol. It has [[Construct]]
/// for IsConstructor probes, but `new Symbol` throws before argument coercion.
fn symbolFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (!self.new_target.isUndefined()) return self.throwError("TypeError", "Symbol is not a constructor");
    // `description` is ToString'd (honoring a `{toString}`/`{valueOf}` object);
    // a Symbol description is a TypeError, and `undefined` means none.
    const desc: ?[]const u8 = if (args.len > 0 and !args[0].isUndefined())
        try self.toStringWtf8(args[0])
    else
        null;
    const sym = try makeSymbolObj(self.arena, self.root_shape, desc, symbolProto(self));
    _ = self.registerSymbol(sym.asObj());
    return sym;
}

/// The cross-realm GlobalSymbolRegistry, kept as a hidden object on the `Symbol`
/// constructor (key → symbol). The Context's `Symbol` binding persists across
/// `evaluate` calls, so the registry does too. NUL-prefixed so it never shows
/// up in enumeration.
fn symbolRegistry(self: *Interpreter) EvalError!?*value.Object {
    // Atomic get-or-create vs. concurrent `Symbol.for` / realm setup on peer
    // threads — otherwise two threads could each create a fresh registry and
    // one set of registrations would be lost.
    if (self.gil) |g| g.lockSymbolRegistry();
    defer if (self.gil) |g| g.unlockSymbolRegistry();
    return symbolRegistryLocked(self);
}

/// The registry get-or-create proper; the caller must already hold
/// `Gil.symbol_registry_lock` (when threads are on). Non-recursive, so a
/// critical section that also does the key lookup calls this, not `symbolRegistry`.
fn symbolRegistryLocked(self: *Interpreter) EvalError!?*value.Object {
    const sym = self.env.get("Symbol") orelse return null;
    if (!sym.isObject()) return null;
    if (sym.asObj().getOwn("\x00registry")) |r| {
        if (r.isObject()) return r.asObj();
    }
    const reg = (try self.newObject()).asObj();
    try sym.asObj().setOwn(self.arena, self.root_shape, "\x00registry", Value.obj(reg));
    return reg;
}

/// `Symbol.for(key)` — return the registered symbol for the string `key`,
/// creating and registering it on first use so equal keys yield the *same*
/// symbol. The registration key is stashed on the symbol (hidden) for `keyFor`.
fn symbolForFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    // `key` is ToString(arg) — honoring a `{toString}`/`{valueOf}` object and
    // throwing for a Symbol — not the raw default stringification.
    const key = if (args.len > 0) try self.toStringWtf8(args[0]) else "undefined";
    return symbolForKey(self, key);
}

/// Internal SymbolRegistry lookup for VM facilities that name a registered
/// symbol without performing user-observable ToString (for example Bun's
/// builtin-name table entry for `nodejs.util.inspect.custom`).
pub fn symbolForKey(self: *Interpreter, key: []const u8) EvalError!Value {
    // The whole lookup-or-register must be atomic vs. peer `Symbol.for(key)`
    // calls, or two threads could both miss `getOwn(key)` and register distinct
    // symbols for the same key — breaking `Symbol.for(k) === Symbol.for(k)`.
    if (self.gil) |g| g.lockSymbolRegistry();
    defer if (self.gil) |g| g.unlockSymbolRegistry();
    const reg = (try symbolRegistryLocked(self)) orelse return self.throwError("TypeError", "Symbol registry unavailable");
    if (reg.getOwn(key)) |existing| return existing;
    if (gc_mod.sharedHeapOwnerContext(self.gc)) |owner| {
        const active_is_owner = if (self.gc_realm_context) |raw|
            @intFromPtr(raw) == @intFromPtr(owner)
        else
            false;
        if (!active_is_owner) {
            const saved = gc_mod.setActiveContext(owner);
            defer gc_mod.restoreActiveContext(saved);
            var owner_machine = owner.interpreter();
            const sym = try makeSymbolObj(
                owner_machine.arena,
                owner_machine.root_shape,
                key,
                symbolProto(&owner_machine),
            );
            _ = owner_machine.registerSymbol(sym.asObj());
            try sym.asObj().setOwn(
                owner_machine.arena,
                owner_machine.root_shape,
                "\x00forKey",
                try Value.strAlloc(owner_machine.arena, key),
            );
            try reg.setOwn(owner_machine.arena, owner_machine.root_shape, key, sym);
            return sym;
        }
    }
    const sym = try makeSymbolObj(self.arena, self.root_shape, key, symbolProto(self));
    _ = self.registerSymbol(sym.asObj());
    try sym.asObj().setOwn(self.arena, self.root_shape, "\x00forKey", try Value.strAlloc(self.arena, key));
    try reg.setOwn(self.arena, self.root_shape, key, sym);
    return sym;
}

/// `Symbol.keyFor(sym)` — the registry key a symbol was registered under via
/// `Symbol.for`, or undefined if it isn't a registered symbol.
fn symbolKeyForFn(ctx: *anyopaque, this: Value, args: []const Value) value.HostError!Value {
    _ = this;
    const self: *Interpreter = @ptrCast(@alignCast(ctx));
    if (args.len == 0 or !args[0].isObject() or !args[0].asObj().is_symbol)
        return self.throwError("TypeError", "Symbol.keyFor requires a symbol argument");
    return args[0].asObj().getOwn("\x00forKey") orelse Value.undef();
}

/// Abstract Relational Comparison (subset): string<string is lexicographic,
/// everything else compares as numbers. String ordering is defined over UTF-16
/// code units, so consume the StringCell through the same representation-aware
/// iterator as String exotic indexing. In particular, two adjacent raw bytes
/// in a flat-latin1 cell are two units even when they form valid UTF-8.
fn compareStringsUtf16(a: Value, b: Value) std.math.Order {
    std.debug.assert(a.isString() and b.isString());
    // Identical physical images are equal only when their representation is
    // identical. This retains the common no-walk path without conflating a
    // future mixed canonical/flat pair.
    if (a.strIsFlatLatin1() == b.strIsFlatLatin1() and std.mem.eql(u8, a.asStr(), b.asStr())) return .eq;
    var ai = Interpreter.StringCodeUnitIterator.initValue(a);
    var bi = Interpreter.StringCodeUnitIterator.initValue(b);
    while (true) {
        const ca = ai.next();
        const cb = bi.next();
        if (ca == null) return if (cb == null) .eq else .lt;
        if (cb == null) return .gt;
        if (ca.?.unit != cb.?.unit) return if (ca.?.unit < cb.?.unit) .lt else .gt;
    }
}

fn lessThan(self: *Interpreter, a: Value, b: Value) EvalError!bool {
    if (a.isString() and b.isString()) {
        return compareStringsUtf16(a, b) == .lt;
    }
    if ((a.isObject() and a.asObj().is_symbol) or (b.isObject() and b.asObj().is_symbol))
        return self.throwError("TypeError", "Cannot convert a Symbol value to a number");
    const x = a.toNumber();
    const y = b.toNumber();
    if (std.math.isNan(x) or std.math.isNan(y)) return false;
    return x < y;
}

/// Does `o` (own or via its prototype chain) have a data or accessor property
/// named `name`? Used by `with`-scope identifier resolution.
/// The root (global) lexical environment — where the installed globals and
/// top-level `var`/function bindings live.
fn rootEnv(env: *Environment) *Environment {
    var root = env;
    while (root.parent) |p| root = p;
    return root;
}

pub fn hasProperty(o: *value.Object, name: []const u8) bool {
    var cur: ?*value.Object = o;
    while (cur) |c| {
        if (c.getOwn(name) != null or c.getAccessor(name) != null) return true;
        // Dense array / typed-array / String-wrapper indices live outside the
        // slot store, so [[HasProperty]] must consult them on each chain object
        // (an inherited array element makes the index present on the receiver).
        if (value.canonicalIndex(name)) |idx| {
            if (c.is_array and c.denseElementPresent(idx)) return true;
            if (c.typedArray()) |ta| if (idx < (ta.currentLength() orelse 0)) return true;
            if (c.boxedPrimitive()) |p| if (p.isString() and idx < Interpreter.utf16LenOfValue(p)) return true;
        }
        cur = c.protoAtomic();
    }
    return false;
}

/// The parameter name a mapped-arguments index aliases, or null if `o` is not a
/// mapped arguments object or index `i` is unmapped (out of range / severed).
pub fn argMapName(o: *value.Object, i: usize) ?[]const u8 {
    const cold = o.coldState() orelse return null;
    if (cold.arg_map_env == null or i >= cold.arg_map_names.len) return null;
    if (i < cold.arg_map_severed.len and cold.arg_map_severed[i].load(.acquire)) return null;
    const nm = cold.arg_map_names[i];
    return if (nm.len == 0) null else nm;
}

/// Whether index `i` still participates in either supported [[ParameterMap]]
/// representation. The tree-walker owns Environment-backed maps; compiled
/// activations use atomic Value cells that never retain a recyclable frame.
pub fn argMapHas(o: *value.Object, i: usize) bool {
    const cold = o.coldState() orelse return false;
    if (i >= cold.arg_map_severed.len or cold.arg_map_severed[i].load(.acquire)) return false;
    if (cold.arg_map_env != null) return argMapName(o, i) != null;
    return i < cold.arg_map_values.len;
}

/// Atomically sever a mapped-arguments index from its parameter binding.
pub fn argMapSever(o: *value.Object, i: usize) void {
    const cold = o.coldState() orelse return;
    if (i >= cold.arg_map_severed.len) return;
    cold.arg_map_severed[i].store(true, .release);
}

/// Read a mapped index's parameter binding (null if unmapped).
pub fn argMapGet(o: *value.Object, i: usize) ?Value {
    if (!argMapHas(o, i)) return null;
    const cold = o.coldState().?;
    if (cold.arg_map_env) |raw| {
        const nm = argMapName(o, i) orelse return null;
        const env: *Environment = @ptrCast(@alignCast(raw));
        return env.getLocal(nm);
    }
    return mappedParameterCellGet(o, i);
}

/// Write a mapped index's parameter binding.
pub fn argMapSet(o: *value.Object, i: usize, v: Value) void {
    if (!argMapHas(o, i)) return;
    const cold = o.coldState().?;
    if (cold.arg_map_env) |raw| {
        const nm = argMapName(o, i) orelse return;
        const env: *Environment = @ptrCast(@alignCast(raw));
        _ = env.assignLocal(nm, v);
        return;
    }
    _ = mappedParameterCellSet(o, i, v);
}

/// Read the backing cell used by a compiled sloppy parameter. This deliberately
/// ignores the object's severed bit: deleting or redefining arguments[i]
/// disconnects the object view, but the function binding still owns the cell.
pub inline fn mappedParameterCellGet(o: *value.Object, i: usize) ?Value {
    const cold = o.coldState() orelse return null;
    if (i >= cold.arg_map_values.len) return null;
    return .{ .bits = cold.arg_map_values[i].load(.acquire) };
}

/// Publish a compiled sloppy parameter write. The generational barrier must
/// precede the release-store so a concurrent marker cannot observe a young
/// pointer without also observing its remembered-set edge.
pub fn mappedParameterCellSet(o: *value.Object, i: usize, v: Value) bool {
    const cold = o.coldState() orelse return false;
    if (i >= cold.arg_map_values.len) return false;
    gc_mod.barrierValueFromManaged(o, v);
    cold.arg_map_values[i].store(v.bits, .release);
    return true;
}

/// CanonicalNumericIndexString(key): the Number a key denotes when it is the
/// canonical string form of that Number ("-0", "0", "1", "1.5", "Infinity", …),
/// else null. Used by the Integer-Indexed Exotic Object internal methods so a
/// numeric-looking key on a TypedArray is handled as an index (never as an
/// ordinary/inherited property), even when out of bounds or fractional.
pub fn canonicalNumericIndexString(key: []const u8) ?f64 {
    if (key.len == 0) return null;
    if (std.mem.eql(u8, key, "-0")) return -0.0;
    // A key must start like a number for this to ever match (cheap reject).
    const c0 = key[0];
    if ((c0 < '0' or c0 > '9') and c0 != '-' and c0 != '.' and c0 != 'I' and c0 != 'N') return null;
    const n = value.stringToNumber(key, false);
    var buf: [512]u8 = undefined;
    var fba = std.heap.FixedBufferAllocator.init(&buf);
    const s = value.numberToString(fba.allocator(), n) catch return null;
    return if (std.mem.eql(u8, s, key)) n else null;
}

/// IsValidIntegerIndex(O, index): true iff `n` is an in-bounds, integral,
/// non-negative, non-`-0` index into the (attached, in-bounds) typed array.
pub fn isValidIntegerIndex(ta: *const value.TypedArrayData, n: f64) bool {
    if (std.math.isNan(n) or std.math.isInf(n) or @trunc(n) != n) return false;
    if (n < 0) return false;
    if (n == 0 and std.math.signbit(n)) return false; // -0
    const len = ta.currentLength() orelse return false;
    return n < @as(f64, @floatFromInt(len));
}

/// Does `o` have `name` as an *own* property (data, accessor, array index, or
/// array `length`)? Backs `hasOwnProperty` / `propertyIsEnumerable` / `Object.hasOwn`.
pub fn objectHasOwn(o: *value.Object, name: []const u8) bool {
    // Private members (`#x`) are internal slots, invisible to all reflection.
    if (value.isPrivateKey(name)) return false;
    if (moduleNsOf(o)) |ns| return moduleNsHas(ns, name);
    // A TypedArray's integer-indexed elements: a canonical numeric key is an own
    // property iff it is a valid index (so "-0"/out-of-bounds/fractional are not).
    if (o.typedArray()) |ta| {
        if (canonicalNumericIndexString(name)) |n| return isValidIntegerIndex(ta, n);
    }
    if (o.getOwn(name) != null or o.getAccessor(name) != null) return true;
    if (isLazyFunctionPrototypeSlot(o, name)) return true;
    if (o.boxedPrimitive()) |p| {
        if (p.isString()) {
            if (std.mem.eql(u8, name, "length")) return true;
            if (Interpreter.arrayIndex(name)) |i| return i < Interpreter.utf16LenOfValue(p);
        }
    }
    if (o.is_array) {
        // A real Array always has an own `length`; an arguments object's `length`
        // is an ordinary own property already handled by getOwn above (so a
        // deleted one is genuinely absent).
        if (!o.is_arguments and std.mem.eql(u8, name, "length")) return true;
        if (Interpreter.arrayElementIndex(name)) |i| return o.denseElementPresent(i);
    }
    if (Interpreter.arrayElementIndex(name)) |i| return o.denseElementPresent(i);
    return false;
}

fn isLazyFunctionPrototypeSlot(o: *value.Object, name: []const u8) bool {
    return std.mem.eql(u8, name, "prototype") and
        o.jsFunction() != null and
        Interpreter.jsFunctionHasOwnPrototypeSlot(o) and
        o.getOwn("prototype") == null and
        o.getAccessor("prototype") == null;
}

fn arg0(args: []const Value) Value {
    return if (args.len > 0) args[0] else Value.undef();
}

/// The next representable f64 above `x` (`x >= 0`); for `x == 0` the smallest
/// positive denormal. Used for the half-ULP delta in `numberToRadix`.
fn nextUpNonNeg(x: f64) f64 {
    if (std.math.isInf(x)) return x;
    const bits: u64 = @bitCast(x);
    return @bitCast(bits +% 1);
}

/// V8 `Double::Exponent()`: the binary exponent `e` for which the value equals
/// (53-bit integer significand) × 2^e. `> 0` means the value is ≥ 2^53, so its
/// low base-r digits are not representable and must be emitted as zeros.
fn v8Exponent(x: f64) i32 {
    const bits: u64 = @bitCast(x);
    const biased: i32 = @intCast((bits >> 52) & 0x7ff);
    if (biased == 0) return -1074; // subnormal
    return biased - 1075; // 0x3ff + 52
}

/// `n.toString(radix)` for radix ≠ 10 on a finite non-zero number. A faithful
/// port of V8's DoubleToRadixCString: emit the fractional part first, stopping
/// as soon as the emitted digits round-trip (half-ULP `delta` termination, ties
/// to even) so the result is the shortest string denoting exactly `n`; a
/// fractional round-up can carry into the integer part. The integer part then
/// zero-fills digit positions below the value's representable precision (≥ 2^53)
/// rather than trusting lossy f64 division. Matches V8 byte-for-byte.
fn numberToRadix(arena: std.mem.Allocator, n: f64, radix: usize) ![]const u8 {
    if (n == 0) return "0";
    const chars = "0123456789abcdefghijklmnopqrstuvwxyz";
    const rf: f64 = @floatFromInt(radix);
    const neg = n < 0;
    const mag = @abs(n);

    // Integer digits grow downward from the middle; fraction digits upward.
    const kBufferSize = 2200;
    const mid = kBufferSize / 2;
    var buffer: [kBufferSize]u8 = undefined;
    var integer_cursor: usize = mid;
    var fraction_cursor: usize = mid;

    var integer = @floor(mag);
    var fraction = mag - integer;

    // delta = half the gap to the next double (at least the smallest denormal).
    var delta = 0.5 * (nextUpNonNeg(mag) - mag);
    const min_delta = nextUpNonNeg(0.0);
    if (delta < min_delta) delta = min_delta;

    if (fraction >= delta) {
        buffer[fraction_cursor] = '.';
        fraction_cursor += 1;
        while (true) {
            fraction *= rf;
            delta *= rf;
            const digit: usize = @intFromFloat(fraction);
            buffer[fraction_cursor] = chars[digit];
            fraction_cursor += 1;
            fraction -= @as(f64, @floatFromInt(digit));
            // Round to even when past the halfway point.
            if (fraction > 0.5 or (fraction == 0.5 and (digit & 1) == 1)) {
                if (fraction + delta > 1) {
                    // Round up: walk back over trailing max-digits, bumping the
                    // first that can grow; a carry off the front adds 1 to integer.
                    while (true) {
                        fraction_cursor -= 1;
                        if (fraction_cursor == mid) {
                            integer += 1;
                            break;
                        }
                        const c = buffer[fraction_cursor];
                        const d: usize = if (c > '9') (c - 'a' + 10) else (c - '0');
                        if (d + 1 < radix) {
                            buffer[fraction_cursor] = chars[d + 1];
                            fraction_cursor += 1;
                            break;
                        }
                    }
                    break;
                }
            }
            if (fraction < delta) break;
        }
    }

    // Integer part: zero-fill positions the f64 can't represent, then divmod.
    while (v8Exponent(integer / rf) > 0) {
        integer /= rf;
        integer_cursor -= 1;
        buffer[integer_cursor] = '0';
    }
    while (true) {
        const remainder = @mod(integer, rf);
        integer_cursor -= 1;
        buffer[integer_cursor] = chars[@intFromFloat(remainder)];
        integer = (integer - remainder) / rf;
        if (integer <= 0) break;
    }

    var out: std.ArrayListUnmanaged(u8) = .empty;
    if (neg) try out.append(arena, '-');
    try out.appendSlice(arena, buffer[integer_cursor..fraction_cursor]);
    return out.items;
}

/// `n.toFixed(d)` — fixed-point with `d` decimals (d ≤ 100; no exponent forms).
///
/// The spec (21.1.3.3 step 5) rounds to the integer n minimizing |n/10^d − x|,
/// breaking ties by "pick the LARGER n" — i.e. round HALF-UP on the magnitude
/// (`(0.5).toFixed(0)` is "1", `(0.125).toFixed(2)` is "0.13"). C's `%.*f` rounds
/// half-to-EVEN, which differs precisely on exact ties. So we emit the EXACT
/// decimal digits (an f64's fractional part terminates within 1074 decimal
/// digits, so printf at that precision does no rounding) and round half-up at
/// position d ourselves.
fn toFixed(arena: std.mem.Allocator, n: f64, d: usize) ![]const u8 {
    if (std.math.isNan(n)) return "NaN";
    if (std.math.isInf(n)) return if (n < 0) "-Infinity" else "Infinity";
    const abs_n = @abs(n);
    if (abs_n >= 1e21) return value.numberToString(arena, n);

    // Exact fractional digits (no rounding), zero-padded past termination.
    const exact_prec: usize = 1074;
    const cap = exact_prec + 40; // + integer digits (<=21) + dot/NUL headroom
    const raw = try arena.alloc(u8, cap);
    const len = snprintf(raw.ptr, cap, "%.*f", @as(c_int, @intCast(exact_prec)), abs_n);
    if (len < 0 or @as(usize, @intCast(len)) >= cap) return error.OutOfMemory;
    const s = raw[0..@intCast(len)]; // "III.FFFF…" with exact_prec fraction digits
    const dot = std.mem.indexOfScalar(u8, s, '.') orelse s.len;
    const int_part = s[0..dot];
    const frac = if (dot < s.len) s[dot + 1 ..] else s[s.len..];

    // Keep the integer part and the first d fraction digits; round half-up on the
    // exact (d+1)th fraction digit (>= '5' rounds up), then propagate any carry.
    var out: std.ArrayListUnmanaged(u8) = .empty;
    try out.appendSlice(arena, int_part);
    if (d > 0) {
        try out.append(arena, '.');
        try out.appendSlice(arena, frac[0..@min(d, frac.len)]);
        if (d > frac.len) try out.appendNTimes(arena, '0', d - frac.len);
    }
    if (d < frac.len and frac[d] >= '5') {
        var i: usize = out.items.len;
        var carry = true;
        while (i > 0 and carry) {
            i -= 1;
            const c = out.items[i];
            if (c == '.') continue;
            if (c == '9') out.items[i] = '0' else {
                out.items[i] = c + 1;
                carry = false;
            }
        }
        if (carry) try out.insert(arena, 0, '1'); // carried past the leading digit
    }
    // Per spec step 6 the sign is set from x < 0 and always prepended (so
    // `(-0.001).toFixed(1)` is "-0.0"); -0 is not < 0, so it stays "0.00".
    if (n < 0) try out.insert(arena, 0, '-');
    return out.items;
}

/// Reformat Zig's scientific output (`1.234e1`, `-9.99e-40`) to JS form, where
/// the exponent always carries a sign (`1.234e+1`, `-9.99e-40`).
fn jsExpFix(arena: std.mem.Allocator, s: []const u8) ![]const u8 {
    const ei = std.mem.indexOfScalar(u8, s, 'e') orelse return arena.dupe(u8, s);
    const mant = s[0..ei];
    const exp = s[ei + 1 ..];
    var sign: u8 = '+';
    var start: usize = 0;
    if (exp.len > 0 and (exp[0] == '-' or exp[0] == '+')) {
        sign = exp[0];
        start = 1;
    }
    while (start + 1 < exp.len and exp[start] == '0') start += 1;
    return std.fmt.allocPrint(arena, "{s}e{c}{s}", .{ mant, sign, exp[start..] });
}

fn renderScientificFixed(arena: std.mem.Allocator, n: f64, frac: usize) ![]const u8 {
    var raw: [512]u8 = undefined;
    const len = snprintf(raw[0..].ptr, raw.len, "%.*e", @as(c_int, @intCast(frac)), @as(f64, n));
    if (len < 0 or @as(usize, @intCast(len)) >= raw.len) return error.OutOfMemory;
    return jsExpFix(arena, raw[0..@intCast(len)]);
}

/// `Number.prototype.toExponential` — scientific notation with `frac` fraction
/// digits (or shortest when null), exponent always signed.
fn toExponentialStr(arena: std.mem.Allocator, n: f64, frac: ?usize) ![]const u8 {
    if (n == 0) {
        var out: std.ArrayListUnmanaged(u8) = .empty;
        try out.append(arena, '0');
        if (frac) |f| if (f > 0) {
            try out.append(arena, '.');
            try out.appendNTimes(arena, '0', f);
        };
        try out.appendSlice(arena, "e+0");
        return out.items;
    }
    const f = frac orelse {
        // Shortest scientific form — no rounding choice, so the renderer is fine.
        var buf: [512]u8 = undefined;
        const s = std.fmt.float.render(&buf, n, .{ .mode = .scientific, .precision = null }) catch return error.OutOfMemory;
        return jsExpFix(arena, s);
    };
    const neg = n < 0;
    // Exact significant digits + decimal exponent: printf %e at 767 digits emits
    // the TRUE digits of the double (no rounding). Keep f+1 significant digits and
    // round HALF-UP on the next exact digit ("pick the larger n", 21.1.3.2) — not
    // printf's half-to-EVEN — so (2.5).toExponential(0) is "3e+0" while the exact
    // double 1.00499… of 1.005 gives (1.005).toExponential(2) === "1.00e+0".
    const high_prec: usize = 767;
    const cap = high_prec + 32;
    const raw = try arena.alloc(u8, cap);
    const rlen = snprintf(raw.ptr, cap, "%.*e", @as(c_int, @intCast(high_prec)), @abs(n));
    if (rlen < 0 or @as(usize, @intCast(rlen)) >= cap) return error.OutOfMemory;
    const es = raw[0..@intCast(rlen)]; // "d.ffff…e±XX"
    const eidx = std.mem.indexOfScalar(u8, es, 'e').?;
    var allsig: std.ArrayListUnmanaged(u8) = .empty;
    for (es[0..eidx]) |c| if (c != '.') try allsig.append(arena, c);
    var exp = std.fmt.parseInt(i32, es[eidx + 1 ..], 10) catch 0;

    const p = f + 1; // total significant digits
    var digits: std.ArrayListUnmanaged(u8) = .empty;
    try digits.appendSlice(arena, allsig.items[0..@min(p, allsig.items.len)]);
    while (digits.items.len < p) try digits.append(arena, '0');
    if (p < allsig.items.len and allsig.items[p] >= '5') {
        var i: usize = digits.items.len;
        var carry = true;
        while (i > 0 and carry) {
            i -= 1;
            if (digits.items[i] == '9') digits.items[i] = '0' else {
                digits.items[i] += 1;
                carry = false;
            }
        }
        if (carry) {
            digits.items[0] = '1'; // "999…" -> "100…", exponent bumped
            exp += 1;
        }
    }

    var out: std.ArrayListUnmanaged(u8) = .empty;
    if (neg) try out.append(arena, '-');
    try out.append(arena, digits.items[0]);
    if (f > 0) {
        try out.append(arena, '.');
        try out.appendSlice(arena, digits.items[1..]);
    }
    try out.appendSlice(arena, try jsExpFix(arena, try std.fmt.allocPrint(arena, "e{d}", .{exp})));
    return out.items;
}

/// `Number.prototype.toPrecision` — `p` significant digits, choosing fixed or
/// exponential notation per spec (exponential when the decimal exponent is
/// < -6 or >= p).
fn toPrecisionStr(arena: std.mem.Allocator, n: f64, p: usize) ![]const u8 {
    if (n == 0) {
        if (p == 1) return "0";
        var z: std.ArrayListUnmanaged(u8) = .empty;
        try z.appendSlice(arena, "0.");
        try z.appendNTimes(arena, '0', p - 1);
        return z.items;
    }
    const neg = n < 0;
    // Exact significant digits + decimal exponent. An f64 has at most ~767
    // significant decimal digits, so printf %e at that precision emits the TRUE
    // digits (no rounding); we then round HALF-UP at digit p ("pick the larger
    // n", 21.1.3.5) instead of C `%e`'s half-to-EVEN — so (2.5).toPrecision(1)
    // is "3" and (0.125).toPrecision(2) is "0.13".
    const high_prec: usize = 767;
    const cap = high_prec + 32;
    const raw = try arena.alloc(u8, cap);
    const rlen = snprintf(raw.ptr, cap, "%.*e", @as(c_int, @intCast(high_prec)), @abs(n));
    if (rlen < 0 or @as(usize, @intCast(rlen)) >= cap) return error.OutOfMemory;
    const es = raw[0..@intCast(rlen)]; // "d.ffff…e±XX" — 1+high_prec significant digits
    const eidx = std.mem.indexOfScalar(u8, es, 'e').?;
    var allsig: std.ArrayListUnmanaged(u8) = .empty; // exact significant digits, no dot
    for (es[0..eidx]) |c| if (c != '.') try allsig.append(arena, c);
    var exp = std.fmt.parseInt(i32, es[eidx + 1 ..], 10) catch 0;

    // Keep p significant digits, rounding half-up on the exact (p+1)th digit.
    var digits: std.ArrayListUnmanaged(u8) = .empty;
    try digits.appendSlice(arena, allsig.items[0..@min(p, allsig.items.len)]);
    while (digits.items.len < p) try digits.append(arena, '0');
    if (p < allsig.items.len and allsig.items[p] >= '5') {
        var i: usize = digits.items.len;
        var carry = true;
        while (i > 0 and carry) {
            i -= 1;
            if (digits.items[i] == '9') digits.items[i] = '0' else {
                digits.items[i] += 1;
                carry = false;
            }
        }
        if (carry) {
            // "999…" -> "100…" with the same p digits and the exponent bumped up.
            digits.items[0] = '1';
            exp += 1;
        }
    }

    var out: std.ArrayListUnmanaged(u8) = .empty;
    if (neg) try out.append(arena, '-');
    if (exp < -6 or exp >= @as(i32, @intCast(p))) {
        // Exponential form: d.ddd e±X
        try out.append(arena, digits.items[0]);
        if (digits.items.len > 1) {
            try out.append(arena, '.');
            try out.appendSlice(arena, digits.items[1..]);
        }
        try out.appendSlice(arena, try jsExpFix(arena, try std.fmt.allocPrint(arena, "e{d}", .{exp})));
    } else if (exp >= 0) {
        const ip: usize = @intCast(exp + 1); // digits before the decimal point
        if (ip >= digits.items.len) {
            try out.appendSlice(arena, digits.items);
            try out.appendNTimes(arena, '0', ip - digits.items.len);
        } else {
            try out.appendSlice(arena, digits.items[0..ip]);
            try out.append(arena, '.');
            try out.appendSlice(arena, digits.items[ip..]);
        }
    } else {
        // exp in [-6, -1]: 0.00…digits
        try out.appendSlice(arena, "0.");
        try out.appendNTimes(arena, '0', @intCast(-exp - 1));
        try out.appendSlice(arena, digits.items);
    }
    return out.items;
}

fn arg(args: []const Value, i: usize) Value {
    return if (i < args.len) args[i] else Value.undef();
}

fn labelEq(a: ?[]const u8, b: ?[]const u8) bool {
    if (a == null or b == null) return false;
    return std.mem.eql(u8, a.?, b.?);
}

fn labelIn(needle: []const u8, labels: []const []const u8) bool {
    for (labels) |label| if (std.mem.eql(u8, needle, label)) return true;
    return false;
}

fn relationalNaN(a: Value, b: Value) bool {
    if (a.isString() and b.isString()) return false;
    return std.math.isNan(a.toNumber()) or std.math.isNan(b.toNumber());
}

