const Parser = parser_mod.Parser;

test "direct eval activation view keeps one live bounded binding cell" {
    var slots = [_]Value{ Value.num(3), Value.num(7) };
    var escaped: std.atomic.Value(bool) = .init(false);
    var slot_lock: std.atomic.Mutex = .unlocked;
    const bindings = [_]bc.DirectEvalBinding{
        .{ .name = "constant", .slot = 1, .lexical = true, .immutable = true, .tdz_checked = true, .mapped_parameter = false },
        .{ .name = "mutable", .slot = 0, .lexical = false, .immutable = false, .tdz_checked = false, .mapped_parameter = false },
    };
    var env = Environment{
        .arena = std.testing.allocator,
        .fn_scope = true,
        .activation = .{
            .frame = .{
                .slots = &slots,
                .mapped_arguments = null,
                .mapped_parameter_indices = &.{},
                .escaped = &escaped,
                .slot_lock = &slot_lock,
            },
            .bindings = &bindings,
        },
    };

    try std.testing.expect(env.hasOwnBinding("mutable"));
    try std.testing.expect(!env.hasOwnBinding("missing"));
    try std.testing.expectEqual(@as(f64, 3), env.get("mutable").?.asNum());
    try std.testing.expectEqual(@as(?bool, false), env.isConst("mutable"));
    try std.testing.expectEqual(@as(?bool, true), env.isConst("constant"));
    try std.testing.expectEqual(Environment.ResolvedBindingState.immutable, env.resolvedBindingState("constant", null));

    try env.assign("mutable", Value.num(11));
    try std.testing.expectEqual(@as(f64, 11), slots[0].asNum());
    try std.testing.expectEqual(@as(f64, 11), env.getLocal("mutable").?.asNum());
    try std.testing.expect(env.assignOwnResolved("mutable", Value.num(13)));
    try std.testing.expectEqual(@as(f64, 13), slots[0].asNum());

    env.markCaptured();
    try std.testing.expect(escaped.load(.acquire));
}

fn evalSource(arena: std.mem.Allocator, src: []const u8) !Value {
    var parser = try Parser.init(arena, src);
    const prog = try parser.parseProgram();
    var env = Environment{ .arena = arena };
    const root_shape = try Shape.createRoot(arena);
    try installGlobals(&env, root_shape);
    var interp = Interpreter{ .arena = arena, .env = &env, .root_shape = root_shape };
    // The TDZ sentinel (a unique object marking a declared-but-uninitialized
    // let/const) is normally installed by Context.init; this bare test-helper
    // interpreter must create it too, or any TDZ-using program (classes, a
    // let/const read before init) crashes in `tdzVal`.
    const tdz = try arena.create(value.Object);
    tdz.* = .{};
    interp.tdz_marker = tdz;
    interp.strict = parser.strict;
    return interp.eval(prog);
}

test "Proxy ownKeys membership installs exact seeded contexts failure atomically" {
    const first_context = Interpreter.SecureStringHashContext{ .seed = 0x5052_4f58_595f_0001 };
    const second_context = Interpreter.SecureStringHashContext{ .seed = 0x5052_4f58_595f_0002 };

    var unavailable: std.testing.FailingAllocator = .init(std.testing.allocator, .{ .fail_index = 0 });
    var failed: Interpreter.SecureStringMembership = .{};
    defer failed.deinit(unavailable.allocator());
    try std.testing.expectError(
        error.OutOfMemory,
        failed.putWithContext(unavailable.allocator(), "first", first_context),
    );
    try std.testing.expect(failed.context == null);
    try std.testing.expectEqual(@as(usize, 0), failed.count());
    try std.testing.expectEqual(@as(usize, 0), failed.index.capacity());

    var membership: Interpreter.SecureStringMembership = .{};
    defer membership.deinit(std.testing.allocator);
    var wide_key: [4096]u8 = @splat('w');
    try std.testing.expect(!try membership.putWithContext(std.testing.allocator, &wide_key, first_context));
    try std.testing.expect(try membership.putWithContext(std.testing.allocator, &wide_key, first_context));
    try std.testing.expect(!try membership.putWithContext(std.testing.allocator, "\x00\x00\x00key", first_context));
    try std.testing.expect(!try membership.putWithContext(std.testing.allocator, "\x00s42", first_context));
    try std.testing.expectEqual(@as(usize, 3), membership.count());
    try std.testing.expect(first_context.hash(&wide_key) != second_context.hash(&wide_key));
    try std.testing.expect(membership.remove("\x00\x00\x00key"));
    try std.testing.expect(membership.remove("\x00s42"));
    try std.testing.expectEqual(@as(usize, 1), membership.count());
}

test "String value methods return the exact StringData cell" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var env = Environment{ .arena = a };
    const root_shape = try Shape.createRoot(a);
    var machine = Interpreter{ .arena = a, .env = &env, .root_shape = root_shape };

    const ascii = try Value.strAlloc(a, "ascii");
    try std.testing.expect(ascii.strIsAscii());
    const latin1 = try Value.strAlloc(a, "\xC3\xA9\xC3\xA9");
    try std.testing.expect(latin1.strIsLatin1() and !latin1.strIsAscii());
    try std.testing.expectEqual(strcell.flat_storage_active, latin1.strIsFlatLatin1());
    const bmp = try Value.strAlloc(a, "\xE2\x82\xAC");
    try std.testing.expect(!bmp.strIsLatin1());
    const astral = try Value.strAlloc(a, "\xF0\x9F\x92\xA9");
    try std.testing.expect(!astral.strIsFlatLatin1());
    const lone_surrogate = try Value.strAlloc(a, "\xED\xA0\xBD");
    try std.testing.expect(!lone_surrogate.strIsFlatLatin1());

    // This becomes a physical flat-latin1 cell automatically when the storage
    // master switch flips, so the same identity witness guards both layouts.
    const primitives = [_]Value{ ascii, latin1, bmp, astral, lone_surrogate };
    var wrappers: [primitives.len]Value = undefined;
    for (primitives, 0..) |primitive, i| wrappers[i] = try machine.makeWrapper(primitive);

    var unavailable: std.testing.FailingAllocator = .init(std.testing.allocator, .{ .fail_index = 0 });
    machine.arena = unavailable.allocator();
    for (primitives, wrappers) |primitive, wrapper| {
        for ([_]Value{ primitive, wrapper }) |receiver| {
            const native_result = try stringValueMethod(@ptrCast(&machine), receiver, &.{});
            try std.testing.expectEqual(primitive.rawBits(), native_result.rawBits());
            for ([_][]const u8{ "toString", "valueOf" }) |name| {
                const fast_result = (try machine.builtinMethod(receiver, name, &.{})).?;
                try std.testing.expectEqual(primitive.rawBits(), fast_result.rawBits());
            }
        }
    }
    try std.testing.expectEqual(@as(usize, 0), unavailable.allocations);
}

test "String method dispatch materializes protocol receivers only when required" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var env = Environment{ .arena = a };
    const root_shape = try Shape.createRoot(a);
    var machine = Interpreter{ .arena = a, .env = &env, .root_shape = root_shape };

    const ascii = try Value.strAlloc(a, "AZ");
    const latin1 = try Value.strAlloc(a, "caf\xc3\xa9\xc3\xbf");
    try std.testing.expect(latin1.strIsFlatLatin1());
    const canonical_latin1 = try latin1.asWtf8(a);

    var unavailable: std.testing.FailingAllocator = .init(std.testing.allocator, .{ .fail_index = 0 });
    machine.arena = unavailable.allocator();

    // charCodeAt has no Symbol protocol. A fail-first allocator proves the
    // generic method path does not eagerly create a duplicate receiver cell.
    const char_code = (try machine.builtinMethod(ascii, "charCodeAt", &.{Value.num(1)})).?;
    try std.testing.expectEqual(@as(f64, 'Z'), char_code.asNum());

    // When a protocol path does need a receiver Value, retain the original
    // physical flat-latin1 cell rather than wrapping its canonical byte view.
    const receiver = try machine.stringReceiverValue(canonical_latin1, latin1.asStringCell());
    try std.testing.expectEqual(latin1.rawBits(), receiver.rawBits());

    // Code-unit-only methods consume the physical cell directly. In
    // particular, charCodeAt must not allocate a canonical WTF-8 snapshot of
    // the whole flat-latin1 receiver merely to read one indexed code unit.
    const latin1_code = (try machine.stringMethodValue(latin1, "charCodeAt", &.{Value.num(3)}, false, null)).?;
    try std.testing.expectEqual(@as(f64, 0xE9), latin1_code.asNum());
    try std.testing.expectEqual(@as(usize, 0), unavailable.allocations);
}

test "String methods preserve original protocol receivers and post-coercion cells" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();

    const result = try evalSource(arena.allocator(),
        \\const boxed = new String("wrong");
        \\let coercions = 0;
        \\boxed.toString = function () { coercions += 1; return "\u00e9x"; };
        \\let seen;
        \\const matcher = { [Symbol.search](receiver) { seen = receiver; return 7; } };
        \\const protocol = boxed.search(matcher) === 7 && seen === boxed && coercions === 0;
        \\const codeUnit = String.prototype.charCodeAt.call(boxed, 0) === 0xE9;
        \\protocol && codeUnit && coercions === 1
    );
    try std.testing.expect(result.asBool());
}

test "String repeat bounds empty work and fills exact canonical output" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var env = Environment{ .arena = a };
    const root_shape = try Shape.createRoot(a);
    var machine = Interpreter{ .arena = a, .env = &env, .root_shape = root_shape };

    const empty = try Value.strAlloc(a, "");
    const flat = try Value.strAlloc(a, "\xc3\xa9\xc3\xbf");
    try std.testing.expect(flat.strIsFlatLatin1());

    var unavailable: std.testing.FailingAllocator = .init(std.testing.allocator, .{ .fail_index = 0 });
    machine.arena = unavailable.allocator();
    const empty_huge = try machine.stringRepeatValue(empty, &.{Value.num(9007199254740991.0)});
    try std.testing.expectEqual(empty.rawBits(), empty_huge.rawBits());
    const one = try machine.stringRepeatValue(flat, &.{Value.num(1)});
    try std.testing.expectEqual(flat.rawBits(), one.rawBits());
    const negative_fraction = try machine.stringRepeatValue(flat, &.{Value.num(-0.5)});
    try std.testing.expectEqualStrings("", negative_fraction.asStr());
    try std.testing.expectError(error.OutOfMemory, machine.stringRepeatValue(Value.str("ab"), &.{Value.num(2)}));
    try std.testing.expectEqual(@as(usize, 0), unavailable.allocations);

    machine.arena = a;
    const repeated_flat = try machine.stringRepeatValue(flat, &.{Value.num(3)});
    try std.testing.expectEqualStrings("\xc3\xa9\xc3\xbf\xc3\xa9\xc3\xbf\xc3\xa9\xc3\xbf", try repeated_flat.asWtf8(a));

    // Repetition can join a trailing high surrogate to the next copy's leading
    // low surrogate. The exact-size path canonicalizes every such boundary.
    const boundary = try Value.strAlloc(a, "\xed\xb0\x80\xed\xa0\x80");
    const repeated_boundary = try machine.stringRepeatValue(boundary, &.{Value.num(2)});
    try std.testing.expectEqualStrings("\xed\xb0\x80\xf0\x90\x80\x80\xed\xa0\x80", try repeated_boundary.asWtf8(a));
}

test "two-value string concatenation retains empties and canonicalizes boundaries" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var env = Environment{ .arena = a };
    const root_shape = try Shape.createRoot(a);
    var machine = Interpreter{ .arena = a, .env = &env, .root_shape = root_shape };

    const empty = try Value.strAlloc(a, "");
    const flat = try Value.strAlloc(a, "caf\xc3\xa9\xc3\xbf");
    try std.testing.expect(flat.strIsFlatLatin1());

    var unavailable: std.testing.FailingAllocator = .init(std.testing.allocator, .{ .fail_index = 0 });
    machine.arena = unavailable.allocator();
    const right_empty = try machine.applyBinary(.add, flat, empty);
    try std.testing.expectEqual(flat.rawBits(), right_empty.rawBits());
    const left_empty = try machine.applyBinary(.add, empty, flat);
    try std.testing.expectEqual(flat.rawBits(), left_empty.rawBits());
    const no_args = (try machine.stringMethodValue(flat, "concat", &.{}, false, null)).?;
    try std.testing.expectEqual(flat.rawBits(), no_args.rawBits());
    const one_empty = (try machine.stringMethodValue(flat, "concat", &.{empty}, false, null)).?;
    try std.testing.expectEqual(flat.rawBits(), one_empty.rawBits());
    try std.testing.expectError(error.OutOfMemory, machine.concatStringValues(Value.str("a"), Value.str("b")));
    try std.testing.expectEqual(@as(usize, 0), unavailable.allocations);

    machine.arena = a;
    const canonical_flat = try machine.concatStringValues(flat, Value.str("!"));
    try std.testing.expectEqualStrings("caf\xc3\xa9\xc3\xbf!", try canonical_flat.asWtf8(a));

    // Concatenation can join separately well-formed WTF-8 surrogate strings.
    // The result must use the canonical four-byte scalar representation.
    const high = try Value.strAlloc(a, "\xed\xa0\x80");
    const low = try Value.strAlloc(a, "\xed\xb0\x80");
    const joined = try machine.concatStringValues(high, low);
    try std.testing.expectEqualStrings("\xf0\x90\x80\x80", try joined.asWtf8(a));

    const order = try evalSource(a,
        \\let log = '';
        \\const left = { valueOf() { log += 'l'; return 'a'; } };
        \\const right = { valueOf() { log += 'r'; return 'b'; } };
        \\left + right + '|' + log
    );
    try std.testing.expectEqualStrings("ab|lr", try order.asWtf8(a));
}

test "variadic string concat uses one exact canonical construction" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var env = Environment{ .arena = a };
    const root_shape = try Shape.createRoot(a);
    var machine = Interpreter{ .arena = a, .env = &env, .root_shape = root_shape };

    const empty = try Value.strAlloc(a, "");
    const flat = try Value.strAlloc(a, "caf\xc3\xa9\xc3\xbf");
    try std.testing.expect(flat.strIsFlatLatin1());

    var unavailable: std.testing.FailingAllocator = .init(std.testing.allocator, .{ .fail_index = 0 });
    machine.arena = unavailable.allocator();
    const retained_receiver = try machine.stringConcatValue(flat, &.{ empty, empty });
    try std.testing.expectEqual(flat.rawBits(), retained_receiver.rawBits());
    const retained = try machine.stringConcatValue(empty, &.{ empty, flat, empty });
    try std.testing.expectEqual(flat.rawBits(), retained.rawBits());
    try std.testing.expectError(
        error.OutOfMemory,
        machine.stringConcatValue(Value.str("a"), &.{ Value.str("b"), Value.str("c") }),
    );
    try std.testing.expectEqual(@as(usize, 0), unavailable.allocations);

    machine.arena = a;
    const combined = try machine.stringConcatValue(flat, &.{ Value.str("-"), flat, Value.str("!") });
    try std.testing.expectEqualStrings("caf\xc3\xa9\xc3\xbf-caf\xc3\xa9\xc3\xbf!", try combined.asWtf8(a));

    const many_args = [_]Value{
        Value.str("b"), Value.str("c"), Value.str("d"), Value.str("e"),
        Value.str("f"), Value.str("g"), Value.str("h"), Value.str("i"),
    };
    const many = try machine.stringConcatValue(Value.str("a"), &many_args);
    try std.testing.expectEqualStrings("abcdefghi", try many.asWtf8(a));

    // Empty pieces do not interrupt adjacent code units. A high surrogate at
    // the end of one non-empty piece and a low surrogate at the start of the
    // next must therefore become one canonical scalar even across empties.
    const high = try Value.strAlloc(a, "\xed\xa0\x80");
    const low = try Value.strAlloc(a, "\xed\xb0\x80");
    const joined = try machine.stringConcatValue(high, &.{ empty, low, empty });
    try std.testing.expectEqualStrings("\xf0\x90\x80\x80", try joined.asWtf8(a));
    const low_high = try Value.strAlloc(a, "\xed\xb0\x80\xed\xa0\x80");
    const twice_joined = try machine.stringConcatValue(high, &.{ low_high, low });
    try std.testing.expectEqualStrings("\xf0\x90\x80\x80\xf0\x90\x80\x80", try twice_joined.asWtf8(a));

    const order = try evalSource(a,
        \\let log = '';
        \\const first = { toString() { log += 'a'; return 'A'; } };
        \\const stop = { toString() { log += 'b'; throw 1; } };
        \\const never = { toString() { log += 'c'; return 'C'; } };
        \\try { ''.concat(first, stop, never); } catch {}
        \\const result = ''.concat(first, 'B', never);
        \\result + '|' + log
    );
    try std.testing.expectEqualStrings("ABC|abac", try order.asWtf8(a));

    const receiver_order = try evalSource(a,
        \\let log = '';
        \\const receiver = { toString() { log += 'r'; return 'R'; } };
        \\const first = { toString() { log += 'a'; return 'A'; } };
        \\const second = { toString() { log += 'b'; return 'B'; } };
        \\const result = String.prototype.concat.call(receiver, first, second);
        \\result + '|' + log
    );
    try std.testing.expectEqualStrings("RAB|rab", try receiver_order.asWtf8(a));
}

test "binary observable coercions remain once-only and left-to-right" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const result = try evalSource(arena.allocator(),
        \\let log = '';
        \\function operand(mark, value, fail) {
        \\  return { valueOf() { log += mark; if (fail) throw 1; return value; } };
        \\}
        \\const results = [];
        \\results.push(operand('a', 'A', false) + operand('b', 'B', false));
        \\results.push(operand('c', 7, false) - operand('d', 2, false));
        \\results.push(operand('e', 2, false) < operand('f', 3, false));
        \\results.push(operand('g', 6, false) & operand('h', 3, false));
        \\results.push(operand('i', 5, false) == 5);
        \\results.push(5 == operand('j', 5, false));
        \\try { operand('k', 0, true) + operand('x', 1, false); } catch {}
        \\function* vmBinary(left, right) { return left + right; }
        \\results.push(vmBinary(operand('l', 'L', false), operand('m', 'M', false)).next().value);
        \\results.join(',') + '|' + log
    );
    try std.testing.expectEqualStrings("AB,5,true,2,true,true,LM|abcdefghijklm", try result.asWtf8(arena.allocator()));
}

test "ToString canonicalizes object-produced StringData" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();

    const result = try evalSource(
        allocator,
        "let log = ''; " ++
            "let key = { toString() { log += 's'; return 'caf\xc3\xa9'; }, valueOf() { log += 'v'; return 1; } }; " ++
            "let object = { [key]: 693 }; object['caf\xc3\xa9'] + '|' + log",
    );
