test "interpreter throw / try / catch / finally" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // catch binds the thrown value
    try std.testing.expectEqual(@as(f64, 42), (try evalSource(a,
        \\let r = 0;
        \\try { throw 42; } catch (e) { r = e; }
        \\r
    )).asNum());
    // finally always runs
    try std.testing.expectEqual(@as(f64, 3), (try evalSource(a,
        \\let r = 0;
        \\try { r = 1; } catch (e) { r = 2; } finally { r = 3; }
        \\r
    )).asNum());
    try std.testing.expect((try evalSource(a,
        \\var outer = "prior";
        \\try { throw "exception"; } catch (outer) { var outer = "catch init"; }
        \\outer === "prior"
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\var before, during, after;
        \\try { throw "exception"; } catch (err) {
        \\  before = err;
        \\  for (var err = "loop initializer"; err !== "increment"; err = "increment") {
        \\    during = err;
        \\  }
        \\  after = err;
        \\}
        \\before === "exception" && during === "loop initializer" && after === "increment"
    )).asBool());
    try std.testing.expectEqual(@as(f64, 42), (try evalSource(a,
        \\function f() {
        \\  try {
        \\    return 42;
        \\  } finally {
        \\    do try {
        \\      return 43;
        \\    } finally {
        \\      break;
        \\    } while (false);
        \\  }
        \\}
        \\f()
    )).asNum());
    // an uncaught throw propagates as error.Throw
    try std.testing.expectError(error.Throw, evalSource(a, "throw 'boom';"));
}

