test "interpreter String index search uses UTF-16 code units" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    try std.testing.expect((try evalSource(a,
        \\let bmp = "éaé";
        \\bmp.indexOf("a", 1) === 1 &&
        \\bmp.indexOf("é", 1) === 2 &&
        \\bmp.lastIndexOf("é") === 2 &&
        \\bmp.lastIndexOf("é", 1) === 0
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\let astral = "💩x💩";
        \\astral.indexOf("\uD83D") === 0 &&
        \\astral.indexOf("\uDCA9") === 1 &&
        \\astral.indexOf("\uD83D", 1) === 3 &&
        \\astral.indexOf("\uDCA9", 2) === 4 &&
        \\astral.lastIndexOf("\uD83D") === 3 &&
        \\astral.lastIndexOf("\uDCA9") === 4 &&
        \\astral.lastIndexOf("\uDCA9", 3) === 1 &&
        \\astral.lastIndexOf("\uD83D", 2) === 0
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\let lone = "\uD83Dx\uDCA9";
        \\lone.indexOf("\uD83D") === 0 &&
        \\lone.indexOf("\uDCA9") === 2 &&
        \\lone.lastIndexOf("\uDCA9") === 2 &&
        \\lone.indexOf("💩") === -1
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\let astral = "💩";
        \\astral.indexOf("", 1) === 1 &&
        \\astral.indexOf("", Infinity) === 2 &&
        \\astral.lastIndexOf("") === 2 &&
        \\astral.lastIndexOf("", 1) === 1 &&
        \\astral.lastIndexOf("", -1) === 0
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\let order = "";
        \\let search = { toString() { order += "s"; return "a"; } };
        \\let position = { valueOf() { order += "p"; return 1; } };
        \\let ok = "ba".indexOf(search, position) === 1 && order === "sp";
        \\order = "";
        \\ok &&= "ba".lastIndexOf(search, position) === 1 && order === "sp";
        \\ok
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\let prefix = "a".repeat(2048);
        \\let text = prefix + prefix + "b";
        \\text.indexOf(prefix + "b") === 2048 &&
        \\text.lastIndexOf(prefix + "b") === 2048 &&
        \\text.lastIndexOf(prefix, 2047) === 2047 &&
        \\"aaaaa".lastIndexOf("aaa") === 2
    )).asBool());
}

test "interpreter String replace and split use UTF-16 code units" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    try std.testing.expect((try evalSource(a,
        \\let astral = "💩";
        \\astral.replace("\uD83D", "H") === "H\uDCA9" &&
        \\astral.replace("\uDCA9", "L") === "\uD83DL" &&
        \\("x" + astral + "y" + astral).replaceAll("\uDCA9", "L") === "x\uD83DLy\uD83DL" &&
        \\astral.replaceAll("", "-") === "-\uD83D-\uDCA9-" &&
        \\"aaaaa".replaceAll("aaa", "X") === "Xaa"
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\let astral = "💩";
        \\let source = "x" + astral + "y" + astral;
        \\let calls = [];
        \\let result = source.replaceAll("\uDCA9", function (match, position, whole) {
        \\  calls.push(match.charCodeAt(0), position, whole === source);
        \\  return "L";
        \\});
        \\result === "x\uD83DLy\uD83DL" &&
        \\calls.join(",") === "56489,2,true,56489,5,true"
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\let astral = "💩";
        \\astral.replace("\uDCA9", "$`|$&|$'") === "\uD83D\uD83D|\uDCA9|" &&
        \\"\uD83Dx\uDCA9".replace("\uDCA9", "L") === "\uD83DxL"
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\let astral = "💩";
        \\let high = ("A" + astral + "B").split("\uD83D");
        \\let low = ("A" + astral + "B").split("\uDCA9");
        \\let limited = ("A" + astral + "B").split("\uD83D", 1);
        \\high.length === 2 && high[0] === "A" && high[1] === "\uDCA9B" &&
        \\low.length === 2 && low[0] === "A\uD83D" && low[1] === "B" &&
        \\limited.length === 1 && limited[0] === "A" &&
        \\"aaaaa".split("aaa").join("|") === "|aa"
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\let prefix = "a".repeat(2048);
        \\let text = prefix + prefix + "b";
        \\text.replaceAll(prefix + "b", "X") === prefix + "X" &&
        \\text.split(prefix + "b").join("|") === prefix + "|"
    )).asBool());
}

test "UTF-16 replacement match collection releases scratch on allocation failure" {
    const run = struct {
        fn check(backing: std.mem.Allocator) !void {
            var machine = Interpreter{
                .arena = backing,
                .scratch_allocator = backing,
                .env = undefined,
                .root_shape = undefined,
            };
            const haystack = "💩a💩a";
            const needle = "\xED\xB2\xA9a"; // WTF-8 U+DCA9 followed by "a".
            var positions = try machine.stringMatchPositionsUtf16(haystack, needle, 6, false, null);
            defer positions.deinit(backing);
            try std.testing.expectEqualSlices(u32, &.{ 1, 4 }, positions.items);
        }
    }.check;
    try std.testing.checkAllAllocationFailures(std.testing.allocator, run, .{});
}

test "interpreter numeric literals (separators, binary/octal) and optional chaining" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // numeric separators + radix prefixes
    try std.testing.expectEqual(@as(f64, 1000000), (try evalSource(a, "1_000_000")).asNum());
    try std.testing.expectEqual(@as(f64, 255), (try evalSource(a, "0b1111_1111")).asNum());
    try std.testing.expectEqual(@as(f64, 511), (try evalSource(a, "0o777")).asNum());
    try std.testing.expectEqual(@as(f64, 3000), (try evalSource(a, "3_000")).asNum());
    // optional chaining
    try std.testing.expect((try evalSource(a, "let o = { a: { b: 5 } }; o.a?.b === 5")).asBool());
    try std.testing.expect((try evalSource(a, "let o = {}; o.x?.y === undefined")).asBool());
    try std.testing.expect((try evalSource(a, "let o = null; o?.a?.b === undefined")).asBool());
    // optional call
    try std.testing.expect((try evalSource(a, "let o = { f: function () { return 7; } }; o.f?.() === 7")).asBool());
    try std.testing.expect((try evalSource(a, "let o = {}; o.missing?.() === undefined")).asBool());
    try std.testing.expect((try evalSource(a,
        \\const a = { _b: { c: 42 }, b() { return this._b; } };
        \\a?.b().c === 42 && (a?.b)().c === 42 && a.b?.().c === 42 && (a.b)?.().c === 42
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\const a = "global";
        \\function fn() { const a = "local"; return eval?.("a"); }
        \\fn() === "global" && ((a) => eval?.("a"))("local") === "global"
    )).asBool());
    // optional method short-circuits the whole chain
    try std.testing.expect((try evalSource(a, "let o = null; o?.a.b.c === undefined")).asBool());
}

test "interpreter arguments object and Array/Object statics" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // arguments object
    try std.testing.expectEqual(@as(f64, 6), (try evalSource(a, "function sum() { let s = 0; for (let i = 0; i < arguments.length; i++) { s += arguments[i]; } return s; } sum(1, 2, 3)")).asNum());
    try std.testing.expectEqualStrings("10,40,30", (try evalSource(a,
        \\function f(a, b, c) {
        \\  b = 40;
        \\  return [...arguments].join(",");
        \\}
        \\f(10, 20, 30)
    )).asStr());
    try std.testing.expect((try evalSource(a,
        \\function g8(h = () => arguments) {
        \\  var arguments = 0;
        \\  return arguments === 0 && arguments !== h();
        \\}
        \\function g9(h = () => arguments) {
        \\  var arguments;
        \\  let before = arguments === h() && arguments !== undefined;
        \\  arguments = 0;
        \\  return before && arguments === 0 && arguments !== h();
        \\}
        \\g8() && g9()
    )).asBool());
    // arrows have no own arguments (inherit) — here referencing arguments at top level is fine
    try std.testing.expectEqual(@as(f64, 3), (try evalSource(a, "function f() { return arguments.length; } f(7, 8, 9)")).asNum());
    // Array.of / from
    try std.testing.expectEqualStrings("1,2,3", (try evalSource(a, "'' + Array.of(1, 2, 3)")).asStr());
    try std.testing.expectEqualStrings("a,b,c", (try evalSource(a, "'' + Array.from('abc')")).asStr());
    // Object.entries / fromEntries
    try std.testing.expectEqual(@as(f64, 2), (try evalSource(a, "Object.entries({ a: 1, b: 2 }).length")).asNum());
    try std.testing.expectEqual(@as(f64, 5), (try evalSource(a, "let o = Object.fromEntries([['x', 5]]); o.x")).asNum());
}

test "interpreter Map and Set" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    try std.testing.expectEqual(@as(f64, 5), (try evalSource(a, "let m = new Map(); m.set('a', 5); m.get('a')")).asNum());
    try std.testing.expectEqual(@as(f64, 2), (try evalSource(a, "let m = new Map(); m.set('a', 1); m.set('b', 2); m.size")).asNum());
    try std.testing.expect((try evalSource(a, "let m = new Map(); m.set('k', 1); m.has('k')")).asBool());
    try std.testing.expectEqual(@as(f64, 1), (try evalSource(a, "let m = new Map([['a', 1], ['b', 2]]); m.delete('b'); m.size")).asNum());
    try std.testing.expectEqualStrings("foo:0|bar:1|foo:baz", (try evalSource(a,
        \\let m = new Map([['foo', 0], ['bar', 1]]);
        \\let out = [];
        \\m.forEach(function(value, key) {
        \\  out.push(key + ':' + value);
        \\  if (key === 'foo' && value === 0) { m.delete('foo'); m.set('foo', 'baz'); }
        \\});
        \\out.join('|')
    )).asStr());
    try std.testing.expect((try evalSource(a,
        \\let ok = false;
        \\let m = new Map([[1, 'present']]);
        \\try { m.getOrInsertComputed(1, 1); } catch (e) { ok = e instanceof TypeError; }
        \\ok
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\let seen;
        \\let m = new Map();
        \\m.getOrInsertComputed(-0, function(key) { seen = 1 / key; return 'value'; });
        \\seen === Infinity && m.get(+0) === 'value'
    )).asBool());
    try std.testing.expectEqual(@as(f64, 3), (try evalSource(a, "let s = new Set([1, 2, 2, 3, 3]); s.size")).asNum());
    try std.testing.expect((try evalSource(a, "let s = new Set(); s.add(7); s.has(7)")).asBool());
    try std.testing.expectEqual(@as(f64, 6), (try evalSource(a, "let s = new Set([1, 2, 3]); let t = 0; s.forEach(function (v) { t += v; }); t")).asNum());
    try std.testing.expect((try evalSource(a,
        \\let m = new Map([[1, 11], [2, 22]]);
        \\let mi = m[Symbol.iterator]();
        \\let r = mi.next();
        \\let ok = r.value[0] === 1 && r.value[1] === 11 && r.done === false;
        \\m.set(3, 33);
        \\r = mi.next();
        \\ok = ok && r.value[0] === 2 && r.value[1] === 22 && r.done === false;
        \\r = mi.next();
        \\ok = ok && r.value[0] === 3 && r.value[1] === 33 && r.done === false;
        \\ok = ok && mi.next().done === true;
        \\m.set(4, 44);
        \\ok = ok && mi.next().done === true;
        \\ok
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\let s = new Set([1, 2]);
        \\let si = s.values();
        \\let ok = si.next().value === 1;
        \\s.add(3);
        \\ok = ok && si.next().value === 2;
        \\ok = ok && si.next().value === 3;
        \\ok = ok && si.next().done === true;
        \\s.add(4);
        \\ok = ok && si.next().done === true;
        \\let ei = s.entries();
        \\let e = ei.next().value;
        \\ok = ok && e[0] === 1 && e[1] === 1;
        \\ok
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\let m = new Map([[1, 'one'], [2, 'two'], [3, 'three']]);
        \\let it = m.entries();
        \\let first = it.next().value;
        \\let ok = first[0] === 1 && Object.getOwnPropertyNames(it).length === 0;
        \\m.delete(2);
        \\m.set(2, 'two-again');
        \\let second = it.next().value;
        \\let third = it.next().value;
        \\ok = ok && second[0] === 3 && third[0] === 2 && third[1] === 'two-again';
        \\ok = ok && it.next().done === true;
        \\let cleared = m.keys();
        \\ok = ok && cleared.next().value === 1;
        \\m.clear();
        \\m.set(4, 'four');
        \\m.set(5, 'five');
        \\ok = ok && cleared.next().value === 4 && cleared.next().value === 5 && cleared.next().done === true;
        \\let a = m.values(), b = m.values();
        \\ok = ok && a.next().value === 'four' && b.next().value === 'four';
        \\ok
    )).asBool());
    try std.testing.expectEqualStrings("1|3|2", (try evalSource(a,
        \\let s = new Set([1, 2, 3]);
        \\let out = [];
        \\let moved = false;
        \\s.forEach(function(v) {
        \\  out.push(v);
        \\  if (v === 1 && !moved) { moved = true; s.delete(2); s.add(2); }
        \\});
        \\out.join('|')
    )).asStr());
}

