test "Intl.DateTimeFormat resolved-state publication is OOM-safe" {
    const run = struct {
        fn check(backing: std.mem.Allocator) !void {
            var arena = std.heap.ArenaAllocator.init(backing);
            defer arena.deinit();
            const allocator = arena.allocator();
            const root_shape = try Shape.createRoot(allocator);
            var machine = Interpreter{
                .arena = allocator,
                .env = undefined,
                .root_shape = root_shape,
            };
            var formatter = value.Object{};
            try dtfStoreOptions(&machine, &formatter, "de-DE-u-nu-latn", .{
                .weekday = "short",
                .year = "numeric",
                .month = "long",
                .day = "2-digit",
                .hour = "2-digit",
                .minute = "2-digit",
                .calendar = "gregory",
                .numbering_system = "latn",
                .hour_cycle = "h23",
                .time_zone = "UTC",
            }, false);
            const data = formatter.intlDateTimeFormatData().?;
            try std.testing.expectEqualStrings("de-DE-u-nu-latn", data.resolved_locale);
            try std.testing.expectEqualStrings("gregory", data.calendar);
            try std.testing.expectEqualStrings("latn", data.numbering_system);
            try std.testing.expectEqual(value.IntlDateTimeFormatData.HourCycle.h23, data.hour_cycle);
            try std.testing.expectEqualStrings("h23", data.hour_cycle.string());
            try std.testing.expectEqual(value.IntlDateTimeFormatData.DayPeriod.none, data.day_period);
            try std.testing.expectEqual(value.IntlDateTimeFormatData.Field.two_digit, data.hour);
            try std.testing.expectEqualStrings("long", data.month.string());

            var twelve_hour_formatter = value.Object{};
            try dtfStoreOptions(&machine, &twelve_hour_formatter, "en-US", .{
                .hour = "numeric",
                .minute = "numeric",
                .second = "numeric",
                .hour_cycle = "h12",
                .time_zone = "UTC",
            }, false);
            const twelve_hour = twelve_hour_formatter.intlDateTimeFormatData().?;
            try std.testing.expectEqual(value.IntlDateTimeFormatData.DayPeriod.am_pm_short, twelve_hour.day_period);
            try std.testing.expectEqual(value.IntlDateTimeFormatData.Field.short, twelve_hour.day_period.field());
            try std.testing.expectEqual(value.IntlDateTimeFormatData.Field.numeric, twelve_hour.hour);
            try std.testing.expectEqual(value.IntlDateTimeFormatData.Field.two_digit, twelve_hour.minute);
            try std.testing.expectEqual(value.IntlDateTimeFormatData.Field.two_digit, twelve_hour.second);

            var structural_scratch = std.heap.ArenaAllocator.init(backing);
            defer structural_scratch.deinit();
            const scratch = structural_scratch.allocator();

            // Latin numeric fields must copy stack formatting into invocation
            // storage; translated fields additionally own their expanded UTF-8.
            var latin_parts = DtfParts{};
            var latin = DtfOutput{ .mode = .parts, .parts = &latin_parts, .scratch = scratch };
            try latin.pushInt(&machine, .year, 2024, false);
            try latin.pushCopied(&machine, .month, "06bis");
            try latin.push(&machine, .literal, ", ");
            try std.testing.expectEqualStrings("2024", latin_parts.items()[0].value);
            try std.testing.expectEqualStrings("06bis", latin_parts.items()[1].value);
            try std.testing.expectEqual(Value.str(", "), latin_parts.items()[2].static_value.?);
            try std.testing.expectEqual(Value.str(", "), try latin_parts.items()[2].materialize(backing));

            var translated_parts = DtfParts{};
            var translated = DtfOutput{ .mode = .parts, .parts = &translated_parts, .scratch = scratch, .numbering_system = "deva" };
            try translated.pushInt(&machine, .day, 9, true);
            try translated.pushCopied(&machine, .fractional_second, "789");
            try std.testing.expectEqualStrings("०९", translated_parts.items()[0].value);
            try std.testing.expectEqualStrings("७८९", translated_parts.items()[1].value);

            try std.testing.expectEqualStrings("甲辰", try dtfChineseYearName(scratch, 2024));
            try std.testing.expectEqualStrings("GMT+5:30", try dtfOffsetZoneName(scratch, 19_800_000_000_000));
        }
    }.check;
    const previous_heap = gc_mod.setActiveHeap(null);
    defer _ = gc_mod.setActiveHeap(previous_heap);
    try std.testing.checkAllAllocationFailures(std.testing.allocator, run, .{});
}

test "Intl cached bound accessor publication is failure-atomic" {
    const run = struct {
        fn check(backing: std.mem.Allocator) !void {
            var arena = std.heap.ArenaAllocator.init(backing);
            defer arena.deinit();
            const allocator = arena.allocator();
            const root_shape = try Shape.createRoot(allocator);
            var machine = Interpreter{
                .arena = allocator,
                .scratch_allocator = allocator,
                .env = undefined,
                .root_shape = root_shape,
            };
            var implementation = value.Object{};
            var formatter = value.Object{};

            const first = machine.makeBoundExact(&implementation, Value.obj(&formatter), &.{}, 1, Value.str("")) catch |err| {
                try std.testing.expect(formatter.getOwn("\x00boundFormat") == null);
                return err;
            };
            const published = formatter.setOwnIfAbsentWithAttr(
                allocator,
                root_shape,
                "\x00boundFormat",
                first,
                .{ .writable = false, .enumerable = false, .configurable = false },
            ) catch |err| {
                try std.testing.expect(formatter.getOwn("\x00boundFormat") == null);
                return err;
            } orelse first;
            try std.testing.expectEqual(first, published);
            try std.testing.expectEqualStrings("", published.asObj().getOwn("name").?.asStr());
            try std.testing.expectEqual(@as(f64, 1), published.asObj().getOwn("length").?.asNum());

            const competing = machine.makeBoundExact(&implementation, Value.obj(&formatter), &.{}, 1, Value.str("")) catch |err| {
                try std.testing.expectEqual(published, formatter.getOwn("\x00boundFormat").?);
                return err;
            };
            const winner = (try formatter.setOwnIfAbsentWithAttr(
                allocator,
                root_shape,
                "\x00boundFormat",
                competing,
                .{ .writable = false, .enumerable = false, .configurable = false },
            )) orelse competing;
            try std.testing.expectEqual(published, winner);
            try std.testing.expectEqual(value.PropAttr{ .writable = false, .enumerable = false, .configurable = false }, formatter.getAttr("\x00boundFormat"));
        }
    }.check;
    const previous_heap = gc_mod.setActiveHeap(null);
    defer _ = gc_mod.setActiveHeap(previous_heap);
    try std.testing.checkAllAllocationFailures(std.testing.allocator, run, .{});
}

