test "Intl.NumberFormat sink emission is OOM-safe" {
    const run = struct {
        fn check(backing: std.mem.Allocator) !void {
            var arena = std.heap.ArenaAllocator.init(backing);
            defer arena.deinit();
            var machine = Interpreter{ .arena = arena.allocator(), .env = undefined, .root_shape = undefined };
            var text = NfOutput{ .mode = .text, .numbering_system = "deva" };
            try text.push(&machine, .integer, "1234567");
            try text.push(&machine, .decimal, ".");
            try text.push(&machine, .fraction, "89");
            try std.testing.expectEqualStrings("१२३४५६७.८९", text.text.items);

            var structural_scratch = std.heap.ArenaAllocator.init(backing);
            defer structural_scratch.deinit();
            var parts = NfOutput{ .mode = .parts, .scratch = structural_scratch.allocator(), .numbering_system = "deva" };
            try parts.push(&machine, .integer, "1234567");
            try parts.push(&machine, .decimal, ".");
            try parts.push(&machine, .fraction, "89");
            try std.testing.expectEqual(@as(usize, 3), parts.parts.items.len);
            var joined: std.ArrayListUnmanaged(u8) = .empty;
            try nfAppendPartValues(&machine, &joined, parts.parts.items);
            try std.testing.expectEqualStrings(text.text.items, joined.items);

            const exact = try nfRoundExact(&machine, "1234567890123456789012345678901234567890", 1, false, 1, 0, 3, null, null, true, "auto", 1, "halfExpand");
            try std.testing.expectEqualStrings("1", exact.int_str);
            try std.testing.expectEqualStrings("235", exact.frac_str);
            const currency = cldr_numbers.currency("ro", "RON", "other");
            try std.testing.expectEqualStrings("de lei românești", try nfCurrencyDisplayName(machine.arena, currency));

            const interval = cldr_numbers.numberRange("ja-JP", "latn");
            const start = [_]NfPart{ .{ .typ = .integer, .value = "1235" }, .{ .typ = .compact, .value = "万" } };
            const end = [_]NfPart{ .{ .typ = .integer, .value = "2346" }, .{ .typ = .compact, .value = "万" } };
            try std.testing.expectEqualStrings("1235万 ～ 2346万", try nfFormatRangePartsText(&machine, interval, &start, &end));
        }
    }.check;
    const previous_heap = gc_mod.setActiveHeap(null);
    defer _ = gc_mod.setActiveHeap(previous_heap);
    try std.testing.checkAllAllocationFailures(std.testing.allocator, run, .{});
}

test "Intl.DurationFormat resolved-state publication is OOM-safe" {
    const run = struct {
        fn check(backing: std.mem.Allocator) !void {
            var arena = std.heap.ArenaAllocator.init(backing);
            defer arena.deinit();
            const allocator = arena.allocator();
            const root_shape = try Shape.createRoot(allocator);
            var machine = Interpreter{ .arena = allocator, .env = undefined, .root_shape = root_shape };
            var formatter = value.Object{};
            var options = DurationFormatOptions{
                .style = .digital,
                .explicit_styles = @splat(null),
                .explicit_displays = @splat(null),
                .unit_styles = undefined,
                .unit_displays = undefined,
                .fractional_digits = 3,
            };
            options.explicit_styles[4] = .numeric;
            options.explicit_styles[5] = .numeric;
            options.explicit_styles[6] = .two_digit;
            try std.testing.expect(!resolveDurationUnitOptions(&options));
            try installDurationFormatData(&machine, &formatter, "en-US-u-nu-arab", &options);
            const data = formatter.intlDurationFormatData().?;
            try std.testing.expectEqualStrings("en-US-u-nu-arab", data.locale);
            try std.testing.expectEqualStrings("arab", data.numbering_system);
            try std.testing.expectEqual(value.IntlDurationFormatData.Style.digital, data.style);
            try std.testing.expectEqual(value.IntlDurationFormatData.UnitStyle.two_digit, data.unit_styles[5]);
            try std.testing.expectEqual(value.IntlDurationFormatData.Display.always, data.unit_displays[6]);
            try std.testing.expectEqual(@as(?u8, 3), data.fractional_digits);
        }
    }.check;
    const previous_heap = gc_mod.setActiveHeap(null);
    defer _ = gc_mod.setActiveHeap(previous_heap);
    try std.testing.checkAllAllocationFailures(std.testing.allocator, run, .{});
}

