        \\var invalid = false;
        \\try {
        \\  formatter.formatRange(
        \\    { valueOf: function () { invalidOrder = invalidOrder + "a"; return Infinity; } },
        \\    { valueOf: function () { invalidOrder = invalidOrder + "b"; return Infinity; } }
        \\  );
        \\} catch (error) {
        \\  invalid = error instanceof RangeError;
        \\}
