test "Function metadata canonicalizes physical StringData names" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();

    const result = try evalSource(
        allocator,
        "let reads = ''; " ++
            "function target(a, b) {} " ++
            "Object.defineProperty(target, 'name', { configurable: true, get() { reads += 'n'; return 'caf\xc3\xa9'; } }); " ++
            "let bound = target.bind(null, 1); " ++
            "let native = Object.prototype.valueOf; " ++
            "Object.defineProperty(native, 'name', { configurable: true, value: 'caf\xc3\xa9' }); " ++
            "bound.name + '|' + bound.length + '|' + reads + '|' + native.toString()",
    );
    try std.testing.expectEqualStrings(
        "bound caf\xc3\xa9|1|n|function caf\xc3\xa9() { [native code] }",
        try result.asWtf8(allocator),
    );
}

test "JSON stringify promotes deep active paths without rejecting aliases" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    try std.testing.expect((try evalSource(arena.allocator(),
        \\let leaf = { marker: 7 };
        \\let deep = leaf;
        \\for (let i = 0; i < 256; i++) deep = { next: deep };
        \\let encoded = JSON.stringify({ deep, aliases: [leaf, leaf] });
        \\encoded.includes('"marker":7') &&
        \\  encoded.endsWith('"aliases":[{"marker":7},{"marker":7}]}')
    )).asBool());
}

test "JSON stringify replacer property list preserves exact seeded membership" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    try std.testing.expect((try evalSource(arena.allocator(),
        \\let coercions = [];
        \\let nulKey = "\u0000wide";
        \\let wideKey = "w".repeat(4096);
        \\let stringKey = new String("b");
        \\stringKey.toString = function () { coercions.push("string"); return "b"; };
        \\let numberKey = new Number(1);
        \\numberKey.toString = function () { coercions.push("number"); return "1"; };
        \\let ignored = { toString() { coercions.push("ignored"); return "ignored"; } };
        \\let object = { b: 2, 1: 3 };
        \\object[nulKey] = 4;
        \\object[wideKey] = 5;
        \\let encoded = JSON.stringify(object, [nulKey, wideKey, stringKey, nulKey, numberKey, wideKey, stringKey, ignored]);
        \\encoded === '{"\\u0000wide":4,"' + wideKey + '":5,"b":2,"1":3}' &&
        \\  coercions.join(",") === "string,number,string"
    )).asBool());
}

test "JSON stringify truncates gap by UTF-16 code units" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    try std.testing.expectEqualStrings(
        "{\n0123456789\"a\": 1\n}",
        (try evalSource(arena.allocator(), "JSON.stringify({ a: 1 }, null, '0123456789tail')")).asStr(),
    );
    try std.testing.expectEqualStrings("true,true,true,true,true", (try evalSource(arena.allocator(),
        \\let value = { a: 1 };
        \\let astral = String.fromCodePoint(0x1F4A9);
        \\let high = String.fromCharCode(0xD83D);
        \\let expected = gap => "{\n" + gap + '"a": 1\n}';
        \\[
        \\  JSON.stringify(value, null, "\u00E9".repeat(12)) === expected("\u00E9".repeat(10)),
        \\  JSON.stringify(value, null, astral.repeat(6)) === expected(astral.repeat(5)),
        \\  JSON.stringify(value, null, "x".repeat(9) + astral + "tail") === expected("x".repeat(9) + high),
        \\  JSON.stringify(value, null, "x".repeat(9) + high + "tail") === expected("x".repeat(9) + high),
        \\  JSON.stringify(value, null, new String("\u00E9".repeat(12))) === expected("\u00E9".repeat(10))
        \\].join(",")
    )).asStr());
}

