        \\class Counter {
        \\  #count = 0;
        \\  #step() { return 10; }
        \\  bump() { this.#count = this.#count + this.#step(); return this.#count; }
        \\}
        \\let c = new Counter();
        \\c.bump(); c.bump(); c.bump()
    )).asNum());
    // static initialization block
    try std.testing.expectEqual(@as(f64, 42), (try evalSource(a,
        \\class C { static x; static { this.x = 42; } }
        \\C.x
    )).asNum());
    // A nested class body can use private names from the enclosing class body.
    try std.testing.expectEqual(@as(f64, 42), (try evalSource(a,
        \\class Outer {
        \\  #x = 42;
        \\  f() {
        \\    var self = this;
        \\    return class Inner { g() { return self.#x; } };
        \\  }
        \\}
        \\var Inner = new Outer().f();
        \\new Inner().g()
    )).asNum());
    try std.testing.expectEqual(@as(f64, 42), (try evalSource(a,
        \\class Base { constructor(obj) { return obj; } }
        \\class C extends Base {
        \\  constructor(obj) { super(obj); }
        \\  #m() { return 42; }
        \\  static val(obj) { return obj.#m(); }
        \\}
        \\C.val(new C({}))
    )).asNum());
    try std.testing.expectError(error.Throw, evalSource(a,
        \\class Base { constructor(obj) { return obj; } }
        \\class C extends Base {
        \\  constructor(obj) { super(obj); }
        \\  #m() { return 42; }
        \\}
        \\new C(Object.preventExtensions({}))
    ));
}

test "interpreter getters and setters" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // object literal getter/setter
    try std.testing.expectEqual(@as(f64, 42), (try evalSource(a,
        \\let o = { _v: 0, get v() { return this._v; }, set v(x) { this._v = x * 2; } };
        \\o.v = 21;
        \\o.v
    )).asNum());
    try std.testing.expect((try evalSource(a,
        \\let getter = Object.getOwnPropertyDescriptor({ get f() {} }, "f").get;
        \\let method = ({ m() {} }).m;
        \\let getterBefore = Object.prototype.hasOwnProperty.call(getter, "prototype");
        \\let methodBefore = Object.prototype.hasOwnProperty.call(method, "prototype");
        \\Object.defineProperty(getter, "prototype", { get() { return 1; }, configurable: true });
        \\Object.defineProperty(method, "prototype", { value: 2, configurable: true });
        \\getterBefore === false && methodBefore === false && getter.prototype === 1 && method.prototype === 2
    )).asBool());
    // class getter via prototype
    try std.testing.expectEqual(@as(f64, 25), (try evalSource(a,
        \\class Sq { constructor(n) { this.n = n; } get area() { return this.n * this.n; } }
        \\(new Sq(5)).area
    )).asNum());
    // class setter
    try std.testing.expectEqual(@as(f64, 6), (try evalSource(a,
        \\class C { set half(x) { this.stored = x / 2; } }
        \\let c = new C(); c.half = 12; c.stored
    )).asNum());
    try std.testing.expectEqualStrings("outer", (try evalSource(a,
        \\let name = "outer";
        \\let o = { get name() { return name; } };
        \\o.name
    )).asStr());
    try std.testing.expect((try evalSource(a,
        \\let f = function inner() { return inner === f; };
        \\f()
    )).asBool());
}

test "ordinary property fused set and delete preserve receiver descriptors" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    try std.testing.expect((try evalSource(a,
        \\var proto = {};
        \\Object.defineProperty(proto, "blocked", { value: 1, writable: false });
        \\var receiver = Object.create(proto);
        \\receiver.blocked = 2;
        \\receiver.created = 3;
        \\receiver.created = 4;
        \\var getterOnly = {};
        \\Object.defineProperty(getterOnly, "value", { get() { return 7; }, configurable: true });
        \\getterOnly.value = 9;
        \\!Object.prototype.hasOwnProperty.call(receiver, "blocked") &&
        \\receiver.blocked === 1 && receiver.created === 4 && getterOnly.value === 7
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\var object = { first: 1 };
        \\Object.defineProperty(object, "accessor", { get() { return 2; }, configurable: true });
        \\Object.defineProperty(object, "fixed", { value: 3, enumerable: true, configurable: false });
        \\var removedData = Reflect.deleteProperty(object, "first");
        \\var removedAccessor = Reflect.deleteProperty(object, "accessor");
        \\var keptFixed = !Reflect.deleteProperty(object, "fixed");
        \\object.first = 4;
        \\removedData && removedAccessor && keptFixed &&
        \\Object.keys(object).join(",") === "fixed,first" && object.first === 4
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\var array = [1];
        \\var inner = new Proxy(array, {});
        \\var outer = new Proxy(inner, { deleteProperty: undefined });
        \\var keptLength = !Reflect.deleteProperty(outer, "length");
        \\var removedIndex = Reflect.deleteProperty(outer, "0");
        \\keptLength && removedIndex && array.length === 1 && !array.hasOwnProperty("0")
    )).asBool());
}

test "interpreter class extends and super" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // super() in constructor + inherited method
    try std.testing.expectEqual(@as(f64, 30), (try evalSource(a,
        \\class Animal { constructor(n) { this.legs = n; } legCount() { return this.legs; } }
        \\class Dog extends Animal { constructor() { super(4); } }
        \\let d = new Dog();
        \\d.legCount() * 7 + 2
    )).asNum());
    // super.method() calls the parent's version
    try std.testing.expectEqual(@as(f64, 11), (try evalSource(a,
        \\class A { val() { return 10; } }
        \\class B extends A { val() { return super.val() + 1; } }
        \\(new B()).val()
    )).asNum());
    // instanceof across the chain
    try std.testing.expect((try evalSource(a,
        \\class A {}
        \\class B extends A {}
        \\let b = new B();
        \\b instanceof B && b instanceof A
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\class F extends Function {}
        \\let inst = new F("x", "return this.bar + x");
        \\let bound = inst.bind({ bar: 3 }, 4);
        \\let ok = bound instanceof F && bound() === 7;
        \\Object.setPrototypeOf(inst, null);
        \\bound = Function.prototype.bind.call(inst, { bar: 1 }, 3);
        \\ok && Object.getPrototypeOf(bound) === null && bound() === 4
    )).asBool());
    // default derived constructor forwards args
    try std.testing.expectEqual(@as(f64, 42), (try evalSource(a,
        \\class Base { constructor(x) { this.x = x; } }
        \\class Sub extends Base {}
        \\(new Sub(42)).x
    )).asNum());
    // inherited static method
    try std.testing.expectEqual(@as(f64, 16), (try evalSource(a,
        \\class P { static sq(n) { return n * n; } }
        \\class C extends P {}
        \\C.sq(4)
    )).asNum());
    try std.testing.expect((try evalSource(a,
        \\var evaluated = false;
        \\var caught;
        \\class C extends Object {
        \\  constructor() {
        \\    try { super(evaluated = true); } catch (e) { caught = e; }
        \\  }
        \\}
        \\Object.setPrototypeOf(C, parseInt);
        \\try { new C(); } catch (e) {}
        \\evaluated && caught instanceof TypeError
    )).asBool());
    try std.testing.expectEqualStrings("Symbol(foo)", (try evalSource(a,
        \\class Base { constructor(v) { this.v = v; } }
        \\class C extends Base {
        \\  constructor() { super(Symbol("foo")); }
        \\}
        \\new C().v.toString()
    )).asStr());
    try std.testing.expectEqualStrings("prop", (try evalSource(a,
        \\var log = "";
        \\class B {}
        \\class C extends B {
        \\  m() {
        \\    function prop() { log += "prop"; throw "stop"; }
        \\    function rhs() { log += "rhs"; }
        \\    try { super[prop()] = rhs(); } catch (e) {}
        \\  }
        \\}
        \\new C().m();
        \\log
    )).asStr());
    try std.testing.expectEqualStrings("rhs,key", (try evalSource(a,
        \\var log = "";
        \\var key = { toString() { log += ",key"; return "x"; } };
        \\class B {}
        \\class C extends B {
        \\  m() {
        \\    function rhs() { log += "rhs"; return 1; }
        \\    super[key] = rhs();
        \\  }
        \\}
        \\new C().m();
        \\log
    )).asStr());
    try std.testing.expectEqual(@as(f64, 1), (try evalSource(a,
        \\var count = 0;
        \\class C { static m() { super.x = count += 1; } }
        \\Object.setPrototypeOf(C, null);
        \\try { C.m(); } catch (e) {}
        \\count
    )).asNum());
    try std.testing.expectError(error.Throw, evalSource(a, "class C {} C()"));
    try std.testing.expectError(error.Throw, evalSource(a,
        \\class C extends Object { constructor() {} }
        \\new C()
    ));
    try std.testing.expectError(error.Throw, evalSource(a,
        \\class C extends Object { constructor() { return null; } }
        \\new C()
    ));
    try std.testing.expect((try evalSource(a,
        \\class C extends Object { constructor() { return { ok: true }; } }
        \\new C().ok
    )).asBool());
}

test "interpreter assignment and parameter destructuring" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // assignment destructuring (array)
    try std.testing.expectEqual(@as(f64, 12), (try evalSource(a, "let x = 0, y = 0; [x, y] = [10, 2]; x + y")).asNum());
    // assignment destructuring (object) — needs parens at statement start
    try std.testing.expectEqual(@as(f64, 3), (try evalSource(a, "let a2 = 0, b2 = 0; ({ a: a2, b: b2 } = { a: 1, b: 2 }); a2 + b2")).asNum());
    // destructuring into a member target
    try std.testing.expectEqual(@as(f64, 9), (try evalSource(a, "let o = {}; [o.x] = [9]; o.x")).asNum());
    // parameter destructuring
    try std.testing.expectEqual(@as(f64, 7), (try evalSource(a, "function f({ x, y }) { return x + y; } f({ x: 3, y: 4 })")).asNum());
    try std.testing.expectEqual(@as(f64, 30), (try evalSource(a, "function g([a3, b3]) { return a3 * b3; } g([5, 6])")).asNum());
    // parameter default + destructuring
    try std.testing.expectEqual(@as(f64, 5), (try evalSource(a, "function h({ n = 5 }) { return n; } h({})")).asNum());
}

test "interpreter destructuring declarations" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // object pattern
    try std.testing.expectEqual(@as(f64, 3), (try evalSource(a, "let { a, b } = { a: 1, b: 2 }; a + b")).asNum());
    // object pattern with rename + default
    try std.testing.expectEqual(@as(f64, 12), (try evalSource(a, "let { a: x, c = 10 } = { a: 2 }; x + c")).asNum());
    // array pattern with hole and rest
    try std.testing.expectEqualStrings("1|3,4", (try evalSource(a, "let [first, , ...rest] = [1, 2, 3, 4]; first + '|' + rest")).asStr());
    // nested pattern
    try std.testing.expectEqual(@as(f64, 7), (try evalSource(a, "let { p: { x, y } } = { p: { x: 3, y: 4 } }; x + y")).asNum());
    // var destructuring names are hoisted before assignment patterns run
    try std.testing.expectEqual(@as(f64, 17), (try evalSource(a,
        \\function objectWithProtoProperty(v) {
        \\  var obj = {};
        \\  return Object.defineProperty(obj, "__proto__", {
        \\    enumerable: true,
        \\    configurable: true,
        \\    writable: true,
        \\    value: v,
        \\  });
        \\}
        \\({ __proto__ } = objectWithProtoProperty(17));
        \\var { __proto__ } = objectWithProtoProperty(42);
        \\__proto__ - 25
    )).asNum());
    // object rest collects the remaining own properties
    try std.testing.expectEqual(@as(f64, 5), (try evalSource(a, "let { a, ...others } = { a: 1, b: 2, c: 3 }; others.b + others.c")).asNum());
}

test "interpreter spread in arrays and calls" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // spread in an array literal
    try std.testing.expectEqualStrings("1,2,3,4", (try evalSource(a, "let xs = [2, 3]; '' + [1, ...xs, 4]")).asStr());
    // spread a string into an array
    try std.testing.expectEqualStrings("a,b,c", (try evalSource(a, "'' + [...'abc']")).asStr());
    // spread args into a call
    try std.testing.expectEqual(@as(f64, 6), (try evalSource(a,
        \\function add(a, b, c) { return a + b + c; }
        \\let args = [1, 2, 3];
        \\add(...args)
    )).asNum());
    // mixed fixed + spread args
    try std.testing.expectEqual(@as(f64, 10), (try evalSource(a,
        \\function add(a, b, c, d) { return a + b + c + d; }
        \\add(1, ...[2, 3], 4)
    )).asNum());
}

test "interpreter default and rest parameters" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // default used when arg missing/undefined
    try std.testing.expectEqual(@as(f64, 5), (try evalSource(a, "function f(a, b = 3) { return a + b; } f(2)")).asNum());
    try std.testing.expectEqual(@as(f64, 6), (try evalSource(a, "function f(a, b = 3) { return a + b; } f(2, 4)")).asNum());
    // default can reference an earlier parameter
    try std.testing.expectEqual(@as(f64, 4), (try evalSource(a, "function f(a, b = a * 2) { return b; } f(2)")).asNum());
    // rest collects remaining args into an array
    try std.testing.expectEqual(@as(f64, 3), (try evalSource(a, "function f(a, ...rest) { return rest.length; } f(1, 2, 3, 4)")).asNum());
    try std.testing.expectEqual(@as(f64, 30), (try evalSource(a,
        \\function sum(...xs) { let s = 0; for (let v of xs) { s = s + v; } return s; }
        \\sum(10, 20)
    )).asNum());
}

test "interpreter object method shorthand and computed keys" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // method shorthand binds this
    try std.testing.expectEqual(@as(f64, 10), (try evalSource(a,
        \\let o = { n: 10, get() { return this.n; } };
        \\o.get()
    )).asNum());
    // computed key
    try std.testing.expectEqual(@as(f64, 5), (try evalSource(a,
        \\let k = 'x';
        \\let o = { [k]: 5 };
        \\o.x
    )).asNum());
    // computed key from an expression
    try std.testing.expectEqualStrings("ok", (try evalSource(a,
        \\let o = { ['a' + 'b']: 'ok' };
        \\o.ab
    )).asStr());
    // VM-created concise methods still close over outer bindings instead of
    // self-binding their display name.
    try std.testing.expectEqualStrings("outer", (try evalSource(a,
        \\function* g() {
        \\  let buffer = 'outer';
        \\  yield { buffer() { return buffer; } };
        \\}
        \\let { buffer } = g().next().value;
        \\buffer()
    )).asStr());
    // NamedEvaluation sets Function.name, but must not create a lexical
    // self-binding for an anonymous function.
    try std.testing.expectEqualStrings("outer", (try evalSource(a,
        \\let f = 'outer';
        \\function* g() {
        \\  yield { f: function() { return f; } };
        \\}
        \\g().next().value.f()
    )).asStr());
}

test "interpreter labeled break and continue" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // labeled break exits the outer loop
    try std.testing.expectEqual(@as(f64, 23), (try evalSource(a,
        \\let hits = 0, found = 0;
        \\outer: for (let i = 0; i < 5; i++) {
        \\  for (let j = 0; j < 5; j++) {
        \\    hits = hits + 1;
        \\    if (i === 2 && j === 3) { found = i * 10 + j; break outer; }
        \\  }
        \\}
        \\found
    )).asNum());
    // labeled continue continues the outer loop
    try std.testing.expectEqual(@as(f64, 5), (try evalSource(a,
        \\let count = 0;
        \\outer: for (let i = 0; i < 5; i++) {
        \\  for (let j = 0; j < 5; j++) {
        \\    if (j === 1) { continue outer; }
        \\  }
        \\  count = count + 100; // never reached
        \\}
        \\let n = 0;
        \\outer2: for (let i = 0; i < 5; i++) { n = n + 1; continue outer2; }
        \\n
    )).asNum());
}

test "Annex B labeled block function updates legacy binding" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    try std.testing.expect((try evalSource(a,
        \\eval("fe(); l: function fe() { return 7; }");
        \\fe() === 7
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\{ f(); l: function f() { return 4; } }
        \\f() === 4
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\{
        \\  f();
        \\  function f() { return 3; }
        \\  f();
        \\  function f() { return 4; }
        \\  f();
        \\}
        \\f() === 4
    )).asBool());
    try std.testing.expect((try evalSource(a,
        \\{
        \\  f();
        \\  function f() { return 3; }
        \\  f();
        \\  l: function f() { return 4; }
        \\  f();
        \\}
        \\f() === 4
    )).asBool());
}

test "Annex B secure legacy name membership preserves exact eligibility" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    // The invocation-local name index hashes the exact decoded identifier bytes,
    // including identifiers large enough to make collision resistance material.
    const wide = try a.alloc(u8, 4096);
    @memset(wide, 'w');
    const wide_source = try std.fmt.allocPrint(
        a,
        "{{ function {s}() {{ return 41; }} }} {s}()",
        .{ wide, wide },
    );
    try std.testing.expectEqual(@as(f64, 41), (try evalSource(a, wide_source)).asNum());

    try std.testing.expect((try evalSource(a,
        \\var duplicateResult, labeledResult, switchResult;
        \\{ function duplicate() { return 1; } function duplicate() { return 2; } duplicateResult = duplicate(); }
        \\label: function \u0065scaped() { return 3; }
        \\labeledResult = escaped();
        \\switch (1) { case 1: function switched() { return 4; } }
        \\switchResult = switched();
        \\var parameterExact = (function(parameterName) {
        \\  { function parameterName() { return 5; } }
        \\  return parameterName;
        \\})(6);
        \\{ let lexicalName = 7; { function lexicalName() { return 8; } } }
        \\try { throw { catchName: 9 }; }
        \\catch ({ catchName }) { { function catchName() { return 10; } } }
        \\duplicateResult === 2 && labeledResult === 3 && switchResult === 4 &&
        \\  parameterExact === 6 && typeof lexicalName === "undefined" &&
        \\  typeof catchName === "undefined"
    )).asBool());
}

test "Annex B grouped destructuring lexicals block eval legacy bindings" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();

    // Every BoundName in a LexicalDeclaration excludes the corresponding
    // Annex B legacy var, including patterns after another declarator. A
    // sloppy eval's lexical record disappears afterward; a wrongly created
    // variable binding would remain observable in the surrounding scope.
    try std.testing.expect((try evalSource(allocator,
        \\var retained = 3;
        \\eval('let unused, { leakedObject } = {}; { function leakedObject() {} }');
        \\eval('const unused = 0, [leakedArray] = []; { function leakedArray() {} }');
        \\eval('let unused, { retained } = {}; { function retained() {} }');
        \\eval('{ function admitted() {} }');
        \\typeof leakedObject === 'undefined' && typeof leakedArray === 'undefined' &&
        \\retained === 3 && typeof admitted === 'function'
    )).asBool());
}

