test "interpreter switch (match, fall-through, default, break)" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    try std.testing.expectEqual(@as(f64, 20), (try evalSource(a,
        \\let r = 0;
        \\switch (2) { case 1: r = 10; break; case 2: r = 20; break; default: r = 99; }
        \\r
    )).asNum());
    // default when no case matches
    try std.testing.expectEqual(@as(f64, 99), (try evalSource(a,
        \\let r = 0;
        \\switch (7) { case 1: r = 10; break; default: r = 99; }
        \\r
    )).asNum());
    // fall-through (no break) accumulates
    try std.testing.expectEqual(@as(f64, 3), (try evalSource(a,
        \\let r = 0;
        \\switch (1) { case 1: r = r + 1; case 2: r = r + 2; break; case 3: r = r + 99; }
        \\r
    )).asNum());
}

test "interpreter multiple declarators and void" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    try std.testing.expectEqual(@as(f64, 6), (try evalSource(a, "let x = 1, y = 2, z = 3; x + y + z")).asNum());
    try std.testing.expect((try evalSource(a, "void 5 === undefined")).asBool());
}

test "interpreter break / continue" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // break stops at 5
    try std.testing.expectEqual(@as(f64, 5), (try evalSource(a,
        \\let n = 0;
        \\for (let i = 0; i < 100; i++) { if (i === 5) { break; } n = i; }
        \\n + 1
    )).asNum());
    // continue skips even numbers -> sum of odds 1..9 = 25
    try std.testing.expectEqual(@as(f64, 25), (try evalSource(a,
        \\let sum = 0;
        \\for (let i = 0; i < 10; i++) { if (i % 2 === 0) { continue; } sum += i; }
        \\sum
    )).asNum());
}

test "interpreter caches immutable debug locations after one registry lookup" {
    var locations: std.AutoHashMapUnmanaged(*const Node, DebugStatementLocation) = .empty;
    defer locations.deinit(std.testing.allocator);
    var node: Node = undefined;
    const expected = DebugStatementLocation{
        .script_id = 17,
        .location = .{ .byte_offset = 23, .line = 4, .column = 9 },
        .source_url = "cached.js",
    };
    try locations.put(std.testing.allocator, &node, expected);

    var registry_lock = DebugRegistryLock{};
    var registry_stats = DebugRegistryStats{};
    var machine = Interpreter{
        .arena = std.testing.allocator,
        .env = undefined,
        .root_shape = undefined,
        .debug_statement_locations = &locations,
        .debug_registry_lock = &registry_lock,
        .debug_registry_stats = &registry_stats,
    };
    const first = machine.debugStatementLocation(&node).?;
    const second = machine.debugStatementLocation(&node).?;
    try std.testing.expectEqual(expected.script_id, first.script_id);
    try std.testing.expectEqual(expected.location, second.location);
    try std.testing.expectEqualStrings(expected.source_url, second.source_url);
    try std.testing.expectEqual(@as(usize, 1), machine.debug_location_cache_misses);
    try std.testing.expectEqual(@as(usize, 1), machine.debug_location_cache_hits);
    const stats = registry_stats.snapshot();
    try std.testing.expectEqual(@as(u64, 1), stats.location_cache_misses);
    try std.testing.expectEqual(@as(u64, 1), stats.location_cache_hits);
    try std.testing.expectEqual(@as(u64, 1), stats.lock_acquires);
    try std.testing.expectEqual(@as(u64, 0), stats.lock_contentions);
    try std.testing.expectEqual(@as(u64, 0), stats.lock_spins);
}

